def make_ssl_context():
    """Oyunun bütün HTTPS isteklerinde kullandığı güvenlik bağlamı."""
    if ssl is None:
        return None
    ctx = ssl.create_default_context()          # Windows'un kendi kökleri
    try:
        ctx.verify_flags &= ~ssl.VERIFY_X509_STRICT
    except Exception:
        pass
    try:
        ctx.load_verify_locations(cadata=_SERVER_ROOTS_PEM)
    except Exception:
        pass
    return ctx


def install_https():
    """Urllib.request.urlopen'a (bağlam verilmeyen her çağrıya) bu bağlamı taktırır."""
    try:
        urllib.request.install_opener(urllib.request.build_opener(
            urllib.request.HTTPSHandler(context=make_ssl_context())))
        return True
    except Exception:
        return False


HTTPS_READY = install_https()

# ---- web / mobil katmanı ----
# Oyun tarayıcıda (pygbag / WebAssembly) da çalışır; iPhone'da Safari'den "Ana
# Ekrana Ekle" ile uygulama gibi açılır:
# * iş parçacığı (thread) yok -> arka plan işleri asyncio görevidir
# * urllib yok -> istekler JavaScript fetch ile gider
# * dosyalar sayfa kapanınca silinir -> kayıtlar localStorage'a yazılır
MOBILE = IS_WEB          # dokunmatik arayüz ve mobil performans profili (aşağıda kesinleşir)
PLATFORM_TAG = "pc"      # dünya sıralaması ayrımı: "pc" | "mobile"

_WEB_JS = r"""
(function(){
  if (window.evo && window.evo.ready) return;
  var evo = window.evo = window.evo || {};
  evo.ready = true;
  evo.seq = 0; evo.out = {};
  evo.req = function(url, method, body, tmo){
    var id = ++evo.seq;
    var ctl = (typeof AbortController !== 'undefined') ? new AbortController() : null;
    var done = false;
    var timer = setTimeout(function(){ if (done) return; done = true;
        try { if (ctl) ctl.abort(); } catch(e) {}
        evo.out[id] = JSON.stringify({s:0, e:'timeout'}); }, tmo);
    var opt = {method: method, headers: {'Accept': 'application/json'},
               cache: 'no-store', credentials: 'omit', redirect: 'follow'};
    if (ctl) opt.signal = ctl.signal;
    if (body) { opt.body = body; opt.headers['Content-Type'] = 'application/json'; }
    fetch(url, opt).then(function(r){
      return r.text().then(function(t){ if (done) return; done = true; clearTimeout(timer);
        evo.out[id] = JSON.stringify({s: r.status, t: t}); });
    }).catch(function(e){ if (done) return; done = true; clearTimeout(timer);
      evo.out[id] = JSON.stringify({s: 0, e: 'net'}); });
    return id;
  };
  evo.take = function(id){ var v = evo.out[id]; if (v === undefined) return '';
    delete evo.out[id]; return v; };
  evo.lsGet = function(k){ try { var v = localStorage.getItem(k); return v === null ? '' : v; }
    catch(e) { return ''; } };
  evo.lsSet = function(k, v){ try { localStorage.setItem(k, v); return 1; } catch(e) { return 0; } };
  evo.lsDel = function(k){ try { localStorage.removeItem(k); } catch(e) {} };
  evo.lsKeys = function(p){ var a = []; try { for (var i = 0; i < localStorage.length; i++) {
      var k = localStorage.key(i); if (k && k.indexOf(p) === 0) a.push(k); } } catch(e) {}
    return JSON.stringify(a); };
  // ---- dokunuşa bağlı işler: klavye, bağlantı (iOS bunları yalnızca
  //      bir dokunuşun İÇİNDE yapmaya izin verir) ----
  evo.zones = [];
  evo.setZones = function(js){ try { evo.zones = JSON.parse(js) || []; } catch(e) { evo.zones = []; } };
  evo.kb = {seq: 0, key: '', val: '', enter: 0, open: 0};
  function evoInput(){
    var inp = document.getElementById('evo_text');
    if (!inp) {
      inp = document.createElement('input');
      inp.id = 'evo_text'; inp.type = 'text';
      inp.setAttribute('autocomplete', 'off'); inp.setAttribute('autocorrect', 'off');
      inp.setAttribute('autocapitalize', 'off'); inp.setAttribute('spellcheck', 'false');
      inp.style.cssText = 'position:fixed;left:0;top:0;width:1px;height:1px;opacity:0.01;font-size:16px;border:0;padding:0;background:transparent;color:transparent;';
      document.body.appendChild(inp);
    }
    if (!inp.evoReady) {
      inp.evoReady = true;
      inp.addEventListener('input', function(){ evo.kb.val = inp.value; evo.kb.seq++; });
      var stop = function(e){ e.stopPropagation();
        if (e.type === 'keydown' && (e.key === 'Enter' || e.keyCode === 13)) {
          e.preventDefault(); evo.kb.enter++; evo.kb.seq++; } };
      inp.addEventListener('keydown', stop); inp.addEventListener('keyup', stop);
      inp.addEventListener('keypress', stop);
      inp.addEventListener('blur', function(){ evo.kb.open = 0; evo.kb.key = ''; evo.kb.seq++;
        try { window.scrollTo(0, 0); } catch(e) {} });
    }
    return inp;
  }
  function evoCanvasXY(cx, cy){
    var c = document.getElementById('canvas'); if (!c) return null;
    var r = c.getBoundingClientRect(); if (!r.width || !r.height) return null;
    // tuval koordinatı -> oyunun "güvenli alan" koordinatı (çentik payı düşülür)
    return [(cx - r.left) * (c.width || 1280) / r.width - evo.safeX, (cy - r.top) * (c.height || 720) / r.height];
  }
  function evoHit(x, y){
    for (var i = 0; i < evo.zones.length; i++) { var z = evo.zones[i];
      if (x >= z.x && x <= z.x + z.w && y >= z.y && y <= z.y + z.h) return z; }
    return null;
  }
  function evoFocus(inp, z){
    inp.type = z.pw ? 'password' : 'text';
    inp.setAttribute('inputmode', z.num ? 'numeric' : 'text');
    inp.value = z.v || ''; evo.kb.key = z.id; evo.kb.val = inp.value; evo.kb.open = 1; evo.kb.seq++;
    try { inp.focus({preventScroll: true}); } catch(e) { inp.focus(); }
    try { inp.setSelectionRange(inp.value.length, inp.value.length); } catch(e) {}
  }
  function evoUp(e){
    var t = (e.changedTouches && e.changedTouches.length) ? e.changedTouches[0] : e;
    if (!t || t.clientX === undefined) return;
    var p = evoCanvasXY(t.clientX, t.clientY); if (!p) return;
    var z = evoHit(p[0], p[1]); var inp = evoInput();
    if (z && z.k === 'text') { evoFocus(inp, z); return; }
    if (z && z.k === 'url') { evo.openUrl(z.v); return; }
    if (z && z.k === 'ad') { evo.adStart(z.v); return; }    // reklam: dokunuş anında sesli başlar
    if (z && z.k === 'unmute') { evo.adUnmute(); return; }
    if (evo.kb.open) { inp.blur(); }
  }
  window.addEventListener('touchend', evoUp, {capture: true, passive: true});
  evo.kbPoll = function(last){ if (evo.kb.seq === last) return '';
    return JSON.stringify({seq: evo.kb.seq, key: evo.kb.key, val: evo.kb.val,
                           enter: evo.kb.enter, open: evo.kb.open}); };
  evo.kbSet = function(v){ var inp = evoInput(); inp.value = v; evo.kb.val = v; };
  evo.kbRetarget = function(id, v, pw, num){ var inp = evoInput();
    inp.type = pw ? 'password' : 'text'; inp.setAttribute('inputmode', num ? 'numeric' : 'text');
    inp.value = v; evo.kb.key = id; evo.kb.val = v; };
  evo.kbClose = function(){ var inp = document.getElementById('evo_text'); if (inp) inp.blur();
    evo.kb.open = 0; evo.kb.key = ''; };
  evo.openUrl = function(u){ try { var w = window.open(u, '_blank');
      if (!w) return 0; try { w.opener = null; } catch(e) {} return 1; } catch(e) { return 0; } };
  // ---- reklam filmi (HTML video, tuvalin üstünde) ----
  evo.ad = null;
  function evoAdPlace(){
    var v = evo.ad; if (!v) return;
    var c = document.getElementById('canvas'); if (!c) return;
    var r = c.getBoundingClientRect(); var k = r.width / (c.width || 1280);
    var R = v.evoRect || [160, 50, 960, 540];
    v.style.left = (r.left + (R[0] + evo.safeX) * k) + 'px'; v.style.top = (r.top + R[1] * k) + 'px';
    v.style.width = (R[2] * k) + 'px'; v.style.height = (R[3] * k) + 'px';
  }
  evo.adStart = function(url){
    try {
      if (evo.ad && evo.ad.evoUrl === url && !evo.ad.ended) { evoAdPlace(); return 1; }
      evo.adStop();
      var v = document.createElement('video');
      v.evoUrl = url; v.src = url; v.preload = 'auto';
      v.setAttribute('playsinline', ''); v.setAttribute('webkit-playsinline', '');
      v.style.cssText = 'position:fixed;z-index:20;background:#000;border-radius:10px;object-fit:contain;pointer-events:none;';
      document.body.appendChild(v); evo.ad = v; evoAdPlace();
      var p = v.play();
      if (p && p.catch) p.catch(function(){ v.muted = true; v.play().catch(function(){}); });
      return 1;
    } catch(e) { return 0; }
  };
  evo.adSetRect = function(x, y, w, h){ if (evo.ad) { evo.ad.evoRect = [x, y, w, h]; evoAdPlace(); } };
  evo.adTime = function(){ var v = evo.ad; if (!v) return -1;
    if (v.error && v.style.display !== 'none') v.style.display = 'none';
    return JSON.stringify({t: v.currentTime || 0, d: v.duration || 0, e: v.ended ? 1 : 0, m: v.muted ? 1 : 0,
                           err: v.error ? 1 : 0}); };
  evo.adStop = function(){ var v = evo.ad; evo.ad = null;
    if (v) { try { v.pause(); v.removeAttribute('src'); v.load(); } catch(e) {} if (v.parentNode) v.parentNode.removeChild(v); } };
  evo.adUnmute = function(){ if (evo.ad) { evo.ad.muted = false; evo.ad.play().catch(function(){}); } };
  window.addEventListener('resize', function(){ setTimeout(evoAdPlace, 60); });
  evo.hidden = 0;
  document.addEventListener('visibilitychange', function(){ if (document.hidden) evo.hidden++; });
  window.addEventListener('pagehide', function(){ evo.hidden++; });
  evo.hiddenCount = function(){ return evo.hidden; };
  evo.safeX = 0;
  evo.layout = function(){
    var p = document.getElementById('evo_safe'), cs = p ? getComputedStyle(p) : null;
    function v(k){ return cs ? (parseFloat(cs[k]) || 0) : 0; }
    return JSON.stringify({w: window.innerWidth || 0, h: window.innerHeight || 0,
      l: v('paddingLeft'), r: v('paddingRight'), t: v('paddingTop'), b: v('paddingBottom'),
      sw: (screen && screen.width) || 0, sh: (screen && screen.height) || 0});
  };
  evo.setSafe = function(sx){ evo.safeX = sx || 0; try { if (window.evoFit) window.evoFit(); } catch(e) {} };
  evo.isTouch = function(){ try { if (window.evoForceTouch) return 1; return (('ontouchstart' in window) ||
      (navigator.maxTouchPoints || 0) > 0) ? 1 : 0; } catch(e) { return 0; } };
  evo.origin = function(){ try { return String(location.origin || ''); } catch(e) { return ''; } };
  evo.param = function(n){ try { return new URLSearchParams(location.search).get(n) || ''; }
    catch(e) { return ''; } };
})();
"""

_WEB = None          # platform.window.evo (yalnız tarayıcıda)


def _web_init():
    global _WEB
    if not IS_WEB or _WEB is not None:
        return _WEB
    try:
        import platform as _pf
        _pf.window.eval(_WEB_JS)
        _WEB = _pf.window.evo
    except Exception as e:
        print("web köprüsü kurulamadı:", e)
        _WEB = None
    return _WEB


def web_call(name, *args, default=None):
    """Window.evo.<name>(...) çağırır; köprü yoksa `default` döner."""
    w = _web_init()
    if w is None:
        return default
    try:
        return getattr(w, name)(*args)
    except Exception:
        return default


# ---- kalıcı kayıt: localStorage ----
# Tarayıcıdaki dosya sistemi (memfs) sayfa kapanınca silinir. Kayıt dosyaları
# her yazıldığında localStorage'a da kopyalanır, açılışta geri yazılır.
_WEB_FS_PREFIX = "evofs:"


def web_persist(path):
    """Az önce yazılan dosyayı localStorage'a kopyalar (yalnız web)."""
    if not IS_WEB:
        return
    try:
        with open(path, "rb") as f:
            raw = f.read()
        txt = base64.b64encode(raw).decode("ascii")
        web_call("lsSet", _WEB_FS_PREFIX + os.path.abspath(path), txt)
    except Exception as e:
        print("web_persist", path, e)


def web_forget(path):
    if IS_WEB:
        web_call("lsDel", _WEB_FS_PREFIX + os.path.abspath(path))


def web_restore_files():
    """Açılışta localStorage'daki kayıtları dosya sistemine geri yazar."""
    if not IS_WEB:
        return 0
    n = 0
    try:
        keys = json.loads(web_call("lsKeys", _WEB_FS_PREFIX, default="[]") or "[]")
    except Exception:
        keys = []
    for k in keys:
        path = str(k)[len(_WEB_FS_PREFIX):]
        # Yalnızca mutlak ve ".." içermeyen yollar (bozuk/kötü niyetli
        # anahtarlar oyunun kendi dosyalarının üstüne yazamasın).
        if not path.startswith("/") or ".." in path.split("/"):
            continue
        try:
            raw = base64.b64decode(web_call("lsGet", k, default="") or "")
            if not raw:
                continue
            d = os.path.dirname(path)
            if d:
                os.makedirs(d, exist_ok=True)
            with open(path, "wb") as f:
                f.write(raw)
            n += 1
        except Exception as e:
            print("web_restore", path, e)
    return n


# ---- arka plan işleri ----
def gc_settle():
    """Çöp toplayıcıyı oyuna uygun hale getirir (yalnız web/telefon)."""
    if not (IS_WEB or MOBILE):
        return
    try:
        import gc
        gc.collect()
        gc.freeze()
        gc.set_threshold(4000, 30, 400)
    except Exception:
        pass


def spawn(fn, *args):
    """fn'i arka planda çalıştırır; oyun beklemez."""
    if asyncio.iscoroutinefunction(fn):
        if IS_WEB:
            async def _guard():
                try:
                    await fn(*args)
                except Exception as e:
                    print("arka plan işi hata:", repr(e))
            try:
                loop = asyncio.get_event_loop()
                t = loop.create_task(_guard())
                _BG_TASKS.add(t)
                t.add_done_callback(_BG_TASKS.discard)
            except Exception as e:
                print("spawn", e)
            return
        threading.Thread(target=lambda: asyncio.run(fn(*args)), daemon=True).start()
        return
    if IS_WEB:
        fn(*args)
        return
    threading.Thread(target=fn, args=args, daemon=True).start()


_BG_TASKS = set()          # web: görevler çöpe gitmesin diye tutulur


def open_url(url):
    """Bağlantıyı tarayıcıda açar."""
    url = str(url or "")
    if not (url.startswith("https://") or url.startswith("http://")):
        return False
    if IS_WEB:
        # iPhone'da yeni sekme yalnız bir dokunuşun içinde açılabilir; bu
        # yüzden düğmeler dokunuşa bağlı açar.
        if url in _LINK_URLS_PREV or url in _LINK_URLS:
            return True
        return bool(web_call("openUrl", url, default=0))
    try:
        if webbrowser is not None:
            webbrowser.open(url)
            return True
    except Exception:
        pass
    return False


def clip_get():
    """Panodaki metin (Ctrl+V). Okunamazsa boş döner."""
    txt = ""
    try:
        if not pygame.scrap.get_init():
            pygame.scrap.init()
        try:
            txt = pygame.scrap.get_text() or ""
        except Exception:
            txt = ""
        if not txt:
            raw = (pygame.scrap.get("text/plain;charset=utf-8")
                   or pygame.scrap.get(pygame.SCRAP_TEXT))
            if raw:
                txt = raw.decode("utf-8", "ignore") if isinstance(raw, (bytes, bytearray)) else str(raw)
    except Exception:
        txt = ""
    return str(txt).replace("\x00", "").replace("\r\n", "\n").replace("\r", "\n")


def clip_set(txt):
    """Metni panoya koyar (Ctrl+C)."""
    txt = str(txt or "")
    try:
        if not pygame.scrap.get_init():
            pygame.scrap.init()
        try:
            pygame.scrap.put_text(txt)
        except Exception:
            pygame.scrap.put(pygame.SCRAP_TEXT, txt.encode("utf-8"))
        return True
    except Exception:
        return False


def _ctrl_down():
    try:
        return bool(pygame.key.get_mods() & (pygame.KMOD_CTRL | pygame.KMOD_META))
    except Exception:
        return False


# ---- metin kutusu imleci ----
# Yazı kutularında imleç artık hep sonda değil: fareyle bir harfin yanına
# tıklanınca imleç oraya gider; sol/sağ, Home/End, Delete çalışır, yazılan harf
# imlecin olduğu yere girer. Kutunun kimliği (ör. "login:user") imleci ve
# görünen pencereyi (uzun yazıda kaydırma) tutar.
_CARETS = {}         # kutu -> imleç (harf sırası); yoksa yazının sonu
_CARET_VIEW = {}     # kutu -> görünen ilk harf


def caret_get(fid, text):
    c = _CARETS.get(fid)
    n = len(text or "")
    return n if c is None else max(0, min(n, c))


def caret_set(fid, i=None):
    """i=None: imleç yazının sonuna (yazı dışarıdan değişti)."""
    if i is None:
        _CARETS.pop(fid, None)
    else:
        _CARETS[fid] = max(0, int(i))


def _word_left(text, i):
    while i > 0 and text[i - 1] == " ":
        i -= 1
    while i > 0 and text[i - 1] != " ":
        i -= 1
    return i


def _word_right(text, i):
    n = len(text)
    while i < n and text[i] == " ":
        i += 1
    while i < n and text[i] != " ":
        i += 1
    return i


def text_edit(fid, text, event, accept=None, limit=10 ** 6):
    """İmleçli düzenleme. Dönüş: (yeni yazı, tuş işlendi mi).
    accept(harf) False dönerse harf girmez. Enter/Tab/Esc çağıran tarafta."""
    text = text or ""
    i = caret_get(fid, text)
    k = getattr(event, "key", None)
    ctrl = _ctrl_down()
    if k == pygame.K_LEFT:
        caret_set(fid, _word_left(text, i) if ctrl else i - 1)
        return text, True
    if k == pygame.K_RIGHT:
        caret_set(fid, min(len(text), _word_right(text, i) if ctrl else i + 1))
        return text, True
    if k == pygame.K_HOME:
        caret_set(fid, 0)
        return text, True
    if k == pygame.K_END:
        caret_set(fid, len(text))
        return text, True
    if k == pygame.K_BACKSPACE:
        if i > 0:
            j = _word_left(text, i) if ctrl else i - 1
            text = text[:j] + text[i:]
            caret_set(fid, j)
        return text, True
    if k == pygame.K_DELETE:
        if i < len(text):
            j = _word_right(text, i) if ctrl else i + 1
            text = text[:i] + text[j:]
            caret_set(fid, i)
        return text, True
    if ctrl and k == pygame.K_v:
        chars = clip_get().replace("\r", "").replace("\n", " ")
    elif ctrl:
        return text, False
    else:
        chars = getattr(event, "unicode", "") or ""
    took = False
    for ch in chars:
        if not ch.isprintable() or len(text) >= limit:
            continue
        if accept is not None and not accept(ch):
            continue
        text = text[:i] + ch + text[i:]
        i += 1
        took = True
    if took:
        caret_set(fid, i)
    return text, took or bool(chars)


def text_view(fid, shown, size, avail, bold=False):
    """Uzun yazının kutuya sığan parçası, imleç görünür kalacak şekilde.
    Dönüş: (ilk harf, görünen yazı, imlecin x payı)."""
    i = caret_get(fid, shown)
    st = min(_CARET_VIEW.get(fid, 0), len(shown))
    if i < st:
        st = i
    while st < i and text_width(shown[st:i], size, bold) > avail:
        st += 1
    # sonda boşluk kaldıysa geri kaydır (yazının sonu kutunun sağına yaslansın)
    while st > 0 and text_width(shown[st - 1:], size, bold) <= avail:
        st -= 1
    _CARET_VIEW[fid] = st
    vis = shown[st:]
    while vis and text_width(vis, size, bold) > avail:
        vis = vis[:-1]
    return st, vis, text_width(shown[st:i], size, bold)


def text_click(fid, shown, size, x0, mx, bold=False):
    """Kutuya tıklanınca imleci tıklanan harfin yanına koyar."""
    if MOBILE:
        caret_set(fid)       # telefon klavyesi yazının sonundan düzenler
        return
    st = min(_CARET_VIEW.get(fid, 0), len(shown))
    best, best_d = st, abs(mx - x0)
    for j in range(st + 1, len(shown) + 1):
        d = abs(mx - (x0 + text_width(shown[st:j], size, bold)))
        if d < best_d:
            best, best_d = j, d
        elif d > best_d:
            break
    caret_set(fid, best)


async def http_call(url, data=None, timeout=20, method=None):
    """HTTP isteği; cevap gövdesini (bytes) döner."""
    if not IS_WEB:
        headers = {"Accept": "application/json"}
        if data is not None:
            headers["Content-Type"] = "application/json"
        req = urllib.request.Request(url, data=data, headers=headers,
                                     method=method or ("POST" if data is not None else "GET"))
        with urllib.request.urlopen(req, timeout=timeout) as r:
            return r.read()
    body = data.decode("utf-8") if isinstance(data, (bytes, bytearray)) else (data or "")
    rid = web_call("req", str(url), method or ("POST" if data is not None else "GET"),
                   body, int(timeout * 1000))
    if rid is None:
        raise urllib.error.URLError("web köprüsü yok")
    while True:
        out = web_call("take", rid, default="")
        if out:
            break
        await asyncio.sleep(0.03)
    res = json.loads(str(out))
    st = int(res.get("s") or 0)
    if st == 0:
        if res.get("e") == "timeout":
            raise urllib.error.URLError(TimeoutError("timed out"))
        raise urllib.error.URLError(ConnectionError("network"))
    raw = str(res.get("t") or "").encode("utf-8")
    if st >= 400:
        raise urllib.error.HTTPError(url, st, "HTTP %d" % st, {}, io.BytesIO(raw))
    return raw


async def http_json(url, payload=None, timeout=20):
    data = None if payload is None else json.dumps(payload).encode("utf-8")
    raw = await http_call(url, data, timeout=timeout)
    return json.loads(raw.decode("utf-8") or "{}")


