NEW_YEAR_FORCE = True             # Noel menüsü kalıcı (oyuncular sevdi)


def _new_year_active():
    if NEW_YEAR_FORCE is not None:
        return bool(NEW_YEAR_FORCE)
    try:
        lt = time.localtime()
        md = (lt.tm_mon, lt.tm_mday)
        return md >= (10, 7) or md <= (1, 7)
    except Exception:
        return True


