def gem_pack_total(pack):
    """Paketin bonus dahil toplam elmas miktarı."""
    return int(pack["gems"] * (1 + pack["bonus"] / 100.0))


# Satın alma sunucusu: hesap ve skor sunucusunun aynısı.
PURCHASE_API_URL = ONLINE_API_URL

# Geliştirici test kipi. açıksa hiçbir ödeme alınmaz, ürün yalnızca yerel
# olarak eklenir ve ekranda büyük harflerle "TEST" yazar.
FAKE_PURCHASE = os.environ.get("KASMA_FAKE_PURCHASE") == "1"

# Ödeme beklenirken sipariş durumu bu aralıkla sorulur (sn) ve en çok bu kadar
# beklenir.
PURCHASE_POLL_EVERY = 4.0
PURCHASE_POLL_MAX = 20 * 60.0


def fmt_tl(kurus):
    """15900 -> '₺159', 2990 -> '₺29,90'."""
    k = int(kurus)
    # Web yazı tipinde (Liberation Sans) ₺ işareti yok: "159 TL" yazılır.
    if IS_WEB:
        return "%d TL" % (k // 100) if k % 100 == 0 else "%d,%02d TL" % (k // 100, k % 100)
    return "₺%d" % (k // 100) if k % 100 == 0 else "₺%d,%02d" % (k // 100, k % 100)


class PurchaseBridge:
    """Gerçek para (TL) ile satın alma (Steam yerine web ödemesi)."""

    def __init__(self, steam, account=None, api_url=PURCHASE_API_URL):
        self.steam = steam                 # eski arayüz uyumu için duruyor
        self.account = account
        self.api_url = (api_url or "").rstrip("/")
        self.status = None        # ekranda gösterilen son durum metni
        self.busy = False
        self.last_error = None
        self.enabled = None       # None = sunucuya henüz sorulmadı
        self.provider = ""
        self.catalog = {}         # "3100" -> {"price": 15900, "price_text": "₺159", ...}
        self.order = None         # bekleyen sipariş
        self._catalog_at = 0.0
        self._catalog_busy = False
        self.fail_n = 0           # art arda başarısız katalog sorgusu
        self.refresh_catalog()

    # ---- katalog ----
    def refresh_catalog(self, force=False):
        """Fiyatları ve mağazanın açık olup olmadığını arka planda sorar."""
        if not self.api_url or (not force and time.time() - self._catalog_at < 60):
            return
        self._catalog_at = time.time()

        if self._catalog_busy:
            return

        async def work():
            self._catalog_busy = True
            try:
                data = await http_json(self.api_url + "/shop/catalog", None, 40)
                self.catalog = dict(data.get("products") or {})
                self.provider = str(data.get("provider") or "")
                self.enabled = bool(data.get("enabled"))
                self.fail_n = 0
            except Exception:
                # ulaşılamamak "KAPALI" demek değil. Durum bilinmiyorsa
                # "bağlanılıyor" kalır ve birkaç saniyede bir yeniden denenir.
                self.fail_n += 1
                self._catalog_at = time.time() - 55     # ~5 sn sonra yeniden dene
            finally:
                self._catalog_busy = False
        spawn(work)

    def price_text(self, item_id, fallback=""):
        """Ürünün sunucudaki fiyatı (yoksa koddaki tahmin)."""
        p = self.catalog.get(str(item_id))
        if p and p.get("price"):
            return fmt_tl(p["price"])
        return fallback

    # ---- durum ----
    def logged_in(self):
        return bool(self.account and self.account.logged_in())

    def available(self):
        """Satın alma şu an gerçekten yapılabilir mi?"""
        if FAKE_PURCHASE:
            return True
        return bool(self.api_url) and self.enabled is True and self.logged_in()

    def unavailable_reason(self):
        if not self.api_url:
            return L("ui.shop_no_server")
        if self.enabled is None:
            return L("ui.st_wake") if self.fail_n else L("ui.shop_connecting")
        if not self.enabled:
            return L("ui.shop_closed")
        if not self.logged_in():
            return L("ui.shop_login")
        return ""

    def waiting(self):
        """Tarayıcıda ödeme bekleniyor mu?"""
        return self.order is not None

    def steam_id(self):
        return None

    # ---- satın alma ----
    def begin_purchase(self, pack, on_done=None, design=None):
        """Satın almayı başlatır."""
        if self.busy or self.order is not None:
            return False
        if FAKE_PURCHASE:
            # test kipi - para akışı yok, yalnızca geliştirme içindir.
            self.status = "TEST KİPİ: ödeme alınmadı"
            if on_done:
                on_done(True, "TEST: satın alma yerel olarak tamamlandı")
            return True
        if not self.available():
            self.last_error = self.unavailable_reason()
            if on_done:
                on_done(False, self.last_error)
            return False
        self.busy = True
        self.status = L("ui.shop_preparing")
        extra = {"product_id": str(pack["id"])}
        if design is not None:
            extra["design"] = design

        def opened(ok, err, res):
            if not ok:
                self.busy = False
                self.status = err or L("ui.op_fail")
                if on_done:
                    on_done(False, self.status)
                return
            self.order = {"id": res.get("order_id"), "url": res.get("pay_url"),
                          "name": res.get("name", ""), "started": time.time(),
                          "on_done": on_done, "polls": 0}
            self.status = L("ui.shop_paying")
            self.open_page()
            spawn(self._poll, self.order)
        self.account.reward_call("/shop/checkout", extra, opened)
        return True

    def open_page(self):
        """Ödeme sayfasını (yeniden) tarayıcıda açar."""
        if self.order and self.order.get("url"):
            open_url(self.order["url"])

    def cancel_wait(self):
        """Oyuncu beklemekten vazgeçti."""
        if self.order is not None:
            self.order["cancelled"] = True
        self.order = None
        self.busy = False
        self.status = None

    def _finish(self, order, ok, msg):
        # Önce sonucu bildir (ekrandaki mesaj ve kuşanma hazır olsun), sonra
        # bekleme kutusunu kapat: arada boş bir kare görünmesin.
        cb = order.get("on_done")
        if cb:
            try:
                cb(ok, msg)
            except Exception:
                pass
        if self.order is order:
            self.order = None
        self.busy = False
        self.status = msg

    async def _poll(self, order):
        """Sipariş teslim edilene ya da düşene kadar sunucuya sorar."""
        while not order.get("cancelled"):
            await asyncio.sleep(PURCHASE_POLL_EVERY)
            if order.get("cancelled") or self.order is not order:
                return
            if time.time() - order["started"] > PURCHASE_POLL_MAX:
                self._finish(order, False, L("ui.shop_timeout"))
                return
            box = {}

            # box varsayılan argüman: geç gelen eski cevap yeni turun kutusuna yazmasın
            def got(ok, err, res, box=box):
                box["ok"], box["err"], box["res"] = ok, err, res
            self.account.reward_call("/shop/order_status", {"order_id": order["id"]}, got)
            t_end = time.time() + 20
            while "ok" not in box and time.time() < t_end:
                await asyncio.sleep(0.05)
            res = box.get("res") or {}
            st = res.get("status")
            if st == "granted":
                # reward_call sunucunun ilerlemesini çoktan uyguladı
                self._finish(order, True, L("ui.shop_done", order.get("name", "")))
                return
            if st in ("failed", "cancelled"):
                self._finish(order, False, L("ui.shop_failed"))
                return


# ücretsiz elmas: ödüllü reklam + günlük hediye:
# * reklam izle -> +250 elmas (günde en çok AD_DAILY_LIMIT kez, iki reklam
#   arasında AD_COOLDOWN saniye)
# * günlük hediye -> her gün bir kez; arka arkaya gelinen her gün biraz daha
#   büyür (7 günlük seri, sonra başa döner) (premium skin ve pet'ler yine
#   yalnızca gerçek parayla satılır.)
AD_PROVIDER = ""             # boş = ev reklamı
AD_REWARD_GEMS = 300           # 50 -> 250, 300 (2 dakikalık yeni tanıtım filmi)
AD_DAILY_LIMIT = 5
AD_COOLDOWN = 90.0           # iki reklam arası (sn)
AD_LENGTH = 120.0            # reklamın süresi - asıl değer GameTour.LENGTH
DAILY_GIFT_GEMS = (150, 250, 350, 450, 550, 650, 750)   # (sunucu: server.py da)

def _day_key(offset_days=0):
    return time.strftime("%Y-%m-%d", time.localtime(time.time() + offset_days * 86400))


def seconds_to_midnight():
    lt = time.localtime()
    return max(0, 86400 - (lt.tm_hour * 3600 + lt.tm_min * 60 + lt.tm_sec))


def fmt_clock(sec):
    sec = int(max(0, sec))
    h, m, s_ = sec // 3600, (sec % 3600) // 60, sec % 60
    return f"{h:d}:{m:02d}:{s_:02d}" if h else f"{m:d}:{s_:02d}"


def _is_paid_item(list_key, item):
    """Gerçek parayla satılan içerik mi?"""
    if list_key == "skins_owned":
        return bool(get_skin(item).get("premium")) and item in SKIN_BY_ID
    if list_key == "cosmetics_owned":
        return str(item).startswith("pet_")
    return False


class RewardCenter:
    """Reklam ödülü ve günlük hediye."""

    CLOCK_SLACK = 600.0          # saat bu kadar geri giderse "geri alınmış" sayılır

    def __init__(self, save, account=None):
        self.save = save
        self.account = account
        self.busy = False
        self.ticket = None
        self.ticket_pending = False

    # ---- kim, nerede ----
    def online_mode(self):
        acc = self.account
        try:
            return bool(acc is not None and getattr(acc, "enabled", False)
                        and acc.logged_in() and getattr(acc, "token", ""))
        except Exception:
            return False

    def _st(self):
        pid = self.save.profile_id()
        st = self.save.data.get("rewards")
        # "pid" yoksa bu, sayaçların bilgisayara ait olduğu ilk sürümden
        # kalmadır ve misafirken doldurulmuştur.
        if not isinstance(st, dict) or st.get("pid", "guest") != pid:
            st = {"pid": pid}
            self.save.data["rewards"] = st
        return st

    def clock_ok(self):
        """Misafirde saat geri alınmış mı?"""
        if self.online_mode():
            return True
        hw = float(self._st().get("hw", 0) or 0)
        return time.time() + self.CLOCK_SLACK >= hw

    def _touch_clock(self, st):
        st["hw"] = max(float(st.get("hw", 0) or 0), time.time())

    # ---- reklam ----
    def ads_used(self):
        st = self._st()
        day, today = str(st.get("ad_day") or ""), _day_key()
        if day == today:
            return int(st.get("ad_count", 0) or 0)
        if day > today:                 # kayıt "gelecekte": saat geri alınmış
            return AD_DAILY_LIMIT
        return 0

    def ads_left(self):
        return max(0, AD_DAILY_LIMIT - self.ads_used())

    def ad_cooldown(self):
        last = float(self._st().get("ad_last", 0) or 0)
        # Saat geri alınmışsa (last gelecekte) en çok bir bekleme süresi say.
        return clamp(last + AD_COOLDOWN - time.time(), 0.0, AD_COOLDOWN)

    def ad_ready(self):
        return (not self.busy and self.clock_ok() and self.ads_left() > 0
                and self.ad_cooldown() <= 0)

    def begin_ad(self):
        """Reklam başladı."""
        self.ticket = None
        if not self.online_mode():
            return
        self.ticket_pending = True

        def done(ok, err, res):
            self.ticket_pending = False
            if ok and res:
                self.ticket = res.get("ticket")
        self.account.reward_call("/rewards/ad_start", {}, done)

    def grant_ad(self, on_done):
        """Reklam sonuna kadar izlendi. on_done(verilen_elmas, hata_metni)."""
        if self.online_mode():
            if not self.ticket:
                on_done(0, L("ui.reward_no_ticket"))
                return
            self.busy = True

            def done(ok, err, res):
                self.busy = False
                on_done(int((res or {}).get("amount", 0) or 0) if ok else 0,
                        "" if ok else (err or L("ui.acc_neterr")))
            self.account.reward_call("/rewards/claim", {"kind": "ad", "ticket": self.ticket}, done)
            self.ticket = None
            return
        if not self.ad_ready():
            on_done(0, L("ui.reward_clock") if not self.clock_ok() else "")
            return
        st = self._st()
        day = _day_key()
        st["ad_count"] = (int(st.get("ad_count", 0) or 0) + 1) if st.get("ad_day") == day else 1
        st["ad_day"] = day
        st["ad_last"] = time.time()
        st["ad_total"] = int(st.get("ad_total", 0) or 0) + 1
        self._touch_clock(st)
        self.save.add_gems(AD_REWARD_GEMS)
        self.save.progress_changed()
        on_done(AD_REWARD_GEMS, "")

    # ---- günlük hediye ----
    def gift_ready(self):
        if self.busy or not self.clock_ok():
            return False
        return str(self._st().get("gift_day") or "") < _day_key()

    def gift_day_index(self):
        """Bugün alınacak hediyenin serideki sırası (0..6)."""
        st = self._st()
        streak = int(st.get("gift_streak", 0) or 0)
        if st.get("gift_day") == _day_key():
            return max(0, streak - 1) % len(DAILY_GIFT_GEMS)
        if st.get("gift_day") == _day_key(-1):
            return streak % len(DAILY_GIFT_GEMS)
        return 0

    def gift_amount(self):
        return DAILY_GIFT_GEMS[self.gift_day_index()]

    def claim_gift(self, on_done):
        """Günlük hediyeyi alır. on_done(verilen_elmas, hata_metni)."""
        if self.online_mode():
            self.busy = True

            def done(ok, err, res):
                self.busy = False
                on_done(int((res or {}).get("amount", 0) or 0) if ok else 0,
                        "" if ok else (err or L("ui.acc_neterr")))
            self.account.reward_call("/rewards/claim", {"kind": "gift"}, done)
            return
        if not self.gift_ready():
            on_done(0, L("ui.reward_clock") if not self.clock_ok() else "")
            return
        st = self._st()
        idx = self.gift_day_index()
        amount = DAILY_GIFT_GEMS[idx]
        st["gift_streak"] = idx + 1
        st["gift_day"] = _day_key()
        self._touch_clock(st)
        self.save.add_gems(amount)
        self.save.progress_changed()
        on_done(amount, "")

    # ---- kartopu savaşı ----
    def snow_used(self):
        st = self._st()
        day, today = str(st.get("snow_day") or ""), _day_key()
        if day == today:
            return int(st.get("snow_count", 0) or 0)
        if day > today and not self.online_mode():
            return SNOW_DAILY             # saat geri alınmış
        return 0

    def snow_left(self):
        return max(0, SNOW_DAILY - self.snow_used())

    def begin_snow(self, on_done):
        """Oyun başlıyor."""
        self.snow_ticket = None
        if not self.online_mode():
            if not self.clock_ok():
                on_done(False, L("ui.reward_clock"))
                return
            on_done(self.snow_left() > 0, "" if self.snow_left() > 0 else L("snow.no_plays"))
            return

        def done(ok, err, res):
            if ok and res and res.get("ticket"):
                self.snow_ticket = res.get("ticket")
                on_done(True, "")
            else:
                on_done(False, err or L("ui.acc_neterr"))
        self.account.reward_call("/rewards/snow_start", {}, done)

    def finish_snow(self, hits, on_done):
        """Oyun bitti: elmas. on_done(verilen_elmas, hata)."""
        hits = int(clamp(int(hits), 0, SNOW_MAX_GEMS))
        if self.online_mode():
            tk = getattr(self, "snow_ticket", None)
            self.snow_ticket = None
            if not tk:
                on_done(0, L("ui.reward_no_ticket"))
                return

            def done(ok, err, res):
                on_done(int((res or {}).get("amount", 0) or 0) if ok else 0,
                        "" if ok else (err or L("ui.acc_neterr")))
            self.account.reward_call("/rewards/claim", {"kind": "snow", "ticket": tk, "hits": hits}, done)
            return
        if not self.clock_ok() or self.snow_left() <= 0:
            on_done(0, L("ui.reward_clock") if not self.clock_ok() else L("snow.no_plays"))
            return
        st = self._st()
        day = _day_key()
        st["snow_count"] = (int(st.get("snow_count", 0) or 0) + 1) if st.get("snow_day") == day else 1
        st["snow_day"] = day
        st["snow_best"] = max(int(st.get("snow_best", 0) or 0), hits)
        self._touch_clock(st)
        if hits > 0:
            self.save.add_gems(hits)
        self.save.progress_changed()
        on_done(hits, "")

    def anything_ready(self):
        return self.ad_ready() or self.gift_ready()


class AdBridge:
    """Ödüllü reklam köprüsü."""

    def __init__(self):
        self.provider = AD_PROVIDER

    def uses_house_ad(self):
        return not self.provider


