# ---- bağlantı hatasının sebebi ----
# Hata türüne ayrılıp ekranda yazıyor ve kayıt klasöründeki
# connection_log.txt'ye ayrıntısıyla düşüyor.
BOOT_PROBE_TIMEOUTS = (12, 30, 45)
BOOT_PROBE_PAUSE = 2.0
# Skor tablosu ve skor gönderimi de arka planda; uyanan sunucuya süre tanı.
WORLD_FETCH_TIMEOUT = 30
SUBMIT_TIMEOUT = 45
NET_LOG_MAX = 256 * 1024


def net_error_kind(e):
    """Bir ağ hatasını (tür, ayrıntı) çiftine çevirir."""
    if isinstance(e, urllib.error.HTTPError):
        return "http", str(e.code)
    r = e.reason if isinstance(e, urllib.error.URLError) else e
    if not isinstance(r, BaseException):
        r = e
    text = str(r)
    if (ssl is not None and isinstance(r, ssl.SSLError)) or "CERTIFICATE_VERIFY" in text.upper():
        return "ssl", str(getattr(r, "verify_message", "") or getattr(r, "reason", "") or text)[:120]
    if isinstance(r, TimeoutError) or "timed out" in text.lower():
        return "timeout", ""
    if socket is not None and isinstance(r, socket.gaierror):
        return "dns", ""
    if isinstance(r, (ConnectionRefusedError, ConnectionResetError,
                      ConnectionAbortedError, PermissionError)):
        return "blocked", type(r).__name__
    return "net", (type(r).__name__ + ": " + text)[:120]


def net_reason_text(kind, detail=""):
    """Hata türünün oyuncuya gösterilecek (yerelleştirilmiş) açıklaması."""
    if kind == "http":
        return L("ui.net_http", detail)
    if kind in ("ssl", "timeout", "dns", "blocked", "setup"):
        return L("ui.net_" + kind)
    return L("ui.net_other", detail or "?")


def log_net_error(where, e, kind=None):
    """Connection_log.txt'ye bir satır yazar (kayıt klasöründe)."""
    try:
        path = os.path.join(get_save_dir(), "connection_log.txt")
        if os.path.exists(path) and os.path.getsize(path) > NET_LOG_MAX:
            os.replace(path, path + ".old")
        k = kind or net_error_kind(e)
        with open(path, "a", encoding="utf-8") as f:
            f.write("%s  v%s  py%s%s  %s  %s/%s  %s\n" % (
                time.strftime("%Y-%m-%d %H:%M:%S"), GAME_VERSION,
                sys.version.split()[0], " exe" if getattr(sys, "frozen", False) else "",
                where, k[0], k[1], repr(e)[:300]))
    except Exception:
        pass


class AccountClient:
    """Hesap işlemleri."""

    def __init__(self, base_url, save):
        self.base_url = (base_url or "").rstrip("/")
        self.save = save
        # ayrım:
        #   enabled: sunucu adresi var mı (kurulum) -> çip hep durur
        #   server_ok: sunucu cevap verdi mi (None = henüz bilinmiyor)
        #   booting: açılış yoklaması sürüyor mu
        self.enabled = bool(self.base_url)
        self.server_ok = None if self.base_url else False
        self.booting = bool(self.base_url)
        # açılış yoklaması kaçıncı denemede (0 = ilk) ve son bağlantı hatasının
        # sebebi (tür, ayrıntı) - ekranda yazar.
        self.boot_try = 0
        self.net_error = ("", "")
        self.account = None          # {"name","email","provider","gems"}
        # Jeton kayıtta makineye bağlı sarılı durur; başka bilgisayarda
        # açılmaz. Sunucu ayrıca oturumu cihaz kimliğine bağlar.
        self.token = open_token(save.data.get("account_token") or "")
        self.busy = False
        self.status = ""             # ekranda görünen son durum metni
        self.ok_msg = ""
        self.google_ready = False
        self.client_id = ""
        # google beklemesi. Pencereyi kapandı diye doğrudan göremiyoruz ama
        # şunu görebiliyoruz: oyun penceresi yeniden öne geldi.
        self.google_wait = False       # tarayıcı cevabı bekleniyor mu
        self.google_cancel = False     # oyuncu vazgeç'e bastı
        self.google_back_at = 0.0      # oyun penceresi öne geldiği an
        # ---- ilerleme eşitlemesi ----
        self.sync_error = ""        # son yazma hatası (hesap ekranında görünür)
        self.sync_at = 0.0          # son başarılı yazmanın zamanı
        self.sync_busy = False
        self._sync_pending = False
        # Kalıcı bir şey değiştiğinde (elmas, skin, pet) sunucuya yaz.
        SaveManager.on_progress_change = self._progress_changed
        # kalıcı yasak konduğu anda sunucuya da bildir.
        SaveManager.on_ban = self.report_ban
        self._lock = threading.Lock()
        if self.enabled:
            spawn(self._boot)

    # ---- düşük seviye ----
    async def _post(self, path, payload, timeout=20):
        return await http_json(self.base_url + path, payload, timeout)

    def _err_text(self, e):
        """Sunucunun hata gövdesini okunur bir cümleye çevirir."""
        try:
            if isinstance(e, urllib.error.HTTPError):
                body = json.loads(e.read().decode("utf-8"))
                return str(body.get("error") or body.get("message") or e.reason)
        except Exception:
            pass
        return L("ui.acc_neterr")

    async def _boot(self):
        """Açılışta: sunucu hangi giriş yollarını açmış, oturumum geçerli mi?"""
        st = await self._status_probe()
        if st is None:
            self.server_ok = False
            self.booting = False
            return
        # Web'de Google girişi kapalı: yerel geri dönüş sunucusu (127.0.0.1)
        # tarayıcıda kurulamaz. Kullanıcı adı + şifre çalışır.
        self.google_ready = bool(st.get("google")) and not IS_WEB
        self.client_id = st.get("client_id", "")
        self.server_ok = bool(st.get("accounts"))
        if not self.server_ok:
            # Sunucu ayakta ama hesap sistemi kapalı: Render'da SUPABASE_URL /
            # SUPABASE_KEY girilmemiş.
            self.net_error = ("setup", "")
            log_net_error("auth/status", RuntimeError("accounts=false"), ("setup", ""))
            self.booting = False
            return
        # Açılışta saklanan oturum hâlâ geçerli mi? Bu iş arka planda dönüyor
        # ve sunucu yavaşsa saniyeler sürebilir.
        tok = self.token
        if not tok:
            self.booting = False
            return
        try:
            res = await self._post("/auth/me", {"token": tok, "device": device_id(),
                                          "device_legacy": device_id_legacy()})
        except Exception:
            self.booting = False
            return          # ağ yoksa jetonu silme: sonra yeniden denenir
        finally:
            self.booting = False
        if self.token != tok:
            # Biz sorarken oyuncu giriş yaptı/çıktı. Elimizdeki cevap eski
            # jetona ait; yeni oturumu onun yüzünden silmeyelim.
            return
        if res.get("success"):
            acc = res["account"]
            # açılışta hesabın sunucudaki durumu (ör. başka cihazda alınan
            # skin, sunucudaki yasak) hemen indirilir.
            pid = "acc:%s" % acc.get("id")
            if self.save.profile_id() != pid:
                self.save.switch_profile(pid)
            self.account = acc
            await self.pull_progress()
        else:
            self._forget()

    async def _status_probe(self):
        """/auth/status'u yoklar; cevap (dict) ya da None döner."""
        tries = BOOT_PROBE_TIMEOUTS
        for i, tmo in enumerate(tries):
            self.boot_try = i
            try:
                st = await http_json(self.base_url + "/auth/status", None, tmo)
                if not isinstance(st, dict):
                    raise ValueError("auth/status: beklenmeyen cevap")
                self.net_error = ("", "")
                return st
            except Exception as e:
                kind = net_error_kind(e)
                self.net_error = kind
                log_net_error("auth/status #%d" % (i + 1), e, kind)
                if kind[0] in ("ssl", "dns", "blocked") or kind == ("http", "404"):
                    break
                if i + 1 < len(tries):
                    await asyncio.sleep(BOOT_PROBE_PAUSE)
        return None

    def retry_connect(self):
        """Sunucu kapalıyken 'YENİDEN dene' düğmesi."""
        if self.booting or not self.base_url:
            return
        self.booting = True
        self.server_ok = None
        self.boot_try = 0
        self.status = ""
        spawn(self._boot)

    # ---- kayıt ----
    async def _remember(self, token, account):
        """Yeni oturumu/hesabı hatırlar ve yerel profili o hesaba çevirir."""
        self.save.switch_profile("acc:%s" % account.get("id"))
        self.save.data["account_token"] = seal_token(token)
        self.save.data["account_name"] = account.get("name", "")
        self.save.save()
        # ilerleme hesaba geçer.
        self.token = token
        self.account = account
        await self.pull_progress()

    def _forget(self):
        self.token = ""
        self.account = None
        self.save.data.pop("account_token", None)
        self.save.switch_profile("guest")
        self.save.save()

    def _session_kicked(self):
        """Tek oturum: bu hesaba başka bir cihazdan girilmiş - bu cihazın jetonu geçersiz."""
        if not self.token:
            return
        self._forget()
        self.status = L("acc.kicked")

    def logged_in(self):
        return bool(self.account)

    def needs_username(self):
        """Google ile gelen oyuncu henüz sıralama adını seçmemiş olabilir."""
        return bool(self.account) and not (self.account or {}).get("username")

    def display_name(self):
        a = self.account or {}
        return a.get("username") or a.get("name") or ""

    # ---- ilerleme eşitleme ----
    def _progress_changed(self):
        """Kayıt değişti: kısa bir gecikmeyle sunucuya yaz."""
        if not self.token or not self.logged_in() or self._sync_pending:
            return
        self._sync_pending = True

        async def later():
            await asyncio.sleep(1.5)
            self._sync_pending = False
            self.push_progress()
        spawn(later)

    # ---- hile itirafı ----
    def _profile_is_mine(self):
        """Aktif yerel profil gerçekten bu oturumun hesabına mı ait?"""
        acc = self.account or {}
        return bool(self.token and acc.get("id")
                    and self.save.profile_id() == "acc:%s" % acc.get("id"))

    def report_ban(self, reason=""):
        """Yerelde kalıcı yasak kondu: sunucuya hemen bildir."""
        if not self._profile_is_mine():
            return
        tok = self.token
        acc_id = (self.account or {}).get("id")
        reason = str(reason or (self.save.data.get("ban_reasons") or ["cheat_code"])[0])

        async def worker():
            try:
                res = await self._post("/player/report_cheat", {
                    "token": tok, "device": device_id(),
                    "device_legacy": device_id_legacy(),
                    "reason": reason}, timeout=15)
            except Exception:
                return
            if tok != self.token or (self.account or {}).get("id") != acc_id:
                return          # arada hesap değişti
            if res.get("success") and isinstance(res.get("progress"), dict):
                self.save.import_progress(res["progress"])
        spawn(worker)

    def _sync_ban(self, prog):
        """Sunucudan gelen ilerleme yasaksız ama yerel profil yasaklıysa (örn. hile çevrimdışıyken kullanıldı) yasağı sunucuya taşı."""
        if (isinstance(prog, dict) and not prog.get("board_banned")
                and self.save.is_board_banned() and self._profile_is_mine()):
            self.report_ban()

    async def pull_progress(self):
        """Hesabın sunucudaki ilerlemesini indirir ve uygular."""
        if not self.token:
            return
        tok = self.token          # istek bu hesabın adına gidiyor
        try:
            res = await self._post("/player/load", {"token": tok,
                                              "device": device_id(),
                                              "device_legacy": device_id_legacy()},
                                             timeout=15)
        except Exception as e:
            # Ağ yoksa yereldeki kopya kullanılmaya devam eder - ama sessiz
            # kalmıyoruz, hesap ekranı durumu gösteriyor.
            self.sync_error = self._err_text(e)
            if self.sync_error == "oturum geçersiz":
                self._session_kicked()
            return
        if tok != self.token:
            # hesap değişti (cevap gelene kadar çıkış yapılıp başka hesaba
            # girilmiş). Bu ilerleme artık başka birinin; uygulanırsa iki hesap
            # birbirine karışır.
            return
        if res.get("success") and isinstance(res.get("progress"), dict):
            self.save.import_progress(res["progress"])
            self._sync_ban(res["progress"])
            self.sync_error = ""
            self.sync_at = time.time()
        else:
            self.sync_error = str(res.get("error") or "ilerleme okunamadı")
            if self.sync_error == "oturum geçersiz":
                self._session_kicked()

    def push_progress(self, reason=""):
        """İlerlemeyi hesaba yazar."""
        if not self.token or not self.logged_in():
            return
        if self.save.is_tainted():
            # Şaibeli yerel kayıt sunucuya gönderilmez; tersine sunucudaki
            # temiz ilerleme indirilir (import_progress onu aynen alır).
            spawn(self.pull_progress)
            return
        prog = self.save.export_progress()
        tok = self.token          # anlık görüntü ile jeton birbirine bağlı
        self.sync_busy = True

        async def worker():
            try:
                # Jetonu burada yeniden okumuyoruz.
                res = await self._post("/player/save", {
                    "token": tok, "device": device_id(),
                    "device_legacy": device_id_legacy(),
                    "progress": prog}, timeout=20)
                if tok != self.token:
                    return      # arada hesap değişti: cevabı uygulama
                if res.get("success") and isinstance(res.get("progress"), dict):
                    # Sunucu düzelttiyse (örn. elmas sınırı) onunki geçerli.
                    self.save.import_progress(res["progress"])
                    self._sync_ban(res["progress"])
                    self.sync_error = ""
                    self.sync_at = time.time()
                else:
                    self.sync_error = str(res.get("error") or "bilinmeyen hata")
                    if self.sync_error == "oturum geçersiz":
                        self._session_kicked()
            except Exception as e:
                self.sync_error = self._err_text(e)
                if self.sync_error == "oturum geçersiz":
                    self._session_kicked()
            finally:
                self.sync_busy = False
        spawn(worker)

    # ---- ücretsiz elmas (sunucu hakem) ----
    def reward_call(self, path, extra, on_done):
        """Ödül isteği (arka planda). on_done(ok, hata_metni, cevap)."""
        tok = self.token
        if not tok:
            on_done(False, L("ui.world_needs_login"), None)
            return

        async def worker():
            try:
                payload = {"token": tok, "device": device_id(),
                           "device_legacy": device_id_legacy()}
                payload.update(extra or {})
                res = await self._post(path, payload, timeout=15)
            except Exception as e:
                on_done(False, self._err_text(e), None)
                return
            if tok != self.token:
                on_done(False, "", None)          # arada hesap değişti
                return
            ok = bool(res.get("success"))
            if ok and isinstance(res.get("progress"), dict):
                self.save.import_progress(res["progress"])
                self.sync_at = time.time()
            on_done(ok, "" if ok else str(res.get("error") or ""), res)
        spawn(worker)

    # ---- kullanıcı adı / şifre ----
    def register(self, username, password, email=""):
        self._run(lambda: self._auth_call("/auth/register", {
            "username": username, "password": password, "email": email}))

    def login(self, who, password):
        """who: kullanıcı adı veya e-posta."""
        self._run(lambda: self._auth_call("/auth/login", {
            "username": who, "password": password}))

    # ---- şifremi unuttum ----
    # 1) /auth/forgot {who}: sunucu hesaba kayıtlı e-postaya 6 haneli, kısa
    #    ömürlü bir kod yollar.
    # 2) /auth/reset {who, code, password}: kod doğruysa şifre değişir, bütün
    #    eski oturumlar kapanır ve bu cihazda oturum açılır (cevap /auth/login
    #    ile aynı biçimde: token + account).
    forgot_sent = False

    def _fp_err(self, e):
        if isinstance(e, urllib.error.HTTPError) and e.code in (404, 405):
            return L("ui.fp_no_server")
        return self._err_text(e)

    def forgot_password(self, who):
        async def fn():
            try:
                res = await self._post("/auth/forgot", {"who": who, "lang": lang()}, timeout=40)
            except Exception as e:
                self.status = self._fp_err(e)
                return
            if res.get("success"):
                self.forgot_sent = True
                self.ok_msg = L("ui.fp_sent")
                self.status = ""
            else:
                self.status = str(res.get("error") or L("ui.acc_neterr"))
        self._run(fn)

    def reset_password(self, who, code, new):
        async def fn():
            try:
                await self._auth_call("/auth/reset", {"who": who, "code": code, "password": new})
            except Exception as e:
                self.status = self._fp_err(e)
                return
            if self.logged_in():
                self.forgot_sent = False
        self._run(fn)

    def claim_username(self, username):
        """Kullanıcı adını bir kez belirler (Google ile gelenler için)."""
        async def fn():
            res = await self._post("/auth/username", {
                "token": self.token, "device": device_id(),
                    "device_legacy": device_id_legacy(),
                "username": username})
            if res.get("success"):
                self.account = res["account"]
                self.save.data["account_name"] = self.account.get("name", "")
                self.save.save()
                self.ok_msg = L("ui.acc_welcome", self.account.get("name", ""))
                self.status = ""
            else:
                self.status = str(res.get("error", ""))
        self._run(fn)

    def change_password(self, current, new):
        """Şifreyi değiştirir (ya da Google hesabına ilk şifreyi kurar)."""
        async def fn():
            res = await self._post("/auth/password", {
                "token": self.token, "device": device_id(),
                "device_legacy": device_id_legacy(),
                "password": current, "new_password": new})
            if res.get("success"):
                if res.get("token"):
                    self.token = res["token"]
                    self.save.data["account_token"] = seal_token(res["token"])
                    self.save.save()
                self.ok_msg = L("ui.acc_pw_done")
                self.status = ""
            else:
                self.status = str(res.get("error", ""))
        self._run(fn)

    def set_email(self, email, password):
        """Kurtarma e-postası ekler/değiştirir (şifre kurtarma kodu buraya gider)."""
        async def fn():
            res = await self._post("/auth/email", {
                "token": self.token, "device": device_id(),
                "device_legacy": device_id_legacy(),
                "email": email, "password": password})
            if res.get("success"):
                if isinstance(res.get("account"), dict):
                    self.account = res["account"]
                else:
                    self.account = dict(self.account or {}, email=email)
                self.ok_msg = L("ui.acc_email_done")
                self.status = ""
            else:
                self.status = str(res.get("error", ""))
        self._run(fn)

    def logout_all(self):
        """Bütün cihazlardan çıkar."""
        async def fn():
            res = await self._post("/auth/logout_all", {
                "token": self.token, "device": device_id(),
                "device_legacy": device_id_legacy()})
            if res.get("success"):
                self._forget()
                self.ok_msg = L("ui.acc_logout_all_done")
                self.status = ""
            else:
                self.status = str(res.get("error", ""))
        self._run(fn)

    async def _auth_call(self, path, payload):
        # Oturum bu cihaza bağlanır: jeton kopyalanıp başka bilgisayarda
        # kullanılamasın (sunucu da ayrıca denetler).
        payload = dict(payload, device=device_id(),
                       device_legacy=device_id_legacy())
        res = await self._post(path, payload)
        if res.get("success"):
            await self._remember(res["token"], res["account"])
            if path == "/auth/register":
                self.just_registered = True       # yeni hesap: eğitim gösterilsin
            self.ok_msg = L("ui.acc_welcome", res["account"].get("name", ""))
            self.status = ""
        else:
            self.status = str(res.get("error", ""))

    def _run(self, fn):
        """İşi arka planda çalıştırır; ekran donmaz."""
        if self.busy:
            return
        self.busy = True
        self.status = ""
        self.ok_msg = ""

        async def worker():
            try:
                r = fn()
                if asyncio.iscoroutine(r):
                    await r
            except Exception as e:
                self.status = self._err_text(e)
            finally:
                self.busy = False
        spawn(worker)

    def logout(self):
        tok = self.token
        self._forget()
        if tok:
            async def worker():
                try:
                    await self._post("/auth/logout", {"token": tok}, timeout=8)
                except Exception:
                    pass
            spawn(worker)

    def google_login(self):
        """Tarayıcıda Google girişini açar ve geri dönüşü bekler."""
        if self.booting:
            self.status = L("ui.acc_checking_session")
            return
        if not self.google_ready:
            self.status = L("ui.acc_google_off")
            return
        self.google_cancel = False
        self.google_back_at = 0.0
        self._run(self._google_worker)

    def google_abort(self):
        """Vazgeç: beklemeyi hemen bitirir."""
        self.google_cancel = True

    def note_window_focus(self, gained=True):
        """Oyun penceresinin odağı değişti."""
        if not self.google_wait:
            return
        if gained:
            if not self.google_back_at:
                self.google_back_at = time.time()
        else:
            self.google_back_at = 0.0

    async def _google_worker(self):
        verifier, challenge = _pkce_pair()
        state = base64.urlsafe_b64encode(os.urandom(18)).decode().rstrip("=")
        # RFC 8252: masaüstü uygulaması için 127.0.0.1 üzerinde rastgele port.
        srv = _http_server.HTTPServer(("127.0.0.1", 0), _OAuthCatcher)
        srv.timeout = 1
        port = srv.server_address[1]
        redirect_uri = f"http://127.0.0.1:{port}"
        params = {
            "client_id": self.client_id,
            "redirect_uri": redirect_uri,
            "response_type": "code",
            "scope": ACCOUNT_SCOPES,
            "code_challenge": challenge,
            "code_challenge_method": "S256",
            "state": state,
            "access_type": "offline",
            "prompt": "select_account",
        }
        url = GOOGLE_AUTH_URL + "?" + urllib.parse.urlencode(params)
        _OAuthCatcher.result = None
        self.status = L("ui.acc_browser")
        try:
            webbrowser.open(url)
        except Exception:
            self.status = L("ui.acc_nobrowser")
            srv.server_close()
            return
        # En çok 3 dakika bekle. erken çıkış iki yoldan olur: oyuncu vazgeç'e
        # basar, ya da tarayıcıyı kapatıp oyuna döner (pencere öne gelir) ve
        # GOOGLE_REFOCUS_GRACE saniye boyunca kod gelmez.
        self.google_wait = True
        self.google_back_at = 0.0
        vazgecti = False
        deadline = time.time() + 180
        try:
            while time.time() < deadline and _OAuthCatcher.result is None:
                if self.google_cancel:
                    vazgecti = True
                    break
                if (self.google_back_at and
                        time.time() - self.google_back_at > GOOGLE_REFOCUS_GRACE):
                    vazgecti = True
                    break
                try:
                    srv.handle_request()     # srv.timeout = 1 sn
                except Exception:
                    break
        finally:
            self.google_wait = False
            srv.server_close()
        res = _OAuthCatcher.result
        _OAuthCatcher.result = None
        if not res:
            self.status = L("ui.acc_cancel") if vazgecti else L("ui.acc_timeout")
            return
        if res.get("state") != state:
            # Beklediğimiz istek değil: başlatmadığımız bir giriş denemesi.
            self.status = L("ui.acc_badstate")
            return
        if "code" not in res:
            self.status = L("ui.acc_cancel")
            return
        self.status = L("ui.acc_checking")
        out = await self._post("/auth/google", {
            "code": res["code"], "code_verifier": verifier,
            "redirect_uri": redirect_uri, "device": device_id(),
             "device_legacy": device_id_legacy()})
        if out.get("success"):
            await self._remember(out["token"], out["account"])
            if out.get("new"):
                self.just_registered = True       # Google ile ilk kez: eğitim
            self.ok_msg = L("ui.acc_welcome", out["account"].get("name", ""))
            self.status = ""
        else:
            self.status = str(out.get("error", ""))


_PENDING_LOCK = threading.Lock()
PENDING_SCORES_MAX = 20
SUBMIT_RETRY_WAITS = (0, 6, 15, 30)   # sn: sunucu uyanıyorsa 4 deneme


class OnlineClient:
    def __init__(self, base_url):
        self._flushing = False
        self.base_url = (base_url or "").rstrip("/")
        self.enabled = bool(self.base_url)
        self.world_scores = None
        self.world_error = None
        self.loading = False

    # ---- gönderilemeyen skorlar diske yazılır, sonra tekrar denenir ----
    @staticmethod
    def _pending_path():
        return os.path.join(get_save_dir(), "pending_scores.json")

    def _pending_load(self):
        try:
            with open(self._pending_path(), "r", encoding="utf-8") as f:
                d = json.load(f)
            return d if isinstance(d, list) else []
        except Exception:
            return []

    def _pending_store(self, items):
        path = self._pending_path()
        try:
            if items:
                tmp = path + ".tmp"
                with open(tmp, "w", encoding="utf-8") as f:
                    json.dump(items[-PENDING_SCORES_MAX:], f)
                os.replace(tmp, path)
            elif os.path.exists(path):
                os.remove(path)
        except Exception as e:
            print("pending_scores yazılamadı:", repr(e))

    def _pending_add(self, payload):
        with _PENDING_LOCK:
            items = [x for x in self._pending_load() if x.get("sig") != payload.get("sig")]
            items.append(payload)
            self._pending_store(items)

    async def _flush_pending(self):
        if self._flushing:
            return
        self._flushing = True
        try:
            with _PENDING_LOCK:
                items = self._pending_load()
            done = set()
            for p in items:
                ok, why, retry = await self._send_once(p)
                if ok or not retry:         # kabul edildi ya da kalıcı red: listeden çık
                    done.add(p.get("sig"))
                else:
                    break                    # sunucu hâlâ yok: sonra tekrar
            if done:
                with _PENDING_LOCK:
                    self._pending_store([x for x in self._pending_load()
                                         if x.get("sig") not in done])
        finally:
            self._flushing = False

    def flush_pending_async(self):
        if self.enabled and not self._flushing and self._pending_load():
            spawn(self._flush_pending)

    def fetch_world_scores_async(self):
        self.flush_pending_async()
        if not self.enabled:
            self.world_scores = []
            self.world_error = "Çevrimiçi sunucu ayarlanmamış (yerel modda)."
            return
        self.loading = True
        self.world_error = None
        self.world_scores = None
        spawn(self._fetch_worker)

    async def _fetch_worker(self):
        try:
            # Arka planda döner, ekranda "yükleniyor" yazar - oyun beklemez.
            # mobil oyuncuların ayrı dünya sıralaması var.
            url = self.base_url + "/scores?platform=" + PLATFORM_TAG
            data = await http_json(url, None, WORLD_FETCH_TIMEOUT)
            if isinstance(data, dict):
                data = data.get("scores", [])
            if not isinstance(data, list):
                data = []
            data.sort(key=lambda e: e.get("score", 0), reverse=True)
            self.world_scores = data[:WORLD_LB_SIZE]
        except Exception as e:
            kind = net_error_kind(e)
            log_net_error("scores", e, kind)
            self.world_error = L("ui.acc_neterr") + " " + net_reason_text(*kind)
            self.world_scores = []
        finally:
            self.loading = False

    def submit_score_async(self, payload, on_done=None):
        if not self.enabled:
            return
        spawn(self._submit_worker, payload, on_done)

    async def _send_once(self, payload):
        """Tek gönderim denemesi -> (başarılı, sebep, tekrar denenebilir mi)."""
        try:
            res = await http_json(self.base_url + "/submit", payload, SUBMIT_TIMEOUT)
            if bool(res.get("success", True)):
                return True, "", False
            return False, str(res.get("error", "")), False       # sunucu bilerek reddetti
        except urllib.error.HTTPError as e:
            try:
                why = str(json.loads(e.read().decode("utf-8")).get("error", "")) or str(e.reason)
            except Exception:
                why = str(e.reason)
            code = int(getattr(e, "code", 0) or 0)
            return False, why, (code >= 500 or code in (408, 425, 429))
        except Exception as e:
            kind = net_error_kind(e)
            log_net_error("submit", e, kind)
            return False, net_reason_text(*kind), True

    async def _submit_worker(self, payload, on_done):
        """Skoru gönderir. Sunucu hatasında/zaman aşımında tekrar dener; yine de
        olmazsa skoru diske yazar, sonraki açılışta/gönderimde otomatik yollar."""
        ok, why, retry = False, "", False
        for wait in SUBMIT_RETRY_WAITS:
            if wait:
                await asyncio.sleep(wait)
            ok, why, retry = await self._send_once(payload)
            if ok or not retry:
                break
        if ok:
            await self._flush_pending()      # eskiden kalan skorlar da gitsin
        elif retry:
            self._pending_add(payload)
            why = (why + " - " if why else "") + "skor cihaza kaydedildi, bağlantı gelince otomatik gönderilir"
        if on_done:
            on_done(ok, why)


# parçacık / efekt sistemi

class Particle:
    __slots__ = ("x", "y", "vx", "vy", "life", "max_life", "color", "r", "gravity", "add", "drag", "grow")

    def __init__(self, x, y, vx, vy, life, color, r, gravity=0.0, add=True, drag=2.0, grow=0.0):
        self.x, self.y = x, y
        self.vx, self.vy = vx, vy
        self.life = life
        self.max_life = max(0.01, life)
        self.color = (int(color[0]), int(color[1]), int(color[2]))
        self.r = r
        self.gravity = gravity
        self.add = add
        self.drag = drag
        self.grow = grow

    def update(self, dt):
        self.x += self.vx * dt
        self.y += self.vy * dt
        self.vy += self.gravity * dt
        d = max(0.0, 1.0 - self.drag * dt)
        self.vx *= d
        self.vy *= d
        self.life -= dt
        return self.life > 0

    def draw(self, surf):
        k = clamp(self.life / self.max_life, 0.0, 1.0)
        r = max(1.0, (self.r + self.grow * (1 - k)) * (0.35 + 0.65 * k))
        if self.add:
            gr = max(2, r * 2.6)
            if MOBILE or gr >= _GFX_GLOW_R[0]:
                add_glow(surf, self.x, self.y, gr, self.color, k * 0.95)
            else:
                # düşük/orta grafik: parlama sprite'ı yok, küçük toplamalı kare
                # (önbellek ve alfa karışımı gerektirmez)
                kk = 0.8 * k
                c = self.color
                sz = max(1, int(r * 0.9))
                surf.fill((int(c[0] * kk), int(c[1] * kk), int(c[2] * kk)),
                          (int(self.x) - sz, int(self.y) - sz, sz * 2, sz * 2),
                          special_flags=pygame.BLEND_RGB_ADD)
        else:
            blit_disc(surf, self.x, self.y, r, self.color, 215 * k)


class Ring:
    __slots__ = ("x", "y", "r0", "r1", "life", "max_life", "color", "width")

    def __init__(self, x, y, r0, r1, life, color, width):
        self.x, self.y, self.r0, self.r1 = x, y, r0, r1
        self.life = life
        self.max_life = life
        self.color = color
        self.width = width

    def update(self, dt):
        self.life -= dt
        return self.life > 0

    def draw(self, surf):
        k = clamp(self.life / self.max_life, 0.0, 1.0)
        rad = lerp(self.r1, self.r0, k ** 1.6)
        col = scale_col(self.color, 0.25 + 0.75 * k)
        w = max(1, int(self.width * k + 0.5))
        pygame.draw.circle(surf, col, (int(self.x), int(self.y)), max(2, int(rad)), w)


class BoltFx:
    __slots__ = ("pts", "color", "life", "max_life")

    def __init__(self, pts, color, life):
        self.pts = pts
        self.color = color
        self.life = life
        self.max_life = life

    def update(self, dt):
        self.life -= dt
        return self.life > 0

    def draw(self, surf):
        k = clamp(self.life / self.max_life, 0.0, 1.0)
        pts = [(int(x), int(y)) for x, y in self.pts]
        if len(pts) >= 2:
            pygame.draw.lines(surf, scale_col(self.color, 0.6 + 0.4 * k), False, pts, max(2, int(5 * k)))
            pygame.draw.lines(surf, WHITE, False, pts, max(1, int(2 * k)))
        add_glow(surf, pts[-1][0], pts[-1][1], 34, self.color, k)


class FloatingText:
    __slots__ = ("x", "y", "vy", "life", "max_life", "text", "color", "size")

    def __init__(self, x, y, text, color=TEXT, size=18, vy=-46, life=0.8):
        self.x, self.y = x, y
        self.vy = vy
        self.life = life
        self.max_life = life
        self.text = text
        self.color = color
        self.size = size

    def update(self, dt):
        self.y += self.vy * dt
        self.vy *= (1 - min(1, dt * 1.5))
        self.life -= dt
        return self.life > 0

    def draw(self, surf):
        t = clamp(self.life / self.max_life, 0, 1)
        sz = int(self.size * (1.15 - 0.15 * t))
        draw_text(surf, self.text, (self.x, self.y), sz, self.color, bold=True, center=True,
                  alpha=int(255 * min(1.0, t * 2.2)))


# ---- sakin ekran ----
# "Sürekli bir şeyler patlıyor, göz yoruyor." Düşman hızı ve sayısı aynı;
# yalnız görsel gürültü kısıldı: flaş ve sarsıntı yarıya yakın, aynı anda
# uçuşan yazı ve parçacık sınırlı, kalabalıkta küçük hasar sayıları atlanır.
FX_FLASH_K = 0.45
FX_FLASH_MAX = 0.32
FX_SHAKE_K = 0.55
FX_BURST_K = 0.7
FX_TEXT_MAX = 36
FX_TEXT_BUSY = 18               # bundan fazla yazı varken küçük sayılar basılmaz


class EffectSystem:
    MAX_PARTICLES = 220 if MOBILE else 420

    def __init__(self):
        self.particles = []
        self.texts = []
        self.rings = []
        self.bolts = []
        self.shake_time = 0.0
        self.shake_mag = 0.0
        self.flash = 0.0
        self.flash_col = WHITE

    def spark(self, x, y, color, vx=0.0, vy=0.0, life=0.5, r=2.5, add=True, gravity=0.0, drag=2.0, grow=0.0):
        if len(self.particles) < min(self.MAX_PARTICLES, gfx_particle_cap()):
            self.particles.append(Particle(x, y, vx, vy, life, color, r, gravity, add, drag, grow))

    def burst(self, x, y, color, n=10, speed=140, life=0.5, r=3.0, gravity=0.0, add=True):
        n = max(1, int(n * FX_BURST_K * gfx_fx_mult() + 0.5))
        for _ in range(n):
            ang = random.uniform(0, math.tau)
            spd = random.uniform(speed * 0.3, speed)
            self.spark(x, y, color, math.cos(ang) * spd, math.sin(ang) * spd,
                       random.uniform(life * 0.6, life), random.uniform(r * 0.6, r), gravity, add)

    def ring(self, x, y, color, n=16, speed=180, life=0.4, r=2.5):
        n = max(3, int(n * FX_BURST_K * gfx_fx_mult() + 0.5))
        for i in range(n):
            ang = (i / n) * math.tau
            self.spark(x, y, color, math.cos(ang) * speed, math.sin(ang) * speed, life, r)

    def shockwave(self, x, y, radius, color, life=0.35, width=5):
        self.rings.append(Ring(x, y, 4, radius, life, color, width))

    def bolt(self, pts, color=(200, 230, 255), life=0.25):
        self.bolts.append(BoltFx(pts, color, life))

    def popup(self, x, y, text, color=TEXT, size=18, life=0.8):
        n = len(self.texts)
        _gl = gfx_level()
        if n >= (FX_TEXT_MAX, 24, 14)[_gl]:
            return
        if n >= (6, 10, FX_TEXT_BUSY)[_gl] and size <= 16 and life <= 0.6:
            return
        self.texts.append(FloatingText(x, y, text, color, size, life=life))

    def shake(self, amount=8, duration=0.18):
        self.shake_time = max(self.shake_time, duration)
        self.shake_mag = max(self.shake_mag, amount * FX_SHAKE_K)

    def do_flash(self, color=WHITE, amount=0.5):
        if gfx_level() == 0:
            return              # düşük grafik: tam ekran ışık patlaması yok
        self.flash = max(self.flash, min(FX_FLASH_MAX, amount * FX_FLASH_K))
        self.flash_col = color

    def get_shake_offset(self):
        if self.shake_time <= 0 or not CFG["shake"]:
            return (0, 0)
        m = self.shake_mag * clamp(self.shake_time / 0.25, 0.0, 1.0)
        return (int(random.uniform(-m, m)), int(random.uniform(-m, m)))

    def update(self, dt):
        self.particles = [p for p in self.particles if p.update(dt)]
        self.texts = [t for t in self.texts if t.update(dt)]
        self.rings = [r for r in self.rings if r.update(dt)]
        self.bolts = [b for b in self.bolts if b.update(dt)]
        if self.shake_time > 0:
            self.shake_time = max(0.0, self.shake_time - dt)
            if self.shake_time <= 0:
                self.shake_mag = 0.0
        if self.flash > 0:
            self.flash = max(0.0, self.flash - dt * 2.2)

    def draw(self, surf):
        for r in self.rings:
            r.draw(surf)
        for p in self.particles:
            p.draw(surf)
        for b in self.bolts:
            b.draw(surf)

    def draw_texts(self, surf):
        texts = self.texts
        if MOBILE and len(texts) > MOBILE_MAX_TEXTS:
            texts = texts[-MOBILE_MAX_TEXTS:]      # telefon: en yeni hasar sayıları
        for t in texts:
            t.draw(surf)


# ikon çizimi

# Aşağıdaki tablo ile draw_icon her simgeyi çizmeden önce ölçekleyip ortalar:
# hepsi aynı büyüklükte bir kutuya oturur ve gerçek merkezi istenen noktaya
# gelir.
ICON_METRICS = {
    "sword":  (0.75, 0.66, -0.03),
    "boot":   (0.58, 0.58, -0.03),
    "heart":  (0.71, 0.62, 0.04),
    "bolt":   (0.42, 0.72, -0.03),
    "target": (0.64, 0.64, -0.03),
    "magnet": (0.60, 0.55, -0.02),
    "coin":   (0.69, 0.69, -0.03),
    "star":   (0.70, 0.72, -0.10),
    "cross":  (0.60, 0.60, -0.03),
    "shield": (0.62, 0.82, -0.01),
    "fist":   (0.58, 0.70, -0.20),
    "clover": (0.68, 0.68, -0.06),
    "gem":    (0.70, 0.78, -0.07),
    "skull":  (0.60, 0.68, -0.06),
    "orbit":  (0.68, 0.68, -0.06),
    "dash":   (0.62, 0.58, -0.03),
    "drop":   (0.52, 0.69, -0.07),
    "flame":  (0.50, 0.73, -0.12),
    "snow":   (0.74, 0.67, -0.03),
    "book":   (0.60, 0.70, -0.11),
    "ghost":  (0.66, 0.87, -0.04),
    "horseshoe": (0.68, 0.70, -0.02),   # şans kitabı
    "clover4": (0.66, 0.74, -0.04),     # dört yapraklı yonca
}
# Bütün simgelerin oturduğu ortak kutunun yarı ölçüsü (r'nin katı).
ICON_FIT = 0.74


def draw_icon(surf, cx, cy, kind, color, r=13):
    kind = kind or "star"
    color = (int(color[0]), int(color[1]), int(color[2]))
    cx, cy = float(cx), float(cy)
    # ---- ortak ölçek + ortalama ----
    # Simgeyi kendi gerçek sınırlarına göre ölçekle (hepsi aynı kutuya otursun)
    # ve görsel merkezini istenen noktaya kaydır (hiçbiri kaymış durmasın).
    m = ICON_METRICS.get(kind)
    if m is not None:
        hw, hh, oy = m
        r = r * (ICON_FIT / max(0.01, max(hw, hh)))
        cy -= oy * r
    if kind == "sword":
        pygame.draw.line(surf, color, (cx - r*0.5, cy + r*0.6), (cx + r*0.6, cy - r*0.6), 4)
        pygame.draw.line(surf, color, (cx - r*0.7, cy + r*0.1), (cx - r*0.2, cy + r*0.6), 3)
    elif kind == "boot":
        pts = [(cx - r*0.5, cy - r*0.6), (cx - r*0.1, cy - r*0.6), (cx - r*0.1, cy + r*0.15),
               (cx + r*0.6, cy + r*0.15), (cx + r*0.6, cy + r*0.55), (cx - r*0.5, cy + r*0.55)]
        pygame.draw.polygon(surf, color, pts, 0)
    elif kind == "heart":
        pygame.draw.circle(surf, color, (cx - r*0.32, cy - r*0.15), r*0.42)
        pygame.draw.circle(surf, color, (cx + r*0.32, cy - r*0.15), r*0.42)
        pygame.draw.polygon(surf, color, [(cx - r*0.7, cy - r*0.05), (cx + r*0.7, cy - r*0.05), (cx, cy + r*0.7)])
    elif kind == "bolt":
        pts = [(cx + r*0.15, cy - r*0.7), (cx - r*0.35, cy + r*0.05), (cx, cy + r*0.05),
               (cx - r*0.15, cy + r*0.7), (cx + r*0.4, cy - r*0.1), (cx + r*0.05, cy - r*0.1)]
        pygame.draw.polygon(surf, color, pts)
    elif kind == "target":
        pygame.draw.circle(surf, color, (cx, cy), r*0.7, 2)
        pygame.draw.circle(surf, color, (cx, cy), r*0.35, 2)
        pygame.draw.circle(surf, color, (cx, cy), 2)
    elif kind == "magnet":
        rect = pygame.Rect(0, 0, int(r*1.1), int(r*1.1))
        rect.center = (int(cx), int(cy))
        pygame.draw.arc(surf, color, rect, math.pi*0.15, math.pi*0.85, 4)
        pygame.draw.line(surf, color, (cx - r*0.55, cy), (cx - r*0.55, cy + r*0.5), 4)
        pygame.draw.line(surf, color, (cx + r*0.55, cy), (cx + r*0.55, cy + r*0.5), 4)
    elif kind == "coin":
        pygame.draw.circle(surf, color, (cx, cy), r*0.75, 2)
        draw_text(surf, "$", (cx, cy), int(r*1.1), color, bold=True, center=True, shadow=False)
    elif kind == "star":
        pts = []
        for i in range(10):
            ang = -math.pi/2 + i * math.pi/5
            rad = r*0.75 if i % 2 == 0 else r*0.32
            pts.append((cx + math.cos(ang)*rad, cy + math.sin(ang)*rad))
        pygame.draw.polygon(surf, color, pts)
    elif kind == "cross":
        pygame.draw.line(surf, color, (cx, cy - r*0.6), (cx, cy + r*0.6), 4)
        pygame.draw.line(surf, color, (cx - r*0.6, cy), (cx + r*0.6, cy), 4)
    elif kind == "shield":
        # Yuvarlak omuzlu, sivri alt uçlu dolu bir kalkan silüeti + koyu kontur
        # + orta kaburga (diğer dolu ikonlarla - book/drop/flame - aynı dil).
        pts = [(cx - r*0.60, cy - r*0.55), (cx - r*0.28, cy - r*0.78),
               (cx + r*0.28, cy - r*0.78), (cx + r*0.60, cy - r*0.55),
               (cx + r*0.60, cy - r*0.02), (cx, cy + r*0.82),
               (cx - r*0.60, cy - r*0.02)]
        pygame.draw.polygon(surf, color, pts)
        pygame.draw.polygon(surf, (14, 14, 22), pts, max(1, int(r*0.09)))
        pygame.draw.line(surf, (14, 14, 22), (cx, cy - r*0.60), (cx, cy + r*0.55),
                          max(1, int(r*0.07)))
    elif kind == "fist":
        pygame.draw.circle(surf, color, (cx, cy), r*0.55, 3)
        pygame.draw.line(surf, color, (cx - r*0.2, cy - r*0.8), (cx - r*0.2, cy - r*0.3), 3)
        pygame.draw.line(surf, color, (cx + r*0.15, cy - r*0.85), (cx + r*0.15, cy - r*0.3), 3)
    elif kind == "clover":
        for ang in (0, math.pi/2, math.pi, math.pi*1.5):
            ox, oy = math.cos(ang)*r*0.35, math.sin(ang)*r*0.35
            pygame.draw.circle(surf, color, (cx + ox, cy + oy), r*0.38)
    elif kind == "horseshoe":
        # şans: ters U nal + çivi delikleri (Kritik'in yoncasıyla karışmasın).
        wd = max(3, int(r * 0.30))
        rr = r * 0.62
        rect = pygame.Rect(0, 0, int(rr * 2), int(rr * 2))
        rect.center = (int(cx), int(cy - r * 0.02))
        pygame.draw.arc(surf, color, rect, 0.0, math.pi, wd)
        for sx in (-1, 1):
            pygame.draw.line(surf, color, (cx + sx * (rr - wd * 0.5), cy - r * 0.02),
                             (cx + sx * (rr - wd * 0.3), cy + r * 0.66), wd)
            pygame.draw.circle(surf, (14, 14, 22), (cx + sx * (rr - wd * 0.5), cy + r * 0.30),
                               max(1, r * 0.07))
        pygame.draw.circle(surf, (14, 14, 22), (cx, cy - rr + wd * 0.5), max(1, r * 0.07))
    elif kind == "clover4":
        # dört yapraklı yonca: çapraz dört yaprak + sap.
        pygame.draw.line(surf, color, (cx, cy), (cx + r * 0.30, cy + r * 0.78),
                         max(2, int(r * 0.14)))
        for k in range(4):
            ang = math.pi / 4 + k * math.pi / 2
            ux, uy = math.cos(ang), math.sin(ang)
            vx, vy = -uy, ux
            for s in (-1, 1):
                pygame.draw.circle(surf, color,
                                   (cx + ux * r * 0.36 + vx * s * r * 0.13,
                                    cy + uy * r * 0.36 + vy * s * r * 0.13 - r * 0.08),
                                   r * 0.24)
        pygame.draw.circle(surf, (14, 14, 22), (cx, cy - r * 0.08), max(1, r * 0.08))
    elif kind == "gem":
        pts = [(cx, cy - r*0.8), (cx + r*0.7, cy - r*0.15), (cx + r*0.4, cy + r*0.75),
               (cx - r*0.4, cy + r*0.75), (cx - r*0.7, cy - r*0.15)]
        pygame.draw.polygon(surf, color, pts, 0)
        pygame.draw.polygon(surf, WHITE, pts, 1)
    elif kind == "skull":
        pygame.draw.circle(surf, color, (cx, cy - r*0.1), r*0.62)
        pygame.draw.rect(surf, color, (cx - r*0.32, cy + r*0.2, r*0.64, r*0.5))
        pygame.draw.circle(surf, (14, 14, 22), (cx - r*0.25, cy - r*0.1), r*0.16)
        pygame.draw.circle(surf, (14, 14, 22), (cx + r*0.25, cy - r*0.1), r*0.16)
    elif kind == "orbit":
        pygame.draw.circle(surf, color, (cx, cy), r*0.7, 1)
        pygame.draw.circle(surf, color, (cx + r*0.5, cy - r*0.5), r*0.22)
        pygame.draw.circle(surf, color, (cx - r*0.5, cy + r*0.5), r*0.22)
        pygame.draw.circle(surf, color, (cx, cy), r*0.18)
    elif kind == "dash":
        for off in (-0.5, 0.1):
            pygame.draw.lines(surf, color, False, [(cx + r*off, cy - r*0.55), (cx + r*(off+0.5), cy),
                                                    (cx + r*off, cy + r*0.55)], 3)
    elif kind == "drop":
        # zehir damlası
        pts = [(cx, cy - r*0.75), (cx + r*0.52, cy + r*0.18), (cx + r*0.30, cy + r*0.62),
               (cx - r*0.30, cy + r*0.62), (cx - r*0.52, cy + r*0.18)]
        pygame.draw.polygon(surf, color, pts)
        pygame.draw.circle(surf, (14, 14, 22), (cx - r*0.14, cy + r*0.18), max(1, r*0.13))
    elif kind == "flame":
        pts = [(cx, cy - r*0.80), (cx + r*0.48, cy - r*0.05), (cx + r*0.34, cy + r*0.62),
               (cx - r*0.34, cy + r*0.62), (cx - r*0.48, cy - r*0.05)]
        pygame.draw.polygon(surf, color, pts)
        pygame.draw.polygon(surf, (14, 14, 22),
                            [(cx, cy - r*0.10), (cx + r*0.22, cy + r*0.30), (cx - r*0.22, cy + r*0.30)])
    elif kind == "snow":
        for k in range(3):
            a = k * math.pi / 3
            dx, dy = math.cos(a) * r*0.72, math.sin(a) * r*0.72
            pygame.draw.line(surf, color, (cx - dx, cy - dy), (cx + dx, cy + dy), 2)
        pygame.draw.circle(surf, color, (cx, cy), max(1, r*0.16))
    elif kind == "mail":
        w_, h_ = r * 1.5, r * 1.05
        box = pygame.Rect(int(cx - w_ / 2), int(cy - h_ / 2), int(w_), int(h_))
        pygame.draw.rect(surf, color, box, max(2, int(r * 0.16)), border_radius=max(2, int(r * 0.15)))
        pygame.draw.lines(surf, color, False, [(box.x + 2, box.y + 2), (cx, cy + h_ * 0.12),
                                               (box.right - 2, box.y + 2)], max(2, int(r * 0.16)))
    elif kind == "book":
        pygame.draw.rect(surf, color, (cx - r*0.62, cy - r*0.72, r*1.24, r*1.44), border_radius=2)
        pygame.draw.line(surf, (14, 14, 22), (cx, cy - r*0.62), (cx, cy + r*0.62), 2)
    elif kind == "ghost":
        # görünmezlik pelerini: başlığı kalkık, alt kenarı dalgalı bir hayalet
        pygame.draw.circle(surf, color, (cx, int(cy - r * 0.22)), int(r * 0.66))
        body = [(cx - r * 0.66, cy - r * 0.2), (cx + r * 0.66, cy - r * 0.2),
                (cx + r * 0.66, cy + r * 0.5), (cx + r * 0.33, cy + r * 0.86),
                (cx, cy + r * 0.5), (cx - r * 0.33, cy + r * 0.86),
                (cx - r * 0.66, cy + r * 0.5)]
        pygame.draw.polygon(surf, color, body)
        pygame.draw.circle(surf, (14, 14, 22), (int(cx - r * 0.24), int(cy - r * 0.3)),
                           max(1, int(r * 0.15)))
        pygame.draw.circle(surf, (14, 14, 22), (int(cx + r * 0.24), int(cy - r * 0.3)),
                           max(1, int(r * 0.15)))
    else:
        pygame.draw.circle(surf, color, (cx, cy), r*0.6, 2)


def draw_coin_label(surf, cx, cy, text, color, size=17, icon="coin",
                    icon_r=8, bold=True, gap=6, shadow=True):
    """Simge + sayı ikilisini tek bir blok gibi (cx, cy) çevresinde ortalar."""
    tw = text_width(text, size, bold)
    total = icon_r * 2.0 + gap + tw
    x0 = cx - total * 0.5
    draw_icon(surf, x0 + icon_r, cy, icon, color, icon_r)
    draw_text(surf, text, (x0 + icon_r * 2.0 + gap + tw * 0.5, cy), size, color,
              bold=bold, center=True, shadow=shadow)
    return total


def coin_label_width(text, size=17, icon_r=8, bold=True, gap=6):
    """Draw_coin_label'ın çizeceği bloğun genişliği (pastili ona göre kur)."""
    return icon_r * 2.0 + gap + text_width(text, size, bold)


