# oyundan kaldırılan skinler -> sahiplerine verilen karşılık
REMOVED_SKINS = {"toxic": "venom_striker"}


def migrate_removed_skins(data):
    """Kaldırılmış bir skine sahip olan oyuncu onun yerine geçen (daha değerli) skini alır; kuşanılıysa o kuşanılır."""
    owned = data.get("skins_owned")
    if not isinstance(owned, list):
        return data
    out = []
    for sid in owned:
        rep_ = REMOVED_SKINS.get(sid)
        if rep_ is None:
            if sid not in out:
                out.append(sid)
        elif rep_ not in out and rep_ not in owned:
            out.append(rep_)
    data["skins_owned"] = out
    if data.get("equipped_skin") in REMOVED_SKINS:
        data["equipped_skin"] = REMOVED_SKINS[data["equipped_skin"]]
    return data
SKIN_BY_ID = {s["id"]: s for s in SKINS}


def get_skin(skin_id):
    return SKIN_BY_ID.get(skin_id, SKINS[0])


def skin_gem_cost(sk):
    """Skinin elmas fiyatı."""
    c = sk.get("cost")
    return float("inf") if c is None else int(c)


