STARTER_BOOKS = [b["key"] for b in BOOKS if b.get("basic")]
# Oyuncunun "bu bana gelmesin" diyerek kapatabileceği en fazla kitap sayısı.
# Kitap sayısı 27'ye çıktığı için pay da büyüdü: 6 kitap kapatılabilir.
MAX_MUTED_BOOKS = 6
