BASE_DASH_CD = 2.4
BASE_BONK_CD = 1.35

# ---- seviye eğrisi ----
# Eski eğri tek bir çarpandı (her seviyede ihtiyaç x1.24 + 8):
#   11-25: neredeyse doğrusal; seviye oyunun akışına ayak uydurur.
#   26-50: hâlâ ölçülü büyür - seviye gelmeye devam eder ama hızlanmaz.
#   51+: belirgin şekilde sertleşir; 50'den sonrası uzun bir tırmanış.
XP_BASE_NEED = 22
# denge düğmesi - seviye hızı. Eski bantlar: 9. dalgada 30., 25. dalgada 61.
# seviye (kalibre edilmiş tahmin).
XP_GAIN_BUFFS = (1.15, 1.20)
# "gelen XP'yi tam %10 kıs" - bütün tecrübe (yaratık, patron, kitap çarpanı
# dahil; hepsi gain_xp'den geçer) x0,90.
XP_TRIM = 0.90
XP_GAIN_SCALE = 1.40 * XP_GAIN_BUFFS[0] * XP_GAIN_BUFFS[1] * XP_TRIM
# 15. seviyeden sonra kilit kalktı.
XP_CURVE_BANDS = (
    (6,    1.240, 8),
    (12,   1.190, 50),
    (50,   1.000, 34),
    (None, 1.012, 40),
)
# bilgelik kitabı: her seviyede tecrübe kazancına eklenen pay. 0.15 -> 0.08.
WISDOM_XP_PER_LEVEL = 0.08
# altın kitabı: her seviyede altın kazancına eklenen pay. 0.15 -> 0.07 ("altın
# kitabıyla bir anda zengin oluyorum").
GOLD_BOOK_PER_LEVEL = 0.07

# dalgaya göre tecrübe ve altın ("ilk 15 dalga için %30 nerfle"). Seviyenin
# gerçekten %30 düşmesi için akan tecrübe %45 kısılır:
#   1-15. dalga: tecrübe %45, altın %30 az (ECON_*_EARLY)
#   16-20. dalga: kısıntı yavaşça %20'ye iner (ECON_LATE) - geç dalgalarda
#      zaten kesmek zor, ikinci bir duvar olmasın
#   cehennem: tecrübe bonuslu (ECON_HELL_XP) - silahlar orada 15'ten
#      25'e büyüsün, oyuncu cehennemde güçlensin; altın tam
ECON_XP_EARLY = 0.55
ECON_GOLD_EARLY = 0.70
ECON_LATE = 0.80
ECON_HELL_XP = 1.35
ECON_EARLY_UNTIL = 15
ECON_RAMP_WAVES = 5


# süreli dalgalar - ekonomi temposu.
ECON_TIME_REF = {
    "normal": ((1, 0.4), (5, 3.7), (10, 8.0), (15, 13.5), (20, 19.0), (25, 24.0), (30, 28.0)),
    "hard": ((1, 0.35), (5, 2.6), (10, 4.8), (15, 8.1), (20, 12.2), (25, 15.0), (30, 18.1)),
    "nightmare": ((1, 0.3), (5, 2.1), (10, 3.9), (15, 6.9), (20, 10.3), (25, 12.9), (30, 15.7)),
}
ECON_TIME_REF_SLOPE = 0.65     # 30'dan sonra eski tempo: dalga başına dakika
# Daha uzun süren dalgada oyuncu daha güçlenip daha hızlı keser (kendini
# besleyen döngü); süre oranı tek başına yetmez - ölçümle ayarlanan pay.
ECON_TIME_EDGE = {"normal": 0.72, "hard": 0.72, "nightmare": 0.85}
ECON_TIME_FLOOR = 0.12
_ECON_TIME_CACHE = {}


def _econ_ref_minutes(w, diff):
    tbl = ECON_TIME_REF.get(diff, ECON_TIME_REF["normal"])
    if w >= tbl[-1][0]:
        return tbl[-1][1] + (w - tbl[-1][0]) * ECON_TIME_REF_SLOPE
    for (w0, m0), (w1, m1) in zip(tbl, tbl[1:]):
        if w0 <= w <= w1:
            return m0 + (m1 - m0) * (w - w0) / float(w1 - w0)
    return tbl[0][1]


def econ_time_factor(wave, diff="normal", biome="arena"):
    """Süreli dalgalarda yaratık başına tecrübe/altın çarpanı."""
    key = (int(wave), diff, biome)
    k = _ECON_TIME_CACHE.get(key)
    if k is None:
        w = max(1, int(wave))
        new_min = (wave_start_time(w, diff, biome) + 0.5 * wave_length(w, diff, biome)) / 60.0
        ref = _econ_ref_minutes(w + (HELL_BASE_WAVE if biome == "hell" else 0), diff)
        if biome == "hell":
            ref -= _econ_ref_minutes(HELL_BASE_WAVE, diff)
        edge = ECON_TIME_EDGE.get(diff, 0.72) if isinstance(ECON_TIME_EDGE, dict) else ECON_TIME_EDGE
        # ilk dalgalarda kendini besleyen döngü yok: pay 5. dalgadan 15'e
        # açılır
        tw_ = w + (HELL_BASE_WAVE if biome == "hell" else 0)
        edge = 1.0 + (edge - 1.0) * clamp((tw_ - 5) / 10.0, 0.0, 1.0)
        k = clamp(edge * ref / max(0.2, new_min), ECON_TIME_FLOOR, 1.0)
        _ECON_TIME_CACHE[key] = k
    return k


# tecrübe yumuşak tavanı. Yani iyi oynayan yine önde gider, yalnızca kopup
# gitmez.
XP_SOFTCAP_REF = ((1, 1), (5, 9), (10, 14), (15, 22), (20, 34), (25, 50), (30, 63))
XP_SOFTCAP_SLOPE = 2.6        # 30'dan sonra dalga başına olağan seviye artışı
XP_SOFTCAP_EDGE = 1.15
XP_SOFTCAP_K = 0.09           # olağanın her 1 seviye üstünde tecrübe ~%8 azalır


def xp_level_softcap(level, total_wave):
    w = max(1, int(total_wave))
    tbl = XP_SOFTCAP_REF
    if w >= tbl[-1][0]:
        ref = tbl[-1][1] + (w - tbl[-1][0]) * XP_SOFTCAP_SLOPE
    else:
        ref = tbl[0][1]
        for (w0, l0), (w1, l1) in zip(tbl, tbl[1:]):
            if w0 <= w <= w1:
                ref = l0 + (l1 - l0) * (w - w0) / float(w1 - w0)
                break
    over = float(level) - ref * XP_SOFTCAP_EDGE
    if over <= 0:
        return 1.0
    return 1.0 / (1.0 + XP_SOFTCAP_K * over)


def econ_wave_factor(wave, biome="arena", kind="gold", diff="normal"):
    """O dalgada yaratıktan düşen tecrübe ("xp") / altın ("gold") çarpanı."""
    tk = econ_time_factor(wave, diff, biome)
    if biome == "hell":
        return (ECON_HELL_XP if kind == "xp" else 1.0) * tk
    early = ECON_XP_EARLY if kind == "xp" else ECON_GOLD_EARLY
    w = int(wave)
    if w <= ECON_EARLY_UNTIL:
        return early * tk
    k = clamp((w - ECON_EARLY_UNTIL) / float(ECON_RAMP_WAVES), 0.0, 1.0)
    return (early + (ECON_LATE - early) * k) * tk


def stack_bonus(per, lvl, soft=4.0):
    """Üst üste binen kitap bonuslarının azalan getirisi."""
    lvl = max(0.0, float(lvl))
    if lvl <= 0:
        return 0.0
    return per * soft * (1.0 - (soft / (soft + lvl)))


def xp_next_need(need, level):
    """`level` seviyesine ulaşan oyuncunun bir sonraki seviye için ihtiyacı."""
    for cap, growth, flat in XP_CURVE_BANDS:
        if cap is None or level <= cap:
            return max(1, int(need * growth + flat))
    return max(1, int(need * XP_CURVE_BANDS[-1][1] + XP_CURVE_BANDS[-1][2]))


# ---- şans sistemi ----
# Şans kritik şansı değildir. Şans, seviye atlarken ve sandıklardan daha yüksek
# kademeli ödül çıkma ihtimalini artırır:
#   Yaygın x1.0, Sıradışı x1.5, Nadir x2.0, Epik x2.85, Efsanevi x4.0
RARITY_COUNT = 5
RARITY_BASE_WEIGHTS = (70.0, 23.0, 6.0, 1.0, 0.15)
RARITY_LUCK_EXP = 0.95
RARITY_LEGEND_CAP = 0.10        # Efsanevi payının tavanı
RARITY_MULTS = (1.0, 1.5, 2.0, 2.85, 4.0)
RARITY_COLORS = ((200, 200, 210), GREEN, BLUE, PURPLE, GOLD)
# Silah nadirlik bonusu: sandık ya da seviye kartı silaha kalıcı hasar ekler.
CARD_RARITY_BONUS = (0.0, 0.03, 0.06, 0.10, 0.16)    # seviye kartı
CHEST_RARITY_BONUS = (0.04, 0.07, 0.12, 0.20, 0.30)  # patron sandığı
WEAPON_BOOST_STEP = 0.07        # (eski ad; yalnızca geriye dönük uyum)
WEAPON_BOOST_CAP = 1.00         # silah başına en fazla +%100
# Efsanevi sandık silaha bir seviye daha verir (tavan izin veriyorsa).
LEGEND_CHEST_EXTRA_LEVEL = True
LUCK_BOOK_PER_LEVEL = 0.075     # şans kitabı: 1-10. seviye +%7,5 ...
LUCK_BOOK_LATE = 0.025          # ... 11-30. seviye +%2,5
CLOVER_LUCK_ON_TAKE = 0.60      # dört yapraklı yonca: alınınca +%60
CLOVER_LUCK_PER_LEVEL = 0.05    # ... ve sonraki her seviyede +%5
CORE_LUCK_SOFT = 6.0            # şans çekirdeği: azalan getiri ...
# ... ilk alım tam +%8 versin diye (stack_bonus ilk adımda per*soft/(soft+1)
# verir): sonsuz alımda toplam +%56'ya yaklaşır.
CORE_LUCK_PER_LEVEL = 0.08 * (CORE_LUCK_SOFT + 1.0) / CORE_LUCK_SOFT
LUCKY_COIN_LUCK = 0.10          # uğurlu akçe: ek +%10 şans
GAMBLER_DICE_LUCK = 0.25        # kumarbazın zarı: +%25 şans
LUCK_FREE_REROLL_K = 0.20       # şanslı yenileme olasılığı = şans * K ...
LUCK_FREE_REROLL_MAX = 0.35     # ... en fazla %35
LUCK_RARE_BOOK_K = 0.5          # nadir kitap ağırlığı * (1 + K * şans)
LUCK_MAGNET_K = 0.5             # mıknatıs şansı * (1 + K * şans)
# Kitap ayarları
DEV_BOOK_HP = 250
# infaz: "tek İnfaz almak yetiyor" - eşikler küçüldü, toplam tavan düştü ve
# ağır yaratıklarda yarıya iniyor.
EXECUTE_BOOK = 0.08
EXECUTE_EDGE = 0.05
EXECUTE_SUNDER = 0.03
EXECUTE_MAX = 0.25
EXECUTE_TOUGH_K = 0.5           # ağır yaratıkta eşiğin çarpanı
LASTHOPE_HP_FRAC = 0.40
LASTHOPE_DR = 0.35
LASTHOPE_REGEN = 2.0            # son umut eşiğin altında can/sn


def rarity_weights(luck):
    """Şansa göre beş kademenin ağırlıkları (Efsanevi tavanı uygulanmış)."""
    f = 1.0 + max(0.0, float(luck))
    w = [RARITY_BASE_WEIGHTS[i] * f ** (RARITY_LUCK_EXP * i)
         for i in range(RARITY_COUNT)]
    rest = sum(w[:-1])
    top = rest * RARITY_LEGEND_CAP / (1.0 - RARITY_LEGEND_CAP)
    if w[-1] > top:
        w[-1] = top
    return w


def roll_rarity(luck, rnd=random):
    """Şansa göre bir nadirlik kademesi çeker: 0 (Yaygın) .."""
    return rnd.choices(range(RARITY_COUNT), weights=rarity_weights(luck), k=1)[0]


def rarity_name(tier):
    return L("rar.%d" % clamp(int(tier), 0, RARITY_COUNT - 1))


def rarity_color(tier):
    return RARITY_COLORS[clamp(int(tier), 0, RARITY_COUNT - 1)]


def rarity_boost(tier, source="chest"):
    """Bu kademenin silaha eklediği kalıcı hasar payı."""
    i = clamp(int(tier), 0, RARITY_COUNT - 1)
    return (CARD_RARITY_BONUS if source == "card" else CHEST_RARITY_BONUS)[i]


def rarity_table(luck, n=20000, seed=1):
    """Doğrulama: n çekilişte kademelerin yüzdesi."""
    rnd = random.Random(seed)
    cnt = [0] * RARITY_COUNT
    for _ in range(n):
        cnt[roll_rarity(luck, rnd)] += 1
    return [100.0 * c / n for c in cnt]


def fmt_pct1(v):
    """Oranı bir ondalıklı yüzde yazar: 0.075 -> "%7,5" (tr) / "7.5%"."""
    x = round(float(v) * 100.0, 1)
    t = ("%d" % int(round(x))) if abs(x - round(x)) < 0.05 else ("%.1f" % x)
    if lang() == "tr":
        return "%" + t.replace(".", ",")
    return t + "%"


