# ---- oyuncu gövdesi ----
# Düz renkli bir daireydi. Artık 3 kat büyük çizilip küçültülen (kenarı
# yumuşak) gölgeli bir gövde: üstten ışık, alttan yansıyan kenar ışığı,
# parlak nokta. Renk / boy başına bir kez çizilir.
_PBODY = {}


def _player_body_sprite(r, body, acc, flash=False):
    key = (int(r), tuple(body), tuple(acc), flash)
    spr = _PBODY.get(key)
    if spr is not None:
        return spr
    if len(_PBODY) > 160:
        _PBODY.clear()
    S = 3
    pad = 4
    size = (int(r) + pad) * 2
    big = pygame.Surface((size * S, size * S), pygame.SRCALPHA)
    c = size * S / 2.0
    R = r * S
    pygame.draw.circle(big, OUTLINE, (c, c), R + 2.2 * S)
    if flash:
        pygame.draw.circle(big, WHITE, (c, c), R)
    else:
        rim = mix_col(lighten(body, 0.40), acc, 0.30)
        pygame.draw.circle(big, rim, (c, c), R)
        pygame.draw.circle(big, scale_col(body, 0.80), (c - R * 0.06, c - R * 0.08), R * 0.94)
        for i in range(12):
            k = i / 11.0
            col = mix_col(scale_col(body, 0.88), lighten(body, 0.24), k ** 0.9)
            pygame.draw.circle(big, col, (c - R * 0.18 * k, c - R * 0.24 * k), R * (0.92 - 0.46 * k))
        # parlak nokta
        pygame.draw.ellipse(big, (*lighten(body, 0.70), 225),
                            (c - R * 0.66, c - R * 0.74, R * 0.62, R * 0.36))
        pygame.draw.circle(big, (255, 255, 255, 235), (c - R * 0.46, c - R * 0.56), R * 0.10)
        pygame.draw.circle(big, acc, (c, c), R, int(1.8 * S))
    spr = pygame.transform.smoothscale(big, (size, size))
    _PBODY[key] = spr
    return spr


def _player_feet(surf, p, px, py, r, body, moving):
    """Gövdenin altında iki küçük ayak; yürürken sırayla basar."""
    ph = p.move_anim
    col = scale_col(body, 0.58)
    for s_ in (-1, 1):
        lift = math.sin(ph + (0 if s_ < 0 else math.pi)) * 3.0 if moving else 0.0
        fx = px + s_ * r * 0.50
        fy = py + r * 0.92 - max(0.0, lift)
        rect = pygame.Rect(0, 0, int(r * 0.74), int(r * 0.48))
        rect.center = (int(fx), int(fy))
        pygame.draw.ellipse(surf, OUTLINE, rect.inflate(4, 4))
        pygame.draw.ellipse(surf, col, rect)


# Seviye / mağara penceresi kapanınca kısa dokunulmazlık: oyuncu kalabalığın
# ortasına hazırlıksız dönmesin (2 kişilikte oyun pencerede de akıyor).
MENU_GRACE = 3.0
GRACE_COLOR = (255, 222, 130)
_GRACE_SPR = {}


def draw_grace_bubble(surf, x, y, r, left, t):
    """Dokunulmazlık balonu: altın kalkan + kalan süre yayı; son saniyede yanıp söner."""
    fade = min(1.0, left / 0.4)
    if left < 1.0 and int(t * 10) % 2 == 0:
        fade *= 0.4
    rr = int(r + 13 + 1.5 * math.sin(t * 6))
    spr = _GRACE_SPR.get(rr)
    if spr is None:
        spr = pygame.Surface((rr * 2 + 6, rr * 2 + 6), pygame.SRCALPHA)
        c = rr + 3
        pygame.draw.circle(spr, (*GRACE_COLOR, 34), (c, c), rr)
        pygame.draw.circle(spr, (*GRACE_COLOR, 70), (c, c), rr, 4)
        pygame.draw.circle(spr, (255, 250, 225, 210), (c, c), rr, 2)
        # parlak yansıma (balon hissi)
        pygame.draw.arc(spr, (255, 255, 255, 170), pygame.Rect(c - rr + 5, c - rr + 5, rr * 2 - 10, rr * 2 - 10),
                        math.radians(100), math.radians(160), 2)
        _GRACE_SPR[rr] = spr
    spr.set_alpha(int(255 * fade))
    surf.blit(spr, (int(x - rr - 3), int(y - rr - 3)))
    add_glow(surf, x, y, rr * 1.5, GRACE_COLOR, 0.2 * fade)
    k = clamp(left / MENU_GRACE, 0.0, 1.0)
    if k > 0.01:
        ar = pygame.Rect(0, 0, rr * 2 + 12, rr * 2 + 12)
        ar.center = (int(x), int(y))
        pygame.draw.arc(surf, scale_col(GRACE_COLOR, 0.55 + 0.45 * fade), ar,
                        math.pi / 2, math.pi / 2 + math.tau * k, 3)


