        self.color = self.skin["color"]
        self.cosmetics = {"hat": None, "eyewear": None, "cape": None}
        self.x = ARENA_RECT.centerx
        self.y = ARENA_RECT.centery
        self.radius = 16
        self.vx = self.vy = 0.0
        self.kbx = self.kby = 0.0

        # ---- taban istatistikler (herkes eşit başlar) ----
