def make_map_enemy(theme, kind, x, y, wave_mult, diff_mult=1.0, wave=1):
    """Arena türünü haritanın kendi yaratığı olarak üretir."""
    mv = map_variant(theme, kind)
    if mv:
        return Enemy(None, x, y, wave_mult, diff_mult, wave=wave, variant=mv)
    return Enemy(kind, x, y, wave_mult, diff_mult, wave=wave)

# Cehennem dalgalarında hangi yaratıktan ne sıklıkla geleceği.
def hell_pick_kind(wave):
    w = max(1, int(wave))
    weights = {
        "h_imp": 10,
        "h_hound": 4 + min(w, 9),
        "h_reaver": 6 + min(w, 8),
        "h_seer": max(0, min(w, 7)),
        "h_golem": max(0, min(w - 1, 8)),
        "h_butcher": max(0, min(w - 2, 8)),
    }
    return random.choices(list(weights.keys()), weights=list(weights.values()), k=1)[0]


# Cehennem yaratıkları arenanın 25. dalgası kadar canlı ve vurucu başlar.
HELL_BASE_WAVE = 25
# denge düğmeleri. "cehenneme çok güçlü giriyoruz, cehennemi buffla": 1.10 ->
# 1.25, cehennem yaratıklarına ayrıca %12 hasar.
HELL_HP_BOOST = 1.60        # cehennem canının taban çarpanı
HELL_DMG_BOOST = 1.35       # cehennem yaratık hasarının taban çarpanı
# cehennemin sonu: cehennem 40 dalgadır.
HELL_FINAL_WAVE = None
HELL_SPEED_BASE_WAVE = 12   # cehennem 1. dalgasının hız temposu (8 -> 12)

# ---- cehennem dengesi (herkese eşit) ----
# Güçlü gelen oyuncu ödülünü almalı (rahat ilerlemeli), zayıf gelen ölmeli -
# oyuncuya göre yeniden kurulan bir cehennem bu farkı siler ve sıralamayı "kim
# daha şanslıysa" yarışından çıkarıp herkesi aynı yere getirirdi:
#      hell_hp_mult(1) = 7,85 iken arena_hp_mult(25) = 8,58


# Cehennemde de zırh var ve dalga başına açılıyor:
# 25. dalgadan sonra arena yaratıkları zırhlanırken portaldan geçen oyuncu
HELL_ARMOR_BASE = 0.18          # 0.10 -> 0.13, 0.18
HELL_ARMOR_PER_WAVE = 0.018     # 0.014 -> 0.018 (plato kırıldı)
HELL_ARMOR_MAX = 0.50           # 0.40 -> 0.50

# cehennem baskısı - arena_pressure'ın cehennemdeki karşılığı.
HELL_PRESSURE_FROM = 6          # bu dalgadan sonra devreye girer (12 -> 10, 6)
HELL_PRESSURE_HP = 1.075        # dalga başına can çarpanı
HELL_PRESSURE_DMG = 1.06        # dalga başına hasar çarpanı
HELL_PRESSURE_SPD = 0.03        # dalga başına hız artışı


def hell_pressure(wave):
    """Cehennemin geç dalgalarındaki baskı: (can, hasar, hız)."""
    over = max(0, int(wave) - HELL_PRESSURE_FROM)
    if over <= 0:
        return 1.0, 1.0, 1.0
    doom = 0 if HELL_FINAL_WAVE is None else max(0, int(wave) - HELL_FINAL_WAVE)
    return (HELL_PRESSURE_HP ** over * DOOM_HP ** doom,
            HELL_PRESSURE_DMG ** over * DOOM_DMG ** doom,
            1.0 + HELL_PRESSURE_SPD * over)


def hell_armor(wave):
    """Cehennem yaratığının gelen hasardan kestiği pay (herkes için aynı)."""
    return clamp(HELL_ARMOR_BASE + HELL_ARMOR_PER_WAVE * (max(1, wave) - 1),
                 0.0, HELL_ARMOR_MAX)


def hell_hp_mult(wave):
    """Cehennem dalgasının can çarpanı."""
    w = max(1, int(wave))
    base = arena_hp_mult(HELL_BASE_WAVE) * HELL_HP_BOOST
    curve = 1.0 + (w - 1) * 0.32 + 0.008 * (w - 1) ** 2
    return base * curve


def hell_dmg_wave(wave):
    """Hasar hesabında kullanılan 'sanal' dalga: cehennem 1 = arena 25."""
    return HELL_BASE_WAVE + (max(1, wave) - 1) * 1.0


def hell_speed_wave(wave):
    """Hız hesabında kullanılan 'sanal' dalga."""
    return HELL_SPEED_BASE_WAVE + (max(1, wave) - 1) * 1.5


