# denge düğmesi - altın akışı. Yere düşen her altın bu çarpanla küçülür.
GOLD_GAIN_BUFF = 1.25
COIN_DROP_SCALE = 0.50 * GOLD_GAIN_BUFF
COIN_DROP_SCALE_HELL = 0.70 * GOLD_GAIN_BUFF


# "parayı da %10 kıs" - yere düşen bütün altın x0,90. Elmas bundan etkilenmez:
# gem_coins toplanan altını bu ölçeğe bölerek hesaplıyor.
GOLD_TRIM = 0.90


def coin_drop_scale(biome):
    return (COIN_DROP_SCALE_HELL if biome == "hell" else COIN_DROP_SCALE) * GOLD_TRIM


def scaled_coin_gain(base, mult, biome):
    x = max(0.0, base * mult * coin_drop_scale(biome))
    n = int(x)
    if random.random() < x - n:
        n += 1
    return n


# Zorluk seviyeleri düşman istatistiklerini (can/hasar) değil, yalnızca oyunun
# temposunu değiştirir: aynı skorda aynı dalgaya ulaşılır, aynı xp/altın/ elmas
# kazanılır - tek fark düşmanların ne kadar hızlı geldiği ve dalgaların ne
# kadar hızlı ilerlediğidir.
DIFF_MULT = {"normal": 1.0, "hard": 1.0, "nightmare": 1.0}
DIFF_PACE = {"normal": 0.72, "hard": 1.0, "nightmare": 1.55}

# Düşmanın görünen şekliyle çarpışma kutusu birebir örtüşsün diye, her tür için
# çizilen görselin gerçek kapladığı alana göre bir çarpışma yarıçapı çarpanı.
ENEMY_HITBOX_FACTOR = {
    "red": 1.0, "blue": 0.72, "yellow": 0.8, "tank": 0.95,
    "sprinter": 0.8, "brute": 0.92, "elite": 1.0,
    # cehennem yaratıkları - vuruş alanı görünen gövdeye göre ayarlandı (kanat,
    # kuyruk ve zincir gibi uzantılar isabet alanına girmez).
    "imp": 0.82, "hound": 0.86, "reaver": 0.94, "seer": 0.88,
    "golem": 0.98, "butcher": 0.92, "warden": 0.96,
    # yarı patron ve korumaları
    "herald": 0.94, "shieldman": 0.90,
    "kamikaze": 0.92,
}


def arena_hp_mult(wave):
    """Arena yaratıklarının dalgaya göre can çarpanı."""
    w = max(1, int(wave))
    return 1.0 + (w - 1) * 0.22 + 0.004 * (min(w, 25) - 1) ** 2


def wave_speed_mult(wave):
    """Yeni başlayanlar ilk dalgalarda telaşlanmasın diye düşman hızını kısar"""
    if wave <= 7:
        t = clamp((wave - 1) / 6.0, 0.0, 1.0)
        return lerp(0.66, 0.94, t)
    t = clamp((wave - 7) / 18.0, 0.0, 1.0)
    return lerp(0.94, 1.55, t)


def late_wave_dmg_mult(wave, coef=None):
    """Düşman hasarının dalgaya göre artışı."""
    if wave <= 12:
        return 1.0 + (wave - 1) * 0.055
    base = 1.0 + 11 * 0.055
    extra = ((wave - 12) ** 1.6) * (LATE_DMG_COEF if coef is None else coef)
    return base + extra


# "17. dalgada çok güçlüler":
# 17. dalga hasarı -%6, 20. dalga -%9, 25. dalga -%13. Asıl düzeltme dalga
LATE_DMG_COEF = 0.042
LATE_DMG_COEF_HELL = 0.05


def _minion_hazard(e, player, lead, r, delay, dmg, color):
    """Yaratığın yere bıraktığı işaretli patlama (oyuncunun gittiği yere)."""
    run = ENEMY_HAZARDS[0]
    hz = getattr(run, "hazards", None)
    if hz is None or sum(1 for h in hz if getattr(h, "minion", False)) >= MINION_HAZARD_CAP:
        return False
    mx, my = getattr(player, "move_in", (0.0, 0.0))
    try:
        sp = float(player.eff_speed())
    except Exception:
        sp = BASE_SPEED
    x = clamp(player.x + mx * sp * lead, ARENA_RECT.left + 30, ARENA_RECT.right - 30)
    y = clamp(player.y + my * sp * lead, ARENA_RECT.top + 30, ARENA_RECT.bottom - 30)
    h = Hazard(x, y, r, delay, dmg, color=color)
    h.minion = True
    hz.append(h)
    return True


class Enemy:
    def __init__(self, kind, x, y, wave_mult, diff_mult=1.0, wave=1,
                 variant=None, biome="arena"):
        """Bir yaratık üretir."""
        var = (HELL_ENEMIES.get(variant) or MAP_ENEMIES.get(variant)) if variant else None
        if var:
            kind = var["base"]
        d = ENEMY_DEFS[kind]
        self.kind = kind                 # davranış
        self.variant = variant
        self.hellish = variant in HELL_ENEMIES
        # harita yaratığı: yalnız görünüşü / adı / mermi görseli farklı; bütün
        # sayılar arenadaki türüyle aynı.
        self.map_var = variant in MAP_ENEMIES
        self.shot_style = var.get("shot", "orb") if var else "orb"
        # Çizim biçimi. Yeni arketipler (bombacı/şifacı) kendi gövdelerini
        # çizdirmiyor: kanıtlanmış gövdeleri renk ve davranış farkıyla yeniden
        # kullanıyorlar.
        SHAPE_ALIAS = {"bomber": "brute", "healer": "yellow",
                       "wizard": "yellow", "stinger": "sprinter"}
        self.shape = (var["shape"] if var
                      else SHAPE_ALIAS.get(kind, kind))      # çizim biçimi
        # Ölüm nedeni / arayüz adı.
        self.disp_name = LX("en." + variant, var["name"]) if var else LX("en." + kind, kind)
        self.x, self.y = x, y

        # ---- cehennemde hız 1. dalga temposuna döner, can/hasar 25. dalga seviyesinde ----
        spd_wave = hell_speed_wave(wave) if biome == "hell" else wave
        dmg_wave = hell_dmg_wave(wave) if biome == "hell" else wave
        # ---- 25. dalgadan sonra arena kasten acımasızlaşır (portala zorlar) ----
        if biome == "hell":
            # Cehennemin kendi baskı eğrisi (zırhı hell_armor veriyor).
            hp_p, dmg_p, spd_p = hell_pressure(wave)
            pr_hp, pr_dmg, pr_spd, pr_armor = hp_p, dmg_p * HELL_DMG_BOOST, spd_p, 0.0
        else:
            pr_hp, pr_dmg, pr_spd, pr_armor = arena_pressure(wave)

        hp_var = var.get("hp", 1.0) if var else 1.0
        dmg_var = var.get("dmg", 1.0) if var else 1.0

        self.max_hp = d["hp"] * wave_mult * hp_var * pr_hp * ENEMY_HP_TUNE
        self.hp = self.max_hp
        self.speed = d["speed"] * wave_speed_mult(spd_wave) * pr_spd
        dmg_mult = late_wave_dmg_mult(dmg_wave, LATE_DMG_COEF_HELL if biome == "hell" else None)
        self.dmg = (d["dmg"] * dmg_mult * diff_mult * dmg_var * pr_dmg
                    * ENEMY_DMG_TUNE)
        # Zırh: gelen hasarın sabit bir yüzdesini keser.
        self.armor = hell_armor(wave) if biome == "hell" else pr_armor
        self.radius = d["radius"] * (var.get("radius", 1.0) if var else 1.0)
        self.coin = d["coin"]
        self.xp = d["xp"]
        self.score = d["score"]
        self.contact_dps = (d["contact_dps"] * dmg_mult * diff_mult * dmg_var
                            * pr_dmg * ENEMY_DMG_TUNE)
        # arı: "hızlıca koşsun ama hasarı 3 3 3 3 3 olsun".
        if kind == "stinger":
            self.speed = min(self.speed, BASE_SPEED * STINGER_SPEED_CAP)
            self.dmg = min(self.dmg, d["dmg"] * STINGER_DMG_CAP)
            self.contact_dps = min(self.contact_dps,
                                   d["contact_dps"] * STINGER_DMG_CAP)
        # Kırmızı toplar (temel düşman) ne kadar güçlüyse görsel olarak o kadar
        # doygun/canlı kırmızı olsun - oyuncu tehlikeyi bir bakışta anlasın.
        if self.shape == "red":
            base_dmg = ENEMY_DEFS["red"]["dmg"]
            self.red_intensity = clamp((self.dmg / base_dmg - 1.0) / 3.2, 0.0, 1.0)
        else:
            self.red_intensity = 0.0
        # Çarpışma (hitbox) yarıçapı - görünen şekle göre ayarlanır, gözle
        # görünenden daha büyük bir alanda "hayalet" hasar/isabet olmasın.
        hb_shape = SHAPE_ALIAS.get(kind, kind) if self.map_var else self.shape
        self.hit_r = self.radius * ENEMY_HITBOX_FACTOR.get(hb_shape, 1.0)
        self.color = var["color"] if var else ENEMY_COLORS[kind]
        # kudurma: 25. dalgadan sonra renk kızıla (yarasa / arı mora) kayar;
        # hâle ve közler draw'da, önbelleğin dışında çizilir.
        self.rage = rage_level(wave, biome)
        self.spawn_wave = int(wave) + (HELL_WAVE_OFFSET if biome == "hell" else 0)
        self.rage_col = RAGE_BAT if kind in ("blue", "stinger") else RAGE_FIRE
        if self.rage > 0:
            self.color = mix_col(self.color, self.rage_col, 0.25 + 0.40 * self.rage)
        self.mutant = False             # mutasyon
        self.fuse_t = 0.0               # kamikaze fitili (0 = yanmıyor)
        self.exploded = False
        # ---- yarı patron (sancaktar) ve korumaları (siperci) ----
        # herald: yarı patron. guards listesi onu koruyan siperciler.
        # shieldman: sancaktarın çevresinde dizilen kalkanlı. guard_of,
        # koruduğu:
        #      sancaktarı gösterir; sancaktar ölürse siperciler dağılır.
        self.is_mini = (kind == "herald")
        self.guards = [] if kind == "herald" else None
        self.guard_of = None
        self.guard_slot = 0
        self.guard_angle = random.uniform(0, math.tau)
        # Kalkanın o anki parlaması (hasar emdiğinde yanar)
        self.block_flash = 0.0
        self.alive = True
        self.hit_flash = 0.0
        self.spawn_t = 0.0
        self.shoot_cd = random.uniform(0.6, 1.4)
        self.heal_cd = random.uniform(0.3, 1.0)   # şifacı'nın iyileştirme sayacı
        self.heal_flash = 0.0                     # iyileşen yaratığın parlaması
        self.dash_cd = random.uniform(1.2, 2.4)
        self.dash_t = 0.0
        self.dash_dx = self.dash_dy = 0.0
        self.knock_x = 0.0
        self.knock_y = 0.0
        self.wobble = random.uniform(0, math.tau)
        self.burn_timer = 0.0
        self.burn_dps = 0.0
        self.burn_tick_acc = 0.0
        self.slow_timer = 0.0
        self.slow_mult = 1.0
        self.touch_cd = 0.0
        # zehir: yanıktan farkı süresinin olmaması - bir kez bulaştı mı düşman
        # ölene kadar devam eder ve her yeni vuruşta üst üste birikir.
        self.poison_dps = 0.0
        self.poison_tick_acc = 0.0
        # Yaratık görünümü için: baktığı yön (yumuşatılmış) ve yürüyüş fazı.
        # Gözler ve bacaklar bu ikisine göre çizilir.
        self.face_x, self.face_y = 0.0, 1.0
        self.walk = random.uniform(0, math.tau)
        # kükreme kitabı: korkan düşman bir süre oyuncudan kaçar.
        self.fear_timer = 0.0
        self.fear_vuln = 0.0        # kükreme: korkmuşken aldığı fazla hasar oranı
        # ---- gövde önbelleği ----
        self._spr = None            # son çizilmiş gövde yüzeyi
        self._spr_key = None        # o yüzeyin ait olduğu görünüş anahtarı
        self._spr_fn = 0            # gövdenin en son çizildiği kare
        self._spr_pad = 0           # yüzeyin merkez kaydırması
        self._spr_off = (0, 0)      # yüzeyin sol üst köşesinin merkeze uzaklığı
        self._blink = None          # önbelleğe çizerken sabitlenen göz kırpma
        # ---- lanet yaratıkları ----
        self.split_gen = 0          # bölünen: kaçıncı kuşak (2'de bölünmez)
        self.raised = False         # ölü çağırıcı'nın kaldırdığı iskelet mi
        self.necro_cd = random.uniform(2.0, 3.5)
        self.phased = False         # hayalet: şu an dokunulmaz mı
        self.phase_t = random.uniform(0.8, GHOST_SOLID_T)

    def apply_poison(self, dps):
        self.poison_dps += dps

    def apply_burn(self, dps, duration):
        self.burn_timer = max(self.burn_timer, duration)
        self.burn_dps = max(self.burn_dps, dps)

    def apply_slow(self, mult, duration):
        if self.slow_timer <= 0 or mult < self.slow_mult:
            self.slow_mult = mult
        self.slow_timer = max(self.slow_timer, duration)

    def _kamikaze_blast(self, player, fx):
        """Kamikaze patlar: menzildeki oyuncuya büyük hasar, kendisi yok olur (ödül yok - kill_cb çağrılmaz)."""
        self.alive = False
        self.exploded = True
        col = ENEMY_COLORS["kamikaze"]
        fx.shockwave(self.x, self.y, KAMIKAZE_RADIUS, (255, 170, 80), 0.35, 7)
        fx.ring(self.x, self.y, col, n=26, speed=320, life=0.5, r=4)
        fx.burst(self.x, self.y, (255, 220, 120), n=18, speed=260, life=0.45, r=4)
        fx.shake(7, 0.22)
        sfx("explosion", 0.8, 0.0)
        if player.alive and (dist(self.x, self.y, player.x, player.y)
                             <= KAMIKAZE_RADIUS + player.radius):
            player.take_damage(self.dmg * KAMIKAZE_DMG_MULT, fx, self.x, self.y,
                               src=self.disp_name)

    def update(self, dt, player, fx, projectiles, kill_cb=None, enemies=None):
        if not self.alive:
            return
        self.spawn_t += dt
        if self.kind == "ghost":
            # hayalet: GHOST_SOLID_T görünür, GHOST_PHASE_T dokunulmaz.
            self.phase_t -= dt
            if self.phase_t <= 0:
                self.phased = not self.phased
                self.phase_t = GHOST_PHASE_T if self.phased else GHOST_SOLID_T
                fx.ring(self.x, self.y, ENEMY_COLORS["ghost"], n=8, speed=110, life=0.3, r=2.2)
        self.wobble += dt * 6
        if self.touch_cd > 0:
            self.touch_cd -= dt
        scale_in = ease_out_cubic(self.spawn_t / 0.3)

        speed_mult = 1.0
        if self.slow_timer > 0:
            self.slow_timer -= dt
            speed_mult = self.slow_mult
            if self.slow_timer <= 0:
                self.slow_mult = 1.0

        if self.burn_timer > 0:
            self.burn_timer -= dt
            self.burn_tick_acc += dt
            while self.burn_tick_acc >= 0.5 and self.alive:
                self.burn_tick_acc -= 0.5
                died = self.take_damage(self.burn_dps * 0.5, False, fx)
                if died and kill_cb:
                    kill_cb(self)
            if self.burn_timer <= 0:
                self.burn_dps = 0.0
            if not self.alive:
                return

        # zehir: süresi yok, düşman ölene kadar her yarım saniyede bir vurur.
        if self.poison_dps > 0:
            self.poison_tick_acc += dt
            while self.poison_tick_acc >= 0.5 and self.alive:
                self.poison_tick_acc -= 0.5
                died = self.take_damage(self.poison_dps * 0.5, False, fx)
                if died and kill_cb:
                    kill_cb(self)
            if not self.alive:
                return

        # görünmezlik pelerini: oyuncu görünmezken sıradan yaratıklar onu
        # göremez. Oldukları yerde kalır, ateş etmez, dokunarak hasar vermez.
        if getattr(player, "invis_t", 0.0) > 0:
            if abs(self.knock_x) > 0.5 or abs(self.knock_y) > 0.5:
                self.x += self.knock_x * dt
                self.y += self.knock_y * dt
                self.knock_x *= max(0.0, 1 - dt * 8)
                self.knock_y *= max(0.0, 1 - dt * 8)
                self.x = clamp(self.x, ARENA_RECT.left + self.radius,
                               ARENA_RECT.right - self.radius)
                self.y = clamp(self.y, ARENA_RECT.top + self.radius,
                               ARENA_RECT.bottom - self.radius)
            if self.hit_flash > 0:
                self.hit_flash -= dt
            if self.block_flash > 0:
                self.block_flash = max(0.0, self.block_flash - dt)
            return

        eff_speed = self.speed * speed_mult

        # kamikaze: dibine gelince fitili ateşler, fitil bitince patlar.
        if self.kind == "kamikaze" and player.alive:
            if self.fuse_t > 0:
                self.fuse_t -= dt
                eff_speed *= KAMIKAZE_FUSE_SLOW
                if self.fuse_t <= 0:
                    self._kamikaze_blast(player, fx)
                    return
            elif (self.spawn_t > 0.3 and
                  dist(self.x, self.y, player.x, player.y) < KAMIKAZE_TRIGGER + player.radius):
                self.fuse_t = KAMIKAZE_FUSE
                fx.popup(self.x, self.y - self.radius - 18, "!", (255, 220, 120), 26, life=0.5)
                sfx("warn", 0.6, 0.05)

        # Baktığı yönü oyuncuya doğru yumuşakça çevir + yürüyüş fazını ilerlet.
        if player.alive:
            tfx, tfy = norm_dir(self.x, self.y, player.x, player.y)
            k = min(1.0, dt * 7.0)
            self.face_x += (tfx - self.face_x) * k
            self.face_y += (tfy - self.face_y) * k
            fl = math.hypot(self.face_x, self.face_y)
            if fl > 1e-5:
                self.face_x /= fl
                self.face_y /= fl
        self.walk += dt * (2.0 + eff_speed * 0.030)

        if abs(self.knock_x) > 0.5 or abs(self.knock_y) > 0.5:
            self.x += self.knock_x * dt
            self.y += self.knock_y * dt
            self.knock_x *= max(0.0, 1 - dt * 8)
            self.knock_y *= max(0.0, 1 - dt * 8)
        elif self.dash_t > 0:
            self.dash_t -= dt
            self.x += self.dash_dx * eff_speed * 2.6 * dt
            self.y += self.dash_dy * eff_speed * 2.6 * dt
        elif self.guard_of is not None and self.guard_of.alive:
            # siperci: oyuncuyu kovalamaz.
            g = self.guard_of
            n = max(1, len(g.guards))
            base = math.atan2(player.y - g.y, player.x - g.x)
            spread = min(math.pi * 0.92, 0.62 * (n - 1))
            off = 0.0 if n == 1 else (self.guard_slot / (n - 1.0) - 0.5) * spread
            a = base + off
            ring = g.radius + self.radius + 44
            tx = g.x + math.cos(a) * ring
            ty = g.y + math.sin(a) * ring
            gdx, gdy = norm_dir(self.x, self.y, tx, ty)
            gd = dist(self.x, self.y, tx, ty)
            if gd > 4:
                step = min(gd, eff_speed * 1.55 * dt * scale_in)
                self.x += gdx * step
                self.y += gdy * step
            self.x = clamp(self.x, ARENA_RECT.left + self.radius, ARENA_RECT.right - self.radius)
            self.y = clamp(self.y, ARENA_RECT.top + self.radius, ARENA_RECT.bottom - self.radius)
            if self.block_flash > 0:
                self.block_flash = max(0.0, self.block_flash - dt)
            if self.hit_flash > 0:
                self.hit_flash -= dt
            # Oyuncu sipercinin gövdesine girdiyse dışarı itilir.
            if player.alive:
                pd = dist(self.x, self.y, player.x, player.y)
                need = self.hit_r + player.radius
                if 0.001 < pd < need:
                    pdx, pdy = (player.x - self.x) / pd, (player.y - self.y) / pd
                    player.x = clamp(self.x + pdx * need,
                                     ARENA_RECT.left + player.radius,
                                     ARENA_RECT.right - player.radius)
                    player.y = clamp(self.y + pdy * need,
                                     ARENA_RECT.top + player.radius,
                                     ARENA_RECT.bottom - player.radius)
            return                     # siperci oyuncuya dokunarak hasar vermez
        else:
            dx, dy = norm_dir(self.x, self.y, player.x, player.y)
            if self.fear_timer > 0:
                # korkmuş düşman ters yöne kaçar
                self.fear_timer -= dt
                dx, dy = -dx, -dy
                self.x += dx * eff_speed * 1.15 * dt * scale_in
                self.y += dy * eff_speed * 1.15 * dt * scale_in
                self.x = clamp(self.x, ARENA_RECT.left + self.radius, ARENA_RECT.right - self.radius)
                self.y = clamp(self.y, ARENA_RECT.top + self.radius, ARENA_RECT.bottom - self.radius)
                return
            if self.is_mini:
                # sancaktar oyuncunun üstüne atılmaz. Sandığı taşıyan taraf
                # odur; mesafesini korur ve çevresinde dolanır.
                d = dist(self.x, self.y, player.x, player.y)
                if d < 250:
                    dx, dy = -dx, -dy                 # fazla yaklaştı: geri çekil
                elif d < 340:
                    dx, dy = -dy, dx                  # istenen bantta: çevresinde dolan
                self.x += dx * eff_speed * dt * scale_in
                self.y += dy * eff_speed * dt * scale_in
                self.x = clamp(self.x, ARENA_RECT.left + self.radius, ARENA_RECT.right - self.radius)
                self.y = clamp(self.y, ARENA_RECT.top + self.radius, ARENA_RECT.bottom - self.radius)
                if self.block_flash > 0:
                    self.block_flash = max(0.0, self.block_flash - dt)
                if self.hit_flash > 0:
                    self.hit_flash -= dt
                if player.alive:
                    dd = dist(self.x, self.y, player.x, player.y)
                    if dd < self.hit_r + player.radius - 2 and self.touch_cd <= 0:
                        self.touch_cd = 0.12
                        player.take_damage(self.contact_dps * 0.12 * 6, fx,
                                           self.x, self.y, self.disp_name)
                return
            if self.kind == "wizard":
                # büyücü: oyuncunun üstüne gitmez, uzaktan zehir oku atar. Oku
                # az vurur ama zehri uzun sürer; oyuncu ya üstüne gider ya da
                # sürekli can kaybeder.
                d = dist(self.x, self.y, player.x, player.y)
                if d < WIZARD_KEEP:
                    dx, dy = -dx, -dy
                elif d < WIZARD_KEEP + 110:
                    dx, dy = -dy, dx
                self.shoot_cd -= dt
                if self.shoot_cd <= 0 and self.spawn_t > 0.6:
                    self.shoot_cd = random.uniform(*WIZARD_SHOOT_CD)
                    pdx, pdy = norm_dir(self.x, self.y, player.x, player.y)
                    wcol = self.color if self.map_var else ENEMY_COLORS["wizard"]
                    projectiles.append(EnemyProjectile(
                        self.x, self.y, pdx * WIZARD_SHOT_SPEED,
                        pdy * WIZARD_SHOT_SPEED, self.dmg,
                        color=wcol, r=7,
                        poison=self.dmg * WIZARD_POISON_MULT, style=self.shot_style))
                    fx.ring(self.x, self.y, wcol, n=10,
                            speed=130, life=0.3, r=2.5)
                    sfx("shoot_c", 0.32, 0.08)
            elif self.kind == "goblin":
                # hazine goblini: oyuncudan kaçar, yanlara zikzak çizer; duvara
                # dayanınca duvar boyunca kayar.
                d = dist(self.x, self.y, player.x, player.y)
                zz = math.sin(self.spawn_t * 2.3 + self.wobble)
                if d < 520:
                    dx, dy = -dx + (-dy) * zz * 0.6, -dy + dx * zz * 0.6
                else:
                    dx, dy = -dy * (1 if zz > 0 else -1), dx * (1 if zz > 0 else -1)
                if (self.x < ARENA_RECT.left + 80 or self.x > ARENA_RECT.right - 80):
                    dx *= 0.2
                    dy = dy if abs(dy) > 0.3 else (1.0 if self.y < ARENA_RECT.centery else -1.0)
                if (self.y < ARENA_RECT.top + 80 or self.y > ARENA_RECT.bottom - 80):
                    dy *= 0.2
                    dx = dx if abs(dx) > 0.3 else (1.0 if self.x < ARENA_RECT.centerx else -1.0)
                ln = math.hypot(dx, dy) or 1.0
                dx, dy = dx / ln, dy / ln
            elif self.kind == "necro":
                # ölü çağırıcı: mesafesini korur; dirilttiği iskeletleri
                # RunState.update_cursed yönetir (cesetlerin listesi orada).
                d = dist(self.x, self.y, player.x, player.y)
                if d < NECRO_KEEP:
                    dx, dy = -dx, -dy
                elif d < NECRO_KEEP + 100:
                    dx, dy = -dy, dx
            elif self.kind == "healer":
                # şifacı: oyuncuya hiç saldırmaz, mesafesini korur ve
                # çevresindeki yaratıkları iyileştirir.
                d = dist(self.x, self.y, player.x, player.y)
                if d < HEALER_KEEP:
                    dx, dy = -dx, -dy              # fazla yaklaştı: geri çekil
                elif d < HEALER_KEEP + 90:
                    dx, dy = -dy, dx               # bantta: çevresinde dolan
                self.heal_cd -= dt
                if self.heal_cd <= 0 and self.spawn_t > 0.5 and enemies:
                    self.heal_cd = HEALER_TICK
                    iyilesen = 0
                    for o in enemies:
                        if o is self or not o.alive or o.hp >= o.max_hp:
                            continue
                        if dist(self.x, self.y, o.x, o.y) > HEALER_RADIUS:
                            continue
                        o.hp = min(o.max_hp, o.hp + o.max_hp * HEALER_FRAC)
                        o.heal_flash = 0.25
                        iyilesen += 1
                        if iyilesen >= HEALER_MAX_TARGETS:
                            break
                    if iyilesen:
                        fx.ring(self.x, self.y, ENEMY_COLORS["healer"], n=12,
                                speed=120, life=0.35, r=2.5)
            elif self.kind == "yellow":
                d = dist(self.x, self.y, player.x, player.y)
                if d < 230:
                    dx, dy = -dx, -dy
                elif d < 280:
                    dx, dy = 0, 0
                self.shoot_cd -= dt
                if self.shoot_cd <= 0 and self.spawn_t > 0.4:
                    self.shoot_cd = random.uniform(1.5, 2.3)
                    pdx, pdy = norm_dir(self.x, self.y, player.x, player.y)
                    self.shots_n = getattr(self, "shots_n", 0) + 1
                    if (self.shots_n % 4 == 0 and getattr(self, "spawn_wave", 1) >= MORTAR_FROM
                            and _minion_hazard(self, player, 0.9, 56, 1.0,
                                               self.dmg * 1.8 + player.max_hp * 0.05, (255, 150, 70))):
                        sfx("shoot_d", 0.35, 0.1)
                    elif self.map_var:
                        projectiles.append(EnemyProjectile(
                            self.x, self.y, pdx * 230, pdy * 230, self.dmg * 0.85,
                            color=MAP_SHOT_COLORS.get(self.shot_style, (235, 210, 70)),
                            style=self.shot_style))
                    else:
                        projectiles.append(EnemyProjectile(self.x, self.y, pdx * 230, pdy * 230,
                                                           self.dmg * 0.85))
                    sfx("shoot_c", 0.3, 0.08)
            elif self.kind == "sprinter":
                self.dash_cd -= dt
                if self.dash_cd <= 0 and self.spawn_t > 0.3:
                    self.dash_cd = random.uniform(1.6, 2.6)
                    self.dash_t = 0.22
                    self.dash_dx, self.dash_dy = dx, dy
            # elit: yere vuruş. Düşeceği yer gittiğin yöne göre önceden belli.
            if (self.kind == "elite" and getattr(self, "spawn_wave", 1) >= ELITE_SLAM_FROM
                    and self.spawn_t > 1.0 and player.alive):
                self.slam_cd = getattr(self, "slam_cd", random.uniform(2.0, 4.0)) - dt
                if self.slam_cd <= 0 and dist(self.x, self.y, player.x, player.y) < 360:
                    self.slam_cd = random.uniform(4.5, 6.5)
                    if _minion_hazard(self, player, 0.35, 78, 0.85,
                                      max(self.dmg * 2.4, player.max_hp * 0.14), (255, 196, 120)):
                        fx.ring(self.x, self.y, (255, 196, 120), n=10, speed=120, life=0.3, r=2.6)
            # düz ve öngörülebilir bir hareket - gereksiz sallanma/titreme
            # olmasın
            self.x += dx * eff_speed * dt * scale_in
            self.y += dy * eff_speed * dt * scale_in

        self.x = clamp(self.x, ARENA_RECT.left + self.radius, ARENA_RECT.right - self.radius)
        self.y = clamp(self.y, ARENA_RECT.top + self.radius, ARENA_RECT.bottom - self.radius)

        if self.hit_flash > 0:
            self.hit_flash -= dt
        if self.heal_flash > 0:
            self.heal_flash -= dt

        if player.alive and self.contact_dps > 0:
            d = dist(self.x, self.y, player.x, player.y)
            if d < self.hit_r + player.radius - 2 and self.touch_cd <= 0:
                self.touch_cd = 0.12
                # zaman kitabı: yavaşlatılmış yaratık hem geç geliyor hem de
                # daha zayıf vuruyor.
                tmp = self.contact_dps * 0.12 * 6
                if self.slow_timer > 0 and player.dash_slow_level > 0:
                    tmp *= (1.0 - min(0.50, 0.30 + 0.05 * player.dash_slow_level))
                dealt = player.take_damage(tmp, fx, self.x, self.y, self.disp_name)
                if dealt > 0 and player.thorns_level > 0:
                    reflect = dealt * 0.35 * player.thorns_level
                    died = self.take_damage(reflect, False, fx)
                    if died and kill_cb:
                        kill_cb(self)

    # Sancaktara giden hasarın siperciler yaşarken oyuncuya kalan kesri.
    HERALD_LEAK = 0.12

    def live_guards(self):
        """Sancaktarı hâlâ koruyan sipercilerin sayısı."""
        if not self.guards:
            return 0
        return sum(1 for g in self.guards if g.alive)

    def take_damage(self, amount, crit, fx, kx=0.0, ky=0.0, quiet=False):
        # hayalet: dokunulmazken hiçbir şey işlemez.
        if self.phased:
            return False
        # sancaktar: siperciler ayaktayken gelen hasarın neredeyse tamamı
        # kalkanlarda emilir.
        if self.is_mini:
            n = self.live_guards()
            if n > 0:
                soaked = amount * (1.0 - self.HERALD_LEAK)
                amount *= self.HERALD_LEAK
                self.block_flash = 0.22
                # Emilen hasar rastgele bir sipercinin kalkanında parlar.
                alive_g = [g for g in self.guards if g.alive]
                if alive_g:
                    gg = random.choice(alive_g)
                    gg.block_flash = 0.22
                    if not quiet and soaked > 0:
                        fx.popup(gg.x, gg.y - gg.radius - 6, "EMİLDİ",
                                 (150, 200, 250), 13, life=0.45)
        # kükreme kitabı: korkmuş yaratık arkasını dönüp kaçtığı için
        # savunmasızdır, daha ağır hasar alır. Korkutmanın ölçülebilir bir
        # karşılığı var.
        if self.fear_timer > 0 and self.fear_vuln > 0:
            amount *= (1.0 + self.fear_vuln)
        if EVO_ON:
            amount *= evo_mark_mult(self)
        # 25. dalgadan sonraki arena yaratıklarının zırhı gelen hasarı keser.
        if self.armor > 0:
            amount *= (1.0 - self.armor)
        if self.alive:
            dmg_note(min(amount, max(0.0, self.hp)))
        self.hp -= amount
        if DMG_SRC[0] in EVO_ON:
            evo_on_hit(self, amount, fx)
        self.hit_flash = 0.14
        self.knock_x += kx
        self.knock_y += ky
        # quiet=True: alan hasarı (su / ateş / pentagram / kitap). Bu alanlar
        # saniyede birkaç kez vurduğu için hasar sayısı basmaz - yoksa ekran
        # okunmaz hâle geliyor. Geri bildirim yaratığın beyaz parlamasıdır.
        col = (255, 230, 120) if crit else WHITE
        if not quiet:
            fx.popup(self.x, self.y - self.radius - 4, f"{int(amount)}" + ("!" if crit else ""),
                     col, 22 if crit else 15, life=0.5)
        if crit:
            sfx("crit", 0.7, 0.03)
        if self.hp <= 0 and self.alive:
            self.alive = False
            fx.burst(self.x, self.y, self.color, n=14, speed=170, life=0.5, r=3.5)
            sfx("kill", 0.5, 0.02)
            return True
        return False

    def _eyes(self, surf, x, y, r, fx_, fy_, n=2, spread=0.42, fwd=0.44,
              sz=0.20, eye_col=(255, 255, 255), pupil=(18, 16, 26), glow_col=None, t=0.0):
        """Yaratığın gözlerini baktığı yöne göre çizer."""
        sx_, sy_ = -fy_, fx_
        # Göz kırpma değeri gövde önbelleğinin anahtarına da giriyor; o yüzden
        # tek bir yerden hesaplanıyor.
        blink = self._blink if self._blink is not None else self._blink_at(t)
        for i in range(n):
            off = 0.0 if n == 1 else (i - (n - 1) / 2.0) * spread * 2.0
            ex = x + fx_ * r * fwd + sx_ * r * off
            ey = y + fy_ * r * fwd + sy_ * r * off
            er = max(1.5, r * sz)
            if glow_col:
                add_glow(surf, ex, ey, er * 3.2, glow_col, .45)
            pygame.draw.circle(surf, OUTLINE, (int(ex), int(ey)), int(er + 1))
            pygame.draw.ellipse(surf, eye_col,
                                (int(ex - er), int(ey - er * blink), int(er * 2), max(1, int(er * 2 * blink))))
            if blink > 0.5:
                px_ = ex + fx_ * er * 0.34
                py_ = ey + fy_ * er * 0.34
                pygame.draw.circle(surf, pupil, (int(px_), int(py_)), max(1, int(er * 0.52)))

    def _legs(self, surf, x, y, r, fx_, fy_, col, pairs=2, length=0.55, width=3, spread=0.62):
        """Yürüyüşle birlikte ileri geri sallanan bacaklar."""
        sx_, sy_ = -fy_, fx_
        for i in range(pairs):
            for s in (-1, 1):
                ph = self.walk + i * 1.7 + (0 if s > 0 else math.pi)
                swing = math.sin(ph) * r * 0.30
                bx = x - fx_ * r * (0.10 + i * 0.34) + sx_ * r * spread * s
                by = y - fy_ * r * (0.10 + i * 0.34) + sy_ * r * spread * s
                tx = bx + sx_ * r * 0.34 * s + fx_ * swing
                ty = by + sy_ * r * 0.34 * s + fy_ * swing
                pygame.draw.line(surf, OUTLINE, (bx, by), (tx, ty), width + 2)
                pygame.draw.line(surf, col, (bx, by), (tx, ty), width)

    # ---- cehennem yaratık çizimleri ----
    # Cehennem yaratıkları arena yaratıklarının boynuz takılmış kopyası değil:
    # her birinin kendi silueti var.

    def _hmap(self, x, y, r):
        fx_, fy_ = self.face_x, self.face_y
        l = math.hypot(fx_, fy_) or 1.0
        fx_, fy_ = fx_ / l, fy_ / l
        sx_, sy_ = -fy_, fx_

        def P(f, s):
            return (x + fx_ * r * f + sx_ * r * s, y + fy_ * r * f + sy_ * r * s)
        return P, fx_, fy_, sx_, sy_

    def _hpoly(self, surf, pts, col, x, y, grow=0.10, width=0):
        if grow > 0:
            pygame.draw.polygon(surf, OUTLINE,
                                [(px + (px - x) * grow, py + (py - y) * grow) for px, py in pts])
        pygame.draw.polygon(surf, col, pts, width)

    def _horns(self, surf, P, r, col=(232, 220, 204), base_f=-0.30, spread=0.52,
               reach=0.46, curl=0.26):
        """İki boynuz - cehennem yaratıklarının ortak imzası."""
        for sgn in (-1, 1):
            b0 = P(base_f, spread * sgn)
            b1 = P(base_f - reach * 0.55, (spread + curl) * sgn)
            b2 = P(base_f - reach, (spread + curl * 0.25) * sgn)
            pygame.draw.lines(surf, OUTLINE, False, [b0, b1, b2], max(4, int(r * 0.22)))
            pygame.draw.lines(surf, col, False, [b0, b1, b2], max(3, int(r * 0.14)))

    def _ember_trail(self, surf, x, y, r, t, n=3, col=(255, 180, 80)):
        for i in range(n):
            ph = (t * 1.1 + i * (1.0 / n) + self.wobble * 0.2) % 1.0
            ex = x + math.sin(t * 2.4 + i * 2.1 + self.wobble) * r * 0.8
            ey = y - r * 0.4 - ph * r * 1.9
            blit_disc(surf, ex, ey, max(1.0, 3.0 * (1.0 - ph)), col, int(210 * (1.0 - ph)))

    # harita yaratıkları - Buzul Vadisi / Zümrüt Orman / Kızıl Çöl.
    # Davranışları arena türlerinden (MAP_ENEMIES "base"); çizimleri kendi.
    def _spike(self, surf, base, tip, half, col, sx_, sy_):
        pts = [(base[0] - sx_ * half, base[1] - sy_ * half), tip,
               (base[0] + sx_ * half, base[1] + sy_ * half)]
        pygame.draw.polygon(surf, OUTLINE, pts, 3)
        pygame.draw.polygon(surf, col, pts)

    def _limb(self, surf, a, b, w, col):
        pygame.draw.line(surf, OUTLINE, a, b, max(3, int(w + 2)))
        pygame.draw.line(surf, col, a, b, max(2, int(w)))

    # ---- buzul ----
    def _draw_f_beetle(self, surf, x, y, r, col, t, breathe):
        """buz böceği: ortadan ayrık buz kabuk, kristal sırtlar, kıskaçlı baş."""
        P, fx_, fy_, sx_, sy_ = self._hmap(x, y, r)
        dark = scale_col(col, 0.55)
        self._legs(surf, x, y, r, fx_, fy_, scale_col(col, 0.45), pairs=3, length=0.62, width=3)
        bite = 0.5 + 0.5 * math.sin(self.walk * 1.8)
        for sgn in (-1, 1):
            claw = [P(0.80, 0.16 * sgn), P(1.22, (0.34 + 0.12 * bite) * sgn),
                    P(1.38, (0.10 + 0.08 * bite) * sgn), P(1.06, 0.06 * sgn)]
            self._hpoly(surf, claw, (214, 238, 255), x, y, grow=0.06)
        hx, hy = P(0.80, 0.0)
        circle_aa(surf, hx, hy, r * 0.34 + 2, OUTLINE)
        circle_aa(surf, hx, hy, r * 0.34, (44, 70, 110))
        k = breathe
        shell = [P(0.66 * k, 0.0), P(0.45 * k, 0.80 * k), P(-0.35 * k, 0.92 * k), P(-0.95 * k, 0.45 * k),
                 P(-1.05 * k, 0.0), P(-0.95 * k, -0.45 * k), P(-0.35 * k, -0.92 * k), P(0.45 * k, -0.80 * k)]
        self._hpoly(surf, shell, col, x, y, grow=0.08)
        pygame.draw.line(surf, dark, P(0.58, 0.0), P(-1.0, 0.0), 2)
        for sgn in (-1, 1):
            for i in range(3):
                f = 0.22 - i * 0.42
                tri = [P(f + 0.18, 0.30 * sgn), P(f - 0.05, 0.64 * sgn), P(f - 0.22, 0.28 * sgn)]
                pygame.draw.polygon(surf, (236, 248, 255), tri)
                pygame.draw.polygon(surf, scale_col(col, 0.7), tri, 1)
        circle_aa(surf, *P(0.05, -0.42), max(1.5, r * 0.10), WHITE)
        self._eyes(surf, hx, hy, r * 0.6, fx_, fy_, n=2, spread=0.36, fwd=0.40, sz=0.20,
                   eye_col=(200, 240, 255), glow_col=(150, 220, 255), t=t)

    def _draw_f_bat(self, surf, x, y, r, col, t, breathe):
        """ayaz yarasası: buz sarkıtı uçlu kanatlar; kırağı perisi daha parlak."""
        P, fx_, fy_, sx_, sy_ = self._hmap(x, y, r)
        flap = math.sin(self.walk * 2.6 + t * 6.0)
        wing_col = mix_col(col, (40, 70, 130), 0.45)
        for sgn in (-1, 1):
            span = 1.40 + flap * 0.30
            wing = [P(0.05, 0.30 * sgn), P(0.35, span * 0.75 * sgn), P(-0.05, span * sgn),
                    P(-0.45, span * 0.82 * sgn), P(-0.70, 0.40 * sgn)]
            self._hpoly(surf, wing, wing_col, x, y, grow=0.05)
            pygame.draw.polygon(surf, lighten(col, 0.3), wing, 1)
            for f, s in ((-0.05, span), (-0.45, span * 0.82)):
                bx, by = P(f, s * sgn)
                tip = (bx - fx_ * r * 0.38, by - fy_ * r * 0.38)
                pygame.draw.polygon(surf, (230, 246, 255),
                                    [(bx - sx_ * 2, by - sy_ * 2), tip, (bx + sx_ * 2, by + sy_ * 2)])
        pr = r * 0.62 * breathe
        circle_aa(surf, x, y, pr + 2, OUTLINE)
        circle_aa(surf, x, y, pr, col)
        for sgn in (-1, 1):
            self._hpoly(surf, [P(0.30, 0.18 * sgn), P(0.86, 0.42 * sgn), P(0.40, 0.46 * sgn)], col, x, y, grow=0.05)
        if self.kind == "stinger":
            add_glow(surf, x, y, r * 1.6, (200, 236, 255), 0.30)
        self._eyes(surf, x, y, pr, fx_, fy_, n=2, spread=0.30, fwd=0.40, sz=0.24,
                   eye_col=(210, 245, 255), glow_col=(140, 210, 255), t=t)

    def _draw_f_wisp(self, surf, x, y, r, col, t, breathe):
        """kar ruhu: süzülen kar küresi, kar kuyruğu, yörüngede buz kırıkları."""
        y -= math.sin(t * 2.4 + self.wobble) * r * 0.12
        P, fx_, fy_, sx_, sy_ = self._hmap(x, y, r)
        add_glow(surf, x, y, r * 1.75, col, 0.30)
        for i in range(6):
            k = i / 5.0
            px_, py_ = P(-0.40 - k * 1.25, math.sin(t * 3 + i * 0.9) * 0.25 * k)
            circle_aa(surf, px_, py_, max(1.0, r * (0.55 - 0.40 * k)), mix_col(col, WHITE, 0.3 + 0.5 * k))
        pr = r * 0.80 * breathe
        circle_aa(surf, x, y, pr + 2, OUTLINE)
        circle_aa(surf, x, y, pr, col)
        circle_aa(surf, x - pr * 0.25, y - pr * 0.25, pr * 0.42, lighten(col, 0.5))
        for i in range(6):
            a = t * 1.2 + i * math.pi / 3
            pygame.draw.line(surf, WHITE, (x, y), (x + math.cos(a) * pr * 0.55, y + math.sin(a) * pr * 0.55), 2)
        for i in range(3):
            a = -t * 2.0 + i * math.tau / 3 + self.wobble
            ox, oy = x + math.cos(a) * r * 1.30, y + math.sin(a) * r * 1.0
            ca, sa = math.cos(a), math.sin(a)
            sh = [(ox + ca * r * 0.30, oy + sa * r * 0.30), (ox - sa * r * 0.10, oy + ca * r * 0.10),
                  (ox - ca * r * 0.30, oy - sa * r * 0.30), (ox + sa * r * 0.10, oy - ca * r * 0.10)]
            pygame.draw.polygon(surf, (225, 245, 255), sh)
            pygame.draw.polygon(surf, scale_col(col, 0.6), sh, 1)
        if self.kind == "wizard":
            for k in (-1, 0, 1):
                self._spike(surf, P(-0.55, k * 0.32), P(-1.05 - (0.14 if k == 0 else 0.0), k * 0.44),
                            3, (220, 240, 255), sx_, sy_)
        elif self.kind == "healer":
            add_glow(surf, x, y, r * 1.5, (120, 255, 180), 0.35)
        self._eyes(surf, x, y, pr, fx_, fy_, n=2, spread=0.28, fwd=0.30, sz=0.17,
                   eye_col=(40, 70, 120), pupil=(220, 240, 255), t=t)

    def _draw_f_golem(self, surf, x, y, r, col, t, breathe):
        """buz golemi: çok yüzlü kristal gövde, blok kollar, parlayan çekirdek."""
        P, fx_, fy_, sx_, sy_ = self._hmap(x, y, r)
        sway = math.sin(self.walk * 1.1) * 0.12
        dark = scale_col(col, 0.6)
        for sgn in (-1, 1):
            o = sway * sgn
            arm = [P(0.35 + o, 0.85 * sgn), P(0.55 + o, 1.25 * sgn), P(0.05 + o, 1.38 * sgn), P(-0.25 + o, 1.0 * sgn)]
            self._hpoly(surf, arm, dark, x, y, grow=0.06)
            pygame.draw.polygon(surf, lighten(col, 0.35), arm, 2)
        k = breathe
        body = [P(0.85 * k, 0.0), P(0.45 * k, 0.80 * k), P(-0.40 * k, 0.95 * k), P(-0.95 * k, 0.35 * k),
                P(-0.90 * k, -0.45 * k), P(-0.25 * k, -0.95 * k), P(0.55 * k, -0.78 * k)]
        self._hpoly(surf, body, col, x, y, grow=0.07)
        cx_, cy_ = P(-0.05, 0.0)
        for i, pt in enumerate(body):
            pygame.draw.line(surf, lighten(col, 0.45) if i % 2 else dark, (cx_, cy_), pt, 1)
        pulse = 0.5 + 0.5 * math.sin(t * 3 + self.wobble)
        add_glow(surf, cx_, cy_, r * (0.9 + 0.3 * pulse), (120, 200, 255), 0.45)
        circle_aa(surf, cx_, cy_, r * 0.26, (190, 236, 255))
        circle_aa(surf, cx_, cy_, r * 0.13, WHITE)
        self._eyes(surf, x, y, r, fx_, fy_, n=2, spread=0.25, fwd=0.55, sz=0.12,
                   eye_col=(170, 230, 255), glow_col=(120, 200, 255), t=t)

    def _beast(self, surf, x, y, r, col, t, breathe, back_col, ear_col, ears="point", tail_w=0.42,
               tail_col=None, snout=1.35, eye_col=(255, 220, 90), muzzle=None):
        """Dört ayaklı koşucu iskeleti (kurt / çakal / panter): kalın bacaklar ve patiler, oval gövde"""
        P, fx_, fy_, sx_, sy_ = self._hmap(x, y, r)
        dark = scale_col(col, 0.62)
        for f, ph in ((0.40, 0.0), (-0.44, math.pi)):
            for sgn in (-1, 1):
                sw = math.sin(self.walk * 2.2 + ph + (0.0 if sgn > 0 else math.pi)) * 0.26
                a, b = P(f, 0.24 * sgn), P(f + sw, 0.64 * sgn)
                self._limb(surf, a, b, max(3, r * 0.24), dark)
                circle_aa(surf, b[0], b[1], max(2.0, r * 0.15), OUTLINE)
                circle_aa(surf, b[0], b[1], max(1.5, r * 0.11), scale_col(col, 0.86))
        run = math.sin(self.walk * 2.2)
        tail = [P(-0.78, 0.0), P(-1.18, run * 0.22), P(-1.58, run * 0.40)]
        pygame.draw.lines(surf, OUTLINE, False, tail, max(4, int(r * (tail_w + 0.14))))
        pygame.draw.lines(surf, tail_col or col, False, tail, max(2, int(r * tail_w)))
        body = [P(0.62, 0.0), P(0.50, 0.36), P(0.10, 0.47), P(-0.45, 0.44), P(-0.85, 0.22), P(-0.92, 0.0),
                P(-0.85, -0.22), P(-0.45, -0.44), P(0.10, -0.47), P(0.50, -0.36)]
        self._hpoly(surf, body, col, x, y, grow=0.07)
        pygame.draw.polygon(surf, back_col, [P(0.32, 0.0), P(0.10, 0.19), P(-0.55, 0.19), P(-0.80, 0.0),
                                             P(-0.55, -0.19), P(0.10, -0.19)])
        for sgn in (-1, 1):
            if ears == "round":
                ex, ey = P(0.66, 0.30 * sgn)
                circle_aa(surf, ex, ey, r * 0.17, OUTLINE)
                circle_aa(surf, ex, ey, r * 0.13, ear_col)
            else:
                big = 1.5 if ears == "big" else 1.0
                ear = [P(0.76, 0.12 * sgn), P(0.50 - 0.12 * (big - 1), (0.42 + 0.22 * (big - 1)) * sgn),
                       P(0.84, 0.32 * sgn)]
                self._hpoly(surf, ear, ear_col, x, y, grow=0.06)
        head = [P(snout, 0.0), P(snout - 0.20, 0.17), P(0.98, 0.31), P(0.66, 0.30), P(0.56, 0.0),
                P(0.66, -0.30), P(0.98, -0.31), P(snout - 0.20, -0.17)]
        self._hpoly(surf, head, col, x, y, grow=0.06)
        if muzzle:
            pygame.draw.polygon(surf, muzzle, [P(snout - 0.04, 0.0), P(1.0, 0.14), P(1.0, -0.14)])
        circle_aa(surf, *P(snout - 0.03, 0.0), max(1.5, r * 0.09), OUTLINE)
        hx, hy = P(0.84, 0.0)
        self._eyes(surf, hx, hy, r * 0.7, fx_, fy_, n=2, spread=0.30, fwd=0.14, sz=0.16,
                   eye_col=eye_col, glow_col=eye_col, t=t)
        return P

    def _draw_f_wolf(self, surf, x, y, r, col, t, breathe):
        """kar kurdu: buz mavisi sırt, açık namlu, kabarık beyaz kuyruk ucu."""
        P = self._beast(surf, x, y, r, col, t, breathe, mix_col(col, (150, 175, 210), 0.45),
                        scale_col(col, 0.65), eye_col=(150, 220, 255), muzzle=WHITE)
        circle_aa(surf, *P(-1.56, math.sin(self.walk * 2.2) * 0.40), r * 0.20, WHITE)

    def _draw_f_yeti(self, surf, x, y, r, col, t, breathe):
        """yeti: kabarık kürk, öne uzanan iri kollar, mavi yüz."""
        P, fx_, fy_, sx_, sy_ = self._hmap(x, y, r)
        swing = math.sin(self.walk * 1.3)
        pr = r * breathe
        circle_aa(surf, x, y, pr + 2, OUTLINE)
        circle_aa(surf, x, y, pr, col)
        for i in range(12):
            a = i * math.tau / 12 + self.wobble
            circle_aa(surf, x + math.cos(a) * pr * 0.90, y + math.sin(a) * pr * 0.90, pr * 0.22,
                      lighten(col, 0.15) if i % 2 else scale_col(col, 0.92))
        if self.kind == "elite":
            add_glow(surf, *P(-0.7, 0.0), r * 0.9, (170, 220, 255), 0.35)
            for k in (-2, -1, 0, 1, 2):
                self._spike(surf, P(-0.55, k * 0.22), P(-1.02 - (0.18 if k == 0 else 0.0), k * 0.30),
                            3.5, (210, 236, 255), sx_, sy_)
        for sgn in (-1, 1):
            hand = P(0.70 + 0.16 * swing * sgn, 0.92 * sgn)
            self._limb(surf, P(0.0, 0.78 * sgn), hand, max(5, r * 0.40), lighten(col, 0.08))
            circle_aa(surf, hand[0], hand[1], r * 0.27, OUTLINE)
            circle_aa(surf, hand[0], hand[1], r * 0.21, (120, 140, 180))
        fxp, fyp = P(0.40, 0.0)
        circle_aa(surf, fxp, fyp, pr * 0.46, (110, 150, 200))
        mo = 0.5 + 0.5 * math.sin(self.walk * 1.6)
        self._hpoly(surf, [P(0.60, -0.20), P(0.78, 0.0), P(0.60, 0.20), P(0.53 + 0.08 * mo, 0.0)],
                    (40, 30, 60), x, y, grow=0.0)
        for k in (-1, 1):
            pygame.draw.line(surf, WHITE, P(0.60, k * 0.12), P(0.72, k * 0.08), 2)
        self._eyes(surf, x, y, pr, fx_, fy_, n=2, spread=0.20, fwd=0.34, sz=0.12, t=t)

    def _draw_f_snowball(self, surf, x, y, r, col, t, breathe):
        """kartopu: yuvarlanan kar topu, kömür gözler, havuç burun."""
        P, fx_, fy_, sx_, sy_ = self._hmap(x, y, r)
        roll = self.walk * 0.9
        pr = r * 0.95 * breathe
        add_glow(surf, x, y, r * 1.6, (180, 220, 255), 0.18 + 0.12 * math.sin(t * 6 + self.wobble))
        for k in (-1, 1):
            self._spike(surf, P(-0.75, 0.25 * k), P(-1.28, 0.45 * k), 3, (190, 225, 255), sx_, sy_)
        circle_aa(surf, x, y, pr + 2, OUTLINE)
        circle_aa(surf, x, y, pr, col)
        for i in range(7):
            a = roll + i * 0.9
            d_ = pr * (0.25 + 0.55 * ((i * 37) % 10) / 10.0)
            circle_aa(surf, x + math.cos(a) * d_, y + math.sin(a) * d_ * 0.8, pr * 0.12, (206, 222, 240))
        circle_aa(surf, x - pr * 0.3, y - pr * 0.35, pr * 0.26, WHITE)
        self._eyes(surf, x, y, pr, fx_, fy_, n=2, spread=0.26, fwd=0.38, sz=0.13,
                   eye_col=(30, 30, 40), pupil=(30, 30, 40), t=t)
        nb, nt = P(0.62, 0.0), P(1.08, 0.0)
        pygame.draw.polygon(surf, (255, 140, 50),
                            [(nb[0] - sx_ * 4, nb[1] - sy_ * 4), nt, (nb[0] + sx_ * 4, nb[1] + sy_ * 4)])

    # ---- orman ----
    def _draw_j_snake(self, surf, x, y, r, col, t, breathe):
        """Yılan: kıvrılarak süzülen pullu gövde, çatal dil."""
        fx_, fy_ = self.face_x, self.face_y
        l = math.hypot(fx_, fy_) or 1.0
        fx_, fy_ = fx_ / l, fy_ / l
        sx_, sy_ = -fy_, fx_
        dark = scale_col(col, 0.58)
        lite = lighten(col, 0.34)
        n = 7
        pts = []
        for i in range(n):
            k = i / (n - 1)
            back = r * (0.25 + 1.58 * k)
            wig = math.sin(self.walk * 1.4 - k * 4.2) * r * 0.55 * k
            pts.append((x - fx_ * back + sx_ * wig, y - fy_ * back + sy_ * wig, r * (0.62 - 0.38 * k)))
        for (px_, py_, rr_) in reversed(pts):
            pygame.draw.circle(surf, OUTLINE, (int(px_), int(py_)), int(rr_ + 2))
        for i, (px_, py_, rr_) in enumerate(reversed(pts)):
            pygame.draw.circle(surf, col if i % 2 else dark, (int(px_), int(py_)), int(rr_))
            pygame.draw.circle(surf, lite, (int(px_ - rr_ * 0.3), int(py_ - rr_ * 0.3)), max(1, int(rr_ * 0.3)))
        hx_, hy_ = x + fx_ * r * 0.35, y + fy_ * r * 0.35
        head = [(hx_ + fx_ * r * 0.75, hy_ + fy_ * r * 0.75), (hx_ + sx_ * r * 0.55, hy_ + sy_ * r * 0.55),
                (hx_ - fx_ * r * 0.45, hy_ - fy_ * r * 0.45), (hx_ - sx_ * r * 0.55, hy_ - sy_ * r * 0.55)]
        pygame.draw.polygon(surf, OUTLINE, [(a, b + 1) for a, b in head])
        pygame.draw.polygon(surf, col, head)
        if int(t * 3 + self.wobble) % 2 == 0:
            tx_, ty_ = hx_ + fx_ * r * 0.75, hy_ + fy_ * r * 0.75
            tip_x, tip_y = tx_ + fx_ * r * 0.50, ty_ + fy_ * r * 0.50
            pygame.draw.line(surf, (220, 50, 70), (tx_, ty_), (tip_x, tip_y), 2)
            for s_ in (-1, 1):
                pygame.draw.line(surf, (220, 50, 70), (tip_x, tip_y),
                                 (tip_x + fx_ * r * 0.2 + sx_ * r * 0.18 * s_,
                                  tip_y + fy_ * r * 0.2 + sy_ * r * 0.18 * s_), 2)
        self._eyes(surf, hx_, hy_, r * 0.8, fx_, fy_, n=2, spread=0.42, fwd=0.35, sz=0.16,
                   eye_col=(255, 230, 90), t=t)

    def _draw_j_fly(self, surf, x, y, r, col, t, breathe):
        """Ateşböceği (parlayan karın) / eşek arısı (çizgili, iğneli)."""
        P, fx_, fy_, sx_, sy_ = self._hmap(x, y, r)
        wasp = self.kind == "stinger"
        buzz = math.sin(t * 40 + self.wobble)
        for sgn in (-1, 1):
            for f in (0.15, -0.20):
                span = 1.05 + 0.15 * buzz
                wing = [P(f, 0.20 * sgn), P(f + 0.35, span * sgn), P(f - 0.30, (span - 0.10) * sgn)]
                pygame.draw.polygon(surf, (226, 240, 246), wing)
                pygame.draw.polygon(surf, (140, 160, 172), wing, 1)
        if not wasp:
            add_glow(surf, *P(-0.62, 0.0), r * (1.05 + 0.25 * math.sin(t * 5 + self.wobble)), (230, 255, 120), 0.55)
        abd = [P(-0.10, 0.0), P(-0.40, 0.42), P(-1.05, 0.30), P(-1.25, 0.0), P(-1.05, -0.30), P(-0.40, -0.42)]
        self._hpoly(surf, abd, col if wasp else (250, 248, 160), x, y, grow=0.07)
        if wasp:
            for f in (-0.45, -0.75, -1.0):
                pygame.draw.line(surf, OUTLINE, P(f, -0.36), P(f, 0.36), 3)
            pygame.draw.polygon(surf, OUTLINE, [P(-1.18, 0.10), P(-1.62, 0.0), P(-1.18, -0.10)])
        circle_aa(surf, x, y, r * 0.42 + 2, OUTLINE)
        circle_aa(surf, x, y, r * 0.42, col if wasp else scale_col(col, 0.62))
        hx, hy = P(0.50, 0.0)
        circle_aa(surf, hx, hy, r * 0.34 + 2, OUTLINE)
        circle_aa(surf, hx, hy, r * 0.34, (40, 40, 40) if wasp else (74, 64, 40))
        for sgn in (-1, 1):
            pygame.draw.line(surf, OUTLINE, P(0.72, 0.12 * sgn), P(1.10, 0.40 * sgn), 2)
        self._eyes(surf, hx, hy, r * 0.5, fx_, fy_, n=2, spread=0.45, fwd=0.25, sz=0.30,
                   eye_col=(255, 120, 60) if wasp else (255, 240, 120), t=t)

    def _draw_j_frog(self, surf, x, y, r, col, t, breathe):
        """Zehir kurbağası: benekli gövde, iri gözler, şişen gırtlak."""
        y -= abs(math.sin(self.walk * 1.3)) * r * 0.18
        P, fx_, fy_, sx_, sy_ = self._hmap(x, y, r)
        dark = scale_col(col, 0.55)
        for sgn in (-1, 1):
            self._hpoly(surf, [P(-0.35, 0.55 * sgn), P(-0.15, 1.05 * sgn), P(-0.75, 1.05 * sgn),
                               P(-0.85, 0.60 * sgn)], dark, x, y, grow=0.05)
            self._limb(surf, P(0.45, 0.55 * sgn), P(0.75, 0.88 * sgn), max(2, r * 0.14), dark)
        k = breathe
        body = [P(0.85 * k, 0.0), P(0.55 * k, 0.75 * k), P(-0.45 * k, 0.85 * k), P(-0.85 * k, 0.30 * k),
                P(-0.85 * k, -0.30 * k), P(-0.45 * k, -0.85 * k), P(0.55 * k, -0.75 * k)]
        self._hpoly(surf, body, col, x, y, grow=0.07)
        for (f, s) in ((-0.30, 0.35), (0.05, -0.40), (-0.55, -0.20), (0.20, 0.45)):
            circle_aa(surf, *P(f, s), r * 0.13, (30, 30, 50))
        charge = clamp(1.0 - float(getattr(self, "shoot_cd", 2.0)), 0.0, 1.0)
        circle_aa(surf, *P(0.72, 0.0), r * (0.18 + 0.20 * charge), lighten(col, 0.45))
        for sgn in (-1, 1):
            ex, ey = P(0.40, 0.42 * sgn)
            circle_aa(surf, ex, ey, r * 0.27, OUTLINE)
            circle_aa(surf, ex, ey, r * 0.22, (255, 220, 60))
            circle_aa(surf, ex + fx_ * r * 0.06, ey + fy_ * r * 0.06, r * 0.10, (20, 20, 20))
        if self.kind == "wizard":
            self._hpoly(surf, [P(-0.05, 0.0), P(-0.45, 0.55), P(-1.25, 0.0), P(-0.45, -0.55)],
                        (60, 150, 60), x, y, grow=0.05)
            pygame.draw.line(surf, (30, 90, 30), P(-0.05, 0.0), P(-1.2, 0.0), 2)
        elif self.kind == "healer":
            fxp, fyp = P(-0.35, 0.0)
            for i in range(5):
                a = i * math.tau / 5 + t
                circle_aa(surf, fxp + math.cos(a) * r * 0.20, fyp + math.sin(a) * r * 0.20, r * 0.14, (255, 190, 220))
            circle_aa(surf, fxp, fyp, r * 0.11, (255, 230, 90))

    def _draw_j_treant(self, surf, x, y, r, col, t, breathe):
        """Ağaç adam: kabuklu gövde, dal kollar, yaprak taç, kovuktan bakan gözler."""
        P, fx_, fy_, sx_, sy_ = self._hmap(x, y, r)
        sway = math.sin(self.walk * 1.0) * 0.10
        dark = scale_col(col, 0.6)
        for sgn in (-1, 1):
            a, b, c = P(0.10, 0.70 * sgn), P(0.55 + sway * sgn, 1.22 * sgn), P(0.85 + sway * sgn, 1.08 * sgn)
            pygame.draw.lines(surf, OUTLINE, False, [a, b, c], max(6, int(r * 0.32)))
            pygame.draw.lines(surf, col, False, [a, b, c], max(4, int(r * 0.22)))
            for kk in (0.0, 0.4):
                circle_aa(surf, *P(0.62 + sway * sgn + kk * 0.3, (1.30 - kk * 0.1) * sgn), r * 0.17, (90, 170, 70))
        pr = r * breathe
        circle_aa(surf, x, y, pr + 2, OUTLINE)
        circle_aa(surf, x, y, pr, col)
        box = (x - pr * 0.7, y - pr * 0.7, pr * 1.4, pr * 1.4)
        for i in range(5):
            a = i * math.tau / 5 + 0.4
            pygame.draw.arc(surf, dark, box, a, a + 0.9, 2)
        for i in range(7):
            a = i * math.tau / 7 + self.wobble
            circle_aa(surf, *P(-0.55 + math.cos(a) * 0.42, math.sin(a) * 0.62), r * 0.34,
                      (70, 150, 60) if i % 2 else (96, 176, 70))
        circle_aa(surf, *P(-0.5, 0.0), r * 0.32, (112, 192, 82))
        hx, hy = P(0.45, 0.0)
        circle_aa(surf, hx, hy, r * 0.32, (40, 26, 18))
        self._eyes(surf, hx, hy, r * 0.6, fx_, fy_, n=2, spread=0.32, fwd=0.05, sz=0.20,
                   eye_col=(255, 220, 90), glow_col=(255, 200, 80), t=t)

    def _draw_j_panther(self, surf, x, y, r, col, t, breathe):
        """panter: kara, ince gövde, yuvarlak kulaklar, uzun kuyruk, sarı gözler."""
        P = self._beast(surf, x, y, r, col, t, breathe, lighten(col, 0.12), scale_col(col, 0.8),
                        ears="round", tail_w=0.24, snout=1.24, eye_col=(255, 214, 60))
        for (f, s) in ((0.1, 0.30), (-0.3, -0.30), (-0.55, 0.28), (0.25, -0.30)):
            pygame.draw.circle(surf, scale_col(col, 0.7), [int(v) for v in P(f, s)], max(1, int(r * 0.08)), 1)

    def _draw_j_gorilla(self, surf, x, y, r, col, t, breathe):
        """goril: kambur yuvarlak sırt, öne uzanan kalın kollar ve yumruklar; gümüş sırt'ın sırtı gümüş."""
        P, fx_, fy_, sx_, sy_ = self._hmap(x, y, r)
        step = math.sin(self.walk * 1.4)
        k = breathe
        body = [P(0.50 * k, 0.0), P(0.34 * k, 0.74 * k), P(-0.30 * k, 0.90 * k), P(-0.82 * k, 0.56 * k),
                P(-0.98 * k, 0.0), P(-0.82 * k, -0.56 * k), P(-0.30 * k, -0.90 * k), P(0.34 * k, -0.74 * k)]
        self._hpoly(surf, body, col, x, y, grow=0.07)
        back = (198, 200, 212) if self.kind == "elite" else lighten(col, 0.14)
        pygame.draw.polygon(surf, back, [P(0.10, 0.0), P(-0.10, 0.36), P(-0.70, 0.34), P(-0.84, 0.0),
                                         P(-0.70, -0.34), P(-0.10, -0.36)])
        for sgn in (-1, 1):
            hand = P(0.78 + 0.16 * step * sgn, 0.92 * sgn)
            self._limb(surf, P(0.10, 0.70 * sgn), hand, max(5, r * 0.38), scale_col(col, 0.9))
            circle_aa(surf, hand[0], hand[1], r * 0.27, OUTLINE)
            circle_aa(surf, hand[0], hand[1], r * 0.21, scale_col(col, 0.68))
        hx, hy = P(0.56, 0.0)
        circle_aa(surf, hx, hy, r * 0.42 + 2, OUTLINE)
        circle_aa(surf, hx, hy, r * 0.42, scale_col(col, 0.82))
        circle_aa(surf, *P(0.76, 0.0), r * 0.26, (150, 128, 126))
        pygame.draw.line(surf, OUTLINE, P(0.64, -0.24), P(0.64, 0.24), max(2, int(r * 0.08)))
        for sgn in (-1, 1):
            circle_aa(surf, *P(0.88, 0.07 * sgn), max(1.0, r * 0.04), OUTLINE)
        self._eyes(surf, hx, hy, r * 0.6, fx_, fy_, n=2, spread=0.36, fwd=0.22, sz=0.17,
                   eye_col=(255, 200, 120), t=t)

    def _draw_j_shroom(self, surf, x, y, r, col, t, breathe):
        """Patlak mantar: beyaz benekli kırmızı şapka, yükselen sporlar."""
        P, fx_, fy_, sx_, sy_ = self._hmap(x, y, r)
        throb = 1.0 + 0.06 * math.sin(t * 7 + self.wobble)
        for sgn in (-1, 1):
            self._limb(surf, P(-0.2, 0.35 * sgn), P(-0.2 + 0.25 * math.sin(self.walk * 2 + sgn), 0.75 * sgn),
                       max(2, r * 0.16), (236, 226, 200))
        pr = r * 0.98 * breathe * throb
        add_glow(surf, x, y, r * 1.6, col, 0.15 + 0.10 * math.sin(t * 7 + self.wobble))
        circle_aa(surf, x, y, pr + 2, OUTLINE)
        circle_aa(surf, x, y, pr, col)
        circle_aa(surf, x - pr * 0.25, y - pr * 0.30, pr * 0.40, lighten(col, 0.25))
        for i, (f, s, rr) in enumerate(((0.35, 0.40, 0.17), (-0.25, -0.45, 0.20), (-0.45, 0.30, 0.14),
                                        (0.10, -0.10, 0.12), (0.45, -0.35, 0.12))):
            circle_aa(surf, *P(f, s), r * rr, (250, 246, 236))
        for i in range(4):
            ph = (t * 0.6 + i * 0.25 + self.wobble * 0.1) % 1.0
            circle_aa(surf, x + math.sin(t * 2 + i * 1.7) * r * 0.8, y - r * 0.4 - ph * r * 1.2,
                      max(1.0, r * 0.12 * (1.0 - ph)), (230, 210, 170))
        self._eyes(surf, x, y, pr, fx_, fy_, n=2, spread=0.24, fwd=0.55, sz=0.13,
                   eye_col=(255, 250, 230), t=t)

    # ---- çöl ----
    def _draw_d_scorpion(self, surf, x, y, r, col, t, breathe):
        """akrep: segmentli gövde, açılıp kapanan iki kıskaç, iğneli kuyruk."""
        P, fx_, fy_, sx_, sy_ = self._hmap(x, y, r)
        dark = scale_col(col, 0.58)
        self._legs(surf, x, y, r, fx_, fy_, dark, pairs=4, length=0.60, width=2, spread=0.55)
        snap = 0.5 + 0.5 * math.sin(self.walk * 1.7)
        for sgn in (-1, 1):
            sh, el, wr = P(0.35, 0.30 * sgn), P(0.56, 0.66 * sgn), P(0.98, 0.60 * sgn)
            self._limb(surf, sh, el, max(2, r * 0.15), col)
            self._limb(surf, el, wr, max(2, r * 0.17), col)
            # C biçimli kıskaç: dış ve iç parmağın arasındaki ağız açılıp
            # kapanır
            o, i_ = 0.66 + 0.07 * snap, 0.42 - 0.07 * snap
            claw = [P(0.92, 0.44 * sgn), P(0.98, 0.80 * sgn), P(1.36, 0.86 * sgn), P(1.62, o * sgn),
                    P(1.34, 0.66 * sgn), P(1.20, 0.58 * sgn), P(1.36, 0.50 * sgn), P(1.56, i_ * sgn),
                    P(1.24, 0.36 * sgn)]
            self._hpoly(surf, claw, col, x, y, grow=0.05)
            pygame.draw.line(surf, lighten(col, 0.28), P(1.02, 0.70 * sgn), P(1.30, 0.76 * sgn), 2)
        segs = []
        for i in range(5):
            kk = i / 4.0
            sway = math.sin(t * 2.5 + self.wobble - kk * 2) * 0.25 * kk
            segs.append(P(-0.65 - 0.30 * i + 0.15 * kk * kk * 4, sway))
        for i, (sx0, sy0) in enumerate(segs):
            circle_aa(surf, sx0, sy0, r * (0.30 - 0.03 * i) + 2, OUTLINE)
            circle_aa(surf, sx0, sy0, r * (0.30 - 0.03 * i), col if i % 2 else dark)
        tip = segs[-1]
        sting = (tip[0] + fx_ * r * 0.45, tip[1] + fy_ * r * 0.45)
        pygame.draw.polygon(surf, OUTLINE, [(tip[0] - sx_ * 4, tip[1] - sy_ * 4), sting, (tip[0] + sx_ * 4, tip[1] + sy_ * 4)])
        pygame.draw.polygon(surf, (60, 30, 20), [(tip[0] - sx_ * 3, tip[1] - sy_ * 3), sting, (tip[0] + sx_ * 3, tip[1] + sy_ * 3)])
        k = breathe
        body = [P(0.60 * k, 0.0), P(0.30, 0.55 * k), P(-0.50, 0.50 * k), P(-0.75, 0.0), P(-0.50, -0.50 * k), P(0.30, -0.55 * k)]
        self._hpoly(surf, body, col, x, y, grow=0.07)
        for f in (0.15, -0.15, -0.45):
            pygame.draw.line(surf, dark, P(f, -0.45), P(f, 0.45), 2)
        self._eyes(surf, x, y, r, fx_, fy_, n=2, spread=0.16, fwd=0.48, sz=0.11,
                   eye_col=(30, 20, 20), pupil=(255, 90, 60), t=t)

    def _draw_d_vulture(self, surf, x, y, r, col, t, breathe):
        """akbaba: geniş tüylü kanatlar, beyaz yaka, kel pembe baş, kanca gaga."""
        P, fx_, fy_, sx_, sy_ = self._hmap(x, y, r)
        flap = math.sin(self.walk * 2.0 + t * 3.0)
        dark = scale_col(col, 0.6)
        for sgn in (-1, 1):
            span = 1.45 + 0.20 * flap
            wing = [P(0.20, 0.30 * sgn), P(0.25, span * 0.70 * sgn), P(-0.10, span * sgn),
                    P(-0.55, span * 0.80 * sgn), P(-0.60, 0.35 * sgn)]
            self._hpoly(surf, wing, col, x, y, grow=0.04)
            for i in range(4):
                f = 0.05 - i * 0.18
                a = P(f, (span - 0.25) * 0.90 * sgn)
                b = P(f - 0.18, (span + 0.05 - i * 0.05) * sgn)
                pygame.draw.line(surf, dark, a, b, 3)
        tail = [P(-0.55, 0.25), P(-1.15, 0.30), P(-1.15, -0.30), P(-0.55, -0.25)]
        self._hpoly(surf, tail, dark, x, y, grow=0.05)
        pr = r * 0.62 * breathe
        circle_aa(surf, x, y, pr + 2, OUTLINE)
        circle_aa(surf, x, y, pr, col)
        circle_aa(surf, *P(0.35, 0.0), r * 0.36, (238, 232, 220))
        hx, hy = P(0.75, 0.0)
        circle_aa(surf, hx, hy, r * 0.26 + 2, OUTLINE)
        circle_aa(surf, hx, hy, r * 0.26, (232, 150, 150))
        beak = [P(0.90, -0.10), P(1.25, 0.0), P(1.08, 0.10), P(0.90, 0.10)]
        self._hpoly(surf, beak, (236, 210, 120), x, y, grow=0.05)
        self._eyes(surf, hx, hy, r * 0.45, fx_, fy_, n=2, spread=0.42, fwd=0.20, sz=0.22,
                   eye_col=(255, 220, 90), t=t)

    def _draw_d_archer(self, surf, x, y, r, col, t, breathe):
        """kum okçusu: sarıklı, peçeli çöl okçusu; sırtında sadak, atıştan önce yayı gerer."""
        P, fx_, fy_, sx_, sy_ = self._hmap(x, y, r)
        cloth = col
        dark = scale_col(cloth, 0.62)
        flow = math.sin(t * 3 + self.wobble)
        scarf = [P(-0.30, 0.10), P(-0.80, 0.30 + 0.10 * flow), P(-1.20, 0.18 + 0.20 * flow),
                 P(-1.05, 0.02 + 0.12 * flow), P(-0.55, -0.05)]
        self._hpoly(surf, scarf, lighten(cloth, 0.18), x, y, grow=0.05)
        if self.kind == "yellow":
            q0, q1 = P(-0.10, -0.42), P(-0.85, -0.70)
            self._limb(surf, q0, q1, max(4, r * 0.26), (122, 78, 42))
            for kq in range(3):
                bx, by = P(-0.12 + kq * 0.05, -0.30 - kq * 0.10)
                tip = (bx + fx_ * r * 0.28, by + fy_ * r * 0.28)
                pygame.draw.line(surf, (230, 226, 214), (bx, by), tip, 2)
        body = [P(0.30, 0.0), P(0.22, 0.66), P(-0.12, 0.86), P(-0.52, 0.64), P(-0.66, 0.0),
                P(-0.52, -0.64), P(-0.12, -0.86), P(0.22, -0.66)]
        body = [(x + (px - x) * breathe, y + (py - y) * breathe) for px, py in body]
        self._hpoly(surf, body, dark, x, y, grow=0.06)
        hx, hy = P(0.04, 0.0)
        pr = r * 0.50
        circle_aa(surf, hx, hy, pr + 2, OUTLINE)
        circle_aa(surf, hx, hy, pr, lighten(cloth, 0.10))
        for kk in (0.62, 0.38):
            pygame.draw.circle(surf, dark, (int(hx), int(hy)), int(pr * kk), 2)
        veil = [P(0.28, -0.40), P(0.60, 0.0), P(0.28, 0.40), P(0.40, 0.0)]
        pygame.draw.polygon(surf, (60, 46, 40), veil)
        self._eyes(surf, hx, hy, pr, fx_, fy_, n=2, spread=0.32, fwd=0.62, sz=0.15,
                   eye_col=(255, 236, 200), t=t)
        if self.kind == "yellow":
            pull = clamp(1.0 - float(getattr(self, "shoot_cd", 2.0)) / 1.2, 0.0, 1.0)
            c0 = P(0.95, 0.0)
            box = pygame.Rect(0, 0, int(r * 1.5), int(r * 1.5))
            box.center = (int(c0[0] - fx_ * r * 0.35), int(c0[1] - fy_ * r * 0.35))
            ang = math.atan2(-fy_, fx_)
            pygame.draw.arc(surf, OUTLINE, box, ang - 1.05, ang + 1.05, 5)
            pygame.draw.arc(surf, (150, 100, 50), box, ang - 1.05, ang + 1.05, 3)
            e1, e2 = P(0.90, 0.62), P(0.90, -0.62)
            mid = P(0.62 - 0.30 * pull, 0.0)
            pygame.draw.lines(surf, (230, 220, 200), False, [e1, mid, e2], 1)
            pygame.draw.line(surf, (120, 80, 40), mid, P(1.35, 0.0), 2)
            self._spike(surf, P(1.30, 0.0), P(1.50, 0.0), 3, (200, 200, 210), sx_, sy_)
        else:
            orb = (110, 240, 170) if self.kind == "healer" else (210, 120, 255)
            top = P(0.80, 0.70)
            self._limb(surf, P(-0.30, 0.75), top, max(2, r * 0.12), (130, 90, 50))
            add_glow(surf, top[0], top[1], r * 0.6, orb, 0.5)
            circle_aa(surf, top[0], top[1], r * 0.20, orb)

    def _draw_d_mummy(self, surf, x, y, r, col, t, breathe):
        """mumya: sargılı gövde, öne uzanan sargılı kollar, sargının arasından parlayan tek yeşil göz"""
        P, fx_, fy_, sx_, sy_ = self._hmap(x, y, r)
        reach = math.sin(self.walk * 1.2) * 0.08
        dark = scale_col(col, 0.72)
        trail = [P(-0.75, 0.30), P(-1.25, 0.45 + 0.15 * math.sin(t * 3 + self.wobble)),
                 P(-1.70, 0.30 + 0.25 * math.sin(t * 3 + self.wobble + 1))]
        pygame.draw.lines(surf, OUTLINE, False, trail, 6)
        pygame.draw.lines(surf, col, False, trail, 4)
        pr = r * 0.92 * breathe
        circle_aa(surf, x, y, pr + 2, OUTLINE)
        circle_aa(surf, x, y, pr, col)
        for i in range(-3, 4):
            f = i * 0.24
            off = 0.06 * ((i * 7) % 3 - 1)
            pygame.draw.line(surf, dark, P(f + off, -0.86), P(f - off, 0.86), 2)
        for sgn in (-1, 1):
            a, b = P(0.30, 0.55 * sgn), P(1.30 + reach * sgn, 0.50 * sgn)
            self._limb(surf, a, b, max(4, r * 0.26), col)
            for kk in (0.35, 0.65):
                m = (a[0] + (b[0] - a[0]) * kk, a[1] + (b[1] - a[1]) * kk)
                pygame.draw.line(surf, dark, (m[0] - sx_ * r * 0.12, m[1] - sy_ * r * 0.12),
                                 (m[0] + sx_ * r * 0.12 + fx_ * 3, m[1] + sy_ * r * 0.12 + fy_ * 3), 2)
            circle_aa(surf, b[0], b[1], r * 0.16 + 2, OUTLINE)
            circle_aa(surf, b[0], b[1], r * 0.16, lighten(col, 0.1))
        ex, ey = P(0.55, 0.22)
        add_glow(surf, ex, ey, r * 0.6, (120, 255, 140), 0.6)
        circle_aa(surf, ex, ey, r * 0.13, (170, 255, 170))
        circle_aa(surf, *P(0.55, -0.22), r * 0.08, (60, 50, 40))

    def _draw_d_jackal(self, surf, x, y, r, col, t, breathe):
        """Çakal: kum rengi, koyu sırt, kocaman kulaklar, krem namlu."""
        self._beast(surf, x, y, r, col, t, breathe, scale_col(col, 0.62), scale_col(col, 0.75),
                    ears="big", tail_w=0.30, eye_col=(255, 200, 80), muzzle=(240, 220, 180))

    def _draw_d_bandit(self, surf, x, y, r, col, t, breathe):
        """Çöl haydudu: geniş omuzlar, çapraz kuşak, beyaz sarık, pala. firavun muhafızı"""
        P, fx_, fy_, sx_, sy_ = self._hmap(x, y, r)
        guard = self.kind == "elite"
        skin = (196, 150, 110)
        swing = math.sin(self.walk * 1.5)
        k = breathe
        body = [P(0.36 * k, 0.0), P(0.26 * k, 0.80 * k), P(-0.18 * k, 0.96 * k), P(-0.62 * k, 0.70 * k),
                P(-0.76 * k, 0.0), P(-0.62 * k, -0.70 * k), P(-0.18 * k, -0.96 * k), P(0.26 * k, -0.80 * k)]
        self._hpoly(surf, body, col, x, y, grow=0.07)
        sash = (60, 90, 200) if guard else (236, 196, 72)
        pygame.draw.line(surf, OUTLINE, P(0.24, -0.74), P(-0.46, 0.72), max(5, int(r * 0.20)))
        pygame.draw.line(surf, sash, P(0.24, -0.74), P(-0.46, 0.72), max(3, int(r * 0.13)))
        hands = []
        for sgn in (-1, 1):
            hand = P(0.62 + 0.14 * swing * sgn, 0.92 * sgn)
            self._limb(surf, P(0.05, 0.80 * sgn), hand, max(4, r * 0.26), scale_col(col, 0.85))
            circle_aa(surf, hand[0], hand[1], r * 0.17 + 2, OUTLINE)
            circle_aa(surf, hand[0], hand[1], r * 0.17, skin)
            hands.append(hand)
        if guard:
            self._limb(surf, P(-0.45, 0.92), P(1.20, 0.92), max(2, r * 0.09), (130, 90, 50))
            self._spike(surf, P(1.15, 0.92), P(1.52, 0.92), 4, (220, 220, 230), sx_, sy_)
        else:
            h = hands[1]
            blade = [h, (h[0] + fx_ * r * 0.55 + sx_ * r * 0.05, h[1] + fy_ * r * 0.55 + sy_ * r * 0.05),
                     (h[0] + fx_ * r * 0.85 + sx_ * r * 0.28, h[1] + fy_ * r * 0.85 + sy_ * r * 0.28),
                     (h[0] + fx_ * r * 0.55 + sx_ * r * 0.20, h[1] + fy_ * r * 0.55 + sy_ * r * 0.20)]
            self._hpoly(surf, blade, (226, 230, 240), x, y, grow=0.04)
        hx, hy = P(0.20, 0.0)
        pr = r * 0.46
        if guard:
            for sgn in (-1, 1):
                for i in range(3):
                    stripe = [P(0.30 - i * 0.05, (0.26 + i * 0.12) * sgn), P(-0.50 - i * 0.08, (0.50 + i * 0.10) * sgn),
                              P(-0.50 - i * 0.08, (0.58 + i * 0.10) * sgn), P(0.30 - i * 0.05, (0.34 + i * 0.12) * sgn)]
                    pygame.draw.polygon(surf, GOLD if i % 2 == 0 else (60, 90, 200), stripe)
            circle_aa(surf, hx, hy, pr + 2, OUTLINE)
            circle_aa(surf, hx, hy, pr, GOLD)
            for i in range(3):
                pygame.draw.line(surf, (60, 90, 200), P(0.20 - 0.14 * (i - 1) - 0.25, -0.30),
                                 P(0.20 - 0.14 * (i - 1) - 0.25, 0.30), 2)
            add_glow(surf, hx, hy, r * 0.8, GOLD, 0.3)
            circle_aa(surf, *P(0.58, 0.0), max(2.0, r * 0.08), (200, 40, 40))
        else:
            circle_aa(surf, hx, hy, pr + 2, OUTLINE)
            circle_aa(surf, hx, hy, pr, (236, 230, 216))
            for kk in (0.70, 0.45):
                pygame.draw.circle(surf, (196, 186, 166), (int(hx), int(hy)), int(pr * kk), 2)
            circle_aa(surf, *P(0.50, 0.0), pr * 0.40, skin)
        self._eyes(surf, hx, hy, pr, fx_, fy_, n=2, spread=0.30, fwd=0.70, sz=0.16, t=t)

    def _draw_d_cactus(self, surf, x, y, r, col, t, breathe):
        """Patlak kaktüs: dikenli yuvarlak gövde, iki kol, tepede pembe çiçek."""
        P, fx_, fy_, sx_, sy_ = self._hmap(x, y, r)
        throb = 1.0 + 0.05 * math.sin(t * 7 + self.wobble)
        dark = scale_col(col, 0.62)
        for sgn in (-1, 1):
            ax, ay = P(-0.05, 1.0 * sgn)
            circle_aa(surf, ax, ay, r * 0.36 + 2, OUTLINE)
            circle_aa(surf, ax, ay, r * 0.36, col)
            bx, by = P(0.30, 1.15 * sgn)
            circle_aa(surf, bx, by, r * 0.24 + 2, OUTLINE)
            circle_aa(surf, bx, by, r * 0.24, col)
        pr = r * 0.95 * breathe * throb
        add_glow(surf, x, y, r * 1.5, (255, 140, 120), 0.10 + 0.10 * math.sin(t * 7 + self.wobble))
        circle_aa(surf, x, y, pr + 2, OUTLINE)
        circle_aa(surf, x, y, pr, col)
        for i in range(8):
            a = i * math.tau / 8 + self.wobble * 0.2
            pygame.draw.line(surf, dark, (x, y), (x + math.cos(a) * pr * 0.92, y + math.sin(a) * pr * 0.92), 2)
        for i in range(16):
            a = i * math.tau / 16 + 0.2
            p0 = (x + math.cos(a) * pr * 0.96, y + math.sin(a) * pr * 0.96)
            p1 = (x + math.cos(a) * pr * 1.22, y + math.sin(a) * pr * 1.22)
            pygame.draw.line(surf, (250, 240, 200), p0, p1, 1)
        fxp, fyp = P(-0.20, 0.0)
        for i in range(5):
            a = i * math.tau / 5 + t * 0.5
            circle_aa(surf, fxp + math.cos(a) * r * 0.20, fyp + math.sin(a) * r * 0.20, r * 0.15, (255, 120, 180))
        circle_aa(surf, fxp, fyp, r * 0.12, (255, 230, 90))
        self._eyes(surf, x, y, pr, fx_, fy_, n=2, spread=0.24, fwd=0.50, sz=0.12, t=t)

    # ---- imp: küçük, zıplayan, yarasa kanatlı şeytancık ----
    def _draw_imp(self, surf, x, y, r, col, t, breathe):
        P, fx_, fy_, sx_, sy_ = self._hmap(x, y, r)
        dark = scale_col(col, 0.58)
        hop = abs(math.sin(self.walk * 1.4)) * r * 0.22
        y -= hop
        P, fx_, fy_, sx_, sy_ = self._hmap(x, y, r)
        # kanatlar (çırpar)
        flap = 0.60 + 0.35 * math.sin(t * 14 + self.wobble)
        wing_col = mix_col(col, (70, 24, 34), 0.55)
        for sgn in (-1, 1):
            wing = [P(-0.05, 0.40 * sgn), P(0.42, (1.45 * flap + 0.36) * sgn),
                    P(-0.34, (1.95 * flap + 0.40) * sgn),
                    P(-0.70, (1.15 * flap + 0.32) * sgn), P(-0.60, 0.42 * sgn)]
            self._hpoly(surf, wing, wing_col, x, y, grow=0.05)
            pygame.draw.polygon(surf, lighten(col, 0.25), wing, 2)
            # kanat parmakları
            for f in (wing[1], wing[2], wing[3]):
                pygame.draw.line(surf, lighten(wing_col, 0.35), wing[0], f, 2)
        # çatal kuyruk
        tail = [P(-0.80, 0.0), P(-1.30, math.sin(t * 4 + self.wobble) * 0.40),
                P(-1.62, math.sin(t * 4 + self.wobble) * 0.62)]
        pygame.draw.lines(surf, OUTLINE, False, tail, max(4, int(r * 0.20)))
        pygame.draw.lines(surf, col, False, tail, max(2, int(r * 0.12)))
        self._hpoly(surf, [(tail[-1][0] + fx_ * r * 0.02, tail[-1][1] + fy_ * r * 0.02),
                           P(-1.95, 0.42), P(-1.95, 0.86)], (255, 120, 60), x, y, grow=0.0)
        # gövde
        pr = r * breathe
        pygame.draw.circle(surf, OUTLINE, (int(x), int(y)), int(pr + 2))
        pygame.draw.circle(surf, col, (int(x), int(y)), int(pr))
        pygame.draw.circle(surf, lighten(col, 0.28),
                           [int(v) for v in P(-0.22, -0.22)], max(2, int(pr * 0.34)))
        self._horns(surf, P, r, base_f=0.10, spread=0.42, reach=0.62, curl=0.28)
        # sırıtan ağız
        mo = 0.5 + 0.5 * math.sin(self.walk * 1.8)
        self._hpoly(surf, [P(0.60, -0.30), P(0.94, 0.0), P(0.60, 0.30),
                           P(0.44 + 0.12 * mo, 0.0)], (46, 14, 18), x, y, grow=0.0)
        for k in (-1, 0, 1):
            pygame.draw.line(surf, (255, 246, 226), P(0.62, k * 0.16), P(0.82, k * 0.10), 2)
        self._eyes(surf, x, y, pr, fx_, fy_, n=2, spread=0.26, fwd=0.32, sz=0.19,
                   eye_col=(255, 238, 190), glow_col=(255, 140, 60), t=t)
        self._ember_trail(surf, x, y, r, t, 2)

    def _draw_goblin(self, surf, x, y, r, col, t, breathe):
        """Hazine goblini: sırtında altın dolu çuval, sivri kulaklar, sırıtış."""
        P, fx_, fy_, sx_, sy_ = self._hmap(x, y, r)
        hop = abs(math.sin(self.walk * 1.6)) * r * 0.25
        y -= hop
        P, fx_, fy_, sx_, sy_ = self._hmap(x, y, r)
        # çuval (arkada)
        bx, by = P(-0.75, 0.0)
        circle_aa(surf, bx, by - r * 0.2, r * 0.92, OUTLINE)
        circle_aa(surf, bx, by - r * 0.2, r * 0.84, (150, 112, 64))
        circle_aa(surf, bx - r * 0.25, by - r * 0.45, r * 0.30, (186, 146, 90))
        pygame.draw.line(surf, (96, 70, 40), P(-0.30, -0.6), P(-0.30, 0.6), 2)
        for i in range(3):
            ph = (t * 1.2 + i * 0.33) % 1.0
            circle_aa(surf, bx + math.sin(t * 4 + i) * r * 0.3, by - r * (0.9 + ph * 1.3),
                      max(1.0, r * 0.13 * (1 - ph)), GOLD)
        add_glow(surf, bx, by - r * 0.3, r * 1.4, GOLD, 0.25)
        # gövde
        pr = r * 0.78 * breathe
        circle_aa(surf, x, y, pr + 2, OUTLINE)
        circle_aa(surf, x, y, pr, col)
        circle_aa(surf, *P(-0.2, -0.2), max(2, pr * 0.32), lighten(col, 0.3))
        # sivri kulaklar
        for s_ in (-1, 1):
            poly_aa(surf, [P(0.05, 0.55 * s_), P(-0.10, 1.25 * s_), P(-0.30, 0.50 * s_)],
                    scale_col(col, 0.8))
        # sırıtış + gözler
        pygame.draw.arc(surf, (40, 30, 20), pygame.Rect(int(P(0.45, 0)[0] - r * 0.3),
                        int(P(0.45, 0)[1] - r * 0.25), int(r * 0.6), int(r * 0.4)), math.pi, math.tau, 2)
        self._eyes(surf, x, y, pr, fx_, fy_, n=2, spread=0.32, fwd=0.40, sz=0.20,
                   eye_col=(255, 240, 160), t=t)

    # ---- lanet yaratıkları ----
    def _draw_splitter(self, surf, x, y, r, col, t, breathe):
        """Bölünen: bölünmek üzere olan, iki çekirdekli jöle."""
        P, fx_, fy_, sx_, sy_ = self._hmap(x, y, r)
        wob = math.sin(t * 5 + self.wobble)
        pts = []
        for i in range(18):
            a = i * math.tau / 18
            rr = r * breathe * (1 + 0.08 * math.sin(a * 3 + t * 4 + self.wobble))
            pts.append((x + math.cos(a) * rr * (1 + 0.07 * wob),
                        y + math.sin(a) * rr * (1 - 0.07 * wob)))
        poly_aa(surf, [(px, py + 2) for px, py in pts], OUTLINE)
        poly_aa(surf, pts, scale_col(col, 0.78))
        poly_aa(surf, poly_inset(pts, 0.80, dx=-r * 0.06, dy=-r * 0.08), col)
        sep = r * 0.30 * (1 + 0.35 * math.sin(t * 3 + self.wobble))
        n1 = (x + sx_ * sep, y + sy_ * sep)
        n2 = (x - sx_ * sep, y - sy_ * sep)
        thick_line(surf, n1, n2, max(2, r * 0.16), scale_col(col, 0.50))
        for nx_, ny_ in (n1, n2):
            circle_aa(surf, nx_, ny_, r * 0.24, scale_col(col, 0.45))
            circle_aa(surf, nx_ - r * 0.05, ny_ - r * 0.05, r * 0.09, lighten(col, 0.5))
        hx, hy = P(-0.30, -0.32)
        circle_aa(surf, hx, hy, max(2, r * 0.18), lighten(col, 0.65))
        self._eyes(surf, x, y, r, fx_, fy_, n=2, spread=0.34, fwd=0.42, sz=0.16, t=t)
        if self.split_gen == 0:
            # ilk kuşak: ortadan geçen bölünme çizgisi
            thick_line(surf, P(0.75, 0.0), P(-0.75, 0.0), 1.2, scale_col(col, 0.40))

    def _draw_necro(self, surf, x, y, r, col, t, breathe):
        """Ölü çağırıcı: kukuletalı cüppe, yeşil yanan gözler, kafatası asa."""
        casting = self.necro_cd < 1.0
        robe = (40, 46, 52)
        pts = [(x - r * 0.95, y + r * 0.95), (x - r * 0.45, y - r * 0.35),
               (x + r * 0.45, y - r * 0.35), (x + r * 0.95, y + r * 0.95)]
        hem = [(x - r * 0.95 + i * r * 0.38, y + r * (0.95 + 0.10 * math.sin(t * 6 + i)))
               for i in range(6)]
        body = pts[:3] + [pts[3]] + hem[::-1]
        poly_aa(surf, [(px, py + 2) for px, py in body], OUTLINE)
        poly_aa(surf, body, robe)
        poly_aa(surf, poly_inset(body, 0.70, dy=-r * 0.05), scale_col(col, 0.42))
        # kukuleta + karanlık yüz
        hy = y - r * 0.45 * breathe
        circle_aa(surf, x, hy, r * 0.62, OUTLINE)
        circle_aa(surf, x, hy, r * 0.58, robe)
        circle_aa(surf, x + self.face_x * r * 0.08, hy + r * 0.06, r * 0.40, (10, 12, 14))
        for s_ in (-1, 1):
            ex_ = x + self.face_x * r * 0.12 + s_ * r * 0.16
            ey_ = hy + r * 0.04
            add_glow(surf, ex_, ey_, r * 0.40, col, 0.55 if casting else 0.35)
            circle_aa(surf, ex_, ey_, max(1.5, r * 0.09), lighten(col, 0.5))
        # asa
        sx0 = x + r * 0.95
        thick_line(surf, (sx0, y + r * 0.9), (sx0, y - r * 1.15), max(2, r * 0.12), (110, 84, 60))
        circle_aa(surf, sx0, y - r * 1.25, r * 0.24, (214, 208, 190))
        circle_aa(surf, sx0 - r * 0.07, y - r * 1.27, r * 0.06, (20, 20, 20))
        circle_aa(surf, sx0 + r * 0.07, y - r * 1.27, r * 0.06, (20, 20, 20))
        add_glow(surf, sx0, y - r * 1.25, r * (0.7 + (0.5 if casting else 0.0)), col,
                 0.5 if casting else 0.25)
        if casting:
            for i in range(6):
                a = t * 2.5 + i * math.tau / 6
                circle_aa(surf, x + math.cos(a) * r * 1.4, y + math.sin(a) * r * 0.7 + r * 0.6,
                          max(1.2, r * 0.08), lighten(col, 0.4))

    def _draw_ghost(self, surf, x, y, r, col, t, breathe):
        """hayalet: dalgalı etekli çarşaf ruh, kocaman kara gözler."""
        float_y = y - r * 0.18 + math.sin(t * 3 + self.wobble) * r * 0.10
        top = []
        for i in range(10):
            a = math.pi + i * math.pi / 9
            top.append((x + math.cos(a) * r * 0.92, float_y + math.sin(a) * r * 0.92))
        hem = []
        for i in range(9):
            k = i / 8.0
            hx_ = x + r * 0.92 - k * r * 1.84
            hem.append((hx_, float_y + r * (0.95 + 0.20 * math.sin(t * 7 + k * 9 + self.wobble))))
        body = [(x + r * 0.92, float_y)] + hem + top
        add_glow(surf, x, float_y, r * 1.6, col, 0.30)
        poly_aa(surf, body, scale_col(col, 0.82))
        poly_aa(surf, poly_inset(body, 0.82, dx=-r * 0.05, dy=-r * 0.08), lighten(col, 0.35))
        for s_ in (-1, 1):
            ex_ = x + self.face_x * r * 0.12 + s_ * r * 0.30
            ey_ = float_y - r * 0.18
            pygame.draw.ellipse(surf, (24, 26, 44), (int(ex_ - r * 0.16), int(ey_ - r * 0.24),
                                                     max(2, int(r * 0.32)), max(3, int(r * 0.46))))
            circle_aa(surf, ex_ - r * 0.04, ey_ - r * 0.10, max(1, r * 0.06), WHITE)
        mo = 0.6 + 0.4 * math.sin(t * 4 + self.wobble)
        pygame.draw.ellipse(surf, (24, 26, 44), (int(x - r * 0.12), int(float_y + r * 0.20),
                                                 max(2, int(r * 0.24)), max(2, int(r * 0.30 * mo))))

    # ---- tazı: alev yeleli, dört ayaklı cehennem köpeği ----
    def _draw_hound(self, surf, x, y, r, col, t, breathe):
        P, fx_, fy_, sx_, sy_ = self._hmap(x, y, r)
        dark = scale_col(col, 0.55)
        if self.dash_t > 0:
            for k in range(3):
                add_glow(surf, *P(-0.6 - k * 0.55, 0.0), r * 1.4, (255, 130, 50), 0.32 - k * 0.09)
        # bacaklar
        for i in range(2):
            for sgn in (-1, 1):
                ph = self.walk * 1.4 + i * 1.8 + (0 if sgn > 0 else math.pi)
                sw = math.sin(ph) * 0.30
                a = P(0.42 - i * 0.84, 0.46 * sgn)
                b = P(0.42 - i * 0.84 + sw, 0.92 * sgn)
                pygame.draw.line(surf, OUTLINE, a, b, max(4, int(r * 0.20)))
                pygame.draw.line(surf, dark, a, b, max(2, int(r * 0.13)))
        # kuyruk
        tw = math.sin(self.walk * 2.0) * 0.42
        self._hpoly(surf, [P(-0.86, 0.14), P(-1.50, tw), P(-0.86, -0.14)], col, x, y, grow=0.04)
        # gövde (uzun, alçak)
        body = [P(1.05, 0.0), P(0.60, 0.62), P(-0.30, 0.70),
                P(-0.92, 0.34), P(-0.92, -0.34), P(-0.30, -0.70), P(0.60, -0.62)]
        self._hpoly(surf, body, col, x, y, grow=0.09)
        # alev yelesi (ense boyunca yukarı fışkıran korlar)
        for i in range(5):
            f = 0.40 - i * 0.26
            h = 0.42 + 0.22 * math.sin(t * 9 + i * 1.3 + self.wobble)
            self._hpoly(surf, [P(f, -0.16), P(f + 0.10, -0.16 - h), P(f + 0.22, -0.16)],
                        (255, 170 - i * 14, 60), x, y, grow=0.0)
            self._hpoly(surf, [P(f, 0.16), P(f + 0.10, 0.16 + h), P(f + 0.22, 0.16)],
                        (255, 170 - i * 14, 60), x, y, grow=0.0)
        # kafa + çene
        hx, hy = P(1.12, 0.0)
        pygame.draw.circle(surf, OUTLINE, (int(hx), int(hy)), int(r * 0.40))
        pygame.draw.circle(surf, dark, (int(hx), int(hy)), int(r * 0.34))
        self._hpoly(surf, [P(1.20, -0.26), P(1.76, 0.0), P(1.20, 0.26)], dark, x, y, grow=0.05)
        for k in (-1, 1):
            pygame.draw.line(surf, (255, 248, 232), P(1.34, 0.14 * k), P(1.62, 0.06 * k), 2)
        self._horns(surf, P, r, base_f=0.92, spread=0.34, reach=0.54, curl=0.30)
        self._eyes(surf, x, y, r, fx_, fy_, n=2, spread=0.16, fwd=1.16, sz=0.12,
                   eye_col=(255, 240, 200), glow_col=(255, 90, 40), t=t)

    # ---- yağmacı: iri, tek elinde satır taşıyan cehennem yağmacısı ----
    def _draw_reaver(self, surf, x, y, r, col, t, breathe):
        P, fx_, fy_, sx_, sy_ = self._hmap(x, y, r)
        dark = scale_col(col, 0.55)
        lite = lighten(col, 0.26)
        step = math.sin(self.walk) * 0.18
        # bacaklar
        for sgn in (-1, 1):
            a = P(-0.36, 0.48 * sgn)
            b = P(-0.72 + step * sgn, 0.60 * sgn)
            pygame.draw.line(surf, OUTLINE, a, b, max(5, int(r * 0.26)))
            pygame.draw.line(surf, dark, a, b, max(3, int(r * 0.18)))
        # satır (sağ elde)
        grip = P(0.30 + step, 0.96)
        tip = P(1.10 + step, 1.10)
        pygame.draw.line(surf, OUTLINE, grip, tip, max(4, int(r * 0.18)))
        pygame.draw.line(surf, (96, 66, 44), grip, tip, max(2, int(r * 0.11)))
        self._hpoly(surf, [tip, P(1.44 + step, 0.74), P(1.10 + step, 0.44), P(0.94 + step, 0.86)],
                    (224, 230, 242), x, y, grow=0.04)
        # gövde
        body = [P(0.62, 0.52), P(0.16, 0.98), P(-0.62, 0.78),
                P(-0.62, -0.78), P(0.16, -0.98), P(0.62, -0.52)]
        self._hpoly(surf, body, col, x, y, grow=0.09)
        # göğüste akkor yara izleri
        for i in range(3):
            pygame.draw.line(surf, (255, 150, 60),
                             P(0.34 - i * 0.22, -0.30 + i * 0.10),
                             P(0.06 - i * 0.22, 0.34 + i * 0.06), 2)
        self._hpoly(surf, [P(0.30, 0.0), P(-0.10, 0.40), P(-0.44, 0.0), P(-0.10, -0.40)],
                    lite, x, y, grow=0.0)
        # kafa: kaskın altından parlayan gözler
        self._hpoly(surf, [P(1.02, 0.0), P(0.78, 0.36), P(0.44, 0.28),
                           P(0.44, -0.28), P(0.78, -0.36)], dark, x, y, grow=0.05)
        self._horns(surf, P, r, base_f=0.50, spread=0.34, reach=0.66, curl=0.36)
        self._eyes(surf, x, y, r, fx_, fy_, n=2, spread=0.15, fwd=0.80, sz=0.11,
                   eye_col=(255, 236, 200), glow_col=(255, 110, 50), t=t)
        self._ember_trail(surf, x, y, r, t, 2)

    # ---- kör KÂhin: tek dev gözü olan, süzülen büyücü ----
    def _draw_seer(self, surf, x, y, r, col, t, breathe):
        y += math.sin(t * 2.0 + self.wobble) * r * 0.16
        P, fx_, fy_, sx_, sy_ = self._hmap(x, y, r)
        dark = scale_col(col, 0.50)
        charging = self.shoot_cd < 0.6
        # dolanan kor halkalar
        for i in range(3):
            a = t * 1.5 + i * math.tau / 3
            rr = r * (1.35 + (0.20 if charging else 0.0))
            ox, oy = x + math.cos(a) * rr, y + math.sin(a) * rr * 0.7
            oc = (255, 235, 150) if charging else (255, 150, 60)
            add_glow(surf, ox, oy, r * 0.30, oc, 0.45)
            pygame.draw.circle(surf, oc, (int(ox), int(oy)), max(2, int(r * 0.13)))
        # yırtık pelerin
        cloak = [P(0.32, 0.46)]
        for i in range(6):
            k = i / 5.0
            wob = math.sin(t * 3.6 + i * 1.3) * 0.16
            cloak.append(P(-0.90 - 0.30 * math.sin(k * math.pi) - (0.18 if i % 2 else 0),
                           (0.5 - k) * 1.70 + wob))
        cloak.append(P(0.32, -0.46))
        self._hpoly(surf, cloak, dark, x, y, grow=0.05)
        # kafa: tek dev göz
        pr = r * breathe
        if charging:
            add_glow(surf, x, y, pr * 2.1, (255, 230, 150), 0.55)
        pygame.draw.circle(surf, OUTLINE, (int(x), int(y)), int(pr + 2))
        pygame.draw.circle(surf, col, (int(x), int(y)), int(pr))
        self._horns(surf, P, r, base_f=-0.10, spread=0.56, reach=0.86, curl=0.40)
        ex, ey = P(0.18, 0.0)
        pygame.draw.circle(surf, (250, 246, 232), (int(ex), int(ey)), int(pr * 0.56))
        pygame.draw.circle(surf, OUTLINE, (int(ex), int(ey)), int(pr * 0.56), 2)
        pupil = (255, 110, 40) if charging else (140, 30, 30)
        add_glow(surf, ex + fx_ * pr * 0.14, ey + fy_ * pr * 0.14, pr * 0.7, pupil, 0.55)
        pygame.draw.circle(surf, pupil,
                           (int(ex + fx_ * pr * 0.14), int(ey + fy_ * pr * 0.14)),
                           int(pr * 0.24))
        self._ember_trail(surf, x, y, r, t, 3)

    # ---- lav golemi: kabuğu çatlamış, içi ergimiş dev ----
    def _draw_golem(self, surf, x, y, r, col, t, breathe):
        P, fx_, fy_, sx_, sy_ = self._hmap(x, y, r)
        dark = scale_col(col, 0.60)
        magma = (255, 132, 44)
        pulse = 0.55 + 0.45 * math.sin(t * 2.6 + self.wobble)
        step = math.sin(self.walk * 0.8) * 0.16
        # bacaklar
        for sgn in (-1, 1):
            a = P(-0.34, 0.50 * sgn)
            b = P(-0.80 + step * sgn, 0.62 * sgn)
            pygame.draw.line(surf, OUTLINE, a, b, max(6, int(r * 0.30)))
            pygame.draw.line(surf, dark, a, b, max(4, int(r * 0.22)))
        # yumruklar
        for sgn in (-1, 1):
            fc = P(0.54 - step * sgn, 1.06 * sgn)
            pygame.draw.circle(surf, OUTLINE, (int(fc[0]), int(fc[1])), int(r * 0.36))
            pygame.draw.circle(surf, dark, (int(fc[0]), int(fc[1])), int(r * 0.30))
        # gövde: düzensiz kaya kabuk
        pts = []
        for i in range(8):
            a = i * math.tau / 8 + 0.3
            jit = 1.0 + 0.18 * math.sin(i * 2.3 + self.wobble)
            pts.append((x + math.cos(a) * r * breathe * jit,
                        y + math.sin(a) * r * breathe * jit))
        self._hpoly(surf, pts, col, x, y, grow=0.08)
        # ergimiş çatlaklar
        add_glow(surf, x, y, r * (1.5 + 0.35 * pulse), magma, 0.22 + 0.18 * pulse)
        for i in range(5):
            a = self.wobble + i * 1.27
            pygame.draw.line(surf, scale_col(magma, 0.6 + 0.4 * pulse),
                             (x + math.cos(a) * r * 0.16, y + math.sin(a) * r * 0.16),
                             (x + math.cos(a + 0.5) * r * 0.86, y + math.sin(a + 0.5) * r * 0.86),
                             max(2, int(r * 0.09)))
        cx, cy = P(0.10, 0.0)
        pygame.draw.circle(surf, magma, (int(cx), int(cy)), int(r * (0.18 + 0.06 * pulse)))
        self._horns(surf, P, r, base_f=-0.24, spread=0.60, reach=0.80, curl=0.40)
        self._eyes(surf, x, y, r, fx_, fy_, n=2, spread=0.22, fwd=0.52, sz=0.13,
                   eye_col=(255, 230, 180), glow_col=magma, t=t)
        self._ember_trail(surf, x, y, r, t, 3)

    # ---- kasap: maskeli, zincirli çengel taşıyan cehennem kasabı ----
    def _draw_butcher(self, surf, x, y, r, col, t, breathe):
        P, fx_, fy_, sx_, sy_ = self._hmap(x, y, r)
        dark = scale_col(col, 0.52)
        step = math.sin(self.walk * 1.2) * 0.20
        # zincir + çengel (savrulur)
        sw = math.sin(t * 2.6 + self.wobble)
        hook_end = P(1.30 + 0.30 * sw, 1.10 * sw)
        chain_from = P(0.10, 0.70)
        for i in range(4):
            k = (i + 1) / 4.0
            cx = lerp(chain_from[0], hook_end[0], k)
            cy = lerp(chain_from[1], hook_end[1], k)
            pygame.draw.circle(surf, (170, 176, 190), (int(cx), int(cy)), max(2, int(r * 0.09)), 2)
        pygame.draw.arc(surf, (226, 232, 244),
                        pygame.Rect(int(hook_end[0] - r * 0.34), int(hook_end[1] - r * 0.34),
                                    int(r * 0.68), int(r * 0.68)), 0.6, 4.2, 3)
        # bacaklar
        for sgn in (-1, 1):
            a = P(-0.30, 0.44 * sgn)
            b = P(-0.74 + step * sgn, 0.56 * sgn)
            pygame.draw.line(surf, OUTLINE, a, b, max(5, int(r * 0.24)))
            pygame.draw.line(surf, dark, a, b, max(3, int(r * 0.16)))
        # gövde (önlüklü)
        body = [P(0.58, 0.46), P(0.10, 0.90), P(-0.66, 0.66),
                P(-0.66, -0.66), P(0.10, -0.90), P(0.58, -0.46)]
        self._hpoly(surf, body, col, x, y, grow=0.09)
        apron = [P(0.46, 0.34), P(-0.30, 0.46), P(-0.30, -0.46), P(0.46, -0.34)]
        self._hpoly(surf, apron, (232, 224, 214), x, y, grow=0.0)
        for i in range(4):
            bl = P(0.30 - i * 0.20, math.sin(i * 2.1) * 0.30)
            pygame.draw.circle(surf, (168, 30, 34), (int(bl[0]), int(bl[1])),
                               max(1, int(r * 0.09)))
        # kafa: dikişli maske
        self._hpoly(surf, [P(1.02, 0.0), P(0.80, 0.34), P(0.46, 0.30),
                           P(0.46, -0.30), P(0.80, -0.34)], (222, 212, 198), x, y, grow=0.05)
        for k in (-1, 1):
            pygame.draw.line(surf, (70, 60, 56), P(0.66, 0.06 * k), P(0.94, 0.06 * k), 1)
        self._eyes(surf, x, y, r, fx_, fy_, n=2, spread=0.14, fwd=0.80, sz=0.09,
                   eye_col=(40, 30, 30), pupil=(255, 90, 60), glow_col=(255, 90, 50), t=t)
        self._ember_trail(surf, x, y, r, t, 2)

    # ---- cehennem muhafızı: kalkanlı, zırhlı elit ----
    def _draw_warden(self, surf, x, y, r, col, t, breathe):
        P, fx_, fy_, sx_, sy_ = self._hmap(x, y, r)
        dark = scale_col(col, 0.52)
        gold = (236, 190, 86)
        add_glow(surf, x, y, r * 2.0, (255, 130, 50), 0.40 + 0.10 * math.sin(t * 3))
        step = math.sin(self.walk) * 0.16
        # bacaklar
        for sgn in (-1, 1):
            a = P(-0.34, 0.48 * sgn)
            b = P(-0.78 + step * sgn, 0.58 * sgn)
            pygame.draw.line(surf, OUTLINE, a, b, max(5, int(r * 0.26)))
            pygame.draw.line(surf, dark, a, b, max(3, int(r * 0.18)))
        # kalkan (sol kol)
        shield = [P(0.62, -0.72), P(0.62, -1.40), P(-0.36, -1.40), P(-0.52, -0.72)]
        self._hpoly(surf, shield, dark, x, y, grow=0.05)
        pygame.draw.polygon(surf, gold, shield, 3)
        pygame.draw.line(surf, gold, P(0.20, -1.06), P(-0.10, -1.06), 3)
        # mızrak (sağ kol)
        grip = P(0.0, 0.86)
        tipp = P(1.62, 1.02)
        pygame.draw.line(surf, OUTLINE, grip, tipp, max(4, int(r * 0.17)))
        pygame.draw.line(surf, (110, 78, 50), grip, tipp, max(2, int(r * 0.10)))
        self._hpoly(surf, [tipp, P(1.34, 0.86), P(1.34, 1.18)], (236, 242, 250), x, y, grow=0.04)
        # gövde
        body = [P(0.64, 0.46), P(0.18, 0.88), P(-0.60, 0.70),
                P(-0.60, -0.70), P(0.18, -0.88), P(0.64, -0.46)]
        self._hpoly(surf, body, col, x, y, grow=0.09)
        pygame.draw.polygon(surf, gold, body, 2)
        self._hpoly(surf, [P(0.36, 0.0), P(-0.04, 0.38), P(-0.40, 0.0), P(-0.04, -0.38)],
                    lighten(col, 0.28), x, y, grow=0.0)
        # miğfer
        self._hpoly(surf, [P(1.04, 0.0), P(0.80, 0.34), P(0.44, 0.28),
                           P(0.44, -0.28), P(0.80, -0.34)], dark, x, y, grow=0.05)
        pygame.draw.line(surf, (22, 18, 22), P(0.84, -0.22), P(0.84, 0.22), max(3, int(r * 0.11)))
        self._horns(surf, P, r, col=gold, base_f=0.46, spread=0.34, reach=0.70, curl=0.38)
        self._eyes(surf, x, y, r, fx_, fy_, n=2, spread=0.13, fwd=0.86, sz=0.09,
                   eye_col=(255, 240, 210), glow_col=(255, 120, 50), t=t)
        self._ember_trail(surf, x, y, r, t, 3)

    # ---- çizim ----
    # yaratık gövdesi önbelleği. Her yaratık 20-40 ayrı çizim çağrısıyla elle
    # çiziliyor.
    SPR_FACE_STEPS = 24          # yön kaç dilime bölünüyor
    SPR_WALK_STEP = 0.19         # yürüyüş fazı adımı (radyan) - 0.26'dan, daha akıcı
    SPR_TIME_HZ = 10.0           # zamana bağlı titreşimlerin tazelenme hızı
    # kare başına yeniden çizim bütçesi. Bütçe dolunca yaratık bir kare daha
    # eski görüntüsüyle basılır - göz bunu fark etmez.
    SPR_BUDGET = 22
    # akıcı animasyon: bütçe düşman sayısıyla büyür (draw_run her karede
    # ayarlar). Şimdi en çok SPR_BUDGET_MAX.
    SPR_BUDGET_MAX = 48
    if MOBILE:
        # Telefon: daha seyrek gövde tazeleme (göz farkı yok denecek kadar az).
        SPR_FACE_STEPS = 16
        SPR_WALK_STEP, SPR_TIME_HZ, SPR_BUDGET, SPR_BUDGET_MAX = 0.42, 1.0, 5, 9
    _spr_budget = [22]
    _spr_tick = [0]              # telefon: denetimi karelere yaymak için
    _spr_frame = [None, 0, 0]    # [t, bu karede yapılan yeniden çizim, kare sayacı]
    # Bütçe hep listenin başındakilere gidiyordu; sondakiler hiç tazelenmeyip
    # eski yöne bakıyordu. Bu kadar kare bekleyen yaratık sırayı beklemez.
    SPR_STARVE = 4

    def _blink_at(self, t):
        """Göz kırpma katsayısı (1.0 = tam açık). ~4 saniyede bir, her yaratık kendi fazında."""
        ph = (t * 0.9 + self.wobble) % 4.0
        if ph < 0.13:
            return max(0.12, abs(ph - 0.065) / 0.065)
        return 1.0

    def _body_key(self, t, r, blink):
        """Gövdenin görünüşünü belirleyen her şeyin özeti."""
        ang = math.atan2(self.face_y, self.face_x)
        return (
            int(ang / math.tau * self.SPR_FACE_STEPS),
            int(self.walk / self.SPR_WALK_STEP),
            int(t * self.SPR_TIME_HZ),
            int(r * 2),
            # Telefonda hasar parlaması gövdeyi yeniden çizdirmez; üstüne ucuz
            # bir beyaz disk basılır. Kalabalıkta en büyük yeniden çizim sebebi
            # buydu.
            (not MOBILE) and self.hit_flash > 0,
            int(blink * 6),
            int(getattr(self, "red_intensity", 0.0) * 6),
            int(getattr(self, "block_flash", 0.0) * 6),
            getattr(self, "shoot_cd", 9.9) < 0.6,
            self._guard_bucket(),
        )

    def _guard_bucket(self):
        """Siperci'nin kalkanı koruduğu sancaktardan dışa bakar; bu yön de görünüşün bir parçası"""
        g = self.guard_of
        if g is None or not g.alive:
            return -1
        return int(math.atan2(self.y - g.y, self.x - g.x) / math.tau * 24)

    def draw(self, surf, t):
        scale = ease_out_cubic(self.spawn_t / 0.3) if self.spawn_t < 0.3 else 1.0
        r = self.radius * scale
        x, y = self.x, self.y
        # Gölge hep canlı: zaten tek blit. Telefonda gölge gövde önbelleğine
        # gömülü: yaratık başına bir blit eksik.
        if not MOBILE or self.phased:
            surf.blit(shadow_sprite(int(r * 2 + 6)), (int(x - r - 3), int(y + r - 3)))

        if scale < 1.0:
            if MOBILE:
                # Telefon: doğuşta gövde her karede baştan çizilmez; hazır
                # gövde basılır, üstünde sönen beyaz bir parlama olur.
                self._ensure_spr(t, self.radius)
                surf.blit(self._spr, (int(x) - self._spr_off[0], int(y) - self._spr_off[1]))
                blit_disc(surf, x, y, self.radius * 1.1, (255, 255, 255), int(170 * (1.0 - scale)))
                return
            # Doğuş animasyonu: boy her karede değişiyor, önbellek anlamsız.
            self._blink = None
            self._draw_body(surf, x, y, t, r)
            return

        if not (MOBILE and self._spr is not None and (Enemy._spr_tick[0] + id(self) // 16) % 3):
            # Telefonda her yaratık görünüşünü üç karede bir denetler (anahtar
            # hesabı da bir maliyet); arada hazır gövde basılır.
            self._ensure_spr(t, r)
        if self.phased:
            # hayalet dokunulmazken yarı saydam görünür.
            ghost_img = self._spr.copy()
            ghost_img.set_alpha(80)
            surf.blit(ghost_img, (int(x) - self._spr_off[0], int(y) - self._spr_off[1]))
            return
        if self.rage > 0:
            self._draw_rage(surf, x, y, r, t, under=True)
        if self.mutant:
            self._draw_mutant(surf, x, y, r, t, under=True)
        surf.blit(self._spr, (int(x) - self._spr_off[0], int(y) - self._spr_off[1]))
        if MOBILE and self.hit_flash > 0:
            blit_disc(surf, x, y, r * 0.9, (255, 255, 255), 90)
        if self.rage > 0:
            self._draw_rage(surf, x, y, r, t, under=False)
        if self.mutant:
            self._draw_mutant(surf, x, y, r, t, under=False)
        if self.kind == "kamikaze":
            self._draw_fuse(surf, x, y, r, t)

    def _ensure_spr(self, t, r):
        """Gövde önbelleğini (self._spr) günceller - 2D çizim ve 2.5D/3D ortak."""
        blink = self._blink_at(t)
        key = self._body_key(t, r, blink)
        if self._spr is not None and self._spr_key != key:
            fr = Enemy._spr_frame
            if fr[0] != t:
                fr[0], fr[1] = t, 0
                fr[2] += 1
            old = self._spr_key
            steps = self.SPR_FACE_STEPS
            # ortak (atlas) karesinden kişisel kareye geçiş: anahtarlar farklı
            # biçimde (ilk alan şekil adı), karşılaştırılamaz -> hemen çiz
            if len(old) != len(key) or getattr(self, "_spr_shared", False):
                turn = steps // 2
            else:
                turn = abs(old[0] - key[0]) % steps
            urgent = (len(old) != len(key) or old[3] != key[3]
                      or old[4] != key[4]                      # boy / hasar parlaması
                      or min(turn, steps - turn) >= 2          # oyuncuya dönüyor
                      or fr[2] - getattr(self, "_spr_fn", 0) >= self.SPR_STARVE)
            if not urgent and fr[1] >= Enemy._spr_budget[0]:
                key = old                                     # bütçe doldu: eskisini bas
            else:
                fr[1] += 1
        if self._spr is None or self._spr_key != key:
            # Ölçüm: hiçbir şeklin çizimi r*2.1'i geçmiyor (en genişi warden,
            # r*1.9). Yüzey ne kadar küçükse blit o kadar ucuz.
            pad = int(r * 2.2) + 6
            spr = pygame.Surface((pad * 2, pad * 2), pygame.SRCALPHA)
            global _GLOW_ON_ALPHA
            _GLOW_ON_ALPHA = True
            self._blink = blink
            _hf = self.hit_flash
            try:
                if MOBILE:
                    # Telefonda parlama gövdeye gömülmez (üstüne ayrı disk
                    # basılır); gömülseydi gövde beyaz kalırdı.
                    self.hit_flash = 0.0
                    if not self.phased:
                        spr.blit(shadow_sprite(int(r * 2 + 6)), (int(pad - r - 3), int(pad + r - 3)))
                self._draw_body(spr, pad, pad, t, r)
            finally:
                _GLOW_ON_ALPHA = False
                self.hit_flash = _hf
                self._blink = None
            off = (pad, pad)
            if MOBILE:
                # Telefon: boş (saydam) kenarlar kırpılır. Yüzey ~3-4 kat
                # küçülür; tarayıcıda saydam blit'in maliyeti piksel başına.
                br = spr.get_bounding_rect()
                if br.w > 0 and br.h > 0 and br.w * br.h < spr.get_width() * spr.get_height() * 0.8:
                    spr = spr.subsurface(br).copy()
                    off = (pad - br.x, pad - br.y)
            self._spr, self._spr_key, self._spr_pad = mob_rle(spr), key, pad
            self._spr_off = off
            self._spr_shared = False
            self._spr_fn = Enemy._spr_frame[2]

    # telefon: ortak gövde atlası Aynı türden yaratıklar aynı karelerden oluşan
    # ortak bir depoyu paylaşır.
    _ATLAS = {}
    _atlas_frame = [None, 0]
    ATLAS_WALK_N = 50
    ATLAS_WALK_STEP = math.tau * 5.0 / ATLAS_WALK_N
    ATLAS_MAX = 4000
    ATLAS_BUDGET = 6
    _SHOOTERS = ("yellow", "wizard")
    _CANON_ATTRS = ("walk", "wobble", "face_x", "face_y", "hp", "slow_timer", "burn_timer",
                    "poison_dps", "hit_flash", "red_intensity", "block_flash", "shoot_cd",
                    "dash_t", "necro_cd", "_blink")

    def _atlas_ok(self):
        return (self.heal_flash <= 0 and self.guard_of is None and self.shape != "herald")

    def _ensure_shared(self, t, r):
        ang = math.atan2(self.face_y, self.face_x)
        fb = int(round(ang / math.tau * 16)) % 16
        wb = int(self.walk / Enemy.ATLAS_WALK_STEP) % Enemy.ATLAS_WALK_N
        if self.kind in Enemy._SHOOTERS:
            sc = self.shoot_cd
            if self.shape in ("j_frog", "d_archer"):
                # bu ikisinde atış hazırlığı kademeli büyür (4 kademe)
                sb = 1 + min(3, int(clamp(1.0 - sc, 0.0, 1.0) * 4))
            else:
                sb = 5 if sc < 0.6 else 0         # yalnız "nişan alıyor" bayrağı
        else:
            sb = -1
        key = (self.shape, self.kind, self.color, self.hellish, int(r * 2),
               getattr(self, "split_gen", 0), fb, wb, 6,
               int(getattr(self, "red_intensity", 0.0) * 6),
               int(getattr(self, "block_flash", 0.0) * 6), sb, self.dash_t > 0,
               getattr(self, "necro_cd", 9.0) < 1.0)
        if key == self._spr_key:
            return
        ent = Enemy._ATLAS.get(key)
        if ent is None:
            fr = Enemy._atlas_frame
            if fr[0] != t:
                fr[0], fr[1] = t, 0
            ok = self._spr_key or (0,) * 7
            turn = abs(ok[6] - fb) % 16
            if (self._spr is not None and fr[1] >= Enemy.ATLAS_BUDGET
                    and int(r * 2) == ok[4] and min(turn, 16 - turn) < 2):
                return                    # bütçe doldu: eski kare bir an daha
            fr[1] += 1
            ent = self._render_shared(key, r)
            atlas = Enemy._ATLAS
            if len(atlas) >= Enemy.ATLAS_MAX:
                for k in list(atlas)[:300]:
                    del atlas[k]
            atlas[key] = ent
        self._spr, self._spr_off = ent
        self._spr_key = key
        self._spr_shared = True

    def _render_shared(self, key, r):
        d = self.__dict__
        miss = object()
        saved = [(a, d.get(a, miss)) for a in Enemy._CANON_ATTRS]
        fb, wb, bl, ri, bf, sb = key[6], key[7], key[8], key[9], key[10], key[11]
        walk = wb * Enemy.ATLAS_WALK_STEP
        a = fb * math.tau / 16
        global _GLOW_ON_ALPHA
        try:
            self.walk, self.wobble = walk, 0.0
            self.face_x, self.face_y = math.cos(a), math.sin(a)
            self.hp = self.max_hp
            self.slow_timer = self.burn_timer = self.poison_dps = 0.0
            self.hit_flash = 0.0
            self.red_intensity, self.block_flash = ri / 6.0, bf / 6.0
            if sb >= 0:
                self.shoot_cd = (1.2 if sb == 0 else 0.3 if sb == 5
                                 else 1.0 - (sb - 0.5) / 4.0)
            self.dash_t = 0.1 if key[12] else 0.0
            if "necro_cd" in d:
                self.necro_cd = 0.5 if key[13] else 2.0
            self._blink = bl / 6.0
            pad = int(r * 2.2) + 6
            spr = pygame.Surface((pad * 2, pad * 2), pygame.SRCALPHA)
            _GLOW_ON_ALPHA = True
            spr.blit(shadow_sprite(int(r * 2 + 6)), (int(pad - r - 3), int(pad + r - 3)))
            self._draw_body(spr, pad, pad, walk * 0.3, r)
        finally:
            _GLOW_ON_ALPHA = False
            for a_, v in saved:
                if v is miss:
                    d.pop(a_, None)
                else:
                    d[a_] = v
        off = (pad, pad)
        br = spr.get_bounding_rect()
        if br.w > 0 and br.h > 0 and br.w * br.h < spr.get_width() * spr.get_height() * 0.8:
            spr = spr.subsurface(br).copy()
            off = (pad - br.x, pad - br.y)
        return (mob_rle(spr), off)

    def mutate(self):
        """mutasyon: bembeyaz zombi derisi + ölçülü güç artışı."""
        if self.mutant:
            return
        self.mutant = True
        self.max_hp *= MUTANT_HP
        self.hp = self.max_hp
        self.dmg *= MUTANT_DMG
        self.contact_dps *= MUTANT_DMG
        self.speed *= MUTANT_SPEED
        self.armor = min(0.60, self.armor + MUTANT_ARMOR)
        self.score = int(self.score * MUTANT_REWARD)
        self.xp = int(self.xp * MUTANT_REWARD)
        self.coin = int(self.coin * MUTANT_REWARD)
        # kızıl kudurma yerini solgun zombi beyazına bırakır
        self.rage = 0.0
        self.red_intensity = 0.0       # temel kırmızının "kızarma"sı mutantı boyamasın
        self.color = mix_col(self.color, MUTANT_SKIN_HELL if getattr(self, "hellish", False)
                             else MUTANT_SKIN, 0.80)
        self._spr = None

    def _draw_mutant(self, surf, x, y, r, t, under):
        """mutant: altta solgun yeşil-beyaz hâle; üstte damarlar ve sızan sporlar."""
        if under:
            add_glow(surf, x, y, r * 2.0, (210, 255, 200), 0.26 + 0.08 * math.sin(t * 4 + self.wobble))
            return
        ph0 = self.wobble * 0.37
        for i in range(3):
            a = ph0 + i * 2.1
            ca, sa = math.cos(a), math.sin(a)
            p0 = (x + ca * r * 0.15, y + sa * r * 0.15)
            p1 = (x + math.cos(a + 0.5) * r * 0.55, y + math.sin(a + 0.5) * r * 0.55)
            p2 = (x + math.cos(a + 0.2) * r * 0.80, y + math.sin(a + 0.2) * r * 0.80)
            pygame.draw.lines(surf, scale_col(MUTANT_VEIN, 0.6), False, [p0, p1, p2], 2)
        for i in range(2):
            ph = (t * 0.9 + i * 0.5 + self.wobble * 0.13) % 1.0
            ex = x + math.sin(i * 2.7 + t * 2.0 + self.wobble) * r * 0.6
            ey = y - r * 0.2 - ph * r * 1.8
            circle_aa(surf, ex, ey, 1.0 + 2.2 * (1.0 - ph), mix_col(MUTANT_VEIN, WHITE, ph))

    def _draw_rage(self, surf, x, y, r, t, under):
        """kudurma: kızıl / mor hâle (altta) ve yükselen közler (üstte)."""
        rg = self.rage
        col = self.rage_col
        bat = col == RAGE_BAT
        fl = 0.80 + 0.20 * math.sin(t * 9.0 + self.wobble)
        if under:
            add_glow(surf, x, y, r * (2.0 + 0.8 * rg), col, (0.30 + 0.45 * rg) * fl)
            if rg > 0.4:
                # öfke halkası: gövdenin çevresinde titreşen ince çember
                ring_aa(surf, x, y, r * (1.18 + 0.06 * math.sin(t * 12 + self.wobble)),
                        lighten(col, 0.25), 2)
            return
        n = 2 + int(rg * 3)
        for i in range(n):
            ph = (t * (1.1 + 0.15 * i) + i * 0.37 + self.wobble * 0.11) % 1.0
            ex = x + math.sin(i * 2.3 + t * 3.1 + self.wobble) * r * 0.75
            ey = y + r * 0.5 - ph * r * 2.3
            if bat:
                _sparkle(surf, ex, ey, 1.2 + 3.2 * (1.0 - ph), (236, 196, 255))
            else:
                circle_aa(surf, ex, ey, 0.8 + 2.0 * (1.0 - ph),
                          mix_col((255, 230, 120), col, ph))

    def _draw_fuse(self, surf, x, y, r, t):
        """kamikaze: fitil kıvılcımı; fitil yanarken kızıl nabız + patlama çemberi."""
        fx_, fy_ = self.face_x, self.face_y
        sx_, sy_ = -fy_, fx_
        cx_, cy_ = x - fx_ * r * 0.9, y - fy_ * r * 0.9
        tip = (cx_ - fx_ * r * 0.55 + sx_ * r * 0.2, cy_ - fy_ * r * 0.55 + sy_ * r * 0.2)
        fl = 0.6 + 0.4 * math.sin(t * 30 + self.wobble)
        add_glow(surf, tip[0], tip[1], 10 + 6 * fl, (255, 200, 90), 0.6)
        circle_aa(surf, tip[0], tip[1], 2.0 + 1.4 * fl, (255, 246, 200))
        if self.fuse_t > 0:
            k = 1.0 - clamp(self.fuse_t / KAMIKAZE_FUSE, 0.0, 1.0)
            pulse = 0.5 + 0.5 * math.sin(t * (18 + 30 * k))
            add_glow(surf, x, y, r * (2.0 + k), (255, 70, 40), 0.35 + 0.45 * pulse)
            rr = int(KAMIKAZE_RADIUS * (0.30 + 0.70 * k))
            pygame.draw.circle(surf, (255, 90, 60), (int(x), int(y)), int(KAMIKAZE_RADIUS), 1)
            pygame.draw.circle(surf, (255, 150 + int(80 * pulse), 90), (int(x), int(y)), rr, 3)

    # Gövde, her yaratığın kendi sprite'ında saklanıyor. _draw_body yalnızca
    # "şu noktaya şu anki görünüşü çiz" der; nereye çizdiğini bilmez, böylece
    # hem dünyaya hem de önbellek yüzeyine aynı kod çizebiliyor.
    def _arena_gear(self, surf, x, y, r, t, flash, breathe):
        """Taş Meydan bir arena: yaratıkları da arena canavarı gibi donanır
        (tasma, miğfer, sorguç, kalkan). Yalnızca haritaya özgü çizimi
        olmayan temel şekillerde."""
        fx_, fy_ = self.face_x, self.face_y
        sx_, sy_ = -fy_, fx_
        bronze = (255, 255, 255) if flash else (206, 146, 66)
        bronze_d = scale_col(bronze, 0.62)
        steel = (255, 255, 255) if flash else (176, 182, 196)

        def P(f, s_):
            return (x + fx_ * f + sx_ * s_, y + fy_ * f + sy_ * s_)

        def tri(a, b, c, col):
            pygame.draw.polygon(surf, OUTLINE, [a, b, c])
            mx_, my_ = (a[0] + b[0] + c[0]) / 3.0, (a[1] + b[1] + c[1]) / 3.0
            pygame.draw.polygon(surf, col, [(mx_ + (q[0] - mx_) * 0.7, my_ + (q[1] - my_) * 0.7) for q in (a, b, c)])

        def band(f0, curve, half, col, w):
            pts = [P(-f0 - curve * (u * u), u * half) for u in (-1.0, -0.66, -0.33, 0.0, 0.33, 0.66, 1.0)]
            pygame.draw.lines(surf, OUTLINE, False, pts, w + 3)
            pygame.draw.lines(surf, col, False, pts, w)
            return pts

        pr = r * breathe
        sh = self.shape
        if sh == "red":
            # dikenli bronz tasma + iki köpek dişi
            pts = band(pr * 0.10, pr * 0.20, pr * 0.86, bronze, 4)
            for k in (1, 3, 5):
                bx_, by_ = pts[k]
                tip = (bx_ - fx_ * pr * 0.34, by_ - fy_ * pr * 0.34)
                tri((bx_ - sx_ * 3, by_ - sy_ * 3), tip, (bx_ + sx_ * 3, by_ + sy_ * 3), bronze)
            for s_ in (-1, 1):
                tri(P(pr * 0.72, s_ * pr * 0.20), P(pr * 0.98, s_ * pr * 0.14), P(pr * 0.74, s_ * pr * 0.06),
                    (250, 246, 236))
        elif sh == "blue":
            # kulak püskülleri + sivri dişler
            for s_ in (-1, 1):
                tri(P(r * 0.40, s_ * r * 0.26), P(r * 0.86, s_ * r * 0.62), P(r * 0.20, s_ * r * 0.46),
                    scale_col(self.color, 0.7) if not flash else WHITE)
                tri(P(r * 0.98, s_ * r * 0.10), P(r * 1.22, s_ * r * 0.05), P(r * 0.96, s_ * r * 0.01),
                    (250, 246, 236))
        elif sh == "yellow":
            # oyulmuş taş: çatlaklar ve dört köşede rün
            rune = (255, 252, 210) if not flash else WHITE
            for i in range(4):
                a = i * math.pi / 2
                c0 = (x + math.cos(a) * pr * 0.62, y + math.sin(a) * pr * 0.62)
                pygame.draw.line(surf, rune, (c0[0] - 2, c0[1]), (c0[0] + 2, c0[1]), 2)
                pygame.draw.line(surf, rune, (c0[0], c0[1] - 3), (c0[0], c0[1] + 3), 1)
            crack = scale_col(self.color, 0.45) if not flash else WHITE
            pygame.draw.lines(surf, crack, False, [(x - pr * 0.62, y - pr * 0.10), (x - pr * 0.40, y + pr * 0.06),
                                                    (x - pr * 0.46, y + pr * 0.30)], 2)
            pygame.draw.lines(surf, crack, False, [(x + pr * 0.30, y - pr * 0.52), (x + pr * 0.42, y - pr * 0.30),
                                                    (x + pr * 0.30, y - pr * 0.16)], 2)
        elif sh == "tank":
            # gladyatör miğferi: kırmızı sorguç + yanda yuvarlak kalkan
            plume = (255, 255, 255) if flash else (206, 44, 56)
            crest = [P(-r * 1.05, -r * 0.16), P(r * 0.30, -r * 0.12), P(r * 0.30, r * 0.12), P(-r * 1.05, r * 0.16)]
            pygame.draw.polygon(surf, OUTLINE, [(a + 1, b + 1) for a, b in crest])
            pygame.draw.polygon(surf, plume, crest)
            for k in range(5):
                f = -r * 0.95 + k * r * 0.28
                pygame.draw.line(surf, scale_col(plume, 0.6), P(f, -r * 0.12), P(f + r * 0.10, r * 0.12), 1)
            scx, scy = P(-r * 0.05, r * 1.10)
            sr = max(4, int(r * 0.48))
            pygame.draw.circle(surf, OUTLINE, (int(scx), int(scy)), sr + 2)
            pygame.draw.circle(surf, bronze, (int(scx), int(scy)), sr)
            pygame.draw.circle(surf, bronze_d, (int(scx), int(scy)), sr, 2)
            pygame.draw.circle(surf, steel, (int(scx), int(scy)), max(2, sr // 3))
        elif sh == "sprinter":
            # dikenli tasma + sırtta kaplan çizgileri
            stripe = scale_col(self.color, 0.45) if not flash else WHITE
            for k in range(3):
                f = -r * 0.10 - k * r * 0.26
                pygame.draw.lines(surf, stripe, False, [P(f, -r * 0.62), P(f - r * 0.12, -r * 0.20),
                                                        P(f - r * 0.12, r * 0.20), P(f, r * 0.62)], 2)
            pts = band(-r * 0.40, r * 0.16, r * 0.62, bronze, 3)
            for k in (2, 4):
                bx_, by_ = pts[k]
                tri((bx_ - sx_ * 3, by_ - sy_ * 3), (bx_ - fx_ * r * 0.26, by_ - fy_ * r * 0.26),
                    (bx_ + sx_ * 3, by_ + sy_ * 3), bronze)
        elif sh == "brute":
            # boynuzlu çelik miğfer
            dome = [P(-pr * 0.10, -pr * 0.70), P(-pr * 0.62, -pr * 0.46), P(-pr * 0.80, 0.0),
                    P(-pr * 0.62, pr * 0.46), P(-pr * 0.10, pr * 0.70)]
            pygame.draw.polygon(surf, OUTLINE, [(a + 1, b + 1) for a, b in dome])
            pygame.draw.polygon(surf, steel, dome)
            pygame.draw.line(surf, lighten(steel, 0.4), P(-pr * 0.20, -pr * 0.50), P(-pr * 0.60, -pr * 0.20), 2)
            for s_ in (-1, 1):
                horn = [P(-pr * 0.20, s_ * pr * 0.62), P(pr * 0.10, s_ * pr * 1.22), P(pr * 0.40, s_ * pr * 1.12),
                        P(pr * 0.02, s_ * pr * 0.52)]
                pygame.draw.polygon(surf, OUTLINE, [(a + 1, b + 1) for a, b in horn])
                pygame.draw.polygon(surf, (240, 228, 200) if not flash else WHITE, horn)

    def _draw_body(self, surf, x, y, t, r):
        # şifacı'nın iyileştirdiği yaratık kısa süre yeşil parlar: oyuncu
        # "bunlar neden ölmüyor?" sorusunun cevabını ekranda görsün, yoksa
        # şifacıyı hedef seçmeyi öğrenemez.
        if self.heal_flash > 0:
            add_glow(surf, x, y, r * 2.0, ENEMY_COLORS["healer"],
                     clamp(self.heal_flash * 0.9, 0.0, 0.5))
        flash = self.hit_flash > 0
        col = WHITE if flash else self.color
        fx_, fy_ = self.face_x, self.face_y
        sx_, sy_ = -fy_, fx_
        dark = scale_col(col, 0.58)
        lite = lighten(col, 0.34)
        # nefes alma: gövde hafifçe şişip iner
        breathe = 1.0 + math.sin(self.walk * 0.9) * 0.045

        # cehennem yaratıklarının kendi çizimleri var.
        hell_draw = HELL_SHAPES.get(self.shape)
        if hell_draw is not None:
            getattr(self, hell_draw)(surf, x, y, r, col, t, breathe)
        elif self.shape == "red":
            # --- etli sürüngen: çenesi olan, tek gözlü, sıçrayarak yürüyen
            # yaratık
            vivid = col if flash else mix_col(self.color, (255, 20, 15), self.red_intensity * 0.85)
            if self.red_intensity > 0.04:
                ga = 0.22 + 0.4 * self.red_intensity + 0.08 * math.sin(t * 5 + self.wobble)
                add_glow(surf, x, y, r * (1.5 + 0.6 * self.red_intensity), vivid, clamp(ga, 0, 0.8))
            hop = abs(math.sin(self.walk * 0.9)) * r * 0.10
            by_ = y - hop
            self._legs(surf, x, by_, r, fx_, fy_, scale_col(vivid, 0.55), pairs=2, width=3)
            pr = r * breathe
            pygame.draw.circle(surf, OUTLINE, (int(x), int(by_)), int(pr + 2))
            pygame.draw.circle(surf, vivid, (int(x), int(by_)), int(pr))
            # sırt dikenleri
            for k in (-1, 0, 1):
                bxp = x - fx_ * pr * 0.55 + sx_ * pr * 0.42 * k
                byp = by_ - fy_ * pr * 0.55 + sy_ * pr * 0.42 * k
                pygame.draw.polygon(surf, scale_col(vivid, 0.6),
                                    [(bxp - sx_ * 3, byp - sy_ * 3),
                                     (bxp - fx_ * pr * 0.34, byp - fy_ * pr * 0.34),
                                     (bxp + sx_ * 3, byp + sy_ * 3)])
            pygame.draw.circle(surf, lighten(vivid, .3),
                               (int(x - pr * .3), int(by_ - pr * .3)), max(2, int(pr * .35)))
            # ağız (yürürken açılıp kapanır)
            mo = 0.5 + 0.5 * math.sin(self.walk * 1.6)
            mx = x + fx_ * pr * 0.66
            my = by_ + fy_ * pr * 0.66
            pygame.draw.polygon(surf, (40, 12, 16),
                                [(mx - sx_ * pr * 0.30, my - sy_ * pr * 0.30),
                                 (mx + fx_ * pr * 0.20, my + fy_ * pr * 0.20),
                                 (mx + sx_ * pr * 0.30, my + sy_ * pr * 0.30),
                                 (mx - fx_ * pr * (0.04 + mo * 0.16), my - fy_ * pr * (0.04 + mo * 0.16))])
            self._eyes(surf, x, by_, pr, fx_, fy_, n=2, spread=0.30, fwd=0.30, sz=0.19, t=t)

        elif self.shape == "blue":
            # --- yarasa/çevik: kanat çırpan, dar gövdeli hızlı yaratık
            flap = math.sin(self.walk * 2.6)
            for s in (-1, 1):
                wtip = (x + sx_ * r * (1.5 + flap * 0.30) * s - fx_ * r * 0.20,
                        y + sy_ * r * (1.5 + flap * 0.30) * s - fy_ * r * 0.20)
                wing = [(x + sx_ * r * 0.30 * s, y + sy_ * r * 0.30 * s),
                        wtip,
                        (x + sx_ * r * 0.62 * s - fx_ * r * 0.80,
                         y + sy_ * r * 0.62 * s - fy_ * r * 0.80)]
                pygame.draw.polygon(surf, OUTLINE, [(a + s, b + 1) for a, b in wing])
                pygame.draw.polygon(surf, dark if not flash else col, wing)
                pygame.draw.polygon(surf, col, wing, 1)
            body = [(x + fx_ * r * 1.05, y + fy_ * r * 1.05),
                    (x + sx_ * r * 0.52, y + sy_ * r * 0.52),
                    (x - fx_ * r * 0.86, y - fy_ * r * 0.86),
                    (x - sx_ * r * 0.52, y - sy_ * r * 0.52)]
            pygame.draw.polygon(surf, OUTLINE, [(a, b + 1) for a, b in body])
            pygame.draw.polygon(surf, col, body)
            pygame.draw.polygon(surf, lite, [(x + fx_ * r * 0.7, y + fy_ * r * 0.7),
                                             (x + sx_ * r * 0.22, y + sy_ * r * 0.22),
                                             (x - fx_ * r * 0.2, y - fy_ * r * 0.2)])
            self._eyes(surf, x, y, r, fx_, fy_, n=2, spread=0.26, fwd=0.46, sz=0.17,
                       eye_col=(255, 240, 190), t=t)

        elif self.shape == "kamikaze":
            # --- kamikaze: çatlaklarından kor sızan, sırtında fitili olan kara
            # bomba-yaratık. Kıvılcım ve fitil nabzı _draw_fuse'da.
            pr = r * breathe
            hot = (255, 120, 50) if not flash else WHITE
            self._legs(surf, x, y, r * 0.86, fx_, fy_, (70, 50, 46), pairs=2, width=3)
            pygame.draw.circle(surf, OUTLINE, (int(x), int(y)), int(pr + 2))
            pygame.draw.circle(surf, WHITE if flash else (54, 42, 42), (int(x), int(y)), int(pr))
            add_glow(surf, x, y, pr * 1.2, (255, 90, 40), 0.22)
            for k_ in range(3):
                a = k_ * 2.1 + 0.4
                pts = [(x + math.cos(a) * pr * 0.12, y + math.sin(a) * pr * 0.12),
                       (x + math.cos(a + 0.35) * pr * 0.55, y + math.sin(a + 0.35) * pr * 0.55),
                       (x + math.cos(a - 0.10) * pr * 0.92, y + math.sin(a - 0.10) * pr * 0.92)]
                pygame.draw.lines(surf, hot, False, pts, 2)
            pygame.draw.circle(surf, (118, 100, 100), (int(x - pr * 0.36), int(y - pr * 0.38)),
                               max(2, int(pr * 0.20)))
            cx_, cy_ = x - fx_ * pr * 0.9, y - fy_ * pr * 0.9
            pygame.draw.circle(surf, OUTLINE, (int(cx_), int(cy_)), max(4, int(pr * 0.30)))
            pygame.draw.circle(surf, (110, 96, 84), (int(cx_), int(cy_)), max(3, int(pr * 0.26)))
            tip = (cx_ - fx_ * pr * 0.55 + sx_ * pr * 0.2, cy_ - fy_ * pr * 0.55 + sy_ * pr * 0.2)
            pygame.draw.line(surf, (214, 184, 130), (cx_, cy_), tip, 2)
            self._eyes(surf, x, y, pr, fx_, fy_, n=2, spread=0.30, fwd=0.42, sz=0.20,
                       eye_col=(255, 230, 120), t=t)

        elif self.shape == "yellow":
            # --- büyücü göz: çevresinde şarj olan kristaller dönen tek gözlü
            # varlık
            charging = self.shoot_cd < 0.6
            spin = t * 1.6
            for i in range(3):
                a = spin + i * math.tau / 3
                orb = r * (1.25 + (0.18 if charging else 0.0))
                ox_, oy_ = x + math.cos(a) * orb, y + math.sin(a) * orb
                oc = (255, 240, 160) if charging else col
                pygame.draw.polygon(surf, OUTLINE,
                                    [(ox_, oy_ - 5), (ox_ + 4, oy_), (ox_, oy_ + 5), (ox_ - 4, oy_)])
                pygame.draw.polygon(surf, oc,
                                    [(ox_, oy_ - 4), (ox_ + 3, oy_), (ox_, oy_ + 4), (ox_ - 3, oy_)])
            if charging:
                add_glow(surf, x, y, r * 1.9, (255, 240, 160), 0.55)
            pr = r * breathe
            pts = [(x, y - pr), (x + pr, y), (x, y + pr), (x - pr, y)]
            pygame.draw.polygon(surf, OUTLINE, [(x, y - pr - 3), (x + pr + 3, y), (x, y + pr + 3), (x - pr - 3, y)])
            pygame.draw.polygon(surf, col, pts)
            pygame.draw.polygon(surf, lite, [(x, y - pr * 0.55), (x + pr * 0.55, y), (x, y)])
            self._eyes(surf, x, y, pr, fx_, fy_, n=1, fwd=0.26, sz=0.34,
                       eye_col=(255, 252, 226), glow_col=(255, 230, 120) if charging else None, t=t)

        elif self.shape == "tank":
            # --- zırhlı yürüyüşçü: plakalı, perçinli, vizörlü ağır yaratık
            self._legs(surf, x, y, r, fx_, fy_, (70, 60, 92), pairs=2, length=0.5, width=4, spread=0.66)
            rect = pygame.Rect(0, 0, int(r * 1.86 * breathe), int(r * 1.86 * breathe))
            rect.center = (int(x), int(y))
            pygame.draw.rect(surf, OUTLINE, rect.inflate(5, 5), border_radius=7)
            pygame.draw.rect(surf, col, rect, border_radius=7)
            # omuz plakaları
            for s in (-1, 1):
                pl = [(x + sx_ * r * 0.94 * s - fx_ * r * 0.40, y + sy_ * r * 0.94 * s - fy_ * r * 0.40),
                      (x + sx_ * r * 1.16 * s + fx_ * r * 0.10, y + sy_ * r * 1.16 * s + fy_ * r * 0.10),
                      (x + sx_ * r * 0.80 * s + fx_ * r * 0.46, y + sy_ * r * 0.80 * s + fy_ * r * 0.46)]
                pygame.draw.polygon(surf, OUTLINE, [(a + s, b + 1) for a, b in pl])
                pygame.draw.polygon(surf, dark, pl)
            pygame.draw.rect(surf, lite, rect.inflate(-r * 0.9, -r * 0.9), border_radius=4)
            # perçinler
            for cx_, cy_ in ((-1, -1), (1, -1), (-1, 1), (1, 1)):
                rx = x + sx_ * r * 0.62 * cx_ + fx_ * r * 0.62 * cy_
                ry = y + sy_ * r * 0.62 * cx_ + fy_ * r * 0.62 * cy_
                pygame.draw.circle(surf, dark, (int(rx), int(ry)), max(1, int(r * 0.10)))
            # vizör
            vx = x + fx_ * r * 0.72
            vy = y + fy_ * r * 0.72
            pygame.draw.line(surf, (22, 20, 30),
                             (vx - sx_ * r * 0.56, vy - sy_ * r * 0.56),
                             (vx + sx_ * r * 0.56, vy + sy_ * r * 0.56), max(3, int(r * 0.26)))
            self._eyes(surf, x, y, r, fx_, fy_, n=2, spread=0.30, fwd=0.72, sz=0.13,
                       eye_col=(255, 120, 120), glow_col=(255, 80, 80), t=t)

        elif self.shape == "sprinter":
            # --- av köpeği: ileri atılan, kuyruklu, hız izi bırakan yaratık
            mv = math.atan2(fy_, fx_)
            if self.dash_t > 0:
                for k in range(3):
                    ta = 0.34 - k * 0.10
                    add_glow(surf, x - fx_ * (14 + k * 12), y - fy_ * (14 + k * 12), r * 1.5, col, ta)
            self._legs(surf, x, y, r, fx_, fy_, dark, pairs=2, width=2, spread=0.52)
            # kuyruk (gövdeyi bastırmayacak kadar kısa)
            tw = math.sin(self.walk * 2.2) * r * 0.38
            tail = [(x - fx_ * r * 0.72, y - fy_ * r * 0.72),
                    (x - fx_ * r * 1.10 + sx_ * tw * 0.5, y - fy_ * r * 1.10 + sy_ * tw * 0.5),
                    (x - fx_ * r * 1.42 + sx_ * tw, y - fy_ * r * 1.42 + sy_ * tw)]
            pygame.draw.lines(surf, OUTLINE, False, tail, 6)
            pygame.draw.lines(surf, col, False, tail, 3)
            # gövde: daha dolgun, kalçası geniş bir dört ayaklı silueti
            pts = rot_pts([(r * 1.34, 0), (r * 0.52, -r * 0.74), (-r * 0.46, -r * 0.86),
                           (-r * 0.92, 0), (-r * 0.46, r * 0.86), (r * 0.52, r * 0.74)], mv, x, y)
            pygame.draw.polygon(surf, OUTLINE, [(a + (a - x) * .10, b + (b - y) * .10) for a, b in pts])
            pygame.draw.polygon(surf, col, pts)
            # sırt çizgisi
            pygame.draw.line(surf, lite, (x - fx_ * r * 0.5, y - fy_ * r * 0.5),
                             (x + fx_ * r * 0.9, y + fy_ * r * 0.9), 2)
            # kulaklar
            for s in (-1, 1):
                exx = x + fx_ * r * 0.34 + sx_ * r * 0.56 * s
                eyy = y + fy_ * r * 0.34 + sy_ * r * 0.56 * s
                ear = [(exx, eyy),
                       (exx - fx_ * r * 0.48 + sx_ * r * 0.30 * s,
                        eyy - fy_ * r * 0.48 + sy_ * r * 0.30 * s),
                       (exx + sx_ * r * 0.34 * s, eyy + sy_ * r * 0.34 * s)]
                pygame.draw.polygon(surf, OUTLINE, [(a + s, b + 1) for a, b in ear])
                pygame.draw.polygon(surf, dark, ear)
            self._eyes(surf, x, y, r, fx_, fy_, n=2, spread=0.24, fwd=0.62, sz=0.15,
                       eye_col=(255, 235, 255), t=t)

        elif self.shape == "brute":
            # --- dev: geniş omuzlu, iki yumruklu, ağır adımlı yaratık
            step = math.sin(self.walk * 1.1) * r * 0.16
            pts = []
            for i in range(6):
                ang = i * math.tau / 6 + math.pi / 6
                rr = r * breathe * (1.0 + (0.10 if i % 2 == 0 else 0.0))
                pts.append((x + math.cos(ang) * rr, y + math.sin(ang) * rr))
            outer = [(x + (a - x) * 1.14, y + (b - y) * 1.14) for a, b in pts]
            # yumruklar (sırayla öne savrulur)
            for s in (-1, 1):
                sw = step * s
                hx = x + fx_ * (r * 0.72 + sw) + sx_ * r * 1.02 * s
                hy = y + fy_ * (r * 0.72 + sw) + sy_ * r * 1.02 * s
                pygame.draw.circle(surf, OUTLINE, (int(hx), int(hy)), int(r * 0.46))
                pygame.draw.circle(surf, dark, (int(hx), int(hy)), int(r * 0.40))
                pygame.draw.circle(surf, lighten(dark, .3),
                                   (int(hx - fx_ * r * 0.1), int(hy - fy_ * r * 0.1)), max(1, int(r * 0.14)))
            pygame.draw.polygon(surf, OUTLINE, outer)
            pygame.draw.polygon(surf, col, pts)
            pygame.draw.polygon(surf, lite,
                                [(x - fx_ * r * 0.34 - sx_ * r * 0.34, y - fy_ * r * 0.34 - sy_ * r * 0.34),
                                 (x + fx_ * r * 0.10 - sx_ * r * 0.44, y + fy_ * r * 0.10 - sy_ * r * 0.44),
                                 (x + fx_ * r * 0.20, y + fy_ * r * 0.20)])
            self._eyes(surf, x, y, r, fx_, fy_, n=2, spread=0.28, fwd=0.50, sz=0.17,
                       eye_col=(255, 225, 190), t=t)

        elif self.shape == "elite":
            # --- elit: taçlı, yörüngesinde kılıçlar dönen altın şampiyon
            add_glow(surf, x, y, r * 2.0, self.color, .55 + .10 * math.sin(t * 3))
            spin = t * 2
            for i in range(6):
                ang = spin + i * math.tau / 6
                ox_ = x + math.cos(ang) * r * 1.42
                oy_ = y + math.sin(ang) * r * 1.42
                bl = rot_pts([(6, 0), (0, -3), (-6, 0), (0, 3)], ang, ox_, oy_)
                pygame.draw.polygon(surf, OUTLINE, bl)
                pygame.draw.polygon(surf, GOLD, bl)
            self._legs(surf, x, y, r, fx_, fy_, (120, 96, 40), pairs=2, width=4, spread=0.60)
            pr = r * breathe
            pygame.draw.circle(surf, OUTLINE, (int(x), int(y)), int(pr + 3))
            pygame.draw.circle(surf, col, (int(x), int(y)), int(pr))
            pygame.draw.circle(surf, GOLD, (int(x), int(y)), int(pr), 3)
            pygame.draw.circle(surf, lighten(col, .3),
                               (int(x - pr * .32), int(y - pr * .32)), max(2, int(pr * .28)))
            # taç
            for k in (-1, 0, 1):
                bxp = x - fx_ * pr * 0.72 + sx_ * pr * 0.40 * k
                byp = y - fy_ * pr * 0.72 + sy_ * pr * 0.40 * k
                tip = (bxp - fx_ * pr * 0.42, byp - fy_ * pr * 0.42)
                pygame.draw.polygon(surf, OUTLINE,
                                    [(bxp - sx_ * 4, byp - sy_ * 4), tip, (bxp + sx_ * 4, byp + sy_ * 4)])
                pygame.draw.polygon(surf, GOLD,
                                    [(bxp - sx_ * 3, byp - sy_ * 3), tip, (bxp + sx_ * 3, byp + sy_ * 3)])
            self._eyes(surf, x, y, pr, fx_, fy_, n=2, spread=0.28, fwd=0.44, sz=0.18,
                       eye_col=(255, 250, 220), glow_col=(255, 220, 120), t=t)

        elif self.shape == "herald":
            # --- sancaktar (yarı patron): sırtında sandık taşıyan sancak
            # taşıyıcı.
            guarded = self.live_guards()
            if guarded:
                dome = 0.5 + 0.5 * math.sin(t * 2.6)
                add_glow(surf, x, y, r * 2.3, self.color, 0.24 + 0.16 * dome)
                for i in range(2):
                    rr = int(r * (1.85 + i * 0.22) + dome * 3)
                    pygame.draw.circle(surf, scale_col(self.color, 0.30 + 0.30 * dome),
                                       (int(x), int(y)), rr, 2)
                # kubbeyi besleyen ışık telleri: sancaktardan her siperciye
                for g in self.guards:
                    if g.alive:
                        pygame.draw.line(surf, scale_col(self.color, 0.22 + 0.30 * dome),
                                         (x, y), (g.x, g.y), 2)
            else:
                add_glow(surf, x, y, r * 1.6, self.color, 0.30)
            self._legs(surf, x, y, r, fx_, fy_, (128, 106, 50), pairs=2, width=4, spread=0.58)
            pr = r * breathe
            # gövde: omuzları geniş, zırhlı bir taşıyıcı
            body = [(x + fx_ * pr * 0.62 + sx_ * pr * 0.72, y + fy_ * pr * 0.62 + sy_ * pr * 0.72),
                    (x - fx_ * pr * 0.80 + sx_ * pr * 0.62, y - fy_ * pr * 0.80 + sy_ * pr * 0.62),
                    (x - fx_ * pr * 0.80 - sx_ * pr * 0.62, y - fy_ * pr * 0.80 - sy_ * pr * 0.62),
                    (x + fx_ * pr * 0.62 - sx_ * pr * 0.72, y + fy_ * pr * 0.62 - sy_ * pr * 0.72)]
            pygame.draw.polygon(surf, OUTLINE, body)
            pygame.draw.polygon(surf, col, body)
            pygame.draw.polygon(surf, lighten(col, 0.30), body, 2)
            # sırttaki sandık - ödülü taşıdığı belli olsun
            cbx = x - fx_ * pr * 0.92
            cby = y - fy_ * pr * 0.92
            cw_, ch_ = pr * 0.62, pr * 0.46
            chest = [(cbx + sx_ * cw_ + fx_ * ch_, cby + sy_ * cw_ + fy_ * ch_),
                     (cbx + sx_ * cw_ - fx_ * ch_, cby + sy_ * cw_ - fy_ * ch_),
                     (cbx - sx_ * cw_ - fx_ * ch_, cby - sy_ * cw_ - fy_ * ch_),
                     (cbx - sx_ * cw_ + fx_ * ch_, cby - sy_ * cw_ + fy_ * ch_)]
            pygame.draw.polygon(surf, OUTLINE, chest)
            pygame.draw.polygon(surf, (126, 86, 48), chest)
            pygame.draw.polygon(surf, GOLD, chest, 2)
            pygame.draw.circle(surf, GOLD, (int(cbx), int(cby)), max(2, int(pr * 0.14)))
            # sancak: yana uzanan direk + dalgalanan bayrak
            px_ = x + sx_ * pr * 0.95
            py_ = y + sy_ * pr * 0.95
            tipx = px_ - fx_ * pr * 0.30 - sy_ * 0
            top = (px_ + (-fy_) * 0, py_ + 0)
            polx, poly = px_, py_ - pr * 1.9
            pygame.draw.line(surf, (92, 74, 48), (px_, py_), (polx, poly), 4)
            pygame.draw.circle(surf, GOLD, (int(polx), int(poly - 3)), 4)
            wave_ = math.sin(t * 4 + self.wobble) * pr * 0.20
            flag = [(polx, poly + 2), (polx + pr * 0.95 + wave_, poly + pr * 0.30),
                    (polx + pr * 0.80 - wave_, poly + pr * 0.62), (polx, poly + pr * 0.78)]
            pygame.draw.polygon(surf, OUTLINE, flag)
            pygame.draw.polygon(surf, (206, 72, 82), flag)
            pygame.draw.polygon(surf, GOLD, flag, 2)
            # miğfer + gözler
            pygame.draw.circle(surf, OUTLINE, (int(x + fx_ * pr * 0.22), int(y + fy_ * pr * 0.22)),
                               int(pr * 0.56 + 2))
            pygame.draw.circle(surf, lighten(col, 0.16),
                               (int(x + fx_ * pr * 0.22), int(y + fy_ * pr * 0.22)), int(pr * 0.56))
            self._eyes(surf, x + fx_ * pr * 0.22, y + fy_ * pr * 0.22, pr * 0.56, fx_, fy_,
                       n=2, spread=0.32, fwd=0.42, sz=0.24,
                       eye_col=(255, 250, 220), glow_col=(255, 220, 130), t=t)

        elif self.shape == "shieldman":
            # --- siperci: önünde kule kalkanı taşıyan, hiç vurmayan kalkanlı.
            # Kalkan, koruduğu sancaktardan dışa bakar; yani oyuncuya karşı
            # durur.
            bf = self.block_flash
            # kalkanın baktığı yön: sancaktar varsa ondan dışa, yoksa oyuncuya
            g = self.guard_of
            if g is not None and g.alive:
                sdx, sdy = norm_dir(g.x, g.y, self.x, self.y)
            else:
                sdx, sdy = fx_, fy_
            snx, sny = -sdy, sdx
            pr = r * breathe
            self._legs(surf, x, y, r, fx_, fy_, (62, 84, 112), pairs=2, width=4, spread=0.52)
            # gövde
            pygame.draw.circle(surf, OUTLINE, (int(x), int(y)), int(pr * 0.86 + 2))
            pygame.draw.circle(surf, col, (int(x), int(y)), int(pr * 0.86))
            self._eyes(surf, x, y, pr * 0.86, fx_, fy_, n=2, spread=0.30, fwd=0.30, sz=0.18,
                       eye_col=(226, 244, 255), t=t)
            # kule kalkanı - gövdeden öne taşan, uzun altıgen levha
            cx_ = x + sdx * (pr * 0.92)
            cy_ = y + sdy * (pr * 0.92)
            hw = pr * 0.96          # kalkanın yarı genişliği
            hl = pr * 0.40          # kalkanın kalınlığı
            shield = [(cx_ + snx * hw - sdx * hl, cy_ + sny * hw - sdy * hl),
                      (cx_ + snx * hw * 0.72 + sdx * hl, cy_ + sny * hw * 0.72 + sdy * hl),
                      (cx_ - snx * hw * 0.72 + sdx * hl, cy_ - sny * hw * 0.72 + sdy * hl),
                      (cx_ - snx * hw - sdx * hl, cy_ - sny * hw - sdy * hl)]
            face = WHITE if bf > 0 else (196, 216, 240)
            if bf > 0:
                add_glow(surf, cx_, cy_, pr * 2.0, (200, 230, 255), clamp(bf * 3.2, 0, 0.9))
            pygame.draw.polygon(surf, OUTLINE, shield)
            pygame.draw.polygon(surf, face, shield)
            pygame.draw.polygon(surf, scale_col(col, 0.75), shield, 2)
            # kalkanın ortasındaki kabartma
            pygame.draw.line(surf, scale_col(col, 0.70),
                             (cx_ + snx * hw * 0.80, cy_ + sny * hw * 0.80),
                             (cx_ - snx * hw * 0.80, cy_ - sny * hw * 0.80), 3)
            pygame.draw.circle(surf, scale_col(col, 0.85), (int(cx_), int(cy_)),
                               max(2, int(pr * 0.22)))
            pygame.draw.circle(surf, WHITE, (int(cx_), int(cy_)), max(1, int(pr * 0.10)))

        else:
            # Güvenlik ağı: tanımsız yeni bir tür eklenirse yine de canlı
            # görünsün.
            pr = r * breathe
            pygame.draw.circle(surf, OUTLINE, (int(x), int(y)), int(pr + 2))
            pygame.draw.circle(surf, col, (int(x), int(y)), int(pr))
            self._eyes(surf, x, y, pr, fx_, fy_, n=2, spread=0.30, fwd=0.40, sz=0.18, t=t)

        # ---- cehennem görselliği ----
        # Cehennem yaratıkları aynı iskeleti kullansa bile bambaşka okunsun:
        # boynuzlar, gövdede akkor çatlaklar ve yukarı süzülen kor zerreleri.
        if self.hellish:
            ember = (255, 150, 60)
            add_glow(surf, x, y, r * 2.1, ember, 0.16 + 0.06 * math.sin(t * 4 + self.wobble))
            # boynuzlar
            for sgn in (-1, 1):
                bx0 = x - fx_ * r * 0.55 + sx_ * r * 0.55 * sgn
                by0 = y - fy_ * r * 0.55 + sy_ * r * 0.55 * sgn
                tipx = bx0 - fx_ * r * 0.70 + sx_ * r * 0.42 * sgn
                tipy = by0 - fy_ * r * 0.70 + sy_ * r * 0.42 * sgn
                pygame.draw.polygon(surf, OUTLINE,
                                    [(bx0 - sx_ * 4, by0 - sy_ * 4), (tipx, tipy),
                                     (bx0 + sx_ * 4, by0 + sy_ * 4)])
                pygame.draw.polygon(surf, (236, 226, 214),
                                    [(bx0 - sx_ * 3, by0 - sy_ * 3), (tipx, tipy),
                                     (bx0 + sx_ * 3, by0 + sy_ * 3)])
            # akkor çatlaklar
            for i in range(3):
                a = self.wobble + i * 2.1
                cx0 = x + math.cos(a) * r * 0.30
                cy0 = y + math.sin(a) * r * 0.30
                cx1 = x + math.cos(a + 0.9) * r * 0.80
                cy1 = y + math.sin(a + 0.9) * r * 0.80
                pygame.draw.line(surf, ember, (cx0, cy0), (cx1, cy1), 2)
            # kor zerreleri
            for i in range(3):
                ph = (t * 0.9 + i * 0.33 + self.wobble * 0.2) % 1.0
                ex = x + math.sin(t * 2.0 + i * 2.4 + self.wobble) * r * 0.75
                ey = y - r * 0.5 - ph * r * 1.6
                blit_disc(surf, ex, ey, max(1.0, 2.6 * (1.0 - ph)), (255, 190, 90),
                          int(200 * (1.0 - ph)))

        if self.shape in ARENA_GEAR and not self.hellish:
            self._arena_gear(surf, x, y, r, t, flash, breathe)

        # ---- durum halkaları ----
        if self.slow_timer > 0:
            pygame.draw.circle(surf, CYAN, (int(x), int(y)), int(r + 4), 1)
        if self.burn_timer > 0:
            pygame.draw.circle(surf, ORANGE, (int(x), int(y)), int(r + 6), 1)
        if self.poison_dps > 0:
            # zehir: yukarı süzülen kabarcıklar + yeşil halka
            pygame.draw.circle(surf, (120, 225, 90), (int(x), int(y)), int(r + 8), 1)
            for i in range(3):
                bph = (t * 1.3 + i * 0.37 + self.wobble) % 1.0
                bxp = x + math.sin(t * 2.4 + i * 2.1) * r * 0.6
                byp = y - r * 0.4 - bph * r * 1.5
                pygame.draw.circle(surf, (150, 240, 120), (int(bxp), int(byp)),
                                   max(1, int(3 * (1.0 - bph))))

        if self.hp < self.max_hp:
            w = r * 2
            bx, by = x - w / 2, y - r - 12
            pygame.draw.rect(surf, (30, 30, 40), (bx, by, w, 4), border_radius=2)
            frac = clamp(self.hp / self.max_hp, 0, 1)
            hc = GREEN if frac > 0.5 else (ORANGE if frac > 0.25 else RED)
            pygame.draw.rect(surf, hc, (bx, by, w * frac, 4), border_radius=2)

