# ---- kayıp kervan ----
# Koşuların bir kısmında 2-4. dalga arasında haritanın bir ucundan öbürüne
# yavaşça bir kervan geçer. Yanında iki saniye durursan durur: altın + bir el
# efsanevi kart. Kaçarsa bir daha gelmez.
CARAVAN_CHANCE = 0.40
CARAVAN_SPEED = 52.0
CARAVAN_R = 78.0
CARAVAN_CHARGE = 2.0
CARAVAN_COLOR = (226, 170, 90)


class Caravan:
    def __init__(self, x0, y0, x1, y1):
        self.x, self.y = x0, y0
        self.x1, self.y1 = x1, y1
        d = dist(x0, y0, x1, y1) or 1.0
        self.dx, self.dy = (x1 - x0) / d, (y1 - y0) / d
        self.charge = 0.0
        self.stopped = False
        self.gone = False
        self.fade = 0.0
        self.wheel = 0.0

    def update(self, dt):
        if self.stopped or self.gone:
            self.fade += dt
            return
        self.x += self.dx * CARAVAN_SPEED * dt
        self.y += self.dy * CARAVAN_SPEED * dt
        self.wheel += dt * CARAVAN_SPEED / 14.0
        if (self.x1 - self.x) * self.dx + (self.y1 - self.y) * self.dy <= 0:
            self.gone = True

    def draw(self, surf, t):
        a = 1.0 - clamp(self.fade / 1.0, 0.0, 1.0) if self.gone else 1.0
        if a <= 0:
            return
        x, y = self.x, self.y
        face = 1 if self.dx >= 0 else -1
        # durma dairesi
        if not self.stopped:
            ring = pygame.Surface((int(CARAVAN_R * 2 + 8), int(CARAVAN_R * 2 + 8)), pygame.SRCALPHA)
            c = int(CARAVAN_R + 4)
            pygame.draw.circle(ring, (*CARAVAN_COLOR, int(28 * a)), (c, c), int(CARAVAN_R))
            pygame.draw.circle(ring, (*CARAVAN_COLOR, int(150 * a)), (c, c), int(CARAVAN_R), 2)
            surf.blit(ring, (int(x - c), int(y - c)))
            if self.charge > 0:
                rect = pygame.Rect(0, 0, int(CARAVAN_R * 2 + 10), int(CARAVAN_R * 2 + 10))
                rect.center = (int(x), int(y))
                pygame.draw.arc(surf, WHITE, rect, math.pi / 2,
                                math.pi / 2 + math.tau * clamp(self.charge / CARAVAN_CHARGE, 0, 1), 5)
        bob = math.sin(t * 6) * 1.5 if not self.stopped else 0.0
        # gölge
        pygame.draw.ellipse(surf, (0, 0, 0), (int(x - 46), int(y + 14), 92, 16))
        # eşek
        hx = x + face * 44
        pygame.draw.ellipse(surf, INK, (int(hx - 17), int(y - 9 + bob), 34, 22))
        pygame.draw.ellipse(surf, (140, 122, 112), (int(hx - 15), int(y - 7 + bob), 30, 18))
        head = (hx + face * 16, y - 12 + bob)
        pygame.draw.circle(surf, INK, (int(head[0]), int(head[1])), 10)
        pygame.draw.circle(surf, (150, 132, 120), (int(head[0]), int(head[1])), 8)
        for ex in (-3, 3):
            pygame.draw.line(surf, INK, (head[0] + ex, head[1] - 6), (head[0] + ex - face * 2, head[1] - 17), 4)
        pygame.draw.circle(surf, (24, 18, 20), (int(head[0] + face * 3), int(head[1] - 1)), 2)
        for lx in (-9, 9):
            ph = math.sin(t * 8 + lx) * 3 if not self.stopped else 0
            pygame.draw.line(surf, INK, (hx + lx, y + 8), (hx + lx + ph, y + 18), 4)
        # araba
        body = pygame.Rect(0, 0, 70, 30)
        body.center = (int(x - face * 6), int(y - 4))
        pygame.draw.rect(surf, INK, body.inflate(6, 6), border_radius=6)
        pygame.draw.rect(surf, (128, 84, 52), body, border_radius=5)
        for k in range(1, 4):
            pygame.draw.line(surf, (98, 62, 38), (body.x + k * 17, body.y + 3), (body.x + k * 17, body.bottom - 3), 2)
        # branda
        cov = pygame.Rect(body.x + 2, body.y - 26, body.w - 4, 34)
        pygame.draw.ellipse(surf, INK, cov.inflate(6, 6))
        pygame.draw.ellipse(surf, (232, 214, 176), cov)
        pygame.draw.ellipse(surf, (206, 184, 140), cov.inflate(-18, -14))
        pygame.draw.rect(surf, (232, 214, 176), (cov.x, cov.centery, cov.w, cov.h // 2))
        pygame.draw.line(surf, INK, (cov.x, cov.centery + cov.h // 2), (cov.right, cov.centery + cov.h // 2), 3)
        # fener
        lx_, ly_ = body.right - 4 if face > 0 else body.x + 4, body.y - 6
        add_glow(surf, lx_, ly_, 26, (255, 210, 120), 0.45 * a)
        pygame.draw.circle(surf, (255, 220, 140), (int(lx_), int(ly_)), 4)
        # tekerlekler
        for wx in (body.x + 14, body.right - 14):
            wy = body.bottom + 4
            pygame.draw.circle(surf, INK, (int(wx), int(wy)), 12)
            pygame.draw.circle(surf, (96, 62, 38), (int(wx), int(wy)), 10)
            for k in range(4):
                ang = self.wheel + k * math.pi / 4
                pygame.draw.line(surf, INK, (wx - math.cos(ang) * 9, wy - math.sin(ang) * 9),
                                 (wx + math.cos(ang) * 9, wy + math.sin(ang) * 9), 2)
            pygame.draw.circle(surf, (210, 170, 110), (int(wx), int(wy)), 3)
        # sandıklar
        if not self.stopped:
            for i_, cc in enumerate(((176, 120, 60), (210, 170, 90))):
                br = pygame.Rect(0, 0, 14, 11)
                br.midbottom = (body.x + 12 + i_ * 16, body.y + 2)
                pygame.draw.rect(surf, INK, br.inflate(4, 4), border_radius=3)
                pygame.draw.rect(surf, cc, br, border_radius=2)


_SHRINE_BEAM = {}


def _shrine_beam(col):
    img = _SHRINE_BEAM.get(col)
    if img is None:
        img = pygame.Surface((26, 150), pygame.SRCALPHA)
        for k in range(150):
            pygame.draw.line(img, (*col, int(70 * k / 150.0)), (13 - 6 * k / 150, k), (13 + 6 * k / 150, k))
        _SHRINE_BEAM[col] = img
    return img


class PowerShrine:
    def __init__(self, x, y, kind, born):
        self.x, self.y = x, y
        self.kind = kind
        self.born = born
        self.charge = 0.0
        self.used = False
        self.fade = 0.0                 # kullanıldıktan / söndükten sonra kaybolma

    def color(self):
        return SHRINE_KINDS[self.kind][0]

    def draw(self, surf, t):
        col = self.color()
        x, y = self.x, self.y
        a = 1.0 - clamp(self.fade / 0.8, 0.0, 1.0)
        if a <= 0:
            return
        # zemindeki rün çemberi
        rr = SHRINE_R
        ring = pygame.Surface((int(rr * 2 + 8), int(rr * 2 + 8)), pygame.SRCALPHA)
        c = rr + 4
        pygame.draw.circle(ring, (*col, int(40 * a)), (int(c), int(c)), int(rr))
        pygame.draw.circle(ring, (*INK, int(160 * a)), (int(c), int(c)), int(rr), 3)
        pygame.draw.circle(ring, (*col, int(200 * a)), (int(c), int(c)), int(rr - 3), 2)
        for i in range(8):
            ang = t * 0.5 + i * math.tau / 8
            px, py = c + math.cos(ang) * (rr - 12), c + math.sin(ang) * (rr - 12)
            pygame.draw.circle(ring, (*lighten(col, 0.3), int(170 * a)), (int(px), int(py)), 3)
        surf.blit(ring, (int(x - c), int(y - c)))
        # dolum yayı
        if self.charge > 0 and not self.used:
            rect = pygame.Rect(0, 0, int(rr * 2 + 10), int(rr * 2 + 10))
            rect.center = (int(x), int(y))
            pygame.draw.arc(surf, WHITE, rect, math.pi / 2,
                            math.pi / 2 + math.tau * clamp(self.charge / SHRINE_CHARGE, 0, 1), 5)
        # gökyüzüne uzanan ışık sütunu (uzaktan görünsün)
        if not self.used:
            beam = _shrine_beam(col)
            beam.set_alpha(int(255 * a * (0.7 + 0.3 * math.sin(t * 3))))
            surf.blit(beam, (int(x - 13), int(y - 168)))
        # taş kaide
        base = pygame.Rect(0, 0, 40, 22)
        base.midbottom = (int(x), int(y + 10))
        pygame.draw.rect(surf, INK, base.inflate(6, 6), border_radius=6)
        pygame.draw.rect(surf, (96, 84, 80), base, border_radius=5)
        pygame.draw.rect(surf, (128, 114, 106), (base.x + 3, base.y + 2, base.w - 6, 5), border_radius=3)
        top = pygame.Rect(0, 0, 30, 10)
        top.midbottom = base.midtop
        pygame.draw.rect(surf, INK, top.inflate(6, 6), border_radius=4)
        pygame.draw.rect(surf, (112, 100, 94), top, border_radius=3)
        # süzülen kristal + simge
        bob = math.sin(t * 2.4 + self.born) * 4
        cy = y - 38 + bob
        if not self.used:
            add_glow(surf, x, cy, 40, col, 0.40 * a)
        pts = [(x, cy - 17), (x + 12, cy), (x, cy + 17), (x - 12, cy)]
        pygame.draw.polygon(surf, INK, [(px * 1.0 + (2 if px > x else -2 if px < x else 0),
                                         py + (2 if py > cy else -2 if py < cy else 0)) for px, py in pts])
        pygame.draw.polygon(surf, col if not self.used else scale_col(col, 0.4), pts)
        pygame.draw.polygon(surf, lighten(col, 0.5), [(x, cy - 17), (x + 5, cy - 3), (x, cy)])
        draw_icon(surf, x, cy + 1, SHRINE_KINDS[self.kind][1], INK, 6)


# ---- harita bulguları ----
# Koşuyu iyi ya da kötü yapan, haritada rastgele çıkan şeyler. Her koşuda
# hepsi gelmez: biri rafı erkenden bulur, öbürü hiçbirini görmez. Hepsi
# oyuncuyu yürütür; uzakta durur, başında beklemek ister.
# tür -> (koşuda çıkma olasılığı, en erken dalga, en geç dalga, bekleme
#        süresi, ömür, renk, simge)
FIND_KINDS = {
    "rack":  (0.45, 1, 3, 1.2, 150.0, (214, 170, 110), "sword"),
    "map":   (0.35, 2, 6, 0.0, 180.0, (232, 206, 150), "target"),
    "sword": (0.35, 3, 7, 4.0, 220.0, (196, 214, 240), "sword"),
    "trial": (0.40, 4, 11, 1.0, 180.0, (236, 90, 80), "skull"),
    "anvil": (0.40, 5, 10, 2.0, 200.0, (255, 150, 70), "fist"),
    "dig":   (0.0, 0, 0, 3.0, 150.0, (226, 120, 80), "target"),
}
FIND_R = 58.0
FIND_SWORD_DMG = 0.15
FIND_TRIAL_T = 25.0
FIND_TRIAL_EVERY = 3.0
FIND_LABEL_D = 330.0            # bu kadar yakındayken adı ve ödülü yazar


class MapFind:
    def __init__(self, kind, x, y, born):
        self.kind = kind
        self.x, self.y = x, y
        self.born = born
        self.charge = 0.0
        self.used = False
        self.fade = 0.0

    def spec(self):
        return FIND_KINDS[self.kind]

    def color(self):
        return FIND_KINDS[self.kind][5]

    def need(self):
        return FIND_KINDS[self.kind][3]

    def draw(self, surf, t, near):
        a = 1.0 - clamp(self.fade / 0.8, 0.0, 1.0)
        if a <= 0:
            return
        col = self.color()
        x, y = self.x, self.y
        k = self.kind
        if self.need() > 0 and not self.used:
            rr = FIND_R
            ring = pygame.Surface((int(rr * 2 + 8), int(rr * 2 + 8)), pygame.SRCALPHA)
            c = rr + 4
            pygame.draw.circle(ring, (*col, int(30 * a)), (int(c), int(c)), int(rr))
            pygame.draw.circle(ring, (*INK, int(140 * a)), (int(c), int(c)), int(rr), 3)
            pygame.draw.circle(ring, (*col, int(170 * a)), (int(c), int(c)), int(rr - 3), 2)
            surf.blit(ring, (int(x - c), int(y - c)))
            if self.charge > 0:
                rect = pygame.Rect(0, 0, int(rr * 2 + 10), int(rr * 2 + 10))
                rect.center = (int(x), int(y))
                pygame.draw.arc(surf, WHITE, rect, math.pi / 2,
                                math.pi / 2 + math.tau * clamp(self.charge / self.need(), 0, 1), 5)
        pygame.draw.ellipse(surf, (0, 0, 0), (int(x - 30), int(y + 6), 60, 14))
        getattr(self, "_draw_" + k)(surf, x, y, t, col, a)
        if near and not self.used:
            # adı altta: oyuncunun üstünde çıkan yazılarla çakışmasın
            ly = y + FIND_R + 14
            draw_text(surf, L("fd." + k), (x, ly), 15, lighten(col, 0.25), bold=True, center=True)
            draw_text(surf, L("fd.%s.d" % k), (x, ly + 19), 12, TEXT, center=True)

    def _draw_rack(self, surf, x, y, t, col, a):
        wood, dark = (150, 102, 62), (104, 68, 40)
        for px in (-26, 26):
            pygame.draw.line(surf, INK, (x + px, y + 8), (x + px * 0.8, y - 46), 9)
            pygame.draw.line(surf, wood, (x + px, y + 8), (x + px * 0.8, y - 46), 5)
