        pygame.draw.line(surf, (226, 186, 90), (x - 19, y - 6), (x - 5, y - 7), 3)
        # balta
        pygame.draw.line(surf, INK, (x + 2, y + 6), (x + 4, y - 52), 7)
        pygame.draw.line(surf, wood, (x + 2, y + 4), (x + 4, y - 50), 3)
