    def _draw_dig(self, surf, x, y, t, col, a):
        pygame.draw.ellipse(surf, INK, (int(x - 34), int(y - 12), 68, 26))
        pygame.draw.ellipse(surf, (122, 90, 62), (int(x - 31), int(y - 10), 62, 21))
