# marka görselleri - EvolveArena logosu ve ikonu (, yenilendi).
_BRAND_CACHE = {}


def brand_image(name):
    """'logo' | 'icon' | 'badge' - ham (ölçeklenmemiş) yüzey ya da None."""
    if name in _BRAND_CACHE:
        return _BRAND_CACHE[name]
    img = None
    try:
        data = {"logo": EMBED_LOGO_PNG, "icon": EMBED_ICON_PNG,
                "badge": EMBED_BADGE_PNG}[name]
        raw = base64.b64decode("".join(data.split()))
        img = pygame.image.load(io.BytesIO(raw), "brand.png")
        if pygame.display.get_surface() is not None:
            img = img.convert_alpha()
    except Exception:
        img = None
    _BRAND_CACHE[name] = img
    return img


def brand_scaled(name, w=None, h=None):
    """Logoyu/ikonu istenen genişliğe (ya da yüksekliğe) ölçekler, önbellekler."""
    key = (name, None if w is None else int(w), None if h is None else int(h))
    img = _BRAND_CACHE.get(key)
    if img is not None:
        return img
    src = brand_image(name)
    if src is None:
        return None
    sw, sh = src.get_size()
    if w is not None:
        size = (int(w), max(1, int(sh * w / sw)))
    else:
        size = (max(1, int(sw * h / sh)), int(h))
    try:
        img = pygame.transform.smoothscale(src, size)
    except Exception:
        img = pygame.transform.scale(src, size)
    _BRAND_CACHE[key] = img
    return img


def set_window_icon():
    """Pencere / görev çubuğu ikonu."""
    try:
        ic = brand_image("icon")
        if ic is not None:
            pygame.display.set_icon(pygame.transform.smoothscale(ic, (64, 64)))
    except Exception:
        pass


class Display:
    """Oyun hep 1280x720'ye çizilir, sonra pencereye ölçeklenir."""

    def __init__(self, save):
        self.save = save
        self.fullscreen = bool(save.data.get("settings", {}).get("fullscreen", False))
        self.scaled_mode = False
        set_window_icon()           # set_mode'dan önce: Windows ilk ikonu buradan alır
        self.screen = self._make_screen()
        pygame.display.set_caption(f"{GAME_TITLE}  v{GAME_VERSION}")
        _BRAND_CACHE.clear()        # ekran açıldı: convert_alpha'lı sürümler yüklensin
        if IS_WEB or SCREEN_W != VIRTUAL_W:
            # Tarayıcıda ekran yüzeyinin kendisine çizilir: her karede tam
            # ekranlık bir kopya (tuval -> ekran) eksik.
            if SAFE_X:
                self.canvas = self.screen.subsurface((SAFE_X, 0, VIRTUAL_W, VIRTUAL_H))
            else:
                self.canvas = self.screen
            web_call("setSafe", SAFE_X)
        else:
            self.canvas = pygame.Surface((VIRTUAL_W, VIRTUAL_H)).convert()
        self.scale = 1.0
        self.offset = (0, 0)
        self.out_size = (VIRTUAL_W, VIRTUAL_H)
        # Kontrolcü etkinken ana döngü buraya sanal imleci yazar; None ise fare
        # kullanılır.
        self.pad_cursor = None
        self._compute_scale()

    def _make_screen(self, size=None):
        """Ekranı açar."""
        if IS_WEB or SCREEN_W != VIRTUAL_W:
            # Tarayıcıda pencere yok: tuval telefonun oranında (SCREEN_W x
            # 720), sayfa onu ekrana sığdırır (ölçekleme CSS'te, ekran
            # kartında).
            self.scaled_mode = True
            return pygame.display.set_mode((SCREEN_W, VIRTUAL_H))
        flags = pygame.FULLSCREEN if self.fullscreen else pygame.RESIZABLE
        want = (0, 0) if self.fullscreen else (size or (VIRTUAL_W, VIRTUAL_H))
        # dikey senkron (vsync): açıkken FPS monitörün yenileme hızında (ör.
        # 144) takılır. Varsayılan KAPALI: sınır yalnız FPS SINIRI ayarıdır.
        vs = 1 if bool(self.save.data.get("settings", {}).get("vsync", False)) else 0
        try:
            try:
                sc = pygame.display.set_mode((VIRTUAL_W, VIRTUAL_H),
                                             flags | pygame.SCALED, vsync=vs)
            except TypeError:
                sc = pygame.display.set_mode((VIRTUAL_W, VIRTUAL_H),
                                             flags | pygame.SCALED)
            self.scaled_mode = True
            return sc
        except Exception:
            self.scaled_mode = False
            return pygame.display.set_mode(want, flags)

    def _compute_scale(self):
        if self.scaled_mode:
            # SDL ölçekliyor: oyun için ekran tam olarak 1280x720.
            self.scale = 1.0
            self.offset = (0, 0)
            self.out_size = (VIRTUAL_W, VIRTUAL_H)
            return
        sw, sh = self.screen.get_size()
        sw, sh = max(sw, 1), max(sh, 1)
        scale = max(min(sw / VIRTUAL_W, sh / VIRTUAL_H), 0.1)
        self.scale = scale
        out_w, out_h = int(VIRTUAL_W * scale), int(VIRTUAL_H * scale)
        self.offset = ((sw - out_w) // 2, (sh - out_h) // 2)
        self.out_size = (out_w, out_h)

    def toggle_fullscreen(self):
        if IS_WEB:
            return          # telefonda uygulama zaten tam ekran açılır
        self.fullscreen = not self.fullscreen
        try:
            self.screen = self._make_screen()
        except Exception:
            self.fullscreen = not self.fullscreen
        # set_mode bazı sürücülerde imleci yeniden görünür yapıyor: gizle.
        try:
            pygame.mouse.set_visible(False)
        except Exception:
            pass
        self.save.data.setdefault("settings", {})["fullscreen"] = self.fullscreen
        self.save.save()
        self._compute_scale()

    def reopen(self):
        """Ekranı aynı ayarlarla yeniden açar (vsync değişince)."""
        try:
            self.screen = self._make_screen()
            pygame.mouse.set_visible(False)
        except Exception as e:
            print("ekran yeniden açılamadı:", repr(e))
        self._compute_scale()

    def handle_resize(self, size):
        # SCALED kipinde boyutlandırmayı SDL kendi hallediyor; set_mode'u
        # yeniden çağırmak gereksiz (ve bazı sürücülerde pencereyi titretiyor).
        if not self.fullscreen and not self.scaled_mode:
            try:
                self.screen = pygame.display.set_mode(size, pygame.RESIZABLE)
            except Exception:
                pass
        self._compute_scale()

    def fill_strips(self, mode="menu"):
        """Çentik payı şeritleri (güvenli alanın iki yanı)."""
        if not SAFE_X or self.canvas is self.screen:
            return
        # Menüde şeritlere fill_strips'ten başka hiçbir şey çizmez: kenar
        # sütunu 4 karede bir uzatmak yeter (çentiğin altında, göze batmaz).
        self._strip_n = getattr(self, "_strip_n", 0) + 1
        if mode == "menu" and getattr(self, "_strip_mode", None) == "menu" and self._strip_n % 4:
            return
        self._strip_mode = mode
        scr, h = self.screen, VIRTUAL_H
        right = SAFE_X + VIRTUAL_W
        if mode == "menu":
            spans = ((0, h),)
        else:
            dark = (23, 17, 18)
            for dx in (0, right):
                scr.fill(dark, (dx, 0, SAFE_X, VIEW_RECT.y))
                scr.fill(dark, (dx, VIEW_RECT.bottom, SAFE_X, h - VIEW_RECT.bottom))
            if mode == "play":
                return
            spans = ((VIEW_RECT.y, VIEW_RECT.bottom),)
        for (y0, y1) in spans:
            if y1 - y0 <= 0:
                continue
            for src_x, dst_x in ((SAFE_X, 0), (right - 1, right)):
                col = scr.subsurface((src_x, y0, 1, y1 - y0))
                scr.blit(pygame.transform.scale(col, (SAFE_X, y1 - y0)), (dst_x, y0))

    def present(self):
        if self.canvas is self.screen or self.canvas.get_parent() is self.screen:
            pygame.display.flip()
            return
        if abs(self.scale - 1.0) < 1e-3 and self.offset == (0, 0):
            self.screen.blit(self.canvas, (0, 0))
        else:
            self.screen.fill((0, 0, 0))
            self.screen.blit(pygame.transform.scale(self.canvas, self.out_size),
                             self.offset)
        pygame.display.flip()

    def virtual_mouse(self):
        # Kontrolcü etkinse imleç ondan gelir.
        if self.pad_cursor is not None:
            return self.pad_cursor
        mx, my = pygame.mouse.get_pos()
        if self.scaled_mode:
            # SCALED kipinde SDL fare konumunu zaten sanal çözünürlüğe
            # çeviriyor.
            return (float(mx), float(my))
        vx = (mx - self.offset[0]) / self.scale if self.scale else 0
        vy = (my - self.offset[1]) / self.scale if self.scale else 0
        return (vx, vy)


