# ---- haritalar - "her koşu aynı başlamasın" ----
# Arena her koşuda rastgele bir haritada açılır. Hepsi aynı 3x3 dünya ve aynı
# kadim mühür; ama zemin, hava, renkler ve küçük bir harita kuralı değişir:
#   taş meydan: klasik arena, kural yok.
#   buzul vadisi: yaratıklar %10 yavaş ama %10 dayanıklı; kar yağar.
#   zümrüt orman: +%12 tecrübe ama yaratıklar %12 daha sık doğar; ateş
#      böcekleri.
#   kızıl çöl: +%15 altın ama yaratıklar %8 hızlı; kum rüzgârı.
MAP_THEMES = ("stone", "frost", "jungle", "desert")
MAP_FLOOR_KEY = {"stone": "arena", "frost": "frost", "jungle": "jungle", "desert": "desert"}
MAP_THEME_COLOR = {"stone": (130, 160, 255), "frost": (170, 225, 255),
                   "jungle": (120, 230, 130), "desert": (255, 186, 100)}
MAP_THEME_ICON = {"stone": "shield", "frost": "snow", "jungle": "clover", "desert": "flame"}

# harita kilidi: "1. haritayı bitirince 2. açılsın, 2. haritada 25. dalgaya
# gelince 3., sonra 4.".
MAP_UNLOCK_WAVE = 25
MAP_UNLOCK_PREV = {"frost": "stone", "jungle": "frost", "desert": "jungle"}


def _stat_int(st, key):
    try:
        return int(float(st.get(key, 0) or 0))
    except (TypeError, ValueError):
        return 0


def map_best_wave(save, theme):
    """Haritada ulaşılan en yüksek dalga (cehennem dalgaları dahil)."""
    return _stat_int(save.data.get("stats") or {}, "best_%s_wave" % theme)


def map_cleared(save, theme):
    """Bu harita bir sonrakini açacak kadar ilerletildi mi?"""
    st = save.data.get("stats") or {}
    if theme == "stone":
        return (_stat_int(st, "stone_cleared") > 0
                or _stat_int(st, "best_stone_wave") > MAP_UNLOCK_WAVE
                or _stat_int(st, "best_wave") > MAP_UNLOCK_WAVE)
    return map_best_wave(save, theme) >= MAP_UNLOCK_WAVE


def map_unlocked(save, theme):
    if theme not in MAP_UNLOCK_PREV:
        return True
    st = save.data.get("stats") or {}
    if _stat_int(st, "%s_kills" % theme) > 0:      # eski kayıtta zaten oynanmış
        return True
    return map_cleared(save, MAP_UNLOCK_PREV[theme])


def map_lock_text(theme):
    prev = MAP_UNLOCK_PREV.get(theme)
    if prev is None:
        return ""
    if prev == "stone":
        return L("ms.lock_stone", L("map.stone.name"))
    return L("ms.lock_need", L("map.%s.name" % prev), MAP_UNLOCK_WAVE)
MAP_RULES = {
    "stone": {},
    "frost": {"enemy_speed": 0.90, "enemy_hp": 0.10},
    "jungle": {"spawn_rate": 1.12, "xp": 0.12},
    "desert": {"enemy_speed": 1.08, "gold": 0.15},
}
# başlangıç seçimi: koşu başında 3 silah kartı (nadirlik çeker; nadir silah
# daha yüksek seviyeden başlar) ve 3 yemin kartı.
OATH_BULWARK_EVERY = 40.0            # sur yemini: kalkan dolum aralığı (sn)
MERCHANT_LUCK_PER_LEVEL = 0.08       # tüccarın kademe şansı: seviye başına +%8
# "tüccar her seviyede değişiyor - bir kez açalım, 3 kez parayla yenileme
# hakkımız olsun". El ilk konuşmada bir kez çekilir ve kendiliğinden değişmez.
MERCHANT_REROLLS = 3
MERCHANT_REROLL_BASE = 100           # 1. yenilemenin taban fiyatı
MERCHANT_REROLL_WAVE = 20            # dalga başına fiyat artışı
MERCHANT_REROLL_STEP = (1, 2, 3)     # 1. / 2. / 3. yenilemenin katı


def merchant_reroll_cost(wave, used):
    """Tüccarın elini yenilemenin altın bedeli (used: kaç kez yenilendi)."""
    k = MERCHANT_REROLL_STEP[min(int(used), len(MERCHANT_REROLL_STEP) - 1)]
    return int((MERCHANT_REROLL_BASE + MERCHANT_REROLL_WAVE * max(1, int(wave))) * k)
# Yeminin güç tarafı kademeyle büyür (Yaygın .. Efsanevi); bedel sabittir.
OATH_TIER_MULT = (1.0, 1.25, 1.5, 1.85, 2.3)


def oath_values(key, tier=0):
    """Yeminin güç değerleri bu kademede: (değer1, değer2?)."""
    m = OATH_TIER_MULT[int(clamp(int(tier), 0, len(OATH_TIER_MULT) - 1))]
    t = int(clamp(int(tier), 0, len(OATH_TIER_MULT) - 1))
    if key == "glass":
        return (0.30 * m,)
    if key == "gold_fever":
        return (0.35 * m,)
    if key == "turtle":
        return (float(int(round(50 * m))), 0.08 * m)
    if key == "scholar":
        return (0.25 * m,)
    if key == "gambler":
        return (0.50 * m,)
    if key == "blood":
        return (0.02 * m,)
    if key == "wind":
        return (0.12 * m, 0.25 * m)
    if key == "bulwark":
        return (float(3 + t), float(int(round(OATH_BULWARK_EVERY / m))))
    if key == "hunter":
        return (1.0 * m,)
    if key == "feast":
        return (0.25 * m,)
    if key == "hoard":
        return (float(int(round(350 * m / 10.0)) * 10),)
    if key == "hawkeye":
        return (0.12 * m, 0.25 * m)
    return ()


def oath_up_text(key, tier=0):
    """Yemin kartının güç satırı, kademenin gerçek sayılarıyla."""
    v = oath_values(key, tier)
    pct = lambda x: "+" + fmt_pct1(x)
    if key == "turtle":
        args = ("+%d" % int(v[0]), pct(v[1]))
    elif key == "bulwark":
        args = ("+%d" % int(v[0]), "%d" % int(v[1]))
    elif key == "hoard":
        args = (fmt_num(int(v[0])),)
    elif key == "hunter":
        args = (pct(stack_bonus(0.385, v[0], soft=3.5)),)
    else:
        args = tuple(pct(x) for x in v)
    return L("oath.%s.up" % key, *args)
