def run_floor_key(run):
    """Bu koşunun zemin/stil anahtarı (cehennem ya da arenanın haritası)."""
    if getattr(run, "biome", "arena") == "hell":
        return "hell"
    return MAP_FLOOR_KEY.get(getattr(run, "map_theme", "stone"), "arena")


_FLOOR_CACHE = {}


def _decorate_arena_floor(surf, st, rnd):
    """1. haritanın zeminini boyar."""
    stone, stone_lo = st["stone"], st["stone_lo"]
    moss, rune = st["moss"], st["rune"]
    sand, crystal = st["sand"], st["crystal"]
    W, H = ARENA_RECT.w, ARENA_RECT.h

    # ---- kırık taş döşeme ----
    # Izgaraya oturan ama her biri biraz kaymış/dönmüş taşlar: dümdüz bir
    # fayans deseni yerine yıllanmış, oturmuş bir meydan hissi.
    TILE = 104
    for gy in range(-1, H // TILE + 2):
        for gx in range(-1, W // TILE + 2):
            if rnd.random() < 0.09:
                continue                      # eksik/kırılmış taş
            cx = gx * TILE + TILE * 0.5 + rnd.uniform(-3, 3)
            cy = gy * TILE + TILE * 0.5 + rnd.uniform(-3, 3)
            # doğal zemin: taş yalnız meydanda ve yollarda
            if st.get("terrain") and rnd.random() > terrain_tile_weight(st, cx, cy, W, H):
                continue
            # Bazı taşlar iki kat geniş: tek tip kare fayans hissi olmasın.
            wide = rnd.random() < 0.16
            hw = TILE * (0.96 if wide else 0.5) - rnd.uniform(2.5, 5.0)
            hh = TILE * 0.5 - rnd.uniform(2.5, 5.0)
            ang = rnd.uniform(-0.022, 0.022)
            pts = rot_pts([(-hw, -hh), (hw, -hh), (hw, hh), (-hw, hh)],
                          ang, cx, cy)
            shade = rnd.uniform(0.80, 1.20)
            face = scale_col(stone, shade)
            # derz gölgesi (taşın altına düşen koyu bant)
            pygame.draw.polygon(surf, scale_col(stone_lo, 0.55),
                                [(x, y + 4) for x, y in pts])
            pygame.draw.polygon(surf, face, pts)
            # üst kenarda pah ışığı, alt kenarda gölge: taş kabarık dursun
            pygame.draw.line(surf, scale_col(face, 1.5), pts[0], pts[1], 2)
            pygame.draw.line(surf, scale_col(face, 1.28), pts[0], pts[3], 1)
            pygame.draw.line(surf, scale_col(stone_lo, 0.7), pts[3], pts[2], 2)
            pygame.draw.polygon(surf, scale_col(stone_lo, 0.85), pts, 1)
            # el boyaması gibi benekler: düz renkli taş yüzü canlansın
            for _k in range(rnd.randint(4, 9)):
                bx = cx + rnd.uniform(-hw * 0.85, hw * 0.85)
                by = cy + rnd.uniform(-hh * 0.8, hh * 0.8)
                pygame.draw.circle(surf, scale_col(face, rnd.uniform(0.84, 1.12)),
                                   (int(bx), int(by)), rnd.choice((1, 1, 2, 2, 3)))
            # taşın üstünde çatlak
            if rnd.random() < 0.30:
                a = rnd.uniform(0, math.pi)
                ln = hw * rnd.uniform(0.5, 1.1)
                pygame.draw.line(surf, scale_col(stone_lo, 0.75),
                                 (cx - math.cos(a) * ln, cy - math.sin(a) * ln * 0.8),
                                 (cx + math.cos(a) * ln, cy + math.sin(a) * ln * 0.8), 2)
            # derzden fışkıran yosun
            if rnd.random() < 0.22:
                mx = cx + rnd.uniform(-hw, hw)
                my = cy + hh * rnd.choice((-1, 1))
                blit_disc(surf, mx, my, rnd.uniform(5, 13), moss,
                          int(rnd.uniform(40, 95)))

    # ---- merkezdeki kadim mühür ----
    # Dünyanın tam ortası: oyuncunun doğduğu yer. İki taş halka, aralarında bir
    # yazıt kuşağı ve ortada sekiz kollu bir yıldız.
    ccx, ccy = W * 0.5, H * 0.5
    R = 300
    blit_disc(surf, ccx, ccy, R * 1.06, sand, 60)
    for k, rad in ((0.52, R), (0.68, R * 0.82), (0.40, R * 0.55), (0.58, R * 0.40)):
        ring_aa(surf, ccx, ccy, rad, scale_col(rune, k), 3)
    # yazıt kuşağı: iki halka arasında eşit aralıklı kısa çentikler
    for i in range(72):
        a = i * math.tau / 72
        r0, r1 = R * 0.84, R * 0.98
        w = 3 if i % 6 == 0 else 1
        pygame.draw.line(surf, scale_col(rune, 0.70 if i % 6 == 0 else 0.42),
                         (ccx + math.cos(a) * r0, ccy + math.sin(a) * r0),
                         (ccx + math.cos(a) * r1, ccy + math.sin(a) * r1), w)
    # sekiz kollu yıldız
    star = []
    for i in range(16):
        a = -math.pi / 2 + i * math.pi / 8
        rr = R * (0.38 if i % 2 == 0 else 0.15)
        star.append((ccx + math.cos(a) * rr, ccy + math.sin(a) * rr))
    poly_aa(surf, star, scale_col(rune, 0.26))
    poly_edge(surf, star, scale_col(rune, 0.62), 2)
    circle_aa(surf, ccx, ccy, R * 0.09, scale_col(rune, 0.50))

    # ---- köşe sütun kaideleri ----
    # Dört köşede yıkılmış sütunların kaidesi: harita bir "yapı" gibi dursun.
    for (px, py) in ((W * 0.22, H * 0.22), (W * 0.78, H * 0.22),
                     (W * 0.22, H * 0.78), (W * 0.78, H * 0.78)):
        blit_disc(surf, px, py + 8, 74, (0, 0, 0), 70)
        for rr, k in ((66, 0.72), (52, 1.0), (40, 1.22)):
            pts = [(px + math.cos(i * math.tau / 8) * rr,
                    py + math.sin(i * math.tau / 8) * rr * 0.86) for i in range(8)]
            pygame.draw.polygon(surf, scale_col(stone, k), pts)
            pygame.draw.polygon(surf, scale_col(stone_lo, 0.9), pts, 2)
        ring_aa(surf, px, py, 30, scale_col(rune, 0.52), 2)
        # kırık sütun gövdesi: kaidenin üstünde kısa bir kütük
        for i in range(3):
            rr = 26 - i * 5
            pygame.draw.circle(surf, scale_col(stone, 1.0 + i * 0.12),
                               (int(px), int(py - i * 7)), rr)
        pygame.draw.circle(surf, scale_col(stone_lo, 1.1),
                           (int(px), int(py - 14)), 16, 2)

    # ---- yerden çıkan kristaller ----
    for _ in range(_nd(46)):
        cx, cy = rnd.uniform(60, W - 60), rnd.uniform(60, H - 60)
        if dist(cx, cy, ccx, ccy) < R * 1.1:
            continue                          # mührün üstüne kristal çıkmaz
        h = rnd.uniform(16, 38)
        w = h * rnd.uniform(0.26, 0.40)
        blit_disc(surf, cx, cy + 3, w * 2.2, (0, 0, 0), 70)
        add_glow(surf, cx, cy - h * 0.4, h * 1.5, crystal, 0.16)
        for sgn, k in ((-1, 0.62), (1, 1.0)):
            pts = [(cx, cy - h * k), (cx + sgn * w, cy - h * 0.34 * k),
                   (cx + sgn * w * 0.7, cy + 4), (cx - sgn * w * 0.2, cy + 4)]
            pygame.draw.polygon(surf, scale_col(crystal, 0.30 + 0.22 * k), pts)
            pygame.draw.polygon(surf, scale_col(crystal, 0.62), pts, 1)

    # ---- moloz / çakıl ----
    for _ in range(_nd(300)):
        cx, cy = rnd.uniform(10, W - 10), rnd.uniform(10, H - 10)
        rad = rnd.uniform(2.5, 7.0)
        n = rnd.randint(5, 7)
        pts = [(cx + math.cos(i * math.tau / n) * rad * rnd.uniform(0.7, 1.25),
                cy + math.sin(i * math.tau / n) * rad * rnd.uniform(0.6, 1.0))
               for i in range(n)]
        pygame.draw.polygon(surf, scale_col(stone_lo, 0.85), [(x, y + 2) for x, y in pts])
        pygame.draw.polygon(surf, scale_col(stone, rnd.uniform(0.85, 1.25)), pts)

    # ---- eski dövüşlerin izleri ----
    # Zemine kazınmış uzun kılıç çizikleri: burada çok kan dökülmüş.
    for _ in range(_nd(46)):
        x0, y0 = rnd.uniform(0, W), rnd.uniform(0, H)
        a = rnd.uniform(0, math.tau)
        ln = rnd.uniform(26, 64)
        p1 = (x0 + math.cos(a) * ln, y0 + math.sin(a) * ln * 0.75)
        pygame.draw.line(surf, scale_col(stone_lo, 0.6), (x0, y0), p1, 2)

# taş meydan süsleri: "ana oyun taş meydanının arka planı çok sade".
STONE_ROAD_W = 176
_STONE_FIRES = None      # [(dünya_x, dünya_y, boy)] - mangal / meşale alevleri


def stone_fire_spots():
    """Taş Meydan'daki alevlerin dünya koordinatları (bir kez hesaplanır)."""
    global _STONE_FIRES
    if _STONE_FIRES is None:
        W, H = ARENA_RECT.w, ARENA_RECT.h
        cx, cy = W * 0.5, H * 0.5
        spots = []
        for i in range(8):                      # mührün çevresindeki mangallar
            a = math.pi / 8 + i * math.tau / 8
            spots.append((cx + math.cos(a) * 430, cy + math.sin(a) * 430, 1.0))
        half = STONE_ROAD_W * 0.5 + 26
        for d in range(560, int(max(W, H) * 0.5), 420):   # yol boyu meşaleler
            for sgn in (-1, 1):
                for sx_, sy_ in ((cx + d * sgn, cy - half), (cx + d * sgn, cy + half),
                                 (cx - half, cy + d * sgn), (cx + half, cy + d * sgn)):
                    if 60 < sx_ < W - 60 and 60 < sy_ < H - 60:
                        spots.append((sx_, sy_, 0.62))
        _STONE_FIRES = [(ARENA_RECT.left + x, ARENA_RECT.top + y, k) for x, y, k in spots]
    return _STONE_FIRES


def _decorate_stone_plaza(surf, st, rnd):
    """Taş Meydan'a özel süsler."""
    W, H = ARENA_RECT.w, ARENA_RECT.h
    cx, cy = W * 0.5, H * 0.5
    R = 300
    rw = STONE_ROAD_W
    pave = (88, 80, 92)
    pave_lo = (40, 34, 46)
    trim = (168, 132, 74)
    # ---- tören yolları: mühre çıkan dört kaldırım (balıksırtı tuğla) ----
    for horiz in (True, False):
        length = W if horiz else H
        step_a, step_b = 34, 17
        row = 0
        across = -rw / 2 + 6
        while across < rw / 2 - 6:
            off = (row % 2) * step_a * 0.5
            along = -off
            while along < length:
                if horiz:
                    bx, by = along, cy + across
                else:
                    bx, by = cx + across, along
                if dist(bx + (step_a / 2 if horiz else step_b / 2),
                        by + (step_b / 2 if horiz else step_a / 2), cx, cy) > R * 1.26:
                    rect = (pygame.Rect(int(bx), int(by), step_a - 2, step_b - 2) if horiz
                            else pygame.Rect(int(bx), int(by), step_b - 2, step_a - 2))
                    col = scale_col(pave, rnd.uniform(0.82, 1.14))
                    pygame.draw.rect(surf, pave_lo, rect.move(0, 2))
                    pygame.draw.rect(surf, col, rect)
                    pygame.draw.line(surf, scale_col(col, 1.25), rect.topleft, rect.topright, 1)
                along += step_a
            across += step_b
            row += 1
        # yol kenarı: altın-kahve bordür + gölge
        for sgn in (-1, 1):
            for k_, w_ in ((0, 7), (1, 2)):
                col = (30, 24, 32) if k_ == 0 else trim
                if horiz:
                    y = cy + sgn * (rw / 2) + (0 if k_ == 0 else -sgn * 3)
                    pygame.draw.line(surf, col, (0, y), (cx - R * 1.24, y), w_)
                    pygame.draw.line(surf, col, (cx + R * 1.24, y), (W, y), w_)
                else:
                    x = cx + sgn * (rw / 2) + (0 if k_ == 0 else -sgn * 3)
                    pygame.draw.line(surf, col, (x, 0), (x, cy - R * 1.24), w_)
                    pygame.draw.line(surf, col, (x, cy + R * 1.24), (x, H), w_)
        # yolun ortasında aralıklı mühür taşları
        for d in range(int(R * 1.6), int(length * 0.5), 260):
            for sgn in (-1, 1):
                px_, py_ = (cx + d * sgn, cy) if horiz else (cx, cy + d * sgn)
                if 40 < px_ < W - 40 and 40 < py_ < H - 40:
                    pts = [(px_, py_ - 22), (px_ + 22, py_), (px_, py_ + 22), (px_ - 22, py_)]
                    pygame.draw.polygon(surf, (36, 30, 40), [(x, y + 3) for x, y in pts])
                    pygame.draw.polygon(surf, (112, 96, 82), pts)
                    pygame.draw.polygon(surf, trim, pts, 2)
                    circle_aa(surf, px_, py_, 6, (120, 160, 255))

    # ---- güneş mozaiği: mührü çeviren renkli taş kuşak ----
    cols = ((124, 58, 50), (164, 128, 70), (52, 96, 104), (164, 128, 70))
    r0, r1 = R * 1.06, R * 1.24
    nseg = 64
    for i in range(nseg):
        a0 = i * math.tau / nseg + 0.006
        a1 = (i + 1) * math.tau / nseg - 0.006
        pts = [(cx + math.cos(a0) * r0, cy + math.sin(a0) * r0),
               (cx + math.cos(a0) * r1, cy + math.sin(a0) * r1),
               (cx + math.cos(a1) * r1, cy + math.sin(a1) * r1),
               (cx + math.cos(a1) * r0, cy + math.sin(a1) * r0)]
        col = scale_col(cols[i % 4], rnd.uniform(0.80, 1.0))
        pygame.draw.polygon(surf, col, pts)
        pygame.draw.polygon(surf, scale_col(col, 0.55), pts, 1)
    ring_aa(surf, cx, cy, r1 + 3, trim, 3)
    ring_aa(surf, cx, cy, r0 - 2, scale_col(trim, 0.7), 2)
    # dört yönde altın ok uçları (yollar mühre bağlanır)
    for i in range(4):
        a = i * math.pi / 2
        tip = (cx + math.cos(a) * (r1 + 46), cy + math.sin(a) * (r1 + 46))
        bl = (cx + math.cos(a - 0.10) * (r1 + 6), cy + math.sin(a - 0.10) * (r1 + 6))
        br = (cx + math.cos(a + 0.10) * (r1 + 6), cy + math.sin(a + 0.10) * (r1 + 6))
        poly_aa(surf, [tip, bl, br], trim)

    # ---- mangallar ve meşaleler (taban; alevler canlı katmanda) ----
    for (wx, wy, k) in stone_fire_spots():
        x, y = wx - ARENA_RECT.left, wy - ARENA_RECT.top
        blit_disc(surf, x, y, 120 * k, (255, 150, 70), 26)       # sıcak ışık havuzu
        blit_disc(surf, x, y + 5, 26 * k, (0, 0, 0), 90)
        if k >= 1.0:
            for rr, col in ((22, (58, 50, 56)), (18, (96, 84, 88)), (13, (40, 26, 22))):
                pygame.draw.circle(surf, col, (int(x), int(y)), rr)
            pygame.draw.circle(surf, trim, (int(x), int(y)), 22, 2)
            for j in range(5):
                a = j * math.tau / 5 + 0.3
                circle_aa(surf, x + math.cos(a) * 7, y + math.sin(a) * 7, 2.6, (210, 90, 40))
        else:
            pygame.draw.circle(surf, (50, 40, 36), (int(x), int(y)), 9)
            pygame.draw.circle(surf, (110, 82, 50), (int(x), int(y)), 7)
            pygame.draw.circle(surf, (36, 22, 18), (int(x), int(y)), 4)

    # ---- dikilitaşlar: yolların dünya kenarındaki ağızlarında ----
    for (ox, oy) in ((cx, 120), (cx, H - 120), (120, cy), (W - 120, cy)):
        for sgn in (-1, 1):
            if abs(ox - cx) < 1:
                x, y = ox + sgn * (rw / 2 + 70), oy
            else:
                x, y = ox, oy + sgn * (rw / 2 + 70)
            s_ = 34
            blit_disc(surf, x + 6, y + 10, s_ * 1.4, (0, 0, 0), 80)
            base = pygame.Rect(int(x - s_ - 8), int(y - s_ - 8), (s_ + 8) * 2, (s_ + 8) * 2)
            pygame.draw.rect(surf, (50, 44, 56), base, border_radius=4)
            pygame.draw.rect(surf, trim, base, 2, border_radius=4)
            # tepeden bakılan piramit uç: dört yüzü farklı ışıkta
            c = (x, y)
            p1, p2, p3, p4 = (x - s_, y - s_), (x + s_, y - s_), (x + s_, y + s_), (x - s_, y + s_)
            pygame.draw.polygon(surf, (138, 128, 140), (p1, p2, c))
            pygame.draw.polygon(surf, (112, 102, 116), (p2, p3, c))
            pygame.draw.polygon(surf, (70, 62, 76), (p3, p4, c))
            pygame.draw.polygon(surf, (96, 86, 100), (p4, p1, c))
            for a_, b_ in ((p1, p3), (p2, p4)):
                pygame.draw.line(surf, (54, 48, 60), a_, b_, 1)
            circle_aa(surf, x, y, 5, (150, 190, 255))

    # ---- ay ışığı birikintileri ve derz çimeni ----
    for _ in range(_nd(34)):
        x, y = rnd.uniform(80, W - 80), rnd.uniform(80, H - 80)
        if dist(x, y, cx, cy) < R * 1.4 or abs(x - cx) < rw * 0.6 or abs(y - cy) < rw * 0.6:
            continue
        w_, h_ = rnd.uniform(50, 120), rnd.uniform(20, 46)
        rect = pygame.Rect(int(x - w_ / 2), int(y - h_ / 2), int(w_), int(h_))
        pygame.draw.ellipse(surf, (26, 34, 58), rect)
        pygame.draw.ellipse(surf, (44, 60, 96), rect.inflate(-8, -6))
        pygame.draw.line(surf, (150, 180, 240), (rect.x + w_ * 0.28, rect.y + h_ * 0.34),
                         (rect.x + w_ * 0.58, rect.y + h_ * 0.28), 2)
    for _ in range(_nd(520)):
        x, y = rnd.uniform(0, W), rnd.uniform(0, H)
        if dist(x, y, cx, cy) < R * 1.3:
            continue
        col = scale_col((86, 140, 92), rnd.uniform(0.6, 1.15))
        for sgn in (-1, 0, 1):
            pygame.draw.line(surf, col, (x, y), (x + sgn * rnd.uniform(2, 5), y - rnd.uniform(4, 9)), 1)


_FLAME_FRAMES = {}
FLAME_NFRAMES = 10


def _flame_frame(k, i):
    """telefon: hazır alev karesi (k = boy, i = kare)."""
    key = (k, i)
    img = _FLAME_FRAMES.get(key)
    if img is None:
        global _GLOW_ON_ALPHA
        W, H = int(60 * k + 20), int(110 * k + 30)
        img = pygame.Surface((W, H), pygame.SRCALPHA)
        x, y = W / 2, H - 14
        tt = i / FLAME_NFRAMES * (math.tau / 1.6)
        _GLOW_ON_ALPHA = True
        try:
            _draw_one_fire(img, x, y, k, tt, 0.0)
        finally:
            _GLOW_ON_ALPHA = False
        img = mob_rle(img)
        _FLAME_FRAMES[key] = img
    return img


def _draw_one_fire(world, x, y, k, t, seed):
    fl = 0.75 + 0.25 * math.sin(t * 11.0 + seed * 0.013) * math.sin(t * 6.3 + seed * 0.011)
    h = (26 if k >= 1.0 else 16) * fl
    w = (12 if k >= 1.0 else 7)
    for j, (col, sc) in enumerate((((255, 120, 40), 1.0), ((255, 196, 80), 0.68),
                                   ((255, 246, 200), 0.36))):
        sway = math.sin(t * 7.0 + j + seed * 0.02) * 3 * k
        pts = [(x - w * sc, y), (x + sway * 0.4 - w * sc * 0.4, y - h * sc * 0.55),
               (x + sway, y - h * sc), (x + sway * 0.4 + w * sc * 0.4, y - h * sc * 0.55),
               (x + w * sc, y)]
        poly_aa(world, pts, col)
    for j in range(2):
        ph = (t * 1.6 + j * 0.5 + seed * 0.003) % 1.0
        circle_aa(world, x + math.sin(t * 4 + j * 3 + seed) * 6, y - h - ph * 34 * k,
                  1.4 * (1.0 - ph) + 0.5, (255, 210, 120))


def _draw_stone_fires(world, cam, t, cheap=False):
    """Taş Meydan mangal ve meşale alevleri (yalnız görünenler)."""
    if MOBILE or cheap:
        for (x, y, k) in stone_fire_spots():
            if not cam.inflate(80, 80).collidepoint(x, y):
                continue
            fl = 0.75 + 0.25 * math.sin(t * 11.0 + x * 0.013) * math.sin(t * 6.3 + y * 0.011)
            add_glow(world, x, y - 6 * k, 56 * k * fl, (255, 150, 60), 0.34)
            img = _flame_frame(k, int(t * 12 + x * 0.37) % FLAME_NFRAMES)
            world.blit(img, (int(x - img.get_width() / 2), int(y - img.get_height() + 14)))
        return
    for (x, y, k) in stone_fire_spots():
        if not cam.inflate(80, 80).collidepoint(x, y):
            continue
        fl = 0.75 + 0.25 * math.sin(t * 11.0 + x * 0.013) * math.sin(t * 6.3 + y * 0.011)
        add_glow(world, x, y - 6 * k, 90 * k * fl, (255, 150, 60), 0.30)
        h = (26 if k >= 1.0 else 16) * fl
        w = (12 if k >= 1.0 else 7)
        for j, (col, sc) in enumerate((((255, 120, 40), 1.0), ((255, 196, 80), 0.68),
                                       ((255, 246, 200), 0.36))):
            sway = math.sin(t * 7.0 + j + x * 0.02) * 3 * k
            pts = [(x - w * sc, y), (x + sway * 0.4 - w * sc * 0.4, y - h * sc * 0.55),
                   (x + sway, y - h * sc), (x + sway * 0.4 + w * sc * 0.4, y - h * sc * 0.55),
                   (x + w * sc, y)]
            poly_aa(world, pts, col)
        for j in range(2):
            ph = (t * 1.6 + j * 0.5 + x * 0.003) % 1.0
            circle_aa(world, x + math.sin(t * 4 + j * 3 + y) * 6, y - h - ph * 34 * k,
                      1.4 * (1.0 - ph) + 0.5, (255, 210, 120))


def _decorate_theme_floor(surf, key, st, rnd):
    """Haritaya özel ek süslemeler (taş döşemenin üstüne, bir kez çizilir)."""
    W, H = ARENA_RECT.w, ARENA_RECT.h
    if key == "frost":
        # kar birikintileri + donmuş su birikintileri + buz çatlakları
        for _ in range(_nd(240)):
            cx, cy = rnd.uniform(0, W), rnd.uniform(0, H)
            blit_disc(surf, cx, cy, rnd.uniform(14, 60), (226, 238, 252), int(rnd.uniform(16, 44)))
        for _ in range(_nd(26)):
            cx, cy = rnd.uniform(80, W - 80), rnd.uniform(80, H - 80)
            rw, rh = rnd.uniform(60, 150), rnd.uniform(26, 60)
            rect = pygame.Rect(int(cx - rw / 2), int(cy - rh / 2), int(rw), int(rh))
            pygame.draw.ellipse(surf, (120, 168, 210), rect)
            pygame.draw.ellipse(surf, (160, 206, 240), rect.inflate(-10, -8))
            pygame.draw.ellipse(surf, (215, 240, 255), rect, 2)
            pygame.draw.line(surf, (240, 250, 255), (rect.x + rw * 0.25, rect.y + rh * 0.35),
                             (rect.x + rw * 0.55, rect.y + rh * 0.30), 2)
        for _ in range(_nd(70)):
            x0, y0 = rnd.uniform(0, W), rnd.uniform(0, H)
            a = rnd.uniform(0, math.tau)
            pts = [(x0, y0)]
            for _s in range(rnd.randint(3, 6)):
                a += rnd.uniform(-0.7, 0.7)
                x0 += math.cos(a) * rnd.uniform(14, 34)
                y0 += math.sin(a) * rnd.uniform(14, 34)
                pts.append((x0, y0))
            pygame.draw.lines(surf, (190, 230, 255), False, pts, 1)
    elif key == "jungle":
        # kökler, yaprak öbekleri, çimen tutamları ve küçük çiçekler
        for _ in range(_nd(60)):
            x0, y0 = rnd.uniform(0, W), rnd.uniform(0, H)
            a = rnd.uniform(0, math.tau)
            pts = [(x0, y0)]
            for _s in range(rnd.randint(4, 8)):
                a += rnd.uniform(-0.6, 0.6)
                x0 += math.cos(a) * rnd.uniform(18, 40)
                y0 += math.sin(a) * rnd.uniform(18, 40)
                pts.append((x0, y0))
            pygame.draw.lines(surf, (40, 30, 20), False, pts, 6)
            pygame.draw.lines(surf, (84, 62, 38), False, pts, 3)
        for _ in range(_nd(170)):
            cx, cy = rnd.uniform(0, W), rnd.uniform(0, H)
            for _l in range(rnd.randint(3, 6)):
                a = rnd.uniform(0, math.tau)
                d = rnd.uniform(0, 16)
                lx, ly = cx + math.cos(a) * d, cy + math.sin(a) * d * 0.7
                lw = rnd.uniform(7, 13)
                pygame.draw.ellipse(surf, scale_col((70, 150, 70), rnd.uniform(0.6, 1.2)),
                                    pygame.Rect(int(lx - lw), int(ly - lw * 0.45), int(lw * 2), int(lw * 0.9)))
        for _ in range(_nd(420)):
            cx, cy = rnd.uniform(0, W), rnd.uniform(0, H)
            col = scale_col((96, 190, 90), rnd.uniform(0.6, 1.25))
            for sgn in (-1, 0, 1):
                pygame.draw.line(surf, col, (cx, cy), (cx + sgn * rnd.uniform(3, 6), cy - rnd.uniform(6, 12)), 2)
        for _ in range(_nd(160)):
            cx, cy = rnd.uniform(0, W), rnd.uniform(0, H)
            col = rnd.choice(((255, 120, 160), (255, 230, 120), (190, 150, 255), (255, 255, 255)))
            for i in range(5):
                a = i * math.tau / 5
                pygame.draw.circle(surf, col, (int(cx + math.cos(a) * 3), int(cy + math.sin(a) * 3)), 2)
            pygame.draw.circle(surf, (255, 220, 90), (int(cx), int(cy)), 2)
    elif key == "desert":
        # kum dalgaları, kayalar, kaktüsler, ağarmış kemikler
        for _ in range(_nd(220)):
            x0, y0 = rnd.uniform(-40, W), rnd.uniform(0, H)
            ln = rnd.uniform(60, 180)
            amp = rnd.uniform(3, 7)
            pts = [(x0 + i * ln / 10.0, y0 + math.sin(i * 0.9) * amp) for i in range(11)]
            pygame.draw.lines(surf, scale_col((210, 168, 108), rnd.uniform(0.7, 1.05)), False, pts, 2)
        for _ in range(_nd(60)):
            cx, cy = rnd.uniform(40, W - 40), rnd.uniform(40, H - 40)
            hgt = rnd.uniform(26, 46)
            blit_disc(surf, cx + 6, cy + 4, hgt * 0.5, (0, 0, 0), 60)
            pygame.draw.rect(surf, (52, 110, 62), pygame.Rect(int(cx - 6), int(cy - hgt), 12, int(hgt)),
                             border_radius=6)
            for sgn in (-1, 1):
                ay = cy - hgt * rnd.uniform(0.45, 0.7)
                pygame.draw.rect(surf, (52, 110, 62), pygame.Rect(int(cx + sgn * 6 - (10 if sgn < 0 else 0)),
                                                                  int(ay), 10, 6), border_radius=3)
                pygame.draw.rect(surf, (52, 110, 62), pygame.Rect(int(cx + sgn * 13 - 3), int(ay - 12), 7, 16),
                                 border_radius=3)
            pygame.draw.line(surf, (96, 160, 100), (cx - 2, cy - hgt + 4), (cx - 2, cy - 4), 2)
        for _ in range(_nd(55)):
            cx, cy = rnd.uniform(20, W - 20), rnd.uniform(20, H - 20)
            pygame.draw.ellipse(surf, (222, 212, 190), pygame.Rect(int(cx - 9), int(cy - 7), 18, 14))
            pygame.draw.circle(surf, (60, 46, 36), (int(cx - 3), int(cy - 1)), 2)
            pygame.draw.circle(surf, (60, 46, 36), (int(cx + 3), int(cy - 1)), 2)
            a = rnd.uniform(0, math.tau)
            pygame.draw.line(surf, (222, 212, 190), (cx + 14, cy + 6),
                             (cx + 14 + math.cos(a) * 18, cy + 6 + math.sin(a) * 10), 3)


def _decorate_hell_floor(surf, st, rnd):
    """Cehennem zeminini boyar: lav çatlakları, magma gölleri, obsidyen kayalar."""
    lava, hot = st["lava"], st["lava_hot"]
    rock, ash = st["rock"], st["ash"]
    W, H = ARENA_RECT.w, ARENA_RECT.h

    # ---- yanık kömür lekeleri (zemine derinlik verir) ----
    for _ in range(_nd(260)):
        cx, cy = rnd.uniform(0, W), rnd.uniform(0, H)
        blit_disc(surf, cx, cy, rnd.uniform(18, 70), (10, 4, 6), int(rnd.uniform(18, 46)))

    # ---- magma gölleri: dış hâle + akkor göbek + kabuk kenarı ----
    for _ in range(_nd(18)):
        cx, cy = rnd.uniform(60, W - 60), rnd.uniform(60, H - 60)
        rad = rnd.uniform(44, 112)
        pts = []
        n = rnd.randint(8, 12)
        for i in range(n):
            a = i * math.tau / n
            rr = rad * rnd.uniform(0.72, 1.18)
            pts.append((cx + math.cos(a) * rr, cy + math.sin(a) * rr * 0.72))
        add_glow(surf, cx, cy, rad * 1.4, lava, 0.22)
        # koyu çukur -> soğumuş kabuk -> ergimiş göbek (üç katman)
        pygame.draw.polygon(surf, (24, 9, 10), [(px, py + 4) for px, py in pts])
        pygame.draw.polygon(surf, (56, 24, 20), pts)
        pygame.draw.polygon(surf, scale_col(lava, 0.68),
                            [(cx + (px - cx) * 0.78, cy + (py - cy) * 0.78) for px, py in pts])
        pygame.draw.polygon(surf, scale_col(hot, 0.78),
                            [(cx + (px - cx) * 0.34, cy + (py - cy) * 0.34) for px, py in pts])
        # kabuk üstünde soğumuş siyah adacıklar
        for _isl in range(rnd.randint(2, 4)):
            ia = rnd.uniform(0, math.tau)
            ir = rad * rnd.uniform(0.15, 0.55)
            blit_disc(surf, cx + math.cos(ia) * ir, cy + math.sin(ia) * ir * 0.7,
                      rnd.uniform(6, 16), (26, 12, 14), 230)
        pygame.draw.polygon(surf, (48, 20, 18), pts, 3)

    # ---- lav çatlakları: dallanan, akkor damarlar ----
    for _ in range(_nd(58)):
        x0, y0 = rnd.uniform(0, W), rnd.uniform(0, H)
        ang = rnd.uniform(0, math.tau)
        for _branch in range(rnd.randint(1, 3)):
            bx, by, ba = x0, y0, ang + rnd.uniform(-0.9, 0.9)
            pts = [(bx, by)]
            for _seg in range(rnd.randint(4, 9)):
                ba += rnd.uniform(-0.55, 0.55)
                step = rnd.uniform(22, 54)
                bx += math.cos(ba) * step
                by += math.sin(ba) * step
                pts.append((bx, by))
            if len(pts) < 2:
                continue
            pygame.draw.lines(surf, (22, 8, 9), False, pts, 6)
            pygame.draw.lines(surf, scale_col(lava, 0.58), False, pts, 3)
            pygame.draw.lines(surf, scale_col(hot, 0.80), False, pts, 1)

    # ---- obsidyen kayalar ve kemik parçaları ----
    for _ in range(_nd(150)):
        cx, cy = rnd.uniform(20, W - 20), rnd.uniform(20, H - 20)
        rad = rnd.uniform(9, 26)
        pts = []
        n = rnd.randint(5, 7)
        for i in range(n):
            a = i * math.tau / n + rnd.uniform(-0.2, 0.2)
            rr = rad * rnd.uniform(0.7, 1.25)
            pts.append((cx + math.cos(a) * rr, cy + math.sin(a) * rr * 0.8))
        pygame.draw.polygon(surf, (12, 6, 9), [(px + 3, py + 4) for px, py in pts])
        pygame.draw.polygon(surf, rock, pts)
        pygame.draw.polygon(surf, ash, pts, 1)
    for _ in range(_nd(70)):
        cx, cy = rnd.uniform(20, W - 20), rnd.uniform(20, H - 20)
        a = rnd.uniform(0, math.tau)
        ln = rnd.uniform(14, 30)
        p0 = (cx - math.cos(a) * ln, cy - math.sin(a) * ln * 0.7)
        p1 = (cx + math.cos(a) * ln, cy + math.sin(a) * ln * 0.7)
        pygame.draw.line(surf, (186, 176, 158), p0, p1, 3)
        pygame.draw.circle(surf, (196, 186, 168), (int(p0[0]), int(p0[1])), 3)
        pygame.draw.circle(surf, (196, 186, 168), (int(p1[0]), int(p1[1])), 3)


# ---- doğal zemin + harita simge yapıları ----
# haritalar baştan sona aynı taş fayanstan ibaretti; orman bile taş döşemeydi.
# buzul / orman / çöl'de zemin doğal (kar, çim-toprak, kum lekeleri); taş
# döşeme yalnız ortadaki meydanda ve oradan dünyanın kenarlarına kıvrılarak
# giden yollarda kalır.
TERRAIN_STYLE = {
    "frost": dict(g=[(54, 66, 90), (70, 86, 114), (96, 116, 146)], speck=(170, 196, 226)),
    "jungle": dict(g=[(30, 50, 32), (40, 68, 40), (56, 46, 30)], speck=(70, 120, 60)),
    "desert": dict(g=[(104, 76, 48), (128, 96, 62), (86, 62, 40)], speck=(160, 126, 84)),
}
TERRAIN_PLAZA_R = 980          # meydanın taş döşemeli yarıçapı
TERRAIN_ROAD_W = 118           # yol yarı genişliği


def _soft_blob_maker():
    cache = {}

    def blob(surf, x, y, r, col, alpha):
        rq = max(16, int(r) // 24 * 24)
        aq = max(8, int(alpha) // 12 * 12)
        key = (rq, col, aq)
        sp = cache.get(key)
        if sp is None:
            sp = pygame.Surface((rq * 2, rq * 2), pygame.SRCALPHA)
            for i in range(8, 0, -1):
                k = i / 8.0
                pygame.draw.circle(sp, (col[0], col[1], col[2], int(aq * (1.0 - k) ** 0.8 + aq * 0.15)),
                                   (rq, rq), int(rq * k))
            cache[key] = sp
        surf.blit(sp, (int(x - rq), int(y - rq)))
    return blob, cache


def _road_offset(along, seed):
    return math.sin(along * 0.0013 + seed) * 150 + math.sin(along * 0.0037 + seed * 2.1) * 55


def terrain_tile_weight(st, x, y, W, H):
    """Bu noktada taş döşeme olsun mu (0..1)?"""
    if not st.get("terrain"):
        return 1.0
    cx, cy = W * 0.5, H * 0.5
    d = math.hypot(x - cx, y - cy)
    w = clamp((TERRAIN_PLAZA_R - d) / 260.0, 0.0, 1.0)
    ry = cy + _road_offset(x, 1.3)
    rx = cx + _road_offset(y, 2.7)
    w = max(w, clamp((TERRAIN_ROAD_W - abs(y - ry)) / 60.0 + 0.4, 0.0, 1.0),
            clamp((TERRAIN_ROAD_W - abs(x - rx)) / 60.0 + 0.4, 0.0, 1.0))
    return w


def _paint_terrain(surf, key, st, rnd):
    """Doğal zemin: büyük yumuşak lekeler + benekler (taş döşemeden önce)."""
    ts = TERRAIN_STYLE.get(key)
    if ts is None:
        return
    W, H = ARENA_RECT.w, ARENA_RECT.h
    surf.fill(ts["g"][0])
    blob, cache = _soft_blob_maker()
    for _ in range(_nd(260)):
        blob(surf, rnd.uniform(0, W), rnd.uniform(0, H), rnd.uniform(120, 300),
             rnd.choice(ts["g"][1:]), rnd.uniform(40, 90))
    for _ in range(_nd(420)):
        blob(surf, rnd.uniform(0, W), rnd.uniform(0, H), rnd.uniform(30, 90),
             rnd.choice(ts["g"]), rnd.uniform(40, 90))
    sp = ts["speck"]
    for _ in range(_nd(5200)):
        x, y = rnd.uniform(0, W), rnd.uniform(0, H)
        c = scale_col(sp, rnd.uniform(0.55, 1.05))
        pygame.draw.circle(surf, c, (int(x), int(y)), rnd.choice((1, 1, 2)))
    cache.clear()


def _far_from_center(rnd, W, H, min_d=900, pad=80):
    for _ in range(20):
        x, y = rnd.uniform(pad, W - pad), rnd.uniform(pad, H - pad)
        if math.hypot(x - W * 0.5, y - H * 0.5) >= min_d:
            return x, y
    return rnd.uniform(pad, W - pad), rnd.uniform(pad, H - pad)


def _off_road(st, rnd, W, H, min_d=900, tries=12):
    """Yola ve meydana denk gelmeyen bir nokta (yapılar yolu kapatmasın)."""
    x, y = _far_from_center(rnd, W, H, min_d)
    for _ in range(tries):
        if terrain_tile_weight(st, x, y, W, H) < 0.05:
            return x, y
        x, y = _far_from_center(rnd, W, H, min_d)
    return x, y


def _star_poly(cx, cy, n, r1, r2, rot=0.0):
    pts = []
    for i in range(n * 2):
        a = rot + i * math.pi / n
        rr = r1 if i % 2 == 0 else r2
        pts.append((cx + math.cos(a) * rr, cy + math.sin(a) * rr))
    return pts


def _ground_shadow(surf, x, y, rx, ry, alpha=70):
    s = pygame.Surface((int(rx * 2) + 2, int(ry * 2) + 2), pygame.SRCALPHA)
    pygame.draw.ellipse(s, (0, 0, 0, alpha), s.get_rect())
    surf.blit(s, (int(x - rx), int(y - ry)))


def _lake(surf, rnd, x, y, size, deep, mid, rim, ice=False):
    pts = []
    n = 14
    for i in range(n):
        a = i * math.tau / n
        rr = size * rnd.uniform(0.75, 1.15)
        pts.append((x + math.cos(a) * rr * 1.5, y + math.sin(a) * rr))
    pygame.draw.polygon(surf, scale_col(rim, 0.6), [(px, py + 5) for px, py in pts])
    pygame.draw.polygon(surf, rim, pts)
    inner = [(x + (px - x) * 0.86, y + (py - y) * 0.86) for px, py in pts]
    pygame.draw.polygon(surf, deep, inner)
    core = [(x + (px - x) * 0.58 - size * 0.12, y + (py - y) * 0.58 - size * 0.08) for px, py in pts]
    pygame.draw.polygon(surf, mid, core)
    if ice:
        for _ in range(7):
            a = rnd.uniform(0, math.tau)
            x0, y0 = x + math.cos(a) * size * 0.3, y + math.sin(a) * size * 0.2
            pl = [(x0, y0)]
            for _s in range(4):
                a += rnd.uniform(-0.8, 0.8)
                x0 += math.cos(a) * size * 0.22
                y0 += math.sin(a) * size * 0.15
                pl.append((x0, y0))
            pygame.draw.lines(surf, (220, 240, 255), False, pl, 1)
        pygame.draw.line(surf, (240, 250, 255), (x - size * 0.7, y - size * 0.35),
                         (x - size * 0.2, y - size * 0.5), 3)
    else:
        for _ in range(3):
            a = rnd.uniform(0, math.tau)
            rr = rnd.uniform(0.2, 0.6) * size
            ring_aa(surf, x + math.cos(a) * rr, y + math.sin(a) * rr * 0.6, size * 0.12,
                    lighten(mid, 0.3), 1)


def _decorate_terrain_landmarks(surf, key, st, rnd):
    """Haritanın simge yapıları."""
    W, H = ARENA_RECT.w, ARENA_RECT.h
    if key == "frost":
        blob, cache = _soft_blob_maker()
        for _ in range(_nd(150)):                                  # kar yığıntıları
            blob(surf, rnd.uniform(0, W), rnd.uniform(0, H), rnd.uniform(40, 120),
                 (210, 226, 244), rnd.uniform(40, 80))
        cache.clear()
        for _ in range(_nd(9)):                                    # donmuş göller
            x, y = _off_road(st, rnd, W, H, 1000)
            _lake(surf, rnd, x, y, rnd.uniform(90, 170), (96, 150, 200), (150, 200, 236),
                  (214, 232, 248), ice=True)
        for _ in range(_nd(26)):                                   # buz kristali kümeleri
            x, y = _off_road(st, rnd, W, H, 950)
            for j in range(rnd.randint(3, 6)):
                a = -math.pi / 2 + rnd.uniform(-0.9, 0.9)
                ln = rnd.uniform(26, 60)
                bx, by = x + rnd.uniform(-18, 18), y + rnd.uniform(-8, 8)
                tip = (bx + math.cos(a) * ln, by + math.sin(a) * ln)
                b0 = (bx - math.sin(a) * 7, by + math.cos(a) * 7)
                b1 = (bx + math.sin(a) * 7, by - math.cos(a) * 7)
                pygame.draw.polygon(surf, OUTLINE, [b0, tip, b1], 3)
                pygame.draw.polygon(surf, (170, 220, 250) if j % 2 else (210, 240, 255), [b0, tip, b1])
                pygame.draw.line(surf, WHITE, (bx, by), tip, 1)
        for _ in range(_nd(60)):                                   # karlı çamlar
            x, y = _off_road(st, rnd, W, H, 1000)
            s = rnd.uniform(34, 62)
            _ground_shadow(surf, x + s * 0.35, y + s * 0.55, s * 1.0, s * 0.45, 80)
            rot = rnd.uniform(0, math.tau)
            for k, (rk, c) in enumerate(((1.0, (30, 66, 60)), (0.74, (40, 86, 74)), (0.48, (56, 110, 92)))):
                pts = _star_poly(x, y - k * s * 0.12, 8, s * rk, s * rk * 0.62, rot + k * 0.3)
                pygame.draw.polygon(surf, OUTLINE, pts, 2)
                pygame.draw.polygon(surf, c, pts)
