# ---- sohbet / komut satırı (L tuşu) ----
# Ekranın sol altında açılan tek satırlık bir kutu. L ile açılır, enter ile
# yazılan satır işlenir, ESC ile kapanır.

CHAT_KEY_LABEL = "L"
CHAT_X = 16                     # kutunun sol kenarı
CHAT_BOTTOM = 16                # kutunun alt kenarının ekran altına uzaklığı
CHAT_W = 420                    # kutunun genişliği
CHAT_MAX_LEN = 48               # tek satıra yazılabilecek en fazla karakter
CHAT_LOG_LINES = 6              # kutunun üstünde görünen en fazla satır
CHAT_LOG_LIFE = 9.0             # bir satırın ekranda kalma süresi (saniye)
# sohbet komutları (hile kodları). Tanınmayan satır sohbete olduğu gibi
# yazılır; yani kutu hem komut satırı hem not defteri gibi çalışır:
#   full1903: 10.000 elmas + kilitli bütün içerik (skin, kıyafet, kitap, silah)
#   skin: yalnızca gerçek parayla satılan 4 premium skin
# yönetici komutu: yalnızca bu kullanıcı adıyla giriş yapmış hesapta çalışır.
#   unban <ad>   |   ban kaldır <ad>   |   banac <ad>
# Asıl yetki denetimi sunucudadır (/admin/unban); buradaki denetim yalnızca
# komutun başkalarında sohbet satırı gibi davranması içindir.
CHAT_ADMIN_NAME = "yapimci1903"
CHAT_CHEAT_CODE = "full1903"
CHAT_CHEAT_GEMS = 10000
CHAT_SKIN_CODE = "skin"


def parse_unban_cmd(line):
    """'unban ad', '/unban ad', 'banac ad', 'ban kaldır ad' -> ad.
    Komut değilse None; komut ama ad yoksa ""."""
    parts = str(line or "").split()
    tr = str.maketrans("çğıöşüÇĞİÖŞÜ", "cgiosuCGIOSU")
    low = [w.translate(tr).lower().lstrip("/!") for w in parts]
    if low and low[0] in ("unban", "unbanla", "banac", "bankaldir"):
        return parts[1].strip() if len(parts) >= 2 else ""
    if len(low) >= 2 and low[0] == "ban" and low[1] in ("kaldir", "ac", "kaldirma"):
        return parts[2].strip() if len(parts) >= 3 else ""
    return None


def parse_give_cmd(line):
    """'elmas ad 5000', '/elmas ad 10k', 'gems ad 2m' -> (ad, miktar).
    Komut değilse None; komut ama ad/miktar eksik ya da bozuksa ("", 0)."""
    parts = str(line or "").split()
    tr = str.maketrans("çğıöşüÇĞİÖŞÜ", "cgiosuCGIOSU")
    if not parts or parts[0].translate(tr).lower().lstrip("/!") not in (
            "elmas", "elmasver", "gems", "give", "gem"):
        return None
    if len(parts) < 3:
        return ("", 0)
    raw = parts[2].lower().replace(".", "").replace(",", "").replace("_", "")
    mult = 1
    if raw[-1:] in ("k", "m"):
        mult = 1000 if raw[-1] == "k" else 1000000
        raw = raw[:-1]
    if not raw.isdigit():
        return ("", 0)
    n = int(raw) * mult
    return (parts[1].strip(), n) if n >= 1 else ("", 0)


class ChatConsole:
    """Sol alttaki sohbet kutusu ve satır geçmişi."""

    def __init__(self):
        self.open = False
        self.text = ""
        # [metin, renk, kalan_süre] - süresi dolan satır yukarıdan silinir.
        self.log = []
        self.caret = 0.0
        self.history = []        # yazılan satırlar (yukarı/aşağı ile gezinir)
        self.hist_idx = 0

    # ---- durum ----
    FID = "chat"

    def open_box(self):
        self.open = True
        self.text = ""
        caret_set(self.FID)
        self.caret = 0.0
        self.hist_idx = len(self.history)
        # Kutu açıkken eski satırlar solmasın: oyuncu ne yazdığını görebilsin.
        for row in self.log:
            row[2] = max(row[2], CHAT_LOG_LIFE)

    def close(self):
        self.open = False
        self.text = ""

    def say(self, msg, color=TEXT):
        """Sohbete bir satır yazar (uzun satır kutuya sığacak şekilde bölünür)."""
        for line in wrap_text(str(msg), 15, CHAT_W - 24) or [""]:
            self.log.append([line, color, CHAT_LOG_LIFE])
        del self.log[:-40]       # geçmiş sınırsız büyümesin

    # ---- girdi ----
    def handle_key(self, event):
        """Kutu açıkken bir tuşu işler."""
        if event.key in (pygame.K_RETURN, pygame.K_KP_ENTER):
            line = self.text.strip()
            if line:
                self.history.append(line)
                del self.history[:-30]
            self.close()
            return line
        if event.key == pygame.K_ESCAPE:
            self.close()
            return None
        if event.key == pygame.K_UP and self.history:
            self.hist_idx = max(0, self.hist_idx - 1)
            self.text = self.history[self.hist_idx]
            caret_set(self.FID)
            return None
        if event.key == pygame.K_DOWN and self.history:
            self.hist_idx = min(len(self.history), self.hist_idx + 1)
            self.text = ("" if self.hist_idx >= len(self.history)
                         else self.history[self.hist_idx])
            caret_set(self.FID)
            return None
        if _ctrl_down() and event.key == pygame.K_c:
            clip_set(self.text)
            return None
        # Yazdırılabilir olmayan karakterler (kontrol tuşları) kutuya girmesin.
        self.text, _ = text_edit(self.FID, self.text, event, None, CHAT_MAX_LEN)
        self.caret = 0.0
        return None

    def box_rect(self):
        return pygame.Rect(CHAT_X, VIRTUAL_H - CHAT_BOTTOM - 28, CHAT_W, 28)

    def handle_click(self, pos):
        """Kutu açıkken tıklama: yazının üstündeyse imleç tıklanan harfe gider."""
        box = self.box_rect()
        if box.collidepoint(pos):
            text_click(self.FID, self.text, 16, box.x + 26, pos[0])
            self.caret = 0.0

    # ---- çizim ----
    def update(self, dt):
        self.caret += dt
        if self.open:
            return               # kutu açıkken satırlar solmaz
        for row in self.log:
            row[2] -= dt
        self.log = [row for row in self.log if row[2] > 0]

    def draw(self, surf):
        rows = self.log[-CHAT_LOG_LINES:]
        if not rows and not self.open:
            return
        x = CHAT_X
        line_h = 17
        box_h = 28 if self.open else 0
        log_h = line_h * len(rows)
        top = VIRTUAL_H - CHAT_BOTTOM - box_h - log_h
        if rows:
            panel(surf, pygame.Rect(x, top - 6, CHAT_W, log_h + 12),
                  alpha=150 if self.open else 105, radius=10, edge_w=1)
            for i, (line, col, life) in enumerate(rows):
                # Son saniyede satır solar: kaybolması ani olmasın.
                fade = clamp(life / 1.2, 0.25, 1.0) if not self.open else 1.0
                draw_text(surf, line, (x + 12, top + i * line_h),
                          15, scale_col(col, fade), shadow=False)
        if not self.open:
            return
        box = pygame.Rect(x, VIRTUAL_H - CHAT_BOTTOM - box_h, CHAT_W, box_h)
        panel(surf, box, alpha=232, radius=10, edge_w=2)
        draw_text(surf, "»", (box.x + 10, box.y + 6), 16, CYAN, bold=True,
                  shadow=False)
        # Metin kutudan taşarsa imlecin olduğu yer görünür kalır.
        _st, vis, cdx = text_view(self.FID, self.text, 16, CHAT_W - 46)
        draw_text(surf, vis, (box.x + 26, box.y + 6), 16, TEXT, shadow=False)
        if (self.caret * 2.2) % 1.0 < 0.55:
            cx = box.x + 27 + cdx
            pygame.draw.line(surf, TEXT, (cx, box.y + 6), (cx, box.y + 22), 2)


# ---- yılbaşı ana menü süsleri ----
# NEW_YEAR_THEME açıkken ana menüye eklenenler (hepsi kodla çizilir, dış dosya
# yok): Ağır parçalar (ağaç, kar yığını) bir kez çizilip saklanır; her karede
# yalnızca küçük, hareketli parçalar çizilir:
# * gökyüzünde ay ve önünden geçen noel baba + 4 geyikli kızak (öndeki
#   Rudolf'un burnu kırmızı yanar, kızağın ardında yıldız tozu)
# * ışık dizisinden sarkan süs topları
# * sol altta yılbaşı ağacı (yanıp sönen toplar, tepede yıldız), altında hediye
#   kutuları ve bir kardan adam
# * ekranın dibinde kar yığını, menü düğmelerinin üstünde kar
def ellipse_aa(surf, cx, cy, rx, ry, col):
    rx, ry = int(round(rx)), int(round(ry))
    if rx < 1 or ry < 1:
        return
    cx, cy = int(round(cx)), int(round(cy))
    if _gfx is not None:
        try:
            _gfx.filled_ellipse(surf, cx, cy, rx, ry, col)
            _gfx.aaellipse(surf, cx, cy, rx, ry, col)
            return
        except Exception:
            pass
    pygame.draw.ellipse(surf, col, pygame.Rect(cx - rx, cy - ry, rx * 2, ry * 2))


