class MenuXmas:
    SANTA_FLY = 11.0          # ekranı bir kez geçme süresi (sn)
    SANTA_GAP = 6.0           # iki geçiş arasındaki bekleme (sn)
    MOON = (150, 150, 40)     # ay: x, y, yarıçap
    TREE = (98, 704)          # ağacın gövde dibi

    def __init__(self):
        self.t = 0.0
        self.santa_t = -2.0   # < 0: bekleniyor, 0..SANTA_FLY: uçuyor
        self.santa_dir = 1
        self.trail = []       # [x, y, ömür, renk]
        self._tree = None
        self._drift = None
        self._caps = {}
        rnd = random.Random(26)
        cols = (XMAS_RED, XMAS_GOLD, (90, 170, 235), (170, 110, 220), XMAS_GREEN, (240, 240, 250))
        self.baubles = []
        for i, x in enumerate((48, 132, 236, 336, 944, 1032)):
            self.baubles.append((x, rnd.uniform(26, 62), cols[i % len(cols)],
                                 rnd.uniform(0, math.tau), rnd.uniform(7.5, 10.5)))
        self.tree_lights = [(rnd.uniform(-1, 1), rnd.uniform(0.12, 0.92), cols[i % 4],
                             rnd.uniform(0, math.tau)) for i in range(26)]

    def update(self, dt):
        self.t += dt
        self.santa_t += dt
        if self.santa_t > self.SANTA_FLY:
            self.santa_t = -self.SANTA_GAP
            self.santa_dir *= -1
        if 0.0 <= self.santa_t <= self.SANTA_FLY:
            sx, sy = self.santa_pos(self.santa_t / self.SANTA_FLY)
            for _ in range(2):
                self.trail.append([sx - self.santa_dir * 26 + random.uniform(-4, 4),
                                   sy + 10 + random.uniform(-3, 3),
                                   random.uniform(0.8, 1.5),
                                   random.choice((XMAS_GOLD, (255, 255, 255), (255, 236, 170)))])
        for p in self.trail:
            p[2] -= dt
            p[1] += 10 * dt
        if len(self.trail) > 260:
            del self.trail[:len(self.trail) - 260]
        self.trail = [p for p in self.trail if p[2] > 0]

    @staticmethod
    def wire_y(x):
        """_draw_new_year_banner'daki ışık telinin o x'teki yüksekliği."""
        return 20 + 6 * math.sin((x / (VIRTUAL_W / 22.0)) * 0.7)

    def santa_pos(self, f):
        if self.santa_dir > 0:
            x = lerp(-280, VIRTUAL_W + 280, f)
        else:
            x = lerp(VIRTUAL_W + 280, -280, f)
        y = 232 - 122 * math.sin(math.pi * f) + 5 * math.sin(self.t * 2.3)
        return x, y

    def draw_sky(self, surf):
        """ay + kızak + yıldız tozu."""
        mx, my, mr = self.MOON
        add_glow(surf, mx, my, mr * 4.2, (120, 120, 160), 0.30)
        add_glow(surf, mx, my, mr * 2.2, (255, 240, 200), 0.32)
        disc_grad(surf, mx, my, mr, (255, 250, 228), (226, 214, 180), 8)
        for (cx, cy, cr) in ((-12, -8, 8), (10, 6, 6), (-4, 16, 4.5), (16, -14, 3.5), (-20, 10, 3)):
            circle_aa(surf, mx + cx, my + cy, cr, (214, 202, 168))
            circle_aa(surf, mx + cx - 1, my + cy - 1, max(1, cr - 1.5), (222, 210, 176))
        for p in self.trail:
            k = clamp(p[2] / 1.2, 0.0, 1.0)
            blit_disc(surf, p[0], p[1], 1.2 + 1.6 * k, p[3], int(230 * k))
        if 0.0 <= self.santa_t <= self.SANTA_FLY:
            f = self.santa_t / self.SANTA_FLY
            sx, sy = self.santa_pos(f)
            self._draw_team(surf, sx, sy, self.santa_dir)
            if 0.40 < f < 0.62:
                a = int(255 * min(1.0, (f - 0.40) / 0.04, (0.62 - f) / 0.04))
                draw_text(surf, "HO HO HO!", (sx - self.santa_dir * 6, sy - 58), 14,
                          (255, 236, 200), bold=True, center=True, alpha=a)

    def _draw_team(self, surf, sx, sy, d):
        t = self.t
        deer = []
        for i in range(4):
            bob = math.sin(t * 7.5 + i * 0.9) * 2.2
            deer.append((sx + d * (58 + i * 36), sy - 8 - i * 3 + bob))
        hand = (sx + d * 9, sy - 24 + math.sin(t * 6) * 2)
        # dizgin: Noel Baba'nın elinden en öndeki geyiğe
        pts = [hand] + [(x - d * 4, y - 2) for x, y in deer]
        for a, b in zip(pts, pts[1:]):
            thick_line(surf, a, b, 1.4, (150, 96, 54), cap=False)
        for i, (x, y) in enumerate(deer):
            self._reindeer(surf, x, y, d, t, i * 1.3, lead=(i == 3))
        self._sleigh(surf, sx, sy, d, t)

    def _reindeer(self, surf, x, y, d, t, phase, lead=False):
        body, belly, dark = (146, 98, 62), (204, 166, 122), (92, 60, 38)
        sw = math.sin(t * 9 + phase)
        # bacaklar (uçuş pozu: öndekiler ileri, arkadakiler geri uzanır)
        for (bx, ang0) in ((7, 0.9), (4, 0.7), (-7, -0.9), (-10, -0.7)):
            a = ang0 + sw * 0.35
            p0 = (x + d * bx, y + 3)
            p1 = (p0[0] + d * math.sin(a) * 11, p0[1] + math.cos(a) * 9)
            thick_line(surf, p0, p1, 2.6, dark)
        ellipse_aa(surf, x, y, 14, 7, body)
        ellipse_aa(surf, x - d * 1, y + 3, 9, 3, belly)
        # boyun + kafa
        thick_line(surf, (x + d * 9, y - 2), (x + d * 15, y - 10), 5, body)
        hx, hy = x + d * 17, y - 12
        circle_aa(surf, hx, hy, 5.2, body)
        ellipse_aa(surf, hx + d * 5, hy + 2, 4.5, 3.2, belly)
        # boynuzlar
        ac = (214, 180, 128)
        thick_line(surf, (hx - d * 2, hy - 4), (hx - d * 6, hy - 14), 1.6, ac)
        thick_line(surf, (hx - d * 4, hy - 9), (hx - d * 10, hy - 11), 1.4, ac)
        thick_line(surf, (hx + d * 1, hy - 4), (hx + d * 1, hy - 13), 1.6, ac)
        thick_line(surf, (hx + d * 1, hy - 9), (hx + d * 5, hy - 12), 1.4, ac)
        circle_aa(surf, hx + d * 1, hy - 2, 1.2, (20, 14, 10))       # göz
        # koşum: kırmızı kayış + altın çan
        thick_line(surf, (x + d * 6, y - 6), (x + d * 3, y + 6), 3, XMAS_RED, cap=False)
        circle_aa(surf, x + d * 4, y + 6, 2.2, XMAS_GOLD)
        circle_aa(surf, x - d * 14, y - 3, 2.6, (240, 236, 228))     # kuyruk
        nx, ny = hx + d * 9.5, hy + 1.5
        if lead:
            k = 0.55 + 0.45 * math.sin(t * 5)
            add_glow(surf, nx, ny, 22, (255, 60, 60), 0.35 + 0.35 * k)
            circle_aa(surf, nx, ny, 2.8, (255, 70, 70))
            circle_aa(surf, nx - 0.8, ny - 0.8, 1, (255, 200, 200))
        else:
            circle_aa(surf, nx, ny, 2.0, (40, 26, 20))

    def _sleigh(self, surf, sx, sy, d, t):
        def P(px, py):
            return (sx + d * px, sy + py)
        # çuval (Noel Baba'nın arkasında)
        circle_aa(surf, *P(-16, -18), 11, (120, 82, 50))
        circle_aa(surf, *P(-18, -21), 6, (142, 100, 64))
        circle_aa(surf, *P(-10, -27), 4, (198, 60, 70))     # çuvaldan taşan hediye
        circle_aa(surf, *P(-20, -28), 3.5, (80, 160, 220))
        # Noel Baba
        circle_aa(surf, *P(0, -16), 10.5, (204, 38, 46))       # gövde
        thick_line(surf, P(-9, -10), P(9, -10), 3, (30, 22, 20), cap=False)   # kemer
        circle_aa(surf, *P(0, -10), 2, XMAS_GOLD)
        circle_aa(surf, *P(2, -29), 6.5, (244, 206, 178))       # yüz
        circle_aa(surf, *P(5, -25), 6, (250, 250, 252))          # sakal
        circle_aa(surf, *P(4.5, -29.5), 1.5, (232, 150, 140))    # burun
        poly_aa(surf, [P(-5, -33), P(9, -34), P(-9, -46)], (204, 38, 46))   # şapka
        thick_line(surf, P(-6, -33), P(10, -34), 4, (250, 250, 252))
        circle_aa(surf, *P(-10, -46), 3.2, (250, 250, 252))
        thick_line(surf, P(4, -18), (sx + d * 9, sy - 24 + math.sin(t * 6) * 2), 3.4,
                   (204, 38, 46))
        circle_aa(surf, sx + d * 9, sy - 24 + math.sin(t * 6) * 2, 2.6, (250, 250, 252))
        # kızak gövdesi
        body = [P(-30, -18), P(-26, 4), P(18, 4), P(28, -6), P(30, -14), P(24, -14),
                P(18, -6), P(-18, -6), P(-22, -18)]
        poly_aa(surf, [(x, y + 2) for x, y in body], (90, 18, 24))
        poly_aa(surf, body, (196, 40, 52))
        thick_line(surf, P(-24, -4), P(18, -4), 2, XMAS_GOLD, cap=False)
        thick_line(surf, P(-28, -17), P(-22, -17), 2, XMAS_GOLD)
        # kızak ayakları (altın)
        thick_line(surf, P(-30, 12), P(26, 12), 2.4, XMAS_GOLD)
        thick_line(surf, P(26, 12), P(34, 4), 2.4, XMAS_GOLD)
        circle_aa(surf, *P(34, 2), 2.6, XMAS_GOLD)
        thick_line(surf, P(-16, 4), P(-16, 12), 2, XMAS_GOLD, cap=False)
        thick_line(surf, P(12, 4), P(12, 12), 2, XMAS_GOLD, cap=False)

    def draw_baubles(self, surf):
        """Işık telinden sarkan büyük süs topları."""
        for (x, ln, col, ph, r) in self.baubles:
            top = self.wire_y(x)
            sw = math.sin(self.t * 1.3 + ph) * 3.0
            bx, by = x + sw, top + ln
            pygame.draw.aaline(surf, (150, 140, 120), (x, top), (bx, by - r))
            pygame.draw.rect(surf, (210, 176, 96), pygame.Rect(int(bx - 3), int(by - r - 4), 6, 5),
                             border_radius=1)
            add_glow(surf, bx, by, r * 2.6, col, 0.14)
            disc_grad(surf, bx, by, r, lighten(col, 0.35), scale_col(col, 0.62), 6)
            thick_line(surf, (bx - r * 0.85, by + 1), (bx + r * 0.85, by + 1), 1.6,
                       lighten(col, 0.55), cap=False)
            circle_aa(surf, bx - r * 0.35, by - r * 0.38, max(1.5, r * 0.26), (255, 255, 255))

    def _build_tree(self):
        """Ağaç bir kez, 3 kat büyük ve düz çizilip yumuşakça küçültülür (saydam yüzeyde gfxdraw'ın bıraktığı kenar deliklerini önler)."""
        W, H, S = 200, 190, 3
        s = pygame.Surface((W * S, H * S), pygame.SRCALPHA)

        def P(pts):
            return [(int(x * S), int(y * S)) for x, y in pts]

        cx, base = W // 2, H - 8
        pygame.draw.rect(s, (96, 62, 36), pygame.Rect((cx - 9) * S, (base - 22) * S, 18 * S, 22 * S),
                         border_radius=3 * S)
        tiers = ((base - 18, 72, 62), (base - 58, 58, 54), (base - 94, 44, 48), (base - 126, 30, 40))
        for (yb, hw, h) in tiers:
            pts = [(cx - hw, yb), (cx + hw, yb), (cx, yb - h)]
            pygame.draw.polygon(s, (18, 64, 40), P([(x, y + 3) for x, y in pts]))
            pygame.draw.polygon(s, (40, 128, 72), P(pts))
            pygame.draw.polygon(s, (32, 108, 62), P([(cx + 2, yb - h + 4), (cx + hw - 4, yb),
                                                     (cx + hw, yb), (cx, yb - h)]))
            # dal ucundaki kar
            for k in range(5):
                fx = -0.8 + k * 0.4
                pygame.draw.circle(s, (*XMAS_SNOW, 255),
                                   (int((cx + fx * hw) * S), int((yb - 1 + abs(fx) * 1.5) * S)),
                                   int((4.6 - abs(fx) * 1.4) * S))
        # altın şerit (garland)
        for (yb, hw, h) in tiers[:3]:
            pts = []
            for k in range(17):
                f = k / 16.0
                pts.append((cx - hw * 0.82 + hw * 1.64 * f, yb - h * 0.42 + math.sin(f * math.pi) * 9))
            pygame.draw.lines(s, XMAS_GOLD, False, P(pts), int(2.4 * S))
            for (x, y) in pts[1:-1:2]:
                pygame.draw.circle(s, (255, 236, 160), (int(x * S), int(y * S)), int(1.3 * S))
        return pygame.transform.smoothscale(s, (W, H))

    def _tree_layout(self):
        return self.TREE[0], self.TREE[1]

    def draw_ground(self, surf):
        """Ekranın dibindeki kar + yılbaşı ağacı + hediyeler + kardan adam."""
        if self._drift is None:
            d = pygame.Surface((VIRTUAL_W, 56), pygame.SRCALPHA)
            pts = [(0, 56)]
            for x in range(0, VIRTUAL_W + 20, 20):
                pts.append((x, 30 + 7 * math.sin(x * 0.011) + 4 * math.sin(x * 0.037 + 1.3)))
            pts.append((VIRTUAL_W, 56))
            pygame.draw.polygon(d, (196, 210, 236, 255), pts)
            pygame.draw.polygon(d, (*XMAS_SNOW, 255), [(x, y + 3) for x, y in pts[1:-1]]
                                + [(VIRTUAL_W, 56), (0, 56)])
            self._drift = d
        surf.blit(self._drift, (0, VIRTUAL_H - 56))
        for i in range(10):     # karda parıltılar
            x = (i * 137.0 + 41) % VIRTUAL_W
            k = 0.5 + 0.5 * math.sin(self.t * 2.4 + i * 1.7)
            if k > 0.75:
                blit_disc(surf, x, VIRTUAL_H - 14 - (i % 3) * 5, 1.6, (255, 255, 255), int(255 * k))

        if self._tree is None:
            self._tree = self._build_tree()
        tx, ty = self._tree_layout()
        add_glow(surf, tx, ty - 80, 150, (255, 210, 120), 0.10)
        surf.blit(self._tree, (tx - self._tree.get_width() // 2, ty - self._tree.get_height() + 8))
        # yanıp sönen toplar
        top_y = ty - 150
        for (fx, fy, col, ph) in self.tree_lights:
            yy = top_y + fy * 128
            half = 6 + fy * 62
            xx = tx + fx * half * 0.78
            k = 0.5 + 0.5 * math.sin(self.t * 2.6 + ph)
            add_glow(surf, xx, yy, 12, col, 0.18 + 0.30 * k)
            circle_aa(surf, xx, yy, 3.2, lighten(col, 0.25 * k))
        # tepedeki yıldız
        sy_ = top_y - 4
        k = 0.5 + 0.5 * math.sin(self.t * 2.0)
        add_glow(surf, tx, sy_, 46, XMAS_GOLD, 0.35 + 0.25 * k)
        pts = []
        for i in range(10):
            a = -math.pi / 2 + i * math.pi / 5
            rr = 11 if i % 2 == 0 else 4.6
            pts.append((tx + math.cos(a) * rr, sy_ + math.sin(a) * rr))
        poly_aa(surf, pts, (255, 214, 96))
        poly_aa(surf, poly_inset(pts, 0.5), (255, 244, 190))

        # hediyeler
        for (gx, gw, gh, body, ribbon) in ((tx - 62, 28, 22, (200, 48, 60), XMAS_GOLD),
                                           (tx + 40, 24, 30, (66, 128, 210), (245, 245, 250)),
                                           (tx - 30, 22, 16, (66, 160, 96), XMAS_RED)):
            r = pygame.Rect(int(gx), int(ty - gh), gw, gh)
            pygame.draw.rect(surf, scale_col(body, 0.6), r.move(0, 2), border_radius=3)
            pygame.draw.rect(surf, body, r, border_radius=3)
            pygame.draw.rect(surf, ribbon, pygame.Rect(r.centerx - 2, r.y, 4, r.h))
            pygame.draw.rect(surf, ribbon, pygame.Rect(r.x, r.y + r.h // 2 - 2, r.w, 4))
            circle_aa(surf, r.centerx - 4, r.y - 2, 3.5, ribbon)
            circle_aa(surf, r.centerx + 4, r.y - 2, 3.5, ribbon)

        # kardan adam
        mx, my = tx + 92, ty
        for (oy, rr) in ((-14, 15), (-38, 11), (-56, 8)):
            circle_aa(surf, mx + 1, my + oy + 2, rr, (190, 204, 230))
            circle_aa(surf, mx, my + oy, rr, XMAS_SNOW)
        for oy in (-20, -32, -42):
            circle_aa(surf, mx, my + oy, 1.6, (40, 40, 50))
        circle_aa(surf, mx - 3, my - 58, 1.4, (30, 30, 36))
        circle_aa(surf, mx + 3, my - 58, 1.4, (30, 30, 36))
        poly_aa(surf, [(mx, my - 56), (mx, my - 53), (mx + 10, my - 54)], (240, 130, 50))
        pygame.draw.rect(surf, XMAS_RED, pygame.Rect(int(mx - 9), int(my - 50), 18, 4), border_radius=2)
        pygame.draw.rect(surf, XMAS_RED, pygame.Rect(int(mx + 3), int(my - 48), 4, 10), border_radius=2)
        pygame.draw.rect(surf, (28, 28, 34), pygame.Rect(int(mx - 9), int(my - 66), 18, 3))
        pygame.draw.rect(surf, (28, 28, 34), pygame.Rect(int(mx - 6), int(my - 77), 12, 11))
        # kollar
        thick_line(surf, (mx - 9, my - 40), (mx - 22, my - 48), 1.6, (110, 76, 46))
        thick_line(surf, (mx + 9, my - 40), (mx + 21, my - 50 + math.sin(self.t * 3) * 3), 1.6,
                   (110, 76, 46))

    def draw_cap(self, surf, rect, seed=0):
        """Bir düğmenin/panelin üst kenarına oturan kar."""
        rect = pygame.Rect(rect)
        key = (rect.w, seed)
        img = self._caps.get(key)
        if img is None:
            rnd = random.Random(seed * 31 + rect.w)
            w = rect.w - 14
            S = 3
            H = 22
            big = pygame.Surface((w * S, H * S), pygame.SRCALPHA)
            snow = (*XMAS_SNOW, 255)
            shade = (190, 204, 232, 255)
            pygame.draw.rect(big, (115, 84, 87, 90), pygame.Rect(3 * S, 12 * S, (w - 6) * S, 5 * S),
                             border_radius=3 * S)
            pygame.draw.rect(big, shade, pygame.Rect(0, 9 * S, w * S, 7 * S), border_radius=4 * S)
            pygame.draw.rect(big, snow, pygame.Rect(0, 8 * S, w * S, 6 * S), border_radius=4 * S)
            x = 9
            while x < w - 9:
                rr = rnd.uniform(4.5, 7.0)
                cy_ = 10 - rr * 0.35
                pygame.draw.circle(big, shade, (int(x * S), int((cy_ + 1) * S)), int(rr * S))
                pygame.draw.circle(big, snow, (int(x * S), int(cy_ * S)), int(rr * S))
                x += rnd.uniform(11, 18)
            for _ in range(max(1, w // 70)):
                dx = rnd.uniform(12, w - 12)
                dl = rnd.uniform(4, 8)
                pygame.draw.rect(big, snow, pygame.Rect(int(dx * S), 12 * S, 4 * S, int(dl * S)),
                                 border_radius=2 * S)
                pygame.draw.circle(big, snow, (int((dx + 2) * S), int((12 + dl) * S)), int(2.3 * S))
            img = pygame.transform.smoothscale(big, (w, H))
            self._caps[key] = img
        surf.blit(img, (rect.x + 7, rect.y - 10))


# ---- başarım / silahlık süsleri ----
# Kart gövdeleri (degrade + kademe rengi) ve arka planlar önbellekte tutulur;
# her karede yalnızca kıpırdayan parçalar (parıltı, kıvılcım, meşale alevi)
# çizilir.
_ACH_BODY_CACHE = {}


def ach_card_body(w, h, col, got, hover):
    key = (w, h, col, got, hover)
    img = _ACH_BODY_CACHE.get(key)
    if img is None:
        if len(_ACH_BODY_CACHE) > 120:
            _ACH_BODY_CACHE.clear()
        if got:
            fill = mix_col(col, (34, 26, 28), 0.74 if hover else 0.80)
        else:
            fill = (50, 39, 39) if hover else (42, 32, 33)
        img = pygame.Surface((w, h), pygame.SRCALPHA)
        img.fill((*fill, 248))
        hand_mask(img, 13)
        _ACH_BODY_CACHE[key] = img
    return img


def draw_padlock(surf, cx, cy, s, col):
    """Küçük asma kilit (kilitli başarım madalyonu)."""
    pygame.draw.arc(surf, col, pygame.Rect(int(cx - s * 0.42), int(cy - s * 0.95), int(s * 0.84),
                                           int(s * 0.95)), 0, math.pi, max(2, int(s * 0.16)))
    body = pygame.Rect(int(cx - s * 0.62), int(cy - s * 0.42), int(s * 1.24), int(s * 0.98))
    pygame.draw.rect(surf, col, body, border_radius=max(2, int(s * 0.18)))
    circle_aa(surf, cx, cy + s * 0.02, max(1.5, s * 0.15), (14, 15, 24))
    pygame.draw.rect(surf, (14, 15, 24), pygame.Rect(int(cx - 1), int(cy + s * 0.05), 3,
                                                     max(2, int(s * 0.28))))


_HALL_CACHE = {}


def draw_trophy_hall(surf, t):
    """Başarımlar arka planı: tepeden inen iki altın ışık hüzmesi + uçuşan altın tozu."""
    beams = _HALL_CACHE.get("beams")
    if beams is None:
        beams = pygame.Surface((VIRTUAL_W, VIRTUAL_H), pygame.SRCALPHA)
        for (x0, x1) in ((300, 120), (980, 1160)):
            for k in range(14):
                f = k / 14.0
                a = int(16 * (1 - f))
                w0, w1 = 30 + 40 * f, 160 + 220 * f
                pygame.draw.polygon(beams, (255, 214, 130, a),
                                    [(x0 - w0, 0), (x0 + w0, 0), (x1 + w1, VIRTUAL_H),
                                     (x1 - w1, VIRTUAL_H)])
        _HALL_CACHE["beams"] = beams
    surf.blit(beams, (0, 0))
    for i in range(46):
        spd = 14 + (i * 7) % 23
        x = (i * 97.3 + math.sin(t * 0.6 + i) * 18) % VIRTUAL_W
        y = VIRTUAL_H + 20 - ((t * spd + i * 53.7) % (VIRTUAL_H + 40))
        k = 0.5 + 0.5 * math.sin(t * 2.2 + i * 1.9)
        blit_disc(surf, x, y, 1.2 + 1.3 * k, (255, 220, 140), int(60 + 120 * k))


def draw_armory_bg(surf, t):
    """Silahlık arka planı: taş duvar, iki yanda yanan meşaleler, yükselen kıvılcımlar."""
    wall = _HALL_CACHE.get("armory")
    if wall is None:
        wall = pygame.Surface((VIRTUAL_W, VIRTUAL_H)).convert()
        for y in range(VIRTUAL_H):
            f = y / VIRTUAL_H
            pygame.draw.line(wall, mix_col((30, 20, 20), (12, 10, 16), f), (0, y), (VIRTUAL_W, y))
        rnd = random.Random(11)
        bh = 34
        for row in range(VIRTUAL_H // bh + 1):
            y = row * bh
            off = (row % 2) * 46
            pygame.draw.line(wall, (16, 11, 12), (0, y), (VIRTUAL_W, y), 2)
            for x in range(-off, VIRTUAL_W, 92):
                pygame.draw.line(wall, (16, 11, 12), (x, y), (x, y + bh), 2)
                sh = rnd.randint(-6, 6)
                if sh > 2:
                    pygame.draw.rect(wall, (36 + sh, 26 + sh, 24 + sh),
                                     pygame.Rect(x + 3, y + 3, 86, bh - 5), border_radius=3)
                pygame.draw.line(wall, (48, 34, 30), (x + 3, y + 3), (x + 86, y + 3), 1)
        # çapraz kılıç gölgeleri (duvara asılı silah rafı hissi)
        for (cx, cy) in ((64, 640), (VIRTUAL_W - 64, 640)):
            for sg in (-1, 1):
                a = math.radians(45 * sg)
                dx, dy = math.sin(a) * 60, -math.cos(a) * 60
                thick_line(wall, (cx - dx, cy - dy), (cx + dx, cy + dy), 6, (22, 16, 16))
                thick_line(wall, (cx - dx * 0.55 - dy * 0.18, cy - dy * 0.55 + dx * 0.18),
                           (cx - dx * 0.55 + dy * 0.18, cy - dy * 0.55 - dx * 0.18), 5, (22, 16, 16))
        # kenar karartma
        vg = pygame.Surface((VIRTUAL_W, VIRTUAL_H), pygame.SRCALPHA)
        for k in range(18):
            pygame.draw.rect(vg, (0, 0, 0, 10), vg.get_rect().inflate(-k * 26, -k * 16), width=14,
                             border_radius=60)
        wall.blit(vg, (0, 0))
        _HALL_CACHE["armory"] = wall
    surf.blit(wall, (0, 0))
    # meşaleler
    for (tx, ty) in ((38, 300), (VIRTUAL_W - 38, 300)):
        fl = 0.75 + 0.25 * math.sin(t * 11 + tx) * math.sin(t * 7.3)
        add_glow(surf, tx, ty - 16, 230 * fl, (255, 140, 50), 0.32)
        add_glow(surf, tx, ty - 16, 70, (255, 200, 110), 0.45 * fl)
        pygame.draw.rect(surf, (70, 52, 40), pygame.Rect(tx - 4, ty, 8, 46), border_radius=2)
        pygame.draw.rect(surf, (110, 84, 60), pygame.Rect(tx - 9, ty - 4, 18, 8), border_radius=3)
        for j, (col, sc) in enumerate((((240, 90, 30), 1.0), ((255, 170, 60), 0.68),
                                        ((255, 238, 170), 0.36))):
            h = 26 * sc * fl
            w = 10 * sc
            sway = math.sin(t * 9 + j) * 2.5 * sc
            poly_aa(surf, [(tx - w, ty - 4), (tx + w, ty - 4), (tx + sway, ty - 4 - h)], col)
            circle_aa(surf, tx, ty - 6, w * 0.95, col)
    # kıvılcımlar
    for i in range(40):
        spd = 30 + (i * 13) % 40
        base_x = 38 if i % 2 == 0 else VIRTUAL_W - 38
        if i % 5 == 0:
            base_x = (i * 131.7) % VIRTUAL_W
        life = (t * spd + i * 37.0) % 300
        x = base_x + math.sin(t * 1.7 + i) * (8 + life * 0.12)
        y = 290 - life if i % 5 else VIRTUAL_H - life * 2.2
        k = clamp(1.0 - life / 300.0, 0.0, 1.0)
        blit_disc(surf, x, y, 1.0 + 1.4 * k, (255, 170 + int(60 * k), 80), int(220 * k))


_BEAM_CACHE = {}


def _beam_sprite(length, width, col, ang_deg):
    """Tavandan inen spot ışığı konisi (açı 2 derecelik basamakla önbellekli)."""
    a = int(round(ang_deg / 2.0)) * 2
    key = (length, width, col, a)
    spr = _BEAM_CACHE.get(key)
    if spr is None:
        if len(_BEAM_CACHE) > 120:
            _BEAM_CACHE.clear()
        # toplamalı karışımla basılır: alfa yok, parlaklık doğrudan renkte.
        # Siyah zemin hiçbir şey eklemez (döndürmenin açtığı köşeler dahil).
        base = pygame.Surface((width, length))
        base.fill((0, 0, 0))
        for y in range(length):
            k = y / max(1, length - 1)
            hw = 10 + (width / 2 - 10) * k
            inten = 0.16 * (1.0 - k) ** 1.5
            pygame.draw.line(base, scale_col(col, inten), (width / 2 - hw, y), (width / 2 + hw, y))
        spr = pygame.transform.rotate(base, a)
        _BEAM_CACHE[key] = spr
    return spr


# ---- mağaza görünümü - hazine odası ----
# Mağazanın kendi arka planı: koyu lacivert-mor kubbe, arkada yüksek kemerli
# bir hazine odası, iki köşede parlayan kristal kümeleri ve altın yığınları,
# tavandan inen gezen iki spot ışığı ve yukarı süzülen elmas kırıntıları.
_STORE_CACHE = {}


def _crystal(surf, x, y, h, w, col, lean=0.0):
    """Tek kristal sütunu: iki yüzlü, uçlu, parlak kenarlı."""
    tip = (x + lean * h, y - h)
    left = [(x - w, y), (x - w * 0.8, y - h * 0.72), tip, (x, y)]
    right = [(x, y), tip, (x + w * 0.8, y - h * 0.72), (x + w, y)]
    pygame.draw.polygon(surf, scale_col(col, 0.55), left)
    pygame.draw.polygon(surf, scale_col(col, 0.85), right)
    pygame.draw.line(surf, lighten(col, 0.45), (x, y), tip, 2)
    pygame.draw.polygon(surf, lighten(col, 0.25), left + right[1:], 1)


def _coin_pile(surf, cx, cy, w, h, rnd):
    """Altın sikke yığını (yarım elips + üstüne serpilmiş sikkeler)."""
    pygame.draw.ellipse(surf, (92, 64, 20), pygame.Rect(cx - w / 2, cy - h, w, h * 2))
    pygame.draw.ellipse(surf, (150, 108, 34), pygame.Rect(cx - w / 2 + 6, cy - h + 4, w - 12, h * 2 - 10))
    for _ in range(int(w * 0.9)):
        a = rnd.uniform(math.pi, math.tau)
        rr = rnd.random() ** 0.6
        px = cx + math.cos(a) * w * 0.46 * rr
        py = cy + math.sin(a) * h * 0.92 * rr
        c = rnd.choice(((232, 186, 90), (255, 214, 120), (196, 146, 54)))
        pygame.draw.ellipse(surf, scale_col(c, 0.6), pygame.Rect(px - 6, py - 2, 12, 6))
        pygame.draw.ellipse(surf, c, pygame.Rect(px - 6, py - 3, 12, 5))


def draw_store_bg(surf, t):
    wall = _STORE_CACHE.get("bg")
    if wall is None:
        rnd = random.Random(1907)
        wall = pygame.Surface((VIRTUAL_W, VIRTUAL_H)).convert()
        for y in range(VIRTUAL_H):
            k = y / VIRTUAL_H
            c = mix_col((10, 16, 40), (30, 16, 54), min(1.0, k * 1.6)) if k < 0.62 else \
                mix_col((30, 16, 54), (8, 8, 18), (k - 0.62) / 0.38)
            pygame.draw.line(wall, c, (0, y), (VIRTUAL_W, y))
        floor_y = 600
        # arka kemerler
        n_arch = 6
        aw = VIRTUAL_W / n_arch
        for i in range(n_arch):
            cx = aw * (i + 0.5)
            r = pygame.Rect(int(cx - aw * 0.36), 190, int(aw * 0.72), floor_y - 190)
            pygame.draw.rect(wall, (14, 12, 32), r)
            pygame.draw.ellipse(wall, (14, 12, 32), pygame.Rect(r.x, r.y - r.w // 2, r.w, r.w))
            pygame.draw.arc(wall, (64, 70, 130), pygame.Rect(r.x - 3, r.y - r.w // 2 - 3, r.w + 6, r.w + 6),
                            0, math.pi, 3)
            # kemerin içinde soluk raf ve elmas sıraları
            for sh in range(3):
                yy = r.y + 70 + sh * 92
                pygame.draw.line(wall, (40, 40, 78), (r.x + 12, yy), (r.right - 12, yy), 3)
                for g in range(4):
                    gx = r.x + 26 + g * (r.w - 52) / 3.0
                    col = rnd.choice(((60, 120, 170), (110, 80, 160), (150, 120, 60), (60, 130, 120)))
                    pygame.draw.polygon(wall, col, [(gx, yy - 16), (gx + 8, yy - 8), (gx, yy - 1), (gx - 8, yy - 8)])
        for i in range(n_arch + 1):
            x = int(aw * i)
            col_r = pygame.Rect(x - 14, 90, 28, floor_y - 90)
            pygame.draw.rect(wall, (34, 32, 66), col_r)
            for k in range(3):
                pygame.draw.line(wall, (46, 44, 86), (col_r.x + 6 + k * 8, col_r.y), (col_r.x + 6 + k * 8, col_r.bottom), 2)
            pygame.draw.rect(wall, (150, 120, 64), pygame.Rect(col_r.x - 5, col_r.y, col_r.w + 10, 10))
            pygame.draw.rect(wall, (150, 120, 64), pygame.Rect(col_r.x - 5, col_r.bottom - 10, col_r.w + 10, 10))
        # parlak zemin
        pygame.draw.rect(wall, (16, 12, 30), pygame.Rect(0, floor_y, VIRTUAL_W, VIRTUAL_H - floor_y))
        pygame.draw.line(wall, (150, 120, 64), (0, floor_y), (VIRTUAL_W, floor_y), 3)
        for i in range(16):
            x0 = VIRTUAL_W / 2 + (i - 7.5) * 90
            pygame.draw.line(wall, (30, 24, 50), (VIRTUAL_W / 2 + (x0 - VIRTUAL_W / 2) * 0.6, floor_y),
                             (VIRTUAL_W / 2 + (x0 - VIRTUAL_W / 2) * 1.8, VIRTUAL_H), 1)
        # köşelerde altın yığınları ve kristal kümeleri
        for cx, sgn in ((110, 1), (VIRTUAL_W - 110, -1)):
            _coin_pile(wall, cx, floor_y + 34, 230, 46, rnd)
            for j, (dx, hh, ww, col) in enumerate(((-40, 150, 22, (90, 200, 255)), (0, 210, 28, (150, 120, 255)),
                                                    (42, 130, 20, (90, 230, 210)), (78, 90, 16, (255, 150, 220)))):
                _crystal(wall, cx + dx * sgn, floor_y + 6, hh, ww, col, lean=0.08 * sgn * (j - 1.5))
        dk = pygame.Surface((VIRTUAL_W, VIRTUAL_H), pygame.SRCALPHA)
        dk.fill((6, 4, 16, 60))
        wall.blit(dk, (0, 0))
        _vignette(wall)
        _STORE_CACHE["bg"] = wall
    surf.blit(wall, (0, 0))
    # kristallerin nabız gibi atan ışığı
    for cx in (110, VIRTUAL_W - 110):
        k = 0.5 + 0.5 * math.sin(t * 1.4 + cx)
        add_glow(surf, cx, 520, 150, (120, 170, 255), 0.16 + 0.10 * k)
    # gezen iki spot ışığı
    for k, (ox, col) in enumerate(((VIRTUAL_W * 0.30, (120, 200, 255)), (VIRTUAL_W * 0.70, (255, 214, 140)))):
        ang = math.sin(t * 0.38 + k * 2.4) * 20
        spr = _beam_sprite(660, 320, col, ang)
        r = spr.get_rect(midtop=(ox, -20))
        r.centerx = ox - math.sin(math.radians(ang)) * 320
        surf.blit(spr, r, special_flags=pygame.BLEND_RGB_ADD)
    # yukarı süzülen elmas kırıntıları
    for i in range(34):
        x = (i * 97.3 + math.sin(t * 0.5 + i) * 26) % VIRTUAL_W
        y = VIRTUAL_H - ((t * (16 + i % 6 * 5) + i * 61.7) % (VIRTUAL_H + 40))
        k = 0.5 + 0.5 * math.sin(t * 2.4 + i * 1.7)
        col = ((120, 210, 255), (190, 160, 255), (255, 214, 140))[i % 3]
        if i % 5 == 0:
            draw_icon(surf, x, y, "gem", col, 4 + 2 * k)
        elif i % 5 == 1:
            _sparkle(surf, x, y, 1.6 + 2.2 * k, col)
        else:
            blit_disc(surf, x, y, 1.0 + 1.1 * k, col, int(50 + 120 * k))


def store_card_body(w, h, accent, hover=False, featured=False):
    """Mağaza kartının gövdesi: kartın renginden hafif boyanmış düz zemin,
    yuvarlak köşe. Kenar nötr; öne çıkan kartta açık renk."""
    key = ("card", w, h, accent, hover, featured)
    img = _STORE_CACHE.get(key)
    if img is None:
        if len(_STORE_CACHE) > 160:
            bg = _STORE_CACHE.get("bg")
            _STORE_CACHE.clear()
            if bg is not None:
                _STORE_CACHE["bg"] = bg
        img = pygame.Surface((w, h), pygame.SRCALPHA)
        img.fill((*mix_col(accent, (34, 26, 28), 0.72 if hover else 0.80), 248))
        hand_mask(img, 14)
        edge = lighten(accent, 0.15) if featured else ((132, 106, 108) if hover else (92, 72, 74))
        ink_frame(img, img.get_rect(), edge, 14, 3 if featured else 2)
        _STORE_CACHE[key] = img
    return img


# Yığındaki elmasların yerleşimi (önden arkaya sıralanır)
_GEM_PILE = ((0, 0), (-24, 8), (24, 8), (0, -16), (-46, 18), (46, 18), (-22, -30), (22, -30))


def draw_gem_pile(surf, cx, cy, tier, accent, t):
    n = max(1, min(len(_GEM_PILE), int(tier)))
    pts = sorted(_GEM_PILE[:n], key=lambda p: p[1])
    add_glow(surf, cx, cy, 46 + 9 * n, accent, 0.30 + 0.03 * n)
    pygame.draw.ellipse(surf, (8, 8, 18), pygame.Rect(cx - 30 - 6 * n, cy + 22, 60 + 12 * n, 14))
    for j, (dx, dy) in enumerate(pts):
        bob = math.sin(t * 2.0 + j * 1.3) * 2.0
        sz = 17 + (3 if (dx, dy) == (0, 0) else 0) + min(4, n // 2)
        col = accent if j % 3 else lighten(accent, 0.25)
        draw_icon(surf, cx + dx, cy + dy + bob, "gem", col, sz)
    if n >= 5:
        sp = (t * 0.9) % 2.0
        if sp < 1.0:
            _sparkle(surf, cx - 30 + 60 * sp, cy - 24 - 8 * math.sin(sp * math.pi), 3.2, WHITE)


def draw_skin_market_bg(surf, t):
    """skin market arka planı: kahramanlar salonu - yüksek taş kemerler"""
    wall = _HALL_CACHE.get("skins")
    if wall is None:
        wall = pygame.Surface((VIRTUAL_W, VIRTUAL_H)).convert()
        for y in range(VIRTUAL_H):
            pygame.draw.line(wall, mix_col((34, 24, 58), (10, 8, 22), y / VIRTUAL_H),
                             (0, y), (VIRTUAL_W, y))
        floor_y = 560
        # mermer satranç zemin (perspektifli)
        for row in range(7):
            y0 = floor_y + row * row * 3.4 + row * 6
            y1 = floor_y + (row + 1) * (row + 1) * 3.4 + (row + 1) * 6
            n = 18
            for i in range(-2, n + 2):
                def px(i_, y_):
                    k = (y_ - floor_y) / 200.0
                    return VIRTUAL_W / 2 + (i_ - n / 2) * (VIRTUAL_W / n) * (1.0 + k * 1.4)
                pts = [(px(i, y0), y0), (px(i + 1, y0), y0), (px(i + 1, y1), y1), (px(i, y1), y1)]
                col = (58, 46, 78) if (i + row) % 2 else (28, 22, 40)
                pygame.draw.polygon(wall, col, pts)
        pygame.draw.line(wall, (196, 154, 84), (0, floor_y), (VIRTUAL_W, floor_y), 3)
        pygame.draw.line(wall, (70, 52, 30), (0, floor_y + 3), (VIRTUAL_W, floor_y + 3), 2)
        # kemerler + sütunlar
        n_arch = 5
        aw = VIRTUAL_W / n_arch
        for i in range(n_arch):
            cx = aw * (i + 0.5)
            r = pygame.Rect(int(cx - aw * 0.34), 150, int(aw * 0.68), floor_y - 150)
            pygame.draw.rect(wall, (16, 12, 30), r)
            pygame.draw.ellipse(wall, (16, 12, 30), pygame.Rect(r.x, r.y - r.w // 2, r.w, r.w))
            pygame.draw.arc(wall, (120, 96, 150), pygame.Rect(r.x - 4, r.y - r.w // 2 - 4, r.w + 8, r.w + 8),
                            0, math.pi, 4)
            for xx in (r.x - 2, r.right + 2):
                pygame.draw.line(wall, (90, 72, 120), (xx, r.y), (xx, floor_y), 4)
            # kaide
            pd = pygame.Rect(int(cx - 46), floor_y - 64, 92, 64)
            pygame.draw.rect(wall, (60, 50, 82), pd)
            pygame.draw.rect(wall, (196, 154, 84), pd, 2)
            pygame.draw.rect(wall, (84, 70, 112), pygame.Rect(pd.x - 8, pd.y - 10, pd.w + 16, 12))
            pygame.draw.rect(wall, (196, 154, 84), pygame.Rect(pd.x - 8, pd.y - 10, pd.w + 16, 12), 1)
        for i in range(n_arch + 1):
            x = int(aw * i)
            col_r = pygame.Rect(x - 16, 60, 32, floor_y - 60)
            pygame.draw.rect(wall, (52, 42, 74), col_r)
            for k in range(4):
                pygame.draw.line(wall, (66, 54, 92), (col_r.x + 6 + k * 7, col_r.y), (col_r.x + 6 + k * 7, col_r.bottom), 2)
            pygame.draw.rect(wall, (196, 154, 84), pygame.Rect(col_r.x - 6, col_r.y, col_r.w + 12, 14))
            pygame.draw.rect(wall, (196, 154, 84), pygame.Rect(col_r.x - 6, col_r.bottom - 14, col_r.w + 12, 14))
        # sancaklar (kemer aralarında, skinlerin renkleriyle)
        cols = [sk.get("color", (200, 200, 200)) for sk in SKINS[:8]] or [(200, 80, 80)]
        for i in range(1, n_arch):
            x = aw * i
            c = cols[i % len(cols)]
            pts = [(x - 28, 80), (x + 28, 80), (x + 28, 230), (x, 252), (x - 28, 230)]
            pygame.draw.polygon(wall, scale_col(c, 0.55), pts)
            pygame.draw.polygon(wall, (196, 154, 84), pts, 2)
            pygame.draw.circle(wall, (196, 154, 84), (int(x), 150), 13, 2)
            pygame.draw.circle(wall, scale_col(c, 0.95), (int(x), 150), 9)
            pygame.draw.line(wall, (196, 154, 84), (x - 36, 78), (x + 36, 78), 4)
        dk = pygame.Surface((VIRTUAL_W, VIRTUAL_H), pygame.SRCALPHA)
        dk.fill((8, 4, 18, 70))
        wall.blit(dk, (0, 0))
        _vignette(wall)
        _HALL_CACHE["skins"] = wall
    surf.blit(wall, (0, 0))
    floor_y = 560
    aw = VIRTUAL_W / 5
    cols = [sk.get("color", (200, 200, 200)) for sk in SKINS] or [(120, 160, 255)]
    # kaidelerde dönen kahraman küreleri (renk sırayla değişir)
    for i in range(5):
        cx = aw * (i + 0.5)
        idx = (i * 3 + int(t / 3.0)) % len(cols)
        c = cols[idx]
        bob = math.sin(t * 1.6 + i) * 5
        cy = floor_y - 104 + bob
        add_glow(surf, cx, cy, 70, c, 0.32)
        circle_aa(surf, cx, cy, 24, scale_col(c, 0.85))
        circle_aa(surf, cx - 7, cy - 8, 7, lighten(c, 0.45))
        for j in range(3):
            a = t * (1.2 + 0.2 * j) + j * 2.1 + i
            circle_aa(surf, cx + math.cos(a) * 36, cy + math.sin(a) * 12, 2.4, lighten(c, 0.3))
        add_glow(surf, cx, floor_y - 66, 50, c, 0.14)
    # gezen iki spot ışığı
    for k, (ox, col) in enumerate(((VIRTUAL_W * 0.28, (255, 226, 160)), (VIRTUAL_W * 0.72, (190, 170, 255)))):
        ang = math.sin(t * 0.45 + k * 2.2) * 22
        spr = _beam_sprite(620, 300, col, ang)
        r = spr.get_rect(midtop=(ox, -20))
        r.centerx = ox - math.sin(math.radians(ang)) * 300
        surf.blit(spr, r, special_flags=pygame.BLEND_RGB_ADD)
    # süzülen altın parıltılar
    for i in range(30):
        x = (i * 113.7 + math.sin(t * 0.4 + i) * 30) % VIRTUAL_W
        y = VIRTUAL_H - ((t * (14 + i % 5 * 4) + i * 53.1) % (VIRTUAL_H + 30))
        k = 0.5 + 0.5 * math.sin(t * 2.7 + i * 1.3)
        if i % 4 == 0:
            _sparkle(surf, x, y, 2.0 + 2.5 * k, (255, 226, 150))
        else:
            blit_disc(surf, x, y, 1.0 + 1.2 * k, (255, 214, 140), int(40 + 120 * k))


def _vignette(wall):
    vg = pygame.Surface((VIRTUAL_W, VIRTUAL_H), pygame.SRCALPHA)
    for k in range(18):
        pygame.draw.rect(vg, (0, 0, 0, 10), vg.get_rect().inflate(-k * 26, -k * 16), width=14,
                         border_radius=60)
    wall.blit(vg, (0, 0))


def _candelabra(surf, cx, cy, t, seed=0.0):
    """Üç kollu pirinç şamdan; mumlar titreşerek yanar."""
    brass, dark = (176, 132, 64), (92, 66, 34)
    pygame.draw.rect(surf, dark, pygame.Rect(cx - 13, cy + 54, 26, 7), border_radius=3)
    pygame.draw.rect(surf, brass, pygame.Rect(cx - 3, cy + 6, 6, 50))
    pygame.draw.arc(surf, brass, pygame.Rect(cx - 22, cy - 6, 44, 30), math.pi, math.tau, 3)
    for k, dx in enumerate((-21, 0, 21)):
        top = cy - (14 if dx == 0 else 2)
        pygame.draw.rect(surf, brass, pygame.Rect(cx + dx - 6, top + 6, 12, 4), border_radius=2)
        pygame.draw.rect(surf, (236, 228, 206), pygame.Rect(cx + dx - 3, top - 12, 6, 18), border_radius=2)
        fl = 0.75 + 0.25 * math.sin(t * 10 + k * 2.1 + seed) * math.sin(t * 6.7 + k)
        add_glow(surf, cx + dx, top - 18, 34 * fl, (255, 190, 100), 0.5)
        h = 13 * fl
        sway = math.sin(t * 8 + k + seed) * 1.5
        poly_aa(surf, [(cx + dx - 3.5, top - 13), (cx + dx + 3.5, top - 13), (cx + dx + sway, top - 13 - h)],
                (255, 170, 60))
        poly_aa(surf, [(cx + dx - 2, top - 13), (cx + dx + 2, top - 13), (cx + dx + sway * 0.6, top - 13 - h * 0.55)],
                (255, 240, 180))


def draw_library_bg(surf, t):
    """Kitaplık arka planı: tavana kadar uzanan ahşap kitap rafları, iki yanda yanan şamdanlar"""
    wall = _HALL_CACHE.get("library")
    if wall is None:
        wall = pygame.Surface((VIRTUAL_W, VIRTUAL_H)).convert()
        for y in range(VIRTUAL_H):
            pygame.draw.line(wall, mix_col((40, 26, 30), (16, 11, 16), y / VIRTUAL_H), (0, y), (VIRTUAL_W, y))
        rnd = random.Random(23)
        shelf_h = 112
        cols = [(128, 42, 50), (54, 76, 128), (48, 98, 66), (138, 100, 42), (96, 50, 118),
                (156, 124, 84), (66, 64, 78), (148, 74, 42), (40, 96, 104)]
        for row_y in range(-20, VIRTUAL_H, shelf_h):
            base = row_y + shelf_h - 10
            x = 0
            while x < VIRTUAL_W:
                if rnd.random() < 0.05:
                    x += rnd.randint(10, 26)
                    continue
                bw = rnd.randint(10, 22)
                bh = rnd.randint(int(shelf_h * 0.52), int(shelf_h * 0.84))
                col = scale_col(rnd.choice(cols), 0.62 + 0.30 * rnd.random())
                if rnd.random() < 0.06 and x > 30:
                    # yaslanmış kitap
                    pts = [(x, base), (x + bw, base), (x + bw + bh * 0.32, base - bh * 0.95),
                           (x + bh * 0.32, base - bh * 0.95)]
                    pygame.draw.polygon(wall, col, pts)
                    pygame.draw.polygon(wall, scale_col(col, 0.55), pts, 1)
                    x += bw + int(bh * 0.34) + 2
                    continue
                r = pygame.Rect(x, base - bh, bw, bh)
                pygame.draw.rect(wall, col, r)
                pygame.draw.rect(wall, scale_col(col, 0.55), r, 1)
                pygame.draw.line(wall, lighten(col, 0.18), (r.x + 2, r.y + 2), (r.x + 2, r.bottom - 3), 1)
                if rnd.random() < 0.75:
                    gold = mix_col(col, (236, 204, 120), 0.55)
                    for fy in (0.14, 0.86):
                        yy = r.y + int(bh * fy)
                        pygame.draw.line(wall, gold, (r.x + 3, yy), (r.right - 3, yy), 1)
                    if bw >= 15 and rnd.random() < 0.5:
                        pygame.draw.rect(wall, scale_col(col, 0.7),
                                         pygame.Rect(r.x + 4, r.y + int(bh * 0.36), bw - 8, int(bh * 0.20)))
                x += bw + 1
            plank = pygame.Rect(0, base, VIRTUAL_W, 13)
            pygame.draw.rect(wall, (74, 46, 30), plank)
            pygame.draw.line(wall, (110, 72, 46), plank.topleft, plank.topright, 2)
            pygame.draw.line(wall, (28, 18, 12), plank.bottomleft, plank.bottomright, 3)
        for x in range(0, VIRTUAL_W + 1, 213):
            pygame.draw.rect(wall, (60, 38, 26), (x - 8, 0, 16, VIRTUAL_H))
            pygame.draw.line(wall, (94, 62, 42), (x - 7, 0), (x - 7, VIRTUAL_H), 2)
            pygame.draw.line(wall, (30, 20, 14), (x + 7, 0), (x + 7, VIRTUAL_H), 2)
        dk = pygame.Surface((VIRTUAL_W, VIRTUAL_H), pygame.SRCALPHA)
        dk.fill((10, 6, 16, 118))
        wall.blit(dk, (0, 0))
        _vignette(wall)
        _HALL_CACHE["library"] = wall
    surf.blit(wall, (0, 0))
    # sıcak mum ışığı + şamdanlar
    for (cx, cy) in ((38, 286), (VIRTUAL_W - 38, 286)):
        fl = 0.8 + 0.2 * math.sin(t * 9 + cx) * math.sin(t * 5.3)
        add_glow(surf, cx, cy - 10, 250 * fl, (255, 160, 80), 0.26)
        _candelabra(surf, cx, cy, t, seed=cx * 0.01)
    # süzülen sayfalar
    for i in range(8):
        ph = (t * (0.018 + 0.006 * (i % 3)) + i * 0.137) % 1.0
        x = (i * 167.3 + 60 + math.sin(t * 0.5 + i * 1.3) * 46) % VIRTUAL_W
        y = -40 + ph * (VIRTUAL_H + 80)
        ang = math.sin(t * 0.9 + i * 2.0) * 0.7
        ca, sa = math.cos(ang), math.sin(ang)
        hw, hh = 9.0, 12.0

        def rot(px, py):
            return (x + px * ca - py * sa, y + px * sa + py * ca)
        pts = [rot(-hw, -hh), rot(hw, -hh), rot(hw, hh), rot(-hw, hh)]
        poly_aa(surf, pts, (226, 214, 186))
        for k in range(4):
            yy = -hh + 5 + k * 5
            pygame.draw.line(surf, (150, 136, 112), rot(-hw + 3, yy), rot(hw - 3 - (k % 2) * 4, yy), 1)
    # mor büyü tozu
    for i in range(40):
        spd = 16 + (i * 7) % 22
        x = (i * 89.7 + math.sin(t * 0.7 + i) * 20) % VIRTUAL_W
        y = VIRTUAL_H + 20 - ((t * spd + i * 41.3) % (VIRTUAL_H + 40))
        k = 0.5 + 0.5 * math.sin(t * 2.4 + i * 1.7)
        c = (196, 150, 255) if i % 3 else (255, 214, 140)
        blit_disc(surf, x, y, 1.0 + 1.4 * k, c, int(50 + 130 * k))


