def _mob_bg_cache(fn):
    """telefon: market / salon arka planları saniyede ~8 kez çizilir, arada hazır (opak) görüntü basılır."""
    cache = {}

    def wrapped(surf, t):
        if not MOBILE:
            return fn(surf, t)
        img = cache.get("img")
        if img is None or img.get_size() != surf.get_size() or abs(t - cache.get("t", -9)) >= 0.12:
            if img is None or img.get_size() != surf.get_size():
                img = pygame.Surface(surf.get_size()).convert()
            fn(img, t)
            cache.update(img=img, t=t)
        surf.blit(img, (0, 0))
    return wrapped


