def coop_dmg_rows(log, n=8):
    """Hasar dökümü -> [[kaynak, hasar], ...] büyükten küçüğe (ağ için küçük)."""
    try:
        rows = sorted(((str(k), int(v)) for k, v in dict(log).items() if v >= 1), key=lambda kv: -kv[1])
    except (TypeError, ValueError):
        return []
    return [[k, v] for k, v in rows[:n]]


def draw_coop_dmg(canvas, rect, rows, n=6):
    """2 kişilik bitiş ekranı: bir oyuncunun hasar dökümü (ilk n kaynak)."""
    clean = []
    for it in (rows if isinstance(rows, list) else []):
        try:
            clean.append((str(it[0])[:24], max(0, int(it[1]))))
        except (TypeError, ValueError, IndexError):
            continue
    draw_text(canvas, L("ui.dmg_title"), (rect.x, rect.y), 13, GOLD, bold=True, shadow=False)
    if not clean:
        draw_text(canvas, L("ui.dmg_none"), (rect.x, rect.y + 30), 12, TEXT_DIM, shadow=False)
        return
    total = max(1, sum(v for _k, v in clean))
    top = max(1, clean[0][1])
    yy = rect.y + 24
    step = max(30, min(40, (rect.h - 24) // max(1, min(n, len(clean)))))
    for key, v in clean[:n]:
        name, ic, c = dmg_src_label(key)
        c = tuple(int(x) for x in c[:3])
        if key in WEAPON_BY_KEY:
            blit_sigil(canvas, rect.x + 9, yy + 9, 8, key, c)
        else:
            draw_icon(canvas, rect.x + 9, yy + 9, ic, c, 7)
        draw_text(canvas, _fit_text(name, 12, rect.w - 110, bold=True), (rect.x + 24, yy), 12, c, bold=True,
                  shadow=False)
        pct = v / total * 100
        draw_text(canvas, fmt_num(v), (rect.right - 44, yy), 11, TEXT_DIM, right=True, shadow=False)
        draw_text(canvas, ("%%%d" % round(pct)) if lang() == "tr" else "%d%%" % round(pct),
                  (rect.right, yy), 11, TEXT, bold=True, right=True, shadow=False)
        draw_bar(canvas, pygame.Rect(rect.x + 24, yy + 16, rect.w - 24, 6), clamp(v / top, 0, 1), c, radius=3)
        yy += step


def coop_available():
    """2 kişilik bu cihazda açık mı?"""
    return not IS_WEB and not MOBILE


class CoopWS:
    """Küçük websocket istemcisi (RFC 6455): yalnızca standart kütüphane."""

    GUID = b"258EAFA5-E914-47DA-95CA-C5AB0DC85B11"
    CHUNK = 16384

    def __init__(self, url, timeout=12.0):
        u = urllib.parse.urlsplit(url)
        if u.scheme not in ("ws", "wss"):
            raise ValueError("ws/wss bekleniyor")
        self.secure = u.scheme == "wss"
        host = u.hostname or ""
        port = u.port or (443 if self.secure else 80)
        path = (u.path or "/") + ("?" + u.query if u.query else "")
        sock = _socket.create_connection((host, port), timeout=timeout)
        try:
            sock.setsockopt(_socket.IPPROTO_TCP, _socket.TCP_NODELAY, 1)
        except Exception:
            pass
        if self.secure:
            sock = make_ssl_context().wrap_socket(sock, server_hostname=host)
        self.sock = sock
        key = base64.b64encode(os.urandom(16)).decode("ascii")
        hostpart = host if (port in (80, 443)) else "%s:%d" % (host, port)
        req = ("GET %s HTTP/1.1\r\nHost: %s\r\nUpgrade: websocket\r\nConnection: Upgrade\r\n"
               "Sec-WebSocket-Key: %s\r\nSec-WebSocket-Version: 13\r\n"
               "User-Agent: EvolveArena/%s\r\n\r\n") % (path, hostpart, key, GAME_VERSION)
        sock.sendall(req.encode("ascii"))
        head = b""
        while b"\r\n\r\n" not in head:
            chunk = sock.recv(4096)
            if not chunk:
                raise ConnectionError("el sıkışma kesildi")
            head += chunk
            if len(head) > 16384:
                raise ConnectionError("el sıkışma çok uzun")
        hdr, rest = head.split(b"\r\n\r\n", 1)
        lines = hdr.decode("latin-1").split("\r\n")
        if not lines or " 101 " not in (lines[0] + " "):
            raise ConnectionError("sunucu bağlantıyı reddetti")
        want = base64.b64encode(hashlib.sha1(key.encode("ascii") + self.GUID).digest()).decode("ascii")
        got = ""
        for ln in lines[1:]:
            if ":" in ln:
                k, v = ln.split(":", 1)
                if k.strip().lower() == "sec-websocket-accept":
                    got = v.strip()
        if not hmac.compare_digest(got, want):
            raise ConnectionError("el sıkışma doğrulanamadı")
        self.buf = bytearray(rest)
        self.q = _queue.Queue()
        self.outq = collections.deque()   # çerçevelenmiş, sıradaki gönderimler
        self.out_n = 0                    # kuyrukta + yarım kalan bayt
        self._nlock = threading.Lock()
        self._cur = None                  # SSL yeniden denemesi için aynı parça
        self.alive = True
        self.reason = ""
        self.last_rx = time.time()
        self._frag_op, self._frag = None, bytearray()
        try:
            self._wr, self._ww = _socket.socketpair()
            self._wr.setblocking(False)
            self._ww.setblocking(False)
        except Exception:
            self._wr = self._ww = None
        sock.setblocking(False)
        self.th = threading.Thread(target=self._io, daemon=True)
        self.th.start()

    # ---- G/Ç döngüsü ----
    def _io(self):
        import select as _select
        sock = self.sock
        try:
            if self.buf:
                self._parse()
            while self.alive:
                rl = [sock] + ([self._wr] if self._wr is not None else [])
                wl = [sock] if (self._cur is not None or self.outq) else []
                pend = self.secure and sock.pending() > 0
                r, w, _ = _select.select(rl, wl, [], 0 if pend else 0.05)
                if self._wr is not None and self._wr in r:
                    try:
                        while self._wr.recv(4096):
                            pass
                    except (BlockingIOError, InterruptedError, OSError):
                        pass
                if sock in r or pend:
                    self._read_some()
                    self._parse()
                if sock in w:
                    self._write_some()
                if time.time() - self.last_rx > 75.0:
                    raise ConnectionError("zaman aşımı")
        except Exception as e:
            self.reason = self.reason or str(e)[:80]
        self.alive = False
        self.q.put(("closed", self.reason))
        for s_ in (self.sock, self._wr, self._ww):
            try:
                if s_ is not None:
                    s_.close()
            except Exception:
                pass

    def _read_some(self):
        for _ in range(64):
            try:
                chunk = self.sock.recv(65536)
            except (BlockingIOError, InterruptedError):
                return
            except _ssl.SSLWantReadError:
                return
            except _ssl.SSLWantWriteError:
                return
            if not chunk:
                raise ConnectionError("bağlantı kapandı")
            self.buf += chunk
            self.last_rx = time.time()
            if len(self.buf) > 4 * COOP_MAX_IN:
                return                    # önce çözülsün

    def _write_some(self):
        for _ in range(16):
            if self._cur is None:
                if not self.outq:
                    return
                frame = self.outq[0]
                if len(frame) <= self.CHUNK:
                    self.outq.popleft()
                    self._cur = frame
                else:
                    self._cur = frame[:self.CHUNK]
                    self.outq[0] = frame[self.CHUNK:]
            try:
                n = self.sock.send(self._cur)
            except (BlockingIOError, InterruptedError, _ssl.SSLWantWriteError, _ssl.SSLWantReadError):
                return                    # aynı parça sonra yeniden denenir
            if n <= 0:
                return
            with self._nlock:
                self.out_n -= n
            self._cur = self._cur[n:] if n < len(self._cur) else None

    def _parse(self):
        buf = self.buf
        while True:
            if len(buf) < 2:
                return
            b0, b1 = buf[0], buf[1]
            fin = b0 & 0x80
            op = b0 & 0x0F
            masked = b1 & 0x80
            n = b1 & 0x7F
            i = 2
            if n == 126:
                if len(buf) < 4:
                    return
                n = int.from_bytes(buf[2:4], "big")
                i = 4
            elif n == 127:
                if len(buf) < 10:
                    return
                n = int.from_bytes(buf[2:10], "big")
                i = 10
            if n > COOP_MAX_IN:
                raise ConnectionError("mesaj çok büyük")
            mask = None
            if masked:
                if len(buf) < i + 4:
                    return
                mask = bytes(buf[i:i + 4])
                i += 4
            if len(buf) < i + n:
                return
            data = bytes(buf[i:i + n])
            del buf[:i + n]
            if mask:
                data = _ws_mask(data, mask)
            if op == 0x8:
                self.reason = "kapandı"
                raise ConnectionError("kapandı")
            if op == 0x9:
                self._queue_frame(0xA, data)
                continue
            if op == 0xA:
                continue
            if op in (0x1, 0x2):
                if fin:
                    self.q.put(("t" if op == 1 else "b", data, time.time()))
                else:
                    self._frag_op, self._frag = op, bytearray(data)
            elif op == 0x0 and self._frag_op is not None:
                self._frag += data
                if len(self._frag) > COOP_MAX_IN:
                    raise ConnectionError("mesaj çok büyük")
                if fin:
                    self.q.put(("t" if self._frag_op == 1 else "b", bytes(self._frag), time.time()))
                    self._frag_op, self._frag = None, bytearray()

    # ---- yazma (yalnız kuyruğa koyar) ----
    def _queue_frame(self, op, data):
        n = len(data)
        head = bytearray([0x80 | op])
        if n < 126:
            head.append(0x80 | n)
        elif n < 65536:
            head.append(0x80 | 126)
            head += n.to_bytes(2, "big")
        else:
            head.append(0x80 | 127)
            head += n.to_bytes(8, "big")
        mask = os.urandom(4)
        head += mask
        frame = bytes(head) + (_ws_mask(data, mask) if n else b"")
        with self._nlock:
            self.out_n += len(frame)
        self.outq.append(frame)
        if self._ww is not None:
            try:
                self._ww.send(b"x")
            except Exception:
                pass

    def pending(self):
        """Henüz hatta çıkmamış bayt (yerel gönderme birikmesi)."""
        return max(0, self.out_n)

    def send(self, data):
        if not self.alive:
            return False
        if self.out_n > 4 * 1024 * 1024:
            # hat tamamen tıkandı: bağlantı ölü sayılır (yeniden bağlanılır)
            self.alive = False
            self.reason = "gönderme tıkandı"
            return False
        if isinstance(data, str):
            self._queue_frame(0x1, data.encode("utf-8"))
        else:
            self._queue_frame(0x2, bytes(data))
        return True

    def close(self):
        if self.alive:
            try:
                self._queue_frame(0x8, b"\x03\xe8")
                t_end = time.time() + 0.3
                while (self.outq or self._cur is not None) and time.time() < t_end and self.th.is_alive():
                    time.sleep(0.01)
            except Exception:
                pass
        self.alive = False
        if self._ww is not None:
            try:
                self._ww.send(b"x")
            except Exception:
                pass


def _ws_mask(data, mask):
    """Büyük websocket gövdesini hızlı maskeler (int xor ile)."""
    n = len(data)
    m = int.from_bytes((mask * (n // 4 + 1))[:n], "big")
    return (int.from_bytes(data, "big") ^ m).to_bytes(n, "big")


# ---- 2 kişilik: doğrudan bağlantı (UDP) ----
# Sunucu yolunda her mesaj iki kez yol alır (oyuncu -> sunucu -> arkadaş);
# Türkiye'den Frankfurt'a gidip gelmek tek başına ~60 ms, iki oyuncu arası
# ~130 ms ediyordu. İki bilgisayar birbirine doğrudan bağlanabilirse gecikme
# yalnızca ikisinin arasındaki yol kadar olur (aynı şehirde 10-30 ms).
# Bağlantı NAT "delik açma" ile kurulur: iki taraf da kendi dış adresini
# (STUN) ve yerel adreslerini sunucu üstünden karşıya yollar, sonra aynı anda
# birbirine paket atar. Kurulamazsa (simetrik NAT, kapalı UDP) oyun sunucu
# yolundan sürer; doğrudan yol düşerse kendiliğinden sunucuya döner.
# Paketler odaya özel rastgele bir anahtarla imzalanır (HMAC). Mesajlar
# sıralı ve kayıpsız gider: parçalara bölünür, karşı taraf aldıklarını
# bildirir, gelmeyen parça hemen yeniden yollanır.
COOP_STUN = (("stun.l.google.com", 19302), ("stun1.l.google.com", 19302),
             ("stun.cloudflare.com", 3478), ("stun.nextcloud.com", 3478))
COOP_P2P_FRAG = 1100           # bir paketteki en büyük veri (MTU altında kalsın)
COOP_P2P_PUNCH_FOR = 10.0      # delik açma denemesi (sn)
COOP_P2P_DEAD = 1.6            # bu kadar sessizlikte doğrudan yol düştü sayılır
COOP_P2P_MAGIC = b"EA\x01"
_P2P_PUNCH, _P2P_PUNCH_ACK, _P2P_DATA, _P2P_ACK, _P2P_PING, _P2P_PONG, _P2P_BYE = range(1, 8)


def _p2p_private(ip):
    try:
        a, b = (int(x) for x in ip.split(".")[:2])
    except Exception:
        return False
    return a == 10 or a == 127 or (a == 192 and b == 168) or (a == 172 and 16 <= b <= 31) or (a == 169 and b == 254)


def _p2p_local_ips():
    out = []
    try:
        s = _socket.socket(_socket.AF_INET, _socket.SOCK_DGRAM)
        try:
            s.connect(("8.8.8.8", 53))           # paket gitmez; yalnız yol seçilir
            out.append(s.getsockname()[0])
        finally:
            s.close()
    except Exception:
        pass
    try:
        for info in _socket.getaddrinfo(_socket.gethostname(), None, _socket.AF_INET):
            ip = info[4][0]
            if ip not in out:
                out.append(ip)
    except Exception:
        pass
    if "127.0.0.1" not in out:
        out.append("127.0.0.1")                  # aynı bilgisayarda iki oyun
    return [ip for ip in out if ip and not ip.startswith("0.")][:6]


def _p2p_local_ips6():
    """Genel IPv6 adresi: NAT yok, çoğu zaman doğrudan yol buradan açılır."""
    out = []
    try:
        s = _socket.socket(_socket.AF_INET6, _socket.SOCK_DGRAM)
        try:
            s.connect(("2001:4860:4860::8888", 53))
            ip = s.getsockname()[0]
            if ip and not ip.lower().startswith("fe80") and ip != "::1":
                out.append(ip)
        finally:
            s.close()
    except Exception:
        pass
    return out


def _p2p_addr_ok(ip):
    try:
        _socket.inet_pton(_socket.AF_INET6 if ":" in ip else _socket.AF_INET, ip)
        return True
    except (OSError, ValueError, TypeError):
        return False


def _stun_request(tid):
    return b"\x00\x01\x00\x00\x21\x12\xa4\x42" + tid


def _stun_parse(data, tid):
    """STUN yanıtından dış adres (ip, port) - tutmazsa None."""
    if len(data) < 20 or data[0:2] != b"\x01\x01" or data[4:8] != b"\x21\x12\xa4\x42" or data[8:20] != tid:
        return None
    n = int.from_bytes(data[2:4], "big")
    i, end = 20, min(len(data), 20 + n)
    mapped = None
    while i + 4 <= end:
        at = int.from_bytes(data[i:i + 2], "big")
        ln = int.from_bytes(data[i + 2:i + 4], "big")
        v = data[i + 4:i + 4 + ln]
        if len(v) >= 8 and v[1] == 1:                     # IPv4
            port = int.from_bytes(v[2:4], "big")
            ip4 = bytes(v[4:8])
            if at == 0x0020:                              # XOR-MAPPED-ADDRESS
                port ^= 0x2112
                ip4 = bytes(x ^ y for x, y in zip(ip4, b"\x21\x12\xa4\x42"))
                return (".".join(str(x) for x in ip4), port)
            if at == 0x0001 and mapped is None:           # MAPPED-ADDRESS
                mapped = (".".join(str(x) for x in ip4), port)
        i += 4 + ((ln + 3) & ~3)
    return mapped


class CoopP2P:
    """Doğrudan UDP yolu: delik açma + sıralı, kayıpsız mesaj kanalı."""

    def __init__(self, stun=COOP_STUN):
        s = _socket.socket(_socket.AF_INET, _socket.SOCK_DGRAM)
        try:
            s.setsockopt(_socket.SOL_SOCKET, _socket.SO_RCVBUF, 1 << 20)
            s.setsockopt(_socket.SOL_SOCKET, _socket.SO_SNDBUF, 1 << 20)
        except Exception:
            pass
        s.bind(("0.0.0.0", 0))
        s.setblocking(False)
        self.sock = s
        self.port = s.getsockname()[1]
        self.sock6 = None
        self.port6 = 0
        ip6 = _p2p_local_ips6()
        if ip6:
            try:
                s6 = _socket.socket(_socket.AF_INET6, _socket.SOCK_DGRAM)
                try:
                    s6.setsockopt(_socket.IPPROTO_IPV6, _socket.IPV6_V6ONLY, 1)
                except Exception:
                    pass
                s6.bind(("::", 0))
                s6.setblocking(False)
                self.sock6 = s6
                self.port6 = s6.getsockname()[1]
            except Exception:
                self.sock6 = None
        self.key = b""
        self.sid = b"\x00" * 4
        self.alive = True
        self.q = _queue.Queue()                  # ("b", veri, varış)
        self.lock = threading.Lock()
        self.cands = [(ip, self.port) for ip in _p2p_local_ips()]
        if self.sock6 is not None:
            self.cands = [(ip, self.port6) for ip in ip6] + self.cands
        self.public = None
        self.peer_cands = []
        self.peer_addr = None
        self.peer_rtt = 9.0
        self.est_t = 0.0
        self.established = False
        self.ever = False                         # bir kez kuruldu mu
        self.punch_until = 0.0
        self.punch_t = 0.0
        self.last_rx = 0.0
        self.ping_t = 0.0
        self.rtt = 0.0
        # gönderen
        self.snd_next = 0
        self.unacked = collections.OrderedDict()   # seq -> [paket, ilk, son, deneme]
        self.unacked_bytes = 0
        self.hi_ack = -1
        self.srtt = 0.0
        self.rttvar = 0.0
        self.rto = 0.12
        # alan
        self.rcv_next = 0
        self.rcv_buf = {}
        self.rcv_msg = bytearray()
        self.ack_due = False
        self.sent_pk = 0
        self.resent_pk = 0
        self._stun = list(stun)
        self._stun_tid = os.urandom(12)
        self._stun_addrs = []
        self._stun_t = 0.0
        self._stun_n = 0
        self.th = threading.Thread(target=self._io, daemon=True)
        self.th.start()
        if self._stun:
            threading.Thread(target=self._resolve_stun, daemon=True).start()

    # ---- dış adres ----
    def _resolve_stun(self):
        addrs = []
        for host, port in self._stun:
            try:
                for info in _socket.getaddrinfo(host, port, _socket.AF_INET, _socket.SOCK_DGRAM):
                    addrs.append(info[4][:2])
                    break
            except Exception:
                pass
        self._stun_addrs = addrs

    def set_key(self, key, sid):
        self.key = bytes(key)
        self.sid = bytes(sid)[:4].ljust(4, b"\x00")

    def start_punch(self, peer_cands):
        """Karşının adayları geldi: delik açma başlar (yeni adaylar eklenir)."""
        with self.lock:
            for c in peer_cands:
                if c not in self.peer_cands:
                    self.peer_cands.append(c)
            if not self.established:
                self.punch_until = time.time() + COOP_P2P_PUNCH_FOR

    def ok(self):
        return self.alive and self.established and time.time() - self.last_rx < COOP_P2P_DEAD

    def pending(self):
        return self.unacked_bytes

    # ---- paket ----
    def _tag(self, body):
        return hmac.new(self.key, body, hashlib.sha256).digest()[:8]

    def _pack(self, typ, payload):
        body = COOP_P2P_MAGIC + bytes((typ,)) + self.sid + payload
        return body + self._tag(body)

    def _sendto(self, pkt, addr):
        try:
            if ":" in addr[0]:
                if self.sock6 is None:
                    return False
                self.sock6.sendto(pkt, addr[:2])
            else:
                self.sock.sendto(pkt, addr)
            return True
        except (BlockingIOError, InterruptedError):
            return False
        except OSError:
            return False

    # ---- dışarıya: mesaj ----
    def send(self, data):
        """Bir mesajı (bayt) parçalayıp sıraya koyar ve hemen yollar."""
        if not self.ok():
            return False
        if self.unacked_bytes > 3 * 1024 * 1024:
            return False
        n = len(data)
        parts = max(1, (n + COOP_P2P_FRAG - 1) // COOP_P2P_FRAG)
        now = time.time()
        with self.lock:
            addr = self.peer_addr
            for i in range(parts):
                chunk = data[i * COOP_P2P_FRAG:(i + 1) * COOP_P2P_FRAG]
                flags = (1 if i == 0 else 0) | (2 if i == parts - 1 else 0)
                seq = self.snd_next
                self.snd_next += 1
                pkt = self._pack(_P2P_DATA, seq.to_bytes(4, "big") + bytes((flags,)) + chunk)
                self.unacked[seq] = [pkt, now, now, 1]
                self.unacked_bytes += len(pkt)
                self._sendto(pkt, addr)
                self.sent_pk += 1
        return True

    def close(self):
        if self.alive and self.established and self.peer_addr:
            for _ in range(2):
                self._sendto(self._pack(_P2P_BYE, b""), self.peer_addr)
        self.alive = False
        for s_ in (self.sock, self.sock6):
            try:
                if s_ is not None:
                    s_.close()
            except Exception:
                pass

    # ---- G/Ç döngüsü ----
    def _io(self):
        import select as _select
        socks = [x for x in (self.sock, self.sock6) if x is not None]
        while self.alive:
            try:
                r, _, _ = _select.select(socks, [], [], 0.004)
            except Exception:
                break
            now = time.time()
            for sk in r:
                for _ in range(256):
                    try:
                        data, addr = sk.recvfrom(4096)
                    except (BlockingIOError, InterruptedError):
                        break
                    except OSError:
                        break
                    try:
                        self._on_packet(data, addr[:2], now)
                    except Exception:
                        pass
            try:
                self._timers(now)
            except Exception:
                pass

    def _timers(self, now):
        # dış adres: birkaç kez sor
        if self._stun_addrs and self.public is None and self._stun_n < 6 and now - self._stun_t > 0.4:
            self._stun_t = now
            self._stun_n += 1
            for a in self._stun_addrs:
                self._sendto(_stun_request(self._stun_tid), a)
        if self.ack_due and self.peer_addr is not None:
            self.ack_due = False
            self._send_ack()
        if not self.key:
            return
        with self.lock:
            if not self.established and now < self.punch_until and now - self.punch_t > 0.05:
                self.punch_t = now
                pay = int(now * 1e6).to_bytes(8, "big")
                for c in self.peer_cands:
                    self._sendto(self._pack(_P2P_PUNCH, pay), c)
            if not self.established or self.peer_addr is None:
                return
            if now - self.ping_t > 0.25:
                self.ping_t = now
                self._sendto(self._pack(_P2P_PING, int(now * 1e6).to_bytes(8, "big")), self.peer_addr)
            # yeniden gönderim
            if self.unacked:
                base = max(0.03, self.rto)
                fast = (self.srtt * 1.125 + 0.004) if self.srtt else 0.05
                for seq, ent in self.unacked.items():
                    age = now - ent[2]
                    # sonra yollanan en az 3 parça ulaştıysa ya da biri ulaşıp
                    # bir gidiş-dönüş geçtiyse bu parça kaybolmuştur
                    lost = seq < self.hi_ack - 2 or (seq < self.hi_ack and age > fast)
                    if lost or age > base * (1.6 ** min(ent[3] - 1, 5)):
                        ent[2] = now
                        ent[3] += 1
                        self._sendto(ent[0], self.peer_addr)
                        self.resent_pk += 1
                        if ent[3] > 30:
                            self.established = False     # yol öldü
                            break

    def _send_ack(self):
        cum = self.rcv_next
        bits = 0
        for k in self.rcv_buf:
            d = k - cum - 1
            if 0 <= d < 256:
                bits |= 1 << d
        self._sendto(self._pack(_P2P_ACK, cum.to_bytes(4, "big") + bits.to_bytes(32, "big")), self.peer_addr)

    def _on_packet(self, data, addr, now):
        if data[:2] == b"\x01\x01":
            pub = _stun_parse(data, self._stun_tid)
            if pub and self.public is None:
                self.public = pub
                if pub not in self.cands:
                    self.cands.insert(0, pub)
            return
        if len(data) < 16 or data[:3] != COOP_P2P_MAGIC or not self.key:
            return
        body, tag = data[:-8], data[-8:]
        if body[4:8] != self.sid or not hmac.compare_digest(tag, self._tag(body)):
            return
        typ = body[3]
        pay = body[8:]
        if typ == _P2P_PUNCH:
            self._sendto(self._pack(_P2P_PUNCH_ACK, pay[:8]), addr)
            if not self.established:
                with self.lock:
                    if self.peer_addr is None:
                        self.peer_addr = addr
            self.last_rx = now
            return
        if typ == _P2P_PUNCH_ACK:
            rtt = max(0.0, now - int.from_bytes(pay[:8], "big") / 1e6)
            with self.lock:
                # ilk yanıt yolu açar; ilk saniyede daha hızlı bir aday gelirse ona geçilir
                if not self.established or (rtt < self.peer_rtt * 0.7 and now - self.est_t < 1.0):
                    if not self.established:
                        self.est_t = now
                    self.peer_addr = addr
                    self.peer_rtt = rtt
                    self.established = True
                    self.ever = True
                    self.rtt = rtt
            self.last_rx = now
            return
        if addr != self.peer_addr:
            if not self.established:
                return
            # karşının NAT eşlemesi değişti (ör. ağ değişimi): yeni adrese geç
            self.peer_addr = addr
        self.last_rx = now
        if typ == _P2P_DATA and len(pay) >= 5:
            seq = int.from_bytes(pay[:4], "big")
            if seq >= self.rcv_next and seq - self.rcv_next < 8192 and seq not in self.rcv_buf:
                self.rcv_buf[seq] = (pay[4], pay[5:])
                while self.rcv_next in self.rcv_buf:
                    fl, chunk = self.rcv_buf.pop(self.rcv_next)
                    self.rcv_next += 1
                    if fl & 1:
                        self.rcv_msg = bytearray()
                    self.rcv_msg += chunk
                    if len(self.rcv_msg) > COOP_MAX_RAW:
                        self.rcv_msg = bytearray()
                        continue
                    if fl & 2:
                        self.q.put(("b", bytes(self.rcv_msg), now))
                        self.rcv_msg = bytearray()
            self.ack_due = True
        elif typ == _P2P_ACK and len(pay) >= 36:
            cum = int.from_bytes(pay[:4], "big")
            bits = int.from_bytes(pay[4:36], "big")
            with self.lock:
                for seq in list(self.unacked):
                    d = seq - cum - 1
                    if seq >= cum + 257:
                        break
                    if seq < cum or (0 <= d < 256 and (bits >> d) & 1):
                        ent = self.unacked.pop(seq)
                        self.unacked_bytes -= len(ent[0])
                        if ent[3] == 1:
                            smp = now - ent[1]
                            if self.srtt == 0.0:
                                self.srtt, self.rttvar = smp, smp / 2
                            else:
                                self.rttvar = 0.75 * self.rttvar + 0.25 * abs(self.srtt - smp)
                                self.srtt = 0.875 * self.srtt + 0.125 * smp
                            self.rto = min(0.6, max(0.02, self.srtt + 4 * self.rttvar))
                        if seq > self.hi_ack:
                            self.hi_ack = seq
        elif typ == _P2P_PING:
            self._sendto(self._pack(_P2P_PONG, pay[:8]), addr)
        elif typ == _P2P_PONG:
            smp = now - int.from_bytes(pay[:8], "big") / 1e6
            if 0 <= smp < 5:
                self.rtt = smp if self.rtt <= 0 else self.rtt * 0.8 + smp * 0.2
        elif typ == _P2P_BYE:
            self.established = False


class CoopLink:
    """Oda kurma / katılma + websocket bağlantısı + mesaj kodlama."""

    def __init__(self, app):
        self.app = app
        self.role = None             # "host" | "guest"
        self.state = "idle"          # idle | busy | lobby | error | closed
        self.error = ""
        self.code = ""
        self.key = ""
        self.host_name = ""
        self.guest_name = ""
        self.peer_on = False
        self.ws = None
        self.inbox = []              # (tür, veri) - ana döngü boşaltır
        self._lock = threading.Lock()
        self._comp = None
        self._dec = None
        self.lost_t = None           # bağlantının koptuğu an (yeniden deneme için)
        self.bytes_in = 0
        self.bytes_out = 0
        self.closed_by_user = False
        self.stream_bad = False      # sıkıştırma akışı koptu: tam görüntü gerek
        self._part = None            # parçalı mesajın açılmış kısmı
        self.down_since = None       # odaya en son ne zamandan beri ulaşamıyoruz
        self.room_gone = False       # sunucu: oda yok / kapandı
        self.rtt_srv = 0.0           # sunucuya gidiş-dönüş (sn)
        self._ping_t = 0.0
        self._ping_sent = 0.0
        # doğrudan yol (UDP)
        self.p2p = None
        self.p2p_key = b""
        self.p2p_sid = b""
        self.path = "relay"          # relay | direct
        self.path_changed = False
        self._p2p_offer_t = 0.0
        self._p2p_offers = 0
        self._tx_stream_path = None
        self._rx_src = None          # sıkıştırma akışı hangi yoldan geliyor
        self.my_ip = None            # sunucunun gördüğü dış ip (STUN yoksa yedek aday)

    # ---- http ----
    def _auth_payload(self, **extra):
        acc = self.app.account
        p = {"token": acc.token, "device": device_id(), "device_legacy": device_id_legacy(),
             "ver": GAME_VERSION}
        p.update(extra)
        return p

    def _http(self, path, payload, timeout=25):
        data = json.dumps(payload).encode("utf-8")
        req = urllib.request.Request(ONLINE_API_URL + path, data=data,
                                     headers={"Content-Type": "application/json",
                                              "Accept": "application/json"}, method="POST")
        try:
            with urllib.request.urlopen(req, timeout=timeout) as r:
                return json.loads(r.read(64 * 1024).decode("utf-8") or "{}")
        except urllib.error.HTTPError as e:
            try:
                body = json.loads(e.read(16 * 1024).decode("utf-8") or "{}")
            except Exception:
                body = {}
            return {"success": False, "error": str(body.get("error") or "sunucu hatası %d" % e.code)}

    def _ws_url(self):
        base = ONLINE_API_URL
        if base.startswith("https://"):
            base = "wss://" + base[len("https://"):]
        elif base.startswith("http://"):
            base = "ws://" + base[len("http://"):]
        return base + "/coop/ws?" + urllib.parse.urlencode({"code": self.code, "key": self.key})

    def _bg(self, fn, *a):
        self.state = "busy"
        self.error = ""

        def run():
            try:
                fn(*a)
            except Exception as e:
                self.state = "error"
                self.error = "%s (%s)" % (L("coop.err_net"), net_error_kind(e))
        threading.Thread(target=run, daemon=True).start()

    def create(self):
        self.role = "host"
        self._bg(self._do_create)

    def join(self, code):
        self.role = "guest"
        self._bg(self._do_join, code)

    def _wake(self):
        # Render'ın uyuyan sunucusu ilk istekte ~1 dk uyanır: önce durum ucu.
        try:
            req = urllib.request.Request(ONLINE_API_URL + "/auth/status", headers={"Accept": "application/json"})
            with urllib.request.urlopen(req, timeout=60) as r:
                r.read(2048)
        except Exception:
            pass

    def _do_create(self):
        self._wake()
        res = self._http("/coop/create", self._auth_payload())
        if not res.get("success"):
            self.state, self.error = "error", str(res.get("error") or L("coop.err_net"))
            return
        self.code = str(res.get("code") or "")[:6]
        self.key = str(res.get("key") or "")[:64]
        self.host_name = str(res.get("name") or "")[:14]
        self._connect()

    def _do_join(self, code):
        self._wake()
        res = self._http("/coop/join", self._auth_payload(code=code))
        if not res.get("success"):
            self.state, self.error = "error", str(res.get("error") or L("coop.err_net"))
            return
        self.code = str(res.get("code") or "")[:6]
        self.key = str(res.get("key") or "")[:64]
        self.host_name = str(res.get("host") or "")[:14]
        self.guest_name = str(res.get("name") or "")[:14]
        self._connect()

    def _connect(self):
        ws = CoopWS(self._ws_url())
        with self._lock:
            old, self.ws = self.ws, ws
        if old is not None:
            old.close()
        self._comp = None
        self._dec = None
        self._part = None
        self._rx_src = None
        self.lost_t = None
        self.state = "lobby"
        self._p2p_start()

    # ---- doğrudan yol ----
    def _p2p_start(self):
        if self.p2p is not None and self.p2p.alive:
            return
        if os.environ.get("EVOLVE_NO_P2P"):
            return
        try:
            self.p2p = CoopP2P()
        except Exception:
            self.p2p = None
            return
        if self.role == "host":
            if not self.p2p_key:
                self.p2p_key = os.urandom(16)
                self.p2p_sid = os.urandom(4)
            self.p2p.set_key(self.p2p_key, self.p2p_sid)
        elif self.p2p_key:
            self.p2p.set_key(self.p2p_key, self.p2p_sid)

    def _p2p_cands(self):
        pp = self.p2p
        if pp is None:
            return []
        out = [list(c) for c in pp.cands]
        if self.my_ip and not pp.public and [self.my_ip, pp.port] not in out:
            out.append([self.my_ip, pp.port])     # çoğu ev modemi kaynak portu korur
        return out[:10]

    def _p2p_msg(self, msg):
        """Karşıdan aday / anahtar geldi."""
        pp = self.p2p
        if pp is None:
            return
        cands = []
        for c in (msg.get("c") or [])[:10]:
            if (isinstance(c, list) and len(c) == 2 and isinstance(c[0], str) and len(c[0]) <= 45
                    and isinstance(c[1], int) and 0 < c[1] < 65536 and _p2p_addr_ok(c[0])):
                cands.append((c[0], c[1]))
        if self.role == "guest":
            try:
                key = bytes.fromhex(str(msg.get("k") or ""))[:32]
                sid = bytes.fromhex(str(msg.get("s") or ""))[:4]
            except ValueError:
                return
            if len(key) < 16 or len(sid) != 4:
                return
            if self.p2p_sid and sid != self.p2p_sid and pp.ever:
                # ev sahibi yolu baştan kurdu: eski oturum kapanır
                pp.close()
                self.p2p = None
                self._p2p_start()
                pp = self.p2p
                if pp is None:
                    return
            if key != self.p2p_key or sid != self.p2p_sid or pp.key != key:
                self.p2p_key, self.p2p_sid = key, sid
                pp.set_key(key, sid)
            self._send_ws({"t": "p2p", "c": self._p2p_cands()})
        if cands:
            pp.start_punch(cands)

    def p2p_tick(self, dt):
        """Aday değişimi + yol seçimi (her karede)."""
        pp = self.p2p
        if pp is None:
            if self.ws is not None and self.ws.alive and self.state == "lobby":
                self._p2p_start()
            return
        now = time.time()
        if not pp.alive or (self.role == "host" and pp.ever and not pp.ok() and now - pp.last_rx > 3.0):
            # doğrudan yol öldü: yeni soket + yeni oturum kimliği, karşı taraf
            # da yeni teklifle sıfırlanır (eski paketler kimlik tutmadığından
            # yok sayılır)
            pp.close()
            self.p2p = None
            if self.role == "host":
                self.p2p_sid = os.urandom(4)
                self._p2p_offers = 0
                self._p2p_offer_t = 0.0
                self._p2p_start()
            return
        if (self.role == "host" and self.peer_on and not pp.ok() and self.ws is not None and self.ws.alive
                and now - self._p2p_offer_t > (1.0 if self._p2p_offers < 12 else 4.0)):
            self._p2p_offer_t = now
            self._p2p_offers += 1
            self._send_ws({"t": "p2p", "k": self.p2p_key.hex(), "s": self.p2p_sid.hex(),
                           "c": self._p2p_cands()})
        path = "direct" if pp.ok() else "relay"
        if path != self.path:
            self.path = path
            self.path_changed = True

    def _send_ws(self, obj):
        ws = self.ws
        if ws is None or not ws.alive:
            return False
        data = b"J" + json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        self.bytes_out += len(data)
        return ws.send(data)

    def direct(self):
        return self.p2p is not None and self.p2p.ok()

    def peer_ok(self):
        """Arkadaş ulaşılabilir mi (sunucu ya da doğrudan yol)."""
        return self.peer_on or self.direct()

    def reconnect(self):
        """Kopan bağlantıyı aynı biletle yeniden kurmayı dener (arka planda)."""
        if self.state == "busy" or not self.key:
            return

        def run():
            try:
                self._connect()
            except Exception:
                self.state = "lobby"     # yeniden denenecek
        self.state = "busy"
        threading.Thread(target=run, daemon=True).start()

    def leave(self):
        """Odadan çık (ev sahibiyse oda kapanır)."""
        self.closed_by_user = True
        code, key = self.code, self.key
        ws = self.ws
        if ws is not None:
            try:
                self.send({"t": "bye"})
            except Exception:
                pass
            self.ws = None
            ws.close()
        if self.p2p is not None:
            self.p2p.close()
            self.p2p = None
        self.state = "closed"
        if code and key:
            def run():
                try:
                    self._http("/coop/leave", {"code": code, "key": key}, timeout=10)
                except Exception:
                    pass
            threading.Thread(target=run, daemon=True).start()

    # ---- mesajlar ----
    def connected(self):
        return (self.ws is not None and self.ws.alive) or self.direct()

    def send(self, obj, stream=False):
        """Mesaj: oyun akışı (görüntü, girdi) doğrudan yol açıksa oradan; komutlar sunucudan."""
        ws = self.ws
        ws_ok = ws is not None and ws.alive
        direct = self.direct()
        t = obj.get("t") if isinstance(obj, dict) else None
        if stream or t == "i":
            via = "direct" if direct else "ws"
        elif t in ("end", "bye"):
            via = "both"
        else:
            via = "ws" if ws_ok else "direct"
        if via == "ws" and not ws_ok or via == "direct" and not direct:
            return False
        raw = json.dumps(obj, separators=(",", ":"), ensure_ascii=False).encode("utf-8")
        if stream:
            if self._tx_stream_path != via:
                self._tx_stream_path = via
                self._comp = None           # yol değişti: akış yeni yolda baştan
            new = self._comp is None
            if new:
                self._comp = _zlib.compressobj(6)
            body = self._comp.compress(raw) + self._comp.flush(_zlib.Z_SYNC_FLUSH)
            parts = [body[i:i + COOP_PART] for i in range(0, len(body), COOP_PART)] or [b""]
            ok = True
            for j, part in enumerate(parts):
                last = j == len(parts) - 1
                if j == 0 and new:
                    head = b"K" if last else b"k"
                else:
                    head = b"Z" if last else b"z"
                self.bytes_out += len(part) + 1
                if via == "direct":
                    ok = self.p2p.send(head + part) and ok
                else:
                    ok = ws.send(head + part) and ok
            if not ok:
                self._comp = None        # yarım kalan akış: sonraki mesaj baştan
            return ok
        data = b"J" + raw
        self.bytes_out += len(data)
        ok = False
        if via in ("direct", "both") and direct:
            ok = self.p2p.send(data) or ok
        if via in ("ws", "both") and ws_ok:
            ok = ws.send(data) or ok
        return ok

    def pending(self):
        """Yolda bekleyen bayt (görüntülerin gittiği yolda)."""
        if self.direct():
            return self.p2p.pending()
        ws = self.ws
        return ws.pending() if ws is not None and ws.alive else 0

    def ping_tick(self, dt):
        """Sunucuya 3 sn'de bir 'ping' (gecikme ölçümü + canlı tutma)."""
        self._ping_t -= dt
        if self._ping_t <= 0 and self.connected():
            self._ping_t = 3.0
            self._ping_sent = time.time()
            try:
                self.ws.send("ping")
            except Exception:
                pass

    def reset_stream(self):
        """Karşı taraf yeniden bağlandı: sıkıştırma akışı baştan başlasın."""
        self._comp = None

    def poll(self):
        """Gelen mesajları çözer (sunucu + doğrudan yol)."""
        out = []
        items = []
        ws = self.ws
        if ws is not None:
            for _ in range(400):
                try:
                    items.append(("ws",) + tuple(ws.q.get_nowait()))
                except _queue.Empty:
                    break
        pp = self.p2p
        if pp is not None:
            for _ in range(400):
                try:
                    items.append(("p2p",) + tuple(pp.q.get_nowait()))
                except _queue.Empty:
                    break
            items.sort(key=lambda it: it[3] if len(it) > 3 else 0.0)
        for it in items:
            src, kind, data = it[0], it[1], it[2]
            rx = it[3] if len(it) > 3 else time.time()
            if kind == "closed":
                if self.ws is ws:
                    self.lost_t = time.time()
                out.append(("closed", data))
                continue
            self.bytes_in += len(data)
            if kind == "t":
                try:
                    msg = json.loads(data.decode("utf-8")[:8192])
                except Exception:
                    continue
                if isinstance(msg, dict) and msg.get("t") == "srv":
                    ev = msg.get("ev")
                    if ev == "pong" and self._ping_sent:
                        self.rtt_srv = max(0.0, min(9.0, rx - self._ping_sent))
                        self._ping_sent = 0.0
                        continue
                    if ev == "hello":
                        self.down_since = None
                        self.room_gone = False
                        you = msg.get("you")
                        if isinstance(you, str) and 7 <= len(you) <= 15 and you.count(".") == 3:
                            self.my_ip = you
                    elif ev == "closed":
                        self.room_gone = True
                    out.append(("srv", msg))
                continue
            msg = self._decode(data, src)
            if isinstance(msg, dict):
                if msg.get("t") == "p2p":
                    try:
                        self._p2p_msg(msg)
                    except Exception:
                        pass
                    continue
                msg["_rx"] = rx
                out.append(("msg", msg))
        return out

    def _decode(self, data, src="ws"):
        if not data:
            return None
        head, body = data[:1], data[1:]
        if head in (b"Z", b"z") and self._rx_src is not None and src != self._rx_src:
            return None                  # eski yoldan geç kalmış akış parçası
        try:
            if head == b"J":
                raw = body
            elif head in (b"K", b"Z", b"k", b"z"):
                if head in (b"K", b"k"):
                    self._dec = _zlib.decompressobj()
                    self._part = None
                    self.stream_bad = False
                    self._rx_src = src
                elif self._dec is None or self.stream_bad:
                    # akışın ortası: başı kaybolmuşsa çözülemez, tam görüntü
                    # beklenir
                    self.stream_bad = True
                    return None
                room = COOP_MAX_RAW - (len(self._part) if self._part else 0)
                raw = self._dec.decompress(body, max(1, room))
                if self._dec.unconsumed_tail:
                    raise ValueError("çok büyük")      # zip bombası / bozuk akış
                if head in (b"k", b"z"):
                    self._part = (self._part or b"") + raw
                    return None
                if self._part is not None:
                    raw, self._part = self._part + raw, None
            else:
                return None
            if len(raw) > COOP_MAX_RAW:
                return None
            return json.loads(raw.decode("utf-8"))
        except Exception:
            if head != b"J":
                self._dec = None
                self._part = None
                self.stream_bad = True
            return None

