# ---- 2 kişilik - ev sahibinde çok oyunculu koşu ----
# RunState'in "oyuncuya ait" alanları (oyuncu, altın, seviye kuyruğu, kartlar,
# kamera, mermiler, silah nesneleri, kombo, skor...) her oyuncu için ayrı bir
# bağlamda tutulur.
COOP_PERSONAL = (
    "player", "gold_wallet", "pending_levelups", "levelup_choices", "reroll_used",
    "skip_used", "reroll_bonus", "destiny_seed", "destiny_locked", "offer_seen",
    "legend_hands", "shop_offers", "want_open_shop", "cam_x", "cam_y",
    "player_projectiles", "water_zones", "fire_rings", "sword_slashes", "tornados",
    "black_holes", "flying_axes", "whip_lashes", "ghost_blades", "wolves", "meteors",
    "beams", "hawks", "bats", "novas", "knives", "quakes", "bat_heal_budget", "minion_t",
    "wolf_howl_cd", "penta_inside", "combo", "dmg_log", "coins_earned", "gem_coins",
    "kills", "score", "score_frac", "merchant_open", "show_map", "show_stats",
    "bonk_hits", "new_books", "new_weapons", "death_cause", "_pet", "_pet_id",
    # sunak güçleri, raf/örs elleri, evrimler: herkesin kendisi
    "shrine_buffs", "find_hands", "evo_perks", "evo_banner", "evo_aegis_t", "evo_shroud_t",
    "evo_blast_t", "evo_blasts", "evo_count", "evo_phx_t", "evo_scorch_t", "reward_card",
    # seviye ellerinin havuzu: herkes kendi açtığı silah ve kitaplarla oynar
    "save",
)
# çizimde iki oyuncunun nesneleri birlikte görünsün diye birleştirilen listeler
COOP_MERGE_LISTS = (
    "player_projectiles", "water_zones", "fire_rings", "sword_slashes", "tornados",
    "black_holes", "flying_axes", "whip_lashes", "ghost_blades", "wolves", "meteors",
    "beams", "hawks", "bats", "novas", "knives", "quakes",
)
_COOP_CTX = [None]      # ev sahibinde o an işlenen oyuncu (hasarın kime yazılacağı)


def _coop_wrap_take_damage(cls):
    """Hasarı veren oyuncu yaratığın üstüne yazılır (öldürme kime sayılsın)."""
    orig = cls.take_damage
    if getattr(orig, "_coop", False):
        return

    def take_damage(self, amount, *a, **k):
        c = _COOP_CTX[0]
        if c is not None:
            self._lh = c
        return orig(self, amount, *a, **k)
    take_damage._coop = True
    cls.take_damage = take_damage


_coop_wrap_take_damage(Enemy)
_coop_wrap_take_damage(Boss)


class CoopRunState(RunState):
    """2 kişilik koşu (ev sahibinin bilgisayarında işler)."""

    is_coop = True
    is_guest = False

    def __init__(self, save, skins, diff, names=("", ""), cosmetics=(None, None), pools=None):
        sv = _AdSave(save.data)
        RunState.__init__(self, sv, skins[0], diff, _AdAch())
        self.players = [self.player]
        self.names = [str(n or "")[:14] for n in names]
        self.cur = 0
        self.ctx = [None, None]
        base = {k: self.__dict__.get(k) for k in COOP_PERSONAL}
        p1 = Player(skins[1] if len(skins) > 1 else "default")
        if cosmetics and len(cosmetics) > 1 and isinstance(cosmetics[1], dict):
            p1.cosmetics = coop_clean_cosmetics(cosmetics[1])
            try:
                p1.apply_cosmetic_perks()
            except Exception:
                pass
        p0 = self.player
        p1.x, p1.y = p0.x + 70, p0.y + 10
        p1.evolved = set()
        p1.evo_tier = {}
        p1.evo_soul = (0, 0.0)
        self.players.append(p1)
        c1 = {}
        for k, v in base.items():
            if isinstance(v, list):
                c1[k] = []
            elif isinstance(v, dict):
                c1[k] = {}
            elif isinstance(v, set):
                c1[k] = set()
            else:
                c1[k] = v
        c1["player"] = p1
        c1["combo"] = ComboMeter()
        c1["destiny_seed"] = random.randrange(1 << 30)
        c1["cam_x"] = clamp(p1.x - VIEW_RECT.w / 2, ARENA_RECT.left, ARENA_RECT.right - VIEW_RECT.w)
        c1["cam_y"] = clamp(p1.y - VIEW_RECT.h / 2, ARENA_RECT.top, ARENA_RECT.bottom - VIEW_RECT.h)
        c1["_pet"] = None
        c1["_pet_id"] = None
        c1["save"] = coop_pool_save(save, pools[1] if pools and len(pools) > 1 else None)
        self.ctx[1] = c1
        for p in self.players:
            p.no_stats = True
            p.max_weapons, p.max_books, p.max_rare = COOP_SLOTS
        # oyuncu 2'nin kaderi de kendi tohumuyla
        self._ctx_use(1)
        try:
            self._roll_destiny()
        finally:
            self._ctx_use(0)
        # ---- 2 kişilik zorluk ----
        self.waves.cap_mult = COOP_CAP_MULT
        self.waves.cap_max = COOP_CAP_MAX
        self.waves.dmg_mult = COOP_ENEMY_DMG
        self._apply_wave_mods()
        # durumlar
        self.inputs = [{}, {}]
        self.menu_open = [False, False]
        self.menu_budget = [COOP_MENU_SHIELD, COOP_MENU_SHIELD]
        self._menu_was = [False, False]
        self.dead = [False, False]
        self.curse_owner = 0
        self.focus = 0
        # patron ruhu: [x, y, hedef (ölen oyuncu, yoksa -1), dolum] - en çok 1 tane
        self.soul = None
        self.revives = 0
        self.tp = [0, 0]                   # ışınlanma sayacı (konuk konumunu bırakır)
        self.cmd_ack = 0
        self.connected = [True, True]
        self.quests = []

    # ---- bağlam ----
    def _ctx_use(self, i):
        """i. oyuncunun kişisel alanlarını RunState'e takar."""
        if i == self.cur or self.ctx[i] is None:
            return
        d = self.__dict__
        mine = {k: d.get(k) for k in COOP_PERSONAL}
        other = self.ctx[i]
        for k in COOP_PERSONAL:
            d[k] = other.get(k)
        self.ctx[self.cur] = mine
        self.ctx[i] = None
        self.cur = i

    def ctx_get(self, i, name, default=None):
        """i. oyuncunun kişisel alanı (bağlamı takmadan)."""
        if i == self.cur:
            return self.__dict__.get(name, default)
        c = self.ctx[i]
        return c.get(name, default) if c is not None else default

    def ctx_set(self, i, name, value):
        if i == self.cur:
            self.__dict__[name] = value
        elif self.ctx[i] is not None:
            self.ctx[i][name] = value

    def other_index(self, i):
        return 1 - i

    # ---- çizim görünümü ----
    def view_begin(self, i):
        """Çizim için: i. oyuncunun gözünden bak; iki oyuncunun silah nesneleri birlikte çizilsin (listeler geçici olarak birleşir)."""
        self._ctx_use(i)
        j = 1 - i
        saved = {}
        oc = self.ctx[j] or {}
        for k in COOP_MERGE_LISTS:
            mine = self.__dict__.get(k) or []
            theirs = oc.get(k) or []
            if theirs:
                saved[k] = mine
                self.__dict__[k] = list(mine) + list(theirs)
        self._view_saved = saved
        op = self.players[j] if j < len(self.players) else None
        self.coop_others = [op] if op is not None else []

    def view_end(self):
        for k, v in getattr(self, "_view_saved", {}).items():
            self.__dict__[k] = v
        self._view_saved = {}

    def alive_players(self):
        return [i for i, p in enumerate(self.players) if p.alive]

    def nearest_player(self, x, y, prefer=None):
        best, bd = None, 1e18
        for i, p in enumerate(self.players):
            if not p.alive:
                continue
            d = (p.x - x) ** 2 + (p.y - y) ** 2
            if prefer is not None and i == prefer:
                d *= 0.64                  # hedef değiştirmekte isteksiz (titreme olmasın)
            if d < bd:
                best, bd = i, d
        return best

    # ---- 2 kişilik ayarları ----
    def wave_hp_mult(self, w):
        return RunState.wave_hp_mult(self, w) * COOP_ENEMY_HP

    def _apply_wave_mods(self):
        RunState._apply_wave_mods(self)
        self.waves.spawn_rate_mult *= COOP_SPAWN_RATE

    def finish_run(self):
        """2 kişilik: ödül, istatistik, sıralama yok (beta)."""
        self.game_over = True

    def run_is_clean(self):
        return False

    def on_enemy_killed(self, e):
        i = e.__dict__.get("_lh") if hasattr(e, "__dict__") else None
        if i is None or i == self.cur or i not in (0, 1):
            return RunState.on_enemy_killed(self, e)
        prev = self.cur
        self._ctx_use(i)
        try:
            return RunState.on_enemy_killed(self, e)
        finally:
            self._ctx_use(prev)

    # ortak mağara: ödül ve bedel iki oyuncuya da işler
    def _apply_curse_reward(self, vals, mult=1):
        prev = self.cur
        for i in self.alive_players() or [prev]:
            self._ctx_use(i)
            RunState._apply_curse_reward(self, vals, mult)
        self._ctx_use(prev)

    def accept_curse(self, idx):
        offers = self.curse_offers or []
        if not (0 <= idx < len(offers)):
            return
        blood = offers[idx].get("kind") == "blood"
        RunState.accept_curse(self, idx)
        # mağaranın tuzağı ikisinin de yanında patlayabilir: ikisi de korunur
        self.menu_grace([self.players[i] for i in self.alive_players()])
        if blood:
            # kan bedeli ikisinden de alınır (bir kez açanınki RunState'te
            # alındı)
            for i in self.alive_players():
                if i == self.cur:
                    continue
                q = self.players[i]
                loss = int(q.max_hp * BLOOD_PRICE)
                q.max_hp = max(30, int(q.max_hp) - loss)
                q.hp = min(q.hp, q.max_hp)
                self.fx.popup(q.x, q.y - 70, f"-{loss} " + L("cu.maxhp"), CURSE_RED, 20, life=1.6)

    # ---- aynı silah iki oyuncuda olmaz ----
    def partner_weapons(self):
        """Şu an işlenen oyuncunun arkadaşlarının silahları."""
        out = set()
        for j, q in enumerate(self.players):
            if j != self.cur and q is not None:
                out.update(q.weapons)
        return out

    def levelup_pool(self):
        # seviye eli, sandık / efsanevi el, raf: hepsi bu havuzdan çeker
        offers, weights = RunState.levelup_pool(self)
        taken = self.partner_weapons()
        if not taken:
            return offers, weights
        keep = [(o, w) for o, w in zip(offers, weights)
                if not (o["kind"] == "weapon" and o["key"] not in self.player.weapons and o["key"] in taken)]
        return [o for o, _w in keep], [w for _o, w in keep]

    def _hand_has_taken(self):
        taken = self.partner_weapons()
        return any(c.get("kind") == "weapon" and c.get("key") in taken and c.get("key") not in self.player.weapons
                   for c in (self.levelup_choices or ()))

    def choose_levelup(self, idx):
        # arkadaş aynı silahı bir an önce aldıysa: el yenilenir, seviye yanmaz
        if self._hand_has_taken():
            ch = self.levelup_choices[idx] if 0 <= idx < len(self.levelup_choices) else None
            if ch is not None and ch.get("kind") == "weapon" and ch.get("key") in self.partner_weapons():
                p = self.player
                self.fx.popup(p.x, p.y - 80, L("coop.w_taken", w_name(ch["w"])), ORANGE, 16, life=1.8)
                self.start_levelup_choice()
                return
        return RunState.choose_levelup(self, idx)

    # mıknatıs: kim alırsa alsın haritadaki altın ve tecrübe ikiye eşit bölünür
    # (çekilen her parça toplayana yarım, arkadaşa yarım yazılır)
    def collect_magnet(self, mg):
        RunState.collect_magnet(self, mg)
        p = self.player
        self.fx.popup(p.x, p.y - 104, L("coop.mag_split"), MAGNET_COLOR2, 15, life=1.8)

    def _update_pickups(self, dt):
        halves = []
        for pu in self.pickups:
            if pu.magnet and pu.kind in ("coin", "xp") and not (pu.collected or pu.dead):
                v = pu.value
                mine = v / 2.0 if pu.kind == "xp" else (int(v) + 1) // 2
                halves.append((pu, v, v - mine))
                pu.value = mine
        RunState._update_pickups(self, dt)
        give = []
        for pu, v, rest in halves:
            if pu.collected:
                if rest > 0:
                    give.append((pu.kind, rest))
            else:
                pu.value = v
        if give and len(self.players) > 1:
            prev = self.cur
            self._ctx_use(1 - prev)
            try:
                q = self.player
                for kind, v in give:
                    if kind == "xp":
                        lv = q.gain_xp(v)
                        if lv > 0:
                            self.pending_levelups += lv
                    else:
                        self.coins_earned += v
                        self.gem_coins += v / (coin_drop_scale(self.biome)
                                               * econ_wave_factor(self.waves.wave, self.biome, "gold", self.diff))
                        self.gold_wallet += v
            finally:
                self._ctx_use(prev)

    def evolve_weapon(self, key):
        RunState.evolve_weapon(self, key)
        # şerit yalnızca evrilene çıkar; ikisi de görsün diye başının üstünde
        # adıyla bir duyuru
        p = self.player
        nm = self.names[self.cur] if self.cur < len(self.names) else ""
        tr_ = evo_tier(p, key)
        self.fx.popup(p.x, p.y - 96, L("coop.evo", nm or "?", evo_name(key, tr_)), evo_color(key, tr_), 22,
                      life=2.4)

    # ortak yemin: seçilen yemin iki oyuncuya da işler
    def apply_oath(self, key, tier=0):
        prev = self.cur
        for i in self.alive_players() or [prev]:
            self._ctx_use(i)
            RunState.apply_oath(self, key, tier)
        self._ctx_use(prev)

    def enter_hell(self):
        RunState.enter_hell(self)
        # cehennemin dalga yöneticisi yeni: 2 kişilik zorluk yeniden yazılır
        self.waves.cap_mult = COOP_CAP_MULT
        self.waves.cap_max = COOP_CAP_MAX
        self.waves.dmg_mult = COOP_ENEMY_DMG
        self._apply_wave_mods()
        p = self.player
        for i, q in enumerate(self.players):
            if q is not p:
                q.x, q.y = p.x + 70, p.y + 10
                q.invuln = max(q.invuln, 2.0)
                self.tp[i] += 1
                if q.alive:
                    q.hp = q.max_hp
        prev = self.cur
        for i in range(len(self.players)):
            self._ctx_use(i)
            self.player_projectiles = []
            self.update_camera(0.0, snap=True)
        self._ctx_use(prev)

    # ---- ana döngü ----
    def update(self, dt, inputs):
        """inputs: [ev sahibinin girdisi, konuğun girdisi]"""
        if self.game_over:
            self.fx.update(dt)
            return
        prev_ctx = self.cur
        DMG_LOG[0] = self.dmg_log
        DMG_SRC[0] = "other"
        EVO_CTX[0] = self
        ENEMY_HAZARDS[0] = self
        self.run_time += dt
        if self.time_stop > 0:
            self.time_stop = max(0.0, self.time_stop - dt)
        alive = self.alive_players()
        # ---- 1) her oyuncu kendi bağlamında: hareket, nişan, ateş, dash, bonk ----
        for i, p in enumerate(self.players):
            self._ctx_use(i)
            _COOP_CTX[0] = i
            inp = inputs[i] if i < len(inputs) else {}
            if not p.alive:
                self._spectate_camera(dt)
                continue
            # pencere açıkken: oyuncu durur, kısa süre korunur (bütçeli).
            # Üst üste seviye eli açılırsa (mağaradan +6 seviye) her kart için
            # ek koruma: 6 kart 3-4 sn'ye sığmıyordu.
            mw = self.__dict__.setdefault("_menu_was", [False, False])
            if self.menu_open[i] and not mw[i]:
                extra = COOP_MENU_PER_CARD * max(0, int(self.pending_levelups) - 1)
                self.menu_budget[i] = max(self.menu_budget[i],
                                          min(COOP_MENU_SHIELD_MAX, COOP_MENU_SHIELD + extra))
            mw[i] = bool(self.menu_open[i])
            if self.menu_open[i]:
                inp = {"aim_x": inp.get("aim_x", p.x), "aim_y": inp.get("aim_y", p.y - 1)}
                if self.menu_budget[i] > 0:
                    self.menu_budget[i] = max(0.0, self.menu_budget[i] - dt)
                    p.invuln = max(p.invuln, 0.06)
            else:
                self.menu_budget[i] = min(COOP_MENU_SHIELD, self.menu_budget[i] + dt * 0.25)
            if self.oath == "bulwark":
                ot = self.__dict__.setdefault("_oath_t2", [0.0, 0.0])
                ot[i] += dt
                if ot[i] >= self.oath_period:
                    ot[i] = 0.0
                    if p.shield_charges < 3:
                        p.shield_charges += 1
            p.update(dt, inp, self.fx)
            if i == 1 and "pos" in inp:
                self._apply_guest_pos(p, inp["pos"], dt)
            self.update_camera(dt)
            self.update_skin_ult(dt)
            ax_w = inp.get("aim_x", p.x)
            ay_w = inp.get("aim_y", p.y - 1)
            aim_dx, aim_dy = norm_dir(p.x, p.y, ax_w, ay_w)
            p.set_aim(aim_dx, aim_dy)
            if inp.get("mouse_down") and p.try_attack():
                self.do_player_attack(*p.aim_dir)
            if inp.get("bonk_pressed") and p.try_bonk():
                self.do_bonk()
            if inp.get("dash_pressed"):
                if p.try_dash(self.fx) and p.dash_slow_level > 0:
                    rad = 200 + 30 * p.dash_slow_level
                    dur = 2.0 + 0.8 * p.dash_slow_level
                    mult = max(0.30, 0.70 - 0.15 * p.dash_slow_level)
                    for e in self.enemies:
                        if e.alive and dist(e.x, e.y, p.x, p.y) < rad and hasattr(e, "apply_slow"):
                            e.apply_slow(mult, dur)
                    for b in self.bosses:
                        if b.alive and dist(b.x, b.y, p.x, p.y) < rad and hasattr(b, "apply_slow"):
                            b.apply_slow(mult, dur)
                    self.fx.shockwave(p.x, p.y, rad, (150, 210, 255), 0.30, 3)
            if p.orbit_level > 0:
                DMG_SRC[0] = "orbit"
                p.orbit_angle += dt * 3.2
                n = p.orbit_level
                for k in range(n):
                    ang = p.orbit_angle + k * math.tau / n
                    ox = p.x + math.cos(ang) * 58
                    oy = p.y + math.sin(ang) * 58
                    for e in self._all_targets():
                        if e.alive and dist(ox, oy, e.x, e.y) < e.radius + 10:
                            if e.take_damage(p.eff_dmg() * 0.45 * dt * 6, False, self.fx):
                                self.on_enemy_killed(e)
                DMG_SRC[0] = "other"
            if p.storm_level > 0:
                p.storm_timer -= dt
                if p.storm_timer <= 0:
                    p.storm_timer = max(1.0, 2.6 - p.storm_level * 0.4)
                    self.do_storm_strike()
            self._wave_milestones()
        frozen = self.time_stop > 0
        # odak: doğum noktaları, kaçak yaratıklar sırayla iki oyuncunun
        # çevresinde
        if alive:
            self.focus = alive[int(self.run_time * 2.0) % len(alive)]
        focus = self.focus
        self._ctx_use(focus)
        _COOP_CTX[0] = None

        # ---- 2) patronlar (ortak) ----
        self._tick_boss_wound([q for q in self.players])
        if self.waves.boss_pending:
            n_before = len([b for b in self.bosses if b.alive])
            self._coop_spawn_boss()
            for b in self.bosses[n_before:]:
                b.__dict__["_lh"] = focus
        if self.bosses:
            DMG_SRC[0] = "other"
            for b in list(self.bosses):
                if b.alive:
                    ti = self.nearest_player(b.x, b.y, b.__dict__.get("_tgt"))
                    if ti is not None:
                        b._tgt = ti
                        if not frozen:
                            b.update(dt, self.players[ti], self.fx, self.enemy_projectiles,
                                     self.hazards, self.on_enemy_killed)
                    if b.summoned_enemies:
                        self.enemies.extend(b.summoned_enemies)
                        b.summoned_enemies = []
            _COOP_CTX[0] = None
            self._coop_boss_deaths()

        # ---- 3) tuzaklar: iki oyuncuya da işler ----
        if not frozen:
            for hz in list(self.hazards):
                was = hz.exploded
                hz.update(dt, self)
                if not was and hz.exploded:
                    for i in self.alive_players():
                        q = self.players[i]
                        if q is self.player:
                            continue
                        if dist(hz.x, hz.y, q.x, q.y) < hz.r + q.radius - 2:
                            if hz.owner is not None and hasattr(hz.owner, "hit_player"):
                                hz.owner.hit_player(q, hz.dmg, self.fx, hz.x, hz.y)
                            else:
                                q.take_damage(hz.dmg, self.fx, hz.x, hz.y, "Tuzak")
        self.hazards = [h for h in self.hazards if h.alive]

        # ---- 4) yaratıklar: en yakın oyuncuyu kovalar ----
        if not frozen:
            DMG_SRC[0] = "other"
            kcb = self.on_enemy_killed
            for e in list(self.enemies):
                ti = self.nearest_player(e.x, e.y, e.__dict__.get("_tgt"))
                if ti is None:
                    continue
                e._tgt = ti
                # (_COOP_CTX boş: zehir/yanık ölümleri son vurana yazılır)
                e.update(dt, self.players[ti], self.fx, self.enemy_projectiles, kcb, self.enemies)
                # öbür oyuncu da yaratığa değiyorsa o da hasar alır
                oi = 1 - ti
                q = self.players[oi]
                if q.alive and e.alive and e.contact_dps > 0:
                    cd = e.__dict__.get("_tcd2", 0.0) - dt
                    if cd <= 0 and dist(e.x, e.y, q.x, q.y) < e.hit_r + q.radius - 2:
                        cd = 0.12
                        q.take_damage(e.contact_dps * 0.72, self.fx, e.x, e.y, e.disp_name)
                    e._tcd2 = cd
            _COOP_CTX[0] = None
        self.enemies = [e for e in self.enemies if e.alive]
        if not frozen and alive:
            self.reposition_stragglers(dt)
            self._update_camping(dt)

        # ---- 5) sandık, anahtar, mıknatıs: yanına giden açar (kendi bağlamında) ----
        first = True
        for i in alive:
            self._ctx_use(i)
            _COOP_CTX[0] = i
            d_ = dt if first else 0.0
            self.update_chests(d_)
            self.update_keys(d_)
            self.update_magnets(d_)
            first = False
        # ---- 6) silahlar: herkes kendi silahları (+ evrim etkileri) ----
        for i in alive:
            self._ctx_use(i)
            _COOP_CTX[0] = i
            if self.evo_perks:
                self.evo_update(dt)
            self.update_boss_weapons(dt)
            self.update_passive_weapons(dt)
            self.update_weapon_objects(dt)
        # ölünün kalan silah nesneleri de sönsün
        for i, p in enumerate(self.players):
            if not p.alive:
                self._ctx_use(i)
                self.update_weapon_objects(dt)
        _COOP_CTX[0] = None
        # ---- 7) düşman mermileri: iki oyuncuya da çarpar ----
        self._coop_enemy_projectiles(dt, frozen)
        # ---- 8) oyuncu mermileri: herkesin kendi mermileri ----
        for i in range(len(self.players)):
            self._ctx_use(i)
            _COOP_CTX[0] = i
            self._update_player_projectiles(dt)
        _COOP_CTX[0] = None
        # ---- 9) yerdeki altın / tecrübe / kalp: en yakın oyuncuya ----
        self._coop_pickups(dt)

        # ---- 10) dalgalar (ortak) ----
        self._ctx_use(focus)
        wave_changed = self.waves.update(0.0 if frozen else dt, self.enemies, self.wave_hp_mult,
                                         self.waves.boss_active, total_score=0)
        if wave_changed:
            sfx("wave", 0.6, 0.0)
        if (wave_changed and not self.waves.boss_pending and not self.waves.boss_active
                and mini_boss_wave(self.waves.wave)):
            self.spawn_mini_boss()
        if wave_changed:
            self._roll_goblin()
            self.extras_wave_changed()
        self._update_goblins()
        # ---- 10b) sunak, harita bulguları, kervan (dünyada ortak; başında
        # duran oyuncu alır) ----
        if alive and not frozen:
            self.extras_update(dt)
            for i in range(len(self.players)):
                self._ctx_use(i)
                if self.shrine_buffs:
                    self.shrine_buffs = [b for b in self.shrine_buffs if b[1] > self.run_time]
            self._ctx_use(focus)

        # ---- 11) kapı, mağara, tüccar: E'ye basan oyuncunun bağlamında ----
        portal_used = False
        if self.hell_portal is not None:
            self.hell_portal.update(dt)
        first = True
        for i in alive:
            self._ctx_use(i)
            inp = inputs[i] if i < len(inputs) else {}
            p = self.player
            if (self.hell_portal is not None and not portal_used and p.alive
                    and inp.get("use_pressed") and self.hell_portal.in_range(p)):
                self.enter_hell()
                portal_used = True
            had = self.curse_offers
            self.update_cursed(dt if first else 0.0, inp, portal_used)
            if self.curse_offers and not had:
                self.curse_owner = i
            self.update_merchant(dt if first else 0.0, inp, portal_used)
            first = False
        # seviye kartları: konuğun eli ev sahibinde hazırlanır
        for i in range(len(self.players)):
            self._ctx_use(i)
            self._skill_tick(dt)
            self.combo.update(dt)
            if self.levelup_choices and self._hand_has_taken():
                self.start_levelup_choice()
                if not self.levelup_choices:
                    self.pending_levelups = 0
            if i != 0 and self.player.alive and self.pending_levelups > 0 and not self.levelup_choices:
                self.start_levelup_choice()
                if not self.levelup_choices:
                    self.pending_levelups = 0
        self._ctx_use(prev_ctx)
        self.fx.update(dt)
        self._soul_tick(dt)
        # ---- 12) ölüm: ölen izler, ikisi de ölünce biter ----
        for i, p in enumerate(self.players):
            if not p.alive and not self.dead[i]:
                self.dead[i] = True
                self.ctx_set(i, "death_cause", p.last_hit_by)
                self.fx.popup(p.x, p.y - 60, L("coop.down", self.names[i] or "?"), RED, 24, life=2.4)
        co_ = self.curse_owner
        if (self.curse_offers and 0 <= co_ < len(self.players)
                and not self.players[co_].alive and self.alive_players()):
            prev_ = self.cur
            self._ctx_use(co_)
            try:
                RunState.decline_curse(self)
            finally:
                self._ctx_use(prev_)
        if not self.alive_players() and not self.game_over:
            self.game_over = True
            self.death_cause = self.players[0].last_hit_by

    # ---- patron ruhu: ölen arkadaşı diriltir ----
    def _soul_spawn(self, x, y):
        """Patron ölünce ruh çıkar. Birikmez: zaten bir ruh varsa yenisi gelmez."""
        if self.soul is not None:
            return
        self.soul = [float(x), float(y), -1, 0.0]
        self.fx.popup(x, y - 90, L("coop.soul"), SOUL_COLOR, 22, life=2.4)
        self.fx.ring(x, y, SOUL_COLOR, n=24, speed=220, life=0.6, r=3)
        sfx("second", 0.7, 0.0)

    def _soul_tick(self, dt):
        sl = self.soul
        if sl is None or self.game_over:
            return
        alive = self.alive_players()
        if not alive:
            return
        dead = [i for i, q in enumerate(self.players) if not q.alive]
        if dead:
            ti = dead[0]
            q = self.players[ti]
            tx, ty = q.x, q.y - 26
            if sl[2] != ti:
                sl[2], sl[3] = ti, 0.0
                self.fx.popup(q.x, q.y - 80, L("coop.soul_go"), SOUL_COLOR, 18, life=2.4)
        else:
            # kimse ölmedi: ruh bekler, yaşayan oyuncunun yanında süzülür
            q = self.players[alive[0]]
            a = self.run_time * 1.6
            tx, ty = q.x + math.cos(a) * 54, q.y - 64 + math.sin(a * 2) * 8
            sl[2], sl[3] = -1, 0.0
        dx, dy = tx - sl[0], ty - sl[1]
        d = math.hypot(dx, dy)
        step = SOUL_SPEED * dt
        if d > step and d > 1.0:
            sl[0] += dx / d * step
            sl[1] += dy / d * step
        else:
            sl[0], sl[1] = tx, ty
        if sl[2] < 0 or d > 30:
            return
        # ruh ölünün üstünde: yaşayan arkadaş üstünde durursa dolar
        near = any(dist(self.players[i].x, self.players[i].y, sl[0], sl[1] + 26) < SOUL_R for i in alive)
        if near:
            sl[3] += dt
            if random.random() < dt * 16:
                a = random.uniform(0, math.tau)
                self.fx.spark(sl[0] + math.cos(a) * SOUL_R, sl[1] + 26 + math.sin(a) * SOUL_R, SOUL_COLOR,
                              -math.cos(a) * 110, -math.sin(a) * 110, 0.45, 2.6)
        else:
            sl[3] = max(0.0, sl[3] - dt * 1.5)
        if sl[3] >= SOUL_NEED:
            self._revive(sl[2])

    def _revive(self, i):
        q = self.players[i]
        q.alive = True
        q.hp = max(1.0, q.max_hp * SOUL_HP)
        q.invuln = max(getattr(q, "invuln", 0.0), MENU_GRACE)
        q.grace_t = MENU_GRACE
        self.dead[i] = False
        self.soul = None
        self.revives += 1
        self.fx.popup(q.x, q.y - 70, L("coop.revived", self.names[i] or "?"), SOUL_COLOR, 26, life=2.2)
        self.fx.shockwave(q.x, q.y, 180, SOUL_COLOR, 0.5, 6)
        self.fx.ring(q.x, q.y, (255, 255, 255), n=30, speed=260, life=0.6, r=3.5)
        self.fx.burst(q.x, q.y - 20, SOUL_COLOR, n=26, speed=200, life=0.8, r=3.2, gravity=-80)
        sfx("levelup", 1.0, 0.0)

    def _spectate_camera(self, dt):
        """Ölen oyuncunun kamerası arkadaşını izler."""
        mate = None
        for q in self.players:
            if q is not self.player and q.alive:
                mate = q
        if mate is None:
            return
        tx = clamp(mate.x - VIEW_RECT.w / 2, ARENA_RECT.left, ARENA_RECT.right - VIEW_RECT.w)
        ty = clamp(mate.y - VIEW_RECT.h / 2, ARENA_RECT.top, ARENA_RECT.bottom - VIEW_RECT.h)
        k = min(1.0, dt * 6)
        self.cam_x += (tx - self.cam_x) * k
        self.cam_y += (ty - self.cam_y) * k

    def _apply_guest_pos(self, p, pos, dt):
        """Konuğun kendi bildirdiği konum (kendi ekranında gecikmesiz yürüsün)."""
        try:
            gx, gy = float(pos[0]), float(pos[1])
        except Exception:
            return
        if not (math.isfinite(gx) and math.isfinite(gy)):
            return
        if pos[2] != self.tp[1]:
            return                        # ışınlanma sonrası eski konum: yok say
        gx = clamp(gx, ARENA_RECT.left + p.radius, ARENA_RECT.right - p.radius)
        gy = clamp(gy, ARENA_RECT.top + p.radius, ARENA_RECT.bottom - p.radius)
        lim = max(p.eff_speed(), 205.0 * p.dash_dist_mult / 0.17) * max(dt, 1 / 60.0) * 2.2 + 50
        dx, dy = gx - p.x, gy - p.y
        dd = math.hypot(dx, dy)
        if dd > lim:
            gx, gy = p.x + dx / dd * lim, p.y + dy / dd * lim
        p.x, p.y = gx, gy

    def _coop_spawn_boss(self):
        """RunState'teki patron doğumu; can iki oyuncunun gücüne göre ölçeklenir."""
        self.waves.boss_pending = False
        self.waves.boss_active = True
        self.waves.boss_clock = 0.0
        wave = self.waves.wave
        champ = boss_count_for_wave(wave)
        hp_mult = boss_hp_share(1)
        self.enemies.clear()
        self.bosses = [b for b in self.bosses if b.alive]
        hell = self.biome == "hell"
        order = HELL_BOSS_ORDER if hell else BOSS_ORDER
        kind = order[self.waves.boss_idx % len(order)]
        self.waves.boss_idx += 1
        cam = self.cam_rect()
        bx = clamp(cam.centerx, ARENA_RECT.left + 90, ARENA_RECT.right - 90)
        by = clamp(cam.top + 110, ARENA_RECT.top + 90, ARENA_RECT.bottom - 90)
        b = Boss(kind, bx, by, hp_mult, 1.0, wave, hellish=hell,
                 theme=None if hell else self.map_theme, champion=champ)
        b.boss_wave = wave
        b.dmg *= COOP_ENEMY_DMG               # 2 kişilik: patron da daha sert vurur
        self.bosses.append(b)
        scale_bosses_to_player([b], self.player)
        # öbür oyuncunun gücü de eklenir
        try:
            d0 = max(1.0, float(self.player.estimated_dps()))
            tot = sum(max(1.0, float(q.estimated_dps())) for q in self.players if q.alive)
            k = tot / d0 * COOP_BOSS_HP
            b.max_hp *= k
            b.hp *= k
        except Exception:
            pass
        self.fx.do_flash((255, 60, 50), 0.4)
        sfx("boss", 1.0, 0.0)

    def _coop_boss_deaths(self):
        for b in list(self.bosses):
            if b.alive:
                continue
            self.on_enemy_killed(b)
            self._beaten_boss_wave = max(getattr(self, "_beaten_boss_wave", 0),
                                         int(getattr(b, "boss_wave", self.waves.wave)))
            nb = max(1, int(getattr(b, "champion", 1)))
            for k in range(nb):
                self.spawn_boss_chest(b, dx=(k - (nb - 1) / 2.0) * 90)
            self._soul_spawn(b.x, b.y)
            self.bosses.remove(b)
        if not self.bosses and self.waves.boss_active:
            beaten = int(getattr(self, "_beaten_boss_wave", 0) or self.waves.wave)
            self._beaten_boss_wave = 0
            self.waves.boss_active = False
            self.waves.announce_timer = 2.5
            self.waves.announce_text = L("ui.boss_down")
            sfx("wave", 0.6, 0.0)
            if self.biome != "hell" and beaten >= HELL_PORTAL_WAVE and self.hell_portal is None:
                self.open_hell_portal()

    def _coop_enemy_projectiles(self, dt, frozen):
        for proj in list(self.enemy_projectiles):
            if not frozen:
                proj.update(dt)
            if not proj.alive or frozen:
                continue
            for i in self.alive_players():
                q = self.players[i]
                self._ctx_use(i)
                if self.block_with_book(proj):
                    break
                if dist(proj.x, proj.y, q.x, q.y) < proj.r + q.radius:
                    owner = getattr(proj, "owner", None)
                    if owner is not None and hasattr(owner, "hit_player"):
                        owner.hit_player(q, proj.dmg, self.fx, proj.x, proj.y)
                    else:
                        q.take_damage(proj.dmg, self.fx, proj.x, proj.y, "mermi")
                        if getattr(proj, "poison", 0.0) > 0:
                            q.apply_poison(proj.poison, WIZARD_POISON_TIME, LX("en.wizard", "Büyücü"))
                    proj.alive = False
                    break
        self.enemy_projectiles = [pr for pr in self.enemy_projectiles if pr.alive]

    def _coop_pickups(self, dt):
        groups = {}
        for pu in self.pickups:
            ti = self.nearest_player(pu.x, pu.y)
            if ti is None:
                continue
            groups.setdefault(ti, []).append(pu)
        keep = self.pickups
        for ti, lst in groups.items():
            self._ctx_use(ti)
            self.pickups = lst
            self._update_pickups(dt)
            done = set(id(pu) for pu in lst if pu.collected or pu.dead)
            keep = [pu for pu in keep if id(pu) not in done]
            self.pickups = keep
        self.pickups = [pu for pu in keep if not (pu.collected or pu.dead)]

    # ---- konuktan gelen komutlar ----
    def guest_command(self, cmd):
        """Konuğun pencere eylemleri."""
        if not isinstance(cmd, dict) or self.game_over:
            return
        c = str(cmd.get("c") or "")
        i = 1
        if not self.players[i].alive:
            return
        prev = self.cur
        self._ctx_use(i)
        try:
            def num(k, lo, hi):
                v = cmd.get(k)
                if not isinstance(v, int) or isinstance(v, bool) or not (lo <= v <= hi):
                    raise ValueError
                return v
            if c == "lv_pick" and self.levelup_choices:
                self.choose_levelup(num("i", 0, len(self.levelup_choices) - 1))
            elif c == "lv_reroll" and self.levelup_choices:
                self.reroll_levelup()
            elif c == "lv_skip" and self.levelup_choices:
                self.skip_levelup()
            elif c == "shop_buy":
                key = str(cmd.get("k") or "")
                if key in SHOP_BY_KEY:
                    self.buy_shop_item(key)
            elif c == "m_open":
                pass
            elif c == "oath" and self.merchant_open and self.oath is None:
                key = str(cmd.get("k") or "")
                tier = num("tier", 0, RARITY_COUNT - 1)
                if (key, tier) in [tuple(x) for x in self.merchant_hand]:
                    self.choose_oath(key, tier)
                    self._ctx_use(1)
                    self.merchant_open = False
            elif c == "m_reroll" and self.merchant_open:
                self.merchant_reroll()
            elif c == "m_close":
                self.merchant_open = False
            elif c == "cu_pick" and self.curse_offers and self.curse_owner == 1:
                self.accept_curse(num("i", 0, len(self.curse_offers) - 1))
            elif c == "cu_decline" and self.curse_offers and self.curse_owner == 1:
                self.decline_curse()
        except (ValueError, TypeError):
            pass
        finally:
            self._ctx_use(prev)


def coop_clean_pools(wp, bk):
    """Konuğun gönderdiği açık silah / kitap listesi: yalnızca bilinen anahtarlar."""
    w = [k for k in (wp if isinstance(wp, list) else [])[:64] if isinstance(k, str) and k in WEAPON_BY_KEY]
    b = [k for k in (bk if isinstance(bk, list) else [])[:96] if isinstance(k, str) and k in BOOK_BY_KEY]
    return (sorted(set(w)), sorted(set(b))) if (w or b) else None


def coop_my_pools(save):
    """Bu oyuncunun seviye ellerinde çıkabilecek silah ve kitapları (açık ve kapatılmamış)."""
    try:
        return ([w["key"] for w in save.unlocked_weapons()], [b["key"] for b in save.unlocked_books()])
    except Exception:
        return ([], [])


def coop_pool_save(save, pools):
    """Konuğun koşu kaydı: ev sahibininkinin kopyası, ama silah/kitap havuzu konuğun kendi listesi."""
    sv = _AdSave(save.data)
    if pools:
        wp, bk = pools
        d = sv.data
        d["weapons_owned"] = list(wp)
        d["books_owned"] = list(bk)
        d["weapons_muted"] = []
        d["books_muted"] = []
        # açılma görevleri ev sahibinin istatistiğine bakmasın
        d["stats"] = {}
        d["achievements"] = {}
    return sv


def coop_clean_cosmetics(d):
    """Konuğun gönderdiği kozmetikler: yalnızca bilinen yuva + kimlik."""
    out = {slot: None for slot in COSMETIC_SLOTS}
    if not isinstance(d, dict):
        return out
    for slot, cid in list(d.items())[:8]:
        if not isinstance(slot, str) or not isinstance(cid, str):
            continue
        if slot in COSMETIC_SLOTS and cid in COSMETIC_BY_ID:
            out[slot] = cid
    return out

# ---- 2 kişilik - anlık görüntü (snapshot) kodlama ----
# Ev sahibi, dünyadaki her nesnenin basit alanlarını (sayı, yazı, bayrak, küçük
# liste/sözlük) gönderir; yalnızca değişen alanlar gider.
COOP_SHARED_LISTS = ("enemies", "bosses", "hazards", "pickups", "enemy_projectiles",
                     "chests", "map_keys", "magnets", "level_drops", "finds")
COOP_SINGLES = ("legend_chest", "hell_portal", "cursed_shrine", "merchant", "shrine", "caravan")
COOP_SYNC_CLASS_NAMES = (
    "Enemy", "Boss", "Hazard", "Pickup", "EnemyProjectile", "PlayerProjectile", "MagnetDrop",
    "LevelDrop", "BossChest", "MapKey", "LegendChest", "HellPortal", "CursedShrine", "Merchant",
    "WaterZone", "FireRing", "SwordSlash", "Tornado", "FlyingAxe", "WhipLash", "GhostBlade",
    "SpectralWolf", "MeteorStrike", "SunBeam", "Hawk", "BatSwarmBat", "FrostNova",
    "ThrownKnife", "QuakeCharge", "Player", "PowerShrine", "Caravan", "MapFind",
)
# RunState'in konuğa gitmeyen alanları (ya ayrı gider ya da konukta anlamsız)
COOP_RUN_SKIP = set(COOP_SHARED_LISTS) | set(COOP_SINGLES) | set(COOP_MERGE_LISTS) | {
    "save", "ach", "fx", "waves", "combo", "players", "ctx", "player", "inputs", "names",
    "penta_inside", "destiny_locked", "dmg_log", "corpses", "quests", "maps_at_start",
    "menu_budget", "cur", "focus", "coop_others",
}
_COOP_FIELD_RE = None
_COOP_SKIP_VAL = object()
# Hiç gönderilmeyen alanlar: yalnızca ev sahibindeki yapay zekânın sayaçları.
COOP_NEVER_FIELDS = frozenset((
    "knock_x", "knock_y", "touch_cd", "dash_cd", "heal_cd", "warp_cd", "burn_tick_acc",
    "poison_tick_acc", "straggle_t", "hit_set", "regen_acc", "dash_dx", "dash_dy",
))
# Saat gibi düzenli akan alanlar: seyrek gönderilir, konuk kendi akıtır.
COOP_SLOW_FIELDS = frozenset((
    "spawn_t", "walk", "wobble", "life", "trail", "debris", "t", "age", "bob", "anim",
    "phase", "spin", "pulse", "move_anim", "ghosts",
))
# Konum ve yön gibi alanlar daha kaba yuvarlanır (bayt az, gözle fark yok).
COOP_ROUND0 = frozenset(("x", "y", "vx", "vy", "tx", "ty"))
COOP_ROUND1 = frozenset(("face_x", "face_y", "shoot_cd"))


def _coop_field_ok(name):
    global _COOP_FIELD_RE
    if _COOP_FIELD_RE is None:
        import re
        _COOP_FIELD_RE = re.compile(r"^[a-z][a-zA-Z0-9_]{0,40}$")
    return bool(_COOP_FIELD_RE.match(name))


_COOP_STATIC = [None, None]      # (id(sözlük) -> etiket, etiket -> sözlük)


def _coop_static_tables():
    """Oyunun sabit kataloglarındaki sözlükler (silah, kitap, skin, patron"""
    if _COOP_STATIC[0] is not None:
        return _COOP_STATIC
    by_id, by_tag = {}, {}
    g = globals()
    for name in sorted(g):
        if not name.isupper() or name.startswith("_") or name in ("CFG", "STRINGS"):
            continue
        v = g[name]
        if isinstance(v, dict) and 0 < len(v) <= 4000:
            for k, d in v.items():
                if isinstance(d, dict) and isinstance(k, str) and id(d) not in by_id:
                    tag = [name, k]
                    by_id[id(d)] = tag
                    by_tag[(name, k)] = d
        elif isinstance(v, (list, tuple)) and 0 < len(v) <= 4000:
            for i, d in enumerate(v):
                if isinstance(d, dict) and id(d) not in by_id:
                    tag = [name, i]
                    by_id[id(d)] = tag
                    by_tag[(name, i)] = d
    _COOP_STATIC[0], _COOP_STATIC[1] = by_id, by_tag
    return _COOP_STATIC


def _coop_q(v):
    if v != v or v in (float("inf"), float("-inf")):
        return 0
    r = round(v, 2)
    if r == int(r) and abs(r) < 1e12:
        return int(r)
    return r


class CoopSyncHost:
    """Ev sahibi tarafı: anlık görüntü üretir (yalnızca değişenler)."""

    FULL_EVERY = 15        # her nesnenin bütün alanları bu kadar görüntüde bir denetlenir

    def __init__(self, run):
        self.run = run
        self.seq = 0
        self.next_nid = 1
        self.id2nid = {}
        self.objs = {}             # nid -> nesne (kimlik tekrar kullanılmasın diye tutulur)
        self.sent = {}             # nid -> {alan: kodlanmış değer}
        self.hot = {}              # sınıf -> sık değişen alanlar
        self.lists = {}            # liste adı -> son gönderilen kimlikler
        self.run_sent = {}
        self.wave_sent = {}
        self.combo_sent = {}
        self.fx_log = []
        self.sfx_log = []
        self.keyframe = True
        _coop_static_tables()

    def reset(self):
        """Konuk (yeniden) bağlandı: her şey baştan, tam görüntüyle gider."""
        self.sent = {}
        self.lists = {}
        self.run_sent = {}
        self.wave_sent = {}
        self.combo_sent = {}
        self.keyframe = True

    def nid(self, obj):
        k = id(obj)
        n = self.id2nid.get(k)
        if n is None:
            n = self.next_nid
            self.next_nid += 1
            self.id2nid[k] = n
            self.objs[n] = obj
        return n

    def enc(self, v, d=0):
        t = type(v)
        if v is None or t is bool or t is int:
            return v
        if t is float:
            return _coop_q(v)
        if t is str:
            return v if len(v) <= 200 else v[:200]
        if d >= 4:
            return _COOP_SKIP_VAL
        if t is set or t is frozenset:
            # (ör. evrilmiş silahlar) konukta liste olur; "in" ile okunur
            if len(v) > 96 or not all(type(x) in (str, int) for x in v):
                return _COOP_SKIP_VAL
            return sorted(v, key=str)
        if t is list or t is tuple:
            if len(v) > 96:
                return _COOP_SKIP_VAL
            out = []
            for x in v:
                e = self.enc(x, d + 1)
                if e is _COOP_SKIP_VAL:
                    return _COOP_SKIP_VAL
                out.append(e)
            return out
        if t is dict:
            tag = _COOP_STATIC[0].get(id(v))
            if tag is not None:
                return {"$s": tag}
            if len(v) > 96:
                return _COOP_SKIP_VAL
            out = {}
            for k, x in v.items():
                if type(k) is str:
                    if k.startswith("$") or k.startswith("#"):
                        continue
                    kk = k
                elif type(k) is int:
                    kk = "#%d" % k
                else:
                    return _COOP_SKIP_VAL
                e = self.enc(x, d + 1)
                if e is not _COOP_SKIP_VAL:
                    out[kk] = e
            return out
        if t is Player:
            try:
                return {"$p": self.run.players.index(v)}
            except ValueError:
                return _COOP_SKIP_VAL
        n = self.id2nid.get(id(v))
        if n is not None:
            return {"$o": n}
        return _COOP_SKIP_VAL

    def _fields(self, obj):
        d = getattr(obj, "__dict__", None)
        if d is not None:
            return d.items()
        names = getattr(type(obj), "__slots__", ())
        return [(n, getattr(obj, n, None)) for n in names]

    def _obj_delta(self, obj, full):
        n = self.nid(obj)
        last = self.sent.get(n)
        cls = type(obj).__name__
        out = {}
        if last is None:
            last = self.sent[n] = {}
            out["$c"] = cls
            full = True
        hot = self.hot.setdefault(cls, set())
        if full or (n + self.seq) % self.FULL_EVERY == 0:
            items = self._fields(obj)
        else:
            dd = getattr(obj, "__dict__", None)
            if dd is not None:
                items = [(k, dd[k]) for k in hot if k in dd]
            else:
                items = [(k, getattr(obj, k, None)) for k in hot]
        new = "$c" in out
        is_full = full or (n + self.seq) % self.FULL_EVERY == 0
        for k, v in items:
            if k[0] == "_" or k in COOP_NEVER_FIELDS:
                continue
            if k in COOP_SLOW_FIELDS and not is_full:
                continue
            if type(v) is float:
                if k in COOP_ROUND0:
                    e = int(round(v)) if math.isfinite(v) else 0
                elif k in COOP_ROUND1:
                    e = round(v, 1) if math.isfinite(v) else 0
                else:
                    e = _coop_q(v)
            else:
                e = self.enc(v)
            if e is _COOP_SKIP_VAL:
                continue
            if last.get(k, _COOP_SKIP_VAL) != e:
                out[k] = e
                last[k] = e
                if not new and k not in COOP_SLOW_FIELDS:
                    hot.add(k)
        return n, out

    def _plain_delta(self, src_items, sent):
        out = {}
        for k, v in src_items:
            if k[0] == "_" or k in COOP_RUN_SKIP:
                continue
            e = self.enc(v)
            if e is _COOP_SKIP_VAL:
                continue
            if sent.get(k, _COOP_SKIP_VAL) != e:
                out[k] = e
                sent[k] = e
        return out

    def build(self, view_rect):
        """Konuğa gidecek anlık görüntü (dict)."""
        run = self.run
        self.seq += 1
        snap = {"t": "s", "n": self.seq, "o": {}, "L": {}}
        if self.keyframe:
            snap["key"] = 1
        full = self.keyframe
        seen = set()
        o = snap["o"]
        # önce oyuncular (bağlar onlara gösterebilsin)
        pn = []
        for p in run.players:
            n, delta = self._obj_delta(p, full)
            seen.add(n)
            pn.append(n)
            if delta:
                o[n] = delta
        if self.lists.get("$P") != pn:
            snap["L"]["$P"] = pn
            self.lists["$P"] = pn

        def visit_list(name, lst):
            nids = []
            for obj in lst:
                if type(obj).__name__ not in COOP_SYNC_CLASS_NAMES:
                    continue
                n, delta = self._obj_delta(obj, full)
                seen.add(n)
                nids.append(n)
                if delta:
                    o[n] = delta
            if self.lists.get(name) != nids:
                snap["L"][name] = nids
                self.lists[name] = nids

        # nesne kimlikleri önce dağıtılsın (bağlar ilk görüntüde de çözülsün)
        for name in COOP_SHARED_LISTS:
            for obj in getattr(run, name, None) or []:
                self.nid(obj)
        for name in COOP_SHARED_LISTS:
            visit_list(name, getattr(run, name, None) or [])
        for i in range(len(run.players)):
            for name in COOP_MERGE_LISTS:
                if name == "black_holes":
                    continue
                visit_list("%d:%s" % (i, name), run.ctx_get(i, name) or [])
        for name in COOP_SINGLES:
            obj = getattr(run, name, None)
            if obj is not None and type(obj).__name__ in COOP_SYNC_CLASS_NAMES:
                n, delta = self._obj_delta(obj, full)
                seen.add(n)
                if delta:
                    o[n] = delta
                val = n
            else:
                val = 0
            key = "$" + name
            if self.lists.get(key) != val:
                snap["L"][key] = val
                self.lists[key] = val
        # kara delikler (sözlük listesi)
        for i in range(len(run.players)):
            bh = self.enc(run.ctx_get(i, "black_holes") or [])
            if bh is not _COOP_SKIP_VAL and self.lists.get("bh%d" % i) != bh:
                snap["L"]["bh%d" % i] = bh
                self.lists["bh%d" % i] = bh
        # silinenler
        gone = [n for n in self.sent if n not in seen]
        if gone:
            snap["d"] = gone
            for n in gone:
                self.sent.pop(n, None)
                obj = self.objs.pop(n, None)
                if obj is not None:
                    self.id2nid.pop(id(obj), None)
        # koşu alanları (konuğun gözünden: kendi altını, kartları, skoru...)
        prev = run.cur
        run._ctx_use(1)
        try:
            r = self._plain_delta(list(run.__dict__.items()), self.run_sent)
            cb = self._plain_delta(list(run.combo.__dict__.items()), self.combo_sent)
        finally:
            run._ctx_use(prev)
        if r:
            snap["R"] = r
        if cb:
            snap["C"] = cb
        w = self._plain_delta(list(run.waves.__dict__.items()), self.wave_sent)
        if w:
            snap["W"] = w
        # ev sahibinin kombosu / skoru (takım tablosu için)
        snap["m"] = [int(run.ctx_get(0, "score") or 0), int(run.ctx_get(0, "kills") or 0)]
        # efektler (yalnız konuğun görebileceği yerde olanlar) ve sesler
        if self.fx_log:
            snap["fx"] = coop_filter_fx(self.fx_log, view_rect)
            self.fx_log = []
        if self.sfx_log:
            seen_s, sl = set(), []
            for nm, vol in self.sfx_log:
                if nm not in seen_s and len(sl) < 10:
                    seen_s.add(nm)
                    sl.append([nm, _coop_q(vol)])
            snap["sfx"] = sl
            self.sfx_log = []
        snap["ack"] = run.cmd_ack
        snap["tp"] = run.tp[1]
        self.keyframe = False
        return snap


COOP_FX_CAP = {"p": 36, "b": 40, "r": 16, "w": 16, "l": 12, "f": 2, "k": 2}


def coop_filter_fx(log, view):
    """Konuğun ekranına düşen efektler (türe göre sınırlı)."""
    out, cnt = [], {}
    area = view.inflate(300, 300) if view is not None else None
    for ev in log:
        k = ev[0]
        c = cnt.get(k, 0)
        if c >= COOP_FX_CAP.get(k, 8):
            continue
        if k in ("p", "b", "r", "w") and area is not None:
            if not area.collidepoint(ev[1], ev[2]):
                continue
        elif k == "l" and area is not None:
            pts = ev[1]
            if not pts or not area.collidepoint(pts[0][0], pts[0][1]):
                continue
        cnt[k] = c + 1
        out.append(ev)
    return out


class CoopFx(EffectSystem):
    """Ev sahibinde: efektler hem çizilir hem konuğa gönderilmek üzere kaydedilir."""

    def __init__(self):
        EffectSystem.__init__(self)
        self.log = None

    def _rec(self, *ev):
        lg = self.log
        if lg is not None and len(lg) < 900:
            lg.append([_coop_q(x) if type(x) is float else x for x in ev])

    def burst(self, x, y, color, n=10, speed=140, life=0.5, r=3.0, gravity=0.0, add=True):
        EffectSystem.burst(self, x, y, color, n, speed, life, r, gravity, add)
        self._rec("b", float(x), float(y), list(color)[:3], int(n), float(speed), float(life), float(r))

    def ring(self, x, y, color, n=16, speed=180, life=0.4, r=2.5):
        EffectSystem.ring(self, x, y, color, n, speed, life, r)
        self._rec("r", float(x), float(y), list(color)[:3], int(n), float(speed), float(life), float(r))

    def shockwave(self, x, y, radius, color, life=0.35, width=5):
        EffectSystem.shockwave(self, x, y, radius, color, life, width)
        self._rec("w", float(x), float(y), float(radius), list(color)[:3], float(life), int(width))

    def bolt(self, pts, color=(200, 230, 255), life=0.25):
        EffectSystem.bolt(self, pts, color, life)
        try:
            self._rec("l", [[_coop_q(float(a)), _coop_q(float(b))] for a, b in list(pts)[:24]],
                      list(color)[:3], float(life))
        except Exception:
            pass

    def popup(self, x, y, text, color=TEXT, size=18, life=0.8):
        EffectSystem.popup(self, x, y, text, color, size, life)
        self._rec("p", float(x), float(y), str(text)[:40], list(color)[:3], int(size), float(life))

    def shake(self, amount=8, duration=0.18):
        EffectSystem.shake(self, amount, duration)
        self._rec("k", float(amount), float(duration))

    def do_flash(self, color=WHITE, amount=0.5):
        EffectSystem.do_flash(self, color, amount)
        self._rec("f", list(color)[:3], float(amount))


def _coop_color(v):
    try:
        return (int(clamp(v[0], 0, 255)), int(clamp(v[1], 0, 255)), int(clamp(v[2], 0, 255)))
    except Exception:
        return (255, 255, 255)


def coop_replay_fx(fx, events):
    """Konukta: ev sahibinden gelen efektleri kendi efekt sistemine oynatır."""
    if not isinstance(events, list):
        return
    for ev in events[:200]:
        try:
            k = ev[0]
            if k == "b":
                fx.burst(float(ev[1]), float(ev[2]), _coop_color(ev[3]), n=min(40, int(ev[4])),
                         speed=float(ev[5]), life=min(3.0, float(ev[6])), r=min(12.0, float(ev[7])))
            elif k == "r":
                fx.ring(float(ev[1]), float(ev[2]), _coop_color(ev[3]), n=min(60, int(ev[4])),
                        speed=float(ev[5]), life=min(3.0, float(ev[6])), r=min(12.0, float(ev[7])))
            elif k == "w":
                if len(fx.rings) < 90:          # konuk: halka / şimşek de tavanlı
                    fx.shockwave(float(ev[1]), float(ev[2]), min(2000.0, float(ev[3])), _coop_color(ev[4]),
                                 life=min(3.0, float(ev[5])), width=min(12, int(ev[6])))
            elif k == "l":
                pts = [(float(a), float(b)) for a, b in ev[1][:24]]
                if len(pts) >= 2 and len(fx.bolts) < 60:
                    fx.bolt(pts, _coop_color(ev[2]), min(2.0, float(ev[3])))
            elif k == "p":
                fx.popup(float(ev[1]), float(ev[2]), str(ev[3])[:40], _coop_color(ev[4]),
                         int(clamp(int(ev[5]), 8, 64)), min(4.0, float(ev[6])))
            elif k == "k":
                fx.shake(min(16.0, float(ev[1])) * 0.6, min(1.0, float(ev[2])))
            elif k == "f":
                fx.do_flash(_coop_color(ev[1]), min(0.8, float(ev[2])) * 0.7)
        except Exception:
            continue


_SFX_TAP = [None]      # ev sahibinde: çalınan seslerin kaydı (konuğa gider)

# 2 kişilik - konuk tarafı
class GuestRun(CoopRunState):
    """Konuğun ekranındaki koşu: simülasyon yok, ev sahibinin anlık görüntüsüyle dolar."""

    is_guest = True

    def __init__(self, save, skins, diff, names=("", ""), cosmetics=(None, None)):
        CoopRunState.__init__(self, save, skins, diff, names, cosmetics)
        self.fx = EffectSystem()
        # kendi bağlamım: 1 (kartlar, altın, skor, kamera hep benim)
        self._ctx_use(1)
        for name in COOP_SHARED_LISTS:
            setattr(self, name, [])
        self.objs = {}
        self.cls_ok = {n: globals()[n] for n in COOP_SYNC_CLASS_NAMES if n in globals()}
        self.cmd_seq = 0
        self.cmd_wait = {}            # gönderilen, onaylanmamış komutlar
        self.cmd_msgs = {}            # id -> [mesaj, zaman] (yeniden gönderim için)
        self.pending_cmds = []        # ağ katmanının göndereceği komutlar
        self.last_snap_t = 0.0
        self.snap_gap = 1.0 / COOP_SNAP_HZ
        self.host_score = [0, 0]
        self.my_tp = 0
        self.got_first = False
        self.local_shop = False
        self.vx = self.vy = 0.0
        self.dash_t = 0.0
        self.dash_dir = (0.0, 0.0)
        self.dash_cd = 0.0
        # çizim ara belleği (jitter buffer): nesneler ev sahibinin zamanında
        # `_interp_d` sn geriden, iki görüntü arasında akıcı çizilir.
        self._clk = collections.deque(maxlen=90)    # (varış, varış - gönderim)
        self._off_min = None
        self._interp_d = 0.12
        self._interp_tgt = 0.12
        self._snap_dt = 1.0 / COOP_SNAP_HZ
        self._last_ht = None
        self._prev_ht = None
        self._cur_ht = 0.0
        self._fxq = []                 # (zaman, efektler, sesler) - zamanı gelince oynar
        # kendi ana silahım: ev sahibini beklemeden burada ateşlenir ve çizilir
        # (hasarı yine ev sahibi verir; onun gönderdiği kopya gizlenir)
        self.pred_shots = []
        self.pred_cd = 0.0
        self._pp_real = None
        # ev sahibinin benim için bildiği konum geçmişi: (ev sahibi zamanı, x, y)
        self._me_hist = collections.deque(maxlen=40)

    # ---- komutlar (pencere eylemleri) ----
    def _cmd(self, c, **kw):
        self.cmd_seq += 1
        msg = {"t": "c", "id": self.cmd_seq, "c": c}
        msg.update(kw)
        self.pending_cmds.append(msg)
        self.cmd_wait[self.cmd_seq] = c
        self.cmd_msgs[self.cmd_seq] = [msg, time.time()]
        return self.cmd_seq

    def resend_cmds(self):
        """Yeniden bağlanınca onaylanmamış komutlar sırayla yeniden gider (ev sahibi kimliği gördüğü komutu ikinci kez işlemez)."""
        sent = {id(m) for m in self.pending_cmds}
        for k in sorted(self.cmd_msgs):
            m = self.cmd_msgs[k][0]
            if id(m) not in sent:
                self.pending_cmds.append(m)
        self.pending_cmds.sort(key=lambda m: m.get("id", 0))

    def expire_cmds(self):
        """Onayı 8 sn'de gelmeyen komut bekletmeyi bırakır (kartlar kilitlenmesin)."""
        now = time.time()
        for k in [k for k, v in self.cmd_msgs.items() if now - v[1] > 8.0]:
            self.cmd_msgs.pop(k, None)
            self.cmd_wait.pop(k, None)

    def _waiting(self, *names):
        return any(v in names for v in self.cmd_wait.values())

    def choose_levelup(self, idx):
        if self._waiting("lv_pick", "lv_reroll", "lv_skip"):
            return
        self._cmd("lv_pick", i=int(idx))
        self.levelup_choices = []          # yeni el gelene dek boş (çift seçim olmasın)
        self.pending_levelups = max(0, self.pending_levelups - 1)

    def reroll_levelup(self):
        if self._waiting("lv_pick", "lv_reroll", "lv_skip"):
            return False, ""
        self._cmd("lv_reroll")
        return True, ""

    def skip_levelup(self):
        if self._waiting("lv_pick", "lv_reroll", "lv_skip"):
            return False, ""
        self._cmd("lv_skip")
        self.levelup_choices = []
        self.pending_levelups = max(0, self.pending_levelups - 1)
        return True, ""

    def buy_shop_item(self, key):
        self._cmd("shop_buy", k=str(key))
        return True

    def choose_oath(self, key, tier=0):
        if key is not None:
            self._cmd("oath", k=str(key), tier=int(tier))
        else:
            self._cmd("m_close")
        self.merchant_open = False

    def merchant_reroll(self):
        self._cmd("m_reroll")
        return True, ""

    def accept_curse(self, idx):
        self._cmd("cu_pick", i=int(idx))
        self.curse_offers = None

    def decline_curse(self):
        self._cmd("cu_decline")
        self.curse_offers = None

    def start_levelup_choice(self):
        pass                                # el ev sahibinde hazırlanır

    def open_shop(self):
        self.shop_offers = SHOP_ITEMS

    def update(self, dt, inputs):
        pass

    # ---- anlık görüntüyü uygula ----
    def _dec(self, v, d=0):
        if isinstance(v, list):
            if d > 6:
                return []
            items = [self._dec(x, d + 1) for x in v[:400]]
            if len(items) <= 4 and items and all(type(x) in (int, float) for x in items):
                return tuple(items)
            return items
        if isinstance(v, dict):
            if d > 6:
                return {}
            if "$p" in v:
                i = v.get("$p")
                return self.players[i] if isinstance(i, int) and 0 <= i < len(self.players) else None
            if "$o" in v:
                n = v.get("$o")
                return self.objs.get(n) if isinstance(n, int) else None
            if "$s" in v:
                tag = v.get("$s")
                if isinstance(tag, list) and len(tag) == 2:
                    return _coop_static_tables()[1].get((tag[0], tag[1]))
                return None
            out = {}
            for k, x in list(v.items())[:400]:
                if not isinstance(k, str):
                    continue
                if k.startswith("#"):
                    try:
                        k = int(k[1:])
                    except ValueError:
                        continue
                out[k] = self._dec(x, d + 1)
            return out
        if isinstance(v, (bool, int, float, str)) or v is None:
            if isinstance(v, float) and not math.isfinite(v):
                return 0.0
            return v
        return None

    def _set_fields(self, obj, fields, track_pos=True):
        cls = type(obj)
        nx = ny = None
        for k, v in fields.items():
            if k == "$c" or not isinstance(k, str) or not _coop_field_ok(k):
                continue
            ca = getattr(cls, k, None)
            if ca is not None and (callable(ca) or isinstance(ca, property)):
                continue                     # yöntemlerin üstüne yazılamaz
            val = self._dec(v)
            if k in COOP_SLOW_FIELDS and type(val) in (int, float) and not isinstance(val, bool):
                # saat alanı: hızını öğren, aralarda konuk kendisi akıtsın
                try:
                    d = obj.__dict__
                    now = time.time()
                    prev = d.get("_rv_" + k)
                    if prev is not None and now - prev[1] > 0.2:
                        rate = (val - prev[0]) / (now - prev[1])
                        if abs(rate) < 50:
                            d.setdefault("_rates", {})[k] = rate
                    d["_rv_" + k] = (val, now)
                    object.__setattr__(obj, k, val)
                    if k not in d.setdefault("_rates", {}):
                        d["_rates"][k] = 1.0 if k in ("spawn_t", "t", "age") else (-1.0 if k == "life" else 0.0)
                except (AttributeError, TypeError):
                    try:
                        object.__setattr__(obj, k, val)
                    except Exception:
                        pass
                continue
            if track_pos and k in ("x", "y") and type(val) in (int, float) and not isinstance(val, bool):
                # konum çizim ara belleğine
                if k == "x":
                    nx = val
                else:
                    ny = val
                continue
            try:
                object.__setattr__(obj, k, val)
            except Exception:
                pass
        if nx is not None or ny is not None:
            try:
                self._push_pos(obj, nx, ny)
            except (AttributeError, TypeError):
                pass

    def _snap_clock(self, snap):
        """Görüntünün ev sahibi zamanı + saat farkı / titreşim tahmini."""
        now = snap.get("_rx") if type(snap.get("_rx")) is float else time.time()
        ht = snap.get("ht")
        if type(ht) in (int, float) and math.isfinite(ht):
            ht = float(ht)
            self._clk.append((now, now - ht))
            if self._last_ht is not None and ht > self._last_ht:
                self._snap_dt = self._snap_dt * 0.9 + min(0.5, ht - self._last_ht) * 0.1
        else:
            ht = (self._last_ht or 0.0) + self._snap_dt
        if self._clk:
            offs = sorted(o_ for _t, o_ in self._clk)
            self._off_min = offs[0]
            jit = offs[min(len(offs) - 1, int(len(offs) * 0.9))] - offs[0]
            self._interp_tgt = clamp(self._snap_dt * 1.15 + jit + 0.015, COOP_INTERP_MIN, COOP_INTERP_MAX)
        self._prev_ht = self._last_ht
        self._last_ht = ht if self._last_ht is None else max(self._last_ht, ht)
        self._cur_ht = ht
        return ht

    def render_time(self):
        if self._off_min is None:
            return None
        return time.time() - self._off_min - self._interp_d

    def apply_snapshot(self, snap):
        if not isinstance(snap, dict):
            return
        o = snap.get("o") or {}
        if not isinstance(o, dict):
            return
        self._snap_clock(snap)
        if snap.get("key"):
            # tam görüntü: eski nesneler (oyuncular hariç) atılır
            keep = {n: ob for n, ob in self.objs.items() if isinstance(ob, Player)}
            self.objs = keep
        L_ = snap.get("L") or {}
        # oyuncu kimlikleri
        pl = L_.get("$P")
        if isinstance(pl, list) and len(pl) == len(self.players):
            for n, p in zip(pl, self.players):
                if isinstance(n, int):
                    self.objs[n] = p
        # 1) yeni nesneleri kur
        for ks, fields in o.items():
            try:
                n = int(ks)
            except (TypeError, ValueError):
                continue
            if not isinstance(fields, dict):
                continue
            if n not in self.objs:
                cname = fields.get("$c")
                cls = self.cls_ok.get(cname) if isinstance(cname, str) else None
                if cls is None or cls is Player:
                    continue
                try:
                    gc_ = coop_guest_class(cname)
                    self.objs[n] = gc_.__new__(gc_)
                except Exception:
                    continue
        # 2) alanları yaz
        me = self.player
        for ks, fields in o.items():
            try:
                n = int(ks)
            except (TypeError, ValueError):
                continue
            obj = self.objs.get(n)
            if obj is None or not isinstance(fields, dict):
                continue
            if obj is me:
                # kendi karakterim: konum/hız bende (ev sahibi yalnız
                # ışınlarken)
                f2 = {k: v for k, v in fields.items()
                      if k not in ("x", "y", "vx", "vy", "move_in", "aim_dir", "dash_time",
                                   "dash_dx", "dash_dy", "kbx", "kby")}
                self._set_fields(obj, f2, track_pos=False)
                if "x" in fields or "y" in fields:
                    me._hx = self._dec(fields.get("x", getattr(me, "_hx", me.x)))
                    me._hy = self._dec(fields.get("y", getattr(me, "_hy", me.y)))
                continue
            self._set_fields(obj, fields, track_pos=not isinstance(obj, Player) or True)
        hx, hy = getattr(me, "_hx", None), getattr(me, "_hy", None)
        if type(hx) in (int, float) and type(hy) in (int, float):
            if self._me_hist and self._cur_ht <= self._me_hist[-1][0] + 1e-6:
                self._me_hist[-1] = (self._me_hist[-1][0], float(hx), float(hy))
            else:
                self._me_hist.append((self._cur_ht, float(hx), float(hy)))
        # 3) listeler
        for name, nids in L_.items():
            if not isinstance(name, str):
                continue
            if name in COOP_SHARED_LISTS and isinstance(nids, list):
                setattr(self, name, [self.objs[n] for n in nids if isinstance(n, int) and n in self.objs])
            elif ":" in name and isinstance(nids, list):
                ci, _, lname = name.partition(":")
                if lname in COOP_MERGE_LISTS and ci in ("0", "1"):
                    lst = [self.objs[n] for n in nids if isinstance(n, int) and n in self.objs]
                    self.ctx_set(int(ci), lname, lst)
            elif name.startswith("$") and name[1:] in COOP_SINGLES:
                obj = self.objs.get(nids) if isinstance(nids, int) and nids else None
                setattr(self, name[1:], obj)
            elif name in ("bh0", "bh1") and isinstance(nids, list):
                bh = [x for x in (self._dec(nids) or []) if isinstance(x, dict)]
                self.ctx_set(int(name[2]), "black_holes", bh)
        # 4) silinenler
        for n in snap.get("d") or []:
            if isinstance(n, int):
                ob = self.objs.get(n)
                if ob is not None and not isinstance(ob, Player):
                    self.objs.pop(n, None)
        # 5) koşu, dalga, kombo alanları
        ack = snap.get("ack")
        if isinstance(ack, int):
            for k in [k for k in self.cmd_wait if k <= ack]:
                self.cmd_wait.pop(k, None)
            for k in [k for k in self.cmd_msgs if k <= ack]:
                self.cmd_msgs.pop(k, None)
        r = snap.get("R")
        if isinstance(r, dict):
            # kamera / harita / panel konuğun kendi elinde
            hold = {"cam_x", "cam_y", "show_map", "show_stats", "want_open_shop", "shop_offers",
                    "fx", "players", "names"}
            if self._waiting("lv_pick", "lv_reroll", "lv_skip"):
                hold |= {"levelup_choices", "pending_levelups"}
            if self._waiting("oath", "m_close"):
                hold.add("merchant_open")
            if self._waiting("cu_pick", "cu_decline"):
                hold.add("curse_offers")
            for k, v in r.items():
                if (not isinstance(k, str) or not _coop_field_ok(k) or k in COOP_RUN_SKIP
                        or k in hold or k in ("is_guest", "is_coop", "objs", "cls_ok",
                                              "pending_cmds", "cmd_wait", "track")):
                    continue
                ca = getattr(type(self), k, None)
                if ca is not None and callable(ca):
                    continue
                self.__dict__[k] = self._dec(v)
        w = snap.get("W")
        if isinstance(w, dict):
            self._set_fields(self.waves, w, track_pos=False)
        cb = snap.get("C")
        if isinstance(cb, dict):
            self._set_fields(self.combo, cb, track_pos=False)
        m = snap.get("m")
        if isinstance(m, list) and len(m) == 2:
            self.host_score = [int(m[0]) if isinstance(m[0], int) else 0,
                               int(m[1]) if isinstance(m[1], int) else 0]
        tp = snap.get("tp")
        if isinstance(tp, int) and tp != self.my_tp:
            # ev sahibi beni ışınladı (cehennem kapısı): konumum onunki olur
            self.my_tp = tp
            hx, hy = getattr(me, "_hx", me.x), getattr(me, "_hy", me.y)
            if type(hx) in (int, float) and type(hy) in (int, float):
                me.x, me.y = float(hx), float(hy)
                self.update_camera(0.0, snap=True)
        if snap.get("fx") or snap.get("sfx"):
            self._fxq.append((self._cur_ht, snap.get("fx"), snap.get("sfx")))
            if len(self._fxq) > 24:            # çok birikti: eskiyi hemen oynat
                self._play_fx(self._fxq.pop(0))
        self.got_first = True

    def _play_fx(self, item):
        _t, fx_, sf = item
        coop_replay_fx(self.fx, fx_)
        for it in (sf or [])[:10]:
            try:
                nm = str(it[0])
                if nm in getattr(audio, "sounds", {}) or nm in getattr(audio, "_raw", {}):
                    sfx(nm, min(1.0, float(it[1])), 0.03)
            except Exception:
                pass

    def _push_pos(self, obj, nx, ny):
        """Konum örneği: (ev sahibi zamanı, x, y)."""
        d = getattr(obj, "__dict__", None)
        if d is None:
            # sözlüksüz (yalnız __slots__) nesne: ara bellek yok, doğrudan yaz
            if nx is not None:
                object.__setattr__(obj, "x", float(nx))
            if ny is not None:
                object.__setattr__(obj, "y", float(ny))
            return
        h = d.get("_hist")
        t = self._cur_ht
        if not h:
            # dikkat: bazı sınıflar (Pickup) __slots__ kullanır: x/y sözlükte
            # değil yuvada durur, o yüzden setattr ile yazılır
            x0 = float(nx if nx is not None else getattr(obj, "x", 0.0) or 0.0)
            y0 = float(ny if ny is not None else getattr(obj, "y", 0.0) or 0.0)
            d["_hist"] = [[t, x0, y0]]
            object.__setattr__(obj, "x", x0)
            object.__setattr__(obj, "y", y0)
            d["_tx"], d["_ty"] = x0, y0
            return
        lx, ly = h[-1][1], h[-1][2]
        x1 = float(nx) if nx is not None else lx
        y1 = float(ny) if ny is not None else ly
        # nesne bir süre durup şimdi kıpırdadıysa, önceki görüntü anında hâlâ
        # eski yerindeydi: yoksa çizim bu aralığı yavaş yavaş kayardı
        if self._prev_ht is not None and h[-1][0] < self._prev_ht - 1e-6 < t:
            h.append([self._prev_ht, lx, ly])
        if t > h[-1][0] + 1e-6:
            h.append([t, x1, y1])
        else:
            h[-1][1], h[-1][2] = x1, y1
        if len(h) > 7:
            del h[:-7]
        d["_tx"], d["_ty"] = x1, y1

    # ---- her kare: kendi hareketim + yumuşatma ----
    def local_update(self, dt, inp):
        me = self.player
        # benim hareketim (Player.update'in hareket kısmının aynısı)
        if me.alive:
            mx = inp.get("right", 0) - inp.get("left", 0)
            my = inp.get("down", 0) - inp.get("up", 0)
            ml = math.hypot(mx, my)
            if ml > 0:
                mx, my = mx / ml, my / ml
                me.move_anim = getattr(me, "move_anim", 0.0) + dt * 10
            me.move_in = (mx, my)
            self.dash_cd = max(0.0, self.dash_cd - dt)
            if inp.get("dash_pressed") and self.dash_cd <= 0 and self.dash_t <= 0:
                dx, dy = (mx, my) if abs(mx) + abs(my) > 0.1 else tuple(me.aim_dir)
                l = math.hypot(dx, dy) or 1.0
                self.dash_dir = (dx / l, dy / l)
                self.dash_t = 0.17
                try:
                    self.dash_cd = float(me.eff_dash_cd())
                except Exception:
                    self.dash_cd = 1.2
            if self.dash_t > 0:
                self.dash_t -= dt
                sp = 205.0 * float(getattr(me, "dash_dist_mult", 1.0) or 1.0) / 0.17
                me.x += self.dash_dir[0] * sp * dt
                me.y += self.dash_dir[1] * sp * dt
                me.speed_now = sp
            else:
                try:
                    sp = float(me.eff_speed())
                except Exception:
                    sp = BASE_SPEED
                k = min(1.0, dt * 16)
                self.vx += (mx * sp - self.vx) * k
                self.vy += (my * sp - self.vy) * k
                me.x += self.vx * dt
                me.y += self.vy * dt
                me.vx, me.vy = self.vx, self.vy
                me.speed_now = math.hypot(self.vx, self.vy)
            me.x = clamp(me.x, ARENA_RECT.left + me.radius, ARENA_RECT.right - me.radius)
            me.y = clamp(me.y, ARENA_RECT.top + me.radius, ARENA_RECT.bottom - me.radius)
            ax, ay = inp.get("aim_x", me.x), inp.get("aim_y", me.y - 1)
            try:
                me.set_aim(*norm_dir(me.x, me.y, ax, ay))
            except Exception:
                pass
            self.update_camera(dt)
            self.pred_cd -= dt
            if inp.get("mouse_down") and COOP_PREDICT_GUN:
                if self.pred_cd <= 0:
                    self._pred_fire(me)
            else:
                self.pred_cd = max(self.pred_cd, 0.0)
        else:
            mate = self.players[0]
            tx = clamp(mate.x - VIEW_RECT.w / 2, ARENA_RECT.left, ARENA_RECT.right - VIEW_RECT.w)
            ty = clamp(mate.y - VIEW_RECT.h / 2, ARENA_RECT.top, ARENA_RECT.bottom - VIEW_RECT.h)
            k = min(1.0, dt * 6)
            self.cam_x += (tx - self.cam_x) * k
            self.cam_y += (ty - self.cam_y) * k
        # öbür nesneler: çizim ara belleğinden (ev sahibi zamanında biraz
        # geriden)
        self._interp_d += clamp(self._interp_tgt - self._interp_d, -0.3 * dt, 0.3 * dt)
        rt = self.render_time()
        if rt is not None:
            while self._fxq and self._fxq[0][0] <= rt:
                self._play_fx(self._fxq.pop(0))
        for lst in self._all_drawn():
            for ob in lst:
                d = getattr(ob, "__dict__", None)
                if d is None or ob is me:
                    continue
                rates = d.get("_rates")
                if rates:
                    for rk, rv in rates.items():
                        cur_ = d.get(rk)
                        if type(cur_) in (int, float) and rv:
                            d[rk] = cur_ + rv * dt
                h = d.get("_hist")
                if h:
                    try:
                        self._interp_pos(ob, d, h, rt)
                    except (AttributeError, TypeError, ValueError):
                        pass
        self._lag_shift(rt)
        self._pred_update(dt)
        # zaman sayaçları (görüntü aralarında da aksın)
        for p in self.players:
            if p is not me and p.alive:
                p.ghosts = [g for g in (getattr(p, "ghosts", None) or []) if isinstance(g, (list, tuple))]
        self.fx.update(dt)
        try:
            self.combo.update(0.0)
        except Exception:
            pass

    # ---- kendi ana silahım: tahmin ----
    def _pred_fire(self, me):
        """Ev sahibinin do_player_attack'ıyla aynı geometri; yalnız görüntü."""
        try:
            cd = float(me.eff_atk_cd())
        except Exception:
            cd = BASE_ATK_CD
        # basılı tutarken aralık kaymasın (kare süresi taşarsa bir sonrakinden düşülür)
        self.pred_cd = max(self.pred_cd + cd, cd * 0.5)
        if len(self.pred_shots) >= COOP_PRED_MAX:
            return
        aim_dx, aim_dy = me.aim_dir
        sk = me.skin
        try:
            n = 1 + int(me.multishot_level)
            speed = 660 * float(me.proj_speed_mult)
            hits = int(me.eff_pierce_hits())
            homing = me.homing_level
        except Exception:
            n, speed, hits, homing = 1, 660.0, 1, 0
        base_ang = math.atan2(aim_dy, aim_dx)
        off = me.radius + sk["wlen"] * 0.55
        for i in range(min(n, 12)):
            ang = base_ang + (i - (n - 1) / 2) * math.radians(9)
            pr = PlayerProjectile(me.x + aim_dx * off, me.y + aim_dy * off,
                                  math.cos(ang) * speed, math.sin(ang) * speed, 0, max(1, hits), 0, 1,
                                  homing=homing, style=sk["proj"], color=sk["color"], accent=sk["accent"])
            self.pred_shots.append(pr)
        me.recoil = 1.0
        me.flash_t = 0.08
        self.fx.spark(me.x + aim_dx * me.radius, me.y + aim_dy * me.radius, sk["accent"],
                      aim_dx * 40, aim_dy * 40, .15, 2)
        sfx("shoot_" + sk["sfx"], 0.5, 0.035)

    def _pred_update(self, dt):
        if not self.pred_shots:
            return
        targets = [e for e in list(self.enemies) + list(self.bosses)
                   if getattr(e, "alive", False) and not getattr(e, "phased", False)
                   and type(getattr(e, "x", None)) in (int, float)]
        for pr in self.pred_shots:
            if pr.homing > 0 and targets:
                best = min(targets, key=lambda e: (e.x - pr.x) ** 2 + (e.y - pr.y) ** 2)
                pr.steer_toward(best.x, best.y, dt)
            pr.update(dt)
            if not pr.alive:
                continue
            pr.emit(self.fx, dt)
            for e in targets:
                if id(e) in pr.hit_set:
                    continue
                er = getattr(e, "hit_r", None) or getattr(e, "radius", 14) or 14
                if (pr.x - e.x) ** 2 + (pr.y - e.y) ** 2 < (pr.r + er + max(3.0, pr.r * 0.35)) ** 2:
                    pr.hit_set.add(id(e))
                    pr.hits_left -= 1
                    if pr.hits_left <= 0:
                        pr.alive = False
                        break
        self.pred_shots = [pr for pr in self.pred_shots if pr.alive]

    def _me_host_at(self, rt):
        """Ev sahibinin rt anında benim için bildiği konum (yoksa None)."""
        h = self._me_hist
        if rt is None or not h:
            return None
        if rt >= h[-1][0]:
            return h[-1][1], h[-1][2]
        if rt <= h[0][0]:
            return h[0][1], h[0][2]
        for i in range(len(h) - 1, 0, -1):
            a_, b_ = h[i - 1], h[i]
            if a_[0] <= rt:
                sp = b_[0] - a_[0]
                k = (rt - a_[0]) / sp if sp > 1e-6 else 1.0
                return a_[1] + (b_[1] - a_[1]) * k, a_[2] + (b_[2] - a_[2]) * k
        return h[0][1], h[0][2]

    def _lag_shift(self, rt):
        """Bana bağlı silahlar (kırbaç, kılıç, ışın, yörünge) ev sahibinin
        geçmişteki konumumda değil, şimdiki yerimde çizilsin."""
        me = self.player
        if not me.alive:
            return
        hp = self._me_host_at(rt)
        if hp is None:
            return
        sx, sy = me.x - hp[0], me.y - hp[1]
        if abs(sx) + abs(sy) < 0.5 or abs(sx) + abs(sy) > 300:
            return
        for name in COOP_LAG_SHIFT:
            for ob in self.ctx_get(1, name) or []:
                d = getattr(ob, "__dict__", None)
                if d is None or not d.get("_hist"):
                    continue          # konumu her kare yeniden yazılmayan nesne kaydırılmaz
                x, y = d.get("x"), d.get("y")
                if type(x) in (int, float) and type(y) in (int, float):
                    d["x"], d["y"] = x + sx, y + sy

    def view_begin(self, i):
        if COOP_PREDICT_GUN:
            own = self.__dict__.get("player_projectiles") or []
            self._pp_real = own
            self.__dict__["player_projectiles"] = (
                [pr for pr in own if not getattr(pr, "gun", 0)] + self.pred_shots)
        CoopRunState.view_begin(self, i)

    def view_end(self):
        CoopRunState.view_end(self)
        if self._pp_real is not None:
            self.__dict__["player_projectiles"] = self._pp_real
            self._pp_real = None

    def _interp_pos(self, ob, d, h, rt):
        """Ev sahibi zamanı rt'de nesnenin yeri: iki örnek arası doğrusal"""
        if rt is None or len(h) == 1 and rt >= h[0][0]:
            x, y = h[-1][1], h[-1][2]
        elif rt <= h[0][0]:
            x, y = h[0][1], h[0][2]
            # yeni doğan mermi: namludan çıkıyormuş gibi geriden gelsin
            vx_, vy_ = d.get("vx"), d.get("vy")
            if (len(h) == 1 and type(vx_) in (int, float) and type(vy_) in (int, float)
                    and not isinstance(ob, (Player, Enemy, Boss))):
                back = min(0.2, h[0][0] - rt)
                x -= vx_ * back
                y -= vy_ * back
        elif rt >= h[-1][0]:
            x, y = h[-1][1], h[-1][2]
            # en yeni görüntüde güncellendiyse ve hâlâ hareketliyse ileri
            # tahmin
            if len(h) >= 2 and self._last_ht is not None and h[-1][0] >= self._last_ht - 1e-6:
                a_, b_ = h[-2], h[-1]
                sp = b_[0] - a_[0]
                if sp > 1e-3 and abs(b_[1] - a_[1]) + abs(b_[2] - a_[2]) < 400:
                    ex = min(rt - b_[0], 0.2)
                    x += (b_[1] - a_[1]) / sp * ex
                    y += (b_[2] - a_[2]) / sp * ex
        else:
            i = len(h) - 2
            while i > 0 and h[i][0] > rt:
                i -= 1
            a_, b_ = h[i], h[i + 1]
            sp = b_[0] - a_[0]
            if abs(b_[1] - a_[1]) + abs(b_[2] - a_[2]) > 400:     # ışınlanma: atla
                x, y = (b_[1], b_[2]) if rt >= a_[0] + sp * 0.5 else (a_[1], a_[2])
            else:
                k = (rt - a_[0]) / sp if sp > 1e-6 else 1.0
                x = a_[1] + (b_[1] - a_[1]) * k
                y = a_[2] + (b_[2] - a_[2]) * k
            if i > 1:
                del h[:i - 1]                  # gerekmeyen eski örnekler
        object.__setattr__(ob, "x", x)
        object.__setattr__(ob, "y", y)

    def _all_drawn(self):
        out = [getattr(self, n, None) or [] for n in COOP_SHARED_LISTS]
        for i in (0, 1):
            for n in COOP_MERGE_LISTS:
                if n != "black_holes":
                    out.append(self.ctx_get(i, n) or [])
        out.append([self.players[0]])
        for n in COOP_SINGLES:
            ob = getattr(self, n, None)
            if ob is not None:
                out.append([ob])
        return out


_COOP_GUEST_CLS = {}


def _coop_guest_getattr(self, name):
    # Konukta nesne __init__ çalışmadan kurulur: çizim kodunun tembel
    # önbellekleri (_spr, _blink...) ilk okunuşta boş başlar.
    if name.startswith("_") and not name.startswith("__"):
        try:
            object.__setattr__(self, name, None)
        except Exception:
            pass
        return None
    raise AttributeError(name)


def _coop_safe_method(fn):
    def wrapped(self, *a, **k):
        try:
            return fn(self, *a, **k)
        except Exception:
            return None
    return wrapped


def coop_guest_class(name):
    """Konukta kullanılan sınıf: aslının alt sınıfı (isinstance aynen çalışır)"""
    c = _COOP_GUEST_CLS.get(name)
    if c is None:
        base = globals()[name]
        ns = {"__getattr__": _coop_guest_getattr}
        for attr in dir(base):
            if attr.startswith("draw") and callable(getattr(base, attr, None)):
                ns[attr] = _coop_safe_method(getattr(base, attr))
        c = type(name, (base,), ns)
        _COOP_GUEST_CLS[name] = c
    return c


