TUT_STEPS = ("welcome", "codex", "codex2", "back", "skin", "skin2", "skin3", "skin4", "play", "map",
             "move", "shop", "shop2", "done")
TUT_FREE_SKIN = "ranger"


class Tutorial:
    """Adım adım yönlendirme katmanı (ekranların üstüne çizilir)."""

    def __init__(self, app):
        self.app = app
        self.i = 0
        self.t = 0.0
        self.active = True
        self._btns = []

    @property
    def step(self):
        return TUT_STEPS[self.i] if self.i < len(TUT_STEPS) else "done"

    def go(self, name):
        if name in TUT_STEPS:
            self.i = TUT_STEPS.index(name)
            self.t = 0.0
            sfx("click", 0.5, 0.0)

    def finish(self):
        self.active = False
        try:
            self.app.save.data.setdefault("settings", {})["tut_done"] = True
            self.app.save.save()
        except Exception:
            pass

    # ---- hedefler (vurgulanan düğme) ----
    def _menu_btn(self, key):
        for b in getattr(self.app, "menu_buttons", None) or []:
            if getattr(b, "mkey", None) == key:
                return b.rect
        return None

    def _skin_card(self):
        try:
            idx = [sk["id"] for sk in SKINS].index(TUT_FREE_SKIN)
        except ValueError:
            return None
        cols, cw, ch, gx, gy = 4, 270, 208, 20, 18
        sx = (VIRTUAL_W - (cols * cw + (cols - 1) * gx)) / 2
        y = SKIN_LIST_TOP + (idx // cols) * (ch + gy) - getattr(self.app, "skin_scroll", 0.0)
        return pygame.Rect(int(sx + (idx % cols) * (cw + gx)), int(y), cw, ch)

    def _codex_card(self):
        cols, cw, gx = 4, 268, 18
        sx = (VIRTUAL_W - (cols * cw + (cols - 1) * gx)) / 2
        return pygame.Rect(int(sx), int(158 - getattr(self.app, "weapon_scroll", 0.0)), cw, 262)

    def _detail_btn(self):
        pr = pygame.Rect(0, 0, 540, 618)
        pr.center = (VIRTUAL_W / 2, VIRTUAL_H / 2)
        by = pr.bottom - 66
        if self.app.save.owns_skin(TUT_FREE_SKIN):
            return pygame.Rect(int(pr.centerx + 7), by, 170, 46)
        return pygame.Rect(int(pr.centerx - 177), by, 170, 46)

    def _back_btn(self):
        return pygame.Rect(int(VIRTUAL_W / 2 - 135), VIRTUAL_H - 58, 270, 44)

    # ---- akış ----
    def update(self, dt):
        """Durum değişikliklerine göre adımı ilerletir; (ekran, hedef, yazı, düğme) döner."""
        a = self.app
        st = a.state
        self.t += dt
        s_ = self.step
        run = a.run
        # oyuncu turu beklemeden oyuna girdiyse menü adımları atlanır
        if st == STATE_PLAY and TUT_STEPS.index(s_) < TUT_STEPS.index("move"):
            self.go("move")
            s_ = self.step
        if s_ == "codex" and st == STATE_WEAPON_CODEX:
            self.go("codex2")
        elif s_ in ("codex2", "back") and st == STATE_MENU:
            self.go("skin")
        elif s_ == "skin" and st == STATE_SKIN_MARKET:
            self.go("skin2")
        elif s_ == "skin2" and st == STATE_SKIN_DETAIL and getattr(a, "detail_skin_id", None) == TUT_FREE_SKIN:
            self.go("skin3")
        elif s_ == "skin3" and a.save.equipped_skin_id() == TUT_FREE_SKIN:
            self.go("skin4")
        elif s_ == "skin3" and st == STATE_SKIN_MARKET:
            self.go("skin2")
        elif s_ in ("skin2", "skin4") and st == STATE_MENU:
            self.go("play" if a.save.equipped_skin_id() == TUT_FREE_SKIN or s_ == "skin4" else "skin")
        elif s_ == "play" and st == STATE_MAP_SELECT:
            self.go("map")
        elif s_ == "map" and st == STATE_MENU:
            self.go("play")
        elif s_ == "move" and run is not None and int(getattr(run, "kills", 0)) >= 1:
            self.go("shop")
        elif s_ == "shop" and st == STATE_RUN_SHOP:
            self.go("shop2")
        elif s_ == "shop2" and st == STATE_PLAY:
            self.go("done")
        elif s_ == "done" and self.t > 4.5:
            self.finish()
        s_ = self.step
        # adım -> (gösterildiği ekran, hedef dikdörtgen, yazı anahtarı, ileri düğmesi)
        table = {
            "welcome": (STATE_MENU, None, "tut.welcome", "start"),
            "codex": (STATE_MENU, self._menu_btn("codex"), "tut.codex", None),
            "codex2": (STATE_WEAPON_CODEX, self._codex_card(), "tut.codex2", "next"),
            "back": (STATE_WEAPON_CODEX, self._back_btn(), "tut.back", None),
            "skin": (STATE_MENU, self._menu_btn("skin"), "tut.skin", None),
            "skin2": (STATE_SKIN_MARKET, self._skin_card(), "tut.skin2", None),
            "skin3": (STATE_SKIN_DETAIL, self._detail_btn(), "tut.skin3", None),
            "skin4": ((STATE_SKIN_MARKET, STATE_SKIN_DETAIL), self._back_btn(), "tut.skin4", None),
            "play": (STATE_MENU, self._menu_btn("play"), "tut.play", None),
            "map": (STATE_MAP_SELECT, None, "tut.map", None),
            "move": (STATE_PLAY, None, "tut.move", None),
            "shop": (STATE_PLAY, None, "tut.shop", None),
            "shop2": (STATE_RUN_SHOP, None, "tut.shop2", None),
            "done": (STATE_PLAY, None, "tut.done", None),
        }
        return table.get(s_)

    def take_click(self, mouse_pos, clicked):
        """Eğitimin kendi düğmeleri tıklandıysa tıklamayı yutar."""
        if not clicked or not self.active:
            return False
        for r, fn in self._btns:
            if r.collidepoint(mouse_pos):
                fn()
                return True
        # karşılama kartı açıkken arkadaki menü tıklanmaz
        return self.step == "welcome" and self.app.state == STATE_MENU

    def _next(self):
        s_ = self.step
        if s_ == "welcome":
            self.go("codex")
        elif s_ == "codex2":
            self.go("back")

    def _skip(self):
        sfx("click", 0.6, 0.0)
        self.finish()

    def draw(self, canvas, dt, mouse_pos):
        self._btns = []
        a = self.app
        if not self.active or (a.state == STATE_MENU and a.splash_t < a.SPLASH_TIME):
            return
        info = self.update(dt)
        if not self.active or info is None:
            return
        states, target, key, btn = info
        if not isinstance(states, tuple):
            states = (states,)
        if a.state not in states:
            return
        play = a.state == STATE_PLAY
        t = self.t
        # spot ışığı: hedef dışı hafif kararır (oyun içinde karartma yok)
        if target is not None and not play:
            dim = pygame.Surface((VIRTUAL_W, VIRTUAL_H), pygame.SRCALPHA)
            dim.fill((6, 8, 18, 120))
            dim.fill((0, 0, 0, 0), target.inflate(16, 16))
            canvas.blit(dim, (0, 0))
            k = 0.5 + 0.5 * math.sin(t * 5)
            pygame.draw.rect(canvas, (255, 214, 90), target.inflate(12 + 6 * k, 12 + 6 * k), 3,
                             border_radius=14)
        welcome = self.step == "welcome"
        if welcome:
            dim = pygame.Surface((VIRTUAL_W, VIRTUAL_H), pygame.SRCALPHA)
            dim.fill((6, 8, 18, 150))
            canvas.blit(dim, (0, 0))
        # konuşma balonu
        if key == "tut.skin2":
            sk_ = SKIN_BY_ID.get(TUT_FREE_SKIN)
            text = L(key, skin_name(sk_) if sk_ else TUT_FREE_SKIN)
        else:
            text = L(key)
        bw = 560 if welcome else 470
        lines = wrap_text(text, 15, bw - 40)[:5]
        extra = 0
        if self.step == "codex2":
            extra = 44
        bh = 58 + len(lines) * 21 + extra + (56 if btn else 0) + (30 if welcome else 0)
        if welcome:
            box = pygame.Rect(0, 0, bw, bh)
            box.center = (VIRTUAL_W // 2, VIRTUAL_H // 2)
        elif play:
            box = pygame.Rect(0, 0, bw, bh)
            box.midbottom = (VIRTUAL_W // 2, VIRTUAL_H - 118)     # duyurulara binmesin
        elif target is not None:
            # hedefin yanına; sığmazsa altına / üstüne
            box = pygame.Rect(0, 0, bw, bh)
            if target.right + 30 + bw < VIRTUAL_W - 10:
                box.midleft = (target.right + 34, target.centery)
            elif target.x - 30 - bw > 10:
                box.midright = (target.x - 34, target.centery)
            elif target.bottom + 20 + bh < VIRTUAL_H - 10:
                box.midtop = (target.centerx, target.bottom + 26)
            else:
                box.midbottom = (target.centerx, target.y - 26)
            box.clamp_ip(pygame.Rect(10, 10, VIRTUAL_W - 20, VIRTUAL_H - 20))
        else:
            box = pygame.Rect(0, 0, bw, bh)
            box.midtop = (VIRTUAL_W // 2, 70)
        bob = math.sin(t * 2.4) * 3 if not welcome else 0
        box = box.move(0, int(bob))
        panel(canvas, box, bg=(30, 34, 58), edge=(78, 82, 116), alpha=246, radius=16, edge_w=2)
        # ok: balondan hedefe
        if target is not None and not play and not welcome:
            ax = clamp(target.centerx, box.x + 20, box.right - 20)
            ay = clamp(target.centery, box.y + 20, box.bottom - 20)
            if target.centerx > box.right:
                ax = box.right
            elif target.centerx < box.x:
                ax = box.x
            elif target.centery > box.bottom:
                ay = box.bottom
            else:
                ay = box.y
            tx = clamp(ax, target.x - 6, target.right + 6)
            ty = clamp(ay, target.y - 6, target.bottom + 6)
            pygame.draw.line(canvas, (255, 214, 90), (ax, ay), (tx, ty), 4)
            ang = math.atan2(ty - ay, tx - ax)
            pts = [(tx, ty), (tx - math.cos(ang - 0.5) * 14, ty - math.sin(ang - 0.5) * 14),
                   (tx - math.cos(ang + 0.5) * 14, ty - math.sin(ang + 0.5) * 14)]
            pygame.draw.polygon(canvas, (255, 214, 90), pts)
        n_steps = len(TUT_STEPS) - 1
        if welcome:
            draw_text(canvas, L("tut.welcome.t"), (box.centerx, box.y + 26), 26, (255, 224, 120), bold=True,
                      center=True)
            ty0 = box.y + 56
        else:
            draw_text(canvas, L("tut.step", max(1, self.i), n_steps), (box.x + 20, box.y + 12), 11,
                      (255, 214, 90), bold=True, shadow=False)
            ty0 = box.y + 34
        for j, ln in enumerate(lines):
            draw_text(canvas, ln, (box.centerx, ty0 + j * 21), 15, (236, 238, 250), center=True, shadow=False)
        y = ty0 + len(lines) * 21 + 6
        if self.step == "codex2":
            # aç / kapat düğmesinin küçük bir örneği
            for k_, lab in enumerate((L("ui.mute_weapon"), L("ui.unmute"))):
                r_ = pygame.Rect(0, 0, 150, 28)
                r_.center = (box.centerx - 84 + k_ * 168, y + 16)
                pygame.draw.rect(canvas, (44, 30, 32) if k_ == 0 else (28, 44, 34), r_, border_radius=8)
                ink_frame(canvas, r_, None, 8, 2)
                draw_text(canvas, _fit_text(lab, 12, r_.w - 12, bold=True), r_.center, 12, TEXT, bold=True,
                          center=True, shadow=False)
            draw_text(canvas, "/", (box.centerx, y + 16), 18, (255, 214, 90), bold=True, center=True)
            y += extra
        if btn:
            label = L("tut.start") if btn == "start" else L("tut.next")
            r_ = pygame.Rect(0, 0, 220, 44)
            r_.midtop = (box.centerx + (-120 if welcome else 0), y + 4)
            hov = r_.collidepoint(mouse_pos)
            pygame.draw.rect(canvas, (80, 170, 115) if hov else (60, 130, 90), r_, border_radius=10)
            ink_frame(canvas, r_, None, 10, 2)
            draw_text(canvas, label, r_.center, 17, WHITE, bold=True, center=True, shadow=False)
            self._btns.append((r_, self._next))
            if welcome:
                r2 = pygame.Rect(0, 0, 220, 44)
                r2.midtop = (box.centerx + 120, y + 4)
                hov2 = r2.collidepoint(mouse_pos)
                pygame.draw.rect(canvas, (110, 80, 84) if hov2 else (84, 60, 64), r2, border_radius=10)
                ink_frame(canvas, r2, None, 10, 2)
                draw_text(canvas, L("tut.skip"), r2.center, 15, WHITE, bold=True, center=True, shadow=False)
                self._btns.append((r2, self._skip))
        if not welcome:
            # her adımda: eğitimi geç
            sk = pygame.Rect(16, VIRTUAL_H - 50, 190, 34)
            if play:
                sk.topleft = (VIRTUAL_W - 206, VIRTUAL_H - 50)
            hov = sk.collidepoint(mouse_pos)
            pygame.draw.rect(canvas, (70, 52, 56) if hov else (46, 34, 38), sk, border_radius=9)
            ink_frame(canvas, sk, None, 9, 1)
            draw_text(canvas, L("tut.skip"), sk.center, 12, (236, 220, 220), bold=True, center=True, shadow=False)
            self._btns.append((sk, self._skip))


# ---- ölüm tekrarı ----
# Koşunun son birkaç saniyesi küçültülüp JPEG olarak yalnızca bellekte tutulur
# (diske hiç yazılmaz). Ölünce sonuç ekranından bir kez izlenebilir; o ekrandan
# çıkınca silinir.
REPLAY_SECS = 8.0
REPLAY_FPS = 12 if MOBILE else 20
# masaüstünde tam 720p (eskiden 960x540 kaydedilip büyütülüyordu: bulanıktı)
REPLAY_SIZE = (640, 360) if MOBILE else (1280, 720)
REPLAY_SLOW_LAST = 1.6           # son kısım ağır çekimde oynar
REPLAY_SLOW = 0.4
REPLAY_HOLD = 1.1                # son karede bekleme
REPLAY_AFTER = 1.4               # 2 kişilikte ölümden sonra kayıt bu kadar sürer
_rp_h = VIRTUAL_H - 68
REPLAY_VIEW = pygame.Rect((VIRTUAL_W - VIRTUAL_W * _rp_h // VIRTUAL_H) // 2, 34, VIRTUAL_W * _rp_h // VIRTUAL_H, _rp_h)
# bu ekranlarda tekrar bellekte kalır, başka yere geçince silinir
REPLAY_KEEP_STATES = frozenset((STATE_PLAY, STATE_PAUSE, STATE_LEVELUP, STATE_CURSE, STATE_MERCHANT,
                                STATE_RUN_SHOP, STATE_GAMEOVER, STATE_NAME_ENTRY, "coop_pause", "coop_end"))
try:
    from collections import deque as _rp_deque
except Exception:
    _rp_deque = None


class DeathReplay:
    def __init__(self):
        self.frames = _rp_deque(maxlen=int(REPLAY_FPS * REPLAY_SECS))
        self.gen = 0
        self.run = None
        self.clock = 0.0
        self.acc = 0.0
        self.after = -1.0
        self.frozen = False
        self.died = False
        self.cause = ""
        self.jpg = True
        self.q = None
        self.th = None
        self.play = None

    def reset(self, run=None):
        self.gen += 1
        self.frames.clear()
        self.run = run
        self.clock = self.acc = 0.0
        self.after = -1.0
        self.frozen = self.died = False
        self.cause = ""
        self.play = None

    def ready(self, run):
        return (self.died and run is not None and run is self.run
                and len(self.frames) >= REPLAY_FPS)

    def capture(self, canvas, dt, run):
        if run is not self.run:
            self.reset(run)
        p = getattr(run, "player", None)
        alive = bool(getattr(p, "alive", True))
        force = False
        if not alive:
            if not self.died:
                force = True              # ölüm karesi hiç atlanmasın
                self.died = True
                self.cause = str(getattr(run, "death_cause", "") or getattr(p, "last_hit_by", "") or "")
                self.after = REPLAY_AFTER
        elif self.died:
            # 2 kişilikte kaldırıldım: önceki ölüm geçersiz, kayıt sürer
            self.died = self.frozen = False
            self.after = -1.0
        if self.frozen:
            return
        if self.after >= 0:
            self.after -= dt
            if self.after < 0:
                self.frozen = True
        self.clock += dt
        self.acc += dt
        # düşük grafikte daha seyrek kare (JPEG sıkıştırma ana döngüyü de yavaşlatıyor)
        iv = 1.0 / (REPLAY_FPS if gfx_level() > 0 else 12)
        if self.acc < iv and not force:
            return
        self.acc = max(0.0, min(self.acc - iv, iv))
        try:
            if canvas.get_size() == REPLAY_SIZE:
                small = canvas.copy()         # aynı boy: küçültme yok (hem net hem ucuz)
            else:
                small = pygame.transform.smoothscale(canvas, REPLAY_SIZE)
        except Exception:
            return
        item = (self.gen, self.clock, small)
        if IS_WEB or _queue is None:
            self._store(item)
            return
        if self.th is None:
            self.q = _queue.Queue(maxsize=6)
            self.th = threading.Thread(target=self._worker, daemon=True)
            self.th.start()
        try:
            self.q.put(item, timeout=0.25) if force else self.q.put_nowait(item)
        except Exception:
            pass                          # yetişemedi: bu kare atlanır

    def _worker(self):
        while True:
            try:
                self._store(self.q.get())
            except Exception:
                pass

    def _store(self, item):
        gen, t, surf = item
        data = surf
        if self.jpg:
            try:
                bio = io.BytesIO()
                pygame.image.save(surf, bio, "replay.jpg")
                data = bio.getvalue()
            except Exception:
                self.jpg = False
        if not self.jpg:
            # JPEG yoksa: daha küçük ham kare (bellek sınırlı kalsın)
            try:
                data = pygame.transform.smoothscale(surf, (REPLAY_SIZE[0] // 2, REPLAY_SIZE[1] // 2))
            except Exception:
                return
        if gen == self.gen:
            self.frames.append((t, data))

    # ---- oynatma ----
    def start(self):
        fr = list(self.frames)
        if fr:
            fr = [f for f in fr if f[0] >= fr[-1][0] - REPLAY_SECS]   # seyrek kayıtta da son 8 sn
        if len(fr) < 2:
            return False
        t0, t1 = fr[0][0], fr[-1][0]
        self.play = {"fr": fr, "t0": t0, "t1": t1, "pos": 0.0, "hold": 0.0, "idx": -1, "img": None,
                     "slow_sfx": False}
        sfx("dash", 0.5, 0.0)
        return True

    def playing(self):
        return self.play is not None

    def stop(self):
        self.play = None

    def _frame_img(self, pl, i):
        if pl["idx"] == i and pl["img"] is not None:
            return pl["img"]
        data = pl["fr"][i][1]
        try:
            if isinstance(data, (bytes, bytearray)):
                img = pygame.image.load(io.BytesIO(data), "replay.jpg")
            else:
                img = data
            # sinema şeritlerinin arasına sığsın (HUD kesilmesin)
            img = pygame.transform.smoothscale(img, REPLAY_VIEW.size)
        except Exception:
            img = pl["img"]
        pl["idx"], pl["img"] = i, img
        return img

    def draw(self, canvas, dt, t):
        """Bir kare oynatır; bitince False döner."""
        pl = self.play
        if pl is None:
            return False
        span = max(0.01, pl["t1"] - pl["t0"])
        slow_from = max(0.0, span - REPLAY_SLOW_LAST)
        slow = pl["pos"] >= slow_from
        if pl["pos"] < span:
            pl["pos"] = min(span, pl["pos"] + dt * (REPLAY_SLOW if slow else 1.0))
        else:
            pl["hold"] += dt
            if pl["hold"] >= REPLAY_HOLD:
                self.play = None
                return False
        if slow and not pl["slow_sfx"]:
            pl["slow_sfx"] = True
            sfx("hurt", 0.35, 0.0)
        # gösterilecek kare: zamanı geçmiş en son kare
        tt = pl["t0"] + pl["pos"]
        fr = pl["fr"]
        lo, hi = 0, len(fr) - 1
        while lo < hi:
            mid = (lo + hi + 1) // 2
            if fr[mid][0] <= tt:
                lo = mid
            else:
                hi = mid - 1
        img = self._frame_img(pl, lo)
        canvas.fill((0, 0, 0))
        if img is not None:
            if pl["hold"] > 0:
                # son kare: renk yavaşça çekilir
                if pl.get("gray") is None:
                    try:
                        pl["gray"] = pygame.transform.grayscale(img)
                    except Exception:
                        pl["gray"] = img
                canvas.blit(img, REPLAY_VIEW.topleft)
                gimg = pl["gray"]
                gimg.set_alpha(int(255 * clamp(pl["hold"] / 0.5, 0.0, 1.0)))
                canvas.blit(gimg, REPLAY_VIEW.topleft)
            else:
                canvas.blit(img, REPLAY_VIEW.topleft)
        bh = REPLAY_VIEW.y
        # son anlarda kızıl kenar
        if slow:
            k = clamp((pl["pos"] - slow_from) / max(0.01, REPLAY_SLOW_LAST), 0.0, 1.0)
            vig = pygame.Surface(REPLAY_VIEW.size, pygame.SRCALPHA)
            for i in range(8):
                q = i / 7.0
                pygame.draw.rect(vig, (120, 0, 16, int((10 + 14 * q) * k)),
                                 vig.get_rect().inflate(-int(70 * q * 6), -int(40 * q * 6)), 36,
                                 border_radius=36)
            canvas.blit(vig, REPLAY_VIEW.topleft)
        # başlık
        blink = 0.5 + 0.5 * math.sin(t * 6)
        circle_aa(canvas, 26, bh // 2, 6, (int(150 + 105 * blink), 40, 50))
        draw_text(canvas, L("rp.title"), (40, bh // 2 - 9), 16, (255, 220, 220), bold=True, shadow=False)
        if slow:
            draw_text(canvas, L("rp.slow"), (VIRTUAL_W / 2, bh // 2 - 8), 14, (255, 150, 150), bold=True,
                      center=True, shadow=False)
        draw_text(canvas, L("rp.skip"), (VIRTUAL_W - 18, bh // 2 - 7), 12, (170, 170, 190), right=True,
                  shadow=False)
        # ilerleme çubuğu (ağır çekim kısmı kızıl)
        bar = pygame.Rect(40, VIRTUAL_H - bh // 2 - 3, VIRTUAL_W - 80, 6)
        pygame.draw.rect(canvas, (50, 46, 58), bar, border_radius=3)
        sx = bar.x + int(bar.w * slow_from / span)
        pygame.draw.rect(canvas, (110, 34, 44), (sx, bar.y, bar.right - sx, bar.h), border_radius=3)
        fw = int(bar.w * clamp(pl["pos"] / span, 0.0, 1.0))
        if fw > 0:
            pygame.draw.rect(canvas, (255, 120, 120) if slow else (230, 230, 245),
                             (bar.x, bar.y, fw, bar.h), border_radius=3)
        left_s = max(0.0, span - pl["pos"])
        draw_text(canvas, "-%.1f" % left_s, (bar.x - 8, bar.y - 5), 11, (170, 170, 190), right=True, shadow=False)
        # son kare: kimin öldürdüğü
        if pl["hold"] > 0 and self.cause:
            a = clamp(pl["hold"] / 0.25, 0.0, 1.0)
            dc = L("ui.killed_by", self.cause)
            w_ = text_width(dc, 20, True) + 60
            r_ = pygame.Rect(0, 0, w_, 44)
            r_.center = (VIRTUAL_W // 2, VIRTUAL_H // 2 + 120)
            panel(canvas, r_, bg=(46, 16, 22), edge=(190, 70, 80), alpha=int(235 * a), radius=14, edge_w=2)
            draw_icon(canvas, r_.x + 24, r_.centery, "skull", (255, 150, 150), 9)
            draw_text(canvas, dc, (r_.x + 42, r_.centery - 11), 20, (255, 200, 200), bold=True, shadow=False)
        return True


# ---- evrimi izle: canlı önizleme ----
# Silahlık > silah > EVRİMİ İZLE. Video dosyası yok: gerçek bir koşu (kaydın
# kopyasıyla) otomatik pilotla oynatılır ve pencereye küçültülüp basılır.
# Kademe seçilince koşu bir alt kademeden başlar, kısa süre sonra evrim
# gerçekleşir (şerit + parlama) ve yeni hâli savaşırken görünür.
EVO_PV_SECS = 14.0              # bir döngünün süresi; sonra baştan
EVO_PV_EVOLVE_AT = 1.6          # döngünün bu anında evrim olur


class EvoPreview:
    def __init__(self, app, key):
        self.app = app
        self.key = key
        self.tier = 1
        self.run = None
        self.pilot = None
        self.t = 0.0
        self.open_t = 0.0
        self.surf = pygame.Surface((VIRTUAL_W, VIRTUAL_H)).convert()
        self.err = False
        self.select(1)

    def select(self, tier):
        self.tier = int(clamp(tier, 0, EVO_TIERS_MAX))
        self._restart()

    def _restart(self):
        key, tier = self.key, self.tier
        try:
            save = _AdSave(self.app.save.data)
            run = RunState(save, self.app.save.equipped_skin_id(), "normal", None)
            run.set_map_theme("stone")
            p = run.player
            show = max(1, tier)
            lvl = evo_level_need(key, show) if key in EVOLUTIONS else 10
            p.weapons = {key: lvl}
            ev = EVOLUTIONS.get(key)
            if ev is not None:
                p.books = {ev[0]: evo_book_need(key, show)}
            p.hp = p.max_hp
            for _ in range(max(0, tier - 1)):
                run.evolve_weapon(key)
            run.evo_banner = None
            run.fx = EffectSystem()
            run.waves._begin_wave(6, 0)
            run.waves.announce_timer = 0.0
            pilot = _TourPilot(run, crowd=16)
            orig = run.update

            def upd(dt, inp, _orig=orig):
                # yalnız silahın kendisi görünsün: ana silah ve bonk susar
                inp["mouse_down"] = False
                inp["bonk_pressed"] = False
                inp["dash_pressed"] = False
                _orig(dt, inp)
            run.update = upd
            self.run, self.pilot = run, pilot
            self.t = 0.0
            self.evolved_now = tier <= 0
            self.err = False
        except Exception as e:
            log_net_error("evo preview", e, ("evo", ""))
            self.run = None
            self.err = True

    def update(self, dt):
        if self.run is None:
            return
        self.t += dt
        try:
            if not self.evolved_now and self.t >= EVO_PV_EVOLVE_AT:
                self.evolved_now = True
                self.run.evolve_weapon(self.key)
            self.pilot.step(min(dt, 1 / 30))
        except Exception as e:
            log_net_error("evo preview", e, ("evo", ""))
            self.run = None
            self.err = True
            return
        if self.t >= EVO_PV_SECS:
            self._restart()

    def draw(self, canvas, rect, t):
        run = self.run
        if run is None:
            pygame.draw.rect(canvas, (14, 10, 12), rect, border_radius=10)
            return
        try:
            draw_run(self.surf, run, t, world_only=True)
        except Exception as e:
            log_net_error("evo preview", e, ("evo", ""))
            self.run = None
            return
        # oyuncunun çevresi biraz yakından (pencere küçük)
        cw, ch = int(rect.w * 1.25), int(rect.h * 1.25)
        px, py = run.world_to_screen(run.player.x, run.player.y)
        src = pygame.Rect(0, 0, cw, ch)
        src.center = (int(px), int(py))
        src.clamp_ip(self.surf.get_rect())
        try:
            img = pygame.transform.smoothscale(self.surf.subsurface(src), rect.size)
        except Exception:
            img = pygame.transform.scale(self.surf.subsurface(src), rect.size)
        canvas.blit(img, rect.topleft)


def _evo_tier_card(canvas, r, key, tier, sel, hov, t):
    """Önizleme penceresinin sağındaki kademe kartı (TEMEL, I, II, III)."""
    w = WEAPON_BY_KEY[key]
    col = evo_color(key, tier) if tier > 0 else tuple(w["color"])
    bg = mix_col((30, 22, 24), col, 0.22 if sel else (0.12 if hov else 0.06))
    pygame.draw.rect(canvas, bg, r, border_radius=12)
    if sel:
        add_glow(canvas, r.centerx, r.centery, r.w * 0.45, col, 0.10 + 0.05 * math.sin(t * 4))
    ink_frame(canvas, r, col if (sel or hov) else scale_col(col, 0.55), 12, 3 if sel else 2)
    b = pygame.Rect(r.x + 12, r.y + 12, 40, 40)
    pygame.draw.rect(canvas, scale_col(col, 0.35), b, border_radius=10)
    ink_frame(canvas, b, col, 10, 2)
    if tier > 0:
        draw_text(canvas, EVO_ROMAN[tier], b.center, 18, lighten(col, 0.35), bold=True, center=True, shadow=False)
    else:
        blit_sigil(canvas, b.centerx, b.centery, 14, key, col)
    tx = b.right + 12
    tw = r.right - tx - 12
    name = evo_name(key, tier) if tier > 0 else w_name(w)
    draw_text(canvas, _fit_text(name, 15, tw, bold=True), (tx, r.y + 10), 15, lighten(col, 0.25), bold=True,
              shadow=False)
    if tier > 0:
        need = L("evo.need", evo_level_need(key, tier), evo_book_name(key), evo_book_need(key, tier))
        draw_text(canvas, _fit_text(need, 11, tw), (tx, r.y + 31), 11, TEXT_DIM, shadow=False)
        perks = evo_perks_for(key, tier)
        line = " + ".join(L("evo.perk." + pk) for pk in perks[-1:])
        yy = r.y + 50
        for ln in wrap_text(line, 11, r.w - 24)[:2]:
            draw_text(canvas, ln, (r.x + 12, yy + 8), 11, (214, 204, 186), shadow=False)
            yy += 14
        icons_x = r.right - 12
        for pk in perks[::-1]:
            draw_icon(canvas, icons_x - 8, r.y + 20, EVO_PERK_ICON[pk], EVO_PERK_COLOR[pk], 7)
            icons_x -= 20
        draw_text(canvas, "x" + ("%.2f" % EVO_TIER_MULT[tier - 1]).rstrip("0").rstrip("."),
                  (r.right - 12, r.bottom - 22), 12, GREEN, bold=True, right=True, shadow=False)
    else:
        draw_text(canvas, L("evo.base_desc"), (tx, r.y + 31), 11, TEXT_DIM, shadow=False)


def replay_button_draw(canvas, rect, mouse_pos, t):
    """Sonuç ekranındaki 'son anları izle' düğmesi (oynat simgeli). Üstünde mi döner."""
    hov = rect.collidepoint(mouse_pos)
    add_glow(canvas, rect.centerx, rect.centery, rect.w * 0.6, (255, 90, 90), 0.08 + 0.04 * math.sin(t * 3))
    panel(canvas, rect, bg=(120, 40, 52) if hov else (92, 30, 40), edge=(255, 130, 130), alpha=245,
          radius=12, edge_w=2)
    cx, cy = rect.x + 26, rect.centery
    pygame.draw.polygon(canvas, (255, 225, 225), [(cx - 6, cy - 9), (cx - 6, cy + 9), (cx + 9, cy)])
    tw = rect.w - 50
    draw_text(canvas, _fit_text(L("rp.watch"), 15, tw, bold=True), (rect.x + 42 + tw / 2, cy), 15,
              (255, 235, 235), bold=True, center=True, shadow=False)
    return hov


