        self.ad_done = False          # reklam sonuna kadar izlendi mi
        self.reward_fx = []           # "+250 ELMAS!" kutlamaları: [x, y, t, miktar]
        self.store_card_t = 0.0       # menüdeki mağaza vitrininin dönme saati
