    def build_menu_buttons(self):
        cx = VIRTUAL_W / 2
        # ---- orta sütun: oyna / skor tablosu / dünya sıralaması (ana akış) ----
        cw, gap = 300, 16
        oyna_h, alt_h = 68, 54
        y0 = 306
        y_oyna = y0
        y_skor = y_oyna + oyna_h + gap
        y_dunya = y_skor + alt_h + gap
        center_bottom = y_dunya + alt_h  # = 306+68+16+54+16+54 = 514

        # ---- yan sütunlar: iki düğme, orta sütunun dört satırına ortalı ----
        # (ayarlar ve arkadaşlar sol üstte küçük kare düğmelerde; kıyafetler
        # skin market'in sekmelerinde; 2 kişilik oyna > harita seçiminde)
        side_w, side_h, side_gap = 236, 60, 20
        block_mid = (y_oyna + center_bottom + 16 + alt_h) / 2.0
        y_side0 = block_mid - side_gap / 2.0 - side_h
        y_side1 = block_mid + side_gap / 2.0
        left_x = cx - cw / 2 - 30 - side_w
        right_x = cx + cw / 2 + 30

        def mb(key, rect, text, fn, **kw):
            b = Button(rect, text, fn, **kw)
            b.mkey = key
            return b

        self.menu_buttons = [
            mb("play", (cx - cw / 2, y_oyna, cw, oyna_h), L("ui.play"), self.open_map_select,
               color=(60, 130, 90), hover_color=(80, 170, 115), text_size=30),
            mb("scores", (cx - cw / 2, y_skor, cw, alt_h), L("ui.scores"), lambda: self.goto(STATE_LEADERBOARD),
               text_size=19),
            mb("world", (cx - cw / 2, y_dunya, cw, alt_h), L("ui.world_lb"), lambda: self.goto(STATE_WORLD_LB),
               color=(50, 80, 120), hover_color=(70, 110, 160), text_size=19),
            # arena ustalığı: koşular arası kalıcı yükseltme.
            mb("mastery", (cx - cw / 2, center_bottom + 16, cw, alt_h), L("ui.mastery"),
               lambda: self.goto(STATE_MASTERY), color=(116, 86, 40), hover_color=(156, 118, 56), text_size=18),
            # silahların kilitleri, ne işe yaradıkları ve istenmeyenleri kapatma
            mb("codex", (left_x, y_side0, side_w, side_h), L("ui.codex"), lambda: self.goto(STATE_WEAPON_CODEX),
               color=(132, 74, 52), hover_color=(178, 100, 70), text_size=16),
            mb("ach", (left_x, y_side1, side_w, side_h), L("ui.achievements"), lambda: self.goto(STATE_ACHIEVEMENTS),
               color=(90, 70, 110), hover_color=(120, 95, 145), text_size=16),
            mb("books", (right_x, y_side0, side_w, side_h), L("ui.books"), lambda: self.goto(STATE_BOOK_MARKET),
               color=(88, 62, 128), hover_color=(120, 88, 168), text_size=16),
            mb("skin", (right_x, y_side1, side_w, side_h), L("ui.skin_market"), lambda: self.goto(STATE_SKIN_MARKET),
               color=(120, 95, 40), hover_color=(160, 125, 55), text_size=16),
        ]
        # sol üstte küçük kare düğmeler: ayarlar, altında arkadaşlar
        self._corner_settings = pygame.Rect(16, 16, 52, 52)
        self._fr_menu_btn = pygame.Rect(16, 78, 52, 52)

    def goto(self, state):
        self.prev_state = self.state
        self.state = state
        if state == STATE_WORLD_LB:
            self.world_lb_t = 0.0        # beliriş animasyonunu başa sar
            self.online.fetch_world_scores_async()
        elif state == STATE_LEADERBOARD:
            self.local_lb_t = 0.0
        elif state == STATE_SKIN_MARKET:
            self.skin_scroll = 0.0
        elif state == STATE_COSMETIC_MARKET:
            self.cosmetic_scroll = 0.0
        elif state == STATE_WEAPON_CODEX:
            self.weapon_scroll = 0.0
            self.weapon_detail = None
        elif state == STATE_BOOK_MARKET:
            self.book_scroll = 0.0
        elif state == STATE_ACHIEVEMENTS:
            self.ach_scroll = 0.0
            self.ach_detail = None
            # Ekrana girerken toplam sayaçlara bağlı başarımları tara.
            self.ach.check_stats()

    def cycle_diff(self):
        i = DIFF_ORDER.index(self.diff)
        self.diff = DIFF_ORDER[(i + 1) % len(DIFF_ORDER)]
        self.save.data.setdefault("settings", {})["difficulty"] = self.diff
        self.save.save()
        sfx("click", 0.6, 0.0)

    def start_run(self):
        # Kuşanılan skin her zaman kayıttan okunur: mağaza, skin market ve menü
        # farklı yerlerden kuşandırabiliyor; tek doğru kaynak kayıttır.
        self.selected_skin = self.save.equipped_skin_id()
        if MOBILE:
            Enemy._ATLAS.clear()      # önceki koşunun (başka haritanın) ortak kareleri
        self.run = RunState(self.save, self.selected_skin, self.diff, self.ach)
        # harita oyna ekranında seçilir (varsayılan taş meydan). gezgin tüccar
        # haritanın bir yerinde belirir ve koşu boyunca kalır; dalga hemen
        # başlar, konuşmak isteğe bağlı.
        self.run.set_map_theme(self.selected_map())
        self.run.roll_quests()
        self.run.spawn_merchant()
        self.merchant_ui.reset()
        self.restart_hold = 0.0
        self.restart_armed = False
        self.state = STATE_PLAY
        audio.set_music("battle")

    def open_map_select(self):
        """oyna: önce harita seçimi; kartlar kapalı (yakınlaşma yok) açılır."""
        self._ms_zoom = None
        self.goto(STATE_MAP_SELECT)

    # ---- kartın büyüyüp ayrıntı penceresine dönüşmesi ----
    def ms_open_zoom(self, theme, idx):
        self._ms_zoom = theme
        self._ms_zoom_from = _ms_card_rect(idx).move(0, -5)
        self._ms_zoom_t0 = self.t
        self._ms_zoom_dir = 1

    def ms_close_zoom(self):
        if getattr(self, "_ms_zoom", None) is None or getattr(self, "_ms_zoom_dir", 1) < 0:
            return
        k = self.ms_zoom_k()
        self._ms_zoom_from = _ms_card_rect(MAP_THEMES.index(self._ms_zoom)).move(0, -5)
        # yarıda kapatılırsa kaldığı yerden geri küçülür
        self._ms_zoom_t0 = self.t - (1.0 - k) * MS_ZOOM_TIME
        self._ms_zoom_dir = -1
        sfx("click", 0.4, 0.0)

    def ms_zoom_k(self):
        """Pencerenin açıklık oranı 0..1 (kapanış bitince yakınlaşma sıfırlanır)."""
        if getattr(self, "_ms_zoom", None) is None:
            return 0.0
        k = clamp((self.t - self._ms_zoom_t0) / MS_ZOOM_TIME, 0.0, 1.0)
        if self._ms_zoom_dir < 0:
            k = 1.0 - k
            if k <= 0.0:
                self._ms_zoom = None
        return k

    def update_map_select(self, dt, mouse_pos, clicked):
        canvas = self.display.canvas
        self.bg.update(dt * 0.2)
        # manzaralar: karede en çok bir tanesi çizilir (takılma olmasın)
        busy = False
        for size in (MS_CARD_SCENE, MS_BIG_SCENE):
            todo = [th for th in MAP_THEMES if (th, size[0], size[1]) not in _MAP_SCENES]
            if todo:
                try:
                    map_scene(todo[0], size[0], size[1])
                except Exception:
                    _MAP_SCENES[(todo[0], size[0], size[1])] = pygame.Surface(size)
                busy = True
                break
        if not busy:
            for th in MAP_THEMES:
                w_ = next((w for w, _a in ms_weapons_for(th)
                           if w is not None and (w["key"], 24, not self.save.owns_weapon(w["key"])) not in _MS_EMB),
                          None)
                if w_ is not None:
                    ms_weapon_emblem(None, 0, 0, 24, w_, not self.save.owns_weapon(w_["key"]))
                    break
        act = draw_map_select(self, canvas, mouse_pos, clicked, self.t)
        # klavye: <- -> seç, enter başla
        keys = pygame.key.get_pressed()
        edge = getattr(self, "_ms_keys", {})
        def hit(kc):
            down = bool(keys[kc])
            was = edge.get(kc, False)
            edge[kc] = down
            return down and not was
        self._ms_keys = edge
        i = MAP_THEMES.index(self.selected_map())
        step = -1 if hit(pygame.K_LEFT) else (1 if hit(pygame.K_RIGHT) else 0)
        if step:
            th = MAP_THEMES[(i + step) % len(MAP_THEMES)]
            for _k in range(len(MAP_THEMES)):
                if map_unlocked(self.save, th):
                    break
                th = MAP_THEMES[(MAP_THEMES.index(th) + step) % len(MAP_THEMES)]
            self.set_selected_map(th)
            if getattr(self, "_ms_zoom", None) is not None and self._ms_zoom_dir > 0:
                self._ms_zoom = th          # açık pencere de yeni haritaya geçer
        elif hit(pygame.K_RETURN) and act is None:
            act = ("start", self.selected_map())
        if act:
            kind, th = act
            if kind == "start" and not map_unlocked(self.save, th):
                self._ms_lock_msg = (map_lock_text(th), self.t + 2.4)
                self._ms_zoom = None
                sfx("error", 0.6, 0.0)
            elif kind == "start":
                self.set_selected_map(th)
                sfx("click", 0.7, 0.0)
                self._ms_zoom = None
                self.start_run()
            elif kind == "coop":
                # 2 kişilik (beta) - yalnız Taş Meydan
                sfx("click", 0.7, 0.0)
                self._ms_zoom = None
                self.open_coop()
            else:
                self._ms_zoom = None
                self.state = STATE_MENU

    def selected_map(self):
        """Oyuncunun seçtiği harita (kayıtta, makineye ait ayar)."""
        m = (self.save.data.get("settings") or {}).get("map", "stone")
        return m if (m in MAP_THEMES and map_unlocked(self.save, m)) else "stone"

    def set_selected_map(self, theme):
        if theme in MAP_THEMES and map_unlocked(self.save, theme):
            self.save.data.setdefault("settings", {})["map"] = theme
            self.save.save()

    def gather_input(self, keys_pressed):
        # Sohbet kutusu açıkken WASD yazıya gider, yürüyüşe gitmez.
        if self.chat.open:
            return {"left": 0, "right": 0, "up": 0, "down": 0}
        # Tuşlar sabit kodlu değil: oyuncunun kendi ataması okunur.
        out = {
            "left": 1 if key_held("left", keys_pressed) else 0,
            "right": 1 if key_held("right", keys_pressed) else 0,
            "up": 1 if key_held("up", keys_pressed) else 0,
            "down": 1 if key_held("down", keys_pressed) else 0,
        }
        # dokunmatik joystick (telefon)
        tmx, tmy = self._touch_move
        if tmx or tmy:
            out["right"] = max(out["right"], tmx) if tmx > 0 else out["right"]
            out["left"] = max(out["left"], -tmx) if tmx < 0 else out["left"]
            out["down"] = max(out["down"], tmy) if tmy > 0 else out["down"]
            out["up"] = max(out["up"], -tmy) if tmy < 0 else out["up"]
        # kontrolcü: sol çubuk.
        if self.pad.ok:
            lx, ly = self.pad.left_stick()
            if lx > 0:
                out["right"] = max(out["right"], lx)
            elif lx < 0:
                out["left"] = max(out["left"], -lx)
            if ly > 0:
                out["down"] = max(out["down"], ly)
            elif ly < 0:
                out["up"] = max(out["up"], -ly)
        return out

    # ---- sohbet / hile kodu ----
    def _chat_can_open(self):
        """Sohbet kutusu bu ekranda açılabilir mi?"""
        if self.state == STATE_PET_DESIGNER and (getattr(self, "pd", None) or {}).get("name_focus"):
            return False
        return self.state not in (STATE_NAME_ENTRY, STATE_LOGIN, STATE_FRIENDS)

    def _chat_submit(self, line):
        """Sohbet kutusuna yazılan satırı işler."""
        if not line:
            return
        cmd = line.strip().lower()
        if cmd == CHAT_CHEAT_CODE:
            self._apply_cheat()
            return
        if cmd == CHAT_SKIN_CODE:
            self._apply_skin_cheat()
            return
        target = parse_unban_cmd(line)
        if target is not None:
            # Komut sessizce sohbet satırına dönmesin: her durumda bir cevap yazılır.
            if not target:
                self.chat.say("kullanım: unban kullanıcıadı", TEXT_DIM)
            elif self._chat_admin_gate():
                self._admin_unban(target)
            return
        give = parse_give_cmd(line)
        # "elmas ..." sıradan bir sohbet sözcüğü de olabilir: eksik/bozuk yazılmış
        # komut yalnızca yöneticiye cevap verir, başkasında normal mesaj kalır.
        if give is not None and (give[0] or self._is_chat_admin()):
            if not give[0]:
                self.chat.say("kullanım: elmas kullanıcıadı miktar  (örn. elmas Ali 5000 ya da 10k)", TEXT_DIM)
            elif self._chat_admin_gate():
                self._admin_give(give[0], give[1])
            return
        co = getattr(self, "coop", None)
        if co is not None and co.role is not None and co.phase in ("lobby", "play", "end") and co.chat_out(line):
            return
        self.chat.say(line, TEXT_DIM)

    def _chat_admin_gate(self):
        """Yönetici komutu çalışabilir mi? Değilse nedenini sohbete yazar."""
        acc = self.account
        if not acc.logged_in() or not acc.token:
            self.chat.say("önce hesabınla giriş yapmalısın", RED)
            return False
        if not self._is_chat_admin():
            self.chat.say("yetkin yok (giriş yapılan hesap: %s)" % (
                (acc.account or {}).get("username") or "?"), RED)
            return False
        return True

    def _admin_give(self, name, amount):
        """Yönetici komutu: bir oyuncuya elmas verir."""
        acc = self.account
        name = "".join(c for c in str(name) if c.isalnum() or c == "_")[:USERNAME_MAX]
        if not name:
            return
        tok = acc.token
        self.chat.say("elmas veriliyor: %s +%s ..." % (name, fmt_num(amount)), TEXT_DIM)

        async def worker():
            try:
                res = await acc._post("/admin/give_gems", {
                    "token": tok, "device": device_id(),
                    "device_legacy": device_id_legacy(),
                    "name": name, "amount": int(amount)}, timeout=30)
            except Exception as e:
                self.chat.say("elmas verilemedi: %s" % acc._err_text(e), RED)
                return
            if not (isinstance(res, dict) and res.get("success")):
                self.chat.say("elmas verilemedi: %s" % (
                    (res or {}).get("error") if isinstance(res, dict) else "?"), RED)
                return
            shown = str(res.get("name") or name)
            self.chat.say("%s: +%s elmas verildi (toplam %s)" % (
                shown, fmt_num(int(res.get("added") or 0)), fmt_num(int(res.get("total") or 0))), GOLD)
            me = str((acc.account or {}).get("username") or "").lower()
            if shown.lower() == me:
                await acc.pull_progress()
        spawn(worker)

    def _is_chat_admin(self):
        acc = self.account
        if not acc.logged_in() or not acc.token:
            return False
        nm = str((acc.account or {}).get("username") or "").strip().lower()
        return nm == CHAT_ADMIN_NAME

    def _admin_unban(self, name):
        """Yönetici komutu: bir oyuncunun dünya sıralaması yasağını kaldırır."""
        acc = self.account
        name = "".join(c for c in str(name) if c.isalnum() or c == "_")[:USERNAME_MAX]
        if not name:
            return
        tok = acc.token
        self.chat.say("ban kaldırılıyor: %s ..." % name, TEXT_DIM)

        async def worker():
            try:
                res = await acc._post("/admin/unban", {
                    "token": tok, "device": device_id(),
                    "device_legacy": device_id_legacy(), "name": name}, timeout=30)
            except Exception as e:
                self.chat.say("ban kaldırılamadı: %s" % acc._err_text(e), RED)
                return
            if not (isinstance(res, dict) and res.get("success")):
                self.chat.say("ban kaldırılamadı: %s" % (
                    (res or {}).get("error") if isinstance(res, dict) else "?"), RED)
                return
            shown = str(res.get("name") or name)
            self.chat.say("%s: ban kaldırıldı" % shown, GREEN)
            me = str((acc.account or {}).get("username") or "").lower()
            if shown.lower() == me:
                self.save.clear_board_ban()
                await acc.pull_progress()
        spawn(worker)

    def _apply_skin_cheat(self):
        """\"skin\" komutu: 4 premium skini açar."""
        added = self.save.unlock_premium_skins()
        self.save.mark_tainted("cheat_code")
        if added:
            self.chat.say("PREMİUM SKİNLER AÇILDI", GOLD)
            self.chat.say(", ".join(added), CYAN)
            self.chat.say("SKİN MARKETİ'nden kuşanabilirsin.", TEXT_DIM)
        else:
            self.chat.say("4 premium skin zaten açıktı.", TEXT_DIM)
        sfx("buy", 0.9, 0.0)

    def _apply_cheat(self):
        """hile kodu: elmas verir ve kilitli bütün içeriği açar."""
        self.save.add_gems(CHAT_CHEAT_GEMS)
        added = self.save.unlock_everything()
        # şaibe en son: damgadan sonra kayda hiçbir şey eklenmez.
        self.save.mark_tainted("cheat_code")
        self.chat.say(f"HİLE KODU KABUL EDİLDİ - +{fmt_num(CHAT_CHEAT_GEMS)} elmas", GOLD)
        self.chat.say("DİKKAT: bu kayıt artık dünya sıralamasına giremez.", RED)
        if self.account.logged_in():
            self.chat.say("Hesabın sunucuda da kalıcı yasaklandı; hile içeriği hesaba yazılmaz.", RED)
        self.chat.say(
            f"açıldı: {added['skins']} skin, {added['cosmetics']} kıyafet, "
            f"{added['pets']} pet, {added['books']} kitap, {added['weapons']} silah", CYAN)
        if not any(added.values()):
            self.chat.say("(kilitli içerik zaten kalmamıştı)", TEXT_DIM)
        sfx("buy", 0.9, 0.0)

    def run_loop(self):
        while self.running:
            self.frame()
        self.save.save()
        pygame.quit()

    async def run_loop_async(self):
        """web / mobil: tarayıcıda ana döngü her karede kontrolü tarayıcıya geri vermek zorunda (await)."""
        perf = bool(web_call("param", "perf", default=""))
        n, t0, worst = 0, time.time(), 0.0
        gc_settle()
        state_prev = self.state
        ema = 0.012
        slow_t = fast_t = 0.0
        half = False             # True: saniyede 30 kare (sabit, düzgün)
        while self.running:
            a = time.perf_counter()
            try:
                self.frame()
            except Exception:
                if not self._frame_error():
                    raise
            work = time.perf_counter() - a
            if self.state != state_prev:
                # Ekran değişti (menü -> oyun gibi): yeni oluşan kalıcı
                # nesneler çöp toplayıcıdan çıkarılır; oyun sırasında "donma"
                # yapan büyük toplamalar böylece olmaz.
                state_prev = self.state
                gc_settle()
                ema = 0.012
            else:
                ema += (min(work, 0.1) - ema) * 0.05
            # kare hızı: telefon bir kareyi ~18 ms'de çizemiyorsa 60 ile 30
            # arasında titremek yerine sabit 30'a geçer (göz titremeyi kasma
            # olarak görür).
            if ema > 0.0185:
                slow_t += work; fast_t = 0.0
                if slow_t > 1.0:
                    half = True
            elif ema < 0.0125:
                fast_t += work + 0.0167; slow_t = 0.0
                if fast_t > 3.0:
                    half = False
            if half and self.state == STATE_PLAY and work < 0.0145:
                # Kare bir tarayıcı karesine sığdı: bir kare daha bekle,
                # böylece her kare tam iki tarayıcı karesi (33 ms) sürer.
                await asyncio.sleep(0)
            hook = getattr(self, "frame_hook", None)
            if hook is not None:
                hook(work, half)
            if perf:
                # ?perf=1 ile açılınca sekme başlığına kare hızı yazılır
                # (yalnız geliştirme/test için).
                worst = max(worst, time.perf_counter() - a)
                n += 1
                if time.time() - t0 >= 1.0:
                    en = len(self.run.enemies) if self.run is not None else 0
                    try:
                        import platform as _pf
                        _pf.window.document.title = "FPS %.0f worst %.0fms state %s en %d" % (
                            n / (time.time() - t0), worst * 1000, self.state, en)
                    except Exception:
                        pass
                    n, t0, worst = 0, time.time(), 0.0
            await asyncio.sleep(0)
        self.save.save()

    def frame(self):
        """Tek bir kare: girdi, güncelleme, çizim, ekrana basma."""
        # Web'de kareyi tarayıcı (requestAnimationFrame) zamanlar; tick burada
        # bekletmesin, yalnızca geçen süreyi ölçsün.
        _pt0 = time.perf_counter()
        dt = min(self.clock.tick(0 if IS_WEB else CFG.get("fps_cap", FPS)) / 1000.0, 1 / 20)
        self._pt1 = time.perf_counter()
        self._pt_wait = (self._pt1 - _pt0) * 1000.0
        self.t += dt
        _UI_FRAME[0] += 1
        self.fps_smpl += (self.clock.get_fps() - self.fps_smpl) * 0.05
        mouse_pos = self.display.virtual_mouse()
        clicked = False
        bonk_pressed = False
        dash_pressed = False
        use_pressed = False      # E - portala gir
        stats_pressed = False    # TAB - istatistik paneli
        wheel_y = 0

        events = pygame.event.get()
        if self.touch is not None:
            events = self.touch.filter_events(events)
        events = list(events) + self._backspace_repeat(dt, events)
        for event in events:
            self.pad.handle_event(event)      # takma/çıkarma
            if event.type == pygame.QUIT:
                self.running = False
                if getattr(self, "coop", None) is not None:
                    try:
                        self.coop.leave()        # arkadaş beklemesin: odadan çık
                    except Exception:
                        pass
            elif event.type in _FOCUS_EVENTS:
                # oyun penceresi öne geldi.
                self.account.note_window_focus(_focus_gained(event))
            elif event.type == pygame.VIDEORESIZE:
                self.display.handle_resize(event.size)
            elif event.type == pygame.MOUSEWHEEL:
                wheel_y += event.y
            elif event.type == pygame.KEYDOWN:
                # sohbet kutusu açıkken bütün tuşlar ona gider: yazarken B ile
                # market açılması, space ile bonk atılması olmaz.
                if self.chat.open:
                    line = self.chat.handle_key(event)
                    if line is not None:
                        self._chat_submit(line)
                    continue
                if (self.state == STATE_COOP_LOBBY and event.key != pygame.K_ESCAPE
                        and self._coop_lobby_key(event)):
                    continue              # oda kodu kutusu
                if event.key == pygame.K_l and self._chat_can_open():
                    self.chat.open_box()
                    sfx("click", 0.5, 0.0)
                elif self.state == STATE_KEYS and getattr(self, "key_waiting", None):
                    # tuş atama bekliyorsa basılan tuş önce buraya gelir:
                    # ESC'ten de önce, yoksa ESC'i atamaya çalışan oyuncu
                    # ekrandan çıkmış olurdu (ESC zaten kilitli ama vazgeçme
                    # yolu da burada).
                    self.handle_keybind_key(event)
                elif event.key == pygame.K_F11:
                    self.display.toggle_fullscreen()
                elif event.key == pygame.K_F3:
                    CFG["fps"] = not CFG["fps"]
                elif event.key == pygame.K_ESCAPE:
                    self.handle_escape()
                elif self.state == STATE_PLAY and key_hit("bonk", event.key):
                    bonk_pressed = True
                elif self.state == STATE_PLAY and key_hit("dash", event.key):
                    dash_pressed = True
                elif self.state == STATE_PLAY and key_hit("use", event.key):
                    use_pressed = True
                elif self.state == STATE_PLAY and key_hit("stats", event.key):
                    stats_pressed = True
                elif self.state == STATE_PLAY and key_hit("map", event.key):
                    # büyük harita aç/kapa. Oyun durmaz; harita yarı saydam bir
                    # karartmanın üstünde durur.
                    self.run.show_map = not self.run.show_map
                    sfx("click", 0.5, 0.0)
                elif self.state == STATE_PLAY and key_hit("shop", event.key):
                    self.run.open_shop()
                    self.state = STATE_RUN_SHOP
                elif self.state == STATE_RUN_SHOP and key_hit("shop", event.key):
                    self.state = STATE_PLAY
                elif self.state == STATE_LOGIN:
                    self.handle_login_key(event)
                elif self.state == STATE_FRIENDS:
                    self.handle_friends_key(event)
                elif self.state == STATE_PET_DESIGNER:
                    self.handle_pet_designer_key(event)
                elif self.state == STATE_NAME_ENTRY:
                    self.handle_name_entry_key(event)
            elif event.type == pygame.MOUSEBUTTONDOWN:
                # Sohbet kutusu açıkken fare tıklaması da oyuna geçmez:
                # yazarken düğmelere basılmasın, ateş edilmesin.
                if self.chat.open:
                    if event.button == 1:
                        self.chat.handle_click(mouse_pos)
                    continue
                if event.button == 1:
                    clicked = True
                elif event.button == 3 and self.state == STATE_PLAY:
                    dash_pressed = True

        # ---- kontrolcü ----
        mpos_now = pygame.mouse.get_pos()
        mouse_moved = mpos_now != self._mouse_prev
        self._mouse_prev = mpos_now
        self.pad.update(dt, mouse_moved)
        PAD_ACTIVE[0] = self.pad.ok and self.pad.active
        if self.pad.active:
            # Menülerde sanal imleç; oyunda nişangah oyuncunun çevresinde sağ
            # çubuğun gösterdiği yöne oturur (aşağıda).
            self.display.pad_cursor = (self.pad.cursor[0], self.pad.cursor[1])
            mouse_pos = self.display.virtual_mouse()
        else:
            self.display.pad_cursor = None

        keys = pygame.key.get_pressed()
        mouse_down = pygame.mouse.get_pressed()[0]

        # ---- dokunmatik (telefon) ----
        self._touch_move = (0.0, 0.0)
        if self.touch is not None:
            tu = self.touch
            if tu.poll_hidden() and self.state == STATE_PLAY:
                self.handle_escape()          # uygulama arka plana gitti: mola
            if tu.take_click():
                clicked = True
            mouse_pos = tu.pointer
            mouse_down = tu.menu_down
            wheel_y += tu.take_wheel(dt)
            if self.state == STATE_PLAY and self.run is not None:
                move, aim, fire, pressed = tu.play_input(self.run)
                self._touch_move = move
                mouse_pos = aim
                mouse_down = fire
                if clicked:
                    # sağ üstteki "⋮" düğmesi / açık istatistik paneli
                    clicked = False
                    if self.run.show_stats or stats_button_rect().inflate(16, 16).collidepoint(tu.pointer):
                        stats_pressed = True
                if "dash" in pressed:
                    dash_pressed = True
                if "bonk" in pressed:
                    bonk_pressed = True
                if "use" in pressed:
                    use_pressed = True
                if "map" in pressed:
                    self.run.show_map = not self.run.show_map
                    sfx("click", 0.5, 0.0)
                if "shop" in pressed:
                    self.run.open_shop()
                    self.state = STATE_RUN_SHOP
                elif "pause" in pressed:
                    self.handle_escape()
        if self.chat.open:
            # Basılı tutulan tuşlar ve fare de kutuya takılır: yön tuşları
            # sohbet geçmişini gezdiriyor, listeyi kaydırmıyor.
            mouse_down = False

        # yön tuşlarıyla (ok tuşları) liste kaydırma - market ekranlarında
        # mouse şart değil
        if not self.chat.open and self.state in (
                STATE_SKIN_MARKET, STATE_COSMETIC_MARKET, STATE_BOOK_MARKET,
                STATE_WEAPON_CODEX,
                STATE_ACHIEVEMENTS):
            if keys[pygame.K_UP]:
                wheel_y += 13.0 * dt
            if keys[pygame.K_DOWN]:
                wheel_y -= 13.0 * dt

        # ---- kontrolcü eylemleri ----
        # Klavye/farenin ürettiği aynı bayraklara yazıyoruz: oyunun geri kalanı
        # pad'in varlığından habersiz kalıyor.
        if self.pad.ok and not self.chat.open:
            pad = self.pad
            if self.state == STATE_PLAY:
                if pad.fire_held():
                    mouse_down = True
                if pad.pressed("x"):
                    bonk_pressed = True
                if pad.pressed("lb") or pad.pressed("rb"):
                    dash_pressed = True
                if pad.pressed("a"):
                    use_pressed = True
                if pad.pressed("back"):
                    stats_pressed = True
                if pad.pressed("y"):
                    self.run.open_shop()
                    self.state = STATE_RUN_SHOP
                if pad.pressed("start"):
                    self.handle_escape()
            elif self.state == STATE_RUN_SHOP and pad.pressed("y"):
                self.state = STATE_PLAY
            else:
                # Menülerde A = tıkla, B/start = geri
                if pad.pressed("a"):
                    clicked = True
                if pad.pressed("b") or pad.pressed("start"):
                    self.handle_escape()
            # Listeler sağ çubukla da kaydırılsın
            if self.state in (STATE_SKIN_MARKET, STATE_COSMETIC_MARKET,
                              STATE_BOOK_MARKET, STATE_WEAPON_CODEX,
                              STATE_ACHIEVEMENTS):
                wheel_y -= pad.right_stick()[1] * 13.0 * dt

        # güvenlik ağı: tek bir karede çıkan hata (çizim / güncelleme) oyunu
        # kapatmaz: kayda yazılır (crash_log.txt), kare atlanır, oyun devam
        # eder.
        menu_timed = False
        if self.touch is not None and self.state != STATE_PLAY:
            if (getattr(self, "_menu_cost", 0.0) > 0.018 and not clicked and not self.touch.fingers
                    and abs(wheel_y) < 1e-6 and not getattr(self, "_menu_skipped", False)):
                self._menu_skipped = True
                self._menu_dt = getattr(self, "_menu_dt", 0.0) + dt
                self.display.present()
                return
            self._menu_skipped = False
            dt = min(0.1, dt + getattr(self, "_menu_dt", 0.0))
            self._menu_dt = 0.0
            menu_timed = True
            _mt0 = time.perf_counter()
        fw = getattr(self, "_font_warm", None)
        if fw is None:
            # yazı tipleri ilk kullanıldıkları karede yükleniyordu (yeni bir
            # pencere ilk açılınca kısa takılma): menüdeyken her karede
            # birkaç boy önceden yüklenir.
            fw = self._font_warm = [(sz, b_) for sz in range(44, 9, -1) for b_ in (True, False)]
        if fw and self.state != STATE_PLAY:
            for _ in range(3):
                if fw:
                    get_font(*fw.pop())
        if getattr(self.account, "just_registered", False):
            # yeni kayıt olan herkese eğitim (bu cihazda daha önce oynamış olsa da)
            self.account.just_registered = False
            if self.tut is None and not getattr(self, "shadow", False):
                self.tut = Tutorial(self)
        self.social.tick(dt)
        if self.social.take_click(mouse_pos, clicked):
            clicked = False
        tut = self.tut
        # 2 kişilik açıkken eğitim bekler (adımları tek kişilik oyuna göre)
        tut_on = tut is not None and tut.active and self.coop is None
        if tut_on and tut.take_click(mouse_pos, clicked):
            clicked = False
        try:
            if self.state == STATE_MENU: self.update_menu(dt, mouse_pos, clicked)
            elif self.state == STATE_PLAY: self.update_play(dt, keys, mouse_pos, mouse_down, bonk_pressed,
                                                            dash_pressed, use_pressed, clicked, stats_pressed)
            elif self.state == STATE_PAUSE: self.update_pause(dt, mouse_pos, clicked)
            elif self.state == STATE_LEVELUP: self.update_levelup(dt, mouse_pos, clicked)
            elif self.state == STATE_CURSE: self.update_curse(dt, mouse_pos, clicked)
            elif self.state == STATE_MERCHANT: self.update_merchant(dt, mouse_pos, clicked)
            elif self.state == STATE_MAP_SELECT: self.update_map_select(dt, mouse_pos, clicked)
            elif self.state == STATE_RUN_SHOP: self.update_run_shop(dt, mouse_pos, clicked)
            elif self.state == STATE_GAMEOVER: self.update_gameover(dt, mouse_pos, clicked)
            elif self.state == STATE_SKIN_MARKET: self.update_skin_market(dt, mouse_pos, clicked, wheel_y)
            elif self.state == STATE_SKIN_DETAIL: self.update_skin_detail(dt, mouse_pos, clicked)
            elif self.state == STATE_COSMETIC_MARKET: self.update_cosmetic_market(dt, mouse_pos, clicked, wheel_y)
            elif self.state == STATE_BOOK_MARKET: self.update_book_market(dt, mouse_pos, clicked, wheel_y)
            elif self.state == STATE_WEAPON_CODEX: self.update_weapon_codex(dt, mouse_pos, clicked, wheel_y)
            elif self.state == STATE_LEADERBOARD: self.update_leaderboard(dt, mouse_pos, clicked)
            elif self.state == STATE_WORLD_LB: self.update_world_leaderboard(dt, mouse_pos, clicked)
            elif self.state == STATE_SNOW: self.update_snow(dt, mouse_pos, clicked)
            elif self.state == STATE_NAME_ENTRY: self.update_name_entry(dt, mouse_pos, clicked)
            elif self.state == STATE_HOW_TO: self.update_howto(dt, mouse_pos, clicked)
            elif self.state == STATE_SETTINGS: self.update_settings(dt, mouse_pos, clicked)
            elif self.state == STATE_ACHIEVEMENTS: self.update_achievements(dt, mouse_pos, clicked, wheel_y)
            elif self.state == STATE_GEM_STORE: self.update_gem_store(dt, mouse_pos, clicked)
            elif self.state == STATE_LOGIN: self.update_login(dt, mouse_pos, clicked)
            elif self.state == STATE_MASTERY: self.update_mastery(dt, mouse_pos, clicked)
            elif self.state == STATE_KEYS: self.update_keys(dt, mouse_pos, clicked)
            elif self.state == STATE_PET_DESIGNER: self.update_pet_designer(dt, mouse_pos, clicked, wheel_y)
            elif self.state == STATE_COOP_LOBBY: self.update_coop_lobby(dt, mouse_pos, clicked)
            elif self.state == STATE_COOP_PAUSE: self.update_coop_pause(dt, mouse_pos, clicked)
            elif self.state == STATE_COOP_END: self.update_coop_end(dt, mouse_pos, clicked)
            elif self.state == STATE_FRIENDS: self.update_friends(dt, mouse_pos, clicked, wheel_y)

            rp = self.replay
            if rp.run is not None and self.state not in REPLAY_KEEP_STATES:
                rp.reset(None)                 # sonuç ekranından çıkıldı: tekrar silinir
        except Exception:
            if not self._frame_error():
                raise
        if menu_timed:
            mc = time.perf_counter() - _mt0
            self._menu_cost = getattr(self, "_menu_cost", 0.0) * 0.9 + mc * 0.1

        if self.tut is not None:
            if self.tut.active and self.coop is None:
                try:
                    self.tut.draw(self.display.canvas, dt, mouse_pos)
                except Exception as e:
                    log_net_error("tutorial", e, ("tut", ""))
                    self.tut.finish()
            if not self.tut.active:
                self.tut = None
        try:
            self.social.draw_overlay(self.display.canvas, mouse_pos, self.t)
        except Exception as e:
            log_net_error("social overlay", e, ("social", ""))
        # Sohbet en üstte durur: hangi ekranda olursak olalım aynı yerde, sol
        # altta görünsün.
        self.chat.update(dt)
        self.chat.draw(self.display.canvas)

        if CFG["fps"]:
            draw_text(self.display.canvas, f"{self.fps_smpl:0.0f} FPS", (VIRTUAL_W - 10, VIRTUAL_H - 26),
                      13, (120, 255, 150), bold=True, right=True, shadow=True)
            _ft = getattr(self, "_ft", None)
            if _ft:
                # bekle: FPS sınırı/vsync bekleyişi | işle: oyun+çizim | flip: ekrana verme
                _msg = f"bekle {_ft[0]:.1f}  isle {_ft[1]:.1f}  flip {_ft[2]:.1f} ms"
                _co = getattr(self, "coop", None)
                _cm = getattr(_co, "_coop_ms", None) if _co is not None else None
                if _cm:
                    _msg += f"  | 2kisi: guncelle {_cm[0]:.1f}  paket {_cm[1]:.1f} ms"
                draw_text(self.display.canvas, _msg, (VIRTUAL_W - 10, VIRTUAL_H - 44),
                          12, (150, 220, 255), right=True, shadow=True)

        # ---- imleç: her şeyin üstünde, tek yerde ----
        # Oyun sırasında nişangah, geri kalan her ekranda menü oku.
        if self.touch is not None:
            # Telefonda imleç yok; klavye açıksa yazılan metin üstte görünür.
            self.touch.draw_keyboard_bar(self.display.canvas)
            self.touch.end_frame()
        elif self.state == STATE_PLAY and self.run is not None and self.run.player.alive:
            draw_cursor(self.display.canvas, mouse_pos, "aim", self.t,
                        hot=mouse_down)
        else:
            draw_cursor(self.display.canvas, mouse_pos, "ui", self.t)

        audio.update()
        self.steam.run_callbacks()
        if self.run is not None and self.state == STATE_PLAY:
            self.display.fill_strips("play")
        elif self.run is not None and (self.state in RUN_OVERLAY_STATES or self.state == STATE_COOP_PAUSE):
            self.display.fill_strips("run")
        else:
            self.display.fill_strips("menu")
        _pt2 = time.perf_counter()
        self.display.present()
        _pt3 = time.perf_counter()
        _ft = getattr(self, "_ft", None)
        _cur = (self._pt_wait, (_pt2 - self._pt1) * 1000.0, (_pt3 - _pt2) * 1000.0)
        if _ft is None:
            self._ft = list(_cur)
        else:
            for _i in range(3):
                _ft[_i] += (_cur[_i] - _ft[_i]) * 0.05

    def _frame_error(self):
        """Bir karede yakalanan hatayı kaydeder."""
        import traceback
        now = time.time()
        times = [x for x in getattr(self, "_err_times", []) if now - x < 10.0]
        times.append(now)
        self._err_times = times
        if IS_WEB:
            print("KARE HATASI:", traceback.format_exc())
        try:
            path = os.path.join(get_save_dir(), "crash_log.txt")
            if os.path.exists(path) and os.path.getsize(path) > 512 * 1024:
                os.replace(path, path + ".old")
            with open(path, "a", encoding="utf-8") as f:
                f.write("\n=== %s  v%s  durum=%s ===\n" % (
                    time.strftime("%Y-%m-%d %H:%M:%S"), GAME_VERSION, self.state))
                f.write(traceback.format_exc())
        except Exception:
            pass
        # 10 saniyede 40'tan fazla hata: durum bozuk, devam etmek anlamsız
        return len(times) <= 40

    # ---- kartopu savaşı ----
    def _snow_open(self):
        self.snow = SnowEvent(self)
        self.state = STATE_SNOW
        sfx("click", 0.8, 0.0)

    def _snow_leave(self):
        self.snow = None
        self.state = STATE_MENU

    def _draw_event_snowman(self, canvas, mouse_pos, clicked):
        """Sol alttaki kardan adam: etkinliğin kapısı."""
        if self.splash_t < self.SPLASH_TIME:
            return
        if self.xmas:
            tx, ty = self.xmas._tree_layout()
            mx, my = tx + 92, ty
        else:
            mx, my = 70, VIRTUAL_H - 14
            for (oy, rr) in ((-14, 15), (-38, 11), (-56, 8)):
                circle_aa(canvas, mx + 1, my + oy + 2, rr, (190, 204, 230))
                circle_aa(canvas, mx, my + oy, rr, (246, 250, 255))
            circle_aa(canvas, mx - 3, my - 58, 1.4, (30, 30, 36))
            circle_aa(canvas, mx + 3, my - 58, 1.4, (30, 30, 36))
            poly_aa(canvas, [(mx, my - 56), (mx, my - 53), (mx + 10, my - 54)], (240, 130, 50))
            pygame.draw.rect(canvas, (28, 28, 34), pygame.Rect(int(mx - 6), int(my - 77), 12, 11))
        hit = pygame.Rect(int(mx - 26), int(my - 84), 52, 88)
        hov = hit.collidepoint(mouse_pos)
        left = self.rewards.snow_left()
        bob = math.sin(self.t * 3.0) * 3
        txt = L("snow.badge", left)
        w = text_width(txt, 11, True) + 18
        br = pygame.Rect(0, 0, w, 22)
        br.midbottom = (mx, my - 88 + bob)
        add_glow(canvas, br.centerx, br.centery, 50, (150, 210, 255), 0.25 + (0.2 if hov else 0.0))
        panel(canvas, br, bg=(30, 60, 110) if left else (60, 60, 70), edge=(190, 230, 255),
              alpha=240, radius=11, edge_w=2 if hov else 1)
        draw_text(canvas, txt, br.center, 11, WHITE, bold=True, center=True, shadow=False)
        pygame.draw.polygon(canvas, (190, 230, 255), [(br.centerx - 5, br.bottom), (br.centerx + 5, br.bottom),
                                                      (br.centerx, br.bottom + 6)])
        if hov:
            ring_aa(canvas, mx, my - 36, 44, (190, 230, 255), 2)
            if clicked:
                self._snow_open()

    def update_snow(self, dt, mouse_pos, clicked):
        canvas = self.display.canvas
        sn = getattr(self, "snow", None)
        if sn is None:
            self.state = STATE_MENU
            return
        keys = pygame.key.get_pressed()
        if sn.stage in ("intro", "wait"):
            sn.draw_intro(canvas, mouse_pos, clicked, dt, self.t)
            return
        sn.update(dt, mouse_pos, clicked and sn.stage == "play", keys)
        sn.draw(canvas, mouse_pos, self.t)
        if sn.stage in ("claim", "result"):
            sn.draw_result(canvas, mouse_pos, clicked, dt, self.t)

    def handle_escape(self):
        # Reklam penceresi açıksa ESC yalnızca onu kapatır (sonuna kadar
        # izlendiyse ödül yine verilir).
        if self.ad_play is not None:
            self._ad_finish(True)
            return
        if self.replay.playing():
            self.replay.stop()
            return
        if self.state == STATE_LOGIN and self.contact is not None:
            self.contact = None
            return
        if self.state == STATE_MENU and self.splash_t < self.SPLASH_TIME:
            self.splash_t = max(self.splash_t, self.SPLASH_TIME - self.SPLASH_FADE)
            return
        if self.state == STATE_PLAY and self.coop is not None and self.coop.phase == "play":
            self.state = STATE_COOP_PAUSE         # 2 kişilik: oyun durmaz
        elif self.state == STATE_COOP_PAUSE: self.state = STATE_PLAY
        elif self.state == STATE_FRIENDS:
            if getattr(self, "_clb_detail", None) is not None:
                self._clb_detail = None
            else:
                self.state = getattr(self, "fr_back", STATE_MENU) or STATE_MENU
                if self.state == STATE_COOP_LOBBY and self.coop is None:
                    self.open_coop()
        elif self.state == STATE_COOP_LOBBY and getattr(self, "_clb_detail", None) is not None:
            self._clb_detail = None
        elif self.state == STATE_COOP_LOBBY:
            if self.coop is not None:
                self.coop.leave()
            self.coop = None
            self.state = getattr(self, "coop_back", STATE_MAP_SELECT) or STATE_MAP_SELECT
        elif self.state == STATE_COOP_END:
            if self.coop is not None:
                self.coop.leave()
            self.coop = None
            self.run = None
            self.state = STATE_MENU
        elif self.state == STATE_PLAY: self.state = STATE_PAUSE
        elif self.state == STATE_MAP_SELECT:
            # açık ayrıntı penceresi önce kapanır, sonra menüye dönülür
            if getattr(self, "_ms_zoom", None) is not None:
                self.ms_close_zoom()
            else:
                self.state = STATE_MENU
        elif self.state == STATE_MERCHANT:
            # Mağaradan çık: tüccar yerinde durur, sonra yine konuşulabilir.
            # (choose_oath(None): 2 kişilikte konuk bunu ev sahibine de
            # bildirir)
            self.run.choose_oath(None)
            self.state = STATE_PLAY
        elif self.state == STATE_PAUSE: self.resume_run()
        elif self.state == STATE_RUN_SHOP: self.state = STATE_PLAY
        elif self.state == STATE_CURSE:
            self.run.decline_curse()
            self.state = STATE_PLAY
        elif self.state == STATE_SKIN_DETAIL: self.state = STATE_SKIN_MARKET
        elif self.state == STATE_WEAPON_CODEX and getattr(self, "evo_pv", None) is not None:
            self.close_evo_viewer()
        elif self.state == STATE_WEAPON_CODEX and self.weapon_detail:
            self.weapon_detail = None
        elif self.state == STATE_BOOK_MARKET and self.book_detail:
            self.book_detail = None
        elif self.state == STATE_ACHIEVEMENTS and self.ach_detail:
            self.ach_detail = None
        elif self.state == STATE_HOW_TO and self.prev_state == STATE_SETTINGS:
            self.state = STATE_SETTINGS         # Ayarlar > Nasıl Oynanır'dan geri dön
        elif self.state == STATE_KEYS:
            # tuşlar ekranı ayarlar'dan açılıyor: ESC oraya döner.
            self.state = STATE_SETTINGS
        elif self.state == STATE_PET_DESIGNER:
            pd = getattr(self, "pd", {}) or {}
            if pd.get("name_focus"):
                pd["name_focus"] = False
            elif pd.get("confirm"):
                pd["confirm"] = False
            elif self.purchase.waiting():
                pass
            elif pd.get("stage") == "design":
                self._pd_back_to_pick()
            else:
                self._pd_leave()
        elif self.state == STATE_WORLD_LB and getattr(self, "_lb_detail", None) is not None:
            self._lb_detail = None
        elif self.state == STATE_SNOW:
            sn = getattr(self, "snow", None)
            if sn is None or sn.stage in ("intro", "result"):
                self._snow_leave()
        elif self.state in (STATE_SKIN_MARKET, STATE_COSMETIC_MARKET, STATE_BOOK_MARKET,
                            STATE_WEAPON_CODEX,
                            STATE_LEADERBOARD, STATE_WORLD_LB, STATE_GEM_STORE,
                            STATE_HOW_TO, STATE_ACHIEVEMENTS, STATE_SETTINGS,
                            STATE_MASTERY, STATE_LOGIN):
            self.state = STATE_MENU
        elif self.state == STATE_NAME_ENTRY:
            # ESC = "adı böyle bırak, devam et". Oyuncuyu bu ekranda kilitli
            # tutmuyoruz; ad boşsa zaten "İsimsiz" yazılıyor.
            if self.run is not None:
                self.confirm_name_entry()
            else:
                self.state = STATE_MENU
        elif self.state == STATE_GAMEOVER:
            pass

    # ---- oynanış ----
    def _draw_run_frame(self, canvas, aim_pos=None, offset=(0, 0)):
        """Koşuyu ekrana çizer (performans)."""
        if self.state != STATE_PLAY and self.run is not None:
            # Pencere açıkken arkadaki dünya karartılmış durur: her karede
            # baştan çizmek pencereyi takır takır yapıyordu. Tek kişilikte
            # oyun durduğu için bir kez, 2 kişilikte (oyun akıyor) saniyede
            # MENU_WORLD_HZ kez çizilir; arada kopyası basılır.
            c = getattr(self, "_menu_world", None)
            live = getattr(self.run, "is_coop", False)
            now = self.t
            if (c is not None and c[0] is self.run and c[1] == self.state and now - c[3] < 0.25
                    and (not live or now - c[2] < 1.0 / MENU_WORLD_HZ)):
                canvas.blit(c[4], (0, 0))
                c[3] = now
                return
            self._draw_run_frame_now(canvas, aim_pos, offset)
            if c is not None and c[4].get_size() == canvas.get_size():
                sfc = c[4]
                sfc.blit(canvas, (0, 0))
            else:
                sfc = canvas.copy()
            self._menu_world = [self.run, self.state, now, now, sfc]
            return
        self._menu_world = None
        self._draw_run_frame_now(canvas, aim_pos, offset)

    def _draw_run_frame_now(self, canvas, aim_pos=None, offset=(0, 0)):
        bgf = self.bg.static_frame()
        ox, oy = (int(offset[0]), int(offset[1])) if offset else (0, 0)
        if ox or oy:
            canvas.blit(bgf, (0, 0))          # sarsıntıda kenarlar açılır
        else:
            # Dünya VIEW_RECT'i tamamen kaplıyor: zeminden yalnızca kenar
            # şeritleri basılır.
            v = VIEW_RECT
            for rr in ((0, 0, VIRTUAL_W, v.y), (0, v.bottom, VIRTUAL_W, VIRTUAL_H - v.bottom),
                       (0, v.y, v.x, v.h), (v.right, v.y, VIRTUAL_W - v.right, v.h)):
                if rr[2] > 0 and rr[3] > 0:
                    canvas.blit(bgf, rr[:2], rr)
        coop = getattr(self.run, "is_coop", False)
        # pencere (duraklatma, mağara, market...) açıkken arkadaki koşu
        # karartılır: üstteki duyuru notları pencerenin yazısına karışmasın
        self.run._overlay = self.state != STATE_PLAY
        if coop:
            # 2 kişilik: kendi gözümden, iki oyuncunun silahları birlikte
            self.run.view_begin(1 if self.run.is_guest else 0)
        try:
            draw_run(canvas, self.run, self.t, aim_pos=aim_pos, shake=(ox, oy))
        finally:
            if coop:
                self.run.view_end()
        rf = getattr(self.run, "record_flash", -1.0)
        if rf >= 0:
            draw_stamp(canvas, L("ui.new_record"), rf, GOLD, y=190, life=2.6)

    def update_play(self, dt, keys, mouse_pos, mouse_down, bonk_pressed, dash_pressed,
                    use_pressed=False, clicked=False, stats_pressed=False):
        if self.coop is not None and self.coop.phase == "play" and self.run is self.coop.run:
            return self._coop_play(dt, keys, mouse_pos, mouse_down, bonk_pressed, dash_pressed,
                                   use_pressed, clicked, stats_pressed)
        # ---- istatistik paneli (sağ üstteki "⋮") ----
        btn = stats_button_rect()
        over_ui = btn.collidepoint(mouse_pos)
        if self.run.show_stats:
            groups = player_stat_groups(self.run.player, self.run)
            n_rows = sum(len(r) for _g, r in groups)
            over_ui = over_ui or stats_panel_rect(n_rows, len(groups)).collidepoint(mouse_pos)
        if stats_pressed or (clicked and btn.collidepoint(mouse_pos)):
            self.run.show_stats = not self.run.show_stats
            sfx("click", 0.5, 0.0)
        if over_ui:
            mouse_down = False

        input_state = self.gather_input(keys)
        input_state["mouse_down"] = mouse_down
        input_state["bonk_pressed"] = bonk_pressed
        input_state["dash_pressed"] = dash_pressed
        input_state["use_pressed"] = use_pressed
        # Fare ekran koordinatında gelir.
        if self.pad.ok:
            rx, ry = self.pad.right_stick()
            if abs(rx) + abs(ry) > 0.02:
                psx, psy = self.run.world_to_screen(self.run.player.x, self.run.player.y)
                l = math.hypot(rx, ry) or 1.0
                mouse_pos = (psx + rx / l * PAD_AIM_RADIUS,
                             psy + ry / l * PAD_AIM_RADIUS)
                self.pad.cursor[0], self.pad.cursor[1] = mouse_pos
        input_state["aim_sx"] = mouse_pos[0]
        input_state["aim_sy"] = mouse_pos[1]
        aim_wx, aim_wy = self.run.screen_to_world(mouse_pos[0], mouse_pos[1])
        input_state["aim_x"] = aim_wx
        input_state["aim_y"] = aim_wy
        # sohbet kutusu açıkken koşu donar.
        self.run.update(0.0 if self.chat.open else dt, input_state)
        self.bg.update(dt * 0.4)

        offset = self.run.fx.get_shake_offset()
        canvas = self.display.canvas
        self._draw_run_frame(canvas, aim_pos=mouse_pos, offset=offset)
        if self.state == STATE_PLAY:
            self.replay.capture(canvas, dt, self.run)
        if self.touch is not None and self.state == STATE_PLAY:
            self.touch.draw_play(canvas, self.run, self.t)

        # hızlı yeniden başlat: R (ayarlanabilir) basılı tutulursa koşu yeni
        # bir harita ve yeni bir elle baştan kurulur.
        try:
            held = (not self.chat.open) and key_held("restart", keys)
        except Exception:
            held = False
        if not held or self.run.game_over:
            self.restart_armed = not held
            self.restart_hold = 0.0
        elif self.restart_armed:
            self.restart_hold += dt
            draw_restart_hold(canvas, self.restart_hold / RESTART_HOLD, self.t)
            if self.restart_hold >= RESTART_HOLD:
                self.restart_hold = 0.0
                sfx("dash", 0.7, 0.1)
                self.start_run()
                return

        if self.run.want_open_shop:
            self.run.want_open_shop = False
            self.run.open_shop()
            self.state = STATE_RUN_SHOP
            return

        if self.run.pending_levelups > 0 and not self.run.levelup_choices:
            self.run.start_levelup_choice()
            if self.run.levelup_choices:
                self.state = STATE_LEVELUP
            else:
                # Verilecek hiçbir şey kalmadıysa seviye ekranı açılmaz; yoksa
                # oyun boş bir ekranda kilitlenirdi.
                self.run.pending_levelups = 0

        # lanetli sandık açıldı: teklif ekranı (oyun durur)
        if self.state == STATE_PLAY and self.run.curse_offers and not self.run.game_over:
            self.state = STATE_CURSE
        # gezgin tüccar ile konuşuldu: mağara ekranı (oyun durur)
        if self.state == STATE_PLAY and self.run.merchant_open and not self.run.game_over:
            self.merchant_ui.reset()
            self.state = STATE_MERCHANT

        if self.run.game_over:
            self.pending_board_rank = -1
            self.online_submit_status = None
            # Doğrulanamayan koşu yerel tabloya da yazılmaz: isim ekranı hiç
            # açılmaz, oyuncu doğrudan sonuç ekranına gider.
            if self.run.run_is_clean() and self.save.qualifies_for_board(self.run.score):
                # Girişliyse isim sorulmaz: hesabın adı neyse odur, hem yerel
                # tabloda hem dünya sıralamasında. Ad bir kez seçilir ve
                # değişmez.
                if self.account.logged_in() and not self.account.needs_username():
                    self.name_input = self.account.display_name()
                    self.confirm_name_entry()
                else:
                    self.state = STATE_NAME_ENTRY
            else:
                self._maybe_submit_online()
                self.state = STATE_GAMEOVER
            audio.set_music("menu")

    def update_levelup(self, dt, mouse_pos, clicked):
        self.restart_armed = False
        if self.coop is not None:
            self._coop_overlay_tick(dt)       # 2 kişilik: oyun durmaz
            if self.state == STATE_COOP_END:
                return
        if not self.run.levelup_choices:
            # el boşaldı (2 kişilikte arkadaş son silahı aldı vb.): ekranda kilitlenme
            self.state = STATE_PLAY
            return
        canvas = self.display.canvas
        self._draw_run_frame(canvas)
        self.levelup_ui.rebuild(self.run.levelup_choices)
        act = self.levelup_ui.draw_and_handle(canvas, self.run, mouse_pos, clicked, self.t)
        if act:
            kind, idx = act
            if kind == "pick":
                self.run.choose_levelup(idx)
            elif kind == "reroll":
                ok, msg = self.run.reroll_levelup()
                self.levelup_ui.say(msg)
            elif kind == "skip":
                ok, msg = self.run.skip_levelup()
                self.levelup_ui.say(msg)
            if self.run.pending_levelups <= 0 or not self.run.levelup_choices:
                # Teklif üretilemediyse (her şey tavanda) ekranda kilitlenme.
                self.run.pending_levelups = max(0, self.run.pending_levelups)
                if not self.run.levelup_choices:
                    self.run.pending_levelups = 0
                self.state = STATE_PLAY

    def update_curse(self, dt, mouse_pos, clicked):
        self.restart_armed = False
        if self.coop is not None:
            self._coop_overlay_tick(dt)       # 2 kişilik: oyun durmaz
            if self.state == STATE_COOP_END:
                return
        """Lanetli sandık teklif ekranı."""
        canvas = self.display.canvas
        self._draw_run_frame(canvas)
        if not self.run.curse_offers:
            self.state = STATE_PLAY
            return
        self.curse_ui.rebuild(self.run.curse_offers)
        act = self.curse_ui.draw_and_handle(canvas, self.run, mouse_pos, clicked, self.t)
        if act:
            kind, idx = act
            if kind == "pick":
                self.run.accept_curse(idx)
            else:
                self.run.decline_curse()
                sfx("click", 0.6, 0.0)
            self.state = STATE_PLAY

    def _toggle_auto_aim(self):
        """Telefon: sağ tarafa dokunulmazken en yakın düşmana kendiliğinden ateş etme."""
        st = self.save.data.setdefault("settings", {})
        st["auto_aim"] = not CFG.get("auto_aim", True)
        CFG["auto_aim"] = st["auto_aim"]
        self.save.save()

    def resume_run(self):
        """Moladan oyuna dön."""
        self.state = STATE_PLAY

    def update_merchant(self, dt, mouse_pos, clicked):
        """Tüccarın mağarası: konuşma -> yemin kartları -> oyun."""
        self.restart_armed = False
        if self.coop is not None:
            self._coop_overlay_tick(dt)       # 2 kişilik: oyun durmaz
            if self.state == STATE_COOP_END:
                return
        canvas = self.display.canvas
        run = self.run
        if not run.merchant_open:
            self.state = STATE_PLAY
            return
        act = self.merchant_ui.draw_and_handle(canvas, run, mouse_pos, clicked, self.t)
        if not act:
            return
        kind, val = act
        if kind == "reroll":
            ok, _why = run.merchant_reroll()
            if ok:
                sfx("coin", 0.9, 0.0)
                sfx("levelup", 0.35, 0.2)
                best = max(t_ for _k, t_ in run.merchant_hand)
                p = run.player
                run.fx.popup(p.x, p.y - 90, L("m.rerolled"), rarity_color(best), 22, life=1.6)
            else:
                sfx("error", 0.6, 0.0)
            return                         # tüccar ekranında kal
        if kind == "oath" and val:
            key, tier = val
            run.choose_oath(key, tier)
            sfx("levelup", 0.6, 0.1)
            if tier >= 3:
                sfx("second", 0.7, 0.0)
            p = run.player
            run.fx.popup(p.x, p.y - 90, "%s - %s" % (L("oath.%s.name" % key), rarity_name(tier)),
                         rarity_color(tier), 20 + tier, life=2.2)
        else:
            run.choose_oath(None)
            sfx("click", 0.6, 0.0)
        self.state = STATE_PLAY

    def update_run_shop(self, dt, mouse_pos, clicked):
        if self.coop is not None:
            self._coop_overlay_tick(dt)       # 2 kişilik: oyun durmaz
            if self.state == STATE_COOP_END:
                return
        canvas = self.display.canvas
        self._draw_run_frame(canvas)
        close = self.shop_ui.draw_and_handle(canvas, self.run, mouse_pos, clicked, self.t)
        if close:
            self.state = STATE_PLAY

    def _fx_slider(self, canvas, rect, mouse_pos, down):
        """Eşya efekti çubuğu: %0 ile %100 arasında sürüklenerek ayarlanır."""
        pct = weapon_fx_pct()
        hov = rect.collidepoint(mouse_pos)
        col = GREEN if pct >= 70 else (ORANGE if pct >= 25 else RED)
        panel(canvas, rect, bg=(64, 46, 48) if hov else (46, 33, 34),
              edge=(128, 104, 106) if hov else PANEL_EDGE, alpha=242, radius=10, edge_w=2)
        draw_text(canvas, L("ui.fx_level"), (rect.x + 16, rect.y + 7), 12, TEXT_DIM,
                  shadow=False)
        draw_text(canvas, fmt_pct(pct), (rect.right - 16, rect.y + 6), 16, col,
                  bold=True, right=True, shadow=False)
        br = pygame.Rect(rect.x + 16, rect.y + 27, rect.w - 32, 11)
        draw_bar(canvas, br, pct / 100.0, col, radius=5)
        # tutamak: çubuğun dolu ucunda küçük bir madalyon
        hx = br.x + br.w * (pct / 100.0)
        pygame.draw.circle(canvas, (23, 17, 18), (int(hx), br.centery), 7)
        pygame.draw.circle(canvas, col, (int(hx), br.centery), 7, 2)
        if down and br.inflate(26, 26).collidepoint(mouse_pos):
            set_weapon_fx_pct((mouse_pos[0] - br.x) / max(1, br.w) * 100.0)
            self._fx_dirty = True
        if getattr(self, "_fx_dirty", False) and not down:
            self._fx_dirty = False
            self.save.data.setdefault("settings", {})["weapon_fx"] = weapon_fx_pct()
            self.save.save()

    def _hud_slider(self, canvas, rect, mouse_pos, down):
        """sol üst panel: silah/kitap şeridinin boyutu, %50-150."""
        pct = hud_scale_pct()
        span = float(HUD_SCALE_MAX - HUD_SCALE_MIN)
        frac = (pct - HUD_SCALE_MIN) / span
        hov = rect.collidepoint(mouse_pos)
        panel(canvas, rect, bg=(64, 46, 48) if hov else (46, 33, 34),
              edge=lighten(CYAN, .25) if hov else PANEL_EDGE, alpha=242, radius=10, edge_w=2)
        draw_text(canvas, L("ui.hud_scale"), (rect.x + 16, rect.y + 7), 12, TEXT_DIM, shadow=False)
        draw_text(canvas, fmt_pct(pct), (rect.right - 16, rect.y + 6), 16, CYAN, bold=True,
                  right=True, shadow=False)
        br = pygame.Rect(rect.x + 16, rect.y + 27, rect.w - 32, 11)
        draw_bar(canvas, br, frac, CYAN, radius=5)
        # %100 çentiği
        mx = br.x + br.w * ((100 - HUD_SCALE_MIN) / span)
        pygame.draw.line(canvas, (200, 210, 230), (mx, br.y - 3), (mx, br.bottom + 3), 1)
        hx = br.x + br.w * frac
        pygame.draw.circle(canvas, (23, 17, 18), (int(hx), br.centery), 7)
        pygame.draw.circle(canvas, CYAN, (int(hx), br.centery), 7, 2)
        if down and br.inflate(26, 26).collidepoint(mouse_pos):
            v = HUD_SCALE_MIN + clamp((mouse_pos[0] - br.x) / max(1, br.w), 0.0, 1.0) * span
            v = int(round(v / 5.0) * 5)            # 5'lik adımlar
            CFG["hud_scale"] = int(clamp(v, HUD_SCALE_MIN, HUD_SCALE_MAX))
            self._hud_dirty = True
        if getattr(self, "_hud_dirty", False) and not down:
            self._hud_dirty = False
            self.save.data.setdefault("settings", {})["hud_scale"] = hud_scale_pct()
            self.save.save()

    def update_pause(self, dt, mouse_pos, clicked):
        """Duraklatma ekranı (ESC)."""
        canvas = self.display.canvas
        self._draw_run_frame(canvas)
        overlay = pygame.Surface((VIRTUAL_W, VIRTUAL_H), pygame.SRCALPHA)
        pygame.draw.rect(overlay, (17, 12, 12, 206), overlay.get_rect())
        canvas.blit(overlay, (0, 0))

        down = pygame.mouse.get_pressed()[0] and not self.chat.open
        cx = VIRTUAL_W / 2
        # Panel, ses kaydırıcıları eklendiği için uzadı: oyuncu müziği ve efekt
        # sesini oyundan çıkmadan ayarlayabiliyor.
        pr = pygame.Rect(0, 0, 720, 512)       # görevler satırı eklendi
        pr.center = (cx, VIRTUAL_H / 2 + 6)
        panel(canvas, pr, bg=(37, 27, 28), edge=(72, 82, 124), alpha=243, radius=18, edge_w=2)

        # ---- başlık: panelin içinde, iki yanında başlık hizasında ayraç ----
        ty = pr.y + 28
        draw_text(canvas, L("ui.paused"), (cx, ty), 36, TEXT, bold=True, center=True)
        tw_ = text_width(L("ui.paused"), 36, True)
        for sgn in (-1, 1):
            x0 = cx + sgn * (tw_ / 2 + 20)
            pygame.draw.line(canvas, scale_col(GOLD, 0.6), (x0, ty), (x0 + sgn * 96, ty), 2)
        draw_text(canvas,
                  L("ui.pause_line", self.run.waves.wave, self.run.player.level,
                    fmt_num(self.run.score)),
                  (cx, ty + 30), 14, TEXT_DIM, center=True, shadow=False)

        # ---- iki sütun: solda görünüm ayarları, sağda düğmeler ----
        colw = 320
        lx = pr.x + 28
        rx = pr.right - 28 - colw
        y = pr.y + 94
        draw_text(canvas, L("ui.look"), (lx, y - 20), 12, GOLD, bold=True, shadow=False)
        draw_text(canvas, L("ui.game"), (rx, y - 20), 12, GOLD, bold=True, shadow=False)

        # sol: eşya efekti + ses + yetenek çubuğu + skin görünümü
        self._fx_slider(canvas, pygame.Rect(lx, y, colw, 50), mouse_pos, down)
        # ---- ses: oyundan çıkmadan ayarlanır ----
        self._set_slider(canvas, pygame.Rect(lx, y + 58, colw, 50),
                         L("ui.music_vol"), "music_vol", mouse_pos, down)
        self._set_slider(canvas, pygame.Rect(lx, y + 116, colw, 50),
                         L("ui.sfx_vol"), "sfx_vol", mouse_pos, down)
        # Ses anında değişir: AudioManager, ayar sözlüğünün kendisini tutuyor,
        # bu yüzden ayrıca bildirmeye gerek yok.
        if getattr(self, "_set_dirty", False) and not down:
            self._set_dirty = False
            self.save.apply_cfg()
            self.save.save()
        y2 = y + 174
        sr = pygame.Rect(lx, y2, colw, 48)
        hov = sr.collidepoint(mouse_pos)
        panel(canvas, sr, bg=(64, 46, 48) if hov else (46, 33, 34),
              edge=(128, 104, 106) if hov else PANEL_EDGE, alpha=242, radius=10, edge_w=2)
        draw_text(canvas, L("ui.skill_bar"), (sr.x + 16, sr.y + 7), 12, TEXT_DIM, shadow=False)
        draw_text(canvas, f"{skill_scale_label()}  »", (sr.x + 16, sr.y + 23), 16,
                  TEXT, bold=True, shadow=False)
        k = clamp(float(CFG.get("skill_scale", 0.85)), 0.5, 1.4)
        pw = int(22 * k)
        for i in range(3):
            prv = pygame.Rect(int(sr.right - 18 - (3 - i) * (pw + 4)),
                              int(sr.centery - pw / 2), pw, pw)
            pygame.draw.rect(canvas, (37, 27, 28), prv, border_radius=4)
            ink_frame(canvas, prv, (90, 200, 210), 4, 1)
        if clicked and hov:
            CFG["skill_scale"] = cycle_skill_scale()
            self.save.data.setdefault("settings", {})["skill_scale"] = CFG["skill_scale"]
            self.save.save()
            sfx("click", 0.6, 0.0)
        self._plain_skin_row(canvas, pygame.Rect(lx, y2 + 58, colw, 48), mouse_pos, clicked)

        shake_r = pygame.Rect(lx, y2 + 116, colw, 48)
        shake_on = bool(CFG.get("shake", True))
        shake_hov = shake_r.collidepoint(mouse_pos)
        panel(canvas, shake_r, bg=(64, 46, 48) if shake_hov else (46, 33, 34),
              edge=(128, 104, 106) if shake_hov else PANEL_EDGE, alpha=242, radius=10, edge_w=2)
        draw_text(canvas, L("ui.shake"), (shake_r.x + 16, shake_r.y + 7), 12, TEXT_DIM, shadow=False)
        draw_text(canvas, L("ui.on") if shake_on else L("ui.off"), (shake_r.x + 16, shake_r.y + 23),
                  16, GREEN if shake_on else RED, bold=True, shadow=False)
        draw_icon(canvas, shake_r.right - 26, shake_r.centery, "target",
                  GOLD if shake_on else (110, 116, 140), 9)
        if clicked and shake_hov:
            st_ = self.save.data.setdefault("settings", {})
            st_["shake"] = not shake_on
            self.save.apply_cfg()
            self.save.save()
            sfx("click", 0.6, 0.0)

        note = L("ui.fx_note_long")
        ny = y2 + 174
        for ln in wrap_text(note, 10, colw):
            draw_text(canvas, ln, (lx, ny), 10, TEXT_DIM, shadow=False)
            ny += 13

        # sağ: oyun düğmeleri
        bh, bgap = 48, 11
        buttons = [
            Button((rx, y, colw, bh), L("ui.resume"), self.resume_run,
                   color=(60, 130, 90), hover_color=(80, 170, 115)),
            (Button((rx, y + (bh + bgap), colw, bh),
                    _tc("OTO NİŞAN: ", "AUTO AIM: ", "AUTO-APUNTAR: ", "AUTO-ZIELEN: ", "АВТОПРИЦЕЛ: ")
                    + (_tc("AÇIK", "ON", "SÍ", "AN", "ВКЛ") if CFG.get("auto_aim", True)
                       else _tc("KAPALI", "OFF", "NO", "AUS", "ВЫКЛ")),
                    self._toggle_auto_aim) if MOBILE else
             Button((rx, y + (bh + bgap), colw, bh), L("ui.fullscreen_toggle"),
                    self.display.toggle_fullscreen)),
            Button((rx, y + 2 * (bh + bgap), colw, bh), L("ui.restart"), self.start_run,
                   color=(130, 90, 60), hover_color=(170, 115, 80)),
            Button((rx, y + 3 * (bh + bgap), colw, bh), L("ui.main_menu"),
                   lambda: self.set_state(STATE_MENU)),
        ]
        for b in buttons:
            b.update(mouse_pos, dt)
            b.draw(canvas)
            if clicked:
                b.click(mouse_pos)
        # sol üst panel boyutu (silah + kitap şeritleri)
        self._hud_slider(canvas, pygame.Rect(rx, y + 4 * (bh + bgap) + 4, colw, 50),
                         mouse_pos, down)
        # koşu görevleri kutusunu oyun içinden gizle / göster
        qr = pygame.Rect(rx, y + 4 * (bh + bgap) + 62, colw, 48)
        self.pause_quest_rect = qr          # testler bu satıra tıklar
        on = bool(CFG.get("show_quests", True))
        hov = qr.collidepoint(mouse_pos)
        panel(canvas, qr, bg=(64, 46, 48) if hov else (46, 33, 34),
              edge=(128, 104, 106) if hov else PANEL_EDGE, alpha=242, radius=10, edge_w=2)
        draw_text(canvas, L("ui.show_quests"), (qr.x + 16, qr.y + 7), 12, TEXT_DIM, shadow=False)
        draw_text(canvas, L("ui.on") if on else L("ui.off"), (qr.x + 16, qr.y + 23), 16,
                  GREEN if on else RED, bold=True, shadow=False)
        draw_icon(canvas, qr.right - 26, qr.centery, "target", GOLD if on else (110, 116, 140), 9)
        if clicked and hov:
            st_ = self.save.data.setdefault("settings", {})
            st_["show_quests"] = not on
            self.save.apply_cfg()
            self.save.save()
            sfx("click", 0.6, 0.0)

        if not MOBILE:          # telefonda ESC / TAB yok
            draw_text(canvas, L("ui.pause_hint"),
                      (cx, pr.bottom - 22), 11, TEXT_DIM, center=True, shadow=False)

    def _plain_skin_row(self, canvas, rect, mouse_pos, clicked, compact=False):
        """"SKİN GÖRÜNÜMÜ" anahtarı: sağında canlı bir önizleme topu taşır."""
        on = not CFG.get("plain_skin")
        hov = rect.collidepoint(mouse_pos)
        panel(canvas, rect, bg=(30, 50, 34) if on else (44, 34, 28),
              edge=(128, 104, 106) if hov else PANEL_EDGE, alpha=240, radius=10, edge_w=2)
        if compact:
            draw_text(canvas, L("ui.skin_look_s", L("ui.on") if on else L("ui.off")),
                      (rect.centerx - 16, rect.centery - 7), 12, TEXT, bold=True,
                      center=True, shadow=False)
        else:
            draw_text(canvas, L("ui.skin_look"), (rect.x + 16, rect.y + 7), 12, TEXT_DIM, shadow=False)
            draw_text(canvas, (L("ui.on") if on else L("ui.off_plain")) + "  »",
                      (rect.x + 16, rect.y + 23), 17, (GREEN if on else ORANGE), bold=True,
                      shadow=False)

        # ---- canlı önizleme: seçili skinin rengiyle küçük bir karakter ----
        sk = get_skin(self.save.equipped_skin_id())
        pr_ = 9 if compact else 12
        pcx, pcy = rect.right - pr_ - 10, rect.centery
        pygame.draw.circle(canvas, OUTLINE, (int(pcx), int(pcy)), pr_ + 2)
        pygame.draw.circle(canvas, scale_col(sk["color"], 0.6), (int(pcx), int(pcy)), pr_)
        pygame.draw.circle(canvas, sk["color"], (int(pcx - 1), int(pcy - 1)), pr_ - 1)
        if on:
            # görünüm açıkken önizlemede de küçük bir kanat/parıltı görünsün
            add_glow(canvas, pcx, pcy, pr_ * 1.8, sk["accent"], .45)
            for s in (-1, 1):
                pygame.draw.polygon(canvas, sk["accent"],
                                    [(pcx + s * pr_ * 0.75, pcy - 2),
                                     (pcx + s * pr_ * 1.45, pcy - pr_ * 0.65),
                                     (pcx + s * pr_ * 0.85, pcy + pr_ * 0.35)])
        pygame.draw.circle(canvas, (250, 250, 255), (int(pcx - 3), int(pcy - 2)), 2)
        pygame.draw.circle(canvas, (250, 250, 255), (int(pcx + 3), int(pcy - 2)), 2)

        if clicked and hov:
            CFG["plain_skin"] = on          # "on" açık demekti -> kapat
            self.save.data.setdefault("settings", {})["plain_skin"] = CFG["plain_skin"]
            self.save.save()
            sfx("click", 0.6, 0.0)
            return True
        return False

    def set_state(self, s):
        if s == STATE_MENU:
            audio.set_music("menu")
        self.state = s

    def world_block_reason(self):
        """Bu koşu dünya sıralamasına neden giremiyor?"""
        if self.save.is_board_banned():
            return L("ui.banned_title")
        if not self.account.logged_in():
            return L("ui.world_needs_login")
        if self.account.needs_username():
            return L("ui.pick_name_why")
        if self.save.is_tainted():
            return L("ui.taint_prefix", self.save.taint_text())
        if self.run is not None and not self.run.run_is_clean():
            return f"koşu doğrulanamadı ({self.run.cheat_flag})"
        # dünya sıralaması yalnız taş meydan'da. Öbür haritalar başarım/silah
        # açmak için; kendi kuralları skoru kolaylaştırabilir.
        if self.run is not None and getattr(self.run, "map_theme", "stone") != "stone":
            return L("map.no_world")
        return None

    def _maybe_submit_online(self):
        if self.run.submitted_online:
            return
        self.run.submitted_online = True
        # İlerleme (elmas, skin, istatistik) her koşudan sonra hesaba yazılır.
        # Dünya sıralamasına girilemese bile bu yapılır: ilerleme ayrı bir şey.
        self.account.push_progress()
        # Sıralamada hesabın adı görünür - sunucu da zaten istemciden geleni
        # değil hesaptaki adı yazıyor.
        name = self.account.display_name() or self.name_input.strip() or "İsimsiz"

        # ---- hile kapısı ----
        # Şaibeli kayıt ya da doğrulanamayan koşu dünya sıralamasına asla
        # gönderilmez.
        blocked = self.world_block_reason()
        if blocked:
            self.online_submit_status = "reddedildi"
            self.online_block_text = blocked
            return

        def on_done(ok, why=""):
            self.online_submit_status = "gönderildi" if ok else "başarısız"
            self.online_block_text = "" if ok else why

        if self.online.enabled:
            self.online_submit_status = "gönderiliyor"
        payload = {
            "name": name[:14],
            "score": int(self.run.score),
            "kills": int(self.run.kills),
            # Cehennemde toplam dalga (arena + cehennem): sunucunun skor
            # denetimi de dalgaya bakıyor.
            "wave": int(self.run.total_wave()),
            "run_time": float(self.run.run_time),
            "created_at": time.time(),
            "diff": self.run.diff,
        }
        # mobil skorlar ayrı tabloya düşer. Alan imzanın içinde: PC skoru mobil
        # tabloya (ya da tersi) elle taşınamaz.
        if PLATFORM_TAG != "pc":
            payload["platform"] = PLATFORM_TAG
        # dalgalar süreyle ilerliyor; sunucu dalga/süre uyumuna bakar.
        payload["wmode"] = "time"
        # Gönderiye imza eklenir: sunucu imzasız/yanlış imzalı istekleri
        # reddeder, böylece sıralamaya elle curl atılamaz. koşu kartı: dünya
        # sıralamasında bu skora tıklayınca açılan ayrıntı (silahlar, kitaplar,
        # hasar, istatistik).
        try:
            det = run_build_snapshot(self.run)
            payload["details"] = det
            payload["build"] = build_hash(det)
        except Exception:
            payload.pop("details", None)
            payload.pop("build", None)
        payload["sig"] = sign_submit(payload)
        # Oturum jetonu imzadan sonra eklenir: imza yalnızca skor alanlarını
        # kapsar. Jeton varsa sunucu skoru hesaba bağlar.
        if self.account.token:
            payload["token"] = self.account.token
            payload["device"] = device_id()
            payload["device_legacy"] = device_id_legacy()
        self.online.submit_score_async(payload, on_done=on_done)

    def _gameover_backdrop(self, r):
        """Oyun bitti arka planı: koşunun son karesi - bulanık, kararmış, kızıl bir hâleyle."""
        bg = getattr(self, "_go_bg", None)
        if bg is not None and getattr(self, "_go_bg_run", None) is r:
            return bg
        base = pygame.Surface((VIRTUAL_W, VIRTUAL_H)).convert()
        base.fill((10, 8, 14))
        try:
            draw_run(base, r, self.t)
        except Exception:
            pass
        small = pygame.transform.smoothscale(base, (VIRTUAL_W // 8, VIRTUAL_H // 8))
        small = pygame.transform.smoothscale(small, (VIRTUAL_W // 3, VIRTUAL_H // 3))
        bg = pygame.transform.smoothscale(small, (VIRTUAL_W, VIRTUAL_H))
        shade = pygame.Surface((VIRTUAL_W, VIRTUAL_H))
        shade.fill((92, 70, 84))
        bg.blit(shade, (0, 0), special_flags=pygame.BLEND_RGB_MULT)
        vig = pygame.Surface((VIRTUAL_W, VIRTUAL_H), pygame.SRCALPHA)
        for i in range(14):
            k = i / 13.0
            pygame.draw.rect(vig, (60, 0, 10, int(16 + 10 * k)),
                             vig.get_rect().inflate(-int(90 * k * 6), -int(52 * k * 6)), 40,
                             border_radius=40)
        bg.blit(vig, (0, 0))
        self._go_bg, self._go_bg_run = bg, r
        return bg

    def update_gameover(self, dt, mouse_pos, clicked):
        """oyun bitti (yeniden tasarım): son karenin bulanık hâli üstünde kahraman kartı"""
        canvas = self.display.canvas
        r = self.run
        if self.replay.playing():
            if not self.replay.draw(canvas, dt, self.t) or clicked:
                self.replay.stop()
            return
        if getattr(self, "_go_run", None) is not r:
            self._go_run = r
            self.gameover_t = 0.0
        self.gameover_t = getattr(self, "gameover_t", 0.0) + dt
        gt = self.gameover_t
        canvas.blit(self._gameover_backdrop(r), (0, 0))
        # süzülen kül / kor
        for i in range(36):
            ph = (self.t * (0.05 + (i % 5) * 0.012) + i * 0.137) % 1.0
            x = (i * 211.7 + math.sin(self.t * 0.7 + i) * 30) % VIRTUAL_W
            y = VIRTUAL_H - ph * (VIRTUAL_H + 40)
            blit_disc(canvas, x, y, 1.5 + (i % 3), (255, 140 + (i % 4) * 25, 90), int(170 * (1 - ph)))
        # ---- başlık ----
        pop = ease_out_cubic(clamp(gt / 0.5, 0.0, 1.0))
        tsz = int(30 + 18 * pop)
        add_glow(canvas, VIRTUAL_W / 2, 40, 300, (255, 60, 60), 0.30 + 0.08 * math.sin(self.t * 2))
        draw_text(canvas, L("ui.game_over"), (VIRTUAL_W / 2, 40), tsz, (255, 96, 96),
                  bold=True, center=True)
        if r.death_cause:
            dc = L("ui.killed_by", r.death_cause)
            dw = text_width(dc, 13, True) + 34
            dr = pygame.Rect(0, 0, dw, 24)
            dr.center = (VIRTUAL_W / 2, 76)
            panel(canvas, dr, bg=(46, 16, 22), edge=(190, 70, 80), alpha=235, radius=12, edge_w=1)
            draw_icon(canvas, dr.x + 14, dr.centery, "skull", (255, 150, 150), 6)
            draw_text(canvas, dc, (dr.x + 26, dr.y + 5), 13, (255, 196, 196), bold=True, shadow=False)

        # ---- paneller ----
        left = pygame.Rect(22, 96, 838, 604)
        right = pygame.Rect(left.right + 16, 96, VIRTUAL_W - 22 - left.right - 16, 604)
        panel(canvas, left, alpha=232)
        self._draw_dmg_breakdown(canvas, r, right)

        pb = getattr(r, "prev_best", None) or {}
        rekor = r.run_is_clean() and int(r.score) > int(pb.get("score", 0))

        # ---- kahraman kartı ----
        hero = pygame.Rect(left.x + 18, left.y + 18, 230, 300)
        theme = getattr(r, "map_theme", "stone")
        hcol = (255, 130, 80) if r.biome == "hell" else MAP_THEME_COLOR.get(theme, CYAN)
        panel(canvas, hero, bg=scale_col(hcol, 0.18), edge=scale_col(hcol, 0.8), alpha=240,
              radius=14, edge_w=2)
        hc = (hero.centerx, hero.y + 112)
        add_glow(canvas, hc[0], hc[1], 120, hcol, 0.30 + 0.08 * math.sin(self.t * 2.4))
        for i in range(10):
            a = self.t * 0.5 + i * math.tau / 10
            pygame.draw.line(canvas, scale_col(hcol, 0.55),
                             (hc[0] + math.cos(a) * 64, hc[1] + math.sin(a) * 64),
                             (hc[0] + math.cos(a) * 92, hc[1] + math.sin(a) * 92), 2)
        ring_aa(canvas, hc[0], hc[1], 62, scale_col(hcol, 0.9), 2)
        try:
            draw_skin_preview(canvas, r.player.skin, hc[0], hc[1], self.t, r=40)
        except Exception:
            pass
        nm = ""
        try:
            if self.account.logged_in():
                nm = self.account.display_name()
        except Exception:
            nm = ""
        nm = nm or self.save.data.get("settings", {}).get("player_name", "") or L("ui.go_player")
        draw_text(canvas, _fit_text(str(nm), 18, hero.w - 20, bold=True), (hero.centerx, hero.y + 186),
                  18, TEXT, bold=True, center=True)
        draw_text(canvas, _fit_text(skin_name(r.player.skin), 12, hero.w - 20),
                  (hero.centerx, hero.y + 208), 12, scale_col(hcol, 1.1), center=True, shadow=False)
        chips = [("LV %d" % r.player.level, PURPLE),
                 (L("ui.hell") if r.biome == "hell" else L("map.%s.short" % theme), hcol),
                 (LX("diff." + r.diff, DIFF_LABEL.get(r.diff, r.diff)), (200, 206, 230))]
        cy_ = hero.y + 232
        for txt, ccol in chips:
            cw_ = text_width(txt, 12, True) + 22
            cr_ = pygame.Rect(0, 0, cw_, 22)
            cr_.center = (hero.centerx, cy_ + 11)
            tag_chip(canvas, cr_, ccol, 11, tint=0.24)
            draw_text(canvas, txt, cr_.center, 12, lighten(ccol, 0.2), bold=True, center=True, shadow=False)
            cy_ += 26

        # ---- istatistik karoları (sayarak dolar) ----
        def _count(v, i):
            k = ease_out_cubic(clamp((gt - 0.25 - i * 0.07) / 1.1, 0.0, 1.0))
            return v * k, k

        def _best(key):
            return int(pb.get(key, 0) or 0)

        tx0, ty0 = hero.right + 16, hero.y
        tw_, th_ = (left.right - 18 - tx0 - 2 * 12) / 3.0, 92
        tiles = [
            (0, 0, 2, "star", GOLD, L("ui.go_score"), int(r.score), fmt_num, _best("score")),
            (2, 0, 1, "target", CYAN, L("ui.go_wave"), int(r.total_wave()), str, _best("wave")),
            (0, 1, 1, "skull", (255, 140, 130), L("ui.go_kills"), int(r.kills), fmt_num, _best("kills")),
            (1, 1, 1, "orbit", (190, 200, 255), L("ui.go_time"), float(r.run_time), fmt_time, 0),
            (2, 1, 1, "coin", GOLD, L("ui.go_gold"), int(r.coins_earned), fmt_num, 0),
            (0, 2, 1, "gem", GEM_COLOR, L("ui.go_gems"), int(r.gems_earned), fmt_num, 0),
            (1, 2, 2, "bolt", (150, 230, 170), L("ui.dmg_total"),
             int(sum(v for v in (getattr(r, "dmg_log", None) or {}).values())), fmt_num, 0),
        ]
        for i, (cx_i, cy_i, span, ic, col, lab, val, fmt_, best) in enumerate(tiles):
            rr = pygame.Rect(int(tx0 + cx_i * (tw_ + 12)), int(ty0 + cy_i * (th_ + 12)),
                             int(tw_ * span + 12 * (span - 1)), th_)
            appear = clamp((gt - 0.1 - i * 0.06) / 0.3, 0.0, 1.0)
            rr = rr.move(0, int((1.0 - ease_out_cubic(appear)) * 24))
            hov = rr.collidepoint(mouse_pos)
            panel(canvas, rr, bg=(44, 32, 33) if not hov else (57, 41, 43),
                  alpha=int(240 * appear), radius=12, edge_w=1)
            circle_aa(canvas, rr.x + 26, rr.y + 26, 15, scale_col(col, 0.26))
            draw_icon(canvas, rr.x + 26, rr.y + 26, ic, col, 9)
            lab_t, lsz = _fit_size(lab.upper(), 11, rr.w - 58, True, min_size=10)
            draw_text(canvas, lab_t, (rr.x + 48 + text_width(lab_t, lsz, True, tiny=True) / 2, rr.y + 26),
                      lsz, (150, 156, 184), bold=True, center=True, shadow=False, tiny=True)
            cur, k = _count(val, i)
            txt = fmt_(int(cur)) if fmt_ is not fmt_time else fmt_time(cur)
            big = 34 if span >= 2 else 26
            draw_text(canvas, txt, (rr.x + 20, rr.y + 42), big, col, bold=True)
            if best > 0 and k >= 1.0:
                bt = L("ui.pb_best", fmt_(best)) if val <= best else "★ " + L("ui.pb_banner")
                draw_text(canvas, _fit_text(bt, 10, rr.w - 24), (rr.right - 12, rr.bottom - 18), 10,
                          (130, 136, 162) if val <= best else GOLD, right=True, shadow=False)

        # ---- bilgi şeridi ----
        y = ty0 + 3 * (th_ + 12) + 8
        lx_ = left.x + 30
        if rekor:
            bar = pygame.Rect(left.x + 18, y, left.w - 36, 50)
            panel(canvas, bar, bg=(48, 38, 18), edge=(104, 84, 44), alpha=238, radius=10, edge_w=2)
            eski = int(pb.get("score", 0))
            alt = (L("ui.pb_first") if eski <= 0 else
                   L("ui.pb_up", fmt_num(eski), "%%%d" % max(1, round(
                       (int(r.score) / max(1, eski) - 1.0) * 100))))
            draw_icon(canvas, bar.x + 24, bar.centery, "star", GOLD, 10)
            # iki satır şeridin içinde dikey ortalı
            h1, h2 = text_height(17, True), text_height(11)
            yb = bar.centery - (h1 + h2) // 2
            draw_text(canvas, L("ui.pb_banner"), (bar.x + 44, yb), 17, GOLD, bold=True, shadow=False)
            draw_text(canvas, alt, (bar.x + 44, yb + h1), 11, (214, 190, 130), shadow=False)
            y += 58
        if getattr(r, "quest_gems", 0):
            draw_text(canvas, L("q.paid", r.quest_gems), (lx_, y), 12, GEM_COLOR, bold=True, shadow=False)
            y += 18
        if self.save.is_board_banned():
            bar = pygame.Rect(left.x + 18, y, left.w - 36, 30)
            panel(canvas, bar, bg=(50, 20, 24), edge=(100, 46, 52), alpha=240, radius=8, edge_w=2)
            draw_text(canvas, L("ui.banned_title") + " - " + L("ui.banned_why", self.save.ban_text()),
                      bar.center, 12, (255, 160, 160), bold=True, center=True, shadow=False)
            y += 36
        if not r.run_is_clean():
            draw_text(canvas, L("ui.run_invalid") + f"  ({r.cheat_flag})", (lx_, y), 14,
                      RED, bold=True, shadow=False)
            y += 20
        elif self.pending_board_rank >= 0:
            draw_text(canvas, L("ui.local_rank", self.pending_board_rank + 1), (lx_, y), 15, GOLD,
                      bold=True, shadow=False)
            y += 20
        if self.online_submit_status in ("reddedildi", "başarısız"):
            draw_text(canvas, L("ui.not_submitted"), (lx_, y), 13, RED, bold=True, shadow=False)
            y += 17
            for ln in wrap_text(getattr(self, "online_block_text", ""), 11, left.w - 70)[:2]:
                draw_text(canvas, ln, (lx_, y), 11, (210, 140, 140), shadow=False)
                y += 14
        elif self.online.enabled and self.online_submit_status:
            status_col = {"gönderiliyor": TEXT_DIM, "gönderildi": GREEN,
                          "başarısız": RED}.get(self.online_submit_status, TEXT_DIM)
            draw_text(canvas, L("ui.submit_state", self.online_submit_status), (lx_, y), 12,
                      status_col, shadow=False)
            y += 18
        new_w = [WEAPON_BY_KEY[k]["name"] for k in getattr(r, "new_weapons", []) if k in WEAPON_BY_KEY]
        new_b = [BOOK_BY_KEY[k]["name"] for k in getattr(r, "new_books", []) if k in BOOK_BY_KEY]
        new_m = [L("map.%s.name" % m) for m in getattr(r, "new_maps", [])]
        for ic, col, lab, items in (("star", GOLD, L("ui.unlocked_map"), new_m),
                                    ("sword", (238, 150, 100), L("ui.unlocked_weapon"), new_w),
                                    ("book", (186, 150, 255), L("ui.unlocked_book"), new_b)):
            if items:
                draw_icon(canvas, lx_ + 4, y + 8, ic, col, 7)
                draw_text(canvas, lab + ", ".join(items[:3]) + (f" +{len(items) - 3}" if len(items) > 3 else ""),
                          (lx_ + 18, y), 13, col, bold=True, shadow=False)
                y += 20
        # en yakın kilit
        yakin = []
        for w2 in BOSS_WEAPONS:
            if not self.save.owns_weapon(w2["key"]):
                yakin.append((weapon_frac(self.save, w2), w_name(w2), "sword", (238, 150, 100)))
        for bk in BOOKS:
            if not self.save.owns_book(bk["key"]):
                yakin.append((book_frac(self.save, bk), bk_name(bk), "book", (186, 150, 255)))
        yakin = [z for z in yakin if z[0] < 0.999]
        yakin.sort(key=lambda z: -z[0])
        by = left.bottom - 76
        if yakin and y + 34 < by - 80:
            y += 4
            draw_text(canvas, L("ui.next_unlock"), (lx_, y), 11, (130, 136, 162), bold=True, shadow=False)
            y += 16
            colw = (left.w - 60) // 2
            for j, (frac, ad, ikon, col) in enumerate(yakin[:2]):
                xx = lx_ + j * (colw + 20)
                draw_icon(canvas, xx + 6, y + 7, ikon, col, 6)
                draw_text(canvas, _fit_text(ad, 13, colw - 120), (xx + 20, y), 13, col, bold=True, shadow=False)
                pb_r = pygame.Rect(xx + colw - 110, y + 5, 80, 8)
                draw_bar(canvas, pb_r, clamp(frac, 0.0, 1.0), col, radius=4)
                draw_text(canvas, "%%%d" % round(frac * 100), (xx + colw - 4, y + 1), 11, col,
                          right=True, shadow=False)

        # ---- koşunun takımı: silahlar + kitaplar (seviye rozetli) ----
        team_y = by - 74
        if team_y > y + 6:
            draw_text(canvas, L("ui.go_build"), (lx_, team_y - 2), 11, (130, 136, 162), bold=True, shadow=False)
            xx = lx_
            pw_ = r.player.weapons
            for k, lv in sorted(pw_.items(), key=lambda kv: -kv[1]):
                if k not in WEAPON_BY_KEY:
                    continue
                col = tuple(WEAPON_BY_KEY[k]["color"])
                tr_ = pygame.Rect(xx, team_y + 14, 44, 44)
                panel(canvas, tr_, bg=(35, 25, 26), edge=scale_col(col, 0.8), alpha=240, radius=9, edge_w=1)
                blit_sigil(canvas, tr_.centerx, tr_.centery, 14, k, col)
                draw_text(canvas, str(lv), (tr_.right - 6, tr_.bottom - 14), 11, WHITE, bold=True, right=True)
                xx += 50
            if pw_:
                xx += 14
            for k, lv in r.player.books.items():
                bk = BOOK_BY_KEY.get(k)
                if bk is None or lv <= 0:
                    continue
                col = tuple(bk["color"])
                tr_ = pygame.Rect(xx, team_y + 14, 44, 44)
                panel(canvas, tr_, bg=(35, 25, 26), edge=scale_col(col, 0.8), alpha=240,
                      radius=9 if not bk.get("rare") else 14, edge_w=2 if bk.get("rare") else 1)
                draw_icon(canvas, tr_.centerx, tr_.centery, bk.get("icon", "book"), col, 11)
                draw_text(canvas, str(lv), (tr_.right - 6, tr_.bottom - 14), 11, WHITE, bold=True, right=True)
                xx += 50
                if xx > left.right - 60:
                    break

        # ---- düğmeler ----
        has_rp = self.replay.ready(r)
        bw, bh = (190, 54) if has_rp else (240, 54)
        gap = 14 if has_rp else 16
        nb = 4 if has_rp else 3
        x0 = left.centerx - (bw * nb + gap * (nb - 1)) / 2
        rp_rect = None
        if has_rp:
            rp_rect = pygame.Rect(int(x0 + bw + gap), by + 6, bw, bh)
        xs = [x0] + [x0 + k * (bw + gap) for k in range(nb - 2, nb)]
        btns = [Button((xs[0], by + 6, bw, bh), L("ui.play_again"), self.start_run,
                       color=(60, 130, 90), hover_color=(80, 170, 115)),
                Button((xs[1], by + 6, bw, bh), L("ui.world_lb"),
                       lambda: self.goto(STATE_WORLD_LB), color=(70, 76, 140),
                       hover_color=(96, 104, 186), text_size=18 if not has_rp else 16),
                Button((xs[2], by + 6, bw, bh), L("ui.main_menu"),
                       lambda: self.set_state(STATE_MENU))]
        if rp_rect is not None:
            hov_rp = replay_button_draw(canvas, rp_rect, mouse_pos, self.t)
            draw_text(canvas, _fit_text(L("rp.note"), 10, left.w - 40), (left.centerx, left.bottom - 8), 10,
                      (150, 130, 140), center=True, shadow=False)
            if clicked and hov_rp:
                self.replay.start()
                return
        add_glow(canvas, btns[0].rect.centerx, btns[0].rect.centery, 150, GREEN,
                 0.10 + 0.05 * math.sin(self.t * 3))
        for b in btns:
            b.update(mouse_pos, dt)
            b.draw(canvas)
            if clicked:
                b.click(mouse_pos)
        if rekor and int(pb.get("score", 0)) > 0:
            draw_stamp(canvas, L("ui.new_record"), gt - 0.35, GOLD, y=360, life=2.4)

    def _draw_dmg_breakdown(self, canvas, r, rect):
        """Ölüm ekranı - hangi silah ne kadar vurdu, büyükten küçüğe."""
        panel(canvas, rect, alpha=245)
        draw_text(canvas, L("ui.dmg_title"), (rect.centerx, rect.y + 30), 22, GOLD,
                  bold=True, center=True)
        log = getattr(r, "dmg_log", None) or {}
        rows = sorted(((v, k) for k, v in log.items() if v >= 1.0), reverse=True)
        total = sum(v for v, _k in rows)
        draw_text(canvas, L("ui.dmg_total"), (rect.x + 22, rect.y + 56), 13, TEXT_DIM,
                  shadow=False)
        draw_text(canvas, fmt_num(int(total)), (rect.right - 22, rect.y + 54), 15, TEXT,
                  bold=True, right=True, shadow=False)
        if not rows:
            draw_text(canvas, L("ui.dmg_none"), (rect.centerx, rect.y + 110), 13, TEXT_DIM,
                      center=True, shadow=False)
            return
        # ilk 10 + her satırda silahın kendi resmi (balta için balta, pentagram
        # için pentagram); silah dışı kaynaklarda simge.
        top = rows[0][0]
        y = rect.y + 82
        row_h = 48
        shown = rows[:10]
        medal = {0: GOLD, 1: (200, 206, 220), 2: (205, 140, 90)}
        for i, (v, k) in enumerate(shown):
            name, ic, col = dmg_src_label(k)
            col = tuple(int(c) for c in col[:3])
            mc = medal.get(i)
            if mc is not None:
                circle_aa(canvas, rect.x + 22, y + 15, 10, scale_col(mc, 0.35))
                ring_aa(canvas, rect.x + 22, y + 15, 10, mc, 2)
            draw_text(canvas, str(i + 1), (rect.x + 22, y + 15), 12,
                      mc or TEXT_DIM, bold=True, center=True, shadow=False)
            tile = pygame.Rect(rect.x + 38, y, 38, 32)
            pygame.draw.rect(canvas, (32, 23, 24), tile, border_radius=8)
            ink_frame(canvas, tile, scale_col(col, 0.75), 8, 1)
            if k in WEAPON_BY_KEY:
                blit_sigil(canvas, tile.centerx, tile.centery, 14, k, col)
            else:
                draw_icon(canvas, tile.centerx, tile.centery, ic, col, 10)
            tx = tile.right + 10
            draw_text(canvas, _fit_text(name, 14, rect.right - tx - 112, bold=True), (tx, y + 1), 14, col,
                      bold=True, shadow=False)
            pct = v / max(1.0, total) * 100.0
            draw_text(canvas, fmt_num(int(v)), (rect.right - 58, y + 2), 12, TEXT,
                      right=True, shadow=False)
            draw_text(canvas, "%%%d" % round(pct) if lang() == "tr" else "%d%%" % round(pct),
                      (rect.right - 18, y + 2), 12, GOLD if i == 0 else TEXT_DIM,
                      bold=True, right=True, shadow=False)
            bar = pygame.Rect(tx, y + 22, rect.right - 18 - tx, 8)
            draw_bar(canvas, bar, clamp(v / max(1.0, top), 0.0, 1.0), col, radius=4)
            y += row_h
        if len(rows) > len(shown):
            rest = sum(v for v, _k in rows[len(shown):])
            draw_text(canvas, "+%d - %s" % (len(rows) - len(shown), fmt_num(int(rest))),
                      (rect.centerx, rect.bottom - 20), 11, TEXT_DIM, center=True, shadow=False)

    # ---- isim girişi ----
    def _text_box_active(self):
        """Şu an bir yazı kutusu klavyeyi dinliyor mu?"""
        if self.chat.open:
            return True
        st = self.state
        if st in (STATE_LOGIN, STATE_FRIENDS, STATE_NAME_ENTRY, STATE_COOP_LOBBY):
            return True
        if st == STATE_PET_DESIGNER:
            return bool(getattr(self, "pd", None) and self.pd.get("name_focus"))
        return False

    def _backspace_repeat(self, dt, events):
        """Silme tuşu basılı tutulunca (0.4 sn sonra) harfleri art arda siler.
        Yalnız yazı kutusu açıkken çalışır; oyun tuşlarına dokunmaz."""
        for e in events:
            if e.type == pygame.KEYDOWN and e.key == pygame.K_BACKSPACE:
                self._bs_hold = 0.0
                self._bs_acc = 0.0
            elif e.type == pygame.KEYUP and e.key == pygame.K_BACKSPACE:
                self._bs_hold = None
        hold = getattr(self, "_bs_hold", None)
        if hold is None:
            return []
        if not pygame.key.get_pressed()[pygame.K_BACKSPACE] or not self._text_box_active():
            self._bs_hold = None
            return []
        self._bs_hold = hold + dt
        if self._bs_hold < 0.4:
            return []
        self._bs_acc += dt
        out = []
        while self._bs_acc >= 0.035 and len(out) < 4:
            self._bs_acc -= 0.035
            out.append(pygame.event.Event(pygame.KEYDOWN, key=pygame.K_BACKSPACE, unicode="\x08",
                                          mod=pygame.key.get_mods(), scancode=0))
        return out

    def handle_name_entry_key(self, event):
        if event.key == pygame.K_RETURN:
            self.confirm_name_entry()
        elif event.key == pygame.K_BACKSPACE:
            self.name_input = self.name_input[:-1]
        elif _ctrl_down() and event.key == pygame.K_c:
            clip_set(self.name_input)
        else:
            chars = clip_get() if (_ctrl_down() and event.key == pygame.K_v) else (
                "" if _ctrl_down() else event.unicode)
            for ch in (chars or ""):
                if ch.isprintable() and len(self.name_input) < 14:
                    self.name_input += ch

    def confirm_name_entry(self):
        r = self.run
        name = self.name_input.strip() or "İsimsiz"
        self.save.data.setdefault("settings", {})["player_name"] = name
        try:
            _mk = "hell" if r.biome == "hell" else str(getattr(r.waves, "theme", None) or "stone")
        except Exception:
            _mk = None
        rank = self.save.submit_score(name, r.score, r.kills, r.run_time, r.total_wave(), r.diff,
                                      skin=r.player.skin.get("id"), map_key=_mk)
        self.pending_board_rank = rank
        self._maybe_submit_online()
        self.state = STATE_GAMEOVER

