    def _draw_loadout_panel(self, canvas, dt, mouse_pos, clicked):
        """Ana menüdeki sol panel: kuşanılmış karakterin canlı önizlemesi."""
        t = self.t
        rect = pygame.Rect(26, 302, 184, 212)
        hover = rect.collidepoint(mouse_pos)
        sk = get_skin(self.save.equipped_skin_id())
        panel(canvas, rect, bg=(55, 40, 41) if hover else (39, 28, 29),
              edge=sk["color"] if hover else (102, 74, 77), alpha=238, radius=14, edge_w=2)

        draw_text(canvas, L("ui.your_char"), (rect.centerx, rect.y + 10), 12, TEXT_DIM,
                  bold=True, center=True, shadow=False)

        # ---- canlı karakter ----
        cx, cy = rect.centerx, rect.y + 84
        bob = math.sin(t * 1.8) * 3
        cy += bob
        fake = type("FP", (), {})()
        fake.radius = 27
        fake.aim_dir = (math.sin(t * 0.6) * 0.30, 1.0)
        fake.cosmetics = self.save.equipped_cosmetics()
        fake.skin = sk

        add_glow(canvas, cx, cy, 58, sk["color"], .38 + .10 * math.sin(t * 2.4))
        if not self.save.cosmetics_locked():
            draw_cosmetic_cape(canvas, fake, cx, cy, t)
        # Skinin kendi görünümü (aura, maske, kanat, pelerin...) tam hâliyle
        locked_cos = self.save.cosmetics_locked()
        draw_skin_preview(canvas, sk, cx, cy, t, r=27, weapon=False, aim=fake.aim_dir,
                          hide_eyes=() if locked_cos else eyes_hidden(fake))
        if not locked_cos:
            draw_cosmetic_eyewear(canvas, fake, cx, cy, t)
            draw_cosmetic_hat(canvas, fake, cx, cy, t)

        _pid = self.save.equipped_cosmetic_id("pet")
        _pt = pet_def(_pid) if _pid else None
        if _pt and CFG.get("pet_show", True):
            draw_pet_def(canvas, _pt, cx + 52, cy + 16, 10, t, face=-1, shadow=False)

        draw_text(canvas, skin_name(sk), (rect.centerx, rect.y + 126), 15, sk["color"],
                  bold=True, center=True)

        # ---- kuşanılmış parçalar: 3 küçük yuva ----
        eq = self.save.equipped_cosmetics()
        slots = [(sl, L("ui.slot_" + sl)) for sl in ("hat", "eyewear", "cape")]
        sw = 60
        sx0 = rect.centerx - (len(slots) * sw) / 2
        for i, (slot, label) in enumerate(slots):
            sr = pygame.Rect(int(sx0 + i * sw + 3), rect.y + 150, sw - 6, 32)
            cid = eq.get(slot)
            item = COSMETIC_BY_ID.get(cid) if cid else None
            pygame.draw.rect(canvas, (30, 22, 23), sr, border_radius=7)
            ink_frame(canvas, sr, item['color'] if item else (82, 59, 61), 7, 1)
            if item:
                pygame.draw.circle(canvas, item["color"], (sr.centerx, sr.y + 11), 6)
                pygame.draw.circle(canvas, lighten(item["color"], .45),
                                   (sr.centerx - 2, sr.y + 9), 2)
            else:
                draw_text(canvas, "-", (sr.centerx, sr.y + 3), 13, (111, 85, 88),
                          center=True, shadow=False)
            draw_text(canvas, label, (sr.centerx, sr.bottom - 12), 8,
                      TEXT_DIM if item else (115, 90, 92), center=True, shadow=False)

        if self.save.cosmetics_locked():
            # Premium skin kendi kostümüyle gelir: slotların üstüne kilit
            # şeridi.
            lr = pygame.Rect(int(sx0 + 3), rect.y + 150, int(len(slots) * sw - 6), 32)
            ls = pygame.Surface(lr.size, pygame.SRCALPHA)
            pygame.draw.rect(ls, (*mix_col((35, 25, 26), PURPLE, 0.16), 225), ls.get_rect(), border_radius=7)
            canvas.blit(ls, lr.topleft)
            ink_frame(canvas, lr, None, 7, 1)
            draw_text(canvas, L("ui.fixed_costume"), lr.center, 11, PURPLE, bold=True,
                      center=True, shadow=False)

        draw_text(canvas, L("ui.click_change"), (rect.centerx, rect.bottom - 18), 10,
                  GOLD if hover else TEXT_DIM, center=True, shadow=False)

        if clicked and hover:
            self.goto(STATE_SKIN_MARKET)
            sfx("click", 0.6, 0.0)

    # ---- yılbaşı süsü (ana menü) ----
    def _draw_new_year_banner(self, canvas):
        """Mevsimindeyse: üstte ışık dizisi, telden sarkan süs topları ve küçük bir kurdela yazısı."""
        if not NEW_YEAR_THEME:
            return
        n = 22
        bulb_colors = ((230, 70, 70), (90, 210, 120), (235, 190, 70), (95, 190, 230))
        pts = []
        for i in range(n + 1):
            x = VIRTUAL_W * i / n
            y = 4 + 16 + 6 * math.sin(i * 0.7)
            pts.append((x, y))
        if len(pts) > 1:
            pygame.draw.aalines(canvas, (80, 72, 60), False, pts)
        if self.xmas:
            self.xmas.draw_baubles(canvas)
        for i in range(n):
            x = VIRTUAL_W * (i + 0.5) / n
            y = 4 + 16 + 6 * math.sin((i + 0.5) * 0.7) + 6
            col = bulb_colors[i % len(bulb_colors)]
            tw = 0.55 + 0.45 * math.sin(self.t * 3.2 + i * 0.9)
            add_glow(canvas, x, y, 15, col, 0.20 * tw)
            blit_disc(canvas, x, y, 3.2, lighten(col, 0.3 * tw), 255)

        # Kurdela: telin ortasından sarkar, logonun hemen üstünde durur.
        msg = L("ui.new_year_banner")
        bw = text_width(msg, 12, True) + 40
        br = pygame.Rect(0, 0, bw, 22)
        br.center = (VIRTUAL_W / 2, 31 + math.sin(self.t * 1.2) * 1.5)
        for sgn in (-1, 1):     # kurdela uçları
            ex = br.centerx + sgn * (bw / 2 + 2)
            poly_aa(canvas, [(ex - sgn * 12, br.y + 3), (ex + sgn * 10, br.y + 6),
                             (ex + sgn * 4, br.centery + 1), (ex + sgn * 10, br.bottom + 2),
                             (ex - sgn * 12, br.bottom - 1)], (150, 26, 36))
        panel(canvas, br, bg=(176, 32, 44), edge=GOLD, alpha=245, radius=7, edge_w=2)
        draw_text(canvas, msg, br.center, 12, (255, 240, 200), bold=True, center=True, shadow=False)

    # ---- logo (ana menü başlığı) ----
    # Logonun içindeki yuvarlak amblemin yeri (logo yüksekliğine oranla);
    # yılbaşı şapkası buraya oturur. tools/make_assets.py çıktısından ölçüldü.
    LOGO_BADGE = (0.1725, 0.50, 0.408)
    LOGO_H = 164

    def _logo_rays(self):
        """Afişteki altın ışınlar - bir kez çizilip saklanır."""
        img = getattr(self, "_rays_img", None)
        if img is None:
            W, H = 900, 420
            img = pygame.Surface((W, H), pygame.SRCALPHA)
            cx, cy = W / 2, H / 2
            n = 22
            for i in range(n):
                a = i * math.tau / n + 0.07
                wd = 0.018
                p1 = (cx + math.cos(a - wd) * 560, cy + math.sin(a - wd) * 560)
                p2 = (cx + math.cos(a + wd) * 560, cy + math.sin(a + wd) * 560)
                pygame.draw.polygon(img, (236, 186, 92, 255), [(cx, cy), p1, p2])
            # kenara doğru sönümle (elips biçimli maske)
            mask = pygame.Surface((W, H), pygame.SRCALPHA)
            steps = 26
            for k in range(steps, 0, -1):
                f = k / steps
                a_ = int(255 * (1 - f) ** 1.6)
                pygame.draw.ellipse(mask, (255, 255, 255, a_),
                                    pygame.Rect(cx - W / 2 * f, cy - H / 2 * f, W * f, H * f))
            img.blit(mask, (0, 0), special_flags=pygame.BLEND_RGBA_MULT)
            self._rays_img = img
        return img

    def _draw_menu_logo(self, canvas):
        bob = math.sin(self.t * 1.4) * 4
        cx, cy = VIRTUAL_W / 2, 122 + bob
        pulse = 0.5 + 0.5 * math.sin(self.t * 1.6)
        if not MOBILE:      # telefonda 600 px'lik toplamalı parlama çok pahalı
            add_glow(canvas, cx, cy, 300, (190, 140, 50), 0.12 + 0.06 * pulse)
        rays = self._logo_rays()
        rays.set_alpha(int(70 + 40 * pulse))
        canvas.blit(rays, (cx - rays.get_width() / 2 + 40, cy - rays.get_height() / 2))
        logo = brand_scaled("logo", h=self.LOGO_H)
        if logo is None:
            # Gömülü görsel çözülemezse eski yazı başlığı (asla boş kalmasın).
            draw_text(canvas, GAME_TITLE, (cx, cy), 60, GOLD, bold=True, center=True)
            return
        lw, lh = logo.get_size()
        lx, ly = cx - lw / 2, cy - lh / 2
        canvas.blit(logo, (lx, ly))
        # amblemin çevresinde dönen küçük parıltılar
        bx = lx + lw * self.LOGO_BADGE[0]
        by = ly + lh * self.LOGO_BADGE[1]
        br = lh * self.LOGO_BADGE[2]
        for i in range(3):
            a = self.t * 0.8 + i * math.tau / 3
            k = 0.5 + 0.5 * math.sin(self.t * 3 + i * 2)
            px, py = bx + math.cos(a) * (br + 8), by + math.sin(a) * (br + 8)
            add_glow(canvas, px, py, 14, (255, 230, 160), 0.25 + 0.35 * k)
            blit_disc(canvas, px, py, 1.8 + k, (255, 248, 220), 230)
        if NEW_YEAR_THEME:
            self._draw_santa_hat(canvas, bx - br * 0.30, by - br * 0.86, br * 0.34, -0.42)

    def _draw_santa_hat(self, canvas, x, y, s, ang):
        """Amblemin tepesine eğik oturan Noel Baba şapkası."""
        def R(px, py):
            c, sn = math.cos(ang), math.sin(ang)
            return (x + px * c - py * sn, y + px * sn + py * c)
        tip_sw = math.sin(self.t * 2.2) * 0.08 * s
        body = [R(-s * 0.95, 0), R(s * 0.95, 0), R(s * 0.35, -s * 0.85),
                R(s * 1.25 + tip_sw, -s * 0.95), R(-s * 0.15, -s * 1.15)]
        poly_aa(canvas, [(px + 2, py + 3) for px, py in body], (60, 10, 16))
        poly_aa(canvas, body, (206, 38, 48))
        poly_aa(canvas, [R(-s * 0.5, -s * 0.2), R(s * 0.2, -s * 0.9), R(-s * 0.1, -s * 1.08),
                         R(-s * 0.7, -s * 0.3)], (232, 70, 78))
        thick_line(canvas, R(-s * 1.0, -s * 0.02), R(s * 1.0, -s * 0.02), s * 0.42, (248, 248, 252))
        tip = R(s * 1.25 + tip_sw, -s * 0.95)
        circle_aa(canvas, tip[0], tip[1], s * 0.24, (248, 248, 252))

    # ---- açılış ekranı (logo) ----
    SPLASH_TIME = 1.5 if MOBILE else 2.6      # telefonda açılış daha kısa
    SPLASH_FADE = 0.45 if MOBILE else 0.55

    def _draw_splash(self, canvas):
        t = self.splash_t
        if t >= self.SPLASH_TIME:
            return
        surf = getattr(self, "_splash_surf", None)
        if surf is None:
            surf = pygame.Surface((VIRTUAL_W, VIRTUAL_H)).convert()
            self._splash_surf = surf
            bgimg = pygame.Surface((VIRTUAL_W, VIRTUAL_H)).convert()
            for y in range(VIRTUAL_H):
                f = y / VIRTUAL_H
                pygame.draw.line(bgimg, mix_col((44, 28, 64), (14, 10, 24), f), (0, y), (VIRTUAL_W, y))
            self._splash_bg = bgimg
        surf.blit(self._splash_bg, (0, 0))
        cx, cy = VIRTUAL_W / 2, VIRTUAL_H / 2 - 30
        k_in = ease_out_cubic(min(1.0, t / 0.7))
        rays = self._logo_rays()
        rays.set_alpha(int(150 * k_in))
        surf.blit(rays, (cx - rays.get_width() / 2, cy - rays.get_height() / 2))
        add_glow(surf, cx, cy, 380, (200, 150, 60), 0.30 * k_in)
        logo = brand_scaled("logo", w=640)
        if logo is not None:
            sc = 0.86 + 0.14 * k_in
            img = pygame.transform.smoothscale(
                logo, (int(logo.get_width() * sc), int(logo.get_height() * sc)))
            img.set_alpha(int(255 * min(1.0, t / 0.45)))
            surf.blit(img, (cx - img.get_width() / 2, cy - img.get_height() / 2))
        else:
            draw_text(surf, GAME_TITLE, (cx, cy), 64, GOLD, bold=True, center=True)
        # yükleme çubuğu
        bw = 280
        frac = clamp(t / (self.SPLASH_TIME - self.SPLASH_FADE), 0.0, 1.0)
        bar = pygame.Rect(0, 0, bw, 8)
        bar.center = (cx, VIRTUAL_H - 120)
        pygame.draw.rect(surf, (40, 30, 56), bar, border_radius=4)
        if frac > 0.02:
            pygame.draw.rect(surf, (236, 186, 92),
                             pygame.Rect(bar.x, bar.y, int(bw * ease_out_cubic(frac)), 8),
                             border_radius=4)
        draw_text(surf, L("ui.tap_skip"), (cx, VIRTUAL_H - 96), 12, (150, 136, 170),
                  center=True, shadow=False)
        a = 1.0
        if t > self.SPLASH_TIME - self.SPLASH_FADE:
            a = (self.SPLASH_TIME - t) / self.SPLASH_FADE
        surf.set_alpha(int(255 * clamp(a, 0.0, 1.0)))
        canvas.blit(surf, (0, 0))

    def update_menu(self, dt, mouse_pos, clicked):
        # dil değiştiyse düğmeleri yeniden kur. Denetim ayarlar ekranında değil
        # burada: menüye hangi yoldan gelinirse gelinsin çalışsın.
        if getattr(self, "_menu_lang", None) != lang():
            self._menu_lang = lang()
            self.build_menu_buttons()
        # Açılış ekranı sürerken menü tıklama almaz; tıklamak açılışı geçer.
        if self.splash_t < self.SPLASH_TIME:
            self.splash_t += dt
            if clicked and self.splash_t > 0.2:
                self.splash_t = max(self.splash_t, self.SPLASH_TIME - self.SPLASH_FADE)
            clicked = False
        overlay_click = clicked
        if self.ad_play is not None:
            clicked = False          # reklam oynarken menü kilitli
        self.bg.update(dt)
        canvas = self.display.canvas
        self.bg.draw(canvas)
        if self.xmas:
            self.xmas.update(dt)
            self.xmas.draw_sky(canvas)
            if MOBILE:
                # yerdeki kar, ağaç ve hediyeler: hazır görüntü (ışıklar ~8 Hz)
                self._mob_widget("xground", pygame.Rect(0, VIRTUAL_H - 250, VIRTUAL_W, 250), 0.12,
                                 lambda s_, d_, c_: self.xmas.draw_ground(s_), dt, False)
            else:
                self.xmas.draw_ground(canvas)
        if MOBILE:
            # Telefon: ışık dizisi + logo hazır görüntüden (saniyede ~10
            # tazelenir)
            self._mob_widget("top", pygame.Rect(0, 0, VIRTUAL_W, 262), 0.1,
                             lambda s_, d_, c_: (self._draw_new_year_banner(s_), self._draw_menu_logo(s_)),
                             dt, False)
        else:
            self._draw_new_year_banner(canvas)
            self._draw_menu_logo(canvas)

        # ---- elmas + rekor: tek satır ----
        gem_txt = L("ui.gems", fmt_num(self.save.get_gems()))
        best = self.save.data.get("stats", {}).get("best_score", 0)
        best_wave = self.save.data.get("stats", {}).get("best_wave", 0)
        best_txt = L("ui.best_line", fmt_num(best), best_wave)
        gw = coin_label_width(gem_txt, 17, 9, gap=7)
        bw_ = text_width(best_txt, 13)
        x0 = VIRTUAL_W / 2 - (gw + 30 + bw_) / 2
        draw_coin_label(canvas, x0 + gw / 2, 214, gem_txt, GEM_COLOR, 17, icon="gem",
                        icon_r=9, gap=7)
        circle_aa(canvas, x0 + gw + 15, 214, 2.5, (110, 112, 140))
        draw_text(canvas, best_txt, (x0 + gw + 30, 214 - text_height(13) / 2), 13, TEXT_DIM)

        # zorluk seçici
        dr = pygame.Rect(0, 0, 260, 32)
        dr.center = (VIRTUAL_W / 2, 248)
        hover = dr.collidepoint(mouse_pos)
        panel(canvas, dr, bg=(60, 44, 74) if hover else (47, 35, 58), edge=(72, 58, 84), alpha=235, radius=9, edge_w=2)
        draw_text(canvas, L("ui.difficulty", LX("diff." + self.diff, DIFF_LABEL[self.diff])), dr.center, 15, (218, 196, 250), bold=True, center=True, shadow=False)
        if clicked and hover:
            self.cycle_diff()
        draw_text(canvas, LX("diffd." + self.diff, DIFF_DESC[self.diff]), (VIRTUAL_W / 2, 280), 11, TEXT_DIM, center=True, shadow=False)

        if MOBILE:
            self._mob_widget("loadout", pygame.Rect(0, 280, 260, 300), 0.2,
                             lambda s_, d_, c_: self._draw_loadout_panel(s_, d_, mouse_pos, c_),
                             dt, clicked)
        else:
            self._draw_loadout_panel(canvas, dt, mouse_pos, clicked)

        for b in self.menu_buttons:
            b.update(mouse_pos, dt)
            b.draw(canvas)
            if clicked:
                b.click(mouse_pos)
        if self.xmas:
            for i, b in enumerate(self.menu_buttons):
                g = b.anim * 4
                self.xmas.draw_cap(canvas, b.rect.inflate(g, g), seed=i)
        self._draw_event_snowman(canvas, mouse_pos, clicked)
        self._menu_corner_buttons(canvas, mouse_pos, clicked)

        # Tuşlar zaten nasıl oynanır'da; sürüm ve bağlantı durumu yalnızca sol
        # altta, göze batmayan tek bir satırda duruyor.
        ver_col = GREEN if self.online.enabled else (92, 96, 118)
        if self.xmas:
            ver_col = scale_col(ver_col, 0.55)       # kar zemininde okunsun
        draw_text(canvas, f"v{GAME_VERSION}", (VIRTUAL_W / 2, VIRTUAL_H - 16), 11,
                  ver_col, center=True, shadow=False)

        # ---- şaibeli kayıt uyarısı ----
        # Oyuncu neden sıralamaya giremediğini sonuç ekranında değil, burada
        # öğrensin; sessizce engellemek "oyun bozuk" hissi verirdi.
        if self.save.is_tainted():
            wr = pygame.Rect(0, 0, 560, 46)
            wr.center = (VIRTUAL_W / 2, 300)
            panel(canvas, wr, bg=(44, 18, 22), edge=(92, 44, 48), alpha=238, radius=10, edge_w=2)
            draw_icon(canvas, wr.x + 24, wr.centery, "shield", RED, 9)
            draw_text(canvas, L("ui.world_locked"), (wr.x + 40, wr.y + 7), 13, RED,
                      bold=True, shadow=False)
            draw_text(canvas, self.save.taint_text(), (wr.x + 40, wr.y + 25), 10,
                      (212, 158, 158), shadow=False)

        # ---- sağ üst: hesap çipi ----
        self.draw_account_chip(canvas, dt, mouse_pos, clicked)

        # ---- sağ: mağaza kartı ----
        if MOBILE:
            _sr = pygame.Rect(self.STORE_CARD_RECT).inflate(150, 60)
            self._mob_widget("store", _sr, 0.12,
                             lambda s_, d_, c_: self.draw_gem_store_card(s_, d_, mouse_pos, c_),
                             dt, clicked)
        else:
            self.draw_gem_store_card(canvas, dt, mouse_pos, clicked)

        self._draw_reward_fx(canvas, dt)
        self._draw_ad_overlay(canvas, dt, mouse_pos, overlay_click)
        self._draw_splash(canvas)

    # ---- hesap çipi (ana menü, sağ üst) ----
    def _mob_widget(self, key, rect, period, fn, dt, clicked):
        """telefon: menünün ağır, süslü bir parçasını hazır görüntüden basar."""
        canvas = self.display.canvas
        rect = rect.clip(canvas.get_rect())
        cache = self.__dict__.setdefault("_mobw", {})
        c = cache.setdefault(key, {"dt": 0.0})
        c["dt"] += dt
        if clicked:
            fn(canvas, c["dt"], True)
            c["dt"] = 0.0
            c["img"] = None
            return
        if c.get("img") is None or self.t - c.get("t", -9) >= period or c.get("rect") != rect:
            work = cache.get("_work")
            if work is None or work.get_size() != canvas.get_size():
                work = pygame.Surface(canvas.get_size(), pygame.SRCALPHA)
                cache["_work"] = work
            work.set_clip(rect)
            work.fill((0, 0, 0, 0), rect)
            global _GLOW_ON_ALPHA
            _GLOW_ON_ALPHA = True
            try:
                fn(work, c["dt"], False)
            finally:
                _GLOW_ON_ALPHA = False
                work.set_clip(None)
            c.update(img=mob_rle(work.subsurface(rect).copy()), t=self.t, rect=rect, dt=0.0)
        canvas.blit(c["img"], rect.topleft)

    def draw_account_chip(self, canvas, dt, mouse_pos, clicked):
        """Sağ üstte küçük bir çip: girişliyse adı, değilse giriş yap."""
        acc = self.account
        # çip hep durur. Yalnızca sunucu adresi hiç ayarlanmamışsa gizleniyor;
        # kapalıysa "SUNUCU KAPALI" yazıp hesap ekranını (ve yeniden dene'yi)
        # açıyor.
        if not acc.enabled:
            return
        inn = acc.logged_in()
        pick = acc.needs_username()
        if inn:
            label = L("ui.pick_name") if pick else acc.display_name()
        elif acc.booting:
            # ilk deneme tutmadıysa sunucu büyük ihtimalle uykudan uyanıyor
            label = L("ui.srv_waking") if getattr(acc, "boot_try", 0) else L("ui.connecting")
        elif not acc.server_ok:
            label = L("ui.acc_offline_chip")
        else:
            label = L("ui.sign_in")
        w = max(150, int(text_width(label, 14, True)) + 62)
        rect = pygame.Rect(VIRTUAL_W - 20 - w, 18, w, 40)
        hover = rect.collidepoint(mouse_pos)
        if inn:
            accent = ORANGE if pick else GREEN
        elif acc.booting:
            accent = (150, 160, 200)
        elif not acc.server_ok:
            accent = (210, 130, 90)
        else:
            accent = CYAN
        panel(canvas, rect, bg=(53, 38, 39) if hover else (38, 28, 29),
              edge=accent if hover else (115, 84, 87), alpha=236, radius=20, edge_w=2)
        ax = rect.x + 24
        circle_aa(canvas, ax, rect.centery, 13, (30, 34, 50))
        ring_aa(canvas, ax, rect.centery, 13, accent, 2)
        if inn and not pick:
            draw_text(canvas, label[:1].upper(), (ax, rect.centery), 14, accent,
                      bold=True, center=True, shadow=False)
        else:
            # küçük insan silueti
            circle_aa(canvas, ax, rect.centery - 4, 4, accent)
            pygame.draw.arc(canvas, accent,
                            pygame.Rect(ax - 7, rect.centery - 2, 14, 14),
                            math.pi * 0.08, math.pi * 0.92, 2)
        draw_text(canvas, label, (rect.x + 44, rect.centery - 8), 14,
                  TEXT if (inn and not pick) else accent, bold=True, shadow=False)
        if acc.busy:
            a = self.t * 5.0
            for i in range(3):
                circle_aa(canvas, rect.right - 26 + i * 7, rect.centery,
                          2.0 + 1.2 * max(0.0, math.sin(a - i * 0.7)), accent)
        if clicked and hover:
            sfx("click", 0.6, 0.0)
            if self.login_mode == "pick" and not acc.needs_username():
                self.login_mode = "in"
            self.login_focus = self._login_field_order()[0]
            acc.status = ""
            self.goto(STATE_LOGIN)

    # ---- mağaza kartı (ana menü, sağ) ----
    # kare kart yerine karakterin paneliyle aynı hizadan başlayıp ekranın
    # dibine inen uzun kart.
    STORE_CARD_RECT = (VIRTUAL_W - 26 - 184, 302, 184, 398)
    SHOWCASE_EVERY = 3.4

    def _showcase_items(self):
        items = []
        for sk in SKINS:
            if sk.get("premium"):
                items.append(("skin", sk))
        for pid in ("pet_dragon", "pet_cat", "pet_ghost", "pet_drone"):
            if pid in PET_BY_ID:
                items.append(("pet", PET_BY_ID[pid]))
        items.append(("pack", max(GEM_PACKS, key=lambda p: p["bonus"])))
        return items

    def _card_body(self, w, h, hover):
        cache = getattr(self, "_card_body_cache", None)
        if cache is None:
            cache = self._card_body_cache = {}
        key = (w, h, hover)
        img = cache.get(key)
        if img is None:
            img = pygame.Surface((w, h), pygame.SRCALPHA)
            img.fill((*((56, 43, 42) if hover else (46, 35, 36)), 250))
            hand_mask(img, 14)
            cache[key] = img
        return img

    def _mini_button(self, canvas, r, label, col, hover, enabled=True, icon=None, text_col=None,
                     size=12):
        """Kart içindeki küçük, düz gövdeli düğme."""
        c = col if enabled else (71, 51, 53)
        if hover and enabled:
            c = lighten(c, 0.18)
        canvas.blit(_button_body(r.w, r.h, c, 1.0 if hover else 0.0, r.h // 2), r.topleft)
        tc = text_col or ((248, 250, 255) if enabled else (150, 154, 176))
        tw = text_width(label, size, True)
        extra = (16 + (size - 12)) if icon else 0
        x0 = r.centerx - (tw + extra) / 2
        if icon == "play":
            cy = r.centery
            poly_aa(canvas, [(x0, cy - 5), (x0, cy + 5), (x0 + 9, cy)], tc)
        elif icon == "gem":
            draw_icon(canvas, x0 + 5, r.centery, "gem", GEM_COLOR, 6 + (size - 12) // 3)
        elif icon == "star":
            draw_icon(canvas, x0 + 5, r.centery, "star", GOLD, 6 + (size - 12) // 3)
        draw_text(canvas, label, (x0 + extra, r.centery - text_height(size, True) / 2), size, tc,
                  bold=True, shadow=enabled)

    def _gift_icon(self, canvas, cx, cy, s, body=(206, 44, 58), ribbon=XMAS_GOLD, t=0.0):
        r = pygame.Rect(0, 0, int(s * 2), int(s * 1.6))
        r.center = (int(cx), int(cy + s * 0.25))
        lid = pygame.Rect(r.x - 2, r.y - int(s * 0.45), r.w + 4, int(s * 0.5))
        pygame.draw.rect(canvas, scale_col(body, 0.75), r, border_radius=3)
        pygame.draw.rect(canvas, body, lid, border_radius=3)
        pygame.draw.rect(canvas, ribbon, pygame.Rect(r.centerx - 2, lid.y, 4, r.bottom - lid.y))
        wob = math.sin(t * 5) * 1.5
        circle_aa(canvas, r.centerx - s * 0.32, lid.y - 2 + wob, s * 0.28, ribbon)
        circle_aa(canvas, r.centerx + s * 0.32, lid.y - 2 - wob, s * 0.28, ribbon)

    def draw_gem_store_card(self, canvas, dt, mouse_pos, clicked):
        """Ana menünün sağındaki mağaza kartı."""
        base = pygame.Rect(self.STORE_CARD_RECT)
        hover = base.collidepoint(mouse_pos)
        if hover and not self.gem_card_was_hover:
            sfx("hover", 0.4, 0.05)
        self.gem_card_was_hover = hover
        self.gem_card_anim += ((1.0 if hover else 0.0) - self.gem_card_anim) * min(1.0, dt * 12)
        self.store_card_t += dt
        rect = base.move(0, -int(self.gem_card_anim * 3))
        accent = GEM_COLOR
        pulse = math.sin(self.t * 2.4) * 0.5 + 0.5
        rw = self.rewards
        handled = False

        canvas.blit(_panel_shadow(rect.w, rect.h, 18), (rect.x - 6, rect.y - 2))
        canvas.blit(self._card_body(rect.w, rect.h, hover), rect.topleft)
        ink_frame(canvas, rect, (74, 66, 86), 18, 2)

        pl, pr_ = rect.x + 12, rect.right - 12

        # ---- başlık ----
        bx, by = rect.x + 28, rect.y + 32
        add_glow(canvas, bx, by, 26, accent, 0.28 + pulse * 0.20)
        for k_ in range(10):
            a = self.t * 0.5 + k_ * math.tau / 10
            thick_line(canvas, (bx + math.cos(a) * 16, by + math.sin(a) * 16),
                       (bx + math.cos(a) * (18.5 + 1.5 * pulse),
                        by + math.sin(a) * (18.5 + 1.5 * pulse)),
                       1.2, scale_col(accent, 0.40 + 0.45 * pulse))
        disc_grad(canvas, bx, by, 13, scale_col(accent, 0.55), (12, 14, 22), 7)
        ring_aa(canvas, bx, by, 13, accent, 2)
        draw_icon(canvas, bx, by, "gem", lighten(accent, 0.3), 9)
        tx = rect.x + 52
        draw_text(canvas, L("ui.store"), (tx, rect.y + 15), 16, accent, bold=True, shadow=True)
        draw_text(canvas, _fit_text(L("ui.store_card_sub"), 10, pr_ - tx), (tx, rect.y + 35), 10,
                  TEXT_DIM, shadow=False)
        if rw.anything_ready():
            # bildirim noktası: alınacak bedava bir şey var
            k = 0.5 + 0.5 * math.sin(self.t * 5)
            add_glow(canvas, rect.right - 8, rect.y + 8, 20, RED, 0.3 + 0.3 * k)
            circle_aa(canvas, rect.right - 8, rect.y + 8, 7, (232, 64, 72))
            draw_text(canvas, "!", (rect.right - 8, rect.y + 8), 11, WHITE, bold=True,
                      center=True, shadow=False)

        # ---- vitrin ----
        items = self._showcase_items()
        idx = int(self.store_card_t / self.SHOWCASE_EVERY) % len(items)
        ph = (self.store_card_t % self.SHOWCASE_EVERY) / self.SHOWCASE_EVERY
        fade = min(1.0, ph / 0.08, (1.0 - ph) / 0.08)
        kind, it = items[idx]
        sc = pygame.Rect(pl, rect.y + 56, pr_ - pl, 128)
        sc_hover = sc.collidepoint(mouse_pos)
        icol = tuple(it.get("color", accent))
        pygame.draw.rect(canvas, (28, 20, 21), sc, border_radius=12)
        prev_clip = canvas.get_clip()
        canvas.set_clip(sc.inflate(-2, -2))
        add_glow(canvas, sc.centerx, sc.y + 50, 90, icol, 0.22 * fade + 0.05)
        for k_ in range(8):
            a = self.t * 0.35 + k_ * math.tau / 8
            p0 = (sc.centerx, sc.y + 50)
            thick_line(canvas, p0, (p0[0] + math.cos(a) * 90, p0[1] + math.sin(a) * 90), 6,
                       scale_col(icol, 0.18 * fade + 0.05), cap=False)
        cy_ = sc.y + 50 + math.sin(self.t * 2) * 2
        if kind == "skin":
            draw_skin_preview(canvas, it, sc.centerx, cy_, self.t, r=int(16 + 4 * fade))
            tag, price = L("ui.showcase_premium"), None
            name = skin_name(it)
        elif kind == "pet":
            draw_pet(canvas, it["kind"], sc.centerx, cy_ + 4, int(10 + 5 * fade), self.t, face=1,
                     moving=True, col=it["color"], acc=it["accent"])
            tag, price = L("ui.showcase_pet"), None
            name = it["name"]
        else:
            for j in range(4):
                ang = -math.pi / 2 + (j - 1.5) * 0.55
                draw_icon(canvas, sc.centerx + math.cos(ang) * 22, cy_ + 6 + math.sin(ang) * 8,
                          "gem", it["color"], int(10 + 3 * fade))
            tag, price, name = L("ui.tab_gems"), None, fmt_num(gem_pack_total(it)) + " " + L("ui.gem")
        canvas.set_clip(prev_clip)
        ink_frame(canvas, sc, lighten(icol, 0.2) if sc_hover else scale_col(icol, 0.7), 12, 2)
        # etiket şeridi
        tg = _fit_text(tag, 9, sc.w - 20, bold=True)
        tgw = text_width(tg, 9, True) + 16
        tr = pygame.Rect(0, 0, int(tgw), 16)
        tr.midtop = (sc.centerx, sc.y - 6)
        pygame.draw.rect(canvas, PURPLE if kind != "pack" else (40, 110, 155), tr, border_radius=8)
        draw_text(canvas, tg, tr.center, 9, WHITE, bold=True, center=True, shadow=False)
        draw_text(canvas, _fit_text(name, 13, sc.w - 12, bold=True), (sc.centerx, sc.y + 86), 13,
                  TEXT, bold=True, center=True, alpha=int(255 * max(0.3, fade)))
        if price is not None:
            draw_coin_label(canvas, sc.centerx, sc.y + 108, fmt_num(price), GEM_COLOR, 13,
                            icon="gem", icon_r=7, gap=5)
        else:
            draw_text(canvas, it.get("price_hint", ""), (sc.centerx, sc.y + 108), 13, GOLD,
                      bold=True, center=True)
        # nokta göstergesi
        n = len(items)
        dx0 = sc.centerx - (n - 1) * 7 / 2
        for j in range(n):
            circle_aa(canvas, dx0 + j * 7, sc.bottom + 8, 2.4 if j == idx else 1.6,
                      accent if j == idx else (70, 78, 104))

        # ---- ücretsiz elmas: reklam ----
        y = rect.y + 202
        free_lbl = _fit_text(L("ui.free_gems"), 11, pr_ - pl, bold=True)
        draw_text(canvas, free_lbl, (pl, y), 11, (140, 230, 160), bold=True, shadow=False)
        ab = pygame.Rect(pl, y + 18, pr_ - pl, 32)
        ab_hover = ab.collidepoint(mouse_pos)
        ready = rw.ad_ready()
        if ready:
            k = 0.5 + 0.5 * math.sin(self.t * 3.2)
            add_glow(canvas, ab.centerx, ab.centery, 70, (90, 220, 120), 0.10 + 0.10 * k)
            self._mini_button(canvas, ab, L("ui.watch_plus", AD_REWARD_GEMS), (54, 150, 86),
                              ab_hover, icon="play")
            sub = L("ui.ads_left", rw.ads_left(), AD_DAILY_LIMIT)
        elif rw.ads_left() > 0:
            self._mini_button(canvas, ab, L("ui.ad_wait", fmt_clock(rw.ad_cooldown())),
                              (54, 150, 86), False, enabled=False)
            sub = L("ui.ads_left", rw.ads_left(), AD_DAILY_LIMIT)
        else:
            self._mini_button(canvas, ab, L("ui.ad_tomorrow", fmt_clock(seconds_to_midnight())),
                              (54, 150, 86), False, enabled=False)
            sub = ""
        ft = L("ui.free_tag")
        fw = text_width(ft, 9, True) + 12
        if ready and text_width(free_lbl, 11, True) + fw + 4 < pr_ - pl:
            # bedava etiketi düğmenin köşesine iğneli (yazıyla çakışmıyorsa)
            fr = pygame.Rect(ab.right - int(fw) + 6, ab.y - 9, int(fw), 15)
            pygame.draw.rect(canvas, (210, 56, 66), fr, border_radius=7)
            ink_frame(canvas, fr, (255, 150, 150), 7, 1)
            draw_text(canvas, ft, fr.center, 9, WHITE, bold=True, center=True, shadow=False)
        if sub:
            draw_text(canvas, sub, (ab.centerx, ab.bottom + 11), 10, TEXT_DIM, center=True,
                      shadow=False)
        if ready:
            touch_ad_zone(ab)
        if clicked and ab_hover:
            handled = True
            if ready:
                self._ad_start()
            else:
                sfx("error", 0.4, 0.0)

        # ---- günlük hediye ----
        y = rect.y + 274
        pygame.draw.line(canvas, (91, 66, 68), (pl, y - 6), (pr_, y - 6), 1)
        gift_ok = rw.gift_ready()
        self._gift_icon(canvas, pl + 14, y + 22, 11, t=self.t if gift_ok else 0.0)
        draw_text(canvas, _fit_text(L("ui.daily_gift"), 11, pr_ - pl - 34, bold=True),
                  (pl + 34, y + 2), 11, GOLD, bold=True, shadow=False)
        gb = pygame.Rect(pl + 34, y + 20, pr_ - pl - 34, 28)
        gb_hover = gb.collidepoint(mouse_pos)
        if gift_ok:
            self._mini_button(canvas, gb, L("ui.claim", rw.gift_amount()), (176, 128, 40),
                              gb_hover, icon="gem")
        else:
            self._mini_button(canvas, gb, L("ui.claimed_in", fmt_clock(seconds_to_midnight())),
                              (176, 128, 40), False, enabled=False)
        if clicked and gb_hover:
            handled = True
            if gift_ok:
                self._claim_gift(gb.centerx, gb.y)
            else:
                sfx("error", 0.4, 0.0)

        # ---- mağazaya git ----
        cta = pygame.Rect(pl, rect.bottom - 44, pr_ - pl, 32)
        cta_hover = cta.collidepoint(mouse_pos)
        self._mini_button(canvas, cta, L("ui.store_go"), (40, 110, 160), cta_hover or
                          (hover and not (ab_hover or gb_hover)))

        if clicked and hover and not handled:
            if sc_hover:
                self.store_tab = {"skin": "skins", "pet": "pets"}.get(kind, "gems")
            else:
                self.store_tab = "free" if rw.anything_ready() else "gems"
            self.goto(STATE_GEM_STORE)
            sfx("click", 0.6, 0.0)

    # ---- ücretsiz elmas: reklam / hediye / kutlama ----
    def _ad_start(self):
        if self.ad_play is not None or not self.rewards.ad_ready():
            return False
        self.rewards.begin_ad()
        try:
            # reklam = 90 sn tanıtım filmi (yoksa 2 dk'lık oyun turu).
            self.house_ad = make_house_ad(self)
        except Exception as e:          # film kurulamazsa ödül yine verilebilsin
            print("Reklam filmi kurulamadı:", e)
            self.house_ad = None
        self.ad_play = 0.0
        self.ad_done = False
        sfx("click", 0.6, 0.0)
        return True

    def _ad_finish(self, reward):
        """Reklamı kapatır. reward=True ve sonuna kadar izlendiyse ödül verilir."""
        if self.ad_play is None:
            return
        if reward and self.ad_done:
            self.rewards.grant_ad(lambda amt, err: self._reward_result(
                amt, err, VIRTUAL_W / 2, VIRTUAL_H / 2))
        self.ad_play = None
        self.ad_done = False
        ad = getattr(self, "house_ad", None)
        if ad is not None and hasattr(ad, "close"):
            ad.close()
        self.house_ad = None            # gölge oyun bellekten atılsın

    def _claim_gift(self, x, y):
        self.rewards.claim_gift(lambda amt, err: self._reward_result(amt, err, x, y))

    def _reward_result(self, amount, err, x, y):
        """Ödül sonucu (sunucudan gelebilir - arka plandaki iş parçacığından çağrılır; yalnızca listeye ekler"""
        if amount:
            self._spawn_reward_fx(x, y, amount)
        elif err:
            self.reward_fx.append([x, y, 0.0, 0, str(err)])
            sfx("error", 0.6, 0.0)

    def _spawn_reward_fx(self, x, y, amount):
        self.reward_fx.append([x, y, 0.0, int(amount)])
        sfx("buy", 1.0, 0.0)

    def _draw_reward_fx(self, canvas, dt):
        """"+250 ELMAS!" yazısı ve dört bir yana saçılan elmaslar."""
        alive = []
        for fx in list(self.reward_fx):
            fx[2] += dt
            x, y, t, amount = fx[:4]
            if len(fx) > 4:                 # hata bildirimi (ödül verilmedi)
                if t > 3.0:
                    continue
                alive.append(fx)
                a_ = int(255 * clamp((3.0 - t) / 0.5, 0.0, 1.0))
                msg = _fit_text(fx[4], 16, 760, bold=True)
                r_ = pygame.Rect(0, 0, int(text_width(msg, 16, True) + 40), 40)
                r_.center = (int(VIRTUAL_W / 2), int(VIRTUAL_H / 2 + 120))
                bs = pygame.Surface(r_.size, pygame.SRCALPHA)
                pygame.draw.rect(bs, (60, 18, 24, int(230 * a_ / 255)), bs.get_rect(), border_radius=10)
                canvas.blit(bs, r_.topleft)
                draw_text(canvas, msg, r_.center, 16, (255, 170, 170), bold=True, center=True,
                          alpha=a_)
                continue
            if t > 1.9:
                continue
            alive.append(fx)
            k = clamp(t / 1.9, 0.0, 1.0)
            add_glow(canvas, x, y, 140 * (1 - k * 0.5), GEM_COLOR, 0.35 * (1 - k))
            for i in range(14):
                a = i * math.tau / 14 + 0.3
                d = ease_out_cubic(min(1.0, t / 0.9)) * (70 + (i % 3) * 22)
                gx, gy = x + math.cos(a) * d, y + math.sin(a) * d + 40 * k * k
                if k < 0.85:
                    draw_icon(canvas, gx, gy, "gem", GEM_COLOR, int(7 - 3 * k))
            pop = 1.0 + 0.25 * max(0.0, 1.0 - t / 0.25)
            ty_ = y - 30 - 50 * ease_out_cubic(k)
            a_ = int(255 * clamp((1.9 - t) / 0.5, 0.0, 1.0))
            draw_text(canvas, L("ui.gems_plus", amount), (x, ty_), int(26 * pop), GEM_COLOR,
                      bold=True, center=True, alpha=a_)
        # Yerinde temizle: sunucu cevabı arka plandan bu sırada yeni bir kayıt
        # eklemiş olabilir; listeyi baştan atamak onu kaybettirirdi.
        keep = set(id(f) for f in alive)
        self.reward_fx[:] = [f for f in self.reward_fx if id(f) in keep or f[2] == 0.0]

    def _draw_ad_overlay(self, canvas, dt, mouse_pos, clicked):
        """Ödüllü reklam penceresi."""
        if self.ad_play is None:
            return
        self.ad_play += dt
        t = self.ad_play
        AD_LENGTH = float(getattr(getattr(self, "house_ad", None), "LENGTH", None) or globals()["AD_LENGTH"])
        if t >= AD_LENGTH:
            self.ad_done = True
        ov = pygame.Surface((VIRTUAL_W, VIRTUAL_H), pygame.SRCALPHA)
        ov.fill((4, 4, 10, int(235 * min(1.0, t / 0.25))))
        canvas.blit(ov, (0, 0))
        vid = pygame.Rect(0, 0, 960, 540)
        vid.center = (VIRTUAL_W // 2, VIRTUAL_H // 2 - 40)
        pygame.draw.rect(canvas, (0, 0, 0), vid.inflate(8, 8), border_radius=14)
        ad = getattr(self, "house_ad", None)
        if ad is not None and hasattr(ad, "place"):
            ad.place(vid)
            if getattr(ad, "muted", False) and not self.ad_done:
                # Tarayıcı filmi sessiz başlattıysa: dokununca ses açılır.
                ub = pygame.Rect(vid.right - 190, vid.bottom + 6, 190, 30)
                touch_ad_zone(ub, "unmute")
                self._mini_button(canvas, ub, _tc("SESİ AÇ", "UNMUTE", "SONIDO", "TON AN", "ЗВУК"),
                                  (40, 110, 160), ub.collidepoint(mouse_pos))
            if getattr(ad, "failed", False):
                draw_text(canvas, _tc("Film yüklenemedi, süre yine de sayılıyor",
                                      "Video failed to load - the timer still counts"),
                          vid.center, 18, TEXT_DIM, center=True)
        if ad is not None:
            try:
                ad.update(dt)
                frame = ad.render()
                canvas.blit(pygame.transform.smoothscale(frame, vid.size), vid.topleft)
            except Exception as e:      # film bozulursa pencere boş kalsın, oyun çökmesin
                print("Reklam filmi hatası:", e)
                self.house_ad = None
        ink_frame(canvas, vid.inflate(8, 8), (120, 87, 90), 14, 2)
        # üst köşeler: reklam etiketi + geri sayım
        lab = L("ui.ad_label")
        lr = pygame.Rect(vid.x + 12, vid.y + 12, int(text_width(lab, 11, True) + 18), 20)
        pygame.draw.rect(canvas, (250, 200, 60), lr, border_radius=5)
        draw_text(canvas, lab, lr.center, 11, (30, 24, 10), bold=True, center=True, shadow=False)
        rx, ry = vid.right - 30, vid.y + 30
        circle_aa(canvas, rx, ry, 17, (10, 10, 16))
        frac = clamp(t / AD_LENGTH, 0.0, 1.0)
        if frac < 1.0:
            pygame.draw.arc(canvas, (250, 200, 60), pygame.Rect(rx - 16, ry - 16, 32, 32),
                            math.pi / 2, math.pi / 2 + math.tau * frac, 3)
            draw_text(canvas, str(int(math.ceil(AD_LENGTH - t))), (rx, ry), 14, WHITE, bold=True,
                      center=True, shadow=False)
        else:
            ring_aa(canvas, rx, ry, 16, GREEN, 3)
            thick_line(canvas, (rx - 7, ry), (rx - 2, ry + 6), 3, GREEN)
            thick_line(canvas, (rx - 2, ry + 6), (rx + 8, ry - 6), 3, GREEN)
        # alt ilerleme çubuğu
        pygame.draw.rect(canvas, (48, 38, 39), pygame.Rect(vid.x, vid.bottom - 5, vid.w, 5))
        pygame.draw.rect(canvas, (250, 200, 60), pygame.Rect(vid.x, vid.bottom - 5, int(vid.w * frac), 5))

        by = vid.bottom + 20
        if self.ad_done:
            b = pygame.Rect(0, 0, 300, 46)
            b.center = (VIRTUAL_W // 2, by + 14)
            hov = b.collidepoint(mouse_pos)
            k = 0.5 + 0.5 * math.sin(self.t * 4)
            add_glow(canvas, b.centerx, b.centery, 170, GREEN, 0.14 + 0.10 * k)
            self._mini_button(canvas, b, L("ui.ad_claim", AD_REWARD_GEMS), (54, 150, 86), hov,
                              icon="gem")
            if clicked and hov:
                self._ad_finish(True)
        else:
            draw_text(canvas, L("ui.ad_reward_in", int(math.ceil(AD_LENGTH - t))),
                      (VIRTUAL_W // 2, by), 14, (250, 210, 110), bold=True, center=True)
            cb = pygame.Rect(0, 0, 190, 30)
            cb.center = (VIRTUAL_W // 2, by + 34)
            hov = cb.collidepoint(mouse_pos)
            pygame.draw.rect(canvas, (44, 40, 52) if hov else (44, 33, 34), cb, border_radius=8)
            ink_frame(canvas, cb, (110, 100, 120), 8, 1)
            draw_text(canvas, L("ui.ad_forfeit"), cb.center, 12, TEXT_DIM, bold=True,
                      center=True, shadow=False)
            if clicked and hov:
                self._ad_finish(False)
                sfx("click", 0.5, 0.0)

    # ---- elmas marketi (satın alma ekranı) ----
    def _buy_gem_pack(self, pack):
        """Bir elmas paketi satın almayı başlatır."""
        def done(ok, msg):
            self.gem_msg = msg
            self.gem_msg_ok = ok
            self.gem_msg_timer = 3.2
            if ok and FAKE_PURCHASE:
                # Yalnızca test kipinde elmas yerel olarak eklenir.
                self.save.add_gems(gem_pack_total(pack))
                self.save.progress_changed()
            # Gerçek satın almada elmaslar sunucuda yazılır; sipariş teslim
            # edilince hesabın ilerlemesi zaten indirildi (çift ekleme yok).
            if ok:
                sfx("buy", 1.0, 0.0)
        self.purchase.begin_purchase(pack, on_done=done)

    def _refresh_gems_from_server(self):
        """Satın alma sonrası elmas sayısını sunucudan tazeler."""
        sid = self.purchase.steam_id()
        if not (sid and self.online.enabled):
            return
        async def work():
            try:
                data = await http_json(ONLINE_API_URL.rstrip("/") + "/get_player",
                                       {"steam_id": sid}, 10)
                if data.get("success"):
                    gems = int(data["data"].get("gems", self.save.get_gems()))
                    self.save.data["gems"] = max(0, gems)
                    self.save.save()
            except Exception:
                pass
        spawn(work)

    def _buy_premium_skin(self, sk):
        """Premium skini gerçek parayla satın almayı başlatır."""
        pack = dict(id=sk["item_id"], gems=0, bonus=0,
                    price_hint=sk.get("price_hint", ""), tag="", color=sk["color"])

        def done(ok, msg):
            self.gem_msg = msg
            self.gem_msg_ok = ok
            self.gem_msg_timer = 3.2
            if ok and FAKE_PURCHASE:
                # Yalnızca test kipinde skin yerel olarak açılır.
                self.save.grant_skin(sk["id"])
                self.save.equip_skin(sk["id"])
                self.gem_msg = f"TEST: {sk['name']} açıldı ve kuşanıldı"
            elif ok:
                # Gerçek satın almada sahiplik sunucuda yazılır; teslimde
                # hesabın ilerlemesi indirildi. Yeni skini hemen kuşan.
                if self.save.owns_skin(sk["id"]):
                    self.save.equip_skin(sk["id"])
                    self.selected_skin = sk["id"]
            if ok:
                sfx("buy", 1.0, 0.0)

        self.purchase.begin_purchase(pack, on_done=done)

    def _draw_payment_wait(self, canvas, mouse_pos, clicked):
        """Tarayıcıda ödeme beklenirken ekranın ortasındaki kutu."""
        pb = self.purchase
        if not pb.waiting():
            return
        dim = pygame.Surface((VIRTUAL_W, VIRTUAL_H), pygame.SRCALPHA)
        dim.fill((17, 12, 12, 170))
        canvas.blit(dim, (0, 0))
        box = pygame.Rect(0, 0, 560, 250)
        box.center = (VIRTUAL_W // 2, VIRTUAL_H // 2)
        add_glow(canvas, box.centerx, box.centery, 260, CYAN, 0.12)
        panel(canvas, box, bg=(44, 32, 33), alpha=252, radius=18, edge_w=2)
        draw_text(canvas, L("ui.shop_waiting"), (box.centerx, box.y + 28), 22, CYAN, bold=True,
                  center=True)
        name = (pb.order or {}).get("name", "")
        if name:
            draw_text(canvas, name, (box.centerx, box.y + 60), 14, GOLD, bold=True, center=True)
        # dönen halka
        cx, cy = box.centerx, box.y + 108
        for j in range(12):
            a = self.t * 4.0 + j * math.tau / 12
            al = (j + 1) / 12.0
            blit_disc(canvas, cx + math.cos(a) * 18, cy + math.sin(a) * 18, 3.2,
                      lighten(CYAN, 0.3), int(255 * al))
        for j, ln in enumerate(wrap_text(L("ui.shop_wait_note"), 12, box.w - 60)[:2]):
            draw_text(canvas, ln, (box.centerx, box.y + 142 + j * 17), 12, TEXT_DIM, center=True,
                      shadow=False)
        b1 = pygame.Rect(box.x + 40, box.bottom - 58, 230, 38)
        b2 = pygame.Rect(box.right - 270, box.bottom - 58, 230, 38)
        h1, h2 = b1.collidepoint(mouse_pos), b2.collidepoint(mouse_pos)
        self._mini_button(canvas, b1, L("ui.shop_reopen"), (40, 110, 160), h1)
        self._mini_button(canvas, b2, L("ui.shop_stop"), (90, 70, 90), h2)
        touch_link(b1, (pb.order or {}).get("url"))
        if clicked and h1:
            pb.open_page()
            sfx("click", 0.6, 0.0)
        elif clicked and h2:
            pb.cancel_wait()
            sfx("click", 0.5, 0.0)

    def _store_buy_button(self, rect, on_buy, color, hover_color, text_size=14, price=""):
        """Mağaza kartlarının ortak düğmesi."""
        pb = self.purchase
        if pb.available() and not pb.waiting():
            return Button(rect, price or L("ui.buy_now"), on_buy, color=color, hover_color=hover_color,
                          enabled=True, text_size=text_size + (2 if price else 0))
        if pb.enabled and not pb.logged_in() and not FAKE_PURCHASE:
            return Button(rect, L("ui.sign_in"), lambda: self.goto(STATE_LOGIN),
                          color=(40, 110, 155), hover_color=(58, 145, 195), enabled=True,
                          text_size=text_size)
        label = price or ("..." if pb.enabled is None else L("ui.soon"))
        return Button(rect, label, lambda: None, color=(64, 48, 49),
                      hover_color=(64, 48, 49), enabled=False, text_size=text_size)

    def _store_tabs(self, canvas, mouse_pos, clicked):
        """Mağaza sekmeleri: simgeli, ortalanmış hap şerit."""
        tabs = [("free", L("ui.tab_free"), "star", (110, 220, 140)),
                ("gems", L("ui.tab_gems"), "gem", GEM_COLOR),
                ("skins", L("ui.premium_skins"), "shield", (200, 150, 255)),
                ("pets", L("ui.tab_pets"), "heart", (255, 150, 190))]
        tw, th, gap = 214, 40, 10
        total = len(tabs) * tw + (len(tabs) - 1) * gap
        x0 = (VIRTUAL_W - total) / 2
        bar = pygame.Rect(int(x0 - 8), 82, int(total + 16), th + 12)
        sh = pygame.Surface(bar.size, pygame.SRCALPHA)
        pygame.draw.rect(sh, (26, 19, 19, 200), sh.get_rect(), border_radius=26)
        canvas.blit(sh, bar.topleft)
        for i, (key, label, icon, acc) in enumerate(tabs):
            r = pygame.Rect(int(x0 + i * (tw + gap)), 88, tw, th)
            active = self.store_tab == key
            hov = r.collidepoint(mouse_pos)
            if active:
                add_glow(canvas, r.centerx, r.centery, tw * 0.55, acc, 0.16)
                canvas.blit(_button_body(r.w, r.h, scale_col(acc, 0.45), 1.0, r.h // 2), r.topleft)
                ink_frame(canvas, r, None, r.h // 2, 2)
            elif hov:
                pygame.draw.rect(canvas, (68, 50, 51), r, border_radius=r.h // 2)
            lw = text_width(label, 14, True)
            lx = r.centerx - (lw + 22) / 2
            draw_icon(canvas, lx + 8, r.centery, icon, acc if (active or hov) else scale_col(acc, 0.6), 8)
            draw_text(canvas, _fit_text(label, 14, tw - 40, bold=True), (lx + 22, r.centery - 9), 14,
                      WHITE if active else (TEXT if hov else TEXT_DIM), bold=True, shadow=active)
            if key == "free" and self.rewards.anything_ready():
                k = 0.5 + 0.5 * math.sin(self.t * 5)
                add_glow(canvas, r.right - 10, r.y + 6, 18, RED, 0.25 + 0.3 * k)
                circle_aa(canvas, r.right - 10, r.y + 6, 6, (232, 64, 72))
            if clicked and hov and not active:
                self.store_tab = key
                sfx("click", 0.5, 0.0)

    def _store_status(self, canvas, mouse_pos, clicked, rect):
        """Alt şeritteki tek satırlık durum çipi."""
        pb = self.purchase
        txt, col, spin, act = None, CYAN, False, None
        if FAKE_PURCHASE:
            txt, col = L("ui.test_mode"), (255, 150, 90)
        elif pb.busy and not pb.waiting():
            txt, spin = pb.status or L("ui.processing"), True
        elif self.store_tab == "free":
            return False
        elif not pb.api_url:
            txt, col = L("ui.shop_no_server"), (225, 190, 110)
        elif pb.enabled is None:
            txt, spin = pb.unavailable_reason(), True
        elif not pb.enabled:
            txt, col = L("ui.st_closed"), (230, 150, 120)
        elif not pb.logged_in():
            txt, col, act = L("ui.st_login"), GOLD, "login"
        if not txt:
            return False
        tw = text_width(txt, 14, True)
        bw = int(tw + (40 if spin else 28) + (130 if act else 0))
        r = pygame.Rect(0, 0, bw, 38)
        r.center = rect.center
        sh = pygame.Surface(r.size, pygame.SRCALPHA)
        pygame.draw.rect(sh, (30, 22, 23, 225), sh.get_rect(), border_radius=19)
        canvas.blit(sh, r.topleft)
        ink_frame(canvas, r, scale_col(col, 0.8), 19, 2)
        x = r.x + 16
        if spin:
            for j in range(8):
                a = self.t * 5.0 + j * math.tau / 8
                blit_disc(canvas, x + 7 + math.cos(a) * 7, r.centery + math.sin(a) * 7, 1.8,
                          col, int(255 * (j + 1) / 8))
            x += 24
        draw_text(canvas, txt, (x, r.centery - 9), 14, col, bold=True, shadow=False)
        if act == "login":
            b = pygame.Rect(r.right - 126, r.y + 5, 118, 28)
            hv = b.collidepoint(mouse_pos)
            self._mini_button(canvas, b, L("ui.sign_in"), (40, 110, 160), hv, size=12)
            if clicked and hv:
                self.goto(STATE_LOGIN)
                sfx("click", 0.6, 0.0)
                return True
        return False

    def _draw_free_gems(self, canvas, dt, mouse_pos, clicked):
        """Mağaza > ücretsiz: reklam, günlük hediye, başarım ödülleri."""
        rw = self.rewards
        card_w, card_h, gap = 340, 330, 24
        x0 = (VIRTUAL_W - (3 * card_w + 2 * gap)) / 2
        y0 = 160
        t = self.t

        def card(i, col, title):
            r = pygame.Rect(int(x0 + i * (card_w + gap)), y0, card_w, card_h)
            hov = r.collidepoint(mouse_pos)
            add_glow(canvas, r.centerx, r.y + 90, 170, col, 0.08 + (0.05 if hov else 0.0))
            canvas.blit(store_card_body(r.w, r.h, col, hov, False), r.topleft)
            draw_text(canvas, title, (r.centerx, r.y + 28), 20, lighten(col, 0.2), bold=True, center=True)
            return r

        # ---- 1) reklam ----
        gcol = (110, 220, 140)
        r = card(0, gcol, L("ui.watch_ad"))
        cx, cy = r.centerx, r.y + 112
        ready = rw.ad_ready()
        k = 0.5 + 0.5 * math.sin(t * 3)
        for j in range(12):
            a = t * 0.4 + j * math.tau / 12
            thick_line(canvas, (cx + math.cos(a) * 46, cy + math.sin(a) * 46),
                       (cx + math.cos(a) * (58 + 4 * k), cy + math.sin(a) * (58 + 4 * k)), 2,
                       scale_col(gcol, 0.35 + 0.4 * k), cap=False)
        add_glow(canvas, cx, cy, 90, gcol, 0.25 + 0.15 * k)
        disc_grad(canvas, cx, cy, 40, (70, 170, 100), (24, 60, 40), 8)
        ring_aa(canvas, cx, cy, 40, lighten(gcol, 0.3), 3)
        poly_aa(canvas, [(cx - 12, cy - 18), (cx - 12, cy + 18), (cx + 20, cy)], (240, 255, 244))
        for j in range(3):
            a = -math.pi / 2 + (j - 1) * 0.7
            draw_icon(canvas, cx + 62 + math.cos(a) * 8 + j * 4, cy - 30 + j * 14 + math.sin(t * 3 + j) * 2,
                      "gem", GEM_COLOR, 8)
        draw_text(canvas, "+" + str(AD_REWARD_GEMS), (cx - 88, cy - 10), 22, GEM_COLOR, bold=True,
                  center=True)
        # günlük hak: 5 küçük kutucuk
        used = rw.ads_used()
        pw = 22
        px0 = cx - (AD_DAILY_LIMIT * pw + (AD_DAILY_LIMIT - 1) * 6) / 2
        for j in range(AD_DAILY_LIMIT):
            pr = pygame.Rect(int(px0 + j * (pw + 6)), r.y + 210, pw, 10)
            pygame.draw.rect(canvas, (102, 74, 77) if j < used else gcol, pr, border_radius=5)
        b = pygame.Rect(r.x + 24, r.bottom - 56, r.w - 48, 40)
        bh = b.collidepoint(mouse_pos)
        if ready:
            self._mini_button(canvas, b, L("ui.watch_plus", AD_REWARD_GEMS), (54, 150, 86), bh,
                              icon="play")
        elif rw.ads_left() > 0:
            self._mini_button(canvas, b, L("ui.ad_wait", fmt_clock(rw.ad_cooldown())), (54, 150, 86),
                              False, enabled=False)
        else:
            self._mini_button(canvas, b, L("ui.ad_tomorrow", fmt_clock(seconds_to_midnight())),
                              (54, 150, 86), False, enabled=False)
        if ready:
            touch_ad_zone(b)
        if clicked and bh and ready:
            self._ad_start()

        # ---- 2) günlük hediye ----
        r = card(1, GOLD, L("ui.daily_gift"))
        gift_ok = rw.gift_ready()
        today = rw.gift_day_index()
        n = len(DAILY_GIFT_GEMS)
        tw_, th_ = 38, 64
        tx0 = r.centerx - (n * tw_ + (n - 1) * 4) / 2
        for j, amt in enumerate(DAILY_GIFT_GEMS):
            tr = pygame.Rect(int(tx0 + j * (tw_ + 4)), r.y + 60, tw_, th_)
            got = j < today or (j == today and not gift_ok)
            cur = j == today and gift_ok
            bg = (52, 44, 22) if cur else ((26, 36, 30) if got else (46, 33, 34))
            pygame.draw.rect(canvas, bg, tr, border_radius=8)
            ink_frame(canvas, tr, GOLD if cur else (90, 160, 110) if got else (93, 69, 71), 8, 2 if cur else 1)
            draw_text(canvas, str(j + 1), (tr.centerx, tr.y + 10), 10,
                      GOLD if cur else TEXT_DIM, bold=True, center=True, shadow=False)
            if got:
                thick_line(canvas, (tr.centerx - 7, tr.y + 33), (tr.centerx - 2, tr.y + 39), 3, GREEN)
                thick_line(canvas, (tr.centerx - 2, tr.y + 39), (tr.centerx + 8, tr.y + 27), 3, GREEN)
            else:
                big = j == n - 1
                self._gift_icon(canvas, tr.centerx, tr.y + 33, 9 if big else 7,
                                body=(150, 70, 200) if big else (206, 44, 58),
                                t=t if cur else 0.0)
            draw_text(canvas, str(amt), (tr.centerx, tr.bottom - 11), 10,
                      GEM_COLOR if not got else (110, 170, 140), bold=True, center=True, shadow=False)
        self._gift_icon(canvas, r.centerx, r.y + 170, 22, t=t if gift_ok else 0.0)
        if gift_ok:
            add_glow(canvas, r.centerx, r.y + 168, 70, GOLD, 0.18 + 0.12 * math.sin(t * 3))
        b = pygame.Rect(r.x + 24, r.bottom - 56, r.w - 48, 40)
        bh = b.collidepoint(mouse_pos)
        if gift_ok:
            self._mini_button(canvas, b, L("ui.claim", rw.gift_amount()), (176, 128, 40), bh, icon="gem")
        else:
            self._mini_button(canvas, b, L("ui.claimed_in", fmt_clock(seconds_to_midnight())),
                              (176, 128, 40), False, enabled=False)
        if clicked and bh and gift_ok:
            self._claim_gift(b.centerx, b.y - 20)

        # ---- 3) başarım ödülleri ----
        r = card(2, PURPLE, L("ui.ach_rewards"))
        unlocked = self.save.data.get("achievements", {})
        left = sum(int(a.get("gems", 0) or 0) for a in ACHIEVEMENTS if a["id"] not in unlocked)
        got_n = sum(1 for a in ACHIEVEMENTS if a["id"] in unlocked)
        cx, cy = r.centerx, r.y + 110
        self._trophy(canvas, cx, cy, 38, GOLD, t)
        draw_coin_label(canvas, cx, r.y + 176, fmt_num(left), GEM_COLOR, 22, icon="gem",
                        icon_r=11, gap=8)
        draw_text(canvas, L("ui.ach_pending", fmt_num(left)), (cx, r.y + 200), 12, TEXT_DIM,
                  center=True, shadow=False)
        draw_text(canvas, L("ui.ach_count", got_n, len(ACHIEVEMENTS)), (cx, r.y + 220), 12,
                  PURPLE, bold=True, center=True, shadow=False)
        b = pygame.Rect(r.x + 24, r.bottom - 56, r.w - 48, 40)
        bh = b.collidepoint(mouse_pos)
        self._mini_button(canvas, b, L("ui.go_ach"), (110, 80, 160), bh)
        if clicked and bh:
            self.goto(STATE_ACHIEVEMENTS)
            sfx("click", 0.6, 0.0)

    def _trophy(self, canvas, cx, cy, s, col, t=0.0):
        """Altın kupa (başarımlar ve mağaza)."""
        k = 0.5 + 0.5 * math.sin(t * 2.2)
        add_glow(canvas, cx, cy - s * 0.2, s * 2.6, col, 0.22 + 0.12 * k)
        dark, lite = scale_col(col, 0.55), lighten(col, 0.45)
        # kulplar
        for sg in (-1, 1):
            pygame.draw.arc(canvas, dark, pygame.Rect(int(cx + sg * s * 0.55 - s * 0.32),
                                                      int(cy - s * 0.78), int(s * 0.64), int(s * 0.7)),
                            -math.pi / 2 if sg > 0 else math.pi / 2,
                            math.pi / 2 if sg > 0 else math.pi * 1.5, max(3, int(s * 0.12)))
        cup = [(cx - s * 0.62, cy - s * 0.85), (cx + s * 0.62, cy - s * 0.85),
               (cx + s * 0.50, cy - s * 0.25), (cx + s * 0.18, cy + s * 0.10),
               (cx - s * 0.18, cy + s * 0.10), (cx - s * 0.50, cy - s * 0.25)]
        poly_aa(canvas, [(x, y + 3) for x, y in cup], (20, 16, 10))
        poly_aa(canvas, cup, col)
        poly_aa(canvas, [(cx - s * 0.48, cy - s * 0.78), (cx - s * 0.18, cy - s * 0.78),
                         (cx - s * 0.22, cy - s * 0.12), (cx - s * 0.40, cy - s * 0.28)], lite)
        pygame.draw.rect(canvas, dark, pygame.Rect(int(cx - s * 0.10), int(cy + s * 0.08),
                                                   int(s * 0.2), int(s * 0.36)))
        base = pygame.Rect(int(cx - s * 0.46), int(cy + s * 0.42), int(s * 0.92), int(s * 0.26))
        pygame.draw.rect(canvas, dark, base, border_radius=3)
        pygame.draw.rect(canvas, col, base.inflate(-4, -6), border_radius=2)
        draw_icon(canvas, cx, cy - s * 0.45, "star", (255, 250, 220), max(5, int(s * 0.22)))
        sp = (t * 1.3) % 3.0
        if sp < 1.0:
            sx_ = cx - s * 0.5 + s * sp
            blit_disc(canvas, sx_, cy - s * 0.6, 2.2, (255, 255, 255), int(220 * (1 - abs(sp - 0.5) * 2)))

    def _draw_gem_packs(self, canvas, dt, mouse_pos, clicked, can_buy):
        """8 elmas paketi, iki sıra."""
        cols = 4
        card_w, card_h, gx, gy = 272, 236, 18, 16
        start_x = (VIRTUAL_W - (cols * card_w + (cols - 1) * gx)) / 2
        y0 = 146
        for i, pack in enumerate(GEM_PACKS[:8]):
            rect = pygame.Rect(int(start_x + (i % cols) * (card_w + gx)),
                               int(y0 + (i // cols) * (card_h + gy)), card_w, card_h)
            hover = rect.collidepoint(mouse_pos)
            featured = bool(pack.get("featured"))
            accent = pack["color"]
            lift = -3 if hover else 0
            rr = rect.move(0, lift)
            if featured:
                k = 0.5 + 0.5 * math.sin(self.t * 2.4 + i)
                add_glow(canvas, rr.centerx, rr.centery, 170, accent, 0.10 + 0.06 * k)
            canvas.blit(store_card_body(rr.w, rr.h, accent, hover, featured), rr.topleft)
            if pack.get("tag"):
                tag = L(pack["tag"])
                tw2 = text_width(tag, 11, True) + 22
                br = pygame.Rect(0, 0, int(tw2), 22)
                br.center = (rr.centerx, rr.y + 1)
                tcol = GOLD if featured else (170, 120, 255)
                pygame.draw.rect(canvas, tcol, br, border_radius=11)
                ink_frame(canvas, br, None, 11, 1)
                draw_text(canvas, tag, br.center, 11, (24, 18, 8) if featured else WHITE, bold=True,
                          center=True, shadow=False)
            draw_gem_pile(canvas, rr.centerx, rr.y + 60, pack.get("tier", i + 1), accent, self.t + i)
            total = gem_pack_total(pack)
            draw_text(canvas, fmt_num(total), (rr.centerx, rr.y + 124), 30, lighten(accent, 0.25),
                      bold=True, center=True)
            if pack["bonus"]:
                bt = L("ui.bonus_chip", pack["bonus"])
                bw2 = text_width(bt, 11, True) + 18
                bc = pygame.Rect(0, 0, int(bw2), 20)
                bc.center = (rr.centerx, rr.y + 156)
                tag_chip(canvas, bc, GOLD, 10, tint=0.2, base=(44, 34, 12))
                draw_text(canvas, bt, bc.center, 11, GOLD, bold=True, center=True, shadow=False)
            else:
                draw_text(canvas, L("ui.gem"), (rr.centerx, rr.y + 156), 11, TEXT_DIM, bold=True,
                          center=True, shadow=False)
            btn = self._store_buy_button((rr.x + 18, rr.bottom - 50, rr.w - 36, 38),
                                         lambda p=pack: self._buy_gem_pack(p),
                                         (40, 110, 155), (58, 145, 195), text_size=15,
                                         price=self.purchase.price_text(pack["id"], pack["price_hint"]))
            btn.update(mouse_pos, dt)
            btn.draw(canvas)
            if clicked:
                btn.click(mouse_pos)

    def _draw_premium_skins(self, canvas, dt, mouse_pos, clicked, can_buy):
        prem = [s for s in SKINS if s.get("premium")]
        cols = max(1, len(prem))
        card_w, card_h, gap = 272, 420, 18
        start_x = (VIRTUAL_W - (cols * card_w + (cols - 1) * gap)) / 2
        y0 = 150
        equipped = self.save.equipped_skin_id()
        for i, sk in enumerate(prem):
            rect = pygame.Rect(int(start_x + i * (card_w + gap)), y0, card_w, card_h)
            owned = self.save.owns_skin(sk["id"])
            is_eq = equipped == sk["id"]
            hover = rect.collidepoint(mouse_pos)
            accent = GOLD if is_eq else sk["color"]
            add_glow(canvas, rect.centerx, rect.y + 110, 150, accent, 0.10)
            canvas.blit(store_card_body(rect.w, rect.h, accent, hover, is_eq), rect.topleft)

            tag = L("ui.equipped") if is_eq else (L("ui.owned") if owned else L("ui.premium"))
            tcol = GOLD if is_eq else (GREEN if owned else PURPLE)
            tw2 = text_width(tag, 11, True) + 20
            br = pygame.Rect(0, 0, int(tw2), 22)
            br.center = (rect.centerx, rect.y + 2)
            bs = pygame.Surface(br.size, pygame.SRCALPHA)
            pygame.draw.rect(bs, (*tcol, 240), bs.get_rect(), border_radius=11)
            canvas.blit(bs, br.topleft)
            draw_text(canvas, tag, br.center, 11, (20, 18, 12) if is_eq else WHITE,
                      bold=True, center=True, shadow=False)

            pygame.draw.ellipse(canvas, (28, 20, 21), pygame.Rect(rect.centerx - 60, rect.y + 140, 120, 22))
            pygame.draw.ellipse(canvas, scale_col(accent, 0.6), pygame.Rect(rect.centerx - 60, rect.y + 140, 120, 22), 2)
            draw_skin_preview(canvas, sk, rect.centerx, rect.y + 104, self.t, r=34)

            draw_text(canvas, skin_name(sk), (rect.centerx, rect.y + 176), 20, WHITE,
                      bold=True, center=True)
            yy = rect.y + 210
            perk_limit = rect.bottom - 64
            for perk in sk.get("perks", []):
                if yy >= perk_limit:
                    break
                for j, ln in enumerate(wrap_text(perk_tr(perk), 10, rect.w - 34)[:2]):
                    if yy >= perk_limit:
                        break
                    draw_text(canvas, ("• " if j == 0 else "   ") + ln,
                              (rect.x + 20, yy), 11, (206, 210, 230), shadow=False)
                    yy += 13
                yy += 4

            if owned:
                btn = Button((rect.x + 18, rect.bottom - 52, rect.w - 36, 38),
                             L("ui.equipped") if is_eq else L("ui.equip"),
                             lambda s=sk: self._equip_premium(s),
                             color=(60, 130, 90) if not is_eq else (64, 48, 49),
                             hover_color=(80, 170, 115), enabled=not is_eq, text_size=15)
            else:
                btn = self._store_buy_button((rect.x + 18, rect.bottom - 52, rect.w - 36, 38),
                                             lambda s=sk: self._buy_premium_skin(s),
                                             (120, 60, 150), (160, 90, 200), text_size=15,
                                             price=self.purchase.price_text(sk["item_id"],
                                                                            sk.get("price_hint", "")))
            btn.update(mouse_pos, dt)
            btn.draw(canvas)
            if clicked:
                btn.click(mouse_pos)

    def _draw_store_pets(self, canvas, dt, mouse_pos, clicked, can_buy):
        """Mağaza > petler sekmesi."""
        # ---- kendi petini yap ----
        fr = pygame.Rect(36, 146, 312, 420)
        fhov = fr.collidepoint(mouse_pos)
        k = 0.5 + 0.5 * math.sin(self.t * 2.2)
        add_glow(canvas, fr.centerx, fr.y + 150, 190, GOLD, 0.10 + 0.06 * k + (0.05 if fhov else 0))
        canvas.blit(store_card_body(fr.w, fr.h, GOLD, fhov, True), fr.topleft)
        br = pygame.Rect(0, 0, int(text_width(L("ui.cp_new"), 10, True) + 22), 20)
        br.center = (fr.centerx, fr.y + 1)
        pygame.draw.rect(canvas, (210, 56, 66), br, border_radius=10)
        draw_text(canvas, L("ui.cp_new"), br.center, 10, WHITE, bold=True, center=True, shadow=False)
        draw_text(canvas, L("ui.cp_title"), (fr.centerx, fr.y + 26), 24, GOLD, bold=True, center=True)
        draw_text(canvas, L("ui.cp_pitch"), (fr.centerx, fr.y + 60), 12, (220, 214, 240), center=True,
                  shadow=False)
        # dönen tasarımlar (ya da oyuncunun yarım kalan tasarımı)
        cx, cy = fr.centerx, fr.y + 200
        prev_clip = canvas.get_clip()
        canvas.set_clip(fr.inflate(-6, -6))
        soft_rays(canvas, cx, cy + 10, self.t, (255, 220, 140), n=12, alpha=20 + int(10 * k),
                  length=150)
        canvas.set_clip(prev_clip)
        pygame.draw.ellipse(canvas, (48, 40, 66), pygame.Rect(cx - 74, cy + 30, 148, 34))
        pygame.draw.ellipse(canvas, scale_col(GOLD, 0.7), pygame.Rect(cx - 74, cy + 30, 148, 34), 2)
        draft = self.save.data.get("pet_draft")
        if isinstance(draft, dict):
            show = clean_custom_pet(draft)
        else:
            # hazır temeller sırayla döner (tasarım ekranı da bunlarla başlar)
            show = custom_pet_base(int(self.t / 2.4))
        draw_custom_pet(canvas, show, cx, cy + 22, 40, self.t, face=1 if math.sin(self.t * 0.7) > 0 else -1,
                        moving=fhov)
        draw_text(canvas, custom_pet_base_name(int(self.t / 2.4)) if not isinstance(draft, dict)
                  else str(show.get("name", "")), (fr.centerx, cy + 86), 15, WHITE, bold=True,
                  center=True)
        n_own = len(owned_custom_pets())
        if n_own:
            draw_text(canvas, L("ui.cp_owned", n_own), (fr.centerx, fr.bottom - 108), 12, GREEN,
                      bold=True, center=True, shadow=False)
        draw_text(canvas, self.purchase.price_text(CUSTOM_PET_PRODUCT_ID, CUSTOM_PET_PRICE_HINT),
                  (fr.centerx, fr.bottom - 88), 24, TEXT, bold=True, center=True)
        db = pygame.Rect(fr.x + 22, fr.bottom - 56, fr.w - 44, 40)
        dhov = db.collidepoint(mouse_pos)
        add_glow(canvas, db.centerx, db.centery, 120, GREEN, 0.10 + 0.10 * k)
        self._mini_button(canvas, db, L("ui.cp_design"), (54, 150, 86), dhov or fhov, icon="star",
                          size=16)
        if clicked and fhov:
            self.open_pet_designer()

        # ---- hazır pet'LER ----
        cols, rows_n = 4, 2
        card_w, card_h, gx, gy = 208, 202, 12, 16
        start_x = fr.right + 16
        y0 = 146
        equipped = self.save.equipped_cosmetic_id("pet")
        for i, pet in enumerate(PETS[:cols * rows_n]):
            cx_, ry = i % cols, i // cols
            rect = pygame.Rect(int(start_x + cx_ * (card_w + gx)),
                               int(y0 + ry * (card_h + gy)), card_w, card_h)
            owned = self.save.owns_cosmetic(pet["id"])
            is_eq = equipped == pet["id"]
            hover = rect.collidepoint(mouse_pos)
            accent = GOLD if is_eq else pet["color"]
            add_glow(canvas, rect.centerx, rect.y + 70, 100, accent, 0.09)
            canvas.blit(store_card_body(rect.w, rect.h, accent, hover, is_eq), rect.topleft)

            tag = L("ui.equipped") if is_eq else (L("ui.owned") if owned else L("ui.slot_pet"))
            tcol = GOLD if is_eq else (GREEN if owned else PURPLE)
            br = pygame.Rect(0, 0, int(text_width(tag, 10, True) + 20), 20)
            br.center = (rect.centerx, rect.y + 1)
            bs = pygame.Surface(br.size, pygame.SRCALPHA)
            pygame.draw.rect(bs, (*tcol, 240), bs.get_rect(), border_radius=10)
            canvas.blit(bs, br.topleft)
            draw_text(canvas, tag, br.center, 10,
                      (18, 16, 10) if is_eq or owned else WHITE, bold=True,
                      center=True, shadow=False)

            pygame.draw.ellipse(canvas, (10, 10, 22), pygame.Rect(rect.centerx - 40, rect.y + 86, 80, 16))
            draw_pet(canvas, pet["kind"], rect.centerx, rect.y + 70, 24, self.t,
                     face=1, moving=hover, col=pet["color"], acc=pet["accent"])
            draw_text(canvas, cos_name(pet), (rect.centerx, rect.y + 120), 16, WHITE,
                      bold=True, center=True)
            if owned:
                btn = Button((rect.x + 16, rect.bottom - 46, rect.w - 32, 34),
                             L("ui.equipped") if is_eq else L("ui.equip"),
                             lambda pt=pet: self._equip_store_pet(pt),
                             color=(38, 40, 54) if is_eq else (60, 130, 90),
                             hover_color=(80, 170, 115), enabled=not is_eq, text_size=13)
            else:
                btn = self._store_buy_button((rect.x + 16, rect.bottom - 46, rect.w - 32, 34),
                                             lambda pt=pet: self._buy_store_pet(pt),
                                             (120, 60, 150), (160, 90, 200), text_size=13,
                                             price=self.purchase.price_text(pet["item_id"],
                                                                            pet.get("price_hint", "")))
            btn.update(mouse_pos, dt)
            btn.draw(canvas)
            if clicked:
                btn.click(mouse_pos)

    # pet tasarla - "kendin yap, beğenince satın al"
    PD_TABS = (("body", ("GÖVDE", "BODY")), ("eyes", ("GÖZ", "EYES")), ("mouth", ("AĞIZ", "MOUTH")),
               ("ears", ("KULAK", "EARS")), ("tail", ("KUYRUK", "TAIL")), ("wings", ("KANAT", "WINGS")),
               ("hat", ("ŞAPKA", "HAT")), ("pattern", ("DESEN", "PATTERN")), ("fx", ("EFEKT", "EFFECT")),
               ("colors", ("RENK", "COLOR")), ("size", ("BOY", "SIZE")))
    PD_SIZE_NAMES = (("Minik", "Tiny"), ("Küçük", "Small"), ("Normal", "Normal"), ("Büyük", "Big"),
                     ("Dev", "Huge"))

    def open_pet_designer(self):
        """Önce hangi pet (sağa-sola kaydırmalı seçim), sonra tasarım."""
        draft = self.save.data.get("pet_draft")
        try:
            base_i = int(self.save.data.get("pet_draft_base", 0)) % len(CUSTOM_PET_BASES)
        except (TypeError, ValueError):
            base_i = 0
        self.pd = {"design": clean_custom_pet(draft) if isinstance(draft, dict)
                   else custom_pet_base(base_i),
                   "has_draft": isinstance(draft, dict),
                   "stage": "pick", "base": base_i, "car": float(base_i), "drag_x0": None,
                   "drag_dx": 0.0, "wheel_cd": 0.0,
                   "tab": "body", "name_focus": False, "confirm": False, "moving": True,
                   "face": 1, "cache": {}, "cache_key": "", "msg": "", "msg_ok": True,
                   "msg_t": 0.0, "pop": 0.0, "confetti": 0.0, "undo": []}
        self.purchase.refresh_catalog(force=True)
        self.goto(STATE_PET_DESIGNER)
        sfx("click", 0.6, 0.0)

    def _pd_step(self, d):
        """Seçim ekranında bir sağa (+1) ya da sola (-1) kaydır."""
        pd = self.pd
        pd["base"] = (pd["base"] + d) % len(CUSTOM_PET_BASES)
        sfx("hover", 0.7, 0.0)

    def _pd_choose(self, keep_draft=False):
        """Seçilen temelle tasarıma geç (ya da yarım kalan tasarıma dön)."""
        pd = self.pd
        if not keep_draft:
            pd["design"] = custom_pet_base(pd["base"])
            pd["undo"] = []
            self.save.data["pet_draft"] = pd["design"]
            self.save.data["pet_draft_base"] = pd["base"]
            pd["has_draft"] = True
        pd["stage"] = "design"
        pd["tab"] = "body"
        pd["pop"] = 1.0
        sfx("levelup", 0.6, 0.0)

    def _pd_back_to_pick(self):
        pd = self.pd
        self.save.data["pet_draft"] = pd["design"]
        pd["name_focus"] = False
        pd["stage"] = "pick"
        pd["car"] = float(pd["base"])
        sfx("click", 0.5, 0.0)

    def _pd_set(self, key, value):
        pd = self.pd
        if pd["design"].get(key) == value:
            return
        pd["undo"] = (pd["undo"] + [json.loads(json.dumps(pd["design"]))])[-30:]
        pd["design"][key] = value
        pd["design"] = clean_custom_pet(pd["design"])
        pd["pop"] = 1.0
        self.save.data["pet_draft"] = pd["design"]
        sfx("hover", 0.6, 0.0)

    def _pd_leave(self):
        self.save.data["pet_draft"] = self.pd["design"]
        self.save.save()
        self.pd["name_focus"] = False
        self.store_tab = "pets"
        self.state = STATE_GEM_STORE

    def handle_pet_designer_key(self, event):
        pd = getattr(self, "pd", None)
        if not pd:
            return
        if pd.get("stage") == "pick" and not pd.get("confirm"):
            if event.key in (pygame.K_LEFT, pygame.K_a):
                self._pd_step(-1)
            elif event.key in (pygame.K_RIGHT, pygame.K_d):
                self._pd_step(1)
            elif event.key in (pygame.K_RETURN, pygame.K_SPACE):
                self._pd_choose()
            return
        if not pd.get("name_focus"):
            return
        nm = pd["design"].get("name", "")
        if event.key in (pygame.K_RETURN, pygame.K_TAB):
            pd["name_focus"] = False
        elif event.key == pygame.K_BACKSPACE:
            pd["design"]["name"] = nm[:-1]
        else:
            ch = event.unicode
            if ch and (ch.isalnum() or ch in " _-") and len(nm) < 14:
                pd["design"]["name"] = nm + ch
        self.save.data["pet_draft"] = pd["design"]

    def _pd_chip_preview(self, key, opt, w, h):
        """Bir seçenek kartının önizlemesi (önbellekli, tasarım değişince yenilenir)."""
        pd = self.pd
        ck = json.dumps(pd["design"], sort_keys=True)
        if pd["cache_key"] != ck:
            pd["cache"] = {}
            pd["cache_key"] = ck
        img = pd["cache"].get((key, opt))
        if img is None:
            d = dict(pd["design"])
            if key == "size":
                d["size"] = opt
            else:
                d[key] = opt
            img = pygame.Surface((w, h), pygame.SRCALPHA)
            r = 34 if key != "size" else 30
            draw_custom_pet(img, d, w / 2, h / 2 + 10, r, 1.3, face=1)
            pd["cache"][(key, opt)] = img
        return img

    def _pd_pick_stage(self, canvas, dt, mouse_pos, clicked, wheel_y):
        """Hangi peti yapacaksın? - sağa sola kaydırmalı seçim."""
        pd = self.pd
        t = self.t
        n = len(CUSTOM_PET_BASES)
        # ---- üst şerit ----
        top = pygame.Surface((VIRTUAL_W, 76), pygame.SRCALPHA)
        pygame.draw.rect(top, (28, 20, 21, 238), top.get_rect())
        canvas.blit(top, (0, 0))
        pygame.draw.line(canvas, GOLD, (0, 76), (VIRTUAL_W, 76), 2)
        draw_icon(canvas, 34, 30, "star", GOLD, 13)
        draw_text(canvas, _tc("HANGİ PETİ YAPMAK İSTİYORSUN?", "WHICH PET DO YOU WANT TO MAKE?"),
                  (56, 14), 26, GOLD, bold=True)
        draw_text(canvas, _tc("Kaydır, seç, sonra her parçasını değiştir.",
                              "Swipe, pick, then change every part."),
                  (56, 48), 12, TEXT_DIM, shadow=False)
        price = self.purchase.price_text(CUSTOM_PET_PRODUCT_ID, CUSTOM_PET_PRICE_HINT)
        draw_text(canvas, price, (VIRTUAL_W - 40, 16), 28, TEXT, bold=True, right=True)

        area = pygame.Rect(0, 90, VIRTUAL_W, 470)
        # ---- sürükleme / tekerlek ----
        held = pygame.mouse.get_pressed()[0]
        if clicked and area.collidepoint(mouse_pos) and pd["drag_x0"] is None:
            pd["drag_x0"] = mouse_pos[0]
            pd["drag_dx"] = 0.0
            pd["press_side"] = None
        elif pd["drag_x0"] is not None:      # bırakma en erken bir sonraki karede
            pd["drag_dx"] = mouse_pos[0] - pd["drag_x0"]
            if not held:
                dx = pd["drag_dx"]
                pd["drag_x0"] = None
                pd["drag_dx"] = 0.0
                if abs(dx) > 50:
                    steps = int(clamp(round(-dx / 230.0), -3, 3)) or (-1 if dx > 0 else 1)
                    for _ in range(abs(steps)):
                        self._pd_step(1 if steps > 0 else -1)
                    clicked = False          # sürükleme tıklama sayılmasın
                elif abs(dx) <= 12 and pd.get("press_side") is not None:
                    # yandaki pete tıklandı (sürüklenmedi): ona kaydır
                    rel = (pd["press_side"] - pd["base"] + n / 2.0) % n - n / 2.0
                    for _ in range(int(abs(round(rel)))):
                        self._pd_step(1 if rel > 0 else -1)
                pd["press_side"] = None
        pd["wheel_cd"] = max(0.0, pd["wheel_cd"] - dt)
        if wheel_y and pd["wheel_cd"] <= 0:
            self._pd_step(-1 if wheel_y > 0 else 1)
            pd["wheel_cd"] = 0.12
        # ---- yumuşak kaydırma: car, seçili indekse en kısa yoldan yaklaşır ----
        diff = (pd["base"] - pd["car"] + n / 2.0) % n - n / 2.0
        pd["car"] = (pd["car"] + diff * min(1.0, dt * 10.0)) % n
        car = pd["car"] - (pd["drag_dx"] / 230.0 if pd["drag_x0"] is not None else 0.0)

        cx, cy = VIRTUAL_W / 2, 330
        k = 0.5 + 0.5 * math.sin(t * 2.0)
        sel = custom_pet_base(pd["base"])
        col = tuple(sel["col"])
        soft_rays(canvas, cx, cy - 10, t, lighten(col, 0.35), n=16, alpha=22 + int(10 * k), length=300)
        add_glow(canvas, cx, cy, 240, col, 0.16 + 0.06 * k)
        pygame.draw.ellipse(canvas, (62, 45, 46), pygame.Rect(cx - 150, cy + 82, 300, 60))
        pygame.draw.ellipse(canvas, (95, 69, 71), pygame.Rect(cx - 150, cy + 76, 300, 60))
        pygame.draw.ellipse(canvas, scale_col(GOLD, 0.75), pygame.Rect(cx - 150, cy + 76, 300, 60), 2)
        # uzaktan yakına çiz (öndeki en son)
        items = []
        for i in range(n):
            rel = (i - car + n / 2.0) % n - n / 2.0
            if abs(rel) > 3.2:
                continue
            items.append((abs(rel), rel, i))
        items.sort(reverse=True)
        hit_side = None
        for dist_, rel, i in items:
            sc = max(0.38, 1.0 - 0.24 * dist_)
            x = cx + rel * 235 * (1.0 - 0.06 * dist_)
            y = cy + 52 - 6 * dist_
            r = int(64 * sc)
            front = dist_ < 0.5
            d = custom_pet_base(i)
            if not front:
                pygame.draw.ellipse(canvas, (55, 40, 41),
                                    pygame.Rect(int(x - 70 * sc), int(y + 28 * sc), int(140 * sc), int(30 * sc)))
            draw_custom_pet(canvas, d, x, y, r, t + i * 0.37, face=1 if rel <= 0 else -1,
                            moving=front, shadow=front)
            if not front:
                rr = pygame.Rect(0, 0, int(150 * sc), int(170 * sc))
                rr.center = (int(x), int(y - 10 * sc))
                if rr.collidepoint(mouse_pos):
                    hit_side = i
                    ring_aa(canvas, x, y - 6, 74 * sc, (200, 190, 240), 2)
                draw_text(canvas, custom_pet_base_name(i), (x, y + 72 * sc), max(11, int(18 * sc)),
                          (150, 150, 180), bold=True, center=True)
        # seçili petin adı
        draw_text(canvas, custom_pet_base_name(pd["base"]).upper(), (cx, cy + 150), 40, GOLD, bold=True,
                  center=True)
        # nokta göstergesi
        dx0 = cx - (n - 1) * 16 / 2
        for i in range(n):
            circle_aa(canvas, dx0 + i * 16, cy + 196, 5 if i == pd["base"] else 3.2,
                      GOLD if i == pd["base"] else (80, 84, 110))
        # oklar
        for sgn, ax in ((-1, 120), (1, VIRTUAL_W - 120)):
            ar = pygame.Rect(0, 0, 84, 84)
            ar.center = (ax, cy + 20)
            hv = ar.collidepoint(mouse_pos)
            add_glow(canvas, ax, cy + 20, 70, GOLD, 0.10 + (0.18 if hv else 0.0))
            circle_aa(canvas, ax, cy + 20, 40, (40, 36, 60) if hv else (26, 24, 40))
            ring_aa(canvas, ax, cy + 20, 40, GOLD if hv else (110, 100, 150), 3)
            px = ax + sgn * 8
            poly_aa(canvas, [(px + sgn * 14, cy + 20), (px - sgn * 12, cy), (px - sgn * 12, cy + 40)],
                    WHITE if hv else (220, 214, 240))
            if clicked and hv:
                self._pd_step(sgn)
                clicked = False
        if clicked and hit_side is not None:
            pd["press_side"] = hit_side      # bırakınca (sürüklenmediyse) ona kaydırılır
            clicked = False

        # ---- alt düğmeler ----
        back = pygame.Rect(24, VIRTUAL_H - 74, 200, 54)
        bh = back.collidepoint(mouse_pos)
        self._mini_button(canvas, back, L("ui.back"), (60, 64, 90), bh, size=15)
        if clicked and bh:
            self._pd_leave()
            sfx("click", 0.5, 0.0)
            return
        ok = pygame.Rect(0, 0, 420, 62)
        ok.center = (VIRTUAL_W // 2, VIRTUAL_H - 47)
        oh = ok.collidepoint(mouse_pos)
        add_glow(canvas, ok.centerx, ok.centery, 220, GREEN, 0.14 + 0.10 * k)
        self._mini_button(canvas, ok, _tc("BUNU SEÇ - TASARLA", "PICK THIS - DESIGN IT"), (54, 150, 86),
                          oh, icon="star", size=20)
        if clicked and oh:
            self._pd_choose()
            return
        if pd["has_draft"]:
            cont = pygame.Rect(VIRTUAL_W - 344, VIRTUAL_H - 74, 320, 54)
            chv = cont.collidepoint(mouse_pos)
            self._mini_button(canvas, cont, _tc("YARIM KALAN TASARIMA DÖN", "BACK TO MY DRAFT"),
                              (70, 64, 120), chv, size=14)
            if clicked and chv:
                self._pd_choose(keep_draft=True)

    def update_pet_designer(self, dt, mouse_pos, clicked, wheel_y=0):
        canvas = self.display.canvas
        self.bg.draw(canvas)
        pd = self.pd
        if pd.get("stage") == "pick":
            self._pd_pick_stage(canvas, dt, mouse_pos, clicked and not self.purchase.waiting(), wheel_y)
            self._draw_payment_wait(canvas, mouse_pos, clicked)
            return
        d = pd["design"]
        t = self.t
        pd["pop"] = max(0.0, pd["pop"] - dt * 3.0)
        pb = self.purchase
        modal = pd["confirm"] or pb.waiting() or pd["msg_t"] > 0
        ui_click = clicked and not modal

        # ================= üst şerit =================
        top = pygame.Surface((VIRTUAL_W, 76), pygame.SRCALPHA)
        pygame.draw.rect(top, (12, 13, 22, 238), top.get_rect())
        canvas.blit(top, (0, 0))
        pygame.draw.line(canvas, GOLD, (0, 76), (VIRTUAL_W, 76), 2)
        draw_icon(canvas, 34, 30, "star", GOLD, 13)
        draw_text(canvas, _tc("PET TASARLA", "DESIGN YOUR PET"), (56, 14), 26, GOLD, bold=True)
        price = pb.price_text(CUSTOM_PET_PRODUCT_ID, CUSTOM_PET_PRICE_HINT)
        draw_text(canvas, price, (VIRTUAL_W - 40, 16), 28, TEXT, bold=True, right=True)

        # ================= sol: canlı önizleme =================
        lp = pygame.Rect(24, 88, 452, 548)
        panel(canvas, lp, bg=(16, 18, 30), edge=(80, 70, 110), alpha=240, radius=18, edge_w=2)
        # ad kutusu
        nr = pygame.Rect(lp.x + 24, lp.y + 16, lp.w - 48, 40)
        nh = nr.collidepoint(mouse_pos)
        pygame.draw.rect(canvas, (26, 28, 44) if (nh or pd["name_focus"]) else (20, 22, 34), nr,
                         border_radius=10)
        ink_frame(canvas, nr, GOLD if pd['name_focus'] else (70, 74, 100), 10, 2)
        draw_text(canvas, _tc("AD", "NAME"), (nr.x + 14, nr.y + 12), 12, TEXT_DIM, bold=True,
                  shadow=False)
        caret = "|" if pd["name_focus"] and int(t * 2) % 2 == 0 else ""
        draw_text(canvas, (d.get("name") or "") + caret, (nr.x + 64, nr.y + 8), 20, TEXT, bold=True)
        if not pd["name_focus"]:
            draw_text(canvas, _tc("değiştirmek için tıkla", "click to rename"), (nr.right - 12, nr.y + 13),
                      10, (110, 116, 146), right=True, shadow=False)
        if ui_click:
            pd["name_focus"] = nh
        touch_text_field(nr, "pet_name", d.get("name") or "", focused=bool(pd["name_focus"]),
                         label=_tc("AD", "NAME"))
        # kaide
        cx, cy = lp.centerx, lp.y + 300
        k = 0.5 + 0.5 * math.sin(t * 2.0)
        col = tuple(d["col"])
        prev_clip = canvas.get_clip()
        canvas.set_clip(lp.inflate(-6, -6))
        soft_rays(canvas, cx, cy - 10, t, lighten(col, 0.35), n=14, alpha=24 + int(10 * k), length=260)
        canvas.set_clip(prev_clip)
        add_glow(canvas, cx, cy - 10, 210, col, 0.16 + 0.06 * k + 0.25 * pd["pop"])
        pygame.draw.ellipse(canvas, (34, 30, 52), pygame.Rect(cx - 150, cy + 64, 300, 64))
        pygame.draw.ellipse(canvas, (56, 50, 82), pygame.Rect(cx - 150, cy + 58, 300, 64))
        pygame.draw.ellipse(canvas, scale_col(GOLD, 0.75), pygame.Rect(cx - 150, cy + 58, 300, 64), 2)
        scale_pop = 1.0 + 0.10 * pd["pop"]
        draw_custom_pet(canvas, d, cx, cy + 40, int(62 * scale_pop), t, face=pd["face"],
                        moving=pd["moving"])
        # alt düğmeler
        bw, bh, gap = 96, 36, 8
        bx0 = lp.centerx - (4 * bw + 3 * gap) / 2
        by = lp.bottom - 56
        btns = [(_tc("DURDUR", "STOP") if pd["moving"] else _tc("YÜRÜT", "WALK"), "walk"),
                (_tc("ÇEVİR", "FLIP"), "flip"), (_tc("PET SEÇ", "PICK PET"), "pick"),
                (_tc("GERİ AL", "UNDO"), "undo")]
        for i, (lbl, act) in enumerate(btns):
            r = pygame.Rect(int(bx0 + i * (bw + gap)), by, bw, bh)
            hv = r.collidepoint(mouse_pos)
            en = act != "undo" or bool(pd["undo"])
            self._mini_button(canvas, r, lbl, (70, 64, 120) if act != "pick" else (150, 100, 40),
                              hv, enabled=en)
            if ui_click and hv and en:
                if act == "walk":
                    pd["moving"] = not pd["moving"]
                elif act == "flip":
                    pd["face"] = -pd["face"]
                elif act == "pick":
                    self._pd_back_to_pick()
                    return
                elif act == "undo":
                    pd["design"] = pd["undo"].pop()
                    self.save.data["pet_draft"] = pd["design"]
                sfx("click", 0.5, 0.0)
        d = pd["design"]

        # ================= sağ: sekmeler + seçenekler =================
        rp = pygame.Rect(492, 88, 764, 548)
        panel(canvas, rp, bg=(16, 18, 30), edge=(80, 70, 110), alpha=240, radius=18, edge_w=2)
        tw_, th_, tg = 116, 30, 8
        for i, (key, pair) in enumerate(self.PD_TABS):
            row = 0 if i < 6 else 1
            ci = i if i < 6 else i - 6
            n_row = 6 if row == 0 else len(self.PD_TABS) - 6
            x0 = rp.centerx - (n_row * tw_ + (n_row - 1) * tg) / 2
            r = pygame.Rect(int(x0 + ci * (tw_ + tg)), rp.y + 14 + row * (th_ + 8), tw_, th_)
            act = pd["tab"] == key
            hv = r.collidepoint(mouse_pos)
            pygame.draw.rect(canvas, (70, 56, 24) if act else ((34, 36, 56) if hv else (24, 26, 40)), r,
                             border_radius=9)
            ink_frame(canvas, r, GOLD if act else (64, 68, 96), 9, 2)
            draw_text(canvas, pair[0] if lang() == "tr" else pair[1], r.center, 13,
                      TEXT if act else TEXT_DIM, bold=True, center=True)
            if ui_click and hv and not act:
                pd["tab"] = key
                sfx("click", 0.5, 0.0)
        area = pygame.Rect(rp.x + 12, rp.y + 96, rp.w - 24, rp.h - 108)
        tab = pd["tab"]
        if tab in CUSTOM_PET_PARTS:
            opts = CUSTOM_PET_PARTS[tab]
            cols = 4 if len(opts) <= 8 else 5
            cw, ch, cg = (area.w - (cols - 1) * 12) // cols, 208, 12
            for i, opt in enumerate(opts):
                r = pygame.Rect(area.x + (i % cols) * (cw + cg), area.y + (i // cols) * (ch + 14), cw, ch)
                sel = d.get(tab) == opt
                hv = r.collidepoint(mouse_pos)
                bg = (44, 38, 24) if sel else ((30, 32, 50) if hv else (22, 24, 38))
                panel(canvas, r, bg=bg, edge=GOLD if sel else ((110, 110, 150) if hv else (54, 58, 82)),
                      alpha=250, radius=14, edge_w=3 if sel else 2)
                if hv and not modal:
                    dd = dict(d)
                    dd[tab] = opt
                    draw_custom_pet(canvas, dd, r.centerx, r.y + 104, 38, t, face=1, moving=True)
                else:
                    img = self._pd_chip_preview(tab, opt, cw, 170)
                    canvas.blit(img, (r.x, r.y + 4))
                lbl = custom_pet_label(tab, opt)
                draw_text(canvas, lbl, (r.centerx, r.bottom - 22), 15, GOLD if sel else TEXT, bold=True,
                          center=True)
                if sel:
                    circle_aa(canvas, r.right - 16, r.y + 16, 10, GOLD)
                    thick_line(canvas, (r.right - 21, r.y + 16), (r.right - 17, r.y + 20), 2, (30, 24, 10))
                    thick_line(canvas, (r.right - 17, r.y + 20), (r.right - 10, r.y + 11), 2, (30, 24, 10))
                if ui_click and hv:
                    self._pd_set(tab, opt)
        elif tab == "colors":
            rows = (("col", _tc("ANA RENK", "MAIN COLOR")), ("col2", _tc("İKİNCİ RENK", "SECOND COLOR")),
                    ("eye", _tc("GÖZ RENGİ", "EYE COLOR")))
            sw, sg = 36, 5
            n = len(CUSTOM_PET_SWATCHES)
            x0 = area.centerx - (n * sw + (n - 1) * sg) / 2
            for ri, (key, title) in enumerate(rows):
                y = area.y + 14 + ri * 140
                draw_text(canvas, title, (area.x + 12, y), 16, GOLD, bold=True)
                cur = tuple(d.get(key) or CUSTOM_PET_DEFAULT[key])
                draw_text(canvas, _tc("seçili", "selected"), (area.right - 70, y + 2), 11, TEXT_DIM,
                          right=True, shadow=False)
                pygame.draw.rect(canvas, cur, pygame.Rect(area.right - 60, y - 2, 48, 22), border_radius=6)
                ink_frame(canvas, pygame.Rect(area.right - 60, y - 2, 48, 22), WHITE, 6, 2)
                for j, c in enumerate(CUSTOM_PET_SWATCHES):
                    r = pygame.Rect(int(x0 + j * (sw + sg)), y + 34, sw, sw)
                    hv = r.collidepoint(mouse_pos)
                    sel = tuple(c) == cur
                    if sel or hv:
                        add_glow(canvas, r.centerx, r.centery, 26, c, 0.35)
                    pygame.draw.rect(canvas, OUTLINE, r.inflate(4, 4), border_radius=9)
                    pygame.draw.rect(canvas, c, r, border_radius=8)
                    ink_frame(canvas, r, WHITE if sel else (200, 200, 220) if hv else (60, 64, 90), 8, 3 if sel else 1)
                    if ui_click and hv:
                        self._pd_set(key, list(c))
                # açık/koyu ayar şeridi: seçili rengin tonları
                for j in range(9):
                    f = (j - 4) / 4.0
                    c = lighten(cur, f * 0.6) if f > 0 else scale_col(cur, 1.0 + f * 0.6)
                    r = pygame.Rect(int(area.centerx - 9 * 22 + j * 44), y + 80, 40, 22)
                    hv = r.collidepoint(mouse_pos)
                    pygame.draw.rect(canvas, c, r, border_radius=6)
                    ink_frame(canvas, r, WHITE if hv else (60, 64, 90), 6, 1)
                    if ui_click and hv:
                        self._pd_set(key, [int(c[0]), int(c[1]), int(c[2])])
        else:   # size
            cols = len(CUSTOM_PET_SIZES)
            cw, ch, cg = (area.w - (cols - 1) * 12) // cols, 300, 12
            for i, sz in enumerate(CUSTOM_PET_SIZES):
                r = pygame.Rect(area.x + i * (cw + cg), area.y + 40, cw, ch)
                sel = abs(float(d.get("size", 1.0)) - sz) < 0.01
                hv = r.collidepoint(mouse_pos)
                panel(canvas, r, bg=(44, 38, 24) if sel else ((30, 32, 50) if hv else (22, 24, 38)),
                      edge=GOLD if sel else (54, 58, 82), alpha=250, radius=14, edge_w=3 if sel else 2)
                img = self._pd_chip_preview("size", sz, cw, 240)
                canvas.blit(img, (r.x, r.y + 10))
                nm = self.PD_SIZE_NAMES[i]
                draw_text(canvas, nm[0] if lang() == "tr" else nm[1], (r.centerx, r.bottom - 30), 16,
                          GOLD if sel else TEXT, bold=True, center=True)
                if ui_click and hv:
                    self._pd_set("size", sz)

        # ================= alt şerit =================
        back = pygame.Rect(24, VIRTUAL_H - 70, 200, 50)
        bhv = back.collidepoint(mouse_pos)
        self._mini_button(canvas, back, L("ui.back"), (60, 64, 90), bhv)
        if ui_click and bhv:
            self._pd_leave()
            sfx("click", 0.5, 0.0)
            return
        okr = pygame.Rect(VIRTUAL_W - 380, VIRTUAL_H - 74, 356, 58)
        ohv = okr.collidepoint(mouse_pos)
        add_glow(canvas, okr.centerx, okr.centery, 200, GREEN, 0.14 + 0.10 * k)
        self._mini_button(canvas, okr, _tc("TAMAM - SATIN AL  ", "OK - BUY  ") + price, (54, 150, 86),
                          ohv, icon="star", size=19)
        if ui_click and ohv:
            pd["confirm"] = True
            pd["name_focus"] = False
            sfx("click", 0.7, 0.0)
            # Açan tıklama tüketilir.
            clicked = False

        # ================= onay penceresi =================
        if pd["confirm"] and not pb.waiting():
            self._pd_confirm(canvas, mouse_pos, clicked and pd["msg_t"] <= 0, price)
        self._draw_payment_wait(canvas, mouse_pos, clicked)
        # ================= sonuç =================
        if pd["msg_t"] > 0:
            pd["msg_t"] -= dt
            box = pygame.Rect(0, 0, 520, 150)
            box.center = (VIRTUAL_W / 2, VIRTUAL_H / 2)
            colr = GREEN if pd["msg_ok"] else RED
            if pd["msg_ok"]:
                pd["confetti"] += dt
                for i in range(80):
                    x = (i * 97.7 + math.sin(pd["confetti"] * 2 + i) * 30) % VIRTUAL_W
                    y = (pd["confetti"] * (160 + (i % 7) * 30) + i * 23) % (VIRTUAL_H + 40) - 20
                    cc = ((255, 214, 110), (255, 120, 140), (120, 210, 255), (150, 240, 160))[i % 4]
                    pygame.draw.rect(canvas, cc, pygame.Rect(int(x), int(y), 6, 10))
            add_glow(canvas, box.centerx, box.centery, 220, colr, 0.16)
            panel(canvas, box, alpha=252, edge=colr, edge_w=2)
            draw_text(canvas, L("ui.op_ok") if pd["msg_ok"] else L("ui.op_fail"),
                      (box.centerx, box.y + 26), 20, colr, bold=True, center=True)
            for j, ln in enumerate(wrap_text(pd["msg"], 13, box.w - 50)[:3]):
                draw_text(canvas, ln, (box.centerx, box.y + 62 + j * 18), 13, TEXT, center=True,
                          shadow=False)
            if clicked and pd["msg_t"] < 3.0:
                pd["msg_t"] = 0.0

    def _pd_confirm(self, canvas, mouse_pos, clicked, price):
        pd = self.pd
        pb = self.purchase
        d = pd["design"]
        dim = pygame.Surface((VIRTUAL_W, VIRTUAL_H), pygame.SRCALPHA)
        dim.fill((17, 12, 12, 190))
        canvas.blit(dim, (0, 0))
        box = pygame.Rect(0, 0, 700, 400)
        box.center = (VIRTUAL_W // 2, VIRTUAL_H // 2)
        add_glow(canvas, box.centerx, box.centery, 320, GOLD, 0.12)
        panel(canvas, box, bg=(41, 30, 31), alpha=252, radius=20, edge_w=3)
        draw_text(canvas, _tc("BU PETİ SATIN AL?", "BUY THIS PET?"), (box.centerx, box.y + 28), 26, GOLD,
                  bold=True, center=True)
        pcx, pcy = box.x + 170, box.y + 210
        add_glow(canvas, pcx, pcy, 140, tuple(d["col"]), 0.22)
        pygame.draw.ellipse(canvas, (95, 69, 71), pygame.Rect(pcx - 100, pcy + 50, 200, 44))
        draw_custom_pet(canvas, d, pcx, pcy + 40, 48, self.t, face=1, moving=True)
        draw_text(canvas, d.get("name", ""), (pcx, box.bottom - 70), 20, TEXT, bold=True, center=True)
        tx = box.x + 330
        draw_text(canvas, price, (tx, box.y + 80), 40, TEXT, bold=True)
        lines = (_tc("• Hesabına kalıcı yazılır", "• Saved to your account forever"),
                 _tc("• Ödemeden sonra tasarım değişmez", "• The design is final after paying"))
        for j, ln in enumerate(lines):
            draw_text(canvas, ln, (tx, box.y + 142 + j * 24), 13, (210, 214, 232), shadow=False)
        b1 = pygame.Rect(tx, box.bottom - 84, 330, 50)
        b2 = pygame.Rect(tx, box.bottom - 30 - 0, 330, 24)
        h1, h2 = b1.collidepoint(mouse_pos), b2.collidepoint(mouse_pos)
        if pb.available():
            self._mini_button(canvas, b1, _tc("ÖDEMEYE GEÇ", "GO TO PAYMENT"), (54, 150, 86), h1,
                              icon="gem", size=17)
            if clicked and h1:
                self._buy_custom_pet()
        elif pb.enabled and not pb.logged_in():
            self._mini_button(canvas, b1, L("ui.sign_in"), (40, 110, 160), h1)
            draw_text(canvas, L("ui.shop_login"), (b1.centerx, b1.y - 14), 11, GOLD, center=True,
                      shadow=False)
            if clicked and h1:
                self.save.data["pet_draft"] = d
                pd["confirm"] = False
                self.goto(STATE_LOGIN)
        else:
            self._mini_button(canvas, b1, L("ui.soon"), (54, 150, 86), False, enabled=False)
            draw_text(canvas, pb.unavailable_reason(), (b1.centerx, b1.y - 14), 11, (225, 190, 110),
                      center=True, shadow=False)
        draw_text(canvas, _tc("tasarlamaya dön", "keep designing"), b2.center, 13,
                  WHITE if h2 else TEXT_DIM, bold=True, center=True, shadow=False)
        if clicked and (h2 or not box.collidepoint(mouse_pos)):
            pd["confirm"] = False
            sfx("click", 0.5, 0.0)

    def _buy_custom_pet(self):
        pd = self.pd
        design = clean_custom_pet(pd["design"])
        self.save.data["pet_draft"] = design
        self.save.save()
        before = {e.get("id") for e in (self.save.data.get("custom_pets") or []) if isinstance(e, dict)}

        def done(ok, msg):
            pd["confirm"] = False
            if ok and FAKE_PURCHASE:
                # test kipi: özel pet yalnızca yerelde oluşur.
                pid = "pet_custom_" + secrets.token_hex(4)
                self.save.data.setdefault("custom_pets", []).append({"id": pid, "design": design})
                self.save.data.setdefault("cosmetics_owned", []).append(pid)
            if ok:
                new = [e.get("id") for e in (self.save.data.get("custom_pets") or [])
                       if isinstance(e, dict) and e.get("id") not in before]
                if new:
                    self.save.equip_cosmetic("pet", new[-1])
                self.save.save()
                pd["msg"] = _tc("{0} hazır ve kuşanıldı! Arenada peşinden koşacak.",
                                "{0} is ready and equipped! It will follow you in the arena.").format(
                    design.get("name", ""))
                sfx("levelup", 1.0, 0.0)
            else:
                pd["msg"] = msg or L("ui.shop_failed")
            pd["msg_ok"] = ok
            pd["msg_t"] = 5.0
            pd["confetti"] = 0.0

        self.purchase.begin_purchase({"id": CUSTOM_PET_PRODUCT_ID}, on_done=done, design=design)

    def _equip_store_pet(self, pet):
        self.save.equip_cosmetic("pet", pet["id"])
        self.save.save()
        sfx("click", 0.6, 0.0)

    def _buy_store_pet(self, pet):
        """pet'i gerçek parayla satın almayı başlatır (premium skinle aynı yol)."""
        pack = dict(id=pet["item_id"], gems=0, bonus=0,
                    price_hint=pet.get("price_hint", ""), tag="", color=pet["color"])

        def done(ok, msg):
            self.gem_msg = msg
            self.gem_msg_ok = ok
            self.gem_msg_timer = 3.2
            if ok and FAKE_PURCHASE:
                # Yalnızca test kipinde pet yerel olarak açılır.
                self.save.buy_cosmetic(pet["id"], 0)
                self.save.equip_cosmetic("pet", pet["id"])
                self.save.save()
                self.gem_msg = f"TEST: {pet['name']} açıldı ve kuşanıldı"
            elif ok and self.save.owns_cosmetic(pet["id"]):
                # Gerçek satın almada sahiplik sunucuda yazılır; yeni pet'i
                # kuşan.
                self.save.equip_cosmetic("pet", pet["id"])
            if ok:
                sfx("buy", 1.0, 0.0)

        self.purchase.begin_purchase(pack, on_done=done)

    def _equip_premium(self, sk):
        self.save.equip_skin(sk["id"])
        self.selected_skin = sk["id"]
        sfx("click", 0.6, 0.0)

