    def update_howto(self, dt, mouse_pos, clicked):
        canvas = self.display.canvas
        self.bg.draw(canvas)
        panel_rect = pygame.Rect(0, 0, 1216, 676)
        panel_rect.center = (VIRTUAL_W / 2, VIRTUAL_H / 2)
        panel(canvas, panel_rect, alpha=245)
        draw_text(canvas, L("ui.howto"), (panel_rect.centerx, panel_rect.y + 24), 27, CYAN, bold=True, center=True)
        w_, b_, r_ = MAX_RUN_WEAPONS, MAX_RUN_BOOKS, MAX_RUN_RARE_BOOKS
        lines = [(_pick(t).format(w=w_, b=b_, r=r_), _pick(d).format(w=w_, b=b_, r=r_))
                 for t, d in (HOWTO_TOUCH if MOBILE else HOWTO_KEYS) + HOWTO_GAME]
        # Maddeler üç sütuna bölünür; satır aralığı sütun başına düşen madde
        # sayısına göre hesaplanır, böylece yeni madde eklenince yazılar ne
        # panelin dışına taşar ne de birbirinin üstüne biner.
        NCOL = 3
        list_top = panel_rect.y + 64
        list_bottom = panel_rect.bottom - 64      # geri düğmesine yer bırak
        per_col = (len(lines) + NCOL - 1) // NCOL
        step = clamp((list_bottom - list_top) / max(1, per_col), 27, 66)
        pad = 26
        col_w = (panel_rect.w - pad * 2) / NCOL
        for i, (title, desc) in enumerate(lines):
            ci = min(NCOL - 1, i // per_col)
            cx = panel_rect.x + pad + ci * col_w
            y = list_top + (i % per_col) * step
            draw_text(canvas, _fit_text(title, 14, col_w - 18, bold=True), (cx, y), 14,
                      GOLD, bold=True)
            draw_text(canvas, _fit_text(desc, 11, col_w - 18), (cx, y + 18), 11,
                      TEXT_DIM, shadow=False)
            # sütunlar arası ince ayraç
            if ci and i % per_col == 0:
                lx_ = cx - 13
                pygame.draw.line(canvas, (86, 63, 65), (lx_, list_top - 6),
                                 (lx_, list_top + (per_col - 1) * step + 24), 1)

        btn = Button((panel_rect.centerx - 100, panel_rect.bottom - 52, 200, 40), L("ui.back"),
                     lambda: self.set_state(STATE_SETTINGS if self.prev_state == STATE_SETTINGS else STATE_MENU))
        btn.update(mouse_pos, dt)
        btn.draw(canvas)
        if clicked:
            btn.click(mouse_pos)

    # ---- ayarlar ----
    def _set_row(self, canvas, rect, label, value, vcol, mouse_pos, clicked):
        """Tek satırlık ayar düğmesi."""
        hov = rect.collidepoint(mouse_pos)
        panel(canvas, rect, bg=(71, 51, 53) if hov else (50, 37, 38),
              edge=(128, 104, 106) if hov else PANEL_EDGE, alpha=240, radius=10, edge_w=2)
        draw_text(canvas, label, (rect.x + 16, rect.y + 7), 12, TEXT_DIM, shadow=False)
        draw_text(canvas, value, (rect.x + 16, rect.y + 23), 17, vcol, bold=True, shadow=False)
        if clicked and hov:
            sfx("click", 0.6, 0.0)
            return True
        return False

    def _set_slider(self, canvas, rect, label, key, mouse_pos, down):
        """Ses çubuğu: tıklayıp sürükleyerek ayarlanır."""
        st = self.save.data.setdefault("settings", {})
        val = clamp(float(st.get(key, 0.5)), 0.0, 1.0)
        hov = rect.collidepoint(mouse_pos)
        panel(canvas, rect, bg=(71, 51, 53) if hov else (50, 37, 38),
              edge=(128, 104, 106) if hov else PANEL_EDGE, alpha=240, radius=10, edge_w=2)
        draw_text(canvas, label, (rect.x + 16, rect.y + 7), 12, TEXT_DIM, shadow=False)
        draw_text(canvas, fmt_pct(int(round(val * 100))), (rect.right - 16, rect.y + 7), 12, CYAN,
                  bold=True, right=True, shadow=False)
        br = pygame.Rect(rect.x + 16, rect.y + 30, rect.w - 32, 12)
        draw_bar(canvas, br, val, CYAN, radius=6)
        if down and br.inflate(0, 24).collidepoint(mouse_pos):
            st[key] = clamp((mouse_pos[0] - br.x) / br.w, 0.0, 1.0)
            self._set_dirty = True

    def update_settings(self, dt, mouse_pos, clicked):
        """Ayarlar ekranı."""
        canvas = self.display.canvas
        self.bg.draw(canvas)
        pr = pygame.Rect(0, 0, 940, 626)
        pr.center = (VIRTUAL_W / 2, VIRTUAL_H / 2)
        panel(canvas, pr, alpha=245)
        draw_text(canvas, L("ui.settings"), (pr.centerx, pr.y + 26), 28, CYAN, bold=True, center=True)
        tw_ = text_width(L("ui.settings"), 28, True)
        for sgn in (-1, 1):
            x0 = pr.centerx + sgn * (tw_ / 2 + 18)
            pygame.draw.line(canvas, (92, 76, 70), (x0, pr.y + 26), (x0 + sgn * 120, pr.y + 26), 2)

        st = self.save.data.setdefault("settings", {})
        down = pygame.mouse.get_pressed()[0] and not self.chat.open
        cw = 420
        lx = pr.centerx - cw - 16
        rx = pr.centerx + 16
        ROW_H, ROW_STEP = 46, 52          # iki sütunda da aynı (7'şer satır)
        draw_text(canvas, L("ui.audio_screen"), (lx, pr.y + 62), 15, GOLD, bold=True)
        draw_text(canvas, L("ui.look_perf"), (rx, pr.y + 62), 15, GOLD, bold=True)

        def save_cfg():
            self.save.apply_cfg()
            self.save.save()

        def tog(rect, label, key, default=True):
            on = bool(st.get(key, default))
            if self._set_row(canvas, rect, label, L("ui.on") if on else L("ui.off"),
                             GREEN if on else RED, mouse_pos, clicked):
                st[key] = not on
                save_cfg()

        # ---- sol sütun (6 satır) ----
        y = pr.y + 88
        # dil en üstte: oyuncu oyunu anlamadığı bir dilde açtıysa ilk aradığı
        # satır bu olur; aşağıda kaybolmasın.
        if self._set_row(canvas, pygame.Rect(lx, y, cw, ROW_H), L("ui.language"),
                         f"{LANG_NAMES.get(lang(), lang())}  »", GOLD, mouse_pos, clicked):
            st["lang"] = next_lang()
            save_cfg()
        y += ROW_STEP
        self._set_slider(canvas, pygame.Rect(lx, y, cw, ROW_H), L("ui.music_vol"), "music_vol",
                         mouse_pos, down)
        y += ROW_STEP
        self._set_slider(canvas, pygame.Rect(lx, y, cw, ROW_H), L("ui.sfx_vol"), "sfx_vol",
                         mouse_pos, down)
        y += ROW_STEP
        full = bool(self.display.fullscreen)
        if self._set_row(canvas, pygame.Rect(lx, y, cw, ROW_H), L("ui.fullscreen"),
                         L("ui.on") if full else L("ui.off"), GREEN if full else RED,
                         mouse_pos, clicked):
            self.display.toggle_fullscreen()
        y += ROW_STEP
        tog(pygame.Rect(lx, y, cw, ROW_H), L("ui.shake"), "shake")
        y += ROW_STEP
        tog(pygame.Rect(lx, y, cw, ROW_H), L("ui.dmg_numbers"), "dmg")
        y += ROW_STEP
        # kontrolcü durumu: bilgi satırı (tıklanmaz). Oyuncu pad'inin tanınıp
        # tanınmadığını buradan görür - "çalışmıyor mu acaba?" diye tahmin
        # etmesin.
        pad_on = self.pad.ok
        self._set_row(canvas, pygame.Rect(lx, y, cw, ROW_H), L("ui.gamepad"),
                      (self.pad.name[:18] if pad_on else L("ui.gamepad_none")),
                      GREEN if pad_on else TEXT_DIM, mouse_pos, False)
        col_bottom = y + ROW_H

        # ---- sağ sütun (5 satır) ----
        y = pr.y + 88
        cap = CFG.get("fps_cap", 60)
        if self._set_row(canvas, pygame.Rect(rx, y, cw, ROW_H), L("ui.fps_cap"),
                         f"{cap} FPS  »", CYAN if cap <= 144 else ORANGE, mouse_pos, clicked):
            i = FPS_CHOICES.index(cap) if cap in FPS_CHOICES else 0
            st["fps_cap"] = FPS_CHOICES[(i + 1) % len(FPS_CHOICES)]
            save_cfg()
        y += ROW_STEP
        # grafik kalitesi: FPS sınırının hemen altında
        gl = gfx_level()
        if self._set_row(canvas, pygame.Rect(rx, y, cw, ROW_H), L("ui.gfx"),
                         L(("ui.gfx_low", "ui.gfx_mid", "ui.gfx_high")[gl]) + "  »",
                         (ORANGE, GOLD, GREEN)[gl], mouse_pos, clicked):
            st["gfx"] = (gl + 2) % 3        # yüksek -> orta -> düşük -> yüksek
            save_cfg()
        y += ROW_STEP
        vs_on = bool(st.get("vsync", False))
        if self._set_row(canvas, pygame.Rect(rx, y, cw, ROW_H), L("ui.vsync"),
                         L("ui.on") if vs_on else L("ui.off"),
                         ORANGE if vs_on else GREEN, mouse_pos, clicked):
            st["vsync"] = not vs_on
            save_cfg()
            self.display.reopen()           # ekran yeni vsync ayarıyla açılır
        y += ROW_STEP
        tog(pygame.Rect(rx, y, cw, ROW_H), L("ui.fps_show"), "fps", default=False)
        y += ROW_STEP
        tog(pygame.Rect(rx, y, cw, ROW_H), L("ui.pet_show"), "pet_show")
        y += ROW_STEP
        self._plain_skin_row(canvas, pygame.Rect(rx, y, cw, ROW_H), mouse_pos, clicked)
        y += ROW_STEP
        sr = pygame.Rect(rx, y, cw, ROW_H)
        if self._set_row(canvas, sr, L("ui.skill_size"), f"{skill_scale_label()}  »",
                         CYAN, mouse_pos, clicked):
            CFG["skill_scale"] = cycle_skill_scale()
            st["skill_scale"] = CFG["skill_scale"]
            self.save.save()

        # ---- tam genişlikte: eşya efekti kaydırıcısı ----
        # Oyun içindeki (ESC) kaydırıcının aynısı: aynı yardımcıyı çağırıyor,
        # yani iki ekran birbiriyle her zaman aynı değeri gösteriyor.
        iy = col_bottom + 18
        ir = pygame.Rect(lx, iy, rx + cw - lx, 50)
        self._fx_slider(canvas, ir, mouse_pos, down)
        if getattr(self, "_fx_dirty", False):
            self._set_dirty = True      # bırakılınca cfg de diske yazılsın

        # ---- kısa notlar ----
        ny = ir.bottom + 12
        notes = [L("ui.note_fx")] + wrap_text(L("ui.note_gfx"), 10, pr.w - 30)[:2]
        for ln in notes:
            draw_text(canvas, ln, (pr.centerx, ny), 10, TEXT_DIM, center=True, shadow=False)
            ny += 14

        # Sürükleme bitince kaydet (her karede dosya yazma)
        if getattr(self, "_set_dirty", False) and not down:
            self._set_dirty = False
            save_cfg()

        # ---- alt düğmeler ----
        by = pr.bottom - 58
        btns = [
            Button((pr.centerx - 356, by, 228, 44), L("ui.howto"),
                   lambda: self.goto(STATE_HOW_TO), text_size=16),
            Button((pr.centerx - 114, by, 228, 44), L("ui.keybinds"),
                   lambda: self.goto(STATE_KEYS),
                   color=(62, 84, 116), hover_color=(88, 118, 160), text_size=16),
            Button((pr.centerx + 128, by, 228, 44), L("ui.back"),
                   lambda: self.set_state(STATE_MENU), text_size=16),
        ]
        for b in btns:
            b.update(mouse_pos, dt)
            b.draw(canvas)
            if clicked:
                b.click(mouse_pos)

    # ---- başarımlar ----
    # Başarım ekranı küçük bir liste değil, tam ekran bir galeri: her kart
    # madalyonu, kademesini, ilerlemesini ve elmas ödülünü gösterir.
    def _ach_sort_key(self, a):
        """Sıralama: önce kilitli ve tamamlanmaya en yakın olanlar."""
        got = self.ach.has(a["id"])
        cur, need, _ = ach_progress(self.save, a)
        frac = (cur / need) if need else 0.0
        return (1 if got else 0, -frac, ACH_TIER_ORDER.index(a.get("tier", "bronz")))

    def _ach_medallion(self, canvas, cx, cy, r, ach, got, pulse=0.0):
        if MOBILE and not _GLOW_ON_ALPHA:
            n = int(r * 6.2) + 8
            img = mob_static_sprite(("ach", ach.get("id") or ach.get("name"), int(r), bool(got)), n,
                                    lambda im, x, y: self._ach_medallion_draw(im, x, y, r, ach, got, 0.5))
            canvas.blit(img, (int(cx - n / 2.0), int(cy - n / 2.0)))
            return
        self._ach_medallion_draw(canvas, cx, cy, r, ach, got, pulse)

    def _ach_medallion_draw(self, canvas, cx, cy, r, ach, got, pulse=0.0):
        """Başarım madalyonu: açıksa kademe renginde metal madalyon"""
        col = ach_tier_color(ach)
        legend = ach.get("tier") == "efsane"
        if got:
            add_glow(canvas, cx, cy, r * 2.8, col, 0.20 + pulse * 0.12)
            n = 12
            for i in range(n):
                a = self.t * (0.35 if not legend else 0.7) + i * math.tau / n
                p0 = (cx + math.cos(a) * r * 1.02, cy + math.sin(a) * r * 1.02)
                p1 = (cx + math.cos(a) * r * (1.32 + 0.06 * pulse),
                      cy + math.sin(a) * r * (1.32 + 0.06 * pulse))
                pygame.draw.line(canvas, scale_col(col, 0.55 + 0.3 * pulse), p0, p1,
                                 max(2, int(r * 0.08)))
            # defne dalları
            for sg in (-1, 1):
                for k in range(5):
                    a = math.pi / 2 + sg * (0.55 + k * 0.36)
                    lx, ly = cx + math.cos(a) * r * 1.12, cy + math.sin(a) * r * 1.12
                    ang = a + sg * math.pi / 2
                    ex, ey = math.cos(ang) * r * 0.20, math.sin(ang) * r * 0.20
                    ellipse_pts = [(lx - ex, ly - ey), (lx + ey * 0.45, ly - ex * 0.45),
                                   (lx + ex, ly + ey), (lx - ey * 0.45, ly + ex * 0.45)]
                    pygame.draw.polygon(canvas, mix_col(col, (90, 170, 90), 0.35), ellipse_pts)
            circle_aa(canvas, cx, cy + 2, r, (8, 8, 12))
            disc_grad(canvas, cx, cy, r, lighten(col, 0.45), scale_col(col, 0.42), 9)
            ring_aa(canvas, cx, cy, r, lighten(col, 0.55), 2)
            circle_aa(canvas, cx, cy, r * 0.74, scale_col(col, 0.30))
            ring_aa(canvas, cx, cy, r * 0.74, scale_col(col, 0.75), 1)
            draw_icon(canvas, cx, cy, ach.get("icon", "star"), lighten(col, 0.55),
                      max(5, int(r * 0.48)))
            # parlama
            circle_aa(canvas, cx - r * 0.45, cy - r * 0.55, max(1.5, r * 0.10), (255, 255, 255))
            if legend:
                for i in range(3):
                    a = -self.t * 1.4 + i * math.tau / 3
                    sx_, sy_ = cx + math.cos(a) * r * 1.45, cy + math.sin(a) * r * 1.45
                    add_glow(canvas, sx_, sy_, 12, col, 0.5)
                    blit_disc(canvas, sx_, sy_, 2.2, (255, 240, 255), 240)
        else:
            circle_aa(canvas, cx, cy + 2, r, (6, 6, 10))
            disc_grad(canvas, cx, cy, r, (40, 42, 58), (18, 19, 28), 7)
            for i in range(16):      # noktalı kademe halkası
                a = i * math.tau / 16
                blit_disc(canvas, cx + math.cos(a) * r, cy + math.sin(a) * r, 1.6,
                          scale_col(col, 0.55), 200)
            draw_icon(canvas, cx, cy - r * 0.1, ach.get("icon", "star"), (64, 68, 86),
                      max(5, int(r * 0.48)))
            draw_padlock(canvas, cx + r * 0.52, cy + r * 0.50, r * 0.34, (150, 140, 120))

    def _ach_shine(self, canvas, rect, i, list_rect):
        sp = ((self.t * 0.35 + i * 0.17) % 1.6) - 0.3
        if 0.0 < sp < 1.0:
            prev = canvas.get_clip()
            canvas.set_clip(rect.inflate(-4, -4).clip(list_rect))
            sx_ = rect.x + sp * (rect.w + 120) - 60
            canvas.blit(self._shine_stripe(rect.h), (int(sx_ - 40), rect.y))
            canvas.set_clip(prev)

    def _ach_card_paint(self, canvas, rect, a, i, got, cur, need, tcol, hover, unlocked, pulse,
                        list_rect, edge, shine=True):
        """Başarımlar listesindeki tek bir kartı çizer (gölge, gövde, yazılar, ilerleme çubuğu, elmas ödülü)."""
        canvas.blit(_panel_shadow(rect.w, rect.h, 13), (rect.x - 6, rect.y - 2))
        canvas.blit(ach_card_body(rect.w, rect.h, tcol, got, hover), rect.topleft)
        ink_frame(canvas, rect, lighten(edge, 0.25) if hover else edge, 13, 2)
        if got:
            ink_frame(canvas, rect.inflate(-6, -6), scale_col(tcol, 0.45), 11, 1)
            # cam parıltısı: kartın üstünden ağır ağır geçen ışık şeridi
            if shine:
                self._ach_shine(canvas, rect, i, list_rect)

        self._ach_medallion(canvas, rect.x + 50, rect.y + 58, 26, a, got, pulse)

        tx = rect.x + 92
        draw_text(canvas, ach_name(a), (tx, rect.y + 16), 18, TEXT if got else (168, 172, 190),
                  bold=True)
        # kademe rozeti (sağ üst): açıksa dolu, kilitliyse çerçeveli
        tier = ACH_TIERS.get(a.get("tier", "bronz"), ACH_TIERS["bronz"])
        tlab = L("tier." + a.get("tier", "bronz"))
        tw_ = text_width(tlab, 10, True) + 16
        tr = pygame.Rect(int(rect.right - 14 - tw_), rect.y + 15, int(tw_), 18)
        if got:
            pygame.draw.rect(canvas, tcol, tr, border_radius=9)
            draw_text(canvas, tlab, tr.center, 10, (24, 18, 12), bold=True,
                      center=True, shadow=False)
        else:
            tag_chip(canvas, tr, tcol, 9, tint=0.14)
            draw_text(canvas, tlab, tr.center, 10, scale_col(tcol, 0.9), bold=True,
                      center=True, shadow=False)

        for j, ln in enumerate(wrap_text(ach_desc(a), 11, rect.w - 112)[:2]):
            draw_text(canvas, ln, (tx, rect.y + 42 + j * 14), 11,
                      (214, 208, 196) if got else TEXT_DIM, shadow=False)

        # ---- alt bölüm: ilerleme / durum ----
        gems = int(a.get("gems", 0) or 0)
        if got:
            okr = pygame.Rect(tx, rect.bottom - 40, 0, 22)
            okt = L("ui.unlocked_on", unlocked.get(a["id"], ""))
            okr.w = int(text_width(okt, 11, True) + 34)
            tag_chip(canvas, okr, GREEN, 11, tint=0.18)
            thick_line(canvas, (okr.x + 10, okr.centery), (okr.x + 14, okr.centery + 4), 2.4, GREEN)
            thick_line(canvas, (okr.x + 14, okr.centery + 4), (okr.x + 21, okr.centery - 4), 2.4,
                       GREEN)
            draw_text(canvas, okt, (okr.x + 27, okr.centery - text_height(11, True) / 2), 11,
                      GREEN, bold=True, shadow=False)
        elif need:
            frac = clamp(cur / max(1, need), 0.0, 1.0)
            pb = pygame.Rect(tx, rect.bottom - 40, rect.w - 112 - 82, 10)
            pygame.draw.rect(canvas, (28, 20, 21), pb, border_radius=5)
            fw_ = int((pb.w - 2) * frac)
            if fw_ > 3:
                fr_ = pygame.Rect(pb.x + 1, pb.y + 1, fw_, pb.h - 2)
                pygame.draw.rect(canvas, scale_col(tcol, 0.8), fr_, border_radius=4)
            ink_frame(canvas, pb, (106, 77, 80), 5, 1)
            draw_text(canvas, f"{fmt_num(int(cur))} / {fmt_num(int(need))}",
                      (tx, rect.bottom - 26), 11, TEXT_DIM, shadow=False)
            draw_text(canvas, fmt_pct(frac * 100), (pb.right, rect.bottom - 26), 11,
                      tcol, bold=True, right=True, shadow=False)
        else:
            draw_padlock(canvas, tx + 6, rect.bottom - 30, 7, (150, 140, 110))
            draw_text(canvas, L("ui.ach_ingame"), (tx + 18, rect.bottom - 36), 11,
                      (170, 160, 128), shadow=False)

        if gems:
            gcol = GEM_COLOR if not got else (110, 170, 140)
            gt = f"+{gems}"
            gw_ = text_width(gt, 13, True) + 34
            gr = pygame.Rect(int(rect.right - 14 - gw_), rect.bottom - 40, int(gw_), 24)
            tag_chip(canvas, gr, gcol, 12, tint=0.16)
            draw_icon(canvas, gr.x + 13, gr.centery, "gem", gcol, 7)
            draw_text(canvas, gt, (gr.x + 24, gr.centery - text_height(13, True) / 2), 13, gcol,
                      bold=True, shadow=False)

        if hover:
            draw_text(canvas, L("ui.detail"), (rect.right - 16, rect.y + 40), 10,
                      lighten(edge, 0.35), bold=True, right=True, shadow=False)

    def _shine_stripe(self, h):
        """Kartın üstünden geçen yarı saydam eğik ışık şeridi (önbellekli)."""
        cache = getattr(self, "_shine_cache", None)
        if cache is None:
            cache = self._shine_cache = {}
        img = cache.get(h)
        if img is None:
            img = pygame.Surface((80, h), pygame.SRCALPHA)
            for k in range(6):
                w = 30 - k * 5
                a = 10 + k * 7
                pygame.draw.polygon(img, (255, 248, 230, a),
                                    [(40 + w * 0.5 + 20 - k * 2, 0), (40 + w * 0.5 + 20 + w - k * 2, 0),
                                     (40 + w * 0.5 - 20 + w - k * 2, h), (40 + w * 0.5 - 20 - k * 2, h)])
            cache[h] = img
        return img

    def update_achievements(self, dt, mouse_pos, clicked, wheel_y=0):
        canvas = self.display.canvas
        self.bg.update(dt)
        self.bg.draw(canvas)
        draw_trophy_hall(canvas, self.t)

        unlocked = self.save.data.get("achievements", {})
        got_n = sum(1 for a in ACHIEVEMENTS if a["id"] in unlocked)
        total_n = len(ACHIEVEMENTS)
        earned_gems = sum(int(a.get("gems", 0) or 0) for a in ACHIEVEMENTS if a["id"] in unlocked)
        left_gems = sum(int(a.get("gems", 0) or 0) for a in ACHIEVEMENTS if a["id"] not in unlocked)

        if self.ach_filter == "got":
            items = [a for a in ACHIEVEMENTS if a["id"] in unlocked]
        elif self.ach_filter == "locked":
            items = [a for a in ACHIEVEMENTS if a["id"] not in unlocked]
            items.sort(key=self._ach_sort_key)
        elif self.ach_filter == "near":
            items = []
            for a in ACHIEVEMENTS:
                if a["id"] in unlocked:
                    continue
                cur, need, _ = ach_progress(self.save, a)
                if need and cur / need >= 0.4:
                    items.append(a)
            items.sort(key=self._ach_sort_key)
        else:
            items = list(ACHIEVEMENTS)

        cols = 3
        card_w, card_h = 400, 134
        gap_x, gap_y = 18, 16
        start_x = (VIRTUAL_W - (cols * card_w + (cols - 1) * gap_x)) / 2
        list_top, list_bottom = 158, VIRTUAL_H - 70
        list_h = list_bottom - list_top

        rows = math.ceil(len(items) / cols) if items else 1
        content_h = rows * card_h + max(0, rows - 1) * gap_y
        max_scroll = max(0, content_h - list_h)

        list_rect = pygame.Rect(0, list_top, VIRTUAL_W, list_h)
        if max_scroll > 0 and list_rect.collidepoint(mouse_pos) and not self.ach_detail:
            self.ach_scroll -= wheel_y * 46
        self.ach_scroll = clamp(self.ach_scroll, 0, max_scroll)

        list_click = clicked and not self.ach_detail
        opened_now = False
        pulse = 0.5 + 0.5 * math.sin(self.t * 3.0)

        prev_clip = canvas.get_clip()
        canvas.set_clip(list_rect)
        for i, a in enumerate(items):
            col_i, row = i % cols, i // cols
            y = list_top + row * (card_h + gap_y) - self.ach_scroll
            if y + card_h < list_top or y > list_bottom:
                continue
            rect = pygame.Rect(int(start_x + col_i * (card_w + gap_x)), int(y), card_w, card_h)
            got = a["id"] in unlocked
            cur, need, done = ach_progress(self.save, a)
            tcol = ach_tier_color(a)
            hover = (rect.collidepoint(mouse_pos) and list_rect.collidepoint(mouse_pos)
                     and not self.ach_detail)
            if hover:
                rect = rect.move(0, -3)

            edge = tcol if got else (91, 69, 71)
            if hover:
                add_glow(canvas, rect.centerx, rect.centery, 180, edge, 0.11)
            elif got:
                add_glow(canvas, rect.x + 48, rect.y + 56, 120, tcol, 0.06)
            if MOBILE:
                # telefon: kartın tamamı (gölge, gövde, yazılar, ilerleme
                # çubuğu) bir kez görüntüye çizilir; her karede tek blit.
                ckey = (a["id"], got, hover, int(cur), int(need), unlocked.get(a["id"], ""), lang())
                cache = self.__dict__.setdefault("_ach_card_img", {})
                img = cache.get(ckey)
                if img is None:
                    if len(cache) > 240:
                        cache.clear()
                    img = pygame.Surface((rect.w + 28, rect.h + 30), pygame.SRCALPHA)
                    lr = pygame.Rect(8, 4, rect.w, rect.h)
                    global _GLOW_ON_ALPHA
                    _GLOW_ON_ALPHA = True
                    try:
                        self._ach_card_paint(img, lr, a, i, got, cur, need, tcol, hover, unlocked,
                                             0.5, img.get_rect(), edge, shine=False)
                    finally:
                        _GLOW_ON_ALPHA = False
                    img = mob_rle(img)
                    cache[ckey] = img
                canvas.blit(img, (rect.x - 8, rect.y - 4))
                if got:
                    self._ach_shine(canvas, rect, i, list_rect)
            else:
                self._ach_card_paint(canvas, rect, a, i, got, cur, need, tcol, hover, unlocked,
                                     pulse, list_rect, edge)

            if list_click and hover:
                self.ach_detail = a["id"]
                self.ach_detail_t = 0.0
                opened_now = True
                sfx("click", 0.5, 0.0)
        canvas.set_clip(prev_clip)

        if max_scroll > 0:
            draw_scrollbar(canvas, VIRTUAL_W - 16, list_top, list_h, content_h, self.ach_scroll)

        # ================= üst şerit =================
        top = pygame.Rect(0, 0, VIRTUAL_W, 96)
        s = pygame.Surface(top.size, pygame.SRCALPHA)
        pygame.draw.rect(s, (28, 20, 21, 235), top)
        canvas.blit(s, (0, 0))
        pygame.draw.line(canvas, (140, 110, 50), (0, 96), (VIRTUAL_W, 96), 2)
        self._trophy(canvas, 28, 36, 17, GOLD, self.t)
        draw_text(canvas, L("ui.achievements"), (52, 18), 26, GOLD, bold=True)
        draw_text(canvas, L("ui.ach_hint"),
                  (52, 50), 11, TEXT_DIM, shadow=False)
        draw_icon(canvas, 58, 74, "gem", GEM_COLOR, 6)
        draw_text(canvas, L("ui.ach_sum", fmt_num(earned_gems), fmt_num(left_gems)),
                  (70, 67), 11, GEM_COLOR, bold=True, shadow=False)

        pbw = 250
        pbx = VIRTUAL_W - pbw - 80   # yüzde yazısına yer
        all_done = got_n >= total_n
        draw_text(canvas, L("ui.ach_count", got_n, total_n), (pbx, 20), 12,
                  GOLD if all_done else TEXT, bold=True, shadow=False)
        draw_bar(canvas, pygame.Rect(pbx, 40, pbw, 10), got_n / max(1, total_n),
                 GOLD if all_done else (230, 180, 90), radius=5)
        draw_text(canvas, fmt_pct(got_n / max(1, total_n) * 100), (pbx + pbw + 8, 38), 11,
                  TEXT_DIM, bold=True, shadow=False)
        # kademe dağılımı
        lx = pbx
        for tkey in ACH_TIER_ORDER:
            tier = ACH_TIERS[tkey]
            tot = sum(1 for a in ACHIEVEMENTS if a.get("tier") == tkey)
            if not tot:
                continue
            g = sum(1 for a in ACHIEVEMENTS if a.get("tier") == tkey and a["id"] in unlocked)
            pygame.draw.circle(canvas, tier["color"], (int(lx + 5), 66), 5)
            draw_text(canvas, f"{g}/{tot}", (lx + 14, 59), 11, tier["color"], bold=True, shadow=False)
            lx += 62

        # ---- filtre sekmeleri ----
        near_n = 0
        for a in ACHIEVEMENTS:
            if a["id"] in unlocked:
                continue
            c, n2, _ = ach_progress(self.save, a)
            if n2 and c / n2 >= 0.4:
                near_n += 1
        tabs = [("all", L("ui.f_all", total_n)),
                ("got", L("ui.f_got", got_n)),
                ("locked", L("ui.f_locked", total_n - got_n)),
                ("near", L("ui.f_near", near_n))]
        tab_w, tab_h, tab_gap = 168, 34, 10
        tabs_x = (VIRTUAL_W - (tab_w * len(tabs) + tab_gap * (len(tabs) - 1))) / 2
        for i, (key, label) in enumerate(tabs):
            r = pygame.Rect(int(tabs_x + i * (tab_w + tab_gap)), 106, tab_w, tab_h)
            active = self.ach_filter == key
            hov = r.collidepoint(mouse_pos) and not self.ach_detail
            bg = (126, 96, 36) if active else ((55, 43, 44) if hov else (46, 33, 34))
            pygame.draw.rect(canvas, bg, r, border_radius=9)
            ink_frame(canvas, r, GOLD if active else PANEL_EDGE, 9, 2)
            draw_text(canvas, label, r.center, 14, TEXT if active else TEXT_DIM,
                      bold=True, center=True)
            if list_click and hov and not active:
                self.ach_filter = key
                self.ach_scroll = 0.0
                sfx("click", 0.5, 0.0)

        if not items:
            draw_text(canvas, L("ui.ach_none"), (VIRTUAL_W / 2, list_top + 70), 16,
                      TEXT_DIM, center=True)

        btn = Button((VIRTUAL_W / 2 - 135, VIRTUAL_H - 58, 270, 44), L("ui.back_menu"),
                     lambda: self.set_state(STATE_MENU), text_size=18)
        btn.update(mouse_pos, dt)
        btn.draw(canvas)
        if list_click:
            btn.click(mouse_pos)

        if self.ach_detail:
            self._draw_ach_detail(canvas, dt, mouse_pos, clicked and not opened_now)

    def _draw_ach_detail(self, canvas, dt, mouse_pos, clicked):
        """Bir başarıma tıklayınca açılan detay penceresi."""
        a = ACH_BY_ID.get(self.ach_detail)
        if not a:
            self.ach_detail = None
            return
        unlocked = self.save.data.get("achievements", {})
        got = a["id"] in unlocked
        cur, need, done = ach_progress(self.save, a)
        tcol = ach_tier_color(a)
        tier = ACH_TIERS.get(a.get("tier", "bronz"), ACH_TIERS["bronz"])

        self.ach_detail_t = min(1.0, self.ach_detail_t + dt / 0.18)
        k = ease_out_cubic(self.ach_detail_t)

        ov = pygame.Surface((VIRTUAL_W, VIRTUAL_H), pygame.SRCALPHA)
        pygame.draw.rect(ov, (5, 6, 12, int(214 * k)), ov.get_rect())
        canvas.blit(ov, (0, 0))

        PW, PH = 640, 442
        r = pygame.Rect(0, 0, int(PW * (0.7 + 0.3 * k)), int(PH * (0.7 + 0.3 * k)))
        r.center = (VIRTUAL_W // 2, VIRTUAL_H // 2 - 6)
        add_glow(canvas, r.centerx, r.centery, 380, tcol, 0.09)
        panel(canvas, r, bg=(24, 22, 16) if got else (37, 27, 28), alpha=252,
              radius=18, edge_w=3)
        if k < 0.6:
            return

        pulse = 0.5 + 0.5 * math.sin(self.t * 3.0)
        self._ach_medallion(canvas, r.centerx, r.y + 70, 36, a, got, pulse)

        draw_text(canvas, ach_name(a), (r.centerx, r.y + 132), 28, TEXT if got else (188, 192, 208),
                  bold=True, center=True)
        # kademe rozeti
        blab = L("ui.tier_badge", L("tier." + a.get("tier", "bronz")))
        bw = text_width(blab, 12, True) + 26
        br = pygame.Rect(0, 0, int(bw), 22)
        br.center = (r.centerx, r.y + 170)
        tag_chip(canvas, br, tcol, 11, tint=0.2)
        draw_text(canvas, blab, br.center, 12, tcol, bold=True,
                  center=True, shadow=False)

        y = r.y + 194
        for ln in wrap_text(ach_desc(a), 15, r.w - 90):
            draw_text(canvas, ln, (r.centerx, y), 15, TEXT, center=True, shadow=False)
            y += 21

        y += 10
        pygame.draw.line(canvas, PANEL_EDGE, (r.x + 40, y), (r.right - 40, y), 1)
        y += 14
        draw_text(canvas, L("ui.how_to_earn"), (r.centerx, y), 13, tcol, bold=True,
                  center=True, shadow=False)
        y += 22
        for ln in wrap_text(ach_how(a) or ach_desc(a), 12, r.w - 90)[:5]:
            draw_text(canvas, ln, (r.centerx, y), 12, (196, 200, 216), center=True, shadow=False)
            y += 17

        y += 12
        # ---- ilerleme ----
        if got:
            draw_text(canvas, L("ui.unlocked_on", unlocked.get(a["id"], "")), (r.centerx, y), 16,
                      GREEN, bold=True, center=True)
            y += 26
        elif need:
            frac = clamp(cur / max(1, need), 0.0, 1.0)
            pb = pygame.Rect(r.x + 60, int(y), r.w - 120, 14)
            draw_bar(canvas, pb, frac, tcol, radius=7)
            y += 20
            kalan = max(0, int(need) - int(cur))
            draw_text(canvas,
                      L("ui.prog_left", fmt_num(int(cur)), fmt_num(int(need)), fmt_num(kalan), fmt_pct(frac * 100)),
                      (r.centerx, y), 13, TEXT_DIM, center=True, shadow=False)
            y += 24
        else:
            draw_text(canvas, L("ui.locked"), (r.centerx, y), 16, (190, 140, 70), bold=True,
                      center=True)
            y += 22
            draw_text(canvas, L("ui.ach_nocount"),
                      (r.centerx, y), 11, TEXT_DIM, center=True, shadow=False)
            y += 22

        # ---- ödül ----
        gems = int(a.get("gems", 0) or 0)
        if gems:
            rw = pygame.Rect(0, 0, 250, 34)
            rw.center = (r.centerx, int(y + 14))
            pygame.draw.rect(canvas, (57, 41, 43), rw, border_radius=10)
            ink_frame(canvas, rw, GEM_COLOR if not got else (80, 140, 110), 10, 2)
            draw_icon(canvas, rw.x + 24, rw.centery, "gem",
                      GEM_COLOR if not got else (110, 170, 140), 8)
            draw_text(canvas, (L("ui.ach_got") if got else L("ui.reward")) + L("ui.gems_cap", gems),
                      (rw.centerx + 12, rw.centery), 14,
                      GEM_COLOR if not got else (110, 170, 140), bold=True, center=True,
                      shadow=False)

        # ---- kapat ----
        cb = pygame.Rect(0, 0, 190, 40)
        cb.center = (r.centerx, r.bottom + 32)
        hov = cb.collidepoint(mouse_pos)
        pygame.draw.rect(canvas, (60, 56, 44) if hov else (55, 43, 44), cb, border_radius=10)
        ink_frame(canvas, cb, tcol if hov else PANEL_EDGE, 10, 2)
        draw_text(canvas, L("ui.close"), cb.center, 15, TEXT if hov else TEXT_DIM, bold=True,
                  center=True)
        if clicked and (hov or not r.collidepoint(mouse_pos)):
            self.ach_detail = None
            sfx("click", 0.5, 0.0)

    # ---- yerel skor tablosu ----
    def update_leaderboard(self, dt, mouse_pos, clicked):
        """Yerel skor tablosu (yeniden): kupa salonu arka planı, solda kişisel rekorlar"""
        canvas = self.display.canvas
        t = self.t
        self.local_lb_t = min(3.0, getattr(self, "local_lb_t", 0.0) + dt)
        self._local_lb_bg(canvas, t)
        board = list(self.save.data.get("leaderboard", []))[:10]
        st = self.save.data.get("stats") or {}
        P = pygame.Rect(36, 26, VIRTUAL_W - 72, VIRTUAL_H - 52)
        add_glow(canvas, P.centerx, P.y + 40, 520, (255, 170, 80), 0.10)
        panel(canvas, P, bg=(22, 16, 20), edge=(176, 120, 64), alpha=238, radius=20, edge_w=2)
        # başlık şeridi
        head = pygame.Rect(P.x + 3, P.y + 3, P.w - 6, 74)
        head_band(canvas, head, (58, 38, 26, 210), (110, 76, 46), radius=14)
        self._draw_trophy(canvas, P.centerx - 220, P.y + 40, 0.62, (255, 205, 90), t)
        self._draw_trophy(canvas, P.centerx + 220, P.y + 40, 0.62, (255, 205, 90), t + 1.3)
        draw_text(canvas, L("ui.local_board"), (P.centerx, P.y + 22), 30, (255, 214, 140), bold=True, center=True)
        draw_text(canvas, L("ui.local_sub"), (P.centerx, P.y + 54), 12, (214, 182, 140), center=True, shadow=False)

        # ---- sol: kişisel rekorlar ----
        L_ = pygame.Rect(P.x + 22, P.y + 94, 268, P.h - 172)
        panel(canvas, L_, bg=(30, 22, 24), edge=(120, 84, 52), alpha=230, radius=14, edge_w=1)
        draw_text(canvas, L("ui.local_records"), (L_.centerx, L_.y + 14), 14, (255, 206, 130), bold=True,
                  center=True, shadow=False)
        try:
            draw_skin_preview(canvas, get_skin(self.save.equipped_skin_id()), L_.centerx, L_.y + 72, t, r=26)
        except Exception:
            pass
        _tt = float(st.get("total_time", 0) or 0)
        _tt_txt = (L("ui.local_hours", int(_tt // 3600), int(_tt % 3600 // 60)) if _tt >= 3600 else fmt_time(_tt))
        tiles = [("star", GOLD, L("ui.local_best"), fmt_num(int(st.get("best_score", 0) or 0))),
                 ("target", CYAN, L("ui.local_best_wave"), str(int(st.get("best_wave", 0) or 0))),
                 ("skull", (255, 140, 130), L("ui.local_total_kills"), fmt_num(int(st.get("total_kills", 0) or 0))),
                 ("orbit", (190, 200, 255), L("ui.local_runs"), fmt_num(int(st.get("runs", 0) or 0))),
                 ("dash", (160, 230, 170), L("ui.local_total_time"), _tt_txt)]
        ty = L_.y + 120
        th = (L_.bottom - 12 - ty) / len(tiles)
        for k, (ic, col, lab, val) in enumerate(tiles):
            ap = ease_out_cubic(clamp((self.local_lb_t - 0.05 * k) / 0.35, 0, 1))
            tr = pygame.Rect(L_.x + 12 + int((1 - ap) * -30), int(ty + k * th), L_.w - 24, int(th) - 8)
            pygame.draw.rect(canvas, (40, 30, 30), tr, border_radius=10)
            ink_frame(canvas, tr, (78, 60, 60), 10, 1)
            draw_icon(canvas, tr.x + 24, tr.centery, ic, col, 11)
            draw_text(canvas, _fit_text(lab, 11, tr.w - 60), (tr.x + 46, tr.y + 8), 11, (200, 180, 160), shadow=False)
            draw_text(canvas, val, (tr.x + 46, tr.y + 24), 19, col, bold=True, shadow=False)

        # ---- sağ: kupa kartları + liste ----
        RX = L_.right + 18
        RW = P.right - 22 - RX
        best = max([1] + [int(e.get("score", 0) or 0) for e in board])
        if not board:
            cy_ = P.y + P.h / 2 - 30
            self._draw_trophy(canvas, RX + RW / 2, cy_ - 30, 1.4, (150, 120, 90), t)
            draw_text(canvas, L("ui.no_score"), (RX + RW / 2, cy_ + 56), 20, (226, 200, 170), bold=True, center=True)
        cw = (RW - 24) / 3
        cards_y = P.y + 94
        ch = 170
        for idx in range(3 if board else 0):   # tablo boşsa sadece "henüz skor yok" görünsün
            ap = ease_out_cubic(clamp((self.local_lb_t - 0.1 - idx * 0.08) / 0.4, 0, 1))
            if ap <= 0.02:
                continue
            cr = pygame.Rect(int(RX + idx * (cw + 12)), int(cards_y + (1 - ap) * 24), int(cw), ch)
            col, _sh = self._rank_style(idx)
            if idx >= len(board):
                pygame.draw.rect(canvas, (34, 26, 28), cr, border_radius=14)
                ink_frame(canvas, cr, (84, 66, 58), 14, 1)
                self._draw_trophy(canvas, cr.centerx, cr.y + 58, 0.9, scale_col(col, 0.45), t)
                draw_text(canvas, L("ui.row_empty"), (cr.centerx, cr.bottom - 34), 12, (130, 112, 100),
                          center=True, shadow=False)
                continue
            e = board[idx]
            body = pygame.Surface(cr.size, pygame.SRCALPHA)
            for yy in range(cr.h):
                f = yy / (cr.h - 1)
                c0 = scale_col(col, 0.34 - 0.18 * f)
                pygame.draw.line(body, (*c0, 236), (0, yy), (cr.w, yy))
            bm = pygame.Surface(cr.size, pygame.SRCALPHA)
            pygame.draw.rect(bm, (255, 255, 255, 255), bm.get_rect(), border_radius=14)
            body.blit(bm, (0, 0), special_flags=pygame.BLEND_RGBA_MIN)
            canvas.blit(body, cr.topleft)
            ink_frame(canvas, cr, col, 14, 2)
            add_glow(canvas, cr.x + 52, cr.y + 60, 60, col, 0.18 + 0.06 * math.sin(t * 2 + idx))
            self._draw_trophy(canvas, cr.x + 52, cr.y + 62, 1.0 - 0.1 * idx, col, t + idx)
            try:
                draw_skin_preview(canvas, get_skin(str(e.get("skin") or "default")), cr.right - 40, cr.y + 40,
                                  t + idx, r=17, weapon=False)
            except Exception:
                pass
            draw_text(canvas, "#%d" % (idx + 1), (cr.x + 98, cr.y + 14), 14, col, bold=True, shadow=False)
            draw_text(canvas, _fit_text(str(e.get("name", "?")), 18, cr.w - 160), (cr.x + 98, cr.y + 32), 18, TEXT,
                      bold=True)
            draw_coin_label(canvas, cr.x + 98 + 70, cr.y + 76, fmt_num(e.get("score", 0)), lighten(col, 0.2), 22,
                            icon="star", icon_r=9, gap=6)
            info = "%s, %s, %s" % (L("ui.lb_wave_n", e.get("wave", "-")), L("ui.n_kills", fmt_num(e.get("kills", 0))),
                                        fmt_time(float(e.get("time", 0) or 0)))
            draw_text(canvas, _fit_text(info, 12, cr.w - 24), (cr.x + 14, cr.y + 112), 12, (226, 214, 200), shadow=False)
            mk = e.get("map")
            sub = []
            if mk:
                sub.append(L("ui.hell") if mk == "hell" else LX("map.%s.name" % mk, mk))
            sub.append(str(e.get("date", "")))
            draw_text(canvas, _fit_text("  -  ".join(x for x in sub if x), 11, cr.w - 90), (cr.x + 14, cr.y + 136),
                      11, (180, 162, 146), shadow=False)
            _lb_diff_badge(canvas, cr.right - 44, cr.y + 136, e.get("diff"))
        # 4-10
        list_top = cards_y + ch + 14
        list_bottom = P.bottom - 70
        n_slots = 7
        row_h = (list_bottom - list_top) / n_slots
        for j in range(n_slots if board else 0):
            i = j + 3
            ap = ease_out_cubic(clamp((self.local_lb_t - 0.35 - j * 0.05) / 0.3, 0, 1))
            if ap <= 0.02:
                continue
            row = pygame.Rect(int(RX + (1 - ap) * 40), int(list_top + j * row_h), RW, int(row_h) - 5)
            if i >= len(board):
                pygame.draw.rect(canvas, (30, 24, 26), row, border_radius=9)
                ink_frame(canvas, row, (70, 56, 52), 9, 1)
                draw_text(canvas, str(i + 1), (row.x + 22, row.centery), 14, (110, 94, 86), bold=True, center=True,
                          shadow=False)
                draw_text(canvas, L("ui.row_empty"), (row.centerx, row.centery), 12, (112, 96, 88), center=True,
                          shadow=False)
                continue
            e = board[i]
            pygame.draw.rect(canvas, (40, 30, 30) if j % 2 == 0 else (34, 26, 27), row, border_radius=9)
            frac = clamp(int(e.get("score", 0) or 0) / best, 0, 1)
            bar = pygame.Rect(row.x + 2, row.bottom - 6, int((row.w - 4) * frac), 4)
            if bar.w > 2:
                pygame.draw.rect(canvas, (220, 150, 70), bar, border_radius=2)
            ink_frame(canvas, row, (96, 72, 56), 9, 1)
            badge = pygame.Rect(row.x + 7, row.y + 5, 30, row.h - 12)
            pygame.draw.rect(canvas, (20, 14, 16), badge, border_radius=7)
            draw_text(canvas, str(i + 1), badge.center, 14, (226, 196, 160), bold=True, center=True, shadow=False)
            try:
                draw_skin_preview(canvas, get_skin(str(e.get("skin") or "default")), row.x + 62, row.centery - 1,
                                  t + i, r=10, weapon=False)
            except Exception:
                pass
            draw_text(canvas, _fit_text(str(e.get("name", "?")), 15, 160), (row.x + 98, row.centery - 9), 15, TEXT,
                      shadow=False)
            draw_coin_label(canvas, row.x + 330, row.centery - 1, fmt_num(e.get("score", 0)), GOLD, 15, icon="star",
                            icon_r=7, gap=5, shadow=False)
            draw_text(canvas, L("ui.lb_wave_n", e.get("wave", "-")), (row.x + 430, row.centery - 8), 13,
                      (150, 200, 235), shadow=False)
            draw_text(canvas, L("ui.n_kills", fmt_num(e.get("kills", 0))), (row.x + 530, row.centery - 8), 13,
                      (230, 170, 160), shadow=False)
            draw_text(canvas, fmt_time(float(e.get("time", 0) or 0)), (row.x + 660, row.centery - 8), 13,
                      (200, 200, 220), shadow=False)
            _lb_diff_badge(canvas, row.right - 120, row.centery - 7, e.get("diff"))
            draw_text(canvas, str(e.get("date", "")), (row.right - 14, row.centery - 8), 12, (170, 150, 136),
                      right=True, shadow=False)

        w, h = 260, 44
        b1 = Button((P.centerx - w - 8, P.bottom - 58, w, h), L("ui.world_lb"), lambda: self.goto(STATE_WORLD_LB),
                    color=(70, 76, 140), hover_color=(96, 104, 186), text_size=19)
        b2 = Button((P.centerx + 8, P.bottom - 58, w, h), L("ui.back"), lambda: self.set_state(STATE_MENU),
                    text_size=19)
        for b in (b1, b2):
            b.update(mouse_pos, dt)
            b.draw(canvas)
            if clicked:
                b.click(mouse_pos)

    def _draw_trophy(self, canvas, cx, cy, s, col, t):
        """Kupa çizimi (yerel skor tablosu): kâse, kulplar, gövde, kaide, parlama."""
        dark = scale_col(col, 0.55)
        lite = lighten(col, 0.45)
        w = 26 * s
        bowl = [(cx - w, cy - 22 * s), (cx + w, cy - 22 * s), (cx + w * 0.82, cy + 2 * s),
                (cx + w * 0.40, cy + 14 * s), (cx - w * 0.40, cy + 14 * s), (cx - w * 0.82, cy + 2 * s)]
        for sgn in (-1, 1):
            hr = pygame.Rect(0, 0, int(22 * s), int(24 * s))
            hr.center = (int(cx + sgn * (w + 4 * s)), int(cy - 10 * s))
            try:
                pygame.draw.ellipse(canvas, dark, hr, max(2, int(4 * s)))
            except Exception:
                pass
        poly_aa(canvas, [(x, y + 2) for x, y in bowl], OUTLINE)
        poly_aa(canvas, bowl, col)
        poly_aa(canvas, poly_inset(bowl, 0.6, dx=-6 * s, dy=-4 * s), lite)
        stem = pygame.Rect(int(cx - 5 * s), int(cy + 13 * s), int(10 * s), int(12 * s))
        pygame.draw.rect(canvas, dark, stem)
        base = pygame.Rect(int(cx - 18 * s), int(cy + 24 * s), int(36 * s), int(9 * s))
        pygame.draw.rect(canvas, OUTLINE, base.move(0, 2), border_radius=max(2, int(3 * s)))
        pygame.draw.rect(canvas, col, base, border_radius=max(2, int(3 * s)))
        pygame.draw.line(canvas, lite, (base.x + 3, base.y + 2), (base.right - 3, base.y + 2), 1)
        sp = 0.5 + 0.5 * math.sin(t * 2.6)
        sx, sy = cx + w * 0.45, cy - 16 * s
        add_glow(canvas, sx, sy, 10 * s, WHITE, 0.25 + 0.3 * sp)
        pygame.draw.line(canvas, WHITE, (sx - 4 * s * sp, sy), (sx + 4 * s * sp, sy), 1)
        pygame.draw.line(canvas, WHITE, (sx, sy - 4 * s * sp), (sx, sy + 4 * s * sp), 1)

    def _local_lb_bg(self, canvas, t):
        if MOBILE:
            # telefon: canlı arka plan saniyede ~8 kez çizilir (opak görüntü)
            c = self.__dict__.setdefault("_llb_bg", {})
            img = c.get("img")
            if img is None or img.get_size() != canvas.get_size() or abs(t - c.get("t", -9)) >= 0.12:
                if img is None or img.get_size() != canvas.get_size():
                    img = pygame.Surface(canvas.get_size()).convert()
                self._local_lb_bg_draw(img, t)
                c.update(img=img, t=t)
            canvas.blit(img, (0, 0))
            return
        self._local_lb_bg_draw(canvas, t)

    def _local_lb_bg_draw(self, canvas, t):
        """kupa salonu arka planı: sıcak koyu degrade, iki yanda raflar ve üstlerinde sönük kupalar"""
        base = getattr(self, "_local_bg_base", None)
        if base is None:
            base = pygame.Surface((VIRTUAL_W, VIRTUAL_H)).convert()
            for yy in range(VIRTUAL_H):
                k = yy / (VIRTUAL_H - 1)
                pygame.draw.line(base, (int(lerp(46, 14, k)), int(lerp(26, 10, k)), int(lerp(24, 14, k))),
                                 (0, yy), (VIRTUAL_W, yy))
            # ahşap paneller
            for x in range(0, VIRTUAL_W, 96):
                pygame.draw.line(base, (34, 20, 18), (x, 0), (x, VIRTUAL_H), 2)
            for sy in (170, 340, 510):
                for x0, x1 in ((0, 150), (VIRTUAL_W - 150, VIRTUAL_W)):
                    pygame.draw.rect(base, (70, 44, 30), (x0, sy, x1 - x0, 12))
                    pygame.draw.rect(base, (98, 64, 40), (x0, sy, x1 - x0, 3))
            self._local_bg_base = base
            self._local_bg_trophies = True
        canvas.blit(base, (0, 0))
        for sy in (170, 340, 510):
            for k, xx in enumerate((40, 104, VIRTUAL_W - 104, VIRTUAL_W - 40)):
                col = ((150, 120, 70), (120, 124, 136), (130, 90, 60))[(k + sy // 170) % 3]
                self._draw_trophy(canvas, xx, sy - 26, 0.62, col, t + k + sy)
        for k, (x, y) in enumerate(((150, 120), (VIRTUAL_W - 150, 120), (150, 640), (VIRTUAL_W - 150, 640))):
            fl = 0.7 + 0.3 * math.sin(t * 9 + k * 2.1) * math.sin(t * 3.7 + k)
            add_glow(canvas, x, y, 120 * fl, (255, 160, 70), 0.20 * fl)
        for i in range(40):
            ph = (t * (0.04 + (i % 5) * 0.008) + i * 0.071) % 1.0
            x = (i * 131.7 + math.sin(t * 0.7 + i) * 20) % VIRTUAL_W
            y = VIRTUAL_H - ph * (VIRTUAL_H + 20)
            blit_disc(canvas, x, y, 1.0 + (i % 3) * 0.6, (255, 190, 110), int(170 * math.sin(ph * math.pi)))

    # ---- dünya sıralaması ----
    # sıralama yardımcıları.
    @staticmethod
    def _rank_style(i):
        """Sıraya göre (madalya rengi, parlaklık) döndürür."""
        if i == 0:
            return (255, 205, 80), 1.0
        if i == 1:
            return (206, 214, 232), 0.82
        if i == 2:
            return (214, 148, 88), 0.72
        return (96, 104, 130), 0.0

    def _draw_medal(self, canvas, cx, cy, i, r, t):
        """İlk üç için madalya, diğerleri için sade sıra rozeti."""
        col, shine = self._rank_style(i)
        if shine > 0:
            add_glow(canvas, cx, cy, r * 2.1, col, .30 * shine + .08 * math.sin(t * 3 + i))
        pygame.draw.circle(canvas, OUTLINE, (int(cx), int(cy)), int(r + 2))
        pygame.draw.circle(canvas, scale_col(col, 0.55), (int(cx), int(cy)), int(r))
        pygame.draw.circle(canvas, col, (int(cx), int(cy)), int(r), 2)
        if shine > 0:
            pygame.draw.circle(canvas, lighten(col, 0.55),
                               (int(cx - r * 0.3), int(cy - r * 0.3)), max(1, int(r * 0.24)))
        draw_text(canvas, str(i + 1), (cx, cy), int(r * 1.1),
                  (18, 18, 26) if shine > 0 else TEXT, bold=True, center=True, shadow=False)

    # ---- dünya sıralaması: yardımcı çizimler ----
    def _wlb_back(self, canvas, panel_rect, t):
        """Dünya sıralaması zemini: salon + hâle + panel + canlı katman. telefon: hepsi tek opak görüntüde"""
        if MOBILE:
            c = self.__dict__.setdefault("_wlb_bg", {})
            img = c.get("img")
            if img is None or img.get_size() != canvas.get_size() or abs(t - c.get("t", -9)) >= 0.12:
                if img is None or img.get_size() != canvas.get_size():
                    img = pygame.Surface(canvas.get_size()).convert()
                self._lb_hall_bg(img, t)
                self._wlb_back_layers(img, panel_rect, t)
                c.update(img=img, t=t)
            canvas.blit(img, (0, 0))
            return
        self._wlb_back_layers(canvas, panel_rect, t)

    def _wlb_back_layers(self, canvas, panel_rect, t):
        panel(canvas, panel_rect, alpha=246, edge=(150, 116, 74), edge_w=3, radius=18)
        self._lb_backdrop(canvas, panel_rect, t)
        ink_frame(canvas, panel_rect, (150, 116, 74), 14, 2)

    def _lb_backdrop(self, canvas, rect, t):
        """Tablonun arkasındaki canlı katman: yükselen ışık zerreleri ve panelin üstünde yavaşça kayan bir kuzey ışığı şeridi."""
        glow = pygame.Surface(rect.size, pygame.SRCALPHA)
        for i in range(3):
            ph = (t * 0.10 + i * 0.37) % 1.0
            cx = rect.w * ph
            add_glow(glow, cx, rect.h * (0.22 + 0.10 * math.sin(t * 0.6 + i)),
                     260, (190, 120, 60), 0.10)
        for i in range(34):
            k = (t * 0.16 + i * 0.0294) % 1.0
            px = (i * 137 + math.sin(t * 0.5 + i) * 26) % rect.w
            py = rect.h - k * (rect.h + 40)
            blit_disc(glow, px, py, 1.2 + 1.8 * (1 - k), (255, 214, 150),
                      int(80 * (1 - k)))
        hand_mask(glow, 14)
        canvas.blit(glow, rect.topleft)

    def _lb_crown(self, canvas, cx, cy, k, col, t):
        """Birincinin başındaki taç."""
        w, h = 15 * k, 11 * k
        pts = [(cx - w, cy + h), (cx - w, cy - h * 0.3),
               (cx - w * 0.5, cy + h * 0.25), (cx, cy - h),
               (cx + w * 0.5, cy + h * 0.25), (cx + w, cy - h * 0.3),
               (cx + w, cy + h)]
        poly_aa(canvas, pts, col)
        poly_edge(canvas, pts, scale_col(col, 0.5), 1)
        for sx in (-w * 0.62, 0, w * 0.62):
            twinkle = 0.5 + 0.5 * math.sin(t * 4 + sx)
            circle_aa(canvas, cx + sx, cy + h * 0.55, 1.8 * k,
                      lighten(col, 0.3 + 0.4 * twinkle))

    def _lb_row(self, canvas, row, i, e, my_name, t, appear, frac=0.0):
        """4. sıradan itibaren tek bir satır kartı."""
        nm = str(e.get("name", "?"))[:16]
        is_me = bool(my_name) and nm.strip().lower() == my_name
        # Görünme animasyonu: satırlar sırayla sağdan kayarak gelir.
        slide = int((1.0 - appear) * 46)
        row = row.move(slide, 0)
        alpha = int(255 * appear)
        if alpha <= 4:
            return
        body = pygame.Surface(row.size, pygame.SRCALPHA)
        if is_me:
            fill_c, edge = (30, 66, 48), (66, 108, 82)
        else:
            fill_c = (24, 28, 45) if i % 2 == 0 else (20, 24, 39)
            edge = (58, 76, 118)
        pygame.draw.rect(body, (*fill_c, 232), body.get_rect(), border_radius=10)
        # skor oranı: zeminin soldan dolan payı (düz, hafif açık bir şerit)
        fw = int((row.w - 4) * clamp(frac, 0.0, 1.0))
        if fw > 3:
            pygame.draw.rect(body, (*mix_col(fill_c, (120, 160, 230), 0.16), 232),
                             (2, 2, fw, row.h - 4), border_radius=8)
        body.set_alpha(alpha)
        canvas.blit(body, row.topleft)
        ink_frame(canvas, row, edge, 10, 2 if is_me else 1)

        # sıra numarası: solda küçük bir plaket
        badge = pygame.Rect(row.x + 7, row.y + 5, 30, row.h - 10)
        pygame.draw.rect(canvas, (30, 22, 23), badge, border_radius=8)
        ink_frame(canvas, badge, edge if is_me else (72, 84, 124), 8, 1)
        draw_text(canvas, str(i + 1), badge.center, 15,
                  GREEN if is_me else (176, 190, 226), bold=True, center=True,
                  shadow=False)

        # oyuncunun o skoru yaptığı skin
        try:
            draw_skin_preview(canvas, get_skin(str(e.get("skin") or "default")),
                              row.x + 64, row.centery, t + i, r=11, weapon=False)
        except Exception:
            pass
        draw_text(canvas, nm, (row.x + 92, row.centery - 9), 16,
                  GREEN if is_me else TEXT, bold=is_me, shadow=False)
        if is_me:
            draw_text(canvas, L("ui.you"), (row.x + 96 + text_width(nm, 16, True),
                                      row.centery - 6), 10, GREEN, bold=True,
                      shadow=False)
        self._lb_hits.append((row, e, i))
        draw_coin_label(canvas, row.x + 350, row.centery, fmt_num(e.get("score", 0)),
                        GOLD if not is_me else (190, 245, 190), 16, icon="star",
                        icon_r=7, gap=5, shadow=False)
        draw_text(canvas, L("ui.lb_wave_n", e.get("wave", "-")),
                  (row.x + 470, row.centery - 8), 13, (150, 190, 235), shadow=False)
        _lb_diff_badge(canvas, row.x + 592, row.centery - 7, e.get("diff"))
        draw_text(canvas, L("ui.n_kills", fmt_num(e.get("kills", 0))),
                  (row.right - 14, row.centery - 8), 13, TEXT_DIM, right=True,
                  shadow=False)

    def _lb_empty_row(self, canvas, row, i, t, appear):
        """Henüz sahibi olmayan sıra: kesik çizgili, davet eden bir yuva."""
        if appear <= 0.02:
            return
        row = row.move(int((1.0 - appear) * 46), 0)
        breathe = 0.5 + 0.5 * math.sin(t * 1.5 + i * 0.6)
        col = tuple(int(lerp(40, 66, breathe)) for _ in range(3))
        # kesik çizgili çerçeve
        seg, gap_l = 9, 6
        for (ax, ay, bx, by) in ((row.x, row.y, row.right, row.y),
                                 (row.x, row.bottom, row.right, row.bottom),
                                 (row.x, row.y, row.x, row.bottom),
                                 (row.right, row.y, row.right, row.bottom)):
            ln = math.hypot(bx - ax, by - ay)
            if ln < 1:
                continue
            ux, uy = (bx - ax) / ln, (by - ay) / ln
            d = 0.0
            while d < ln:
                d2 = min(ln, d + seg)
                pygame.draw.line(canvas, col, (ax + ux * d, ay + uy * d),
                                 (ax + ux * d2, ay + uy * d2), 1)
                d += seg + gap_l
        draw_text(canvas, str(i + 1), (row.x + 22, row.centery), 15,
                  tuple(int(lerp(72, 104, breathe)) for _ in range(3)),
                  bold=True, center=True, shadow=False)
        draw_text(canvas, L("ui.row_empty"),
                  (row.centerx, row.centery), 12,
                  tuple(int(lerp(78, 112, breathe)) for _ in range(3)),
                  center=True, shadow=False)

    def update_world_leaderboard(self, dt, mouse_pos, clicked):
        canvas = self.display.canvas
        t = self.t
        if not MOBILE:
            self._lb_hall_bg(canvas, t)
        self._lb_hits = []
        # ayrıntı penceresi açıkken alttaki ekran tıklama almaz
        detail = getattr(self, "_lb_detail", None)
        under_click = clicked and detail is None
        # "SEN" rozetinin eşleştiği ad: girişliyse hesabın adı, değilse
        # oyuncunun kendi yazdığı ad.
        my_name = (self.account.display_name()
                   if self.account.logged_in() else "")
        my_name = my_name.strip().lower()
        # Ekrana her girişte liste sırayla belirsin diye küçük bir sayaç.
        self.world_lb_t = min(3.0, getattr(self, "world_lb_t", 0.0) + dt)

        panel_rect = pygame.Rect(0, 0, 780, 618)
        panel_rect.center = (VIRTUAL_W / 2, VIRTUAL_H / 2)
        self._wlb_back(canvas, panel_rect, t)

        # ---- başlık şeridi ----
        head = pygame.Rect(panel_rect.x + 3, panel_rect.y + 3, panel_rect.w - 6, 78)
        head_band(canvas, head, (60, 40, 28, 200), (130, 92, 52), radius=14)
        title = L("ui.world_lb")
        if PLATFORM_TAG == "mobile":
            title += "  -  " + _tc("MOBİL", "MOBILE", "MÓVIL", "MOBIL", "МОБАЙЛ")
        ty_ = panel_rect.y + 30
        draw_text(canvas, title, (panel_rect.centerx, ty_), 31,
                  (255, 214, 140), bold=True, center=True)
        # başlığın iki yanında yıldız (başlıkla aynı hizada)
        sx_off = text_width(title, 31, True) // 2 + 26
        for sgn in (-1, 1):
            draw_icon(canvas, panel_rect.centerx + sgn * sx_off, ty_, "star", (255, 222, 140),
                      12 + 1.2 * math.sin(t * 2.4 + sgn))
        draw_text(canvas, L("ui.lb_sub", WORLD_LB_SIZE),
                  (panel_rect.centerx, panel_rect.y + 60), 12, TEXT_DIM,
                  center=True, shadow=False)

        body_top = panel_rect.y + 96

        # ---- kalıcı sıralama yasağı ----
        # Hileci bu ekranı açtığında kendi adını aramakla uğraşmasın: neden
        # orada olmadığı en üstte, kırmızı kırmızı yazıyor.
        if self.save.is_board_banned():
            bb = pygame.Rect(panel_rect.x + 24, body_top, panel_rect.w - 48, 86)
            panel(canvas, bb, bg=(48, 18, 22), edge=(200, 74, 84), alpha=244,
                  radius=10, edge_w=2)
            draw_text(canvas, L("ui.banned_title"), (bb.centerx, bb.y + 12), 17,
                      (255, 150, 150), bold=True, center=True, shadow=False)
            yy = bb.y + 36
            for ln in wrap_clip(L("ui.banned_body"), 11, bb.w - 36, 3):
                draw_text(canvas, ln, (bb.centerx, yy), 11, (226, 176, 176),
                          center=True, shadow=False)
                yy += 15
            body_top = bb.bottom + 10

        if self.online.loading:
            for k in range(10):
                a = t * 3.4 + k * math.tau / 10
                al = 0.15 + 0.85 * ((k / 10.0 + t * 0.6) % 1.0)
                blit_disc(canvas, panel_rect.centerx + math.cos(a) * 28,
                          panel_rect.centery - 20 + math.sin(a) * 28,
                          1.5 + 2.2 * al, (120, 180, 255), int(230 * al))
            draw_text(canvas, L("ui.lb_loading"), (panel_rect.centerx, panel_rect.centery + 22),
                      18, TEXT_DIM, center=True)

        elif self.online.world_error and not self.online.world_scores:
            draw_icon(canvas, panel_rect.centerx, panel_rect.centery - 56, "shield", (110, 118, 148), 26)
            # hata sebebiyle geliyor (uzun) - satırlara bölünür.
            wl = wrap_text(self.online.world_error, 15, panel_rect.w - 120)[:3]
            for i, ln in enumerate(wl):
                draw_text(canvas, ln, (panel_rect.centerx,
                                       panel_rect.centery - 16 + (i - (len(wl) - 1)) * 19),
                          15, TEXT, center=True)
            if not self.online.enabled:
                draw_text(canvas, L("ui.dev_note1"),
                          (panel_rect.centerx, panel_rect.centery + 14), 13, TEXT_DIM, center=True, shadow=False)
                draw_text(canvas, L("ui.dev_note2"),
                          (panel_rect.centerx, panel_rect.centery + 32), 13, TEXT_DIM, center=True, shadow=False)

        else:
            board = (self.online.world_scores or [])[:WORLD_LB_SIZE]
            if not board:
                draw_icon(canvas, panel_rect.centerx, panel_rect.centery - 40, "star", (110, 118, 148), 26)
                draw_text(canvas, L("ui.lb_none"),
                          (panel_rect.centerx, panel_rect.centery), 19, TEXT_DIM, center=True)
                draw_text(canvas, L("ui.lb_be_first"), (panel_rect.centerx, panel_rect.centery + 26),
                          14, TEXT_DIM, center=True, shadow=False)
            else:
                best = max(1, max(int(e.get("score", 0) or 0) for e in board))
                # ---- podyum (ilk üç) ----
                pod_h = 176
                pod = pygame.Rect(panel_rect.x + 30, body_top, panel_rect.w - 60, pod_h)
                order = [1, 0, 2]          # 2. - 1. - 3. sırayla yan yana
                slot_w = pod.w / 3
                # basamakların yükseklikleri: birinci en yüksekte durur
                step_h = {0: pod_h - 54, 1: pod_h - 74, 2: pod_h - 88}
                for slot, idx in enumerate(order):
                    col, shine = self._rank_style(idx)
                    ap = clamp((self.world_lb_t - idx * 0.10) / 0.35, 0.0, 1.0)
                    ap = ease_out_cubic(ap)
                    if ap <= 0.01:
                        continue
                    cx = pod.x + slot_w * slot + slot_w / 2
                    if idx >= len(board):
                        # Sahibi olmayan podyum basamağı: sönük, kesik çizgili
                        # bir kaide olarak yine de durur - podyumun bir ayağı
                        # eksik kalmasın.
                        bh = step_h[idx] * ap
                        st_r = pygame.Rect(int(cx - slot_w * 0.36),
                                           int(pod.bottom - bh),
                                           int(slot_w * 0.72), int(max(2, bh)))
                        dim = scale_col(col, 0.34)
                        for yy in range(0, st_r.h, 12):
                            pygame.draw.line(canvas, scale_col(col, 0.16),
                                             (st_r.x + 4, st_r.y + yy),
                                             (st_r.right - 4, st_r.y + yy), 1)
                        pygame.draw.rect(canvas, dim, st_r, width=1,
                                         border_top_left_radius=10,
                                         border_top_right_radius=10)
                        self._draw_medal(canvas, cx, st_r.y - 22, idx, 18, t)
                        draw_text(canvas, L("ui.empty"), (cx, st_r.y + 20), 15, dim,
                                  bold=True, center=True, shadow=False)
                        draw_text(canvas, L("ui.waiting_owner"), (cx, st_r.y + 42), 10,
                                  scale_col(col, 0.30), center=True, shadow=False)
                        continue
                    e = board[idx]
                    base_y = pod.bottom
                    bh = step_h[idx] * ap
                    step = pygame.Rect(int(cx - slot_w * 0.36), int(base_y - bh),
                                       int(slot_w * 0.72), int(max(2, bh)))
                    # basamak: üstü aydınlık, altı koyu bir blok
                    ss = pygame.Surface(step.size, pygame.SRCALPHA)
                    for yy in range(step.h):
                        f = yy / max(1, step.h - 1)
                        base = scale_col(col, 0.30 - 0.16 * f)
                        pygame.draw.line(ss, (*base, 238), (0, yy), (step.w, yy))
                    smask = pygame.Surface(step.size, pygame.SRCALPHA)
                    pygame.draw.rect(smask, (255, 255, 255, 255), smask.get_rect(),
                                     border_top_left_radius=10, border_top_right_radius=10)
                    ss.blit(smask, (0, 0), special_flags=pygame.BLEND_RGBA_MIN)
                    canvas.blit(ss, step.topleft)
                    pygame.draw.rect(canvas, col, step, width=2,
                                     border_top_left_radius=10, border_top_right_radius=10)
                    # basamağın üst kenarında parlayan bir şerit
                    pygame.draw.line(canvas, lighten(col, 0.45),
                                     (step.x + 6, step.y + 2), (step.right - 6, step.y + 2), 2)

                    nm = str(e.get("name", "?"))[:13]
                    is_me = bool(my_name) and nm.strip().lower() == my_name
                    bob = math.sin(t * 2 + idx) * 2.4
                    my = step.y - 22 + bob
                    if idx == 0:
                        # birinciye taç + sürekli yükselen kıvılcımlar
                        self._lb_crown(canvas, cx, my - 32, 1.0, (255, 226, 130), t)
                        for sp in range(5):
                            ph = (t * 0.55 + sp * 0.2) % 1.0
                            blit_disc(canvas, cx + math.sin(t * 1.6 + sp * 2) * 26,
                                      step.y - 6 - ph * 62, 2.2 * (1 - ph),
                                      (255, 224, 140), int(200 * (1 - ph)))
                    # skin avatarı (madalya yanında)
                    try:
                        draw_skin_preview(canvas, get_skin(str(e.get("skin") or "default")),
                                          cx, my - 4, t + idx, r=17, weapon=False)
                    except Exception:
                        pass
                    self._draw_medal(canvas, cx - 30, my + 8, idx, 11, t)
                    self._lb_hits.append((pygame.Rect(int(cx - slot_w * 0.40), int(my - 34),
                                                      int(slot_w * 0.80), int(pod.bottom - my + 34)), e, idx))
                    draw_text(canvas, nm, (cx, step.y + 20), 16,
                              GREEN if is_me else TEXT, bold=True, center=True)
                    draw_coin_label(canvas, cx, step.y + 44, fmt_num(e.get("score", 0)),
                                    col, 19, icon="star", icon_r=8, gap=5)
                    draw_text(canvas, L("ui.lb_wave_k", e.get("wave", "-"), fmt_num(e.get("kills", 0))),
                              (cx, step.y + 62), 10, (176, 190, 220), center=True, shadow=False)
                    _lb_diff_badge(canvas, cx, step.y + 76, e.get("diff"))
                    if is_me:
                        draw_text(canvas, L("ui.you"), (cx, step.y + 92), 11, GREEN,
                                  bold=True, center=True, shadow=False)
                pygame.draw.line(canvas, (58, 82, 128), (pod.x, pod.bottom),
                                 (pod.right, pod.bottom), 2)

                # ---- 4. sıradan itibaren liste ----
                # Liste her zaman 10 sıraya kadar çizilir: sahibi olmayan
                # sıralar boş bırakılmaz, "bu sıra seni bekliyor" diyen kesik
                # çizgili bir yuva olarak durur.
                rest = board[3:WORLD_LB_SIZE]
                n_slots = WORLD_LB_SIZE - 3
                list_top = pod.bottom + 12
                list_bottom = panel_rect.bottom - 70
                row_h = (list_bottom - list_top) / n_slots
                for j in range(n_slots):
                    i = j + 3
                    ap = ease_out_cubic(clamp((self.world_lb_t - 0.30 - j * 0.06) / 0.30,
                                              0.0, 1.0))
                    row = pygame.Rect(panel_rect.x + 34, int(list_top + j * row_h),
                                      panel_rect.w - 68, int(row_h) - 5)
                    if j < len(rest):
                        e = rest[j]
                        frac = clamp(int(e.get("score", 0) or 0) / best, 0.0, 1.0)
                        self._lb_row(canvas, row, i, e, my_name, t, ap, frac * ap)
                    else:
                        self._lb_empty_row(canvas, row, i, t, ap)

        # Girişsizken tek satırlık hatırlatma: adını hesapla sahiplenirsen
        # kimse o adla skor gönderemez (sunucu adı hesaptan alır).
        if self.account.enabled and not self.account.logged_in():
            draw_text(canvas, L("ui.acc_need"),
                      (panel_rect.centerx, panel_rect.bottom - 74), 11,
                      (140, 170, 206), center=True, shadow=False)

        w, h = 200, 44
        btn = Button((panel_rect.centerx - w - 8, panel_rect.bottom - 56, w, h), L("ui.refresh"),
                     self._world_lb_refresh)
        btn2 = Button((panel_rect.centerx + 8, panel_rect.bottom - 56, w, h), L("ui.back"),
                      lambda: self.set_state(STATE_MENU))
        for b in (btn, btn2):
            b.update(mouse_pos, dt)
            b.draw(canvas)
            if under_click:
                b.click(mouse_pos)
        # satır / podyum: üstüne gelince parlar, tıklayınca koşu kartı açılır
        if detail is None:
            for rr, e, idx in self._lb_hits:
                if rr.collidepoint(mouse_pos):
                    ink_frame(canvas, rr.inflate(4, 4), (150, 200, 255), 12, 2)
                    draw_text(canvas, L("ui.lb_click"), (rr.right - 8, rr.bottom - 13), 10,
                              (170, 200, 240), right=True, shadow=False)
                    if clicked:
                        self._lb_detail = (e, idx)
                        self._lb_detail_t = 0.0
                        sfx("click", 0.8, 0.0)
                    break
        else:
            self._lb_detail_t = getattr(self, "_lb_detail_t", 0.0) + dt
            if self._lb_draw_detail(canvas, detail[0], detail[1], mouse_pos, clicked, t):
                self._lb_detail = None

    def _lb_hall_bg(self, canvas, t):
        """Şampiyonlar salonu arka planı: derin lacivert-mor degrade, tepeden dönen ışık hüzmeleri"""
        base = getattr(self, "_lb_bg_base", None)
        if base is None:
            base = pygame.Surface((VIRTUAL_W, VIRTUAL_H)).convert()
            for yy in range(VIRTUAL_H):
                k = yy / (VIRTUAL_H - 1)
                pygame.draw.line(base, (int(lerp(26, 8, k)), int(lerp(20, 10, k)), int(lerp(58, 22, k))),
                                 (0, yy), (VIRTUAL_W, yy))
            # sütunlar
            for sx in (70, 190, VIRTUAL_W - 190, VIRTUAL_W - 70):
                col = pygame.Rect(sx - 26, 120, 52, VIRTUAL_H - 120)
                pygame.draw.rect(base, (34, 30, 64), col)
                pygame.draw.rect(base, (52, 46, 92), col.inflate(-30, 0))
                for k in range(5):
                    pygame.draw.line(base, (24, 22, 46), (col.x + 8 + k * 9, col.y), (col.x + 8 + k * 9, col.bottom), 2)
                pygame.draw.rect(base, (70, 60, 110), (sx - 34, 106, 68, 18), border_radius=4)
                pygame.draw.rect(base, (70, 60, 110), (sx - 34, VIRTUAL_H - 24, 68, 24), border_radius=4)
            # yer: parlak mermer şerit
            for yy in range(VIRTUAL_H - 60, VIRTUAL_H):
                k = (yy - (VIRTUAL_H - 60)) / 60.0
                pygame.draw.line(base, (int(40 - 20 * k), int(34 - 16 * k), int(80 - 40 * k)), (0, yy), (VIRTUAL_W, yy))
            self._lb_bg_base = base
        canvas.blit(base, (0, 0))
        # tepeden dönen ışık hüzmeleri
        rays = pygame.Surface((VIRTUAL_W, VIRTUAL_H), pygame.SRCALPHA)
        cx, cy = VIRTUAL_W / 2, -60
        for i in range(9):
            a = math.pi / 2 + math.sin(t * 0.25 + i * 0.9) * 0.55 + (i - 4) * 0.16
            ln = VIRTUAL_H * 1.3
            w = 0.035 + 0.015 * math.sin(t * 0.7 + i)
            pts = [(cx, cy), (cx + math.cos(a - w) * ln, cy + math.sin(a - w) * ln),
                   (cx + math.cos(a + w) * ln, cy + math.sin(a + w) * ln)]
            pygame.draw.polygon(rays, (255, 214, 140, 16 + int(8 * math.sin(t + i))), pts)
        canvas.blit(rays, (0, 0))
        add_glow(canvas, cx, 40, 420, (255, 200, 120), 0.12)
        # süzülen altın tozu
        for i in range(60):
            ph = (t * (0.03 + (i % 7) * 0.006) + i * 0.0617) % 1.0
            x = (i * 97.3 + math.sin(t * 0.6 + i) * 24) % VIRTUAL_W
            y = VIRTUAL_H - ph * (VIRTUAL_H + 30)
            blit_disc(canvas, x, y, 1.0 + (i % 3) * 0.7, (255, 220, 150), int(150 * math.sin(ph * math.pi)))

    def _lb_draw_detail(self, canvas, e, rank, mouse_pos, clicked, t):
        """Koşu kartı: sıralamadaki bir skora tıklayınca açılan ayrıntı."""
        k = ease_out_cubic(clamp(getattr(self, "_lb_detail_t", 0.0) / 0.25, 0.0, 1.0))
        dim = pygame.Surface((VIRTUAL_W, VIRTUAL_H), pygame.SRCALPHA)
        dim.fill((4, 5, 12, int(200 * k)))
        canvas.blit(dim, (0, 0))
        R = pygame.Rect(0, 0, 1060, 620)
        R.center = (VIRTUAL_W / 2, VIRTUAL_H / 2 + int((1 - k) * 40))
        col, shine = self._rank_style(rank)
        if rank > 2:
            col = (110, 160, 230)
        add_glow(canvas, R.centerx, R.y + 40, 420, col, 0.16)
        panel(canvas, R, bg=(32, 23, 24), edge=col, alpha=250, radius=18, edge_w=3)
        b = e.get("build") if isinstance(e.get("build"), dict) else None
        # ---- başlık ----
        self._draw_medal(canvas, R.x + 44, R.y + 42, rank, 20, t)
        nm = str(e.get("name", "?"))[:14]
        draw_text(canvas, nm, (R.x + 78, R.y + 18), 28, TEXT, bold=True)
        sub = []
        if b:
            sub.append(L("ui.hell") if b.get("hell") else L("map.%s.name" % b.get("map", "stone")))
        sub.append(LX("diff." + str(e.get("diff") or "normal"), str(e.get("diff") or "normal")))
        try:
            sub.append(time.strftime("%d.%m.%Y", time.localtime(float(e.get("created_at") or 0))))
        except Exception:
            pass
        draw_text(canvas, "  -  ".join(sub), (R.x + 80, R.y + 54), 13, (160, 170, 200), shadow=False)
        draw_coin_label(canvas, R.right - 150, R.y + 40, fmt_num(e.get("score", 0)), GOLD, 30,
                        icon="star", icon_r=12, gap=8)
        # kapat
        xb = pygame.Rect(R.right - 46, R.y + 12, 34, 34)
        hov = xb.collidepoint(mouse_pos)
        pygame.draw.rect(canvas, (60, 30, 40) if hov else (55, 40, 41), xb, border_radius=9)
        ink_frame(canvas, xb, (220, 120, 130) if hov else (110, 116, 150), 9, 2)
        pygame.draw.line(canvas, WHITE, (xb.x + 10, xb.y + 10), (xb.right - 10, xb.bottom - 10), 3)
        pygame.draw.line(canvas, WHITE, (xb.right - 10, xb.y + 10), (xb.x + 10, xb.bottom - 10), 3)
        pygame.draw.line(canvas, scale_col(col, 0.6), (R.x + 20, R.y + 80), (R.right - 20, R.y + 80), 1)
        if clicked and (hov or not R.collidepoint(mouse_pos)):
            sfx("click", 0.6, 0.0)
            return True
        # ---- sol: skin + temel sayılar ----
        L_ = pygame.Rect(R.x + 20, R.y + 94, 260, R.h - 114)
        panel(canvas, L_, bg=scale_col(col, 0.14), edge=scale_col(col, 0.6), alpha=240, radius=14, edge_w=1)
        sk = get_skin(str(e.get("skin") or (b or {}).get("skin") or "default"))
        add_glow(canvas, L_.centerx, L_.y + 92, 110, tuple(sk["color"]), 0.30 + 0.08 * math.sin(t * 2.4))
        ring_aa(canvas, L_.centerx, L_.y + 92, 58, scale_col(col, 0.9), 2)
        try:
            draw_skin_preview(canvas, sk, L_.centerx, L_.y + 92, t, r=38)
        except Exception:
            pass
        draw_text(canvas, skin_name(sk), (L_.centerx, L_.y + 162), 14, tuple(sk["color"]), bold=True,
                  center=True)
        st = (b or {}).get("st") or {}
        cells = [("target", CYAN, L("ui.go_wave"), str(e.get("wave", "-"))),
                 ("skull", (255, 140, 130), L("ui.go_kills"), fmt_num(e.get("kills", 0))),
                 ("orbit", (190, 200, 255), L("ui.go_time"), fmt_time(float(e.get("run_time") or 0))),
                 ("star", PURPLE, "LV", str(int(st.get("lvl", 0))) if st.get("lvl") else "-"),
                 ("shield", (255, 120, 90), L("ui.lb_bosses"),
                  str(int(st.get("bosses", 0))) if b else "-")]
        yy = L_.y + 186
        for ic, ccol, lab, val in cells:
            cr = pygame.Rect(L_.x + 14, yy, L_.w - 28, 46)
            panel(canvas, cr, bg=(39, 28, 29), alpha=240, radius=10, edge_w=1)
            draw_icon(canvas, cr.x + 20, cr.centery, ic, ccol, 8)
            draw_text(canvas, lab, (cr.x + 38, cr.centery - 8), 12, (160, 166, 196), bold=True, shadow=False)
            draw_text(canvas, val, (cr.right - 12, cr.centery - 11), 19, ccol, bold=True, right=True)
            yy += 52
        if not b:
            M = pygame.Rect(L_.right + 16, L_.y, R.right - 20 - L_.right - 16, L_.h)
            panel(canvas, M, bg=(39, 28, 29), edge=(70, 80, 120), alpha=240, radius=14, edge_w=1)
            for i, ln in enumerate(wrap_text(L("ui.lb_no_build"), 15, M.w - 80)[:3]):
                draw_text(canvas, ln, (M.centerx, M.centery - 20 + i * 22), 15, TEXT_DIM, center=True)
            return False
        # ---- orta: silahlar + kitaplar + hasar ----
        M = pygame.Rect(L_.right + 16, L_.y, 430, L_.h)
        panel(canvas, M, bg=(39, 28, 29), edge=(70, 80, 120), alpha=240, radius=14, edge_w=1)
        draw_text(canvas, L("ui.lb_weapons"), (M.x + 16, M.y + 10), 13, (238, 170, 120), bold=True, shadow=False)
        xx = M.x + 16
        for key, lv in (b.get("w") or [])[:6]:
            w = WEAPON_BY_KEY.get(key)
            if not w:
                continue
            c = tuple(w["color"])
            tr = pygame.Rect(xx, M.y + 30, 62, 62)
            panel(canvas, tr, bg=(28, 20, 21), edge=scale_col(c, 0.85), alpha=245, radius=11, edge_w=2)
            blit_sigil(canvas, tr.centerx, tr.centery - 7, 14, key, c)
            draw_text(canvas, "Lv.%d" % lv, (tr.centerx, tr.bottom - 15), 11, WHITE, bold=True, center=True)
            xx += 68
        draw_text(canvas, L("ui.lb_books"), (M.x + 16, M.y + 102), 13, (186, 150, 255), bold=True, shadow=False)
        xx = M.x + 16
        for key, lv in (b.get("b") or [])[:6]:
            bk = BOOK_BY_KEY.get(key)
            if not bk:
                continue
            c = tuple(bk["color"])
            tr = pygame.Rect(xx, M.y + 122, 62, 62)
            panel(canvas, tr, bg=(28, 20, 21), edge=scale_col(c, 0.85), alpha=245,
                  radius=16 if bk.get("rare") else 11, edge_w=2)
            draw_icon(canvas, tr.centerx, tr.centery - 5, bk.get("icon", "book"), c, 14)
            draw_text(canvas, "Lv.%d" % lv, (tr.centerx, tr.bottom - 15), 11, WHITE, bold=True, center=True)
            if tr.collidepoint(mouse_pos):
                tip = bk_name(bk)
                draw_text(canvas, tip, (tr.centerx, tr.y - 14), 11, c, bold=True, center=True)
            xx += 68
        draw_text(canvas, L("ui.dmg_title"), (M.x + 16, M.y + 196), 13, GOLD, bold=True, shadow=False)
        rows = b.get("d") or []
        total = max(1, sum(v for _k, v in rows))
        top = max(1, rows[0][1]) if rows else 1
        yy = M.y + 218
        for i, (key, v) in enumerate(rows[:8]):
            name, ic, c = dmg_src_label(key)
            c = tuple(int(x) for x in c[:3])
            tile = pygame.Rect(M.x + 14, yy, 30, 28)
            pygame.draw.rect(canvas, (28, 20, 21), tile, border_radius=7)
            ink_frame(canvas, tile, scale_col(c, 0.75), 7, 1)
            if key in WEAPON_BY_KEY:
                blit_sigil(canvas, tile.centerx, tile.centery, 10, key, c)
            else:
                draw_icon(canvas, tile.centerx, tile.centery, ic, c, 8)
            draw_text(canvas, _fit_text(name, 12, 170, bold=True), (tile.right + 8, yy), 12, c, bold=True, shadow=False)
            pct = v / total * 100
            draw_text(canvas, "%s  %s" % (fmt_num(v), ("%%%d" % round(pct)) if lang() == "tr" else "%d%%" % round(pct)),
                      (M.right - 14, yy), 11, TEXT, right=True, shadow=False)
            draw_bar(canvas, pygame.Rect(tile.right + 8, yy + 16, M.right - 14 - tile.right - 8, 7),
                     clamp(v / top, 0, 1), c, radius=3)
            yy += 34
        # ---- sağ: istatistikler ----
        S = pygame.Rect(M.right + 16, L_.y, R.right - 20 - M.right - 16, L_.h)
        panel(canvas, S, bg=(29, 21, 22), edge=(96, 106, 152), alpha=244, radius=14, edge_w=1)
        draw_text(canvas, L("ui.lb_stats"),
                  (S.centerx, S.y + 10), 14, (190, 200, 240), bold=True, center=True, shadow=False)
        yy = S.y + 34
        grp = None
        for key, lab, kind, c, g in BUILD_STAT_VIEW:
            if key not in st:
                continue
            if g != grp:
                grp = g
                draw_text(canvas, L(g), (S.x + 14, yy), 11, (120, 128, 160), bold=True, shadow=False)
                yy += 17
            draw_text(canvas, _fit_text(L(lab), 12, S.w - 110), (S.x + 18, yy), 12, (190, 196, 220), shadow=False)
            draw_text(canvas, build_stat_text(kind, st.get(key)), (S.right - 14, yy), 12, c, bold=True,
                      right=True, shadow=False)
            yy += 17
            if yy > S.bottom - 18:
                break
        return False

    def _world_lb_refresh(self):
        """yenile: listeyi yeniden çeker ve beliriş animasyonunu başa sarar."""
        self.world_lb_t = 0.0
        self.online.fetch_world_scores_async()

